// ===== mono-performance-boot =====

(function() {
  if (window.__monoPerfBooted) return;
  window.__monoPerfBooted = true;

  var docEl = document.documentElement;
  var ua = '';
  var hc = 0;
  var dm = 0;
  try { ua = navigator.userAgent || ''; } catch (e) {}
  try { hc = Number(navigator.hardwareConcurrency || 0) || 0; } catch (e) {}
  try { dm = Number(navigator.deviceMemory || 0) || 0; } catch (e) {}

  var isMobileLike = /iPhone|iPad|iPod|Android|Mobile|HarmonyOS/i.test(ua);
  var lowPower = !!((hc && hc <= 6) || (dm && dm <= 4) || isMobileLike);
  var perf = window.__monoPerf = {
    lowPower: lowPower,
    hiddenSkipFloorMs: lowPower ? 2600 : 1800,
    domVisibleFloorMs: lowPower ? 5200 : 3600,
    scopedVisibleFloorMs: lowPower ? 4200 : 3000,
    heavyVisibleFloorMs: lowPower ? 7000 : 4800,
    heavyHiddenFloorMs: lowPower ? 22000 : 15000,
    scopeIdleFloorMs: lowPower ? 9000 : 6000
  };

  if (docEl && docEl.classList) {
    docEl.classList.add('mono-light-preview', 'mono-performance-mode', 'mono-app-booting');
    if (lowPower) docEl.classList.add('mono-low-power-preview');
  }

  function getFnSource(fn) {
    try {
      return typeof fn === 'function' ? Function.prototype.toString.call(fn) : String(fn || '');
    } catch (e) {
      return '';
    }
  }

  function isHeavyPoller(source) {
    return /(injectCutout|injectOrRefreshCutout|enhancePosterName|patchZones|ensureSlotPrinter|patchPrintAction|moveToolbar|resetInitialPaperScroll|syncEmptyStage|addProviderNote|applyFullVinylMode|scheduleBbAutoScan|injectTicketMachineHomeIcon|placeTicketMachineIcon|normalizeAll|checkChatDom|mountEscapeTheaterIcon|buildVinyl|syncVinylSpin|normalizeIcon|hydrateMasksFromIdbAndCache|addRecordCoverButtons|ensureCoverInput|patchRender|restoreResizeHandles|ensureDialogTop|ensureManageClickable)/i.test(source);
  }

  function isScopedUiPoller(source) {
    return /(buildVinyl|syncVinylSpin|normalizeIcon|watch\(\)|applyFullVinylMode|ensureSlotPrinter|patchPrintAction|moveToolbar|resetInitialPaperScroll|syncEmptyStage|addProviderNote|addNote|hydrateMasksFromIdbAndCache|addRecordCoverButtons|ensureCoverInput|restoreResizeHandles|ensureDialogTop|ensureManageClickable|IDS\.forEach\(applyOne\)|monoSyncSpecialHomeIconsWithFolders)/i.test(source);
  }

  function isDomScanPoller(source) {
    return /(querySelector|querySelectorAll|getElementById|closest|classList|setAttribute|appendChild|removeChild|innerHTML|matches\(|document\.body|document\.documentElement)/.test(source);
  }

  function isRealtimeTimer(source) {
    return /(_hTimerSec|player\.time|progressTimer|lyricTimer|rpcUpdateVPhoneTime|updateSpyClock|updateHomeScreen|timerInterval|帖子Message\('tick'\)|帖子Message\("tick"\))/i.test(source);
  }

  function isElementVisible(el) {
    try {
      if (!el) return false;
      if (el.hidden) return false;
      if (el.classList && (el.classList.contains('hidden') || el.classList.contains('hide'))) return false;
      var cs = window.getComputedStyle ? getComputedStyle(el) : null;
      if (cs && (cs.display === 'none' || cs.visibility === 'hidden' || cs.pointerEvents === 'none' && cs.opacity === '0')) return false;
      if (el.offsetParent !== null) return true;
      var rect = el.getBoundingClientRect ? el.getBoundingClientRect() : null;
      return !!(rect && (rect.width > 0 || rect.height > 0));
    } catch (e) {
      return false;
    }
  }

  function isAnySelectorVisible(selectorText) {
    if (!selectorText) return true;
    try {
      return selectorText.split(',').some(function(part) {
        var sel = String(part || '').trim();
        if (!sel) return false;
        return isElementVisible(document.querySelector(sel));
      });
    } catch (e) {
      return true;
    }
  }

  function inferScopeSelector(source) {
    if (!source) return '';
    if (/(ticketMachinePage|tm-)/i.test(source)) return '#ticketMachinePage';
    if (/(aiMusicStudioPage|v38|v39|melody|vinyl)/i.test(source)) return '#aiMusicStudioPage';
    if (/(youtubePage|data-yt|yt-)/i.test(source)) return '#youtubePage';
    if (/(instagramPage|ins-)/i.test(source)) return '#instagramPage';
    if (/(chatPage|groupChatPage|datingChatPage|callPage|chatBox|headHeartVoice|plus-panel-btn|checkChatDom)/i.test(source)) {
      return '#chatPage,#groupChatPage,#datingChatPage,#callPage';
    }
    if (/(app-ai-music-studio|aiMusicStudioHomeIconBox|app-youtube|youtubeHomeIconBox|app-instagram|instagramHomeIconBox|app-ticket-machine|app-escape-theater|homePage3|homeScreen|mono_iph_|drag-id|iph-placed|home-entry|placeIcon|renderAiMusicStudioHomeIcon|monoSyncSpecialHomeIconsWithFolders|normalizeAll)/i.test(source)) {
      return '#homeScreen,#homePage1,#homePage2,#homePage3';
    }
    return '';
  }

  function tuneIntervalDelay(delay, source) {
    var base = Number(delay);
    if (/monoScanAndTriggerAvatar|runSingleAvatar|runPairAvatar|tryPersonaSendChatScreenshot|monoQueuePersonaImageGen|monoTriggerRoleAvatarChange/i.test(source || '')) return (!isFinite(base) || base < 0) ? 0 : base;
    if (!isFinite(base) || base < 0) base = 0;
    if (isHeavyPoller(source)) return Math.max(base, perf.heavyVisibleFloorMs);
    if (!isRealtimeTimer(source) && isScopedUiPoller(source) && base > 0 && base <= 1600) {
      return Math.max(base, perf.scopedVisibleFloorMs);
    }
    if (!isRealtimeTimer(source) && base > 0 && base <= 1500 && isDomScanPoller(source)) {
      return Math.max(base, perf.domVisibleFloorMs);
    }
    return base;
  }

  var nativeSetInterval = window.setInterval.bind(window);
  var nativeClearInterval = window.clearInterval.bind(window);
  var mutationBatchDelay = lowPower ? 180 : 90;
  var resizeBatchDelay = lowPower ? 140 : 70;
  window.setInterval = function(callback, delay) {
    var args = Array.prototype.slice.call(arguments, 2);
    var source = getFnSource(callback);
    var isRealtime = isRealtimeTimer(source);
    var isHeavy = isHeavyPoller(source);
    var scopeSelector = inferScopeSelector(source);
    var tunedDelay = tuneIntervalDelay(delay, source);
    return nativeSetInterval(function() {
      if (document.hidden && !isRealtime && tunedDelay <= perf.hiddenSkipFloorMs) return;
      if (document.hidden && isHeavy) return;
      if (!isRealtime && scopeSelector && !isAnySelectorVisible(scopeSelector)) return;
      if (typeof callback === 'function') return callback.apply(this, args);
      return window.eval(String(callback));
    }, document.hidden && isHeavy ? Math.max(tunedDelay, perf.heavyHiddenFloorMs) : tunedDelay);
  };
  window.clearInterval = function(id) {
    return nativeClearInterval(id);
  };

  var raf = window.requestAnimationFrame ? window.requestAnimationFrame.bind(window) : function(fn) { return setTimeout(fn, 16); };

  if (window.MutationObserver && !window.MutationObserver.__monoPerfWrapped) {
    var NativeMutationObserver = window.MutationObserver;
    var WrappedMutationObserver = function(callback) {
      var queued = false;
      var pending = [];
      return new NativeMutationObserver(function(records, observer) {
        if (records && records.length) pending = pending.concat(records);
        if (queued) return;
        queued = true;
        setTimeout(function() {
          queued = false;
          var batch = pending.slice();
          pending.length = 0;
          callback(batch, observer);
        }, mutationBatchDelay);
      });
    };
    WrappedMutationObserver.prototype = NativeMutationObserver.prototype;
    try { Object.setPrototypeOf(WrappedMutationObserver, NativeMutationObserver); } catch (e) {}
    WrappedMutationObserver.__monoPerfWrapped = true;
    window.MutationObserver = WrappedMutationObserver;
  }

  if (window.ResizeObserver && !window.ResizeObserver.__monoPerfWrapped) {
    var NativeResizeObserver = window.ResizeObserver;
    var WrappedResizeObserver = function(callback) {
      var queued = false;
      var latestEntries = null;
      var latestObserver = null;
      return new NativeResizeObserver(function(entries, observer) {
        latestEntries = entries;
        latestObserver = observer;
        if (queued) return;
        queued = true;
        setTimeout(function() {
          queued = false;
          callback(latestEntries || [], latestObserver);
        }, resizeBatchDelay);
      });
    };
    WrappedResizeObserver.prototype = NativeResizeObserver.prototype;
    try { Object.setPrototypeOf(WrappedResizeObserver, NativeResizeObserver); } catch (e) {}
    WrappedResizeObserver.__monoPerfWrapped = true;
    window.ResizeObserver = WrappedResizeObserver;
  }

  document.addEventListener('visibilitychange', function() {
    if (!docEl || !docEl.classList) return;
    if (document.hidden) docEl.classList.add('mono-page-hidden');
    else docEl.classList.remove('mono-page-hidden');
  }, { passive: true });
})();


