// ===== mono-boot-guard =====

(function(){
  var released = false;
  function appLooksReady(){
    try {
      var home = document.getElementById('homeScreen');
      if (home && home.offsetParent !== null) return true;
      var activePage = document.querySelector('.page.active');
      if (activePage && activePage.offsetParent !== null) return true;
    } catch(e) {}
    return false;
  }
  function releaseBootGuard(){
    if (released) return;
    released = true;
    try { document.documentElement.classList.remove('mono-app-booting'); } catch(e) {}
    try {
      var splash = document.getElementById('monoBootSplash');
      if (splash) splash.remove();
    } catch(e) {}
  }
  function tryReleaseBootGuard(){
    if (appLooksReady() || document.readyState === 'complete') releaseBootGuard();
  }
  window.__monoReleaseBootGuard = releaseBootGuard;
  document.addEventListener('DOMContentLoaded', function(){
    setTimeout(tryReleaseBootGuard, 120);
    setTimeout(tryReleaseBootGuard, 500);
    setTimeout(tryReleaseBootGuard, 1200);
    if (typeof window.afterDB === 'function') {
      try {
        window.afterDB(function(){
          requestAnimationFrame(function(){
            requestAnimationFrame(releaseBootGuard);
          });
        });
      } catch(e) {}
    }
  });
  window.addEventListener('load', function(){
    setTimeout(tryReleaseBootGuard, 120);
    setTimeout(releaseBootGuard, 1600);
  }, { passive: true });
  setTimeout(releaseBootGuard, 4000);
})();


