  const DB_VERSION = 2;          // v2: added novel_blobs store
  const STORE = 'kv';
  const BLOB_STORE = 'novel_blobs'; // large novel content & covers
  const MEMO_PREFIX = 'mono_';   // 只攔截 mono_ 开头的 key
