// ── 图片压缩工具 ──────────────────────────────────────────
function compressImage(base64, maxSize, quality) {
  maxSize = maxSize || 800; quality = quality || 0.72;
  return new Promise(function(resolve) {
    var img = new Image();
    img.onload = function() {
      var w = img.width, h = img.height;
      if (w > maxSize || h > maxSize) {
        if (w > h) { h = Math.round(h * maxSize / w); w = maxSize; }
        else       { w = Math.round(w * maxSize / h); h = maxSize; }
      }
      var canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      canvas.getContext('2d').drawImage(img, 0, 0, w, h);
      resolve(canvas.toDataURL('image/jpeg', quality));
    };
    img.onerror = function() { resolve(base64); };
    img.src = base64;
  });
}
async function safeSetItem(key, value) {
  // With IndexedDB backing there's no quota limit — just set directly
  localStorage.setItem(key, value);
}
// ─────────────────────────────────────────────────────────
function handleHome图片(input) {
  if (input.files && input.files[0]) {
    var reader = new FileReader();
    reader.onload = async function(e) {
      const compressed = await compressImage(e.target.result, 1200, 0.8);
      var img = document.getElementById('home图片Img');
      img.src = compressed;
      img.style.display = 'block';
      document.getElementById('home图片Placeholder').style.display = 'none';
      await safeSetItem('mono_home_photo', compressed);
    };
    reader.readAsDataURL(input.files[0]);
  }
}
function loadHome图片() {
  var saved = localStorage.getItem('mono_home_photo');
  if (saved) {
    var img = document.getElementById('home图片Img');
    img.src = saved;
    img.style.display = 'block';
    document.getElementById('home图片Placeholder').style.display = 'none';
  }
}
// Initialize home screen after DB is ready
var _origOnload = window.onload;
window.onload = function() {
  window.afterDB(function() {
    try { if (_origOnload) _origOnload(); } catch(e) { console.warn('[mono] origOnload error:', e); }
    try { updateHomeScreen(); } catch(e) {}
    try { setInterval(updateHomeScreen, 60000); } catch(e) {}
    try { loadHome图片(); } catch(e) {}
    try { document.querySelectorAll('.page').forEach(function(p) { p.classList.remove('active'); p.style.display = 'none'; }); } catch(e) {}
    try { var _mb = document.getElementById('menuBtn'); if (_mb) _mb.style.display = 'none'; } catch(e) {}
    try { var _hs = document.getElementById('homeScreen'); if (_hs) _hs.style.display = 'flex'; } catch(e) {}
  });
};


