(function(){
  function isGlassChat(){
    var page = document.getElementById('chatPage');
    return !!(page && (page.classList.contains('chat-theme-frosted') || page.classList.contains('bubble-preset-frosted')));
  }
  function syncGlassTitleColor(){
    try {
      var page = document.getElementById('chatPage');
      if (!page) return;
      var p = (typeof personas !== 'undefined' && typeof currentId !== 'undefined') ? personas.find(function(x){ return x.id == currentId; }) : null;
      var c = (p && p.frostedTitleColor) ? p.frostedTitleColor : (page.style.getPropertyValue('--theme-frosted-name-color') || '#ffffff');
      page.style.setProperty('--theme-frosted-name-color', c);
      page.style.setProperty('--mono-frosted-ui-color', c);
    } catch(e) {}
  }
  function syncGlassHeaderContactsButton(){
    try {
      var page = document.getElementById('chatPage');
      var btn = document.getElementById('chatContactsBtn');
      var header = page && page.querySelector('.chat-header');
      var back = page && page.querySelector('.chat-header-back-btn');
      var actions = page && page.querySelector('.chat-header-actions');
      if (!page || !btn || !header || !back || !actions) return;
      var glass = page.classList.contains('chat-theme-frosted') || page.classList.contains('bubble-preset-frosted');
      if (glass) {
        if (btn.parentElement !== header) header.insertBefore(btn, back.nextSibling);
      } else {
        if (btn.parentElement !== actions) actions.insertBefore(btn, actions.firstChild);
      }
    } catch(e) {}
  }
  function syncGlassKeyboardClean(){
    try {
      var root = document.documentElement;
      if (isGlassChat()) {
        root.style.setProperty('--mono-keyboard-offset', '0px');
        /* old keyboard mode: do not force page back to top while an input is focused */
      }
      syncGlassHeaderContactsButton();
      syncGlassTitleColor();
    } catch(e) {}
  }
  var _glassCleanQueued = false;
  function scheduleGlassKeyboardClean(){
    if (_glassCleanQueued) return;
    _glassCleanQueued = true;
    requestAnimationFrame(function(){
      _glassCleanQueued = false;
      syncGlassKeyboardClean();
    });
  }
  window.monoSyncCleanGlassChatFix = syncGlassKeyboardClean;
  window.monoScheduleCleanGlassChatFix = scheduleGlassKeyboardClean;
  var oldApply = window.applyBubbleStyles;
  if (typeof oldApply === 'function' && !oldApply.__monoCleanGlassWrapped) {
    var wrapped = function(p){
      var r = oldApply.apply(this, arguments);
      setTimeout(scheduleGlassKeyboardClean, 0);
      setTimeout(scheduleGlassKeyboardClean, 80);
      return r;
    };
    wrapped.__monoCleanGlassWrapped = true;
    window.applyBubbleStyles = wrapped;
  }
  ['resize','orientationchange'].forEach(function(ev){
    window.addEventListener(ev, function(){ setTimeout(scheduleGlassKeyboardClean, 30); setTimeout(scheduleGlassKeyboardClean, 180); }, {passive:true});
  });
  document.addEventListener('focusin', function(e){
    if (e.target && e.target.id === 'userInput') {
      scheduleGlassKeyboardClean();
      setTimeout(scheduleGlassKeyboardClean, 80);
      setTimeout(scheduleGlassKeyboardClean, 260);
    }
  }, true);
  document.addEventListener('focusout', function(e){
    if (e.target && e.target.id === 'userInput') setTimeout(scheduleGlassKeyboardClean, 100);
  }, true);
  document.addEventListener('DOMContentLoaded', function(){
    scheduleGlassKeyboardClean();
  });
})();


