const COVER_COLORS = ['#1a1a1a','#2d4a3e','#3a2d4a','#4a3a2d','#2d3a4a','#4a2d2d','#2d4a4a','#4a4a2d','#3a3a3a','#1a2d4a'];
function makeCoverColor(title) {
  let h = 0;
  for (let c of title) h = (h * 31 + c.charCodeAt(0)) & 0xffffffff;
  return COVER_COLORS[Math.abs(h) % COVER_COLORS.length];
}
