// ===================== 核心数据 =====================
// 安全解析：localStorage 中损坏的 JSON 不会导致整页崩溃
function _safeParse(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (raw === null || raw === undefined) return fallback;
    const parsed = JSON.parse(raw);
    return (parsed !== null && parsed !== undefined) ? parsed : fallback;
  } catch(e) {
    console.warn('[mono] localStorage 解析失败，已使用默认值：', key, e.message);
    return fallback;
  }
}
let personas = _safeParse('mono_personas', []);
let currentId = null;
let isWechatMode = true; // 强制微信模式，永久开启
let apiConfig = _safeParse('mono_api', { url: '', key: '', model: '' });
const AUTO_MODEL_SENTINEL = '__auto__';
const EFFECTIVE_API_STORAGE_KEY = 'mono_effective_api';

// ===== MONO API COST ROUTER PATCH =====
// 普通聊天采用一次 API 聊天包模式：当前正在使用的 API 负责本轮聊天包。
// 副 API 不再被强制指定为“小功能 API”；用户切换到哪个 API，独立功能/生成就跟随哪个 API。
const MONO_AUX_API_FEATURES_KEY = 'mono_aux_features_enabled';
const MONO_AUX_API_ID_KEY = 'mono_aux_api_id';
const MONO_ONE_SHOT_CHAT_KEY = 'mono_one_shot_chat_enabled';
function monoOneShotChatEnabled() {
  const stored = localStorage.getItem(MONO_ONE_SHOT_CHAT_KEY);
  // 默认开启：普通 char 聊天尽量只调用一次 API；用户手动关闭才恢复旧的多段小功能调用。
  return stored !== 'false';
}
function monoToggleOneShotChat(enabled) {
  try { localStorage.setItem(MONO_ONE_SHOT_CHAT_KEY, enabled ? 'true' : 'false'); } catch(e) {}
}
function monoOneShotChatInstruction() {
  if (!monoOneShotChatEnabled()) return '';
  return `

【一次 API 聊天包模式 · 省调用规则】
- 本次普通 char 聊天只能依靠这一轮 API 完成核心回复、心声/记忆标签判断和语气决策，不要让系统再为贴图判断、文字图判断、转账/外卖判断、黑盒心声记录、自动总结等另开 API。
- 如果需要记录心声，只能在本次回复末尾使用既有 [heart_voice]{...} 标签；如果需要自刻记忆，只能使用既有 [memory: ...] 标签。
- 不要输出任何“需要另行调用功能”“稍后生成小功能”的说明。
- 除非用户明确点击了独立小功能按钮，否则普通聊天只生成聊天正文。`; 
}

function monoBuildOneShotStickerPack(p) {
  try {
    if (!monoOneShotChatEnabled() || !p || !p.allowSticker) return { prompt: '', candidates: [] };
    if (typeof getStickers !== 'function' || typeof _buildPersonaStickerCandidates !== 'function') return { prompt: '', candidates: [] };
    const allowedLibraryIds = Array.isArray(p.stickerLibraryIds) && p.stickerLibraryIds.length ? p.stickerLibraryIds : null;
    const stickers = getStickers(allowedLibraryIds);
    if (!Array.isArray(stickers) || stickers.length === 0) return { prompt: '', candidates: [] };
    const recentText = (Array.isArray(p.history) ? p.history.slice(-8) : []).map(function(m){ return String(m.content || ''); }).join(' ');
    if (/去世|死|病危|自杀|分手|离婚|葬礼|急救|住院|崩溃|绝望|遗书/.test(recentText)) return { prompt: '', candidates: [] };
    const candidates = _buildPersonaStickerCandidates(stickers, Array.isArray(p.history) ? p.history : [], 12);
    if (!candidates.length) return { prompt: '', candidates: [] };
    const list = candidates.map(function(s, i){
      const desc = s._visionDesc || s.caption || '无描述';
      return i + '：' + String(desc).slice(0, 80);
    }).join('\n');
    return {
      candidates: candidates,
      prompt: `\n\n【一次聊天包 · 真实表情包规则】\n如果你觉得这一轮回复适合发送表情包，可以在回复末尾单独追加一行：[sticker:编号]\n编号只能从下面列表选择。不要写“（表情包消息）”“发送表情包”“表情包消息”等文字占位。\n如果不适合发，就不要写 sticker 标签。严肃/沉重/争吵升级时不要发表情包。\n【可用表情包编号】\n${list}\n【输出例】\n文字回复###下一条文字\n[sticker:2]\n`
    };
  } catch(e) {
    console.warn('[one-shot sticker] build pack failed:', e);
    return { prompt: '', candidates: [] };
  }
}
function monoExtractOneShotSticker(rawContent, stickerPack) {
  const out = { text: String(rawContent || ''), sticker: null };
  try {
    if (!stickerPack || !Array.isArray(stickerPack.candidates) || !stickerPack.candidates.length) return out;
    const re = /\n?\s*(?:\[\s*(?:sticker|贴图|表情包|sticker_id)\s*[:：]\s*(\d+)\s*\]|【\s*(?:sticker|贴图|表情包)\s*[:：]\s*(\d+)\s*】)\s*$/i;
    const m = out.text.match(re);
    if (!m) return out;
    const idx = parseInt(m[1] || m[2], 10);
    if (!Number.isFinite(idx) || idx < 0 || idx >= stickerPack.candidates.length) {
      out.text = out.text.replace(re, '').trim();
      return out;
    }
    const s = stickerPack.candidates[idx];
    if (s && (s.src || s.stickerSrc || s.url || s.image)) {
      out.sticker = (typeof window !== 'undefined' && typeof window._normalizeStickerItem === 'function') ? window._normalizeStickerItem(s) : s;
    }
    out.text = out.text.replace(re, '').trim();
  } catch(e) { console.warn('[one-shot sticker] extract failed:', e); }
  return out;
}

function monoBuildOneShotImagePrompt(p) {
  try {
    if (!monoOneShotChatEnabled() || !p || p.allowImageGen !== true) return '';
    const cfg = (typeof monoGetImageApiConfig === 'function') ? monoGetImageApiConfig() : {};
    const hasImageApi = !!(cfg && cfg.url && cfg.key && cfg.model);
    const lastUser = (Array.isArray(p.history) ? p.history.slice().reverse().find(function(m){ return m && m.role === 'user' && !m._hiddenContext && !m._systemNote; }) : null);
    const userText = lastUser ? String(lastUser.content || '') : '';
    const explicit = (typeof monoLooksLikeImageRequest === 'function') ? monoLooksLikeImageRequest(userText) : false;
    return `

【一次聊天包 · 真实生图判断规则 V10】
生图不能在用户刚发消息时立刻触发；用户本轮文字只能作为参考。必须先由你完成本轮普通角色回复，再根据“你这次回复是否已经答应/准备给用户看某个画面”来决定是否附带真实图片。
如果这一轮确实需要发送图片，只能在全部文字回复最后单独追加一行：[image_gen|prompt=图片内容描述|caption=可选配文]
前端会先显示你的文字回复，再开始生成图片；不要写“（图片消息）”“我生成图片中”“发图占位”等文字。

严格限制：
- 当前角色${p.allowImageGen === true ? '已开启' : '未开启'}生图；生图 API ${hasImageApi ? '已配置' : '未完整配置'}。
- 用户本轮原文：${userText.slice(0, 220) || '（无）'}
- 用户本轮${explicit ? '明确要求看图/发图/给他看看某物' : '没有明确要求看图/发图'}。
- 判断顺序必须是：先正常回复用户 → 再看你自己的回复是否自然表示“答应发图/给用户看/拍给用户看/发照片给用户”。只有你的回复已经表达这种意思时，才追加 image_gen 标签。
- 如果用户明确要求看图/发图，而且角色没有理由拒绝，通常应该自然答应，并在回复末尾追加 image_gen 标签；不要只口头答应却不发图。
- 如果你的回复是在拒绝、回避、转移话题、只想文字解释，或者没有明确要给用户看画面，就不要追加 image_gen 标签。
- 没有明确要求时，默认不要发图；只有角色回复内容本身非常自然地需要“顺手拍一张给用户看”时才允许低频使用。
- 用户只是普通聊天、提到“照片/图片/看/拍/风景”等词，不等于必须发图；必须看你的角色回复是否真的答应发图。
- 如果要发图，prompt 必须写具体可见内容：物件、场景、角度、光线、手机随手拍感；不要写抽象情绪。
- 如果你已经选择发图，你的文字回复必须自然承接这张图，但不能重复说明系统会生成图片。
- 一轮最多一个 [image_gen|...] 标签；不要和大型卡片乱叠。
- 不确定就不要输出 image_gen 标签。`;
  } catch(e) { return ''; }
}
function monoExtractOneShotImageGen(rawContent) {
  const out = { text: String(rawContent || ''), image: null };
  try {
    const re = /\n?\s*\[\s*(?:image_gen|image|img|生图|生图|发图|发图)\s*(?:\|\s*([\s\S]*?)|[:：]\s*([\s\S]*?))\]\s*$/i;
    const m = out.text.match(re);
    if (!m) return out;
    const body = String(m[1] || m[2] || '').trim();
    let prompt = body;
    let caption = '';
    if (body.indexOf('=') > -1 || body.indexOf('|') > -1) {
      const kv = (typeof monoParseKvTagBody === 'function') ? monoParseKvTagBody(body) : {};
      prompt = kv.prompt || kv.desc || kv.description || kv.content || kv.text || body;
      caption = kv.caption || kv.note || '';
    }
    prompt = String(prompt || '').replace(/^prompt\s*[:：=]\s*/i, '').trim();
    caption = String(caption || '').trim();
    out.text = out.text.replace(re, '').trim();
    if (prompt && prompt.length >= 2) out.image = { prompt: prompt.slice(0, 900), caption: caption.slice(0, 80) };
  } catch(e) { console.warn('[one-shot image] extract failed:', e); }
  return out;
}
