(function installApiUsageTracker(){
  if (window.__monoApiUsageTrackerInstalled) return;
  window.__monoApiUsageTrackerInstalled = true;
  const baseFetch = window.fetch.bind(window);
  window.fetch = async function(input, init) {
    const requestUrl = typeof input === 'string' ? input : ((input && input.url) || '');
    const method = String((init && init.method) || (input && input.method) || 'GET').toUpperCase();
    const headers = _monoBuildHeadersObject(input, init);
    if (!_monoShouldTrackApiUsage(requestUrl, method, headers)) {
      return baseFetch(input, init);
    }
    const body = await _monoReadRequestBodyForUsage(input, init);
    const requestMeta = _monoGetRequestMetaFromBody(body, requestUrl);
    const sourceCaller = _monoParseStackCaller((new Error()).stack || '');
    const meta = {
      url: requestUrl,
      method: method,
      endpointType: _monoGetEndpointType(requestUrl),
      sourceCaller: sourceCaller,
      sourceLabel: _monoResolveApiUsageSource(sourceCaller, requestMeta.promptPreview),
      requestModel: requestMeta.model,
      requestedMaxTokens: requestMeta.requestedMaxTokens,
      messageCount: requestMeta.messageCount,
      promptPreview: requestMeta.promptPreview
    };
    return _monoRunTrackedApiRequest(meta, function() {
      return baseFetch(input, init);
    });
  };
})();
// userProfile 初始化：从 localStorage 读文字字段，头像从 IDB blob 异步加载
