    // would be missing. Re-parsing here guarantees we get the complete data.
    try {
      const _rawPersonas = JSON.parse(localStorage.getItem('mono_personas') || '[]');
      // Restore chatBgImage AND history from separate IndexedDB keys
      personas = _rawPersonas.map(p => {
        let restored = Object.assign({}, p);
        // Restore chatBgImage
        if (restored.chatBgImage === '__ref__') {
          restored.chatBgImage = localStorage.getItem('mono_bg_' + p.id) || '';
        }
        // Restore history (stored separately for unlimited capacity)
        if (restored.history === '__hist_ref__' || !Array.isArray(restored.history)) {
          try {
            const histRaw = localStorage.getItem('mono_hist_' + p.id);
            const parsed = histRaw ? JSON.parse(histRaw) : [];
            restored.history = Array.isArray(parsed) ? parsed : [];
          } catch(he) { restored.history = []; }
        }
        return restored;
      });
    } catch(e) { personas = personas || []; }
    try { groups = JSON.parse(localStorage.getItem('mono_groups') || '[]'); } catch(e) {}
    // Also reload other large data structures that may have been missed
    try { momentsData = JSON.parse(localStorage.getItem('mono_moments') || '[]'); } catch(e) {}
    try { diaryData = JSON.parse(localStorage.getItem('mono_diary') || '[]'); } catch(e) {}
    try { novelBookshelf = JSON.parse(localStorage.getItem('mono_novel_shelf') || '[]'); } catch(e) {}
