async function confirmMultiDelete() {
  if (selectedMsgIndices.size === 0) return;
  const p = personas.find(x => x.id == currentId);
  if (!p) return;
  const ok = await window.monoInAppConfirm({
    title: '批量删除消息',
    note: '确定删除选中的 ' + selectedMsgIndices.size + ' 条消息？',
    confirmText: '删除',
    cancelText: '取消',
    danger: true
  });
  if (!ok) return;
  const indices = Array.from(selectedMsgIndices).sort((a, b) => b - a);
  const removed = indices.map(function(i) { return p.history[i]; }).filter(Boolean);
  await monoDeleteChatMessagesImageData(p.id, removed);
  indices.forEach(i => p.history.splice(i, 1));
  saveData();
  cancelMultiSelect();
  renderMessages();
  spyDataCache = {};
}
async function regenerateMsg(idx) {
  const p = personas.find(x => x.id == currentId);
  if (!p) return;
  if (!_hasUsableApiConfig(apiConfig)) { alert('请先配置API'); return; }
  p.history.splice(idx);
  renderMessages();
  const typing = document.getElementById('typingArea');
  typing.classList.remove('hidden');
  const min回复 = p.min回复Count || 1;
  const max回复 = p.max回复Count || 5;
  const count = Math.floor(Math.random() * (max回复 - min回复 + 1)) + min回复;
  const modePrompt = BUILTIN_WB;
  const _regenUserIdentity = (typeof monoResolveUserIdentityProfile === 'function')
    ? monoResolveUserIdentityProfile(p)
    : (typeof userProfile !== 'undefined' ? userProfile : { name: '用户' });
  const _regenUserName = monoGetResolvedUserDisplayName(_regenUserIdentity, (userProfile.name || '用户'));
  const _regenRecentChat = p.history.slice(-(p.memoryCount||100)).map(function(m) {
    const speakerName = m.role === 'user'
      ? monoGetResolvedUserDisplayName(
          (typeof monoResolveUserIdentityProfile === 'function')
            ? monoResolveUserIdentityProfile(p, { message: m, maskId: m.userMaskId || '' })
            : _regenUserIdentity,
          _regenUserName
        )
      : p.name;
    return `${speakerName}：${m.content||''}`;
  }).join('\n');
  const _regenWbInject = typeof buildWorldBookInjection === 'function' ? buildWorldBookInjection(_regenRecentChat, p.id) : '';
  const _regenGcInject = _buildGcMemoryInjection(p.id);
  const _regenHealthInject = typeof _buildHealthInjection === 'function' ? _buildHealthInjection(p.id) : '';
  const _regenLangCode = _detectPersonaLang(p);
  const _regenLangOv = _langOverridePrompt(_regenLangCode);
  const _regenLangHeader = _regenLangOv ? `${_regenLangOv}\n⚠️ 上述语言指令为最高优先级，整个回复必须严格遵守，不得使用其他语言。\n\n` : '';
  const sysPrompt = `${_regenLangHeader}${LANG_SYSTEM_PREFIX}${STYLE_INSTRUCTIONS}\n你是${p.name}。人设：${p.persona}。你对用户（${_regenUserName}）的昵称是${p.nickname||p.name}。${_regenLangOv}\n请连续发送 ${count} 条消息，消息之间用 "###" 分隔。这些消息要像同一个人连续说话一样自然流动，意思和情绪一脉相承，读起来连贯流畅，而不是各自独立的碎片。绝对遵守人设。${modePrompt}${_regenWbInject}${_regenGcInject}${_regenHealthInject}`;
  try {
    const memC = p.memoryCount || 100;
    const historyToSend = p.history.slice(-memC)
      .filter(m => m && !m._hiddenContext && !m._systemNote && !m._transferContext && !m.imageGenerating && !m._pendingImageGen)
      .map((m, idx, arr) => {
      let content = m.content || '';
      if (m.msgType === 'voice' && m.role === 'user') {
        content = content ? `[语音消息] ${content}` : '[语音消息（内容不明）]';
      }
      if (m.msgType === 'image') {
        return {
          role: m.role === 'user' ? 'user' : 'assistant',
          content: _buildImageHistoryText(m, idx, arr)
        };
      }
      if (m.msgType === 'sticker') {
        return {
          role: m.role === 'user' ? 'user' : 'assistant',
          content: (typeof _monoBuildStickerHistoryText === 'function')
            ? _monoBuildStickerHistoryText(m, idx, arr, p, _regenUserName)
            : '[表情包消息]'
        };
      }
      if (m.msgType === 'takeout_card') {
        return {
          role: m.role === 'user' ? 'user' : 'assistant',
          content: _buildTakeoutHistoryText(m.takeoutData || {})
        };
      }
      return { role: m.role === 'user' ? 'user' : 'assistant', content };
    });
    const response = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(_applyApiModel({ messages: [{role:'system',content:sysPrompt},...historyToSend], temperature: p.temperature || 1.0 }, apiConfig.model))
    });
    if (!response.ok) {
      let errorDetail = '';
      try { const errData = await response.json(); errorDetail = JSON.stringify(errData); } catch(ex) { errorDetail = await response.text().catch(() => ''); }
      throw new Error(`API错误 (${response.status} ${response.statusText})\n\n服务器返回: ${errorDetail}\n\n可能原因:\n1. API密钥无效或已过期\n2. 模型名称不正确\n3. API服务器暂时不可用\n4. 请求超出配额限制`);
    }
    const data = await response.json();
    const replyText = _extractAssistantMessageContent(data);
    let messages = replyText.split('###').map(s=>s.trim()).filter(s=>s);
    // 微信模式下：强制每条消息去除换行
    if (isWechatMode) {
      messages = messages.map(m => m.replace(/[\r\n]+/g, ''));
    }
    // 强制执行最少/最多信息条数
    if (messages.length > max回复) messages = messages.slice(0, max回复);
    if (messages.length === 0) {
      throw new Error('AI返回了空回复，请重试');
    }
    typing.classList.add('hidden');
    for (let msg of messages) {
      await new Promise(r => setTimeout(r, 800 + Math.random()*1500));
      msg = msg.replace(/\\n/g, '\n').replace(/\n/g, '');
      p.history.push({ role: 'assistant', content: msg });
      renderMessages();
      saveData();
    }
    spyDataCache = {};
  } catch(e) {
    typing.classList.add('hidden');
    console.warn('重新生成失败:', e.message);
    _showApiErrorToast('重新生成失败', e);
  }
}
