async function openSpyApp(appId, personaId) {
  const p = personas.find(x => x.id == personaId);
  if (!p) return;
  document.querySelectorAll('.spy-app-page').forEach(pg => pg.classList.remove('open'));
  document.getElementById(appId).classList.add('open');
  const liveApiConfig = _getCurrentActiveApiConfig();
  const cacheKey = `${personaId}_${appId}_${_getApiConfigSignature(liveApiConfig)}`;
  if (spyDataCache[cacheKey]) { renderSpyApp(appId, spyDataCache[cacheKey], p); return; }
  const bodyId = appId + 'Body';
  const bodyEl = document.getElementById(bodyId);
  if (bodyEl) bodyEl.innerHTML = '<div class="spy-loading"><div class="spy-spinner"></div>正在读取数据...</div>';
  try {
    const data = await generateSpyAppData(appId, p);
    spyDataCache[cacheKey] = data;
    renderSpyApp(appId, data, p);
  } catch(e) {
    if (bodyEl) bodyEl.innerHTML = `<div class="spy-loading" style="color:#ff3b30;">载入失败<br><span style="font-size:10px;">${e.message}</span></div>`;
  }
}
function closeSpyApp(appId) { document.getElementById(appId).classList.remove('open'); }
async function refreshSpyApp(appId) {
  const p = personas.find(x => x.id == currentSpyPersonaId);
  if (!p) return;
  const liveApiConfig = _getCurrentActiveApiConfig();
  const cacheKey = `${currentSpyPersonaId}_${appId}_${_getApiConfigSignature(liveApiConfig)}`;
  delete spyDataCache[cacheKey];
  const btn = document.getElementById('refreshBtn' + appId);
  if (btn) btn.classList.add('spinning');
  const bodyId = appId + 'Body';
  const bodyEl = document.getElementById(bodyId);
  if (bodyEl) bodyEl.innerHTML = '<div class="spy-loading"><div class="spy-spinner"></div>重新生成中...</div>';
  try {
    const data = await generateSpyAppData(appId, p);
    spyDataCache[cacheKey] = data;
    renderSpyApp(appId, data, p);
  } catch(e) {
    if (bodyEl) bodyEl.innerHTML = `<div class="spy-loading" style="color:#ff3b30;">生成失败<br><span style="font-size:10px;">${e.message}</span></div>`;
  } finally {
    if (btn) btn.classList.remove('spinning');
  }
}
let currentSpyPersonaId = null;
async function generateSpyAppData(appId, persona) {
  const liveApiConfig = _getCurrentActiveApiConfig();
  const fullChat = persona.history.slice(-(persona.memoryCount||100)).map(m => {
    const label = m.role === 'user' ? userProfile.name : persona.name;
    const content = (m.msgType === 'voice' && m.role === 'user')
      ? `[语音消息] ${m.content || '（内容不明）'}`
      : (m.content || '');
    return `${label}：${content}`;
  }).join('\n');
  const relationCtx = fullChat ? `\n\n【${persona.name}与${userProfile.name}的近期聊天记录】:\n${fullChat}` : '';
  const userCtx = `用户名：${userProfile.name}${userProfile.bio ? '，简介：' + userProfile.bio : ''}`;
  const prompts = {
    spyTaobao: `${LANG_SYSTEM_PREFIX}你是${persona.name}，人设：${persona.persona}。${userCtx}。${relationCtx}\n\n根据角色的性格、生活方式，以及与${userProfile.name}的关系和近期聊天内容，生成这个人最近在淘宝的购物记录（5-7条）。返回JSON数组：\n[{"category":"clothing/food/beauty/electronics/home/book/sport/other","name":"商品名","desc":"商品描述（20字内）","price":"¥XX.XX","date":"YYYY-MM-DD"}]\n只返回JSON。`,
    spyWechat: `${LANG_SYSTEM_PREFIX}你是${persona.name}，人设：${persona.persona}。${userCtx}。${relationCtx}
【重要约束】
1. 你必须完全基于${persona.name}的人设来生成微信联系人和对话。
2. 如果${persona.name}的人设中有恋爱关系（如有女朋友/男朋友/配偶），那么微信中不能出现暧昧对象、前任等矛盾内容。
3. 联系人的关系必须与${persona.name}的人设和与${userProfile.name}的聊天记录保持一致，不能有任何矛盾。
4. 对话内容要贴合${persona.name}的性格和说话风格。
5. 对话内容要与近期和${userProfile.name}的聊天内容相关联（如有的话）。
生成这个人微信里的5个联络人及对话记录。返回JSON数组：
[{"name":"联络人名","relation":"关系（必须与人设一致）","color":"#十六进制颜色","preview":"最近一条消息（15字内）","time":"时间","messages":[{"from":"them/me","text":"消息内容"}]}]
每个联络人至少4条messages。只返回JSON。`,
    spyMemo: `${LANG_SYSTEM_PREFIX}你是${persona.name}，人设：${persona.persona}。${userCtx}。${relationCtx}\n\n生成这个人备忘录里的4-5条记录。返回JSON数组：\n[{"title":"标题","content":"完整内容（50-120字）","date":"YYYY-MM-DD HH:MM"}]\n只返回JSON。`,
    spyWallet: `${LANG_SYSTEM_PREFIX}你是${persona.name}，人设：${persona.persona}。${userCtx}。${relationCtx}\n\n生成这个人最近的钱包交易记录（8-10条）。返回JSON：\n{"balance":"¥XXXX.XX","month_expense":"¥XXXX.XX","month_income":"¥XXXX.XX","transactions":[{"category":"food/transport/shopping/entertainment/salary/transfer/other","name":"项目名","date":"MM-DD HH:MM","amount":"+/-XXX.XX","type":"income/expense"}]}\n只返回JSON。`,
    spyMusic: `${LANG_SYSTEM_PREFIX}你是${persona.name}，人设：${persona.persona}。${userCtx}。${relationCtx}\n\n生成这个人最近3天的音乐播放记录（8-10首）。返回JSON：\n{"now_playing":{"song":"当前歌曲名","artist":"歌手"},"history":[{"song":"歌曲名","artist":"歌手名","date":"MM-DD","time":"HH:MM"}]}\n只返回JSON。`,
    spyBrowser: `${LANG_SYSTEM_PREFIX}你是${persona.name}，人设：${persona.persona}。${userCtx}。${relationCtx}\n\n生成这个人最近的浏览器搜索及浏览记录（8-10条）。返回JSON数组：\n[{"category":"social/shopping/news/search/video/music/other","title":"搜索或网页标题","url":"相关域名","time":"时间如：今天 14:32"}]\n只返回JSON。`
  };
  const prompt = prompts[appId];
  if (!prompt) throw new Error('未知app');
  if (!_hasUsableApiConfig(liveApiConfig)) throw new Error('请先配置API');
  const response = await fetch(`${liveApiConfig.url.replace(/\/$/, '')}/chat/completions`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${liveApiConfig.key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(_applyApiModel({ messages: [{ role: 'user', content: prompt }], temperature: 0.9, max_tokens: 2000 }, liveApiConfig.model))
  });
  if (!response.ok) throw new Error(`API Error: ${response.status}`);
  const res = await response.json();
  const text = _extractAssistantMessageContent(res).trim();
  return safeParseJSON(text);
}
