// 角色未开启生图时，文字图只生成“普通文字图内容”，绝不使用生图/照片描述 prompt。
function monoCleanNormalTextImageContent(raw) {
  let text = String(raw || '').trim();
  if (!text) return '';
  text = text.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
  try {
    const obj = JSON.parse(text);
    if (obj && typeof obj === 'object') {
      text = obj.text || obj.content || obj.prompt || obj.desc || obj.caption || text;
    }
  } catch(e) {}
  text = String(text || '')
    .replace(/^(?:文字图内容|文字图|内容|text|content|prompt)\s*[:：]/i, '')
    .replace(/[“”]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
  // 防止未开启生图时仍把“照片/画面/prompt/镜头/光线”等生图描述塞进文字图。
  text = text.replace(/^(?:一张|这是一张|画面中|照片中|图片中|镜头里|镜头中|手机随手拍|自然光|真实生活感)[，,\s]*/i, '').trim();
  return text.slice(0, 180);
}
