function monoDownloadPreviewImage() {
  const img = document.getElementById('imagePreviewImg');
  const src = img ? img.src : '';
  if (!src) return;
  const a = document.createElement('a');
  a.href = src;
  a.download = 'mono-image-' + Date.now() + (src.indexOf('image/webp')>-1?'.webp':src.indexOf('image/jpeg')>-1?'.jpg':'.png');
  document.body.appendChild(a); a.click(); a.remove();
}


// ===================== V11: API 数据集/Markdown 泄漏清理 =====================
function monoCleanApiDatasetLeak(text) {
  let s = String(text == null ? '' : text);
  if (!s) return '';
  // 常见污染形态：翻译样本后拼接训练文件路径，如 +++++ output/zh_CN/20240515_14_36_01_001.md
  s = s.replace(/\s*\+{3,}\s*output\/[A-Za-z_\-\/0-9.]+\.md[\s\S]*$/i, '').trim();
  s = s.replace(/\s*output\/(?:zh_CN|zh_Hans|zh_TW|ja_JP|en_US|ko_KR)\/[A-Za-z0-9_\-\/]+\.md[\s\S]*$/i, '').trim();
  // 防止整段二次资料/角色分析被当成聊天气泡
  const bad = /(《我的英雄学院》角色分析|爆豪勝己|Bakug[oō]\s*Katsuki|汗硝酸|自杀劝诱|###\s*\*\*一、角色概况|###\s*\*\*二、性格解析|output\/[A-Za-z_\-\/0-9.]+\.md)/i;
  if (bad.test(s)) {
    // 如果前面有正常短句，只保留污染前的自然文本；否则整条丢弃
    const cut = s.split(/\n\s*(?:-{3,}|###\s*\*\*|\*\*《|一、角色概况|二、性格解析)/)[0].trim();
    if (cut && cut.length <= 180 && !bad.test(cut)) return cut;
    return '';
  }
  return s.trim();
}
function monoSanitizeAllStoredApiDatasetLeaks() {
  try {
    if (!Array.isArray(personas)) return;
    let changed = false;
    personas.forEach(function(p){
      if (!p || !Array.isArray(p.history)) return;
      const next = [];
      p.history.forEach(function(m){
        if (!m || typeof m !== 'object') return;
        if (typeof m.content === 'string') {
          const cleaned = monoCleanApiDatasetLeak(m.content);
          if (cleaned !== m.content) changed = true;
          if (!cleaned && !m.msgType) return;
          m.content = cleaned;
        }
        next.push(m);
      });
      if (next.length !== p.history.length) changed = true;
      p.history = next;
    });
    if (changed) { try { saveData(); } catch(e) {} try { renderMessages({fast:true}); } catch(e) {} }
  } catch(e) {}
}
setTimeout(monoSanitizeAllStoredApiDatasetLeaks, 500);

// ===================== 发送消息 =====================
async function sendMessage() {
  const input = document.getElementById('userInput');
  const text = input.value.trim();
  if (!text || !currentId) return;
  const p = personas.find(x => x.id == currentId);
  if (!p) return;
  const resolvedUserIdentity = monoResolveUserIdentityProfile(p);
  const newMsg = { role: 'user', content: text, timestamp: Date.now(), userMaskId: resolvedUserIdentity.maskId || '' };
  if (currentQuoteMsg) {
    newMsg.quote = (typeof monoBuildQuotePayload === 'function') ? monoBuildQuotePayload(currentQuoteMsg) : {
      role: currentQuoteMsg.role,
      content: currentQuoteMsg.content,
      displayContent: currentQuoteMsg.displayContent || monoQuotePreviewText(currentQuoteMsg),
      msgType: currentQuoteMsg.msgType || '',
      locationData: currentQuoteMsg.locationData || null,
      senderName: currentQuoteMsg.senderName || ''
    };
  }
  // 确保 history 已加载（防止 history 是 __hist_ref__ 字符串）
  if (!Array.isArray(p.history)) {
    try {
      const raw = localStorage.getItem('mono_hist_' + p.id);
      p.history = raw ? JSON.parse(raw) : [];
      if (!Array.isArray(p.history)) p.history = [];
    } catch(e) { p.history = []; }
  }
  p.history.push(newMsg);
  p._lastUserChatTs = newMsg.timestamp;
  p.lastUserMessageTime = newMsg.timestamp;
  input.value = '';
  cancelQuote();
  saveData();
  renderMessages({ fast: true });
  renderContactList();
  try { tdRenderGamePanel(); } catch(e) {}
  // Scroll to bottom
  var chatBox = document.getElementById('chatBox');
  if (chatBox) chatBox.scrollTop = chatBox.scrollHeight;
  // Track chat message for task system
  if (typeof taskTrackChatMessage === 'function') taskTrackChatMessage(currentId, newMsg.timestamp);
  checkUserTransferIntent(text, p);
  var _tdOutcome = { skipDefaultAuto回复: false };
  if (typeof tdHandleUserMessageInActiveGame === 'function') {
    try { _tdOutcome = await tdHandleUserMessageInActiveGame(p, newMsg) || _tdOutcome; } catch(e) { console.warn('[td game send hook]', e); }
  }
  // V10：普通聊天不再在用户发送文字的瞬间触发生图。
  // 用户文字只作为参考；等角色本轮回复 API 返回后，根据角色回复是否答应/准备发图，通过 [image_gen|prompt=...] 标签一次性判断并附带发送。
  // 根据角色回复模式决定是否自动回复
  if (!_tdOutcome.skipDefaultAuto回复 && typeof _handleAuto回复AfterSend === "function") _handleAuto回复AfterSend(currentId);
  if (_isHeartVoiceGenerationEnabled(p) && (p.replyMode || 'manual') === 'manual' && _heartVoiceModeAllowsPopup(p) && _isHeartVoiceUiVisible()) {
    maybeGenerateReadHeartVoicePopup(currentId, text);
  }
}
