function toggleWechatMode() {
  isWechatMode = !isWechatMode;
  localStorage.setItem('mono_wechat_mode', isWechatMode ? '1' : '0');
  document.getElementById('wechatBtn').innerText = isWechatMode ? "Wechat: On" : "Wechat: Off";
  document.getElementById('modeStatus').innerText = isWechatMode ? "Modern Texting Mode" : "Immersion Mode";
  document.getElementById('chatPage').classList.toggle('wechat-style', isWechatMode);
}
