    + '  <input class="npc-editor-input npc-editor-link-label" type="text" value="' + monoRolePhoneEsc(link.label || '') + '" placeholder="例：旧同学 / 邻居 / 熟客">'
    + '  <label class="npc-editor-label" style="margin-top:8px;">关系描述</label>'
