function _getModelFetchSignature(url, key) {
  const normalizedUrl = _normalizeApiBaseUrl((url || '').trim());
  const normalizedKey = (key || '').trim();
  if (!normalizedUrl || !normalizedKey) return '';
  return `${normalizedUrl}__${normalizedKey.length}__${normalizedKey.slice(-6)}`;
}
function _setModelSelectOptions(selectId, models, selectedModel, placeholder, savedLabelPrefix) {
  const select = document.getElementById(selectId);
  if (!select) return;
  const list = Array.isArray(models) ? models.filter(Boolean) : [];
  const seen = new Set();
  select.innerHTML = '';
  const first = document.createElement('option');
  first.value = '';
  first.textContent = placeholder || '请选择模型';
  select.appendChild(first);
  list.forEach(function(id) {
    if (seen.has(id)) return;
    seen.add(id);
    const option = document.createElement('option');
    option.value = id;
    option.textContent = id;
    select.appendChild(option);
  });
  if (selectedModel) {
    if (!seen.has(selectedModel)) {
      const savedOption = document.createElement('option');
      savedOption.value = selectedModel;
      savedOption.textContent = (savedLabelPrefix || '当前已保存：') + selectedModel;
      select.appendChild(savedOption);
    }
    select.value = selectedModel;
  } else {
    select.value = '';
  }
}
function _markModelSelectionFresh(selectId, url, key) {
  const select = document.getElementById(selectId);
  if (!select) return;
  select.dataset.fetchSignature = _getModelFetchSignature(url, key);
}
function _isModelSelectionFresh(selectId, url, key) {
  const select = document.getElementById(selectId);
  if (!select) return false;
  return !!select.value && !!select.dataset.fetchSignature && select.dataset.fetchSignature === _getModelFetchSignature(url, key);
}
function onMainApiSourceInput() {
  const select = document.getElementById('modelSelect');
  if (!select) return;
  const currentSig = _getModelFetchSignature(document.getElementById('apiUrl').value, document.getElementById('apiKey').value);
  if (!select.dataset.fetchSignature || !currentSig || select.dataset.fetchSignature === currentSig) return;
  _setModelSelectOptions('modelSelect', [], '', 'API 地址或 Key 已变更，请重新点击“模型”提取', '当前已保存：');
  select.dataset.fetchSignature = '';
  setFetchStatus('请重新点击“模型”提取并选择当前站点可用模型。', true);
}
function getSelectedModel() { return document.getElementById('modelSelect').value.trim(); }
function setFetchStatus(msg,isError) {
  const el=document.getElementById('fetchStatus');
  el.textContent=msg; el.className=`text-xs mt-2 ${isError?'text-red-500':'text-green-600'}`;
  el.classList.remove('hidden');
}
async function fetchModels() {
  const url=_normalizeApiBaseUrl(document.getElementById('apiUrl').value.trim());
  const key=document.getElementById('apiKey').value.trim();
  if(!url||!key){ alert("请先填写 API URL 和 API Key！"); return; }
  setFetchStatus('正在获取模型列表...',false);
  try {
    const res = await _compatibleFetchModelList(url, key);
    if(!res.ok){ const t=await res.text().catch(()=>''); throw new Error(`HTTP ${res.status}${t?': '+t.slice(0,160):''}`); }
    const data=await res.json();
    const models=_extractApiModelIds(data);
    if(models.length===0) {
      _setModelSelectOptions('modelSelect', [], '', '该站点未返回可选模型', '当前已保存：');
      _markModelSelectionFresh('modelSelect', url, key);
      setFetchStatus('△ 已连通，但该站点没有返回可选模型列表。当前版本不支持手动输入模型，请确认该站点的 /models 接口是否正常。',true);
      return;
    }
    _cacheApiModels(url, models);
    const presetApi = _getPresetApiConfig();
    const preferredModel = (presetApi.url === url && presetApi.key === key && presetApi.model !== AUTO_MODEL_SENTINEL) ? presetApi.model : '';
    _setModelSelectOptions('modelSelect', models, preferredModel, '请选择模型', '当前已保存：');
    _markModelSelectionFresh('modelSelect', url, key);
    setFetchStatus(`✓ 成功获取 ${models.length} 个模型`,false);
  } catch(e) {
    setFetchStatus(`✗ ${e.message}`,true);
  }
}
// ── API URL 输入实时提示（支持标准反代 / HuggingFace / 直连格式识别）──
function _onApiUrlInput(el) {
  const hintEl = document.getElementById('apiUrlHint');
  if (!hintEl) return;
  const raw = (el.value || '').trim();
  if (!raw) { hintEl.style.display = 'none'; hintEl.textContent = ''; return; }
  let hint = '';
  if (/huggingface\.co/i.test(raw) || /hf\.space/i.test(raw)) {
    if (/\/models\/[^/]+\/v\d+/i.test(raw)) {
      hint = '✓ HuggingFace 推理端点（含模型路径 + /v1）格式正确';
    } else if (/\/models\/[^/]+/i.test(raw)) {
      hint = '✓ HuggingFace 推理端点 — 将自动追加 /v1，如需指定版本请在末尾加 /v1';
    } else if (/endpoints\.huggingface\.cloud/i.test(raw)) {
      hint = '✓ HuggingFace Dedicated Endpoint，确保末尾含 /v1';
    } else {
      hint = '⚠ HuggingFace URL 格式建议：https://api-inference.huggingface.co/models/<model-id>/v1';
    }
  } else if (/anthropic\.com/i.test(raw)) {
    hint = '✓ Anthropic 官方 API（claude-* 模型）— 支持自动适配格式';
  } else if (/openai\.com/i.test(raw)) {
    hint = '✓ OpenAI 官方 API — 标准格式：https://api.openai.com/v1';
  } else if (/\/v\d+$/i.test(raw)) {
    hint = '✓ 标准反代格式（Base URL 含 /v1），可直接使用';
  } else if (/^https?:\/\/.+/i.test(raw)) {
    hint = '提示：若反代不含 /v1，系统将自动尝试追加 /v1；也可手动加上 /v1';
  } else if (raw.length > 3) {
    hint = '⚠ 请以 https:// 或 http:// 开头';
  }
  if (hint) { hintEl.textContent = hint; hintEl.style.display = 'block'; }
  else { hintEl.style.display = 'none'; }
}
function saveApi() {
  const url=_normalizeApiBaseUrl(document.getElementById('apiUrl').value.trim());
  const key=document.getElementById('apiKey').value.trim();
  const model=getSelectedModel();
  if(!url||!key){ alert("请先填写 API URL 和 API Key！"); return; }
  if(!model){ alert('请先点击“模型”提取可用模型，并从列表中选择一个模型！'); return; }
  if(!_isModelSelectionFresh('modelSelect', url, key)) { alert('当前 API 地址或 Key 已变更，请重新点击“模型”提取并选择模型！'); return; }
  const presetApi = _normalizeApiConfigObject({url,key,model});
  localStorage.setItem('mono_api',JSON.stringify(presetApi));
  activeApiId = 'preset';
  localStorage.setItem(ACTIVE_API_KEY, 'preset');
  spyDataCache = {};
  apiConfig = _normalizeApiConfigObject(presetApi);
  _persistEffectiveApiConfig(apiConfig);
  if (typeof applyActiveApi === 'function') applyActiveApi();
  if (typeof renderSecondaryApiList === 'function') renderSecondaryApiList();
  if (typeof renderActiveApiIndicator === 'function') renderActiveApiIndicator();
  if (typeof updateFabPanel === 'function') updateFabPanel();
  setFetchStatus(`✓ 已保存：${model}`,false);
  setTimeout(()=>toggleApiSettings(),800);
}
async function testApi() {
  const urlInput = document.getElementById('apiUrl');
  const keyInput = document.getElementById('apiKey');
  const url = _normalizeApiBaseUrl((urlInput ? urlInput.value.trim() : '') || apiConfig.url);
  const key = (keyInput ? keyInput.value.trim() : '') || apiConfig.key;
  const model = getSelectedModel() || apiConfig.model || '';
  if (!url || !key) { alert('请填写完整的API配置（URL、Key）'); return; }
  if (!model) { alert('请先点击“模型”提取可用模型，并从列表中选择一个模型！'); return; }
  if (!_isModelSelectionFresh('modelSelect', url, key)) { alert('当前 API 地址或 Key 已变更，请重新点击“模型”提取并选择模型！'); return; }

  const statusEl = document.getElementById('apiStatus');
  if (statusEl) { statusEl.textContent = '正在测试连接...'; statusEl.style.color = '#f0ad4e'; }

  const provider = _detectApiProvider(url, model);
  const providerLabel = { anthropic:'Anthropic', gemini:'Gemini', azure:'Azure OpenAI', openai:'OpenAI', huggingface:'HuggingFace', groq:'Groq', together:'Together AI', mistral:'Mistral', openai_compat:'OpenAI 兼容' }[provider] || provider;

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 35000);
    const response = await _compatibleChatCompletion(url, key, {
      model: model,
      messages: [{ role: 'user', content: 'Hi' }],
      max_tokens: 16,
      temperature: 0.2
    }, { signal: controller.signal });
    clearTimeout(timeoutId);

    let errorBody = '';
    let bodyObj = null;
    if (!response.ok) {
      try { errorBody = await response.text(); bodyObj = _safeJsonParse(errorBody); } catch(ex) {}
    }

    if (!response.ok) {
      const s = response.status;
      // 解析服务端返回的错误信息
      const serverMsg = (bodyObj && (
        (bodyObj.error && (bodyObj.error.message || bodyObj.error.code)) ||
        bodyObj.message || bodyObj.detail || bodyObj.msg
      )) || errorBody.slice(0, 300);

      let suggestion = '';
      if (s === 400) {
        suggestion = '参数格式错误。常见原因：模型名称不正确、请求参数不被该 API 支持。';
        if (/model/i.test(serverMsg)) suggestion += '\n→ 请检查模型名是否填写正确（可点「模型」按钮获取可用模型列表）';
      } else if (s === 401) {
        suggestion = `认证失败（${providerLabel}）。\n→ 请检查 API Key 是否正确、是否已过期`;
        if (provider === 'anthropic') suggestion += '\n→ Anthropic Key 格式应以 sk-ant- 开头';
        else if (provider === 'gemini') suggestion += '\n→ Gemini Key 可在 Google AI Studio 免费申请';
        else if (provider === 'azure') suggestion += '\n→ Azure 需要填入部署端点 URL（不是 OpenAI 的 URL）';
      } else if (s === 403) {
        suggestion = '权限被拒绝。可能原因：账户无访问权限、IP 被封禁、模型需要单独申请。';
      } else if (s === 404) {
        suggestion = 'API 地址或模型不存在（404）。\n→ 请确认 Base URL 格式正确（通常以 /v1 结尾）\n→ 检查模型名是否与该平台支持的一致';
      } else if (s === 422) {
        suggestion = '参数校验失败（422）。\n→ 该 API 不接受某些参数，已自动尝试精简模式，但仍失败\n→ 请手动检查模型名是否正确';
      } else if (s === 429) {
        suggestion = '请求频率超限或余额不足（429）。\n→ 请稍后重试，或检查账户余额';
      } else if (s >= 500) {
        suggestion = `服务端错误（${s}）。该 API 服务器暂时出现问题，请稍后重试。`;
      }

      if (statusEl) { statusEl.textContent = `连接失败 (${s})`; statusEl.style.color = '#d9534f'; }
      alert(`API 测试失败 [${providerLabel}]\n\nHTTP ${s} ${response.statusText}\n\n${serverMsg ? '服务端返回：\n' + serverMsg + '\n\n' : ''}${suggestion}`);
      return;
    }

    let data = null;
    try { data = await response.json(); } catch(e) {}

    if (data && data.choices && data.choices.length > 0) {
      if (statusEl) { statusEl.textContent = '连接成功'; statusEl.style.color = '#5cb85c'; }
      const usedModel = (data.model || (data.choices[0].message && data.choices[0].index != null ? '' : '')) || _getEffectiveApiModel(model) || '自动适配';
      alert(`✅ API 连接成功！\n\n供应商识别：${providerLabel}\n实际模型：${usedModel}\n状态：正常运行`);
    } else if (data && (data.content || data.output || data.text)) {
      // 非标准 OpenAI 格式但有内容
      if (statusEl) { statusEl.textContent = '连接成功（非标准格式）'; statusEl.style.color = '#f0ad4e'; }
      alert(`✅ API 连通，但响应格式不是标准 OpenAI 格式。\n\n供应商：${providerLabel}\n\n返回内容（前200字）：\n${JSON.stringify(data).slice(0,200)}\n\n若正常使用中出现问题，请确认该 API 是否完整兼容 OpenAI /chat/completions 格式。`);
    } else {
      if (statusEl) { statusEl.textContent = '返回格式异常'; statusEl.style.color = '#f0ad4e'; }
      alert(`API 连通但返回内容异常。\n\n供应商：${providerLabel}\n返回：${JSON.stringify(data || {}).slice(0,300)}\n\n请确认该 API 是否兼容 OpenAI 格式。`);
    }
  } catch(e) {
    if (statusEl) { statusEl.textContent = '连接失败'; statusEl.style.color = '#d9534f'; }
    let msg = e.message || String(e);
    let tip = '';
    if (e.name === 'AbortError') {
      msg = '连接超时（35秒无响应）';
      tip = '\n→ API 服务器可能无法访问，或网络延迟过高';
    } else if (/failed to fetch|networkerror|network request failed/i.test(msg)) {
      tip = `\n→ 网络连接失败，可能原因：\n  1. API 地址不正确（需以 https:// 开头）\n  2. 该 API 服务器拒绝了跨域请求（CORS）\n  3. 当前网络无法访问该服务器`;
      if (provider === 'anthropic' || provider === 'openai') tip += `\n  4. 部分地区需要代理才能访问 ${providerLabel} 官方 API`;
    } else if (/cors/i.test(msg)) {
      tip = '\n→ 跨域（CORS）错误：该 API 服务器不允许从浏览器直接请求\n→ 建议使用支持 CORS 的反代服务';
    }
    alert(`API 连接失败 [${providerLabel}]\n\n${msg}${tip}`);
  }
}
