async function aiGenerateMomentsProfile(type, id, field, btnEl) {
  if (!apiConfig || !apiConfig.url || !apiConfig.key || !apiConfig.model) {
    alert('请先在设置里配置可用的 API。');
    return;
  }
  const requestKey = _momentsIdentityGenKey(type, id, field);
  const now = Date.now();
  if (_momentsIdentityGenPending[requestKey]) {
    alert('这项 AI 生成还在进行中，请先等上一条请求完成，避免重复扣额度。');
    return;
  }
  if (_momentsIdentityGenCooldown[requestKey] && now - _momentsIdentityGenCooldown[requestKey] < 4000) {
    alert('刚刚已经触发过一次生成了，请不要连续点，避免重复扣额度。');
    return;
  }
  const meta = getMomentsProfileMeta(type, id);
  if (!meta) return;
  const mode = field === 'nickname' ? 'nickname' : (field === 'signature' ? 'signature' : 'both');
  const prompt = _buildMomentsIdentityPrompt(type, id, mode);
  if (!prompt) {
    alert('找不到对应资料，暂时无法生成。');
    return;
  }
  const btn = btnEl || null;
  const oldHtml = btn ? btn.innerHTML : '';
  try {
    _momentsIdentityGenPending[requestKey] = true;
    _momentsIdentityGenCooldown[requestKey] = now;
    if (btn) {
      btn.disabled = true;
      btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> 生成中';
    }
    const resp = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiConfig.key}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: apiConfig.model,
        messages: [{ role: 'user', content: prompt }],
        temperature: 0.9,
        max_tokens: 220
      })
    });
    if (!resp.ok) {
      throw new Error('接口返回异常：' + resp.status);
    }
    const data = await resp.json();
    const rawText = (((data || {}).choices || [])[0] || {}).message ? ((((data || {}).choices || [])[0] || {}).message.content || '') : '';
    if (!_stripMomentsAiFences(rawText)) {
      throw new Error('AI 返回为空，界面不会生成任何内容，但这次请求已经发出。');
    }
    const parsed = _parseMomentsIdentityResult(rawText, meta.displayName || meta.name || '', meta.signature || '');
    const currentNickname = _normalizeMomentsIdentityCompareValue(meta.displayName || meta.name || '');
    const currentSignature = _normalizeMomentsIdentityCompareValue(meta.signature || '');
    const nextNickname = mode === 'signature'
      ? currentNickname
      : _normalizeMomentsIdentityCompareValue(parsed.nickname || '');
    const nextSignature = mode === 'nickname'
      ? currentSignature
      : _normalizeMomentsIdentityCompareValue(parsed.signature || '');
    const targetNicknameChanged = mode !== 'signature' && nextNickname && nextNickname !== currentNickname;
    const targetSignatureChanged = mode !== 'nickname' && nextSignature !== currentSignature;
    if (mode !== 'signature' && !nextNickname) {
      throw new Error('AI 没有返回可用的网名。原始返回：' + _momentsIdentityRawPreview(rawText));
    }
    if (mode !== 'nickname' && !nextSignature) {
      throw new Error('AI 没有返回可用的个性签名。原始返回：' + _momentsIdentityRawPreview(rawText));
    }
    if (!targetNicknameChanged && !targetSignatureChanged) {
      throw new Error('AI 返回的结果和当前主页资料相同，所以看起来像没有生成。原始返回：' + _momentsIdentityRawPreview(rawText));
    }
    if (type === 'user') {
      if (mode !== 'signature') userProfile.momentsNickname = nextNickname || userProfile.name || '用户';
      if (mode !== 'nickname') userProfile.momentsSignature = nextSignature || '';
      persistMomentsUserProfile();
    } else {
      const p = personas.find(function(x) { return String(x.id) === String(id); });
      if (!p) throw new Error('角色不存在');
      if (mode !== 'signature') p.momentsNickname = nextNickname || p.name;
      if (mode !== 'nickname') p.momentsSignature = nextSignature || '';
      saveData();
    }
    renderMoments();
  } catch (e) {
    alert('AI 生成主页资料失败：' + (e && e.message ? e.message : e));
  } finally {
    delete _momentsIdentityGenPending[requestKey];
    _momentsIdentityGenCooldown[requestKey] = Date.now();
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = oldHtml || '<i class="fas fa-sparkles"></i> AI生成';
    }
  }
}
