// ═══════════════════════════════════════════════════════════
//  MOMENTS SOCIAL STATS & NETWORK SYSTEM
// ═══════════════════════════════════════════════════════════

// ── Storage helpers ──────────────────────────────────────────
function _getMomentsNetworkStore() {
  try { return JSON.parse(localStorage.getItem('mono_moments_network') || '{}'); } catch(e) { return {}; }
}
function _saveMomentsNetworkStore(store) {
  try { localStorage.setItem('mono_moments_network', JSON.stringify(store)); } catch(e) {}
}
function _getMomentsStatsStore() {
  try { return JSON.parse(localStorage.getItem('mono_moments_stats') || '{}'); } catch(e) { return {}; }
}
function _saveMomentsStatsStore(store) {
  try { localStorage.setItem('mono_moments_stats', JSON.stringify(store)); } catch(e) {}
}

// ── Count formatter ──────────────────────────────────────────
function _formatSocialCount(n) {
  n = Math.floor(n || 0);
  if (n >= 100000000) return (n / 100000000).toFixed(1).replace(/\.0$/, '') + '亿';
  if (n >= 10000) return (n / 10000).toFixed(1).replace(/\.0$/, '') + '万';
  if (n >= 1000) return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'k';
  return String(n);
}

// ── Persona personality analysis for count seeding ────────────
function _analyzePersonaSocialTrait(p) {
  if (!p) return { base: 200, growthRate: 1.0 };
  const text = ((p.persona || '') + ' ' + (p.name || '') + ' ' + (p.nickname || '')).toLowerCase();
  let base = 200, followingBase = 80, growthRate = 1.0;

  // Identity / role boost
  if (/idol|偶像|爱豆|明星|歌手|演员|网红|博主|主播|up主|导演|模特/.test(text)) {
    base = 80000 + Math.floor(Math.random() * 200000);
    followingBase = 300 + Math.floor(Math.random() * 500);
    growthRate = 8.0;
  } else if (/知名|着名|有名|popular|famous|出名/.test(text)) {
    base = 15000 + Math.floor(Math.random() * 30000);
    followingBase = 200 + Math.floor(Math.random() * 300);
    growthRate = 4.0;
  } else if (/学生|高中|大学|校园|同学/.test(text)) {
    base = 80 + Math.floor(Math.random() * 400);
    followingBase = 100 + Math.floor(Math.random() * 200);
    growthRate = 0.6;
  } else if (/商人|总裁|老板|ceo|企业家|律师|医生|教授/.test(text)) {
    base = 500 + Math.floor(Math.random() * 2000);
    followingBase = 80 + Math.floor(Math.random() * 150);
    growthRate = 1.5;
  } else if (/作家|画家|艺术家|设计师|摄影|创作/.test(text)) {
    base = 800 + Math.floor(Math.random() * 5000);
    followingBase = 300 + Math.floor(Math.random() * 500);
    growthRate = 2.0;
  } else {
    base = 150 + Math.floor(Math.random() * 800);
    followingBase = 60 + Math.floor(Math.random() * 200);
    growthRate = 1.0;
  }

  // Personality modifier
  if (/外向|活泼|开朗|张扬|热情|健谈|社交|爱交朋友/.test(text)) {
    base = Math.floor(base * 1.6);
    followingBase = Math.floor(followingBase * 1.5);
    growthRate *= 1.4;
  } else if (/内向|安静|寡言|冷淡|疏离|孤僻/.test(text)) {
    base = Math.floor(base * 0.4);
    followingBase = Math.floor(followingBase * 0.5);
    growthRate *= 0.55;
  } else if (/冷|淡漠|傲慢|高冷/.test(text)) {
    base = Math.floor(base * 0.7);
    growthRate *= 0.75;
  }

  return { base: Math.max(base, 10), followingBase: Math.max(followingBase, 5), growthRate };
}

function _analyzeUserSocialTrait() {
  const text = ((userProfile && userProfile.name) || '') + ' ' + ((userProfile && userProfile.bio) || '') + ' ' + ((userProfile && userProfile.momentsSignature) || '');
  let base = 120 + Math.floor(Math.random() * 300);
  let followingBase = 80 + Math.floor(Math.random() * 150);
  let growthRate = 1.0;
  if (/博主|up主|主播|摄影|画画|设计|作家|模特|艺人|乐队|歌手|演员|创业|店主|主理人/.test(text)) {
    base = 800 + Math.floor(Math.random() * 5000);
    followingBase = 160 + Math.floor(Math.random() * 260);
    growthRate = 1.8;
  } else if (/学生|高中|大学|校园|实习|社团/.test(text)) {
    base = 100 + Math.floor(Math.random() * 500);
    followingBase = 90 + Math.floor(Math.random() * 180);
    growthRate = 0.75;
  }
  if (/外向|活泼|开朗|热情|社交|健谈/.test(text)) {
    base = Math.floor(base * 1.45);
    followingBase = Math.floor(followingBase * 1.25);
    growthRate *= 1.25;
  } else if (/内向|安静|慢热|寡言|冷淡|疏离/.test(text)) {
    base = Math.floor(base * 0.75);
    followingBase = Math.floor(followingBase * 0.85);
    growthRate *= 0.8;
  }
  return { base: Math.max(base, 10), followingBase: Math.max(followingBase, 5), growthRate };
}

// ── Stats initialization & auto-growth ───────────────────────
function _getMomentsStats(type, id) {
  const storeKey = type + '_' + id;
  const store = _getMomentsStatsStore();
  const now = Date.now();

  if (!store[storeKey]) {
    // First time: seed based on persona traits
    let trait;
    if (type === 'persona') {
      const p = personas.find(x => String(x.id) === String(id));
      trait = _analyzePersonaSocialTrait(p);
    } else {
      trait = _analyzeUserSocialTrait();
    }
    // Add slight randomness with a seeded offset based on id
    const seed = String(id).split('').reduce((a, c) => a + c.charCodeAt(0), 0);
    store[storeKey] = {
      followers: trait.base + (seed % 47),
      following: trait.followingBase + (seed % 13),
      growthRate: trait.growthRate,
      lastUpdate: now - Math.floor(Math.random() * 86400000 * 7) // pretend it started up to 7 days 前
    };
    _saveMomentsStatsStore(store);
  }

  // Auto-increment based on elapsed time
  const entry = store[storeKey];
  const elapsedHours = (now - entry.lastUpdate) / 3600000;
  if (elapsedHours >= 0.5) { // update at most every 30 min
    const baseHourlyGrowth = entry.growthRate * (entry.followers < 1000 ? 0.08 : entry.followers < 10000 ? 0.3 : entry.followers < 100000 ? 1.2 : 4);
    const followerGain = Math.floor(elapsedHours * baseHourlyGrowth * (0.7 + Math.random() * 0.6));
    const followingGain = Math.floor(elapsedHours * entry.growthRate * 0.02 * (0.5 + Math.random() * 1.0));
    entry.followers += Math.max(0, followerGain);
    entry.following += Math.max(0, followingGain);
    entry.lastUpdate = now;
    _saveMomentsStatsStore(store);
  }
  const customStats = type === 'user' ? _getUserCustomMomentsStats() : { followers: null, following: null };
  return {
    followers: customStats.followers == null ? entry.followers : customStats.followers,
    following: customStats.following == null ? entry.following : customStats.following
  };
}

// ── Open network list (粉丝 / 追踪) ──────────────────────────
let _networkListState = { type: '', id: '', listType: '' }; // listType: 'followers' | 'following'

async function openNetworkList(type, id, listType) {
  _networkListState = { type, id, listType };
  const overlay = document.getElementById('momentsNetworkOverlay');
  const titleEl = document.getElementById('momentsNetworkTitle');
  const subtitleEl = document.getElementById('momentsNetworkSubtitle');
  const listEl = document.getElementById('momentsNetworkList');
  const stats = _getMomentsStats(type, id);
  titleEl.textContent = listType === 'followers' ? '粉丝' : '正在追踪';
  subtitleEl.textContent = _formatSocialCount(listType === 'followers' ? stats.followers : stats.following) + ' 人';
  listEl.innerHTML = '<div class="moments-network-loading"><i class="fas fa-circle-notch fa-spin"></i>生成中，请稍候…</div>';
  overlay.classList.add('open');

  // Get or generate account list
  const store = _getMomentsNetworkStore();
  const storeKey = type + '_' + id;
  if (!store[storeKey]) store[storeKey] = {};
  const listKey = listType + 'List'; // 'followersList' or 'followingList'

  if (!store[storeKey][listKey] || store[storeKey][listKey].length === 0) {
    try {
      const accounts = await _generateNetworkAccounts(type, id, listType);
      store[storeKey][listKey] = accounts;
      _saveMomentsNetworkStore(store);
    } catch(e) {
      listEl.innerHTML = '<div class="moments-network-loading">生成失败，请重试</div>';
      return;
    }
  }

  _renderNetworkList(store[storeKey][listKey], listType, type, id);
}

function closeMomentsNetworkList(e) {
  if (e && e.target !== document.getElementById('momentsNetworkOverlay')) return;
  document.getElementById('momentsNetworkOverlay').classList.remove('open');
}

function _renderNetworkList(accounts, listType, contextType, contextId) {
  const listEl = document.getElementById('momentsNetworkList');
  if (!accounts || accounts.length === 0) {
    listEl.innerHTML = '<div class="moments-network-loading">暂无记录</div>';
    return;
  }
  listEl.innerHTML = accounts.map(function(acc) {
    const badge = listType === 'followers' ? '粉丝' : '追踪中';
    const avatarSrc = acc.avatar || makeAvatar(acc.name || '?', acc.avatarBg || '#888', '#fff');
    return `<div class="moments-network-account-item" onclick="openConnectedAccountProfile('${acc.id}','${contextType}','${contextId}')">
      <img class="moments-network-acct-avatar" src="${avatarSrc}" onerror="this.src='${makeAvatar(acc.name||'?','#888','#fff')}'">
      <div class="moments-network-acct-info">
        <div class="moments-network-acct-name">${_escapeHtml(acc.name)}</div>
        <div class="moments-network-acct-handle">${_escapeHtml(acc.handle)}</div>
        <div class="moments-network-acct-bio">${_escapeHtml(acc.bio || acc.signature || '')}</div>
      </div>
      <div class="moments-network-acct-badge">${badge}</div>
    </div>`;
  }).join('');
}

// ── AI generate network accounts ─────────────────────────────
async function _generateNetworkAccounts(type, id, listType) {
  const apiCfg = _getCurrentActiveApiConfig();
  if (!apiCfg.url || !apiCfg.key || !apiCfg.model) {
    // Fallback: generate placeholder accounts without AI
    return _generateFallbackAccounts(type, id, listType);
  }
  let personaDesc = '';
  let personaName = '';
  if (type === 'persona') {
    const p = personas.find(x => String(x.id) === String(id));
    if (p) {
      personaName = p.momentsNickname || p.name || '角色';
      personaDesc = (p.persona || '').substring(0, 600);
    }
  } else {
    personaName = userProfile.momentsNickname || userProfile.name || '用户';
    personaDesc = userProfile.bio || '';
  }
  const count = listType === 'followers' ? 12 : 10;
  const roleDesc = listType === 'followers'
    ? `这些账号是「${personaName}」在社交平台上的粉丝（关注了TA的人）`
    : `这些账号是「${personaName}」在社交平台上正在追踪的人（TA关注的账号）`;
  const prompt = `你是一个社交媒体账号生成器。\n角色资料：${personaName}，人设：${personaDesc}\n\n请根据上面的角色背景，生成${count}个真实感的社交账号。${roleDesc}。\n账号要有各种年龄、身份、性格，符合该角色的生活圈子和交际范围。每个账号有：name（昵称）、handle（@开头的账号，英文小写+数字）、bio（个性签名/简介，15-30字，简体中文）、relationship（和「${personaName}」的关系，如：高中同学、同事、网友、粉丝等，10字内）、avatarBg（头像背景色hex，如#e74c3c）。\n\n严格只返回JSON数组，不加任何说明：\n[{"name":"昵称","handle":"@xxx","bio":"简介","relationship":"关系","avatarBg":"#xxxxxx"}]`;

  const resp = await fetch(apiCfg.url.replace(/\/$/, '') + '/chat/completions', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + apiCfg.key, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: apiCfg.model, messages: [{ role: 'user', content: prompt }], max_tokens: 1200, temperature: 0.92 })
  });
  if (!resp.ok) throw new Error('API error ' + resp.status);
  const data = await resp.json();
  const raw = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '[]';
  const parsed = safeParseJSON(raw.replace(/```json|```/g, '').trim());
  if (!Array.isArray(parsed) || parsed.length === 0) return _generateFallbackAccounts(type, id, listType);
  return parsed.map(function(a, i) {
    return {
      id: 'acc_' + type + '_' + id + '_' + listType + '_' + i,
      name: a.name || '用户' + i,
      handle: a.handle || ('@user' + i),
      bio: a.bio || '',
      signature: a.bio || '',
      relationship: a.relationship || '',
      avatarBg: a.avatarBg || '#888888',
      avatar: makeAvatar((a.name || 'U').charAt(0), a.avatarBg || '#888888', '#fff')
    };
  });
}

function _generateFallbackAccounts(type, id, listType) {
  const names = ['小鱼儿','云朵','向阳花','深夜书房','静静','温柔的风','格调','笑忘书','半夏','暗香','凌云','傍晚','阿梦'];
  const bios = ['记录美好生活','喜欢拍照和旅行','佛系养花中','每天都要开心哦','普通人的普通日子','热爱音乐与咖啡','摄影/美食/生活','人间值得','慢慢来','读书改变气质'];
  return Array.from({ length: 10 }, function(_, i) {
    const bg = ['#e74c3c','#3498db','#2ecc71','#9b59b6','#f39c12','#1abc9c','#e67e22','#2980b9','#8e44ad','#16a085'][i % 10];
    const nm = names[i % names.length];
    return {
      id: 'acc_' + type + '_' + id + '_' + listType + '_' + i,
      name: nm,
      handle: '@' + nm.replace(/[^\w]/g, '').toLowerCase() + (100 + i),
      bio: bios[i % bios.length],
      signature: bios[i % bios.length],
      relationship: listType === 'followers' ? '粉丝' : '追踪',
      avatarBg: bg,
      avatar: makeAvatar(nm.charAt(0), bg, '#fff')
    };
  });
}

// ── Connected Account Profile View ───────────────────────────
// momentsViewState extended: { mode:'account', accountId, contextType, contextId }
// Account data cached: _connectedAccountCache[accountId] = { account, 帖子s }

let _connectedAccountCache = {};

function openConnectedAccountProfile(accountId, contextType, contextId) {
  // Close network list overlay
  const overlay = document.getElementById('momentsNetworkOverlay');
  if (overlay) overlay.classList.remove('open');

  momentsViewState = { mode: 'account', accountId, contextType, contextId };
  renderMoments();
  // Trigger async 帖子 generation after render
  setTimeout(function() { _ensureConnectedAccount帖子(accountId, contextType, contextId); }, 100);
}

function _buildConnectedAccountProfileView() {
  const { accountId, contextType, contextId } = momentsViewState;
  // Find account info
  const store = _getMomentsNetworkStore();
  const storeKey = contextType + '_' + contextId;
  const allAccounts = ((store[storeKey] || {}).followersList || []).concat(((store[storeKey] || {}).followingList || []));
  const acc = allAccounts.find(a => a.id === accountId);
  if (!acc) return '<div class="moments-profile-empty">找不到该账号</div>';

  // Find context persona for showing interaction info
  let contextPersona = null;
  let contextMeta = null;
  if (contextType === 'persona') {
    contextPersona = personas.find(p => String(p.id) === String(contextId));
    if (contextPersona) contextMeta = getMomentsProfileMeta('persona', contextId);
  }

  // Stats for the account
  const followerCount = _formatSocialCount(acc.followerCount || Math.floor(50 + Math.random() * 2000));
  const followingCount = _formatSocialCount(acc.followingCount || Math.floor(30 + Math.random() * 300));

  // Get cached 帖子s
  const cached = _connectedAccountCache[accountId];
  const 帖子s = (cached && cached.帖子s) ? cached.帖子s : [];
  const isLoading = !cached || cached.loading;

  const avatarSrc = acc.avatar || makeAvatar((acc.name || '?').charAt(0), acc.avatarBg || '#888', '#fff');

  // Back button: go back to persona profile or feed
  const backFn = contextType === 'persona' ? `openMomentsProfile('persona','${contextId}')` : `showMomentsFeed()`;

  const 帖子sHtml = isLoading
    ? '<div class="moments-network-loading"><i class="fas fa-circle-notch fa-spin"></i>正在生成动态…</div>'
    : 帖子s.length === 0
      ? '<div class="moments-profile-empty">这个账号还没有发布动态</div>'
      : 帖子s.map(function(帖子) { return _buildConnectedAccountPostCard(帖子, acc, contextPersona, contextMeta); }).join('');

  return `<div class="moments-ca-shell">
    <div class="moments-profile-banner" style="height:160px;">
      <div style="background:linear-gradient(135deg,${acc.avatarBg||'#888'},#2c2c2c);width:100%;height:100%;"></div>
      <div class="moments-profile-banner-overlay"></div>
      <div class="moments-profile-top-actions">
        <button onclick="${backFn}"><i class="fas fa-chevron-left"></i> 返回</button>
      </div>
      <div class="moments-profile-head">
        <div class="moments-profile-head-main">
          <div>
            <div class="moments-profile-name">${_escapeHtml(acc.name)}</div>
            <div class="moments-profile-handle">${_escapeHtml(acc.handle)}</div>
          </div>
          <img src="${avatarSrc}" onerror="this.src='${makeAvatar((acc.name||'?').charAt(0),'#888','#fff')}'">
        </div>
      </div>
    </div>
    <div class="moments-stats-bar">
      <div class="moments-stats-item">
        <div class="moments-stats-count">${followerCount}</div>
        <div class="moments-stats-label">粉丝</div>
      </div>
      <div class="moments-stats-divider"></div>
      <div class="moments-stats-item">
        <div class="moments-stats-count">${followingCount}</div>
        <div class="moments-stats-label">追踪</div>
      </div>
      <div class="moments-stats-divider"></div>
      <div class="moments-stats-item">
        <div class="moments-stats-count">${帖子s.length || '—'}</div>
        <div class="moments-stats-label">动态</div>
      </div>
    </div>
    <div class="moments-profile-signature">${_escapeHtml(acc.bio || acc.signature || '这个人没有写任何签名')}</div>
    ${contextPersona ? `<div style="padding:8px 16px 2px;background:#f5f5f5;font-size:calc(10px * var(--fs,1));color:#999;">与 <strong style="color:#555;">${_escapeHtml(contextMeta ? contextMeta.displayName : contextPersona.name)}</strong> 的关系：${_escapeHtml(acc.relationship || '好友')}</div>` : ''}
    <div class="moments-profile-feed">
      <div class="moments-section-title"><span>动态</span><span>${isLoading ? '加载中' : 帖子s.length + ' 条'}</span></div>
      ${帖子sHtml}
    </div>
  </div>`;
}

function _buildConnectedAccountPostCard(帖子, acc, contextPersona, contextMeta) {
  const avatarSrc = acc.avatar || makeAvatar((acc.name || '?').charAt(0), acc.avatarBg || '#888', '#fff');
  const personaLiked = 帖子.personaLiked && contextPersona;
  const personaComment = 帖子.personaComment && contextPersona;
  const likeCount = 帖子.likeCount || 0;
  const commentCount = (帖子.comments || []).length;

  const engagementHtml = `
    <div class="moments-ca-帖子-stats">
      <div class="moments-ca-stat-chip ${personaLiked ? 'liked' : ''}">
        <i class="fas fa-heart"></i> ${likeCount}${personaLiked ? '（含' + _escapeHtml(contextMeta ? contextMeta.displayName : contextPersona.name) + '）' : ''}
      </div>
      <div class="moments-ca-stat-chip">
        <i class="fas fa-comment"></i> ${commentCount}
      </div>
      <button class="moments-ca-forward-btn" onclick='_fwdFromConnectedAccount(${JSON.stringify({
        source:"moments", connectedAccountId: acc.id,
        contextPersonaId: contextPersona ? String(contextPersona.id) : "",
        author: acc.name, avatar: avatarSrc,
        content: 帖子.content || "", time: 帖子.time || Date.now(),
        comments: 帖子.comments || []
      }).replace(/'/g,"&#39;")})'>
        <i class="fas fa-share"></i> 转发
      </button>
    </div>`;

  const personaInteractionHtml = (personaLiked || personaComment) ? `
    <div class="moments-ca-persona-interaction">
      <div class="moments-ca-persona-interaction-label"><i class="fas fa-star" style="font-size:8px;margin-right:3px;"></i>${_escapeHtml(contextMeta ? contextMeta.displayName : contextPersona.name)} 的互动</div>
      ${personaLiked ? `<div class="moments-ca-persona-interaction-text"><i class="fas fa-heart" style="color:#e0465a;font-size:10px;"></i> 点赞了这条动态</div>` : ''}
      ${personaComment ? `<div class="moments-ca-persona-interaction-text"><i class="fas fa-comment" style="color:#4f6ef7;font-size:10px;"></i> 留言：${_escapeHtml(帖子.personaComment)}</div>` : ''}
    </div>` : '';

  const commentsHtml = (帖子.comments && 帖子.comments.length > 0)
    ? `<div class="moments-ca-comments-block">${帖子.comments.slice(0,3).map(function(c) {
        return `<div class="moments-ca-comment-row">
          <div class="moments-ca-comment-body">
            <span class="moments-ca-comment-author">${_escapeHtml(c.author)}：</span>
            <span class="moments-ca-comment-text">${_escapeHtml(c.text || c.content || '')}</span>
          </div>
        </div>`;
      }).join('')}${帖子.comments.length > 3 ? `<div style="font-size:calc(10px * var(--fs,1));color:#bbb;padding:4px 0;">还有 ${帖子.comments.length - 3} 条评论…</div>` : ''}</div>`
    : '';

  return `<div class="moments-ca-帖子-card">
    <div class="moments-ca-帖子-author">
      <img src="${avatarSrc}" onerror="this.src='${makeAvatar((acc.name||'?').charAt(0),'#888','#fff')}'">
      <div>
        <div class="moments-ca-帖子-author-name">${_escapeHtml(acc.name)}</div>
        <div class="moments-ca-帖子-author-handle">${_escapeHtml(acc.handle)}</div>
      </div>
    </div>
    <div class="moments-ca-帖子-content">${_escapeHtml(帖子.content || '')}</div>
    <div class="moments-ca-帖子-meta">${formatTime(帖子.time || Date.now())}</div>
    ${engagementHtml}
    ${personaInteractionHtml}
    ${commentsHtml}
  </div>`;
}

function _fwdFromConnectedAccount(帖子Data) {
  _fwdPayload = 帖子Data;
  openFwdPersonaModal(帖子Data);
}

// ── Async 帖子 generation for connected accounts ──────────────
async function _ensureConnectedAccount帖子(accountId, contextType, contextId) {
  if (_connectedAccountCache[accountId] && !_connectedAccountCache[accountId].loading) return;
  _connectedAccountCache[accountId] = { loading: true, 帖子s: [] };

  // Find account
  const store = _getMomentsNetworkStore();
  const storeKey = contextType + '_' + contextId;
  const allAccounts = ((store[storeKey] || {}).followersList || []).concat(((store[storeKey] || {}).followingList || []));
  const acc = allAccounts.find(a => a.id === accountId);
  if (!acc) { _connectedAccountCache[accountId] = { loading: false, 帖子s: [] }; return; }

  let contextPersona = null;
  if (contextType === 'persona') {
    contextPersona = personas.find(p => String(p.id) === String(contextId));
  }

  try {
    const 帖子s = await _aiGenerateConnectedAccount帖子(acc, contextPersona);
    _connectedAccountCache[accountId] = { loading: false, 帖子s };
    // Re-render only if we're still on this account
    if (momentsViewState.mode === 'account' && momentsViewState.accountId === accountId) {
      renderMoments();
    }
  } catch(e) {
    _connectedAccountCache[accountId] = { loading: false, 帖子s: _fallbackConnectedAccount帖子(acc, contextPersona) };
    if (momentsViewState.mode === 'account' && momentsViewState.accountId === accountId) {
      renderMoments();
    }
  }
}

async function _aiGenerateConnectedAccount帖子(acc, contextPersona) {
  const apiCfg = _getCurrentActiveApiConfig();
  if (!apiCfg.url || !apiCfg.key || !apiCfg.model) {
    return _fallbackConnectedAccount帖子(acc, contextPersona);
  }

  const personaCtxStr = contextPersona
    ? `（注意：这个账号和角色「${contextPersona.momentsNickname || contextPersona.name}」有关系：${acc.relationship || '好友'}。极少数动态（约1条）可以隐约提到或@TA，但大多数动态都是关于自己日常生活的）`
    : '';

  const prompt = `你是一个真实社交账号的动态生成器。\n账号昵称：${acc.name}，简介：${acc.bio || acc.signature || '无'}\n${personaCtxStr}\n\n请生成这个账号最近发布的8条朋友圈动态。\n动态内容要真实多样，反映日常生活（美食/天气/心情/工作/旅行/兴趣等），口语化，不要都和某个人有关。\n同时决定角色「${contextPersona ? (contextPersona.momentsNickname || contextPersona.name) : '无关联角色'}」是否对某些动态有互动（可以点赞或留言，也可以没有）。\n\n严格只返回JSON数组：\n[{\n  "content": "动态正文（30-120字，可有emoji）",\n  "time": 相对毫秒数如1735000000000,\n  "likeCount": 数字,\n  "personaLiked": true或false,\n  "personaComment": "角色的留言内容（没有则为null）",\n  "comments": [{"author":"网友名","text":"评论（10-30字）"}]\n}]\n只返回JSON，共8条，不加任何说明。`;

  const resp = await fetch(apiCfg.url.replace(/\/$/, '') + '/chat/completions', {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + apiCfg.key, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: apiCfg.model, messages: [{ role: 'user', content: prompt }], max_tokens: 1800, temperature: 0.93 })
  });
  if (!resp.ok) throw new Error('API error ' + resp.status);
  const data = await resp.json();
  const raw = (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '[]';
  const parsed = safeParseJSON(raw.replace(/```json|```/g, '').trim());
  if (!Array.isArray(parsed) || parsed.length === 0) return _fallbackConnectedAccount帖子(acc, contextPersona);

  const now = Date.now();
  return parsed.map(function(p, i) {
    return {
      id: 'ca帖子_' + acc.id + '_' + i,
      content: p.content || '今天天气真好。',
      time: p.time || (now - (parsed.length - i) * 86400000 * Math.random() * 3),
      likeCount: typeof p.likeCount === 'number' ? p.likeCount : Math.floor(Math.random() * 50),
      personaLiked: !!p.personaLiked,
      personaComment: p.personaComment || null,
      comments: Array.isArray(p.comments) ? p.comments : []
    };
  });
}

function _fallbackConnectedAccount帖子(acc, contextPersona) {
  const contentPool = [
    '今天吃了一碗超好吃的面，心满意足了。',
    '下班路上突然下雨，没带伞，整个人都湿透了。',
    '最近在追一部剧，停不下来。',
    '周末在家躺了一整天，什么都没做，很舒服。',
    '朋友介绍了一家新开的咖啡店，去了一趟，氛围很好。',
    '今天工作状态不对，什么都没做成。',
    '最近状态很好，感觉一切都在往好的方向走。',
    '又一年快过去了，有点感慨。'
  ];
  const now = Date.now();
  return contentPool.map(function(content, i) {
    return {
      id: 'ca帖子_' + acc.id + '_' + i,
      content: content,
      time: now - i * 86400000 * (0.5 + Math.random()),
      likeCount: Math.floor(Math.random() * 30),
      personaLiked: contextPersona && Math.random() < 0.25,
      personaComment: null,
      comments: []
    };
  });
}

async function deleteMoment(itemId) {
  const ok = await window.monoInAppConfirm({
    title: '删除朋友圈',
    note: '确定要删除这条朋友圈吗？',
    confirmText: '删除',
    cancelText: '取消',
    danger: true
  });
  if (!ok) return;
  const item = momentsData.find(m => m.id === itemId);
  await monoDeleteMomentImageData(item);
  momentsData = momentsData.filter(m => m.id !== itemId);
  localStorage.setItem('mono_moments', JSON.stringify(momentsData));
  renderMoments();
}
async function deleteMomentsComment(itemId, cIdx) {
  const ok = await window.monoInAppConfirm({
    title: '删除留言',
    note: '确定要删除这条留言吗？',
    confirmText: '删除',
    cancelText: '取消',
    danger: true
  });
  if (!ok) return;
  const item = momentsData.find(m => m.id === itemId);
  if (!item || !item.comments) return;
  item.comments.splice(cIdx, 1);
  localStorage.setItem('mono_moments', JSON.stringify(momentsData));
  renderMoments();
  const box = document.getElementById(`moments评论_${itemId}`);
  if (box) box.classList.add('open');
}
async function editMoment(itemId) {
  const item = momentsData.find(m => m.id === itemId);
  if (!item) return;
  const newContent = await window.monoInAppPrompt({
    title: '编辑朋友圈',
    label: '朋友圈内容',
    value: item.content,
    multiline: true,
    rows: 5,
    confirmText: '保存',
    cancelText: '取消'
  });
  if (newContent === null) return;
  const trimmed = newContent.trim();
  if (!trimmed) { alert('内容不能为空'); return; }
  item.content = trimmed;
  localStorage.setItem('mono_moments', JSON.stringify(momentsData));
  renderMoments();
}
function toggleMoments评论(itemId) {
  const box = document.getElementById(`moments评论_${itemId}`);
  const btn = document.getElementById(`cmtToggleBtn_${itemId}`);
  if (!box) return;
  const isOpen = box.classList.contains('open');
  box.classList.toggle('open');
  btn.classList.toggle('active', !isOpen);
  if (!isOpen) {
    const input = document.getElementById(`momentsCommentInput_${itemId}`);
    if (input) setTimeout(() => input.focus(), 100);
  }
}
function toggleMomentsLike(itemId) {
  const item = momentsData.find(m => m.id === itemId);
  if (!item) return;
  if (!item.likes) item.likes = [];
  const name = userProfile.name;
  const idx = item.likes.indexOf(name);
  if (idx === -1) item.likes.push(name);
  else item.likes.splice(idx, 1);
  localStorage.setItem('mono_moments', JSON.stringify(momentsData));
  renderMoments();
}
function 帖子MomentsComment(itemId) {
  const input = document.getElementById(`momentsCommentInput_${itemId}`);
  if (!input) return;
  const text = input.value.trim();
  if (!text) return;
  const item = momentsData.find(m => m.id === itemId);
  if (!item) return;
  if (!item.comments) item.comments = [];
  item.comments.push({ author: userProfile.name, content: text, time: Date.now(), replies: [] });
  localStorage.setItem('mono_moments', JSON.stringify(momentsData));
  // 用户评论后，角色可能看到并主动私聊（只针对用户自己发的朋友圈上的评论）
  if (item.authorType === 'user' && currentId) {
    const _momentWithComment = { ...item, _triggerComment: text };
    setTimeout(() => maybeProactiveDMFromMoment(_momentWithComment), 500);
  }
  const isPersonaPost = personas.some(p => p.name === item.author);
  if (isPersonaPost && apiConfig.url && apiConfig.key && apiConfig.model) {
    const persona = personas.find(p => p.name === item.author);
    if (persona) {
      setTimeout(async () => {
        const reply = await generatePersona回复ToComment(persona, item.content, userProfile.name, text, item.comments || []);
        if (reply) {
          const freshItem = momentsData.find(m => m.id === itemId);
          if (freshItem) {
            if (!freshItem.comments) freshItem.comments = [];
            const replyText = typeof reply === 'object' && reply.text ? reply.text : (typeof reply === 'string' ? reply : '');
            if (typeof reply === 'object' && reply.text) {
              freshItem.comments.push({ author: persona.name, text: reply.text, content: reply.text, translation: reply.translation, time: Date.now(), replies: [] });
            } else {
              freshItem.comments.push({ author: persona.name, content: reply, time: Date.now(), replies: [] });
            }
            localStorage.setItem('mono_moments', JSON.stringify(momentsData));
            renderMoments();
            const box = document.getElementById(`moments评论_${itemId}`);
            if (box) box.classList.add('open');
            // 写入记忆：用户评论了什么 + 角色回复了什么
            if (replyText) {
              if (!persona.memoryCore) persona.memoryCore = [];
              const now = new Date();
              const ds = now.getFullYear() + '/' + String(now.getMonth()+1).padStart(2,'0') + '/' + String(now.getDate()).padStart(2,'0');
              persona.memoryCore.push({ content: userProfile.name + '在我的朋友圈「' + (freshItem.content || '').slice(0, 30) + (freshItem.content && freshItem.content.length > 30 ? '…' : '') + '」下评论了：「' + text + '」，我回复了：「' + replyText + '」', date: ds, auto: true, source: '朋友圈' });
              if (typeof saveData === 'function') saveData();
            }
          }
        }
      }, 1000 + Math.random() * 2000);
    }
  }
  renderMoments();
  const box = document.getElementById(`moments评论_${itemId}`);
  if (box) box.classList.add('open');
}
// ── 回复特定评论（moments） ──
function openMomentsComment回复(itemId, cIdx, commentAuthor) {
  // Close any other open reply boxes first
  document.querySelectorAll('[id^="mc回复Row_"]').forEach(el => {
    if (el.id !== `mc回复Row_${itemId}_${cIdx}`) el.style.display = 'none';
  });
  const row = document.getElementById(`mc回复Row_${itemId}_${cIdx}`);
  if (!row) return;
  const isOpen = row.style.display !== 'none';
  row.style.display = isOpen ? 'none' : 'flex';
  if (!isOpen) {
    const inp = document.getElementById(`mc回复Input_${itemId}_${cIdx}`);
    if (inp) setTimeout(() => inp.focus(), 80);
  }
}
async function 帖子MomentsComment回复(itemId, cIdx, commentAuthor) {
  const inp = document.getElementById(`mc回复Input_${itemId}_${cIdx}`);
  if (!inp) return;
  const text = inp.value.trim();
  if (!text) return;
  const item = momentsData.find(m => m.id === itemId);
  if (!item || !item.comments || !item.comments[cIdx]) return;
  if (!item.comments[cIdx].replies) item.comments[cIdx].replies = [];
  item.comments[cIdx].replies.push({ author: userProfile.name, content: text, replyTo: commentAuthor, time: Date.now() });
  inp.value = '';
  document.getElementById(`mc回复Row_${itemId}_${cIdx}`).style.display = 'none';
  localStorage.setItem('mono_moments', JSON.stringify(momentsData));
  renderMoments();
  const box = document.getElementById(`moments评论_${itemId}`);
  if (box) box.classList.add('open');
  // If the comment author is a persona, trigger their auto-reply to user's reply
  if (!apiConfig.url || !apiConfig.key || !apiConfig.model) return;
  const isCommentByPersona = personas.some(p => p.name === commentAuthor);
  // Also check if the 帖子 author is a persona and it's their own 帖子, they may also reply
  const isPostByPersona = personas.some(p => p.name === item.author);
  const targetPersonaName = isCommentByPersona ? commentAuthor : (isPostByPersona ? item.author : null);
  if (!targetPersonaName) return;
  const persona = personas.find(p => p.name === targetPersonaName);
  if (!persona) return;
  // Build full thread context for this comment
  const commentObj = item.comments[cIdx];
  const all评论 = (item.comments || []).map(c => `${c.author}：${c.content || c.text || ''}`).join('\n');
  const threadReplies = (commentObj.replies || []).map(r => `${r.author}${r.replyTo ? ' 回复 ' + r.replyTo : ''}：${r.content}`).join('\n');
  setTimeout(async () => {
    try {
      const _rLang = _detectPersonaLang(persona);
      const _rLangOv = _langOverridePrompt(_rLang);
      const recentChat = persona.history ? persona.history.slice(-20).map(m => m.role === 'user' ? userProfile.name + '：' + (m.content || '') : persona.name + '：' + (m.content || '')).join('\n') : '';
      const prompt = `${LANG_SYSTEM_PREFIX}你是${persona.name}，人设：${persona.persona}。
与${userProfile.name}的近期聊天记录（供参考）：
${recentChat || '（暂无）'}
朋友圈动态内容："${item.content || ''}"
评论区所有评论：
${all评论}
本条评论（${commentAuthor}）："${commentObj.content || commentObj.text || ''}"
此评论下的回复记录：
${threadReplies || '（无）'}
${userProfile.name} 刚刚回复你（${commentAuthor}）说："${text}"${_rLangOv}
请以${persona.name}的身份，用${_rLang ? '你的语言设定' : '简体中文'}，根据你的人设性格、聊天记录、以及整个评论串的上下文，自然地回复${userProfile.name}的这条回复。20字以内，只返回回复内容本身。`;
      const r = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(_applyApiModel({ messages: [{ role: 'user', content: prompt }], temperature: persona.temperature || 1.0, max_tokens: 100 }, apiConfig.model))
      });
      if (!r.ok) return;
      const data = await r.json();
      let replyText = _extractAssistantMessageContent(data).trim().replace(/^["'「」]|["'「」]$/g, '');
      if (!replyText) return;
      let translation = '';
      if (_rLang && replyText && persona.enableTranslation !== false) {
        try {
          const _tr = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, { method: 'POST', headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' }, body: JSON.stringify(_applyApiModel({ messages: [{ role: 'user', content: '將以下文字翻譯成简体中文，只返回翻譯结果：\n' + replyText }], max_tokens: 100, temperature: 0.2 }, apiConfig.model)) });
          if (_tr.ok) { const _td = await _tr.json(); translation = _extractAssistantMessageContent(_td).trim(); }
        } catch(e) {}
      }
      const freshItem = momentsData.find(m => m.id === itemId);
      if (!freshItem || !freshItem.comments || !freshItem.comments[cIdx]) return;
      if (!freshItem.comments[cIdx].replies) freshItem.comments[cIdx].replies = [];
      freshItem.comments[cIdx].replies.push({ author: persona.name, content: replyText, replyTo: userProfile.name, time: Date.now(), translation });
      localStorage.setItem('mono_moments', JSON.stringify(momentsData));
      renderMoments();
      const box2 = document.getElementById(`moments评论_${itemId}`);
      if (box2) box2.classList.add('open');
    } catch(e) { console.warn('moments reply auto-reply err:', e.message); }
  }, 1200 + Math.random() * 2000);
}
