    const reply = _extractAssistantMessageContent(data).trim().replace(/^["']|["']$/g, '');
    // If foreign, translate (only if persona has translation enabled)
    if (_rLang && reply && persona.enableTranslation !== false) {
      try {
        const _tr = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, { method: 'POST', headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' }, body: JSON.stringify(_applyApiModel({ messages: [{ role: 'user', content: '將以下文字翻譯成简体中文，只返回翻譯结果：\n' + reply }], max_tokens: 100, temperature: 0.2 }, apiConfig.model)) });
        if (_tr.ok) { const _td = await _tr.json(); return { text: reply, translation: _extractAssistantMessageContent(_td).trim() }; }
      } catch(e) {}
    }
