// ── 用户在角色实名帖楼中楼互动 → 角色以实名身份继续回应 ──
async function _generatePersonaForum回复ToUser回复Public(sectionId, 帖子Id, commentIdx, replyIdx, targetPost, originalCommentText, commentAuthor, user回复Text) {
  try {
    const persona = personas.find(p => p.id == targetPost.personaId);
    if (!persona) {
      return _generateForum回复To回复(sectionId, 帖子Id, commentIdx, replyIdx, targetPost.title, targetPost.content, originalCommentText, commentAuthor, '', user回复Text);
    }
    _showForumCommentTyping(帖子Id, commentIdx, 'reply');
    const 帖子s = forumData[sectionId] || [];
    const tp = 帖子s.find(p => p.id === 帖子Id);
    if (!tp) { _hideForumCommentTyping(帖子Id, commentIdx, 'reply'); return; }
    const comment = tp.comments[commentIdx];
    let replyChain = '';
    if (comment && comment.replies) {
      comment.replies.slice(-6).forEach(r => {
        replyChain += `【${r.author}】回复【${r.replyTo || ''}】：${r.content}\n`;
      });
    }
    const prompt = `${LANG_SYSTEM_PREFIX}你是${persona.name}，人设：${persona.persona}。
你以自己的身份在论坛发了这个帖子，大家都知道发帖者就是你本人。
标题：${targetPost.title}
内容：${targetPost.content}
原楼评论：${commentAuthor}：${originalCommentText}
本楼回复串：
${replyChain || '（暂无）'}
现在用户「${userProfile.name}」对你说："${user回复Text}"
你要以${persona.name}本人的身份继续回复用户。
要求：
- 你知道对方就是用户「${userProfile.name}」
- 像公开论坛里的正常对话，不需要隐藏认识对方
- 符合你的人设和说话方式，20-70字
返回JSON：{"content":"回复内容"}
只返回JSON。`;
    const raw = await _forumApiFetch(prompt, 280);
    const result = safeParseJSON(raw);
    _hideForumCommentTyping(帖子Id, commentIdx, 'reply');
    if (!result || !result.content) return;
    const fp = (forumData[sectionId] || []).find(p => p.id === 帖子Id);
    if (!fp || !fp.comments[commentIdx]) return;
    if (!fp.comments[commentIdx].replies) fp.comments[commentIdx].replies = [];
    fp.comments[commentIdx].replies.push({
      id: Date.now(),
      author: persona.name,
      avatar: persona.avatar || '',
      content: result.content,
      replyTo: userProfile.name,
      time: Date.now(),
      isPersonaComment: true,
      authorType: 'persona'
    });
    _forumSyncMemoriesForPost(fp, sectionId);
    saveForumState();
    renderForum();
  } catch(e) {
    _hideForumCommentTyping(帖子Id, commentIdx, 'reply');
    console.warn('persona public reply-to-reply err:', e.message);
    _showApiErrorToast('论坛回复失败', e);
  }
}
