function toggleNovelTags() {
  const p = document.getElementById('novelTagsPanel');
  const c = document.getElementById('novelTagsChevron');
  p.classList.toggle('open');
  c.style.transform = p.classList.contains('open') ? 'rotate(180deg)' : '';
}
function _novelAddUnique(list, value) {
  const text = String(value || '').trim();
  if (!text || list.indexOf(text) !== -1) return;
  list.push(text);
}
function _novelCombinePairs(left, right, formatter) {
  const out = [];
  (left || []).forEach(function(a) {
    (right || []).forEach(function(b) {
      const text = formatter ? formatter(a, b) : (String(a || '') + String(b || ''));
      _novelAddUnique(out, text);
    });
  });
  return out;
}
function _novelFinalizeTags(list, fallbackPrefix) {
  const out = [];
  (list || []).forEach(function(item) { _novelAddUnique(out, item); });
  let idx = 1;
  while (out.length < 100) {
    _novelAddUnique(out, fallbackPrefix + idx);
    idx += 1;
  }
  return out.slice(0, 100);
}
