async function generateNextChapterNovel() {
  if (!currentNovel) return;
  const novelCategory = _novelResolveMainCategory(currentNovel);
  const saved = getNovelChapters(currentNovel.title);
  document.getElementById('nrContent').innerHTML = ''; document.getElementById('nrLoader').classList.add('active'); document.getElementById('nrBody').scrollTop = 0;
  try {
    const prompt = `${LANG_SYSTEM_PREFIX}当前小说大类：${novelCategory}。\n为小说《${currentNovel.title}》生成下一章，全部使用简体中文：\n标签：${(currentNovel.tags||[]).join('、')}\n简介：${currentNovel.description||''}\n${_novelRelationshipRules('', currentNovel.tags || [], currentNovel, novelCategory)}\n前文参考：\n${saved.chapters.join('\n\n').slice(-3000)}\n字数800-1000字，绝对不能跑去其他三大类，直接返回正文，不需标题。`;
    const content = await _novelGenerateChapterWithCategory(prompt, 2000, novelCategory);
    if (!content) { document.getElementById('nrLoader').classList.remove('active'); return; }
    saved.chapters.push(content); saved.currentIndex = saved.chapters.length - 1;
    saveNovelChapters(currentNovel.title, saved.chapters, saved.currentIndex);
    document.getElementById('nrChapterLabel').textContent = `第 ${saved.chapters.length} 章`;
    document.getElementById('nrContent').innerHTML = content.replace(/\n/g, '<br><br>');
    document.getElementById('nr评论').innerHTML = ''; generateNovel评论(currentNovel.title);
    // 自动生成新章节陪读便签（如已设定陪读角色）
    if (_companionPersonaId) { setTimeout(function(){ _triggerNovel(); }, 200); }
  } catch(e) { alert('生成失败: ' + e.message); }
  document.getElementById('nrLoader').classList.remove('active');
}
