function adjustTxtFontSize(delta) {
  txtFontSize = Math.max(12, Math.min(24, txtFontSize + delta));
  saveTxtFontSize(txtFontSize);
  document.getElementById('txtFontSizeLabel').textContent = txtFontSize + 'px';
  if (currentTxtBook) {
    renderTxtPage();
  }
}
