async function saveImportedBookInfo() {
  if (!_editingBookId) return;
  const newName = document.getElementById('editBookName').value.trim() || currentTxtBook.title;
  const imgEl = document.querySelector('#editBookCoverPreview img');
  const coverDataUrl = imgEl ? imgEl.src : null;
  const books = getImportedBooks();
  const idx = books.findIndex(b => b.id === _editingBookId);
  if (idx !== -1) {
    books[idx].title = newName;
    // coverDataUrl is stored in blob store — save it there
    if (coverDataUrl) {
      if (window._monoIdbBlobSet) await window._monoIdbBlobSet(_getCoverBlobKey(_editingBookId), coverDataUrl).catch(()=>{});
      _importedBookBlobCache[_editingBookId] = Object.assign(_importedBookBlobCache[_editingBookId] || {}, { coverDataUrl });
    }
    await saveImportedBooks(books);
  }
  if (currentTxtBook) {
    currentTxtBook.title = newName;
    if (coverDataUrl) currentTxtBook.coverDataUrl = coverDataUrl;
    document.getElementById('txtReaderTitle').textContent = newName;
  }
  closeEditBookModal(null);
  renderNovelBookshelf();
}
// ── 从书架移除导入书 ──
async function removeImportedBook(bookId) {
  const ok = await window.monoInAppConfirm({
    title: '移除导入书籍',
    note: '确定移除这本书吗？',
    confirmText: '移除',
    cancelText: '取消',
    danger: true
  });
  if (!ok) return;
  const books = getImportedBooks().filter(b => b.id !== bookId);
  await saveImportedBooks(books);
  monoPurgeKeys(['mono_imported_progress_' + bookId]);
  // 清除 IDB blob store 里的章节内容和封面
  monoPurgeBlobKeys([_getContentBlobKey(bookId), _getCoverBlobKey(bookId)]);
  // 清除内存缓存
  delete _importedBookBlobCache[bookId];
  // Also remove companion sticky caches for this book
  try {
    const cacheKey = _STICKY_CACHE_KEY;
    const histKey  = _STICKY_HIST_KEY;
    const cache = JSON.parse(localStorage.getItem(cacheKey) || '{}');
    const hist  = JSON.parse(localStorage.getItem(histKey)  || '{}');
    Object.keys(cache).forEach(k => { if (k.startsWith(bookId + '_')) delete cache[k]; });
    Object.keys(hist).forEach(k  => { if (k.startsWith(bookId + '_')) delete hist[k]; });
    localStorage.setItem(cacheKey, JSON.stringify(cache));
    localStorage.setItem(histKey,  JSON.stringify(hist));
    Object.keys(_companionCache).forEach(k => { if (k.startsWith(bookId + '_')) delete _companionCache[k]; });
    Object.keys(_companionChapHist).forEach(k => { if (k.startsWith(bookId + '_')) delete _companionChapHist[k]; });
  } catch(e) {}
  renderNovelBookshelf();
}
