// ── 商品加载 ──────────────────────────────────────────
async function loadShopProducts(category) {
  const loader = document.getElementById('shopLoader');
  const grid = document.getElementById('shopGrid');
  const title = document.querySelector('.shop-section-title');
  loader.classList.add('active'); grid.innerHTML = '';
  if (title) title.textContent = category.toUpperCase() + ' PICKS';
  const emojis = SHOP_EMOJIS[category] || ['🛍️'];
  const prompt = `${LANG_SYSTEM_PREFIX}为中文购物平台MONO SHOP生成8个${category}类商品，使用简体中文。\n每个商品包含：商品名称（有清晰商品特色）、店铺名称、价格（合理）、20字以内的商品描述、预计送达天数（3-7天）。\n严格返回JSON数组，不加说明：\n[{"name":"商品名","shopName":"店铺名","price":数字,"description":"描述","deliveryDays":数字}]`;
  try {
    const r = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: prompt }], temperature: 0.85, max_tokens: 1500 })
    });
    if (!r.ok) throw new Error('API Error');
    const data = await r.json();
    const products = safeParseJSON(data.choices[0].message.content.trim());
    grid.innerHTML = products.map((p, i) => {
      const emoji = emojis[i % emojis.length];
      return `<div class="shop-card" onclick="openShopDetail(${JSON.stringify({...p, emoji, category}).replace(/"/g,'&quot;')})">
        <div class="shop-card-cover">
          <div class="shop-card-cover-pattern"></div>
          <span style="position:relative;z-index:1;font-size:32px;">${emoji}</span>
        </div>
        <div class="shop-card-body">
          <div class="shop-card-name">${p.name}</div>
          <div class="shop-card-shop">${p.shopName}</div>
          <div class="shop-card-price">¥${p.price}<span> / ${p.deliveryDays}天送达</span></div>
        </div>
      </div>`;
    }).join('');
  } catch(e) {
    grid.innerHTML = `<div style="grid-column:span 2;text-align:center;padding:20px;font-size:12px;color:#888;">请先配置API以生成商品</div>`;
  }
  loader.classList.remove('active');
}
function setShopCat(el, cat) {
  document.querySelectorAll('.shop-cat-btn').forEach(b => b.classList.remove('active'));
  el.classList.add('active');
  shopCurrentCat = cat;
  loadShopProducts(cat);
}
