// ══════════════════════════════════════════════════════════
// 聊天系统文字颜色（时间/名字/已读未读）Meta Text Colors
// ══════════════════════════════════════════════════════════
function _getMetaColorStyleTag() {
  let el = document.getElementById('_chatMetaColorStyle');
  if (!el) { el = document.createElement('style'); el.id = '_chatMetaColorStyle'; document.head.appendChild(el); }
  return el;
}
function applyMetaColors(p) {
  const timeColor   = (p && p.metaTimeColor)   || '';
  const nameColor   = (p && p.metaNameColor)   || '';
  const readColor   = (p && p.metaReadColor)   || '';
  const unreadColor = (p && p.metaUnreadColor) || '';
  const el = _getMetaColorStyleTag();
  let css = '';
  if (timeColor)   css += ':root { --chat-meta-time-color: ' + timeColor + '; }\n';
  else              css += ':root { --chat-meta-time-color: #bbb; }\n';
  // Hide timestamp if enabled
  if (p && p.hideTimestamp) css += '.msg-time-read { display: none !important; }\n';
  else css += '.msg-time-read { display: flex !important; }\n';
  if (nameColor)   css += ':root { --chat-meta-name-color: ' + nameColor + '; }\n';
  else              css += ':root { --chat-meta-name-color: #999; }\n';
  // read/unread applied via inline data-read-color attr and JS patch below
  el.textContent = css;
  // patch read/unread color on rendered messages via CSS vars
  const rootStyle = document.documentElement.style;
  rootStyle.setProperty('--chat-meta-read-color',   readColor   || '#aaa');
  rootStyle.setProperty('--chat-meta-unread-color', unreadColor || '#ccc');
}
function livePreviewMetaColors() {
  const p = {
    metaTimeColor:   (document.getElementById('pMetaTimeColor')   || {}).value || '',
    metaNameColor:   (document.getElementById('pMetaNameColor')   || {}).value || '',
    metaReadColor:   (document.getElementById('pMetaReadColor')   || {}).value || '',
    metaUnreadColor: (document.getElementById('pMetaUnreadColor') || {}).value || '',
  };
  applyMetaColors(p);
  // Live patch existing rendered read/unread spans
  document.querySelectorAll('.msg-time-read span:last-child').forEach(function(span) {
    var txt = span.textContent;
    if (txt === '已读') span.style.color = p.metaReadColor || '#aaa';
    else if (txt === '未读') span.style.color = p.metaUnreadColor || '#ccc';
  });
}
function resetMetaColors() {
  var defaults = { metaTimeColor: '#bbbbbb', metaNameColor: '#999999', metaReadColor: '#aaaaaa', metaUnreadColor: '#cccccc' };
  var el;
  el = document.getElementById('pMetaTimeColor');   if (el) el.value = defaults.metaTimeColor;
  el = document.getElementById('pMetaNameColor');   if (el) el.value = defaults.metaNameColor;
  el = document.getElementById('pMetaReadColor');   if (el) el.value = defaults.metaReadColor;
  el = document.getElementById('pMetaUnreadColor'); if (el) el.value = defaults.metaUnreadColor;
  applyMetaColors(defaults);
  var p = personas.find(function(x){ return x.id == currentId; });
  if (p) { p.metaTimeColor = ''; p.metaNameColor = ''; p.metaReadColor = ''; p.metaUnreadColor = ''; saveData(); }
}
// ══════════════════════════════════════════════════════════
// 每个聊天室完整自定义 CSS — Per-Room Full Custom CSS
// ══════════════════════════════════════════════════════════
function _getRoomCssStyleTag(id) {
  id = id || '_roomCustomCssStyle';
  let el = document.getElementById(id);
  if (!el) { el = document.createElement('style'); el.id = id; document.head.appendChild(el); }
  return el;
}
function _roomCssSelectorNeedsGlobalScope(selector) {
  const s = String(selector || '').trim();
  return /^(html|body|:root)\b/i.test(s) || /^\.phone-nav\b/.test(s) || /^#(?:chatPage|groupChatPage)\b/.test(s);
}
function _roomCssScopeSelector(selector, scopeRoot) {
  const s = String(selector || '').trim();
  if (!s) return '';
  if (_roomCssSelectorNeedsGlobalScope(s)) return s;
  return scopeRoot + ' ' + s;
}
function _roomCssForceImportant(body) {
  return String(body || '').replace(/([a-zA-Z_-][\w-]*)\s*:\s*([^;{}]+)(;?)/g, function(match, prop, value, semi) {
    if (String(prop || '').indexOf('--') === 0) return match;
    if (/!important\s*$/i.test(value)) return prop + ': ' + value.trim() + (semi || '');
    return prop + ': ' + value.trim() + ' !important' + (semi || '');
  });
}
function _compileScopedRoomCustomCss(rawCss, scopeRoot) {
  const raw = String(rawCss || '').replace(/\/\*[\s\S]*?\*\//g, '').trim();
  if (!raw) return '';
  return raw.replace(/(^|})(\s*)([^@{}][^{}]*)\{([^{}]*)\}/g, function(match, closeBrace, ws, selectorText, body) {
    const selectors = String(selectorText || '')
      .split(',')
      .map(function(sel) { return _roomCssScopeSelector(sel, scopeRoot); })
      .filter(Boolean);
    if (!selectors.length) return match;
    return (closeBrace || '') + (ws || '') + selectors.join(', ') + ' { ' + _roomCssForceImportant(body).trim() + ' }';
  });
}
function _getCompiledRoomCss(rawCss, scopeRoot) {
  const compiled = _compileScopedRoomCustomCss(rawCss, scopeRoot);
  if (!compiled) return '';
  return '/* room-custom-css: compiled for strong override */\n' + compiled;
}
function removeChatRoomCustomCss() {
  const e = document.getElementById('_roomCustomCssStyle'); if (e) e.textContent = '';
  const g = document.getElementById('_gcRoomCustomCssStyle'); if (g) g.textContent = '';
}
function applyChatRoomCustomCss(p) {
  const el = _getRoomCssStyleTag('_roomCustomCssStyle');
  el.textContent = (p && p.chatRoomCustomCss) ? _getCompiledRoomCss(p.chatRoomCustomCss, '#chatPage') : '';
  // Also clear group room CSS when switching to 1-on-1
  const g = document.getElementById('_gcRoomCustomCssStyle'); if (g) g.textContent = '';
}
function applyGcRoomCustomCss(group) {
  const el = _getRoomCssStyleTag('_gcRoomCustomCssStyle');
  el.textContent = (group && group.chatRoomCustomCss) ? _getCompiledRoomCss(group.chatRoomCustomCss, '#groupChatPage') : '';
  // Also clear persona room CSS when switching to group chat
  const p = document.getElementById('_roomCustomCssStyle'); if (p) p.textContent = '';
}
function livePreviewRoomCss() {
  const css = (document.getElementById('pRoomCustomCss') || {}).value || '';
  _getRoomCssStyleTag('_roomCustomCssStyle').textContent = _getCompiledRoomCss(css, '#chatPage');
}
function saveRoomCss() {
  const css = (document.getElementById('pRoomCustomCss') || {}).value || '';
  livePreviewRoomCss();
  const p = personas.find(x => x.id == currentId);
  if (p) { p.chatRoomCustomCss = css; saveData(); }
  const status = document.getElementById('roomCssStatus');
  if (status) { status.style.display = 'block'; status.textContent = '✓ 已应用并保存！'; setTimeout(() => { status.style.display = 'none'; }, 2500); }
}
function resetRoomCss() {
  if (!confirm('确定要重置此聊天室的自定义 CSS 吗？')) return;
  const editor = document.getElementById('pRoomCustomCss');
  if (editor) editor.value = '';
  _getRoomCssStyleTag('_roomCustomCssStyle').textContent = '';
  const p = personas.find(x => x.id == currentId);
  if (p) { p.chatRoomCustomCss = ''; saveData(); }
  const status = document.getElementById('roomCssStatus');
  if (status) { status.style.display = 'block'; status.textContent = '已重置。'; setTimeout(() => { status.style.display = 'none'; }, 2000); }
}
// Group chat room CSS live preview/reset
function livePreviewGcRoomCss() {
  const css = (document.getElementById('gcRoomCustomCss') || {}).value || '';
  _getRoomCssStyleTag('_gcRoomCustomCssStyle').textContent = _getCompiledRoomCss(css, '#groupChatPage');
}
function resetGcRoomCss() {
  if (!confirm('确定要重置此群聊室的自定义 CSS 吗？')) return;
  const editor = document.getElementById('gcRoomCustomCss');
  if (editor) editor.value = '';
  _getRoomCssStyleTag('_gcRoomCustomCssStyle').textContent = '';
}
// ══════════════════════════════════════════
// BUBBLE PRESET SYSTEM
// ══════════════════════════════════════════
var _BUBBLE_PRESET_CLASSES = ['bubble-preset-wechat', 'bubble-preset-imessage', 'bubble-preset-line', 'bubble-preset-retro', 'bubble-preset-oshiglow', 'bubble-preset-journal'];
var _CHAT_THEME_CLASSES = ['chat-theme-frosted'];
function normalizeBubblePreset(preset) {
  preset = preset || 'none';
  return _BUBBLE_PRESET_CLASSES.indexOf('bubble-preset-' + preset) === -1 ? 'none' : preset;
}
function normalizeChatTheme(theme) {
  return theme === 'frosted' ? 'frosted' : 'default';
}
function toggleFrostedTitleColorControl(theme) {
  theme = normalizeChatTheme(theme);
  var wrap = document.getElementById('frostedTitleColorWrap');
  if (wrap) wrap.style.display = theme === 'frosted' ? 'block' : 'none';
}
function applyFrostedMessageMetaVisibility(p) {
  try {
    var chatPage = document.getElementById('chatPage');
    if (!chatPage) return;
    var theme = getEffectiveChatTheme(p);
    var hide = !!(p && p.frostedHideMessageMeta);
    chatPage.classList.toggle('frosted-hide-message-meta', theme === 'frosted' && hide);
  } catch (e) {}
}
function migrateLegacyFrostedThemeIfNeeded(p) {
  try {
    if (p && !p.chatTheme && p.bubblePreset === 'frosted') {
      p.chatTheme = 'frosted';
      p.bubblePreset = 'none';
      return true;
    }
  } catch (e) {}
  return false;
}
function getEffectiveChatTheme(p) {
  if (!p) return 'default';
  if (p.chatTheme) return normalizeChatTheme(p.chatTheme);
  return p.bubblePreset === 'frosted' ? 'frosted' : 'default';
}
function syncFrostedComposerState() {
  try {
    var chatPage = document.getElementById('chatPage');
    var input = document.getElementById('userInput');
    if (!chatPage || !input) return;
    chatPage.classList.toggle('frosted-has-text', !!String(input.value || '').trim());
  } catch (e) {}
}
function bindFrostedComposerState() {
  try {
    var input = document.getElementById('userInput');
    if (!input || input.dataset.frostedStateBound === '1') {
      syncFrostedComposerState();
      return;
    }
    input.addEventListener('input', syncFrostedComposerState);
    input.addEventListener('change', syncFrostedComposerState);
    input.addEventListener('keydown', function(e) {
      if (e.key === 'Enter') setTimeout(syncFrostedComposerState, 0);
    });
    document.addEventListener('click', function(e) {
      if (e.target && e.target.closest && e.target.closest('.chat-send-btn')) {
        setTimeout(syncFrostedComposerState, 80);
      }
    }, true);
    input.dataset.frostedStateBound = '1';
    syncFrostedComposerState();
  } catch (e) {}
}
function applyChatThemeClass(theme) {
  try {
    theme = normalizeChatTheme(theme);
    var chatPage = document.getElementById('chatPage');
    var drawer = document.getElementById('contactsDrawer');
    var menuBtn = document.getElementById('menuBtn');
    [chatPage, drawer, menuBtn].forEach(function(el) {
      if (!el) return;
      _CHAT_THEME_CLASSES.forEach(function(cls) { el.classList.remove(cls); });
      if (theme === 'frosted') el.classList.add('chat-theme-frosted');
    });
    document.body.classList.toggle('chat-theme-frosted-active', theme === 'frosted');
    if (theme !== 'frosted' && chatPage) chatPage.classList.remove('frosted-hide-message-meta');
    if (typeof updateMonoViewportMetrics === 'function') updateMonoViewportMetrics();
    syncFrostedComposerState();
  } catch (e) {}
}
function selectChatTheme(theme) {
  theme = normalizeChatTheme(theme);
  document.querySelectorAll('.chat-theme-option').forEach(function(el) {
    el.style.borderColor = '#ddd';
    el.style.boxShadow = 'none';
  });
  var opt = document.getElementById('ctOpt-' + theme);
  if (opt) {
    opt.style.borderColor = '#1a1a1a';
    opt.style.boxShadow = '0 0 0 1px #1a1a1a';
  }
  var hi = document.getElementById('pChatTheme');
  if (hi) hi.value = theme;
  toggleFrostedTitleColorControl(theme);
  applyChatThemeClass(theme);
  livePreviewBubble();
  var p = personas.find(function(x){ return x.id == currentId; });
  if (p) {
    p.chatTheme = theme;
    if (p.bubblePreset === 'frosted') p.bubblePreset = 'none';
    saveData();
  }
}
function loadChatThemeUI(theme) {
  theme = normalizeChatTheme(theme);
  document.querySelectorAll('.chat-theme-option').forEach(function(el) {
    el.style.borderColor = '#ddd';
    el.style.boxShadow = 'none';
  });
  var opt = document.getElementById('ctOpt-' + theme);
  if (opt) {
    opt.style.borderColor = '#1a1a1a';
    opt.style.boxShadow = '0 0 0 1px #1a1a1a';
  }
  var hi = document.getElementById('pChatTheme');
  if (hi) hi.value = theme;
  toggleFrostedTitleColorControl(theme);
}
function updateMonoViewportMetrics() {
  try {
    var root = document.documentElement;
    /* Restored old-version keyboard behavior:
       do NOT use visualViewport.height to shrink the whole app when the keyboard opens. */
    root.style.setProperty('--mono-app-vh', '1vh');
    root.style.setProperty('--mono-keyboard-offset', '0px');
    var chatPage = document.getElementById('chatPage');
    if (chatPage && chatPage.parentElement) {
      var hostHeight = chatPage.parentElement.clientHeight || 0;
      var chatTop = chatPage.offsetTop || 0;
      var chatHeight = Math.max(0, hostHeight - chatTop);
      if (chatHeight > 0) root.style.setProperty('--mono-chat-page-h', chatHeight + 'px');
    }
  } catch (e) {}
}
function bindMonoViewportMetrics() {
  try {
    if (window.__monoViewportMetricsBound) {
      updateMonoViewportMetrics();
      return;
    }
    window.__monoViewportMetricsBound = true;
    updateMonoViewportMetrics();
    window.addEventListener('resize', updateMonoViewportMetrics, { passive: true });
    window.addEventListener('orientationchange', function() {
      setTimeout(updateMonoViewportMetrics, 120);
    }, { passive: true });
  } catch (e) {}
}
function applyBubblePresetClass(preset) {
  preset = normalizeBubblePreset(preset);
  var targets = [document.getElementById('chatPage'), document.getElementById('groupChatPage'), document.getElementById('datingChatPage')].filter(Boolean);
  targets.forEach(function(el) {
    _BUBBLE_PRESET_CLASSES.forEach(function(cls) { el.classList.remove(cls); });
    if (preset && preset !== 'none') { el.classList.add('bubble-preset-' + preset); }
  });
  try { document.body.classList.toggle('chat-preset-frosted-active', preset === 'frosted'); } catch (e) {}
  syncFrostedComposerState();
}
function selectBubblePreset(preset) {
  preset = normalizeBubblePreset(preset);
  // Update UI selection
  document.querySelectorAll('.bubble-preset-option').forEach(function(el) {
    el.style.borderColor = '#ddd';
    el.style.boxShadow = 'none';
  });
  var opt = document.getElementById('bpOpt-' + preset);
  if (opt) { opt.style.borderColor = '#1a1a1a'; opt.style.boxShadow = '0 0 0 1px #1a1a1a'; }
  // Store in hidden input
  var hi = document.getElementById('pBubblePreset');
  if (hi) hi.value = preset;
  // Apply to chat pages
  applyBubblePresetClass(preset);
  // Persist to current persona
  var p = personas.find(function(x){ return x.id == currentId; });
  if (p) { p.bubblePreset = preset; saveData(); }
  // Also re-apply custom CSS on top
  livePreviewBubble();
}
function loadBubblePresetUI(preset) {
  preset = normalizeBubblePreset(preset);
  document.querySelectorAll('.bubble-preset-option').forEach(function(el) {
    el.style.borderColor = '#ddd';
    el.style.boxShadow = 'none';
  });
  var opt = document.getElementById('bpOpt-' + preset);
  if (opt) { opt.style.borderColor = '#1a1a1a'; opt.style.boxShadow = '0 0 0 1px #1a1a1a'; }
  if (preset === 'none') {
    var defOpt = document.getElementById('bpOpt-none');
    if (defOpt) { defOpt.style.borderColor = '#1a1a1a'; defOpt.style.boxShadow = '0 0 0 1px #1a1a1a'; }
  }
  var hi = document.getElementById('pBubblePreset');
  if (hi) hi.value = preset;
}
(function initFrostedComposerStateBinding() {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindFrostedComposerState, { once: true });
  } else {
    bindFrostedComposerState();
  }
})();
(function initMonoViewportMetricsBinding() {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', bindMonoViewportMetrics, { once: true });
  } else {
    bindMonoViewportMetrics();
  }
})();
// ===================== NEW: Custom Chat Background =====================
function openChatBgEditor() {
  if (!currentId) return;
  openEditor(true);
  setTimeout(() => {
    const el = document.getElementById('pChatBgPreview');
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, 300);
}
function handleChatBgSelect(input) {
  if (input.files && input.files[0]) {
    const file = input.files[0];
    const reader = new FileReader();
    reader.onload = async function(e) {
      let compressed = e.target.result;
      try { compressed = await compressImage(e.target.result, 1200, 0.82); } catch(err) { compressed = e.target.result; }
      const imgEl = document.getElementById('pChatBgImg');
      if (imgEl) {
        imgEl.src = compressed;
        imgEl.style.display = 'block';
      }
      const ph = document.getElementById('pChatBgPlaceholder');
      if (ph) ph.style.display = 'none';
      const p = personas.find(x => x.id == currentId);
      if (p) {
        p.chatBgImage = compressed;
        applyChatBackground(p);
        saveData();
      }
      if (input) input.value = '';
    };
    reader.readAsDataURL(file);
  }
}
function resetChatBg() {
  document.getElementById('pChatBgImg').src = '';
  document.getElementById('pChatBgImg').style.display = 'none';
  document.getElementById('pChatBgPlaceholder').style.display = '';
  const p = personas.find(x => x.id == currentId);
  if (p) { p.chatBgImage = ''; applyChatBackground(p); saveData(); }
  alert('\u804a\u5929\u5ba4\u80cc\u666f\u5df2\u91cd\u7f6e\u70ba\u9810\u8a2d\uff01');
}
function monoCssUrl(value) {
  value = String(value || '');
  return 'url("' + value.replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n|\r/g, '') + '")';
}
function applyChatBackground(p) {
  const chatBox = document.getElementById('chatBox');
  const chatPage = document.getElementById('chatPage');
  if (!chatBox) return;
  // chatBgImage may be stored separately (as '__ref__') or inline.
  // Read through localStorage proxy so multi-world + IndexedDB cache both work.
  const bg = p && (p.chatBgImage === '__ref__'
    ? localStorage.getItem('mono_bg_' + p.id) || ''
    : (p.chatBgImage || ''));
  const cssBg = bg ? monoCssUrl(bg) : '';
  if (chatPage) {
    chatPage.classList.toggle('mono-has-custom-bg', !!bg);
    if (bg) chatPage.style.setProperty('--mono-chat-bg-image', cssBg);
    else chatPage.style.removeProperty('--mono-chat-bg-image');
  }
  if (bg) {
    chatBox.style.setProperty('background-image', cssBg, 'important');
    chatBox.style.setProperty('background-size', 'cover', 'important');
    chatBox.style.setProperty('background-position', 'center center', 'important');
    chatBox.style.setProperty('background-repeat', 'no-repeat', 'important');
  } else {
    chatBox.style.removeProperty('background-image');
    chatBox.style.removeProperty('background-size');
    chatBox.style.removeProperty('background-position');
    chatBox.style.removeProperty('background-repeat');
  }
}
