  if (!family) { alert('\u8acb\u8f38\u5165\u5b57\u9ad4\u540d\u7a31 (font-family)'); return; }
  const fontSettings = { url: url, family: family, fontData: _customFontData || '', fontSize: fontSize };
  localStorage.setItem('mono_custom_font', JSON.stringify(fontSettings));
  loadAndApplyCustomFont(fontSettings);
  alert('\u5b57\u9ad4\u5df2\u61c9\u7528\u4e26\u4fdd\u5b58\uff01');
