// ── 从消息中提取明确提到的金额 ──
function extractMentionedAmount(text) {
  // 各种金额格式：含动词+数字、¥符号、数字+单位
  const patterns = [
    /[给给转转打发发借还还賠赔]\s*我?\s*(\d+(?:\.\d+)?)\s*[万万]?\s*[元块块圆圆kK]?/,
    /[¥￥]\s*(\d+(?:\.\d+)?)/,
    /(\d+(?:\.\d+)?)\s*[万万]\s*[元块块圆圆]?/,
    /(\d+(?:\.\d+)?)\s*[元块块圆圆kK]/,
  ];
  for (const pat of patterns) {
    const m = text.match(pat);
    if (m) {
      const n = parseFloat(m[1]);
      if (!isNaN(n) && n > 0) {
        const hasWan = /万|万/.test(m[0]);
        return hasWan ? n * 10000 : n;
      }
    }
  }
  return null;
}
// ── 用户发消息后：侦测是否有转账意图 ──
async function checkUserTransferIntent(text, p) {
  const hasKeyword = TRANSFER_KEYWORDS.some(kw => text.includes(kw));
  const detectedAmt = extractMentionedAmount(text);
  // 有金额+转账相关字符也触发
  const amountWithContext = detectedAmt && /[给给你我转转打发发借还还賠赔块块元钱钱]/u.test(text);
  if (!hasKeyword && !amountWithContext) return;
  await new Promise(res => setTimeout(res, 1200 + Math.random() * 1000));
  if (!apiConfig.url || !apiConfig.key || !apiConfig.model) {
    // 无 API：直接用侦测金额或随机金额转账
    const amt = detectedAmt || parseFloat((Math.random() * 9990 + 10).toFixed(2));
    p.history.push({ role: 'assistant', msgType: 'transfer', transferAmt: amt, transferNote: '', transferStatus: 'pending', content: '[角色转账: ¥' + amt.toFixed(2) + ']' });
    saveData();
    if (currentId == p.id) renderMessages();
    return;
  }
  const recentChat = p.history.slice(-(p.memoryCount||100)).map(m => `${m.role==='user'?userProfile.name:p.name}：${m.content||''}`).join('\n');
  // 如果侦测到具体金额，强制使用；否则由 AI 自由决定
  const amtInstruction = detectedAmt
    ? `用户消息中明确提到了金额 ¥${detectedAmt}，你必须转账这个金额。`
    : `根据你的人设、角色背景和情境自由决定金额（无上限，完全符合角色身份）。`;
  const prompt = `${LANG_SYSTEM_PREFIX}你是${p.name}，人设：${p.persona}。\n${userProfile.name}向你请求转账，消息是："${text}"。\n你决定转账给对方。${amtInstruction}\n${(()=>{const _tl=_detectPersonaLang(p);const _nt=!!(_tl&&_tl!=='zh'&&_tl!=='zh-cn');return _nt?`你必须用符合你人设的语气以你的母语（${_tl}）写一条便簽（10-30字，不可为空，有个性和情感），并在 note_translation 字段附简体中文翻译。\n只返回JSON，不加任何说明：{"amount": 数字, "note": "便簽原文（必填）", "note_translation": "简体中文翻译（必填）"}`:'你必须用符合你人设的语气写一条便簽（10-30字，不可为空，有个性和情感，像角色本人说话）。\n只返回JSON，不加任何说明：{"amount": 数字, "note": "便簽（必填）"}';})()}\n\n【最近聊天】\n${recentChat}`;
  try {
    const r = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: prompt }], temperature: p.temperature || 1.0, max_tokens: 100 })
    });
    if (!r.ok) throw new Error('api error');
    const data = await r.json();
    let raw = data.choices[0].message.content.trim().replace(/```json|```/g, '').trim();
    const result = JSON.parse(raw);
    const amt = parseFloat(result.amount);
    if (!isNaN(amt) && amt > 0) {
      await new Promise(res => setTimeout(res, 500 + Math.random() * 600));
      p.history.push({ role: 'assistant', msgType: 'transfer', transferAmt: amt, transferNote: result.note || '', transferNoteTranslation: result.note_translation || '', transferStatus: 'pending', content: '[角色转账: ¥' + amt.toFixed(2) + ']' });
      saveData();
      if (currentId == p.id) renderMessages();
    }
  } catch(e) {
    const amt = detectedAmt || parseFloat((Math.random() * 9990 + 10).toFixed(2));
    p.history.push({ role: 'assistant', msgType: 'transfer', transferAmt: amt, transferNote: '', transferStatus: 'pending', content: '[角色转账: ¥' + amt.toFixed(2) + ']' });
    saveData();
    if (currentId == p.id) renderMessages();
  }
}
