function monoSlimChatHistoryForStorage(personaId, history) {
  return (Array.isArray(history) ? history : []).map(function(msg) {
    if (!msg || typeof msg !== 'object') return msg;
    if (msg.msgType !== 'image') return msg;
    const copy = Object.assign({}, msg);
    if (!copy._monoChatImageBlobKey && /^data:image\//i.test(String(copy.imageSrc || ''))) {
      copy._monoChatImageBlobKey = monoChatImageBlobKey(personaId, copy);
    }
    if (copy._monoChatImageBlobKey) {
      delete copy.imageSrc;
    }
    return copy;
  });
}
async function monoPersistChatHistoryImages(personaId, history) {
  if (!window._monoIdbBlobSet) return false;
  const list = Array.isArray(history) ? history : [];
  let changed = false;
  for (let i = 0; i < list.length; i++) {
    const msg = list[i];
    if (!msg || msg.msgType !== 'image') continue;
    const src = String(msg.imageSrc || '').trim();
    if (!/^data:image\//i.test(src)) continue;
    if (!msg._monoChatImageBlobKey) msg._monoChatImageBlobKey = monoChatImageBlobKey(personaId, msg);
    try {
      await window._monoIdbBlobSet(msg._monoChatImageBlobKey, src);
      changed = true;
    } catch(e) {}
  }
  return changed;
}
function monoSchedulePersistChatHistoryImages(personaId, history) {
  if (!personaId || !Array.isArray(history) || !history.length) return;
  const pid = String(personaId);
  window.__monoChatImagePersistJobs = window.__monoChatImagePersistJobs || {};
  if (window.__monoChatImagePersistJobs[pid]) return;
  window.__monoChatImagePersistJobs[pid] = 1;
  Promise.resolve().then(async function() {
    try {
      await monoPersistChatHistoryImages(pid, history);
      try { localStorage.setItem('mono_hist_' + pid, JSON.stringify(monoSlimChatHistoryForStorage(pid, history))); } catch(e) {}
    } finally {
      delete window.__monoChatImagePersistJobs[pid];
    }
  });
}
function monoScheduleHydrateVisibleChatImages(personaId, history, limit) {
  if (!window._monoIdbBlobGet || !Array.isArray(history) || !history.length) return;
  const pid = String(personaId || '');
  if (!pid) return;
  window.__monoChatImageHydrateJobs = window.__monoChatImageHydrateJobs || {};
  if (window.__monoChatImageHydrateJobs[pid]) return;
  const maxCount = Math.max(1, Number(limit) || 8);
  const targets = history.filter(function(msg) {
    return msg && msg.msgType === 'image' && !msg.imageSrc && msg._monoChatImageBlobKey;
  }).slice(-maxCount);
  if (!targets.length) return;
  window.__monoChatImageHydrateJobs[pid] = 1;
  Promise.resolve().then(async function() {
    let changed = false;
    try {
      for (const msg of targets) {
        try {
          const data = await window._monoIdbBlobGet(msg._monoChatImageBlobKey);
          if (data) {
            msg.imageSrc = data;
            changed = true;
          }
        } catch(e) {}
      }
      if (changed && String(currentId || '') === pid) {
        try { renderMessages({ fast: true }); } catch(e) {}
      }
    } finally {
      delete window.__monoChatImageHydrateJobs[pid];
    }
  });
}
