    imageCaption: String(meta.imageCaption || '').trim(),
    imageDesc: String(meta.imageDesc || '').trim(),
    imageSimulated: !!meta.imageSimulated,
    textImagePrompt: String(meta.textImagePrompt || meta.imageDesc || '').trim(),
    imageUiDescHidden: !!meta.imageUiDescHidden,
