  const desc = hideDesc ? '' : (String(m.imageDesc || m.content || '').trim() || (m.role === 'assistant' ? '[你发送了一张图片]' : '[用户发送了一张图片]'));
  const caption = String(m.imageCaption || '').trim();
  const base = m.role === 'assistant'
    ? (hideDesc ? '[你发送了一张图片]' : '[你发送了一张图片：' + desc + ']')
    : (hideDesc ? '[用户发送了一张图片]' : '[用户发送了一张图片：' + desc + ']');
  if (m.role !== 'user') return caption ? (base + '（图片配文：' + caption + '）') : base;
  const prevMsg = arr && arr[idx - 1];
  const prevText = (prevMsg && prevMsg.role === 'user' && !prevMsg.msgType && prevMsg.content) ? prevMsg.content : '';
  const nextMsg = arr && arr[idx + 1];
  const nextText = (nextMsg && nextMsg.role === 'user' && !nextMsg.msgType && nextMsg.content) ? nextMsg.content : '';
  let contextHint = '';
  if (prevText) contextHint += `（前文：用户刚说了"${prevText}"）`;
  if (nextText) contextHint += `（后续：用户接着说了"${nextText}"）`;
