function batchStickerAddFromAlbum() {
  const remaining = 10 - _batchStickerSlots.length;
  if (remaining <= 0) { alert('最多添加10个表情包'); return; }
  document.getElementById('batchStickerFileInput').click();
}
function batchStickerToggleUrlInput() {
  const area = document.getElementById('batchStickerUrlArea');
  area.style.display = area.style.display === 'none' ? 'block' : 'none';
}
async function handleBatchStickerFiles(input) {
  if (!input.files || input.files.length === 0) return;
  const remaining = 10 - _batchStickerSlots.length;
  const files = Array.from(input.files).slice(0, remaining);
  for (const file of files) {
    if (_batchStickerSlots.length >= 10) break;
    const base64 = await new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = async (e) => {
        const compressed = await compressImage(e.target.result, 400, 0.82);
        resolve(compressed);
      };
      reader.readAsDataURL(file);
    });
    _batchStickerSlots.push({ src: base64, desc: '', status: 'pending', isUrl: false });
  }
  renderBatchStickerSlots();
  input.value = '';
  // Auto-describe if vision API is configured
  if (isVisionApiConfigured()) {
    autoBatchDescribe();
  }
}
function batchStickerAddUrl() {
  if (_batchStickerSlots.length >= 10) { alert('最多添加10个表情包'); return; }
  const urlInput = document.getElementById('batchStickerUrlInput');
  const url = urlInput.value.trim();
  if (!url) return;
  if (!url.match(/^https?:\/\//i)) { alert('请输入有效的URL'); return; }
  _batchStickerSlots.push({ src: url, desc: '', status: 'pending', isUrl: true });
  urlInput.value = '';
  renderBatchStickerSlots();
  // Auto-describe if vision API is configured
  if (isVisionApiConfigured()) {
    autoBatchDescribeByIndex(_batchStickerSlots.length - 1);
  }
}
function removeBatchStickerSlot(idx) {
  _batchStickerSlots.splice(idx, 1);
  renderBatchStickerSlots();
}
function renderBatchStickerSlots() {
  const container = document.getElementById('batchStickerSlots');
  if (_batchStickerSlots.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:30px;color:#ccc;font-size:10px;text-transform:uppercase;letter-spacing:1px;">点击上方按钮添加表情包<br>最多可同时添加10个</div>';
    return;
  }
  container.innerHTML = _batchStickerSlots.map((slot, i) => {
    const statusClass = slot.status === 'success' ? 'success' : slot.status === 'error' ? 'error' : slot.status === 'loading' ? 'loading' : '';
    const statusText = slot.status === 'success' ? '✓ 已识别' : slot.status === 'error' ? '✗ 识别失败' : slot.status === 'loading' ? '识别中...' : '待识别';
    const descPreview = slot.desc ? slot.desc.slice(0, 30) + (slot.desc.length > 30 ? '...' : '') : '';
    return '<div class="batch-sticker-slot">' +
      '<div class="slot-preview"><img src="' + slot.src + '" alt="sticker" onerror="this.style.display=\'none\'"></div>' +
      '<div class="slot-info">' +
        '<div style="font-size:10px;font-weight:700;">#' + (i+1) + (descPreview ? ' · ' + descPreview : '') + '</div>' +
        '<div class="slot-status ' + statusClass + '">' + statusText + '</div>' +
      '</div>' +
      '<span class="slot-remove" onclick="removeBatchStickerSlot(' + i + ')"><i class="fas fa-times"></i></span>' +
    '</div>';
  }).join('');
}
async function autoBatchDescribe() {
  for (let i = 0; i < _batchStickerSlots.length; i++) {
    if (_batchStickerSlots[i].status === 'pending') {
      await autoBatchDescribeByIndex(i);
    }
  }
}
async function autoBatchDescribeByIndex(idx) {
  if (idx >= _batchStickerSlots.length) return;
  const slot = _batchStickerSlots[idx];
  if (slot.status !== 'pending') return;
  slot.status = 'loading';
  renderBatchStickerSlots();
  document.getElementById('batchStickerProgress').style.display = 'block';
  document.getElementById('batchStickerProgressText').textContent = '正在识别第 ' + (idx+1) + '/' + _batchStickerSlots.length + ' 张图片...';
  try {
    let imgData = slot.src;
    // If it's a URL, we need to convert to base64 first for the API
    if (slot.isUrl) {
      try {
        imgData = await urlToBase64(slot.src);
      } catch(e) {
        // If can't convert, try sending URL directly
        imgData = slot.src;
      }
    }
    const desc = await describeImageWithVisionApi(imgData);
    slot.desc = desc;
    slot.status = 'success';
  } catch(e) {
    console.warn('表情包识别失败:', e.message);
    slot.status = 'error';
    slot.desc = '';
  }
  renderBatchStickerSlots();
  // Hide progress if all done
  const allDone = _batchStickerSlots.every(s => s.status !== 'loading' && s.status !== 'pending');
  if (allDone) {
    document.getElementById('batchStickerProgress').style.display = 'none';
  }
}
function urlToBase64(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = function() {
      const canvas = document.createElement('canvas');
      canvas.width = Math.min(img.width, 400);
      canvas.height = Math.round(img.height * (canvas.width / img.width));
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      resolve(canvas.toDataURL('image/jpeg', 0.82));
    };
    img.onerror = () => reject(new Error('无法加载图片'));
    img.src = url;
  });
}
function confirmBatchStickers() {
  if (_batchStickerSlots.length === 0) { alert('请先添加表情包'); return; }
  const libs = getStickerLibraries();
  const targetLib = libs.find(function(lib) { return lib.id === getCurrentStickerLibraryId(); }) || libs[0];
  if (!targetLib) { alert('没有可用的表情包库'); return; }
  _batchStickerSlots.forEach(slot => {
    targetLib.stickers.push({
      src: slot.src,
      caption: slot.desc || '',
      isUrl: slot.isUrl || false,
      _visionDesc: slot.desc || ''  // Store vision-generated description permanently
    });
  });
  saveStickerLibraries(libs);
  closeBatchStickerModal();
  renderStickerManageView();
  alert('成功添加 ' + _batchStickerSlots.length + ' 个表情包！');
}
