function _tdWorldKey() {
  try { return 'mono_truth_dare_' + (typeof mwGetActiveId === 'function' ? (mwGetActiveId() || 'default') : 'default'); } catch(e) { return 'mono_truth_dare_default'; }
}
function _tdLoadStore() {
  try { return JSON.parse(localStorage.getItem(_tdWorldKey()) || '{}'); } catch(e) { return {}; }
}
function _tdSaveStore(store) {
  try { localStorage.setItem(_tdWorldKey(), JSON.stringify(store || {})); } catch(e) {}
}
function _tdDefaultState(personaId) {
  return {
    active: false,
    personaId: String(personaId || ''),
    phase: 'idle',
    accepted: false,
    mode: 'turns',
    round: 0,
    turnOwner: '',
    turnCursor: 'user',
    lastSummary: '',
    usedTruthPrompts: [],
    usedDarePrompts: [],
    currentQuestion: '',
    currentTruthQuestion: '',
    currentTask: null,
    userDare: null,
    updatedAt: 0
  };
}
function tdGetState(personaId) {
  const key = String(personaId || '');
  const store = _tdLoadStore();
  return Object.assign(_tdDefaultState(key), store[key] || {});
}
function tdSetState(personaId, nextState) {
  const key = String(personaId || '');
  const store = _tdLoadStore();
  store[key] = Object.assign(_tdDefaultState(key), nextState || {}, { personaId: key, updatedAt: Date.now() });
  _tdSaveStore(store);
  if (String(currentId || '') === key) tdRenderGamePanel();
}
function tdClearState(personaId) {
  const key = String(personaId || '');
  const store = _tdLoadStore();
  delete store[key];
  _tdSaveStore(store);
  if (String(currentId || '') === key) tdRenderGamePanel();
}
function _tdEnsurePersonaHistory(p) {
  if (!p) return [];
  if (!Array.isArray(p.history)) {
    try {
      const raw = localStorage.getItem('mono_hist_' + p.id);
      p.history = raw ? JSON.parse(raw) : [];
      if (!Array.isArray(p.history)) p.history = [];
    } catch(e) { p.history = []; }
  }
  return p.history;
}
function _tdPushContext(personaId, text, extras) {
  const p = personas.find(function(x) { return String(x.id) === String(personaId); });
  if (!p) return;
  const hist = _tdEnsurePersonaHistory(p);
  hist.push(Object.assign({
    role: 'assistant',
    content: String(text || ''),
    _hiddenContext: true,
    timestamp: Date.now()
  }, extras || {}));
  saveData();
}
function _tdPushChatMessage(personaId, msg) {
  const p = personas.find(function(x) { return String(x.id) === String(personaId); });
  if (!p) return -1;
  const hist = _tdEnsurePersonaHistory(p);
  hist.push(Object.assign({ timestamp: Date.now() }, msg || {}));
  saveData();
  if (String(currentId || '') === String(personaId)) renderMessages();
  try { renderContactList(); } catch(e) {}
  return hist.length - 1;
}
function _tdUpdateLatestInviteStatus(personaId, status) {
  const p = personas.find(function(x) { return String(x.id) === String(personaId); });
  if (!p) return;
  const hist = _tdEnsurePersonaHistory(p);
  for (let i = hist.length - 1; i >= 0; i--) {
    const m = hist[i];
    if (m && m.msgType === 'truth_dare_invite' && m.role === 'user') {
      m.tdInviteStatus = status;
      break;
    }
  }
  saveData();
  if (String(currentId || '') === String(personaId)) renderMessages();
}
function _tdGetApiConfigSafe() {
  try {
    if (typeof _getApiConfig === 'function') {
      const cfg = _getApiConfig();
      if (cfg && cfg.url && cfg.key) return cfg;
    }
  } catch(e) {}
  try {
    if (typeof _getCurrentActiveApiConfig === 'function') {
      const cfg = _getCurrentActiveApiConfig();
      if (cfg && cfg.url && cfg.key) return cfg;
    }
  } catch(e) {}
  try {
    if (apiConfig && apiConfig.url && apiConfig.key) return apiConfig;
  } catch(e) {}
  return null;
}
function _tdRecentChatText(p, maxCount) {
  const hist = _tdEnsurePersonaHistory(p).slice(-(maxCount || (p.memoryCount || 60)));
  return hist.filter(function(m) { return !m._hiddenContext && !m._systemNote && !m._transferContext; }).map(function(m) {
    return (m.role === 'user' ? (userProfile.name || '用户') : p.name) + '：' + (m.content || '');
  }).join('\n');
}
function _tdCoreMemoryText(p) {
  if (!p || !Array.isArray(p.memoryCore) || p.memoryCore.length === 0) return '（无）';
  return p.memoryCore.map(function(item, idx) {
    const content = typeof item === 'string' ? item : (item.content || '');
    return (idx + 1) + '. ' + content;
  }).join('\n');
}
function _tdBuildPersonaPromptBase(p, state) {
  const relCtx = typeof _mwBuildRelInjectForChar === 'function' ? (_mwBuildRelInjectForChar(p.name, null, false) || '') : '';
  const wbCtx = typeof buildWorldBookInjection === 'function' ? (buildWorldBookInjection((p.persona || '') + '\n' + _tdRecentChatText(p, 24), p.id) || '') : '';
  const usedTruth = (state && state.usedTruthPrompts || []).slice(-16).join(' / ');
  const usedDare = (state && state.usedDarePrompts || []).slice(-16).join(' / ');
  return `${typeof LANG_SYSTEM_PREFIX !== 'undefined' ? LANG_SYSTEM_PREFIX : ''}你是${p.name}。人设：${p.persona || '（无）'}。
你和用户 ${userProfile.name || '用户'} 正在当前这个私聊聊天室里玩「真心话大冒险」。
你已经接受了这场游戏，这件事对你来说是真实发生过的。

【必须遵守】
1. 语气必须完全符合你的人设、关系设定、聊天上下文与记忆。
2. 你清楚知道现在是在和用户玩真心话大冒险，所以要能理解邀请、轮次、真心话问题、大冒险指令这些上下文。
3. 真心话问题不要油腻、不要空泛、不要问既定事实，也不要重复过去问过的内容。
4. 大冒险要有趣、刺激、带一点点尴尬或暧昧，但不要侮辱性、不要恶意羞辱。
5. 如果关系是情侣、夫妻、暧昧等亲密关系，可以更偏向暧昧、试探、情感推进、亲密隐私。
6. 如果是朋友圈相关内容，绝对不要在文案里提到这是大冒险、被要求发的、配合游戏发的。
7. 给用户出大冒险时，必须严格遵守关系图里的人物关系逻辑——绝对不能让用户去向你的情敌表白或做暧昧互动。

【你的核心记忆】
${_tdCoreMemoryText(p)}

【你和用户最近的聊天】
${_tdRecentChatText(p, 32) || '（暂无）'}

【关系图 / 世界关系】
${relCtx || '（无）'}

【世界书补充】
${wbCtx || '（无）'}

【避免重复】
过去已经出现过的真心话关键词：${usedTruth || '（暂无）'}
过去已经出现过的大冒险关键词：${usedDare || '（暂无）'}`;
}
async function _tdFetchModelCompletion(messages, persona, maxTokens, temperature) {
  const cfg = _tdGetApiConfigSafe();
  if (!cfg) throw new Error('NO_API');
  const r = await fetch(`${cfg.url.replace(/\/$/, '')}/chat/completions`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${cfg.key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: cfg.model || apiConfig.model,
      messages: messages,
      max_tokens: maxTokens || 260,
      temperature: temperature == null ? (persona && persona.temperature) || 0.95 : temperature
    })
  });
  if (!r.ok) throw new Error('API Error ' + r.status);
  const data = await r.json();
  return (((data || {}).choices || [])[0] || {}).message ? ((((data || {}).choices || [])[0] || {}).message.content || '').trim() : '';
}
async function _tdPersonaAskText(p, state, ask, fallbackText) {
  var _tdTypingEl = document.getElementById('typingArea');
  if (_tdTypingEl) _tdTypingEl.classList.remove('hidden');
  try {
    const base = _tdBuildPersonaPromptBase(p, state);
    const raw = await _tdFetchModelCompletion([{ role: 'user', content: base + '\\n\\n' + ask }], p, 260, 0.95);
    if (_tdTypingEl) _tdTypingEl.classList.add('hidden');
    return String(raw || '').replace(/^["'\u201c\u300c]|["'\u201d\u300d]$/g, '').trim() || fallbackText || '';
  } catch(e) {
    if (_tdTypingEl) _tdTypingEl.classList.add('hidden');
    return fallbackText || '';
  }
}
async function _tdPersonaAskJson(p, state, ask, fallbackObj) {
  var _tdTypingEl = document.getElementById('typingArea');
  if (_tdTypingEl) _tdTypingEl.classList.remove('hidden');
  try {
    const base = _tdBuildPersonaPromptBase(p, state);
    let raw = await _tdFetchModelCompletion([{ role: 'user', content: base + '\\n\\n' + ask }], p, 420, 0.9);
    if (_tdTypingEl) _tdTypingEl.classList.add('hidden');
    raw = String(raw || '').replace(/```json|```/gi, '').trim();
    return Object.assign({}, fallbackObj || {}, JSON.parse(raw));
  } catch(e) {
    if (_tdTypingEl) _tdTypingEl.classList.add('hidden');
    return Object.assign({}, fallbackObj || {});
  }
}
function _tdPersonaFallbackAccept回复(p) {
  return (p && p.name ? p.name : '角色') + '轻轻笑了一下，说可以，陪你玩。';
}
// ── TD Multi-message helper: splits reply on ### and pushes each message separately,
//    respecting persona's min回复Count / max回复Count settings ──
async function _tdPersonaAskMulti(p, state, ask, fallbackText, opts) {
  const min回复 = (opts && opts.min != null) ? opts.min : (p.min回复Count || 1);
  const max回复 = (opts && opts.max != null) ? opts.max : (p.max回复Count || 3);
  const count = (typeof monoPickNaturalReplyCount === 'function') ? monoPickNaturalReplyCount(min回复, max回复, p, ask || '') : (Math.floor(Math.random() * (max回复 - min回复 + 1)) + min回复);
  const base = _tdBuildPersonaPromptBase(p, state);
  const multiAsk = ask + '\n【发送格式】请连续发送 ' + count + ' 条消息，消息之间用 "###" 分隔，像平时发消息一样自然连贯，不要把所有内容塞进一条里。只返回消息内容本身，不要解释。';
  let raw = '';
  try {
    raw = await _tdFetchModelCompletion([{ role: 'user', content: base + '\n\n' + multiAsk }], p, Math.max(400, count * 220), 0.95);
  } catch(e) {}
  let parts = raw ? raw.split('###').map(function(s) { return s.replace(/^["'"\u201c\u300c]|["'"\u201d\u300d]$/g, '').trim(); }).filter(Boolean) : [];
  if (parts.length === 0) parts = fallbackText ? [fallbackText] : [];
  // Clamp to configured range
  if (parts.length > max回复) parts = parts.slice(0, max回复);
  if (parts.length === 0) return [];
  // Show typing indicator
  const typingEl = document.getElementById('typingArea');
  if (typingEl) typingEl.classList.remove('hidden');
  const results = [];
  for (let i = 0; i < parts.length; i++) {
    const msg = parts[i];
    if (!msg) continue;
    // Delay between messages (similar to normal chat)
    if (i > 0) await new Promise(function(r) { setTimeout(r, 600 + Math.random() * 900); });
    if (typingEl) typingEl.classList.remove('hidden');
    // Small typing pause before revealing message
    await new Promise(function(r) { setTimeout(r, 500 + Math.min(600, msg.length * 8)); });
    if (typingEl) typingEl.classList.add('hidden');
    _tdPushChatMessage(p.id, { role: 'assistant', content: msg });
    results.push(msg);
  }
  if (typingEl) typingEl.classList.add('hidden');
  return results;
}
function _tdRelatedPersonas(personaId) {
  const p = personas.find(function(x) { return String(x.id) === String(personaId); });
  if (!p) return [];
  const rels = typeof mwGetRelEntries === 'function' ? (mwGetRelEntries() || []) : [];
  const names = [];
  rels.forEach(function(rel) {
    if (rel.a === p.name && rel.b) names.push(rel.b);
    if (rel.b === p.name && rel.a) names.push(rel.a);
  });
  const uniq = Array.from(new Set(names));
  const mapped = uniq.map(function(name) { return personas.find(function(px) { return px.name === name; }); }).filter(Boolean);
  if (mapped.length > 0) return mapped;
  return personas.filter(function(px) { return String(px.id) !== String(personaId); }).slice(0, 8);
}
function tdSyncDareModalFields() {
  const mode = (document.getElementById('tdDareModeSelect') || {}).value || 'simulate';
  const targetType = (document.getElementById('tdDareChatTargetType') || {}).value || 'persona';
  const chatFields = document.getElementById('tdDareChatFields');
  const personaSelect = document.getElementById('tdDareChatPersonaSelect');
  const npcName = document.getElementById('tdDareNpcNameInput');
  const npcIdentity = document.getElementById('tdDareNpcIdentityInput');
  const hint = document.getElementById('tdDareHintText');
  if (chatFields) chatFields.style.display = mode === 'chat' ? 'block' : 'none';
  if (personaSelect) personaSelect.style.display = (mode === 'chat' && targetType === 'persona') ? 'block' : 'none';
  if (npcName) npcName.style.display = (mode === 'chat' && targetType === 'npc') ? 'block' : 'none';
  if (npcIdentity) npcIdentity.style.display = (mode === 'chat' && targetType === 'npc') ? 'block' : 'none';
  if (hint) {
    hint.textContent = mode === 'simulate'
      ? '角色会先在聊天室里读到这条指令，表达一下自己的情绪，再由你决定是否让 TA 真正执行。'
      : (mode === 'moments'
        ? '执行时会直接跳到朋友圈页面，由角色真实发出相关动态，并打上大冒险标签。'
        : '执行时会跳到对应的角色聊天室，由角色真实把这条信息发给目标对象。');
  }
}
