// REAL VOICE RECORDING ENGINE
// - MediaRecorder for audio capture
// - Web Speech API (SpeechRecognition) for STT
// - Fallback: send audio blob to Whisper-compatible API
// ════════════════════════════════════════════════
let _vrMediaRecorder = null;
let _vrAudioChunks = [];
let _vrStream = null;
let _vrTimerInterval = null;
let _vrSeconds = 0;
let _vrRecognition = null;
let _vrTranscript = '';
let _vrIsSlideUp = false;
let _vrStartY = null;
let _vrAudioBlob = null;
