// Play/pause a real TTS voice bubble
function playVoiceAudio(bubbleEl) {
  const audioRef = (bubbleEl.dataset && bubbleEl.dataset.audioUrl) || '';
  if (!audioRef) return;
  const btn = bubbleEl.querySelector('.voice-play-btn');
  // Already playing this bubble → pause it
  if (_currentVoiceEl === bubbleEl && _currentVoiceAudio && !_currentVoiceAudio.paused) {
    _currentVoiceAudio.pause();
    bubbleEl.classList.remove('playing');
    if (btn) btn.innerHTML = '<svg viewBox="0 0 10 10" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><polygon points="2,1 9,5 2,9"/></svg>';
    return;
  }
  // Stop whatever is currently playing
  if (_currentVoiceAudio) {
    _currentVoiceAudio.pause();
    if (_currentVoiceEl) {
      _currentVoiceEl.classList.remove('playing');
      const oldBtn = _currentVoiceEl.querySelector('.voice-play-btn');
      if (oldBtn) oldBtn.innerHTML = '<svg viewBox="0 0 10 10" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><polygon points="2,1 9,5 2,9"/></svg>';
    }
    _currentVoiceAudio = null;
    _currentVoiceEl = null;
  }
  // Resolve idb: reference → real audio URL, then play
  _resolveAudioRef(audioRef).then(audioUrl => {
    if (!audioUrl) return;
    const audio = new Audio(audioUrl);
    _currentVoiceAudio = audio;
    _currentVoiceEl = bubbleEl;
    bubbleEl.classList.add('playing');
    if (btn) btn.innerHTML = '<svg viewBox="0 0 10 10" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><rect x="1.5" y="1" width="3" height="8" rx="0.5"/><rect x="5.5" y="1" width="3" height="8" rx="0.5"/></svg>';
    audio.play().catch(e => {
      console.warn('Audio play failed:', e);
      bubbleEl.classList.remove('playing');
      if (btn) btn.innerHTML = '<svg viewBox="0 0 10 10" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><polygon points="2,1 9,5 2,9"/></svg>';
      _currentVoiceAudio = null;
      _currentVoiceEl = null;
    });
    audio.onended = () => {
      bubbleEl.classList.remove('playing');
      if (btn) btn.innerHTML = '<svg viewBox="0 0 10 10" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><polygon points="2,1 9,5 2,9"/></svg>';
      if (_currentVoiceAudio === audio) { _currentVoiceAudio = null; _currentVoiceEl = null; }
      // Clean up blob URL if we created one
      if (audioUrl.startsWith('blob:')) URL.revokeObjectURL(audioUrl);
    };
    audio.onerror = () => {
      bubbleEl.classList.remove('playing');
      if (btn) btn.innerHTML = '<svg viewBox="0 0 10 10" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><polygon points="2,1 9,5 2,9"/></svg>';
      if (_currentVoiceAudio === audio) { _currentVoiceAudio = null; _currentVoiceEl = null; }
      if (audioUrl.startsWith('blob:')) URL.revokeObjectURL(audioUrl);
    };
  });
}
// Resolve an audioRef to a playable URL.
// Handles: 'idb:<key>' (IndexedDB ArrayBuffer), 'data:...' (inline), plain URLs
async function _resolveAudioRef(ref) {
  if (!ref) return null;
  if (ref.startsWith('idb:')) {
    const idbKey = ref.slice(4);
    if (!window._monoIdbBlobGet) return null;
    const buf = await window._monoIdbBlobGet(idbKey);
    if (!buf) return null;
    const blob = new Blob([buf], { type: 'audio/mpeg' });
    return URL.createObjectURL(blob); // short-lived; caller must revoke after use
  }
  return ref; // data: URL or remote URL — use directly
}
// ---- PERSONA-INITIATED TRANSFER ----
async function tryPersonaTransfer(p, recentChat) {
  if (!p.allowSticker && !p.allowVoice) return; // reuse: only if persona has rich media enabled
  // Actually let persona transfer independently:
  if (!apiConfig.url || !apiConfig.key || !apiConfig.model) return;
  const prompt = `${LANG_SYSTEM_PREFIX}你是${p.name}，人设：${p.persona}。\n根据你的人设、以下聊天气氛和内容，判斷你是否真的有强理由主动转账给${userProfile.name}？\n转账是一个非常少见的特殊行为，不是日常示好手段。只有明确请客、补偿、庆祝、或用户明确提到资金需求时才考虑。\n普通聊天、暧昧、关心、撒娇都不够，默认应返回 false。\n请回覆JSON格式：{"transfer": true/false, "amount": 数字（如转账）, "note": "便簽", "reason": "原因"}\n若transfer为false，reason可省略。只返回JSON。\n\n【最近聊天记录】\n${recentChat}`;
  try {
    const r = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST', headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: prompt }], temperature: p.temperature || 1.0, max_tokens: 150 })
    });
    const data = await r.json();
    let raw = data.choices[0].message.content.trim().replace(/```json|```/g, '').trim();
    const result = JSON.parse(raw);
    if (result.transfer && result.amount > 0) {
      await new Promise(res => setTimeout(res, 800 + Math.random() * 1200));
      const duration = calcVoiceDuration('transfer');
      p.history.push({ role: 'assistant', msgType: 'transfer', transferAmt: result.amount, transferNote: result.note || '', transferStatus: 'pending', content: '[角色转账: ¥' + result.amount.toFixed(2) + ']' });
      saveData();
      if (currentId == p.id) renderMessages();
    }
  } catch(e) {}
}
