// ===== 角色回复模式逻辑 =====
var _userIsTyping = false;
var _userTypingTimer = null;
var _pendingAuto回复 = null;
var _auto回复AbortController = null; // AbortController for cancelling in-flight API requests
var _auto回复Cancelled = false; // Flag to stop message-by-message output mid-stream
function _update回复ModeUI() {
  var mode = _getSelected回复Mode();
  var speedSection = document.getElementById('replySpeedSection');
  if (speedSection) speedSection.style.display = (mode === 'manual') ? 'none' : 'block';
  // Show/hide custom speed input
  var customRadio = document.getElementById('p回复SpeedCustom');
  var customInput = document.getElementById('replySpeedCustomInput');
  if (customInput && customRadio) {
    customInput.style.display = customRadio.checked ? 'flex' : 'none';
  }
}
function _getSelected回复Mode() {
  if (document.getElementById('p回复Mode1') && document.getElementById('p回复Mode1').checked) return 'manual';
  if (document.getElementById('p回复Mode2') && document.getElementById('p回复Mode2').checked) return 'auto_interrupt';
  if (document.getElementById('p回复Mode3') && document.getElementById('p回复Mode3').checked) return 'auto_no_interrupt';
  return 'manual';
}
// Get reply delay in ms based on speed setting of current persona
function _get回复Delay(p) {
  var speed = p.replySpeed || 'fast';
  var minMs, maxMs;
  if (speed === 'fast') { minMs = 0; maxMs = 5000; }
  else if (speed === 'medium') { minMs = 60000; maxMs = 300000; }
  else if (speed === 'slow') { minMs = 360000; maxMs = 600000; }
  else if (speed === 'custom') {
    minMs = (p.replySpeedCustomMin || 0) * 1000;
    maxMs = (p.replySpeedCustomMax || 10) * 1000;
  } else { minMs = 0; maxMs = 5000; }
  if (maxMs < minMs) maxMs = minMs;
  return Math.floor(Math.random() * (maxMs - minMs + 1)) + minMs;
}
// Abort any ongoing auto-reply (cancel API request + stop message output)
function _abortOngoingAuto回复() {
  // Cancel pending timer
  if (_pendingAuto回复) { clearTimeout(_pendingAuto回复); _pendingAuto回复 = null; }
  // Abort in-flight API request
  if (_auto回复AbortController) {
    try { _auto回复AbortController.abort(); } catch(e) {}
    _auto回复AbortController = null;
  }
  // Signal to stop message-by-message output loop
  _auto回复Cancelled = true;
  // Release the lock so a new reply can be triggered later
  if (currentId && _auto回复Locks) { delete _auto回复Locks[currentId]; }
  // Hide typing indicator
  var typing = document.getElementById('typingArea');
  if (typing) typing.classList.add('hidden');
}
function _markPersonaUserActivity(p, ts) {
  if (!p) return;
  var safeTs = Number(ts) || Date.now();
  p._lastUserChatTs = safeTs;
  p.lastUserMessageTime = safeTs;
}
function _getPersonaLastUserActivityTs(p) {
  if (!p) return 0;
  var latest = Math.max(Number(p._lastUserChatTs || 0), Number(p.lastUserMessageTime || 0));
  if (Array.isArray(p.history)) {
    for (var i = p.history.length - 1; i >= 0; i--) {
      var msg = p.history[i];
      if (msg && msg.role === 'user' && msg.timestamp) {
        latest = Math.max(latest, Number(msg.timestamp) || 0);
        break;
      }
    }
  }
  return latest;
}
function _getPersonaLastAutoMessageTs(p) {
  if (!p || !Array.isArray(p.history)) return 0;
  if (p._lastAutoMsgTime) return Number(p._lastAutoMsgTime) || 0;
  for (var i = p.history.length - 1; i >= 0; i--) {
    var msg = p.history[i];
    if (msg && msg._autoMsgTime) return Number(msg._autoMsgTime) || 0;
  }
  return 0;
}
function _getPersonaAutoMsgAnchorTs(p) {
  return Math.max(_getPersonaLastUserActivityTs(p), _getPersonaLastAutoMessageTs(p));
}
function _isOfflineModeActiveForPersona(personaId) {
  try {
    var offlinePage = document.getElementById('offlinePage');
    if (!offlinePage || !offlinePage.classList.contains('active')) return false;
    if (typeof _offlineState === 'undefined' || !_offlineState) return false;
    return String(_offlineState.personaId || '') === String(personaId || '');
  } catch(e) {
    return false;
  }
}
// Called after user sends a message - handles auto reply based on mode
var _lastUserSendTime = 0; // Track when user last sent a message
var _noInterruptMinWait = 2000; // Minimum wait time (ms) in no-interrupt mode to detect if user will send more messages
function _handleAuto回复AfterSend(personaId) {
  var p = personas.find(function(x) { return x.id == personaId; });
  if (!p) return;
  _markPersonaUserActivity(p, _getPersonaLastUserActivityTs(p) || Date.now());
  var mode = p.replyMode || 'manual';
  if (mode === 'manual') return; // manual mode: do nothing
  var delay = _get回复Delay(p);
  if (_pendingAuto回复) { clearTimeout(_pendingAuto回复); _pendingAuto回复 = null; }
  if (mode === 'auto_interrupt') {
    // Auto reply after delay, regardless of user typing
    _pendingAuto回复 = setTimeout(function() {
      _pendingAuto回复 = null;
      if (currentId == personaId) triggerAuto回复();
    }, delay);
  } else if (mode === 'auto_no_interrupt') {
    // Abort any ongoing reply — user sent a new message, so cancel current generation
    _abortOngoingAuto回复();
    // Record the time of this user message send
    _lastUserSendTime = _getPersonaLastUserActivityTs(p) || Date.now();
    // Use the larger of configured delay or minimum wait to avoid interrupting user
    var effectiveDelay = Math.max(delay, _noInterruptMinWait);
    // Auto reply after effective delay, but also debounce: reset timer on each new message
    _pendingAuto回复 = setTimeout(function() {
      _pendingAuto回复 = null;
      _tryAuto回复WhenNotTyping(personaId);
    }, effectiveDelay);
  }
}
function _tryAuto回复WhenNotTyping(personaId) {
  // Check if user is still typing
  if (_userIsTyping) {
    setTimeout(function() { _tryAuto回复WhenNotTyping(personaId); }, 500);
    return;
  }
  // Check if enough time has passed since user's last message
  var elapsed = Date.now() - _lastUserSendTime;
  if (elapsed < _noInterruptMinWait) {
    // Not enough time passed — user may still be sending more messages, wait a bit more
    setTimeout(function() { _tryAuto回复WhenNotTyping(personaId); }, _noInterruptMinWait - elapsed + 100);
    return;
  }
  if (currentId == personaId) triggerAuto回复();
}
// Detect user typing in the input field
function _setupTypingDetection() {
  var input = document.getElementById('userInput');
  if (!input || input._typingDetectionSetup) return;
  input._typingDetectionSetup = true;
  input.addEventListener('input', function() {
    _userIsTyping = true;
    if (_userTypingTimer) clearTimeout(_userTypingTimer);
    _userTypingTimer = setTimeout(function() {
      _userIsTyping = false;
    }, 2000); // User considered "stopped typing" after 2 seconds of no input
    // In no-interrupt mode: abort ongoing reply when user starts typing
    var _curP = currentId ? personas.find(function(x) { return x.id == currentId; }) : null;
    if (_curP && (_curP.replyMode === 'auto_no_interrupt')) {
      _abortOngoingAuto回复();
    }
  });
  input.addEventListener('blur', function() {
    _userIsTyping = false;
    if (_userTypingTimer) { clearTimeout(_userTypingTimer); _userTypingTimer = null; }
  });
}
