  const _blockedWbInject = typeof buildWorldBookInjection === 'function' ? buildWorldBookInjection(recentChat, p.id) : '';
  const _blockedLangCode = _detectPersonaLang(p);
  const _blockedLangOv = _langOverridePrompt(_blockedLangCode);
  const _blockedNeedsTranslation = !!(_blockedLangCode && _blockedLangCode !== 'zh' && _blockedLangCode !== 'zh-cn');
  const _blockedTranslationNote = _blockedNeedsTranslation
