function loadCustomizations() {
  // Load home background
  const bgData = localStorage.getItem('mono_home_bg');
  if (bgData) {
    document.getElementById('homeScreen').style.backgroundImage = `url(${bgData})`;
    const preview = document.getElementById('bgPreview');
    if (preview) preview.innerHTML = `<img src="${bgData}">`;
  }
  // Load custom app icons
  APP_ICONS_CONFIG.forEach((app, i) => {
    const iconData = localStorage.getItem(`mono_icon_${app.key}`);
    if (iconData) {
      applyCustomIcon(app.key, iconData);
    }
  });
}
function changeHomeBg(input) {
  if (input.files && input.files[0]) {
    const reader = new FileReader();
    reader.onload = async function(e) {
      const compressed = await compressImage(e.target.result, 1400, 0.82);
      await safeSetItem('mono_home_bg', compressed);
      document.getElementById('homeScreen').style.backgroundImage = `url(${compressed})`;
      const preview = document.getElementById('bgPreview');
      if (preview) preview.innerHTML = `<img src="${compressed}">`;
    };
    reader.readAsDataURL(input.files[0]);
  }
}
function resetHomeBg() {
  localStorage.removeItem('mono_home_bg');
  document.getElementById('homeScreen').style.backgroundImage = '';
  const preview = document.getElementById('bgPreview');
  if (preview) preview.innerHTML = '<span style="font-size:11px;color:#aaa;">点击选择背景图片</span>';
}
function renderIconCustomizeGrid() {
  const grid = document.getElementById('iconCustomizeGrid');
  if (!grid) return;
  grid.innerHTML = APP_ICONS_CONFIG.map((app, i) => {
    const savedIcon = localStorage.getItem(`mono_icon_${app.key}`);
    const previewContent = savedIcon
      ? `<img src="${savedIcon}">`
      : (app.defaultSvg ? app.defaultSvg : `<i class="fas ${app.icon}"></i>`);
    return `<div class="customize-item" onclick="document.getElementById('iconInput_${app.key}').click()">
      <div class="customize-item-preview">${previewContent}</div>
      <div class="customize-item-label">${app.label}</div>
      <input type="file" id="iconInput_${app.key}" hidden accept="image/*" onchange="changeAppIcon('${app.key}', this)">
    </div>`;
  }).join('');
}
function changeAppIcon(appKey, input) {
  if (input.files && input.files[0]) {
    const reader = new FileReader();
    reader.onload = async function(e) {
      const compressed = await compressImage(e.target.result, 256, 0.82);
      await safeSetItem(`mono_icon_${appKey}`, compressed);
      applyCustomIcon(appKey, compressed);
      renderIconCustomizeGrid();
    };
    reader.readAsDataURL(input.files[0]);
  }
}
function applyCustomIcon(appKey, imgData) {
  // Map each app key to the stable ID of its icon BOX element
  const iconBoxIdMap = {
    // Page 1 grid apps — icon box is first child of the app-icon div
    'chat':             'app-chat',
    'moments':          'app-moments',
    'forum':            'app-forum',
    'novel':            'app-novel',
    // Extra row apps
    'scriptExperience': 'app-script',
    'notifCenter':      'app-notif',
    'dream':            'app-dream',
    'online':           'app-online',
    // Dock apps — icon box has its own ID
    'diary':            'dock-diary',
    'shop':             'dock-shop',
    'visit':            'dock-visit',
    'profile':          'dock-profile',
    // Page 2 specific icon boxes (already have stable IDs)
    'location':         'igLocationIconBox',
    'blackbox':         'igBlackboxIconBox',
    'music':            'igMusicIconBox',
    'task':             'igTaskIconBox',
    'dating':           'igDatingIconBox',
    'pet':              'igPetIconBox',
    'shopApp':          'igShopIconBox',
    'health':           'igHealthIconBox',
    'decrypt':          'decryptHomeIconBox',
    'entertainment':    'entHomeIconBox',
    'youtube':          'youtubeHomeIconBox',
    'instagram':        'instagramHomeIconBox',
    'escape-theater':   'escapeTheaterHomeIconBox',
  };
  const stableId = iconBoxIdMap[appKey];
  if (!stableId) return;
  const containerEl = document.getElementById(stableId);
  if (!containerEl) return;
  // For app-icon wrappers (page1 + extra row), inject into the icon-box child
  // For dock/page2 boxes, inject directly into the element
  const isDockOrPage2Box = containerEl.classList.contains('home-dock-app-box') ||
    containerEl.id.startsWith('ig') || containerEl.id.startsWith('dock-');
  let targetBox;
  if (isDockOrPage2Box) {
    targetBox = containerEl;
  } else {
    // It's a home-app-icon wrapper — get the icon box inside it
    targetBox = containerEl.querySelector('.home-app-icon-box') || containerEl;
  }
  const borderRadius = ['location','blackbox','music','task','dating','pet','health','decrypt','entertainment','youtube','instagram','escape-theater'].includes(appKey) ? '16px' :
                       appKey === 'shopApp' ? '18px' : '';
  targetBox.innerHTML = `<img class="custom-icon" src="${imgData}"` +
    (borderRadius ? ` style="border-radius:${borderRadius};"` : '') + `>`;
}
