  if (typeof _offlineState !== 'undefined' && _offlineState.sessions && Object.keys(_offlineState.sessions).length > 0) {
    _saveOfflineSessions();
  }
  const readBlobByKey = async function(key, fallback) {
    try {
      if (window._monoIdbBlobGet) {
        const val = await window._monoIdbBlobGet(key);
        if (val != null) return val;
      }
    } catch(e) {}
    return fallback;
  };
