function importImageAssetsFile(input) {
  if (!input.files || !input.files[0]) return;
  const statusEl = document.getElementById('importExportStatus');
  statusEl.style.display = 'block';
  statusEl.style.color = '#666';
  statusEl.textContent = '正在读取图片资源包...';
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const raw = JSON.parse(e.target.result);
      if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
        throw new Error('无效的文件格式，请选择 Mono 图片资源 JSON 文件');
      }
      if (!monoIsKnownBackupPayload(raw) || monoDetectBackupKind(raw) !== MONO_BACKUP_KIND_IMAGES) {
        throw new Error('这不是图片资源包，请改用“导入主数据”按钮导入普通备份');
      }
      monoConfigureImportConfirm(MONO_BACKUP_KIND_IMAGES);
      _pendingImportData = { kind: MONO_BACKUP_KIND_IMAGES, raw: raw };
      document.getElementById('importPreviewContent').innerHTML = monoBuildImageAssetPreview(raw);
      document.getElementById('importConfirmModal').style.display = 'flex';
      statusEl.style.display = 'none';
    } catch(err) {
      statusEl.style.color = '#e74c3c';
      statusEl.textContent = '✗ 图片资源包读取失败: ' + err.message;
      _pendingImportData = null;
      monoConfigureImportConfirm(MONO_BACKUP_KIND_MAIN);
    }
    input.value = '';
  };
  reader.readAsText(input.files[0]);
}
