// ===================== Refresh Items =====================
function visitRefreshItems() {
  if (!visitCurrentCharId || !visitCurrentRoom) return;
  const data = getVisitData();
  const key = 'items_' + visitCurrentCharId + '_' + visitCurrentRoom;
  delete data[key];
  saveVisitData(data);
  generateRoomItems(visitCurrentCharId, visitCurrentRoom);
}
// ===================== Message / Comment System =====================
function getVisitMessages(charId) {
  const data = getVisitData();
  return data['msgs_' + charId] || [];
}
function saveVisitMessages(charId, msgs) {
  const data = getVisitData();
  data['msgs_' + charId] = msgs;
  saveVisitData(data);
}
function renderVisitMessages(charId) {
  const list = document.getElementById('visitMsgList');
  if (!list) return;
  const msgs = getVisitMessages(charId);
  if (msgs.length === 0) {
    list.innerHTML = '<div style="padding:10px 0;text-align:center;font-size:10px;color:#ccc;letter-spacing:1px;">还没有留言</div>';
    return;
  }
  const persona = personas.find(x => x.id == charId);
  const _vLang = persona ? _detectPersonaLang(persona) : '';
  list.innerHTML = msgs.map((m, idx) => {
    const isChar = m.role === 'assistant';
    // Build translation block
    let trHtml = '';
    const _visitTrEnabled = persona ? (persona.enableTranslation !== false) : true;
    if (isChar && _vLang && _visitTrEnabled) {
      if (m.translation) {
        trHtml = _buildKoreanTranslation(m.translation);
      } else {
        // No translation yet — show retry pill
        trHtml = `<div class="visit-msg-tr-retry" style="margin-top:6px;font-size:10px;color:#bbb;cursor:pointer;letter-spacing:0.5px;font-style:italic;user-select:none;" onclick="retryVisitTranslation(${JSON.stringify(charId)},${idx},'${(m.text||'').replace(/'/g,"\\'")}')">翻譯失败 · 点擊重试</div>`;
      }
    } else if (m.translation && _visitTrEnabled) {
      trHtml = _buildKoreanTranslation(m.translation);
    }
    return `<div class="visit-msg-item" data-visit-idx="${idx}">
      <div class="visit-msg-author">${m.author}</div>
      <div class="visit-msg-text">${m.text}</div>
      ${trHtml}
      <div class="visit-msg-time">${m.time || ''}</div>
    </div>`;
  }).join('');
  list.scrollTop = list.scrollHeight;
}
async function retryVisitTranslation(charId, idx, text) {
  const el = document.querySelector(`.visit-msg-item[data-visit-idx="${idx}"] .visit-msg-tr-retry`);
  if (el) { el.textContent = '翻譯中…'; el.style.cursor = 'default'; el.onclick = null; }
  if (!text || !apiConfig.url || !apiConfig.key || !apiConfig.model) {
    if (el) el.textContent = '翻譯失败 · 点擊重试';
    return;
  }
  try {
    const r = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST', headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: '將以下文字翻譯成简体中文，只返回翻譯结果：\n' + text }], max_tokens: 150, temperature: 0.2 })
    });
    if (!r.ok) throw new Error('failed');
    const d = await r.json();
    const tr = (d.choices[0].message.content || '').trim();
    if (!tr) throw new Error('empty');
    // Save back to message object
    const msgs = getVisitMessages(charId);
    if (msgs[idx]) { msgs[idx].translation = tr; saveVisitMessages(charId, msgs); }
    renderVisitMessages(charId);
  } catch(e) {
    if (el) {
      el.textContent = '翻譯失败 · 点擊重试';
      el.style.cursor = 'pointer';
      el.onclick = function() { retryVisitTranslation(charId, idx, text); };
    }
  }
}
async function visitSendMsg() {
  if (!visitCurrentCharId) return;
  const input = document.getElementById('visitMsgInput');
  const text = input.value.trim();
  if (!text) return;
  input.value = '';
  const p = personas.find(x => x.id == visitCurrentCharId);
  if (!p) return;
  const now = new Date();
  const timeStr = now.getMonth()+1 + '/' + now.getDate() + ' ' + now.getHours().toString().padStart(2,'0') + ':' + now.getMinutes().toString().padStart(2,'0');
  // Save user message
  const msgs = getVisitMessages(visitCurrentCharId);
  msgs.push({ author: userProfile.name || '我', text: text, time: timeStr, role: 'user' });
  saveVisitMessages(visitCurrentCharId, msgs);
  renderVisitMessages(visitCurrentCharId);
  // Auto-reply from character
  await visitAuto回复(visitCurrentCharId, text, p);
}
async function visitAuto回复(charId, userText, persona) {
  if (!apiConfig.url || !apiConfig.key || !apiConfig.model) return;
  const msgs = getVisitMessages(charId);
  const recentMsgs = msgs.slice(-10).map(m => `${m.author}: ${m.text}`).join('\n');
  const _vLang = _detectPersonaLang(persona);
  const _vLangOv = _langOverridePrompt(_vLang);
  const sysPrompt = `你是${persona.name}。人设：${persona.persona || '无'}。${_vLangOv}
用户来你家串门，在你家的留言板上留了言。请用符合你人设的方式回复。
回复要求：只回复一句话，简短自然，像朋友间的对话。不要使用emoji。不要用列表格式。
最近留言:
${recentMsgs}`;
  try {
    const response = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: apiConfig.model,
        messages: [
          { role: 'system', content: sysPrompt },
          { role: 'user', content: userText }
        ],
        temperature: 0.85
      })
    });
    if (!response.ok) return;
    const result = await response.json();
    const reply = result.choices[0].message.content.trim().replace(/[\r\n]+/g, ' ');
    const now = new Date();
    const timeStr = (now.getMonth()+1) + '/' + now.getDate() + ' ' + now.getHours().toString().padStart(2,'0') + ':' + now.getMinutes().toString().padStart(2,'0');
    const updatedMsgs = getVisitMessages(charId);
    updatedMsgs.push({ author: persona.name, text: reply, time: timeStr, role: 'assistant' });
    // Translate if foreign language
    if (_vLang && reply && persona.enableTranslation !== false) {
      try {
        const _tr = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, { method: 'POST', headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: '將以下文字翻譯成简体中文，只返回翻譯结果：\n' + reply }], max_tokens: 100, temperature: 0.2 }) });
        if (_tr.ok) { const _td = await _tr.json(); const tr = (_td.choices[0].message.content || '').trim(); if (tr) updatedMsgs[updatedMsgs.length-1].translation = tr; }
      } catch(e) {}
    }
    saveVisitMessages(charId, updatedMsgs);
    renderVisitMessages(charId);
  } catch(e) {
    console.warn('Visit auto-reply failed:', e.message);
    _showApiErrorToast('拜访自动回复失败', e);
  }
}
