// ===================== Script API Compatibility Layer =====================
// 剧本体验统一使用聊天软件当前保存/生效的 API 配置，并复用同一套兼容请求与 JSON 解析逻辑。
function scriptGetActiveApiConfig() {
  var cfg = null;
  try { if (typeof _getCurrentActiveApiConfig === 'function') cfg = _getCurrentActiveApiConfig(); } catch(e) {}
  if ((!cfg || !cfg.url || !cfg.key || !cfg.model) && typeof apiConfig !== 'undefined') cfg = apiConfig;
  try { if (typeof _normalizeApiConfigObject === 'function') cfg = _normalizeApiConfigObject(cfg || {}); } catch(e) {}
  return cfg || { url: '', key: '', model: '' };
}
function scriptHasUsableApiConfig() {
  var cfg = scriptGetActiveApiConfig();
  if (typeof _hasUsableApiConfig === 'function') return _hasUsableApiConfig(cfg);
  return !!(cfg && cfg.url && cfg.key && cfg.model);
}
async function scriptCallChatApi(messages, options) {
  var cfg = scriptGetActiveApiConfig();
  if (!scriptHasUsableApiConfig()) throw new Error('请先在聊天软件的 API Config 中连接并保存 API。');
  var payload = {
    messages: messages,
    temperature: options && options.temperature != null ? options.temperature : 0.85,
    max_tokens: options && options.max_tokens ? options.max_tokens : 2048,
    stream: false
  };
  if (typeof _applyApiModel === 'function') payload = _applyApiModel(payload, cfg.model);
  else payload.model = cfg.model;
  var resp;
  if (typeof _compatibleChatCompletion === 'function') {
    resp = await _compatibleChatCompletion(cfg.url, cfg.key, payload, {});
  } else {
    var endpoint = (typeof _buildApiChatCandidates === 'function' ? _buildApiChatCandidates(cfg.url)[0] : cfg.url.replace(/\/+$/, '') + '/chat/completions');
    resp = await fetch(endpoint, { method: 'POST', headers: { 'Authorization': 'Bearer ' + cfg.key, 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
  }
  // 兼容少数 API 适配器：可能直接返回字符串/对象，而不是 Response。
  if (typeof resp === 'string') {
    var directText = resp.trim();
    if (!directText) throw new Error('API 返回内容为空');
    return directText;
  }
  if (resp && typeof resp === 'object' && typeof resp.text !== 'function') {
    var directObjText = typeof _extractAssistantMessageContent === 'function' ? _extractAssistantMessageContent(resp) : '';
    if (directObjText) return String(directObjText).trim();
    return resp;
  }
  if (!resp || !resp.ok) {
    var status = resp ? resp.status : 'network';
    var detail = '';
    try { detail = await resp.text(); } catch(e) {}
    throw new Error('API 请求失败：' + status + (detail ? ' ' + String(detail).slice(0, 120) : ''));
  }
  var rawBody = '';
  try { rawBody = await resp.text(); } catch(e) { rawBody = ''; }
  if (rawBody && typeof rawBody !== 'string') rawBody = JSON.stringify(rawBody);
  var data = null;
  try { data = rawBody ? JSON.parse(rawBody) : null; } catch(e) {
    // 部分中转 API 会直接返回纯文本；这时不要让 resp.json() 的语法错误中断剧情生成
    if (rawBody && !/^\s*[\{\[]/.test(rawBody)) return String(rawBody).trim();
    throw new Error('API 返回不是标准响应JSON：' + (e && e.message ? e.message : e));
  }
  var text = typeof _extractAssistantMessageContent === 'function'
    ? _extractAssistantMessageContent(data)
    : (data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || '';
  text = String(text || '').trim();
  if (!text && data && (Array.isArray(data) || typeof data === 'object')) return data;
  if (!text) throw new Error('API 返回内容为空');
  return text;
}
function scriptTryJsonParseLoose(s) {
  s = String(s || '').trim();
  if (!s) return null;
  try { return JSON.parse(s); } catch(e) {}
  // 修复 AI 常见 JSON 错误：数组/对象元素换行但少逗号、尾逗号、代码块、中文智能引号
  var fixed = s
    .replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '')
    .replace(/[“”]/g, '"').replace(/[‘’]/g, "'")
    .replace(/,\s*([}\]])/g, '$1')
    .replace(/}\s*{/g, '},{')
    .replace(/]\s*"/g, '],"')
    .replace(/}\s*"/g, '},"')
    .replace(/"\s*\n\s*"/g, '",\n"')
    .replace(/"\s*\r\n\s*"/g, '",\n"');
  try { return JSON.parse(fixed); } catch(e2) {}
  return null;
}
function scriptExtractBalancedJsonBlockLoose(text, startChar) {
  var raw = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  if (typeof _extractBalancedJsonBlock === 'function') {
    try { var b = _extractBalancedJsonBlock(raw, startChar); if (b) return b; } catch(e) {}
  }
  var endChar = startChar === '[' ? ']' : '}';
  var start = raw.indexOf(startChar);
  var end = raw.lastIndexOf(endChar);
  return start >= 0 && end > start ? raw.slice(start, end + 1) : '';
}
function scriptParseJsonFromAi(text, fallback, preferredShape) {
  // 兼容所有 API/中转层：有些兼容层会直接返回 object/array，不能再 text.replace()。
  if (text === null || text === undefined) return fallback;
  if (Array.isArray(text)) return text;
  if (typeof text === 'object') {
    var extracted = typeof _extractAssistantMessageContent === 'function' ? _extractAssistantMessageContent(text) : '';
    if (extracted && typeof extracted === 'string') text = extracted;
    else return text;
  }
  var s = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  var parsed = scriptTryJsonParseLoose(s);
  if (parsed !== null) return parsed;
  var shapes = preferredShape === 'array' ? ['[', '{'] : ['{', '['];
  for (var i = 0; i < shapes.length; i++) {
    var snippet = scriptExtractBalancedJsonBlockLoose(s, shapes[i]);
    parsed = scriptTryJsonParseLoose(snippet);
    if (parsed !== null) return parsed;
  }
  // 最后再调用全局解析器，但禁止它抛出的错误冒泡到剧本体验
  if (typeof _parseJsonFromText === 'function') {
    try { parsed = _parseJsonFromText(s, null, preferredShape || 'object'); if (parsed !== null) return parsed; } catch(e) {}
  }
  return fallback;
}
function scriptNormalizeCard(card) {
  card = card && typeof card === 'object' ? card : {};
  card.title = cleanTextContent(card.title || '未命名剧本');
  card.tags = Array.isArray(card.tags) ? card.tags.map(cleanTextContent).filter(Boolean) : [];
  card.world = cleanTextContent(card.world || '一个等待展开的世界。');
  card.worldDetail = cleanTextContent(card.worldDetail || '');
  card.conflict = cleanTextContent(card.conflict || '人物之间存在尚未解开的矛盾与牵引。');
  card.characters = Array.isArray(card.characters) ? card.characters : [];
  card.characters = card.characters.map(function(c, i) {
    c = c && typeof c === 'object' ? c : {};
    return {
      name: cleanTextContent(c.name || ('角色' + (i + 1))),
      role: cleanTextContent(c.role || '重要人物'),
      age: cleanTextContent(c.age || ''),
      appearance: cleanTextContent(c.appearance || ''),
      personality: cleanTextContent(c.personality || ''),
      background: cleanTextContent(c.background || ''),
      speechStyle: cleanTextContent(c.speechStyle || ''),
      goal: cleanTextContent(c.goal || ''),
      fear: cleanTextContent(c.fear || ''),
      relationships: cleanTextContent(c.relationships || ''),
      quirk: cleanTextContent(c.quirk || ''),
      secret: cleanTextContent(c.secret || '')
    };
  }).filter(function(c) { return c.name; });
  if (card.characters.length < 2) throw new Error('API 返回的角色数量不足，至少需要2个角色');
  card.characters = card.characters.slice(0, 6);
  card.opening = cleanTextContent(card.opening || '故事开始了。');
  card.directions = Array.isArray(card.directions) ? card.directions.map(cleanTextContent).filter(Boolean).slice(0, 3) : [];
  card.chapters = Number(card.chapters) || 20;
  card.chapterGoals = Array.isArray(card.chapterGoals) ? card.chapterGoals.map(cleanTextContent).filter(Boolean) : [];
  card.ending = cleanTextContent(card.ending || '开放结局');
  return card;
}
function scriptNormalizeStoryJson(json) {
  json = json && typeof json === 'object' ? json : {};
  json.narrator = cleanTextContent(json.narrator || '');
  json.dialogues = Array.isArray(json.dialogues) ? json.dialogues : [];
  json.dialogues = json.dialogues.map(function(d) {
    d = d && typeof d === 'object' ? d : {};
    return {
      character: cleanTextContent(d.character || d.name || ''),
      action: cleanTextContent(d.action || ''),
      text: cleanTextContent(d.text || d.dialogue || d.content || ''),
      innerThought: cleanTextContent(d.innerThought || '')
    };
  }).filter(function(d) { return d.character && d.text; }).slice(0, 3);
  json.options = Array.isArray(json.options) ? json.options.map(cleanTextContent).filter(Boolean).slice(0, 3) : [];
  if (!json.narrator && json.dialogues.length === 0) throw new Error('API 返回内容不符合剧情 JSON 格式');
  return json;
}
// ===================== Custom Input =====================
function scriptShowCustom() {
  scriptShowView('scriptCustomView');
}
// ===================== Generation =====================
async function scriptGenerateFromTags() {
  if (scriptSelectedTags.length === 0) { alert('请至少选择一个标签'); return; }
  scriptLastGenerateInput = scriptSelectedTags.join(', ');
  scriptLastGenerateMode = 'tags';
  await scriptGenerate('根据以下标签组合生成剧本大纲：' + scriptSelectedTags.join('、'));
}
async function scriptGenerateFromCustom() {
  const desc = document.getElementById('scriptCustomDesc').value.trim();
  if (!desc) { alert('请输入故事描述'); return; }
  scriptLastGenerateInput = desc;
  scriptLastGenerateMode = 'custom';
  await scriptGenerate('根据以下描述生成剧本大纲：' + desc);
}
async function scriptRegenerate() {
  if (!scriptLastGenerateInput) return;
  const prompt = scriptLastGenerateMode === 'tags'
    ? '根据以下标签组合生成剧本大纲：' + scriptLastGenerateInput
    : '根据以下描述生成剧本大纲：' + scriptLastGenerateInput;
  await scriptGenerate(prompt);
}
async function scriptGenerate(userPrompt) {
  if (scriptIsGenerating) return;
  scriptIsGenerating = true;
  scriptShowView('scriptCardView');
  const content = document.getElementById('scriptCardContent');
  content.innerHTML = '<div class="script-loading"><div class="script-loading-dots"><span></span><span></span><span></span></div>AI 正在构思剧本...</div>';
  if (!scriptHasUsableApiConfig()) {
    content.innerHTML = '<div style="padding:30px;text-align:center;color:#999;font-size:12px;">请先在聊天软件的 API Config 中连接并保存 API</div>';
    scriptIsGenerating = false;
    return;
  }
  const sysPrompt = `你是一个专业的互动剧本生成器。用户会提供标签或描述，你需要生成一份完整的剧本大纲。
请严格按以下JSON格式输出（不要输出其他内容）：
{
  "title": "剧本标题",
  "tags": ["标签1", "标签2", ...],
  "world": "详细的世界背景描述（时代、地点、社会环境、氛围，4-6句话）",
  "worldDetail": "更深层的背景设定（权力结构、社会规则、关键事件、文化特色等，3-5句话）",
  "conflict": "核心矛盾描述（2-3句话，要具体）",
  "characters": [
    {
      "name": "角色全名",
      "role": "剧中身份（职业/社会角色）",
      "age": "年龄",
      "appearance": "外貌特征描述（3-4个关键词或1-2句话）",
      "personality": "性格特点（至少3个关键词）",
      "background": "详细背景故事（3-5句话，包含成长经历、家庭背景、重要转折）",
      "speechStyle": "说话风格（例如：温柔低语、冷淡疏离、热情洋溢、毒舌但关心人、口头禅等）",
      "goal": "角色的核心目标和动机",
      "fear": "角色最害怕的事情或内心弱点",
      "relationships": "与其他角色的关系描述",
      "quirk": "独特的习惯或小癖好",
      "secret": "隐藏的秘密或不为人知的一面"
    }
  ],
  "opening": "故事起点场景描述（要有画面感，3-4句话）",
  "directions": [
    "故事线分支1描述",
    "故事线分支2描述",
    "故事线分支3描述"
  ],
  "chapters": 8,
  "chapterGoals": ["第一章目标", "第二章目标", ...],
  "ending": "HE/BE/开放结局"
}
要求：
1. 角色至少2个，最多6个
2. 每个角色的人设要立体丰满，有血有肉，像真实的人
3. 角色之间的关系要复杂有张力
4. 故事要有层次感，有起承转合
5. 不要使用任何emoji
6. 所有内容用中文
7. 章节数建议20-25章
8. 每个角色的说话风格要独特且有辨识度`;
  try {
    const text = await scriptCallChatApi([
      { role: 'system', content: sysPrompt },
      { role: 'user', content: userPrompt }
    ], { temperature: 0.9, max_tokens: 5000 });
    const parsed = scriptParseJsonFromAi(text, null, 'object');
    if (!parsed) throw new Error('API 返回内容不符合剧本 JSON 格式');
    scriptCurrentCard = scriptNormalizeCard(parsed);
    scriptRenderCard();
  } catch (e) {
    console.warn('Script generation failed:', e);
    content.innerHTML = `<div style="padding:30px;text-align:center;color:#999;font-size:12px;">生成失败: ${e.message}<br><br><button class="script-generate-btn" style="width:auto;display:inline-block;padding:10px 20px;" onclick="scriptRegenerate()">重试</button></div>`;
  }
  scriptIsGenerating = false;
}
function scriptRenderCard() {
  const card = scriptCurrentCard;
  if (!card) return;
  const content = document.getElementById('scriptCardContent');
  let html = '';
  // Title
  html += `<div class="script-card-block"><div class="script-card-label">剧本名 title</div><div class="script-card-value title-val">${card.title || '未命名'}</div></div>`;
  // Tags
  html += `<div class="script-card-block"><div class="script-card-label">标签列表 tags</div><div class="script-card-tags">${(card.tags || []).map(t => `<span class="script-card-tag">${t}</span>`).join('')}</div></div>`;
  // World
  html += `<div class="script-card-block"><div class="script-card-label">世界背景 world</div><div class="script-card-value">${card.world || ''}</div></div>`;
  // Conflict
  html += `<div class="script-card-block"><div class="script-card-label">核心矛盾 conflict</div><div class="script-card-value">${card.conflict || ''}</div></div>`;
  // Characters
  html += `<div class="script-card-block"><div class="script-card-label">人物表 characters</div>`;
  (card.characters || []).forEach(c => {
    const initial = (c.name || '?')[0];
    html += `<div class="script-char-item">
      <div class="script-char-avatar">${initial}</div>
      <div class="script-char-info">
        <div class="script-char-name">${c.name}</div>
        <div class="script-char-role">${c.role || ''}</div>
        <div class="script-char-traits">${c.personality || ''}</div>
      </div>
    </div>`;
  });
  html += `</div>`;
  // Opening
  html += `<div class="script-card-block"><div class="script-card-label">故事起点 opening</div><div class="script-card-value">${card.opening || ''}</div></div>`;
  // Directions
  html += `<div class="script-card-block"><div class="script-card-label">预设走向 directions</div>`;
  (card.directions || []).forEach((d, i) => {
    html += `<div class="script-direction-item"><div class="script-direction-num">路线 ${i + 1}</div><div class="script-direction-text">${d}</div></div>`;
  });
  html += `</div>`;
  // Chapters
  html += `<div class="script-card-block"><div class="script-card-label">预计章节 chapters</div><div class="script-card-value">${card.chapters || 8} 章</div>`;
  if (card.chapterGoals && card.chapterGoals.length > 0) {
    html += `<div style="margin-top:8px;">`;
    card.chapterGoals.forEach((g, i) => {
      html += `<div style="font-size:11px;color:#666;padding:3px 0;"><span style="color:#999;font-family:'DM Mono',monospace;font-size:9px;">CH.${i+1}</span> ${g}</div>`;
    });
    html += `</div>`;
  }
  html += `</div>`;
  // Ending
  html += `<div class="script-card-block"><div class="script-card-label">结局预告 ending</div><div class="script-card-value">${card.ending || '未定'}</div></div>`;
  content.innerHTML = html;
}
// ===================== Role Assignment =====================
