  document.getElementById('scriptReaderTitle').textContent = a.card.title || '重读';
  let html = `<div style="margin-bottom:16px;"><div class="script-card-label">剧本 / ${a.card.title}</div>
    <div class="script-card-tags" style="margin-top:4px;">${(a.card.tags || []).map(t => `<span class="script-card-tag">${t}</span>`).join('')}</div>
  </div>`;
  html += '<div style="border-top:1px solid #eee;padding-top:12px;">';
