function scriptReplayFromNode(idx) {
  const archives = JSON.parse(localStorage.getItem('mono_script_archives') || '[]');
  const a = archives[idx];
  if (!a || !a.decisionPoints || a.decisionPoints.length === 0) {
    alert('此存档没有关键抉择节点');
    return;
  }
  let nodeHtml = '<div style="font-size:12px;color:#888;margin-bottom:12px;">选择一个关键抉择节点重新开始:</div>';
  a.decisionPoints.forEach((dp, di) => {
    nodeHtml += `<div class="script-direction-item" onclick="scriptRestartFromNode(${idx}, ${di})">
      <div class="script-direction-num">第 ${dp.chapter} 章 / 抉择点 ${di + 1}</div>
      <div class="script-direction-text">${dp.description}</div>
    </div>`;
  });
  scriptShowView('scriptArchiveView');
  document.getElementById('scriptArchiveContent').innerHTML = nodeHtml;
}
function scriptRestartFromNode(archiveIdx, nodeIdx) {
  const archives = JSON.parse(localStorage.getItem('mono_script_archives') || '[]');
  const a = archives[archiveIdx];
  if (!a) return;
  const dp = a.decisionPoints[nodeIdx];
  if (!dp) return;
  // Restore state up to that point
  scriptCurrentCard = a.card;
  scriptMyRole = a.myRole;
  scriptTotalChapters = (a.totalChapters === 'infinite' || !a.totalChapters) ? Infinity : a.totalChapters;
  scriptCurrentChapter = dp.chapter;
  scriptStoryMessages = a.messages.slice(0, dp.msgIndex);
  scriptStoryHistory = [...scriptStoryMessages];
  scriptMessageCount = scriptStoryMessages.length;
  scriptDecisionPoints = a.decisionPoints.slice(0, nodeIdx);
  scriptStoryStartTime = Date.now();
  scriptShowView('scriptStoryView');
  document.getElementById('scriptStoryTitle').textContent = scriptCurrentCard.title || '剧本';
  document.getElementById('scriptChapterLabel').textContent = '第 ' + scriptCurrentChapter + ' 章';
  document.getElementById('scriptChapterCount').textContent = '第 ' + scriptCurrentChapter + ' 章';
  document.getElementById('scriptChapterFill').style.width = ((scriptCurrentChapter % 5) / 5 * 100) + '%';
  // Render character select bar
  scriptTalkTarget = null;
  scriptRenderCharSelectBar();
  // Re-render messages
  const area = document.getElementById('scriptChatArea');
  area.innerHTML = '';
  scriptStoryMessages.forEach(m => {
    const div = document.createElement('div');
    if (m.type === 'narrator') {
      div.className = 'script-msg-row narrator';
      div.innerHTML = `<div class="script-msg-bubble">${m.text}</div>`;
    } else if (m.type === 'user') {
      const myChar = scriptCurrentCard.characters[scriptMyRole];
      const initial = (myChar.name || '?')[0];
      div.className = 'script-msg-row user';
      div.innerHTML = `<div class="script-msg-bubble">${m.text}</div>
        <div class="script-msg-meta"><div class="script-msg-avatar" style="background:#fff;color:#1a1a1a;border:1px solid #ddd;">${initial}</div><div class="script-msg-name">${myChar.name}</div></div>`;
    } else {
      const initial = (m.charName || '?')[0];
      div.className = 'script-msg-row npc';
      div.innerHTML = `<div class="script-msg-meta"><div class="script-msg-avatar">${initial}</div><div class="script-msg-name">${m.charName}</div></div><div class="script-msg-bubble">${m.text}</div>`;
    }
    area.appendChild(div);
  });
  area.scrollTop = area.scrollHeight;
  // Show the decision point again
  const overlay = document.getElementById('scriptDecisionOverlay');
  overlay.style.display = 'flex';
  document.getElementById('scriptDecisionDesc').textContent = dp.description;
  document.getElementById('scriptDecisionOptions').innerHTML = dp.options.map((opt, i) =>
    `<button class="script-option-btn" onclick="scriptMakeDecision(${i}, '${opt.replace(/'/g, "\\'")}')" style="margin-bottom:6px;">${opt}</button>`
  ).join('');
}
function scriptExportArchive() {
  // Export current reader content as text
  const content = document.getElementById('scriptReaderContent');
  if (!content) return;
  const text = content.innerText;
  const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = '剧本导出.txt';
  a.click();
  URL.revokeObjectURL(url);
}
function scriptExportArchiveByIndex(idx) {
  const archives = JSON.parse(localStorage.getItem('mono_script_archives') || '[]');
  const a = archives[idx];
  if (!a) return;
  let text = '剧本: ' + (a.card.title || '未命名') + '\n';
  text += '标签: ' + (a.card.tags || []).join(', ') + '\n';
  text += '日期: ' + (a.date || '') + '\n';
  text += '='.repeat(40) + '\n\n';
  a.messages.forEach(m => {
    if (m.type === 'narrator') {
      text += '[旁白] ' + m.text + '\n\n';
    } else if (m.type === 'user') {
      const myChar = a.card.characters[a.myRole];
      text += (myChar ? myChar.name : '我') + ': ' + m.text + '\n\n';
    } else {
      text += (m.charName || '角色') + ': ' + m.text + '\n\n';
    }
  });
  const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = (a.card.title || '剧本') + '_导出.txt';
  link.click();
  URL.revokeObjectURL(url);
}
function scriptDeleteArchive(idx) {
  if (!confirm('确定删除此存档？')) return;
  const archives = JSON.parse(localStorage.getItem('mono_script_archives') || '[]');
  archives.splice(idx, 1);
  localStorage.setItem('mono_script_archives', JSON.stringify(archives));
  scriptRenderArchives();
}
