// ── 语音 ──
// ── Group Chat: Real Voice Recording ──
// Reuses the same _vr* engine variables as solo chat.
// _vrMode tracks which chat context is active: 'solo' or 'gc'
let _vrMode = 'solo';
function _gcVroTimerEl()   { return document.getElementById('gcVroTimer'); }
function _gcVroHintEl()    { return document.getElementById('gcVroHint'); }
function _gcVroActionsEl() { return document.getElementById('gcVroActions'); }
function _gcVroSlideEl()   { return document.getElementById('gcVroSlideHint'); }
function _gcVroOverlay()   { return document.getElementById('gcVoiceRecordOverlay'); }
async function startGcVoiceRecord(e) {
  if (e) e.preventDefault();
  if (_vrIsRecording) return;
  if (!currentGroupId) { alert('请先开启群聊'); return; }
  _vrMode = 'gc';
  _vrStartY = e ? (e.touches ? e.touches[0].clientY : e.clientY) : null;
  _vrIsSlideUp = false;
  _vrTranscript = '';
  _vrAudioChunks = [];
  _vrAudioBlob = null;
  try {
    _vrStream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch(err) {
    alert('无法使用麥克风：' + err.message + '\n请确保已授予麥克风权限。');
    return;
  }
  const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus'
    : MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm'
    : MediaRecorder.isTypeSupported('audio/mp4') ? 'audio/mp4' : '';
  _vrMediaRecorder = new MediaRecorder(_vrStream, mimeType ? { mimeType } : {});
  _vrMediaRecorder.ondataavailable = ev => { if (ev.data.size > 0) _vrAudioChunks.push(ev.data); };
  _vrMediaRecorder.onstop = () => { _vrAudioBlob = new Blob(_vrAudioChunks, { type: _vrMediaRecorder.mimeType || 'audio/webm' }); };
  _vrMediaRecorder.start(100);
  _vrIsRecording = true;
  const SRClass = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (SRClass) {
    try {
      _vrRecognition = new SRClass();
      _vrRecognition.continuous = true;
      _vrRecognition.interimResults = true;
      _vrRecognition.lang = _getVoiceLangConfig().webSpeechLang;
      _vrRecognition.onresult = ev => {
        let t = '';
        for (let i = 0; i < ev.results.length; i++) t += ev.results[i][0].transcript;
        _vrTranscript = t;
        if (_gcVroHintEl() && !_vrIsSlideUp) _gcVroHintEl().textContent = t || '正在录音中⋯';
      };
      _vrRecognition.onerror = () => { _vrRecognition = null; };
      _vrRecognition.start();
    } catch(e) { _vrRecognition = null; }
  }
  _vrSeconds = 0;
  if (_gcVroTimerEl()) _gcVroTimerEl().textContent = '0:00';
  _vrTimerInterval = setInterval(() => {
    _vrSeconds++;
    if (_gcVroTimerEl()) _gcVroTimerEl().textContent = fmtVoiceTime(_vrSeconds);
    if (_vrSeconds >= 60) stopGcVoiceRecord();
  }, 1000);
  const overlay = _gcVroOverlay();
  if (overlay) { overlay.style.display = 'flex'; }
  if (_gcVroSlideEl()) _gcVroSlideEl().style.display = 'flex';
  if (_gcVroActionsEl()) _gcVroActionsEl().classList.remove('show');
  if (_gcVroHintEl()) _gcVroHintEl().textContent = (apiConfig.url && apiConfig.key) ? '正在录音⋯（识别由 Whisper 处理）' : '正在录音中⋯';
  const btn = document.getElementById('gcChatVoiceBtn');
  if (btn) btn.classList.add('recording');
  const moveHandler = (ev) => {
    if (!_vrIsRecording) return;
    const curY = ev.touches ? ev.touches[0].clientY : ev.clientY;
    const dy = (_vrStartY || curY) - curY;
    if (dy > 40 && !_vrIsSlideUp) {
      _vrIsSlideUp = true;
      if (_gcVroSlideEl()) _gcVroSlideEl().style.display = 'none';
      if (_gcVroActionsEl()) _gcVroActionsEl().classList.add('show');
      if (_gcVroHintEl()) _gcVroHintEl().textContent = '选择发送方式';
    } else if (dy <= 20 && _vrIsSlideUp) {
      _vrIsSlideUp = false;
      if (_gcVroSlideEl()) _gcVroSlideEl().style.display = 'flex';
      if (_gcVroActionsEl()) _gcVroActionsEl().classList.remove('show');
      if (_gcVroHintEl()) _gcVroHintEl().textContent = _vrTranscript || '正在录音中⋯';
    }
  };
  if (btn) {
    btn.addEventListener('mousemove', moveHandler);
    btn.addEventListener('touchmove', moveHandler, { passive: true });
    btn._vrMoveHandler = moveHandler;
  }
}
function _stopGcRecordingMedia() {
  _vrIsRecording = false;
  clearInterval(_vrTimerInterval);
  if (_vrRecognition) { try { _vrRecognition.stop(); } catch(e) {} _vrRecognition = null; }
  if (_vrMediaRecorder && _vrMediaRecorder.state !== 'inactive') _vrMediaRecorder.stop();
  if (_vrStream) { _vrStream.getTracks().forEach(t => t.stop()); _vrStream = null; }
  const btn = document.getElementById('gcChatVoiceBtn');
  if (btn) {
    btn.classList.remove('recording', 'ready-send');
    if (btn._vrMoveHandler) {
      btn.removeEventListener('mousemove', btn._vrMoveHandler);
      btn.removeEventListener('touchmove', btn._vrMoveHandler);
      btn._vrMoveHandler = null;
    }
  }
}
function stopGcVoiceRecord(e) {
  if (!_vrIsRecording || _vrMode !== 'gc') return;
  if (e) e.preventDefault();
  _stopGcRecordingMedia();
  if (_vrSeconds < 1) { _closeGcVroOverlay(); return; }
  if (_gcVroSlideEl()) _gcVroSlideEl().style.display = 'none';
  if (_gcVroActionsEl()) _gcVroActionsEl().classList.add('show');
  if (_gcVroHintEl()) _gcVroHintEl().textContent = _vrTranscript || '（录音完成，请选择发送方式）';
}
function _closeGcVroOverlay() {
  const overlay = _gcVroOverlay();
  if (overlay) overlay.style.display = 'none';
  if (_gcVroActionsEl()) _gcVroActionsEl().classList.remove('show');
  if (_gcVroSlideEl()) _gcVroSlideEl().style.display = 'flex';
  _vrAudioBlob = null; _vrTranscript = ''; _vrSeconds = 0; _vrMode = 'solo';
}
function cancelGcVoiceRecord() {
  if (_vrIsRecording) _stopGcRecordingMedia();
  _closeGcVroOverlay();
}
async function sendGcVoiceAsText() {
  if (_gcVroHintEl()) _gcVroHintEl().textContent = '正在识别语音⋯';
  if (_gcVroActionsEl()) _gcVroActionsEl().classList.remove('show');
  if (!apiConfig.url || !apiConfig.key) {
    _closeGcVroOverlay();
    alert('需要设定 API Key 才能使用语音识别。');
    return;
  }
  const transcript = await _resolveTranscript();
  _closeGcVroOverlay();
  if (!transcript) { alert('无法识别语音内容，请重新嘗试。'); return; }
  const input = document.getElementById('gcInput');
  if (input) { input.value = transcript; input.focus(); }
}
async function sendGcVoiceAsVoice() {
  if (_gcVroHintEl()) _gcVroHintEl().textContent = (apiConfig.url && apiConfig.key) ? '正在识别语音⋯' : '发送中⋯';
  if (_gcVroActionsEl()) _gcVroActionsEl().classList.remove('show');
  const transcript = (apiConfig.url && apiConfig.key) ? await _resolveTranscript() : (_vrTranscript || null);
  _closeGcVroOverlay();
  const g = groups.find(x => x.id === currentGroupId);
  if (!g) return;
  const duration = fmtVoiceTime(_vrSeconds || 1);
  g.messages.push({
    role: 'user',
    type: 'voice',
    content: '[语音]',
    voiceText: transcript || '',
    voiceDuration: duration,
    timestamp: Date.now()
  });
  saveGroups();
  renderGroupMessages(g);
  gcTriggerResponses(g, transcript ? '[语音消息] ' + transcript : '[语音消息（内容不明）]');
}
