function closeGcRedEnvelopeModal() {
  document.getElementById('gcRedEnvelopeModal').classList.remove('show');
}
function sendGcRedEnvelope() {
  const amount = parseFloat(document.getElementById('gcRedEnvAmount').value);
  const count = parseInt(document.getElementById('gcRedEnvCount').value) || 1;
  const note = document.getElementById('gcRedEnvNote').value.trim() || '恭喜发財，大吉大利';
  if (!amount || amount <= 0) { alert('请输入紅包金额'); return; }
  if (count < 1) { alert('紅包个数至少为1'); return; }
  const g = groups.find(x => x.id === currentGroupId);
  if (!g) return;
  walletDeduct(amount, '发紅包 (' + count + '个)');
  g.messages.push({
    role: 'user',
    type: 'redenvelope',
    content: note,
    redEnvelope: {
      id: 'env_' + Date.now(),
      totalAmount: amount,
      count: count,
      claimed: []
    },
    timestamp: Date.now()
  });
  saveGroups();
  renderGroupMessages(g);
  closeGcRedEnvelopeModal();
  // AI characters may grab the red envelope
  setTimeout(() => gcAiGrabRedEnvelopes(g, g.messages.length - 1), 1000 + Math.random() * 2000);
}
function grabGcRedEnvelope(msgIdx) {
  const g = groups.find(x => x.id === currentGroupId);
  if (!g || !g.messages[msgIdx]) return;
  const msg = g.messages[msgIdx];
  if (!msg.redEnvelope) return;
  const env = msg.redEnvelope;
  const claimed = env.claimed || [];
  if (claimed.some(c => c.claimedBy === 'user')) return; // Already claimed
  if (claimed.length >= env.count) return; // All claimed
  const remaining = env.totalAmount - claimed.reduce((s, c) => s + c.amount, 0);
  const remainCount = env.count - claimed.length;
  let amt;
  if (remainCount === 1) {
    amt = remaining;
  } else {
    // Random amount: at least 0.01, at most 2x average
    const avg = remaining / remainCount;
    amt = Math.max(0.01, Math.min(remaining - 0.01 * (remainCount - 1), Math.random() * avg * 2));
  }
  amt = Math.round(amt * 100) / 100;
  env.claimed.push({ claimedBy: 'user', amount: amt, time: Date.now() });
  if (!env.claimed) env.claimed = [];
  saveGroups();
  renderGroupMessages(g);
  walletCredit(amt, '搶紅包', '', '');
  // After user grabs, trigger AI characters to grab too
  if (env.claimed.length < env.count) {
    setTimeout(() => gcAiGrabRedEnvelopes(g, msgIdx), 500 + Math.random() * 1500);
  }
}
async function gcAiGrabRedEnvelopes(g, msgIdx) {
  if (!g.messages[msgIdx]) return;
  const env = g.messages[msgIdx].redEnvelope;
  if (!env) return;
  const members = (g.memberIds || []).map(mid => personas.find(p => p.id == mid)).filter(Boolean);
  // Shuffle members for randomness
  const shuffled = [...members].sort(() => Math.random() - 0.5);
  for (const member of shuffled) {
    if ((env.claimed || []).length >= env.count) break;
    if ((env.claimed || []).some(c => c.claimedBy === member.id)) continue;
    // 80% chance AI will grab
    if (Math.random() > 0.8) continue;
    await new Promise(r => setTimeout(r, 500 + Math.random() * 2000));
    const claimed = env.claimed || [];
    const remaining = env.totalAmount - claimed.reduce((s, c) => s + c.amount, 0);
    const remainCount = env.count - claimed.length;
    if (remainCount <= 0 || remaining <= 0) break;
    let amt;
    if (remainCount === 1) {
      amt = remaining;
    } else {
      const avg = remaining / remainCount;
      amt = Math.max(0.01, Math.min(remaining - 0.01 * (remainCount - 1), Math.random() * avg * 2));
    }
    amt = Math.round(amt * 100) / 100;
    env.claimed.push({ claimedBy: member.id, amount: amt, time: Date.now() });
    saveGroups();
    renderGroupMessages(g);
  }
}

// ── 群聊角色红包低频控制：避免角色频繁主动发红包 ──
function gcShouldRoleSendRedEnvelopeRarely(g, responder) {
  try {
    const msgs = Array.isArray(g && g.messages) ? g.messages : [];
    const now = Date.now();
    const recent = msgs.slice(-80);
    // 群里最近已经有人发过红包，则不要继续叠加刷屏。
    const recentRed = [...recent].reverse().find(m => m && m.type === 'redenvelope');
    if (recentRed && now - (recentRed.timestamp || 0) < 3 * 60 * 60 * 1000) return false;
    // 同一个角色 24 小时内最多主动发一次红包。
    const sameRoleRed = [...msgs].reverse().find(m => m && m.type === 'redenvelope' && String(m.role) === String(responder && responder.id));
    if (sameRoleRed && now - (sameRoleRed.timestamp || 0) < 24 * 60 * 60 * 1000) return false;
    const lastText = msgs.slice(-12).map(m => String(m && m.content || '')).join(' ');
    const hasStrongContext = /红包|紅包|抢红包|搶紅包|生日|过年|新年|春节|恭喜|中奖|庆祝|慶祝|发钱|請客|请客|奶茶钱|群福利|开心一下|开心一下/.test(lastText);
    // 有明确红包/庆祝/请客语境时才小概率触发；没有语境时几乎不主动发。
    return Math.random() < (hasStrongContext ? 0.08 : 0.003);
  } catch (e) {
    return false;
  }
}

// ── 角色也可以发紅包（受低频控制） ──
async function gcRoleSendRedEnvelope(g, responder) {
  if (!gcShouldRoleSendRedEnvelopeRarely(g, responder)) return;
  const members = (g.memberIds || []).map(mid => personas.find(p => p.id == mid)).filter(Boolean);
  const count = Math.min(members.length + 1, Math.floor(Math.random() * 3) + 2);
  const amount = Math.round((Math.random() * 50 + 5) * 100) / 100;
  const notes = ['恭喜发財', '紅包来了～', '搶紅包！', '开心一下', '小意思', '请大家喝奶茶', '发个紅包熱鬧一下'];
  const note = notes[Math.floor(Math.random() * notes.length)];
  g.messages.push({
    role: responder.id,
    type: 'redenvelope',
    content: note,
    redEnvelope: {
      id: 'env_' + Date.now(),
      totalAmount: amount,
      count: count,
      claimed: []
    },
    timestamp: Date.now()
  });
  saveGroups();
  renderGroupMessages(g);
}
// ── 自动回覆 ──
async function triggerGcAuto回复() {
  const g = groups.find(x => x.id === currentGroupId);
  if (!g) return;
  if (!apiConfig.url || !apiConfig.key || !apiConfig.model) { alert('请先配置API'); return; }
  const members = (g.memberIds || []).map(mid => personas.find(p => p.id == mid)).filter(Boolean);
  if (members.length === 0) return;
  // Find the last user message to parse @mentions
  const lastUserMsg = [...(g.messages || [])].reverse().find(m => m.role === 'user');
  const userContent = lastUserMsg ? lastUserMsg.content || '' : '';
  
  // Parse @mentions in the last user message
  const mentionedNames = [];
  const mentionRegex = /@(\S+)/g;
  let mm;
  while ((mm = mentionRegex.exec(userContent)) !== null) {
    mentionedNames.push(mm[1]);
  }
  // Determine which characters should reply:
  // If user @mentioned specific characters → those characters MUST reply; others MAY reply
  // If no @mention → ALL characters reply
  let must回复 = [];
  let may回复 = [];
  
  if (mentionedNames.length > 0) {
    members.forEach(m => {
      const isMentioned = mentionedNames.some(n => m.name.includes(n) || n.includes(m.name));
      if (isMentioned) must回复.push(m);
      else may回复.push(m);
    });
    // If @mention matched nobody, treat as no-mention (all reply)
    if (must回复.length === 0) must回复 = [...members];
  } else {
    // No @mention: all characters reply
    must回复 = [...members];
  }
  // Combine: must-reply first, then maybe some of may-reply (70% chance each)
  const responders = [...must回复];
  may回复.forEach(m => { if (Math.random() < 0.7) responders.push(m); });
  // Shuffle responders (preserve must-reply first roughly)
  const mustSet = new Set(must回复.map(m => m.id));
  const shuffledMust = [...must回复].sort(() => Math.random() - 0.5);
  const shuffledMay = may回复.filter(m => responders.includes(m)).sort(() => Math.random() - 0.5);
  const finalResponders = [...shuffledMust, ...shuffledMay];
  document.getElementById('gcTypingArea').style.display = 'flex';
  for (const responder of finalResponders) {
    try {
      const minCount = Math.max(1, responder.min回复Count || 1);
      const maxCount = Math.max(minCount, responder.max回复Count || 3);
      const msgCount = Math.floor(Math.random() * (maxCount - minCount + 1)) + minCount;
      // Small initial delay before first message
      await new Promise(r => setTimeout(r, 600 + Math.random() * 1200));
      // Request ALL messages in ONE call so the model knows what it already said
      // and won't repeat itself across messages
      const replies = await gcFetchAiReplies(g, responder, msgCount);
      if (!replies || replies.length === 0) continue;
      for (let i = 0; i < replies.length; i++) {
        const rawReply = replies[i];
        if (!rawReply) continue;
        const _gcAuto = (typeof monoGcAttachAutoQuote === 'function') ? monoGcAttachAutoQuote(g, responder.id, rawReply) : { content: rawReply, quote: null };
        const reply = _gcAuto.content || rawReply;
        const replyMentions = [];
        const rm = /@(\S+)/g;
        let rMatch;
        while ((rMatch = rm.exec(reply)) !== null) replyMentions.push(rMatch[1]);
        const _gcMsgObj = { role: responder.id, content: reply, mentions: replyMentions, timestamp: Date.now() };
        if (_gcAuto.quote) {
          _gcMsgObj.quote = _gcAuto.quote;
          _gcMsgObj.quoteFrom = _gcAuto.quote.from;
          _gcMsgObj.quoteText = _gcAuto.quote.text;
          _gcMsgObj.quoteType = _gcAuto.quote.type || 'text';
          _gcMsgObj.quoteRole = _gcAuto.quote.role || '';
        }
        g.messages.push(_gcMsgObj);
        // 标记所有用户消息为已读（角色已读）
        g.messages.forEach(function(gm) { if (gm.role === 'user' && !gm._readByChar) gm._readByChar = true; });
        saveGroups();
        renderGroupMessages(g);
        if (g.notificationEnabled !== false) {
          showGroupNotification(g, responder, reply);
        }
        if (i === 0) {
          // 红包不再作为常规群聊随机动作；只有在 gcShouldRoleSendRedEnvelopeRarely 判断通过时才会极低频触发。
          await new Promise(r => setTimeout(r, 1000 + Math.random() * 2000));
          await gcRoleSendRedEnvelope(g, responder);
        }
        if (i < replies.length - 1) {
          await new Promise(r => setTimeout(r, 400 + Math.random() * 800));
        }
      }
    } catch (e) {
      console.warn('Group chat response error for', responder.name, e);
      _showApiErrorToast('群聊 · ' + responder.name + ' 回复失败', e);
    }
  }
  document.getElementById('gcTypingArea').style.display = 'none';
}
// Show a notification toast for group messages
function showGroupNotification(g, sender, text) {
  // Check if notification is enabled for this group
  if (g.notificationEnabled === false) return;
  // Don't show if group chat is currently open/visible
  if (document.getElementById('groupChatPage').classList.contains('active')) return;
  
  const toast = document.getElementById('monoNotifToast');
  const avatarEl = document.getElementById('monoNotifAvatar');
  const nameEl = document.getElementById('monoNotifName');
  const textEl = document.getElementById('monoNotifText');
  
  if (!toast) return;
  
  avatarEl.src = sender.avatar || '';
  nameEl.textContent = g.name + ' · ' + sender.name;
  textEl.textContent = text.substring(0, 60);
  
  toast.classList.add('show');
  setTimeout(() => toast.classList.remove('show'), 4000);
  
  // Add to notification history
  const notifSettings = JSON.parse(localStorage.getItem('mono_notif_settings') || '{}');
  const notifHistory = JSON.parse(localStorage.getItem('mono_notif_history') || '[]');
  notifHistory.unshift({
    type: 'group',
    groupId: g.id,
    groupName: g.name,
    senderName: sender.name,
    senderAvatar: sender.avatar,
    text: text.substring(0, 80),
    time: Date.now()
  });
  if (notifHistory.length > 100) notifHistory.pop();
  localStorage.setItem('mono_notif_history', JSON.stringify(notifHistory));
}
// ── AI 回覆核心函数 ──
// Returns array of reply strings (1 API call for all messages)
async function gcFetchAiReplies(g, responder, count) {
  if (!apiConfig.url || !apiConfig.key || !apiConfig.model) return [];
  const members = (g.memberIds || []).map(mid => personas.find(p => p.id == mid)).filter(Boolean);
  const responderUserIdentity = monoResolveUserIdentityProfile(responder);
  const roomMode = monoResolveGroupUserIdentityMode(g);
  const roomModeInstruction = roomMode === 'same_person'
    ? '【群聊里的用户身份规则】不同 userMaskId 代表同一个真实用户，但每个角色仍只按照自己连接到的用户面具设定、称呼、昵称与记忆来理解和称呼用户。你可以对同一用户使用自己习惯的称呼或@对应面具名，但绝对不能把别的面具细节并入你当前连接面具的记忆。若世界关系图已经把不同用户面具作为不同节点建立关系，则以世界关系图为最高优先级，必须把那些节点视为不同人物。'
    : '【群聊里的用户身份规则】不同 userMaskId 代表不同的人。不同面具的称呼、头像、记忆、理解必须彼此隔离，不能混淆。';
  // Private chat memory
  let memoryContext = '';
  if (g.settings && g.settings.charMemoryShare && g.settings.charMemoryShare[responder.id]) {
    const charHistory = (responder.history || []).slice(-20)
      .map(m => `${m.role === 'user' ? monoResolveUserIdentityProfile(responder, { message: m }).name : responder.name}: ${m.content}`).join('\n');
    if (charHistory) memoryContext = `\n【你与${responderUserIdentity.name}的私聊记忆（仅你知道）】\n${charHistory}\n`;
  }
  // Full live transcript — read g.messages every time so each character
  // sees what the previous characters in this round already said
  const allMessages = g.messages || [];
  function fmtMsg(m) {
    const sName = m.role === 'user'
      ? monoGroupUserName(g, m)
      : (personas.find(p => p.id == m.role) || {}).name || '?';
    const qPrefix = (m.quoteFrom || (m.quote && m.quote.from)) ? `（引用/回复 ${m.quoteFrom || (m.quote && m.quote.from)}：${m.quoteText || (m.quote && m.quote.text) || ''}）` : '';
    if (m.type === 'redenvelope') return `${sName}: ${qPrefix}[发了一个红包：${m.content}]`;
    if (m.type === 'sticker')     return `${sName}: ${qPrefix}[发了一个表情包]`;
    if (m.type === 'voice')       return `${sName}: ${qPrefix}[语音] ${m.voiceText || ''}`;
    return `${sName}: ${qPrefix}${m.content || ''}`;
  }
  const transcript = allMessages.slice(-60).map(fmtMsg).join('\n');
  const wbInjection = typeof buildWorldBookInjection === 'function'
    ? buildWorldBookInjection(transcript, responder.id) : '';
  const otherMembers = members.filter(m => m.id !== responder.id).map(m => m.name).join('、');
  // count=1 → ask for 1 plain message; count>1 → ask for N messages separated by ###
  const countInstruction = count <= 1
    ? '只发1条消息，不使用###分隔符。'
    : `发${count}条消息，每条消息之间用"###"分隔。每条消息意思和内容必须不同，要递进或补充，绝对不能重复相同意思。`;
  // Detect language override from persona
  const _gcPersonaText = (responder.persona || '') + ' ' + (wbInjection || '');
  let _gcLangOverride = '';
  if (/日语回覆|日本语回覆|用日语|用日本语|以日语|以日本语|日语.*回覆|日文回覆|用日文|以日文|Japanese.*reply|speak.*Japanese|日语回复|用日语|以日语/i.test(_gcPersonaText)) {
    _gcLangOverride = '\n【语言设定：强制】角色人设要求你必须全程使用日语（日本语）回覆。';
  } else if (/韩语回覆|韩文回覆|用韩语|用韩文|以韩语|以韩文|Korean.*reply|speak.*Korean|한국어로|用韩语|以韩语|韩语回复/i.test(_gcPersonaText)) {
    _gcLangOverride = '\n【语言设定：强制】角色人设要求你必须全程使用韩语（한국어）回覆。';
  } else if (/英语回覆|英文回覆|用英语|用英文|以英语|以英文|English.*reply|speak.*English|英语回复|用英语|以英语/i.test(_gcPersonaText)) {
    _gcLangOverride = '\n【语言设定：强制】角色人设要求你必须全程使用英语（English）回覆。';
  } else if (/粤语回覆|粤语回覆|粤语回复|粤语回复|广东话回覆|廣东话回覆|广东话回复|廣东话回复|用粤语|用粤语|用广东话|用廣东话|以粤语|以粤语|以广东话|以廣东话|港式中文|香港话|香港话|Cantonese.*reply|speak.*Cantonese|廣东话/i.test(_gcPersonaText)) {
    _gcLangOverride = '\n【语言设定：强制】角色人设要求你必须全程使用粤语（廣东话）回覆，包括粤语词汇、语气词和表达方式，不可使用普通话书面语。';
  } else if (/俄语回覆|俄语回覆|俄语回复|俄语回复|俄文回覆|俄文回复|用俄语|用俄语|用俄文|以俄语|以俄语|以俄文|Russian.*reply|speak.*Russian|русский|по-русски/i.test(_gcPersonaText)) {
    _gcLangOverride = '\n【语言设定：强制】角色人设要求你必须全程使用俄语（Русский）回复，不可使用中文。';
  }
  // ── 多世界：实时注入群聊关系图记忆 ──
  const _gcMemberNames = members.map(m => m.name);
  const _gcRelInject = (typeof _mwBuildRelInjectForChar === 'function')
    ? _mwBuildRelInjectForChar(responder.name, _gcMemberNames, true)
    : '';
  const sysPrompt = `${typeof LANG_SYSTEM_PREFIX !== 'undefined' ? LANG_SYSTEM_PREFIX : ''}${typeof STYLE_INSTRUCTIONS !== 'undefined' ? STYLE_INSTRUCTIONS : ''}
你是「${responder.name}」。人设：${responder.persona}。${_gcLangOverride}
当前场景：群聊「${g.name}」。
群成员：${members.map(m => m.name).join('、')}、${monoGroupUserName(g) || responderUserIdentity.name}（用户）。
其他角色：${otherMembers || '（无）'}。
${roomModeInstruction}
${wbInjection}${memoryContext}${_gcRelInject}
【完整群聊记录（最近60条）】
${transcript || '（暂无记录）'}
【现在轮到你「${responder.name}」发言】
${countInstruction}
【规则】
1. 完全活出「${responder.name}」的人设——用词、语气、节奏都要有这个角色独特的辨识度，不能和其他角色雷同。
2. 发言必须自然接续群聊最近的话题，不能无视刚才说了什么另起炉灶。
3. 如果其他成员刚说了某件事，不要重复——直接回应他们、补充、或表达你不同的看法（根据人设决定是否有不同看法）。
4. 如果有人@你，必须直接回应那个人，风格和态度必须符合你与他的关系设定（若关系图中有定义）。
5. 提及群成员用@名字格式。
5.1 如果你是在明确回复某个群成员刚才的一句话，必须在消息最前面加机器标记：[replyTo:成员名]，然后再写正常内容。例如：[replyTo:林炎] @林炎 你刚才那句我不同意。这个标记只用于系统生成引用块，用户不会看到。
5.2 [replyTo:成员名] 只能写真实群成员名字，不能乱编；不确定自己在回复谁就不要加。
6. 禁止在回复前加自己名字的前缀（如"${responder.name}："），直接说话。
7. 鼓励角色展现性格棱角：可以有自己的观点、小情绪、说话习惯——一个自来熟的人会主动搭话，一个高冷的人只说关键一句，一个爱吐槽的人会忍不住评论两句。这种差异才让群聊有生命力。
8. 【关系一致性】若群内有与你存在关系设定的成员，发言时务必体现该关系的情感倾向，不能无视已设定的亲密、对立或特殊情感。
9. 【红包低频】群聊里不要频繁主动提“发红包/抢红包/红包来了”。除非最近话题明确是生日、新年、庆祝、请客或用户直接要求红包，否则不要把红包当作常规回复内容。
${BUILTIN_WB}`;
  try {
    const response = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: apiConfig.model,
        messages: [
          { role: 'system', content: sysPrompt },
          { role: 'user', content: '请根据以上群聊记录发言。' }
        ],
        temperature: responder.temperature || 1.0
      })
    });
    if (!response.ok) return [];
    const data = await response.json();
    const raw = (data.choices[0].message.content || '').trim();
    // Split by ### and clean each message
    const namePrefix = new RegExp('^' + responder.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[：:] *');
    const replies = raw.split('###')
      .map(s => s.trim().replace(namePrefix, '').trim())
      .filter(s => s.length > 0)
      .slice(0, count);
    return replies;
  } catch (e) {
    console.warn('gcFetchAiReplies error:', e);
    _showApiErrorToast('群聊 AI 回复失败', e);
    return [];
  }
}
// Legacy single-reply wrapper (kept for background auto-reply compatibility)
async function gcFetchAi回复(g, responder, userContent, isContinuation) {
  const replies = await gcFetchAiReplies(g, responder, 1);
  return replies[0] || null;
}
// ── 群组消息触发AI回覆 (legacy, kept for compatibility) ──
async function gcTriggerResponses(g, userContent) {
  // This function is now replaced by triggerGcAuto回复
  // Kept for backward compatibility
  await triggerGcAuto回复();
}
// ── 发送群组消息（改写版） ──
async function sendGroupMessage() {
  const input = document.getElementById('gcInput');
  const content = input.value.trim();
  if (!content) return;
  const g = groups.find(x => x.id === currentGroupId);
  if (!g) return;
  // Parse mentions
  const mentions = [];
  const mentionRegex = /@(\S+)/g;
  let match;
  while ((match = mentionRegex.exec(content)) !== null) {
    mentions.push(match[1]);
  }
  const selectedMaskId = monoGetGroupUserMaskSelection();
  // Build message object
  const msgObj = { role: 'user', content: content, mentions: mentions, timestamp: Date.now(), userMaskId: selectedMaskId };
  // Add quote if present
  if (gcQuoteData) {
    msgObj.quoteFrom = gcQuoteData.from;
    msgObj.quoteText = gcQuoteData.text;
    msgObj.quote = { from: gcQuoteData.from, text: gcQuoteData.text, role: gcQuoteData.role || '', type: gcQuoteData.type || 'text', index: gcQuoteData.index };
    cancelGcQuote();
  }
  g.messages.push(msgObj);
  input.value = '';
  document.getElementById('gcMentionList').classList.remove('open');
  closeGcPlusPanel();
  saveGroups();
  renderGroupMessages(g);
  // Do NOT auto-trigger AI responses - user must click the reply button
  // (triggerGcAuto回复 is only called when user clicks the 回覆 button)
}
// @mention autocomplete
function onGcInputChange() {
  const input = document.getElementById('gcInput');
  const val = input.value;
  const mentionList = document.getElementById('gcMentionList');
  const g = groups.find(x => x.id === currentGroupId);
  if (!g) { mentionList.classList.remove('open'); return; }
  const atIdx = val.lastIndexOf('@');
  if (atIdx >= 0 && (atIdx === 0 || val[atIdx - 1] === ' ')) {
    const query = val.substring(atIdx + 1).toLowerCase();
    const members = (g.memberIds || []).map(mid => personas.find(p => p.id == mid)).filter(Boolean);
    const currentUserIdentity = monoResolveGroupUserIdentity(g, { userMaskId: monoGetGroupUserMaskSelection() });
    const allParticipants = [...members.map(m => ({ id: m.id, name: m.name, avatar: m.avatar })), { id: 'user', name: currentUserIdentity.name, avatar: currentUserIdentity.avatar }];
    const filtered = allParticipants.filter(p => p.name.toLowerCase().includes(query));
    if (filtered.length > 0 && query.length <= 20) {
      mentionList.innerHTML = filtered.map(p => `<div class="gc-mention-item" onclick="selectGcMention('${p.name}')">
        <img src="${p.avatar}" alt="${p.name}">
        <span>${p.name}</span>
      </div>`).join('');
      mentionList.classList.add('open');
      return;
    }
  }
  mentionList.classList.remove('open');
}
function selectGcMention(name) {
  const input = document.getElementById('gcInput');
  const val = input.value;
  const atIdx = val.lastIndexOf('@');
  if (atIdx >= 0) {
    input.value = val.substring(0, atIdx) + '@' + name + ' ';
  }
  document.getElementById('gcMentionList').classList.remove('open');
  input.focus();
}
// Group Settings
function openGcSettingsFromChat() {
  const g = groups.find(x => x.id === currentGroupId);
  if (!g) return;
  openGcSettings(g.id);
}
function openGcSettings(groupId) {
  const g = groups.find(x => x.id === groupId);
  if (!g) return;
  document.getElementById('gcSettingsGroupId').value = g.id;
  document.getElementById('gcSettingsName').value = g.name;
  // Notification toggle
  const notifToggle = document.getElementById('gcNotifToggle');
  if (notifToggle) {
    if (g.notificationEnabled !== false) notifToggle.classList.add('on');
    else notifToggle.classList.remove('on');
  }
  const memContainer = document.getElementById('gcMemorySettings');
  const members = (g.memberIds || []).map(mid => personas.find(p => p.id == mid)).filter(Boolean);
  const memShare = (g.settings && g.settings.charMemoryShare) || {};
  memContainer.innerHTML = members.map(m => {
    const isOn = memShare[m.id] === true;
    return `<div class="gc-memory-item">
      <div class="gc-memory-item-left">
        <img src="${m.avatar}" alt="${m.name}">
        <span class="gc-memory-item-name">${m.name}</span>
      </div>
      <div class="wb-toggle ${isOn ? 'on' : ''}" data-char-id="${m.id}" onclick="this.classList.toggle('on')">
        <div class="wb-toggle-*****"></div>
      </div>
    </div>`;
  }).join('');
  // gcToPrivateSync — group chat memory → private chat
  const syncContainer = document.getElementById('gcToPrivateSyncSettings');
  const syncShare = (g.settings && g.settings.gcToPrivateSync) || {};
  if (syncContainer) {
    syncContainer.innerHTML = members.length === 0
      ? '<div style="font-size:11px;color:#bbb;padding:6px 0;">群组暂无成员</div>'
      : members.map(m => {
          const isOn = syncShare[m.id] === true;
          return `<div class="gc-memory-item">
            <div class="gc-memory-item-left">
              <img src="${m.avatar}" alt="${m.name}">
              <span class="gc-memory-item-name">${m.name}</span>
            </div>
            <div class="wb-toggle ${isOn ? 'on' : ''}" data-sync-char-id="${m.id}" onclick="this.classList.toggle('on')">
              <div class="wb-toggle-*****"></div>
            </div>
          </div>`;
        }).join('');
  }
  const memberContainer = document.getElementById('gcMemberSettings');
  memberContainer.innerHTML = members.map(m => {
    return `<div style="display:flex;align-items:center;justify-content:space-between;padding:6px 0;border-bottom:1px solid #f0f0f0;">
      <div style="display:flex;align-items:center;gap:8px;">
        <img src="${m.avatar}" style="width:24px;height:24px;border-radius:50%;object-fit:cover;">
        <span style="font-size:12px;font-weight:600;">${m.name}</span>
      </div>
      <button onclick="removeGroupMember('${g.id}','${m.id}')" style="font-size:9px;padding:3px 8px;border:1px solid #e74c3c;color:#e74c3c;background:#fff;border-radius:4px;cursor:pointer;font-family:inherit;">移除</button>
    </div>`;
  }).join('') + `<button onclick="addGroupMemberPrompt('${g.id}')" style="width:100%;margin-top:8px;padding:8px;border:1px dashed #ccc;background:#fff;border-radius:6px;font-size:11px;cursor:pointer;font-family:inherit;"><i class="fas fa-plus" style="margin-right:4px;"></i>添加成员</button>`;
  // Load beauty settings
  document.getElementById('gcBubbleAiCss').value = g.bubbleAiCss || '';
  document.getElementById('gcBubbleUserCss').value = g.bubbleUserCss || '';
  if (document.getElementById('gcRoomCustomCss')) document.getElementById('gcRoomCustomCss').value = g.chatRoomCustomCss || '';
  if (g.chatBgImage) {
    document.getElementById('gcChatBgImg').src = g.chatBgImage;
    document.getElementById('gcChatBgImg').style.display = 'block';
    document.getElementById('gcChatBgPlaceholder').style.display = 'none';
  } else {
    document.getElementById('gcChatBgImg').style.display = 'none';
    document.getElementById('gcChatBgPlaceholder').style.display = '';
  }
  document.getElementById('gcSettingsModal').classList.add('open');
}
function closeGcSettingsModal() {
  document.getElementById('gcSettingsModal').classList.remove('open');
}
function saveGroupSettings() {
  const gId = document.getElementById('gcSettingsGroupId').value;
  const g = groups.find(x => x.id === gId);
  if (!g) return;
  g.name = document.getElementById('gcSettingsName').value.trim() || g.name;
  // Save notification setting
  const notifToggle = document.getElementById('gcNotifToggle');
  if (notifToggle) {
    g.notificationEnabled = notifToggle.classList.contains('on');
  }
  const toggles = document.querySelectorAll('#gcMemorySettings .wb-toggle');
  if (!g.settings) g.settings = {};
  if (!g.settings.charMemoryShare) g.settings.charMemoryShare = {};
  toggles.forEach(t => {
    const charId = t.dataset.charId;
    g.settings.charMemoryShare[charId] = t.classList.contains('on');
  });
  // Save gcToPrivateSync toggles
  const syncToggles = document.querySelectorAll('#gcToPrivateSyncSettings .wb-toggle');
  if (!g.settings.gcToPrivateSync) g.settings.gcToPrivateSync = {};
  syncToggles.forEach(t => {
    const charId = t.dataset.syncCharId;
    if (charId) g.settings.gcToPrivateSync[charId] = t.classList.contains('on');
  });
  // Save beauty settings
  g.bubbleAiCss  = document.getElementById('gcBubbleAiCss').value.trim();
  g.bubbleUserCss = document.getElementById('gcBubbleUserCss').value.trim();
  g.chatRoomCustomCss = (document.getElementById('gcRoomCustomCss') || {value: ''}).value.trim();
  const gcBgImg = document.getElementById('gcChatBgImg');
  g.chatBgImage = (gcBgImg && gcBgImg.style.display !== 'none' && gcBgImg.src) ? gcBgImg.src : '';
  saveGroups();
  renderGroupList();
  if (currentGroupId === gId) {
    document.getElementById('gcHeaderName').textContent = g.name;
    const members = (g.memberIds || []).map(mid => personas.find(p => p.id == mid)).filter(Boolean);
    document.getElementById('gcHeaderMembers').textContent = members.map(m => m.name).join(', ') + ', ' + userProfile.name;
    applyGcBubbleStyles(g);
    applyGcBackground(g);
    applyGcRoomCustomCss(g);
  }
  closeGcSettingsModal();
}
async function deleteGroup() {
  const ok = await window.monoInAppConfirm({
    title: '删除群组',
    note: '确认删除这个群组？所有聊天记录也会被删除。',
    confirmText: '删除',
    cancelText: '取消',
    danger: true
  });
  if (!ok) return;
  const gId = document.getElementById('gcSettingsGroupId').value;
  groups = groups.filter(x => x.id !== gId);
  saveGroups();
  monoPostDeleteVerify([
    function() { return !groups.some(function(g) { return String(g.id) === String(gId); }); }
  ]);
  closeGcSettingsModal();
  closeGroupChat();
  renderGroupList();
}
function removeGroupMember(groupId, charId) {
  const g = groups.find(x => x.id === groupId);
  if (!g) return;
  g.memberIds = (g.memberIds || []).filter(id => id !== charId);
  if (g.settings && g.settings.charMemoryShare) delete g.settings.charMemoryShare[charId];
  if (g.settings && g.settings.gcToPrivateSync) delete g.settings.gcToPrivateSync[charId];
  if (g.memberIds.length < 2) { alert('群组至少需要2个成员'); return; }
  saveGroups();
  openGcSettings(groupId);
}
function addGroupMemberPrompt(groupId) {
  const g = groups.find(x => x.id === groupId);
  if (!g) return;
  const available = personas.filter(p => !(g.memberIds || []).includes(p.id));
  if (available.length === 0) { alert('没有更多角色可以添加'); return; }
  const names = available.map((p, i) => `${i + 1}. ${p.name}`).join('\n');
  const choice = prompt('选择要添加的角色（输入序号）：\n' + names);
  if (!choice) return;
  const idx = parseInt(choice) - 1;
  if (idx >= 0 && idx < available.length) {
    g.memberIds.push(available[idx].id);
    if (!g.settings) g.settings = {};
    if (!g.settings.charMemoryShare) g.settings.charMemoryShare = {};
    g.settings.charMemoryShare[available[idx].id] = false;
    if (!g.settings.gcToPrivateSync) g.settings.gcToPrivateSync = {};
    g.settings.gcToPrivateSync[available[idx].id] = false;
    saveGroups();
    openGcSettings(groupId);
  }
}
