// ===================== HOME PAGE SWIPE =====================
(function() {
  let currentHomePage = 0;
  let startX = 0, startY = 0, isDragging = false, movedX = 0;
  const THRESHOLD = 50;
  function goToHomePage(idx) {
    currentHomePage = idx;
    window._iphCurrentPage = idx;
    // Always delegate to the multi-page system (handles flip + swipe uniformly)
    if (window.goToHomePageMulti) {
      window.goToHomePageMulti(idx);
      return;
    }
    // Fallback: direct transform if multi-page not yet loaded
    const wrapper = document.getElementById('homePagesWrapper');
    if (wrapper) wrapper.style.transform = `translateX(${idx === 0 ? '0%' : '-50%'})`;
    const d0 = document.getElementById('hdot0');
    const d1 = document.getElementById('hdot1');
    if (d0) d0.classList.toggle('active', idx === 0);
    if (d1) d1.classList.toggle('active', idx === 1);
    if (idx === 1) renderIgStories();
  }
  window.goToHomePage = goToHomePage;
  function initHomeSwipe() {
    const hs = document.getElementById('homeScreen');
    if (!hs) return;
    function shouldIgnorePageSwipe() {
      return (typeof window._iphIsEditMode === 'function' && window._iphIsEditMode())
        || !!window._iphDragging
        || !!document.querySelector('.is-dragging-source');
    }
    // Apply persisted page mode on load
    if (typeof applyHomePageMode === 'function') applyHomePageMode();
    hs.addEventListener('touchstart', function(e) {
      if (shouldIgnorePageSwipe()) { isDragging = false; movedX = 0; return; }
      const t = e.changedTouches[0];
      startX = t.clientX; startY = t.clientY;
      isDragging = true; movedX = 0;
    }, { passive: true });
    hs.addEventListener('touchmove', function(e) {
      if (shouldIgnorePageSwipe()) { isDragging = false; movedX = 0; return; }
      if (!isDragging) return;
      const t = e.changedTouches[0];
      movedX = t.clientX - startX;
      // In flip mode: if the gesture is clearly horizontal, prevent default scroll
      // to avoid accidental page drift; vertical scroll is always allowed (passive)
      if (homePageMode === 'flip') {
        const movedY = t.clientY - startY;
        // Only block if strongly horizontal and not vertical
        if (Math.abs(movedX) > Math.abs(movedY) * 1.5 && Math.abs(movedX) > 10) {
          // Can't call preventDefault on passive listener – handled in touchend by ignoring
        }
      }
    }, { passive: true });
    hs.addEventListener('touchend', function(e) {
      if (shouldIgnorePageSwipe()) { isDragging = false; movedX = 0; return; }
      if (!isDragging) return;
      isDragging = false;
      // Flip mode uses edge tap zones instead of swipe — ignore horizontal drag gestures
      if (homePageMode === 'flip') { movedX = 0; return; }
      if (Math.abs(movedX) > THRESHOLD) {
        if (window.goToHomePageMulti) {
          const cur = window._iphCurrentPage || 0;
          if (movedX < 0) window.goToHomePageMulti(cur + 1);
          else if (movedX > 0) window.goToHomePageMulti(cur - 1);
          currentHomePage = window._iphCurrentPage || 0;
        } else {
          if (movedX < 0 && currentHomePage === 0) goToHomePage(1);
          else if (movedX > 0 && currentHomePage === 1) goToHomePage(0);
        }
      }
      movedX = 0;
    }, { passive: true });
    // Mouse drag for desktop testing
    hs.addEventListener('mousedown', function(e) {
      // Don't start drag in flip mode (tap zones handle navigation)
      if (shouldIgnorePageSwipe()) { isDragging = false; movedX = 0; return; }
      if (homePageMode === 'flip') return;
      startX = e.clientX; isDragging = true; movedX = 0;
    });
    window.addEventListener('mousemove', function(e) {
      if (shouldIgnorePageSwipe()) { isDragging = false; movedX = 0; return; }
      if (!isDragging) return;
      movedX = e.clientX - startX;
    });
    window.addEventListener('mouseup', function(e) {
      if (shouldIgnorePageSwipe()) { isDragging = false; movedX = 0; return; }
      if (!isDragging) return;
      isDragging = false;
      if (homePageMode === 'flip') { movedX = 0; return; }
      if (Math.abs(movedX) > THRESHOLD) {
        if (window.goToHomePageMulti) {
          const cur = window._iphCurrentPage || 0;
          if (movedX < 0) window.goToHomePageMulti(cur + 1);
          else if (movedX > 0) window.goToHomePageMulti(cur - 1);
          currentHomePage = window._iphCurrentPage || 0;
        } else {
          if (movedX < 0 && currentHomePage === 0) goToHomePage(1);
          else if (movedX > 0 && currentHomePage === 1) goToHomePage(0);
        }
      }
      movedX = 0;
    });
  }
  window.afterDB(initHomeSwipe);
})();
// ===================== INSTAGRAM STORIES SYSTEM =====================
let igStories = (function() {
  try { return JSON.parse(localStorage.getItem('mono_ig_stories') || '{}'); } catch(e) { return {}; }
})();       // personaId → [{ text, translation, time }]
function _saveIgStories() { try { localStorage.setItem('mono_ig_stories', JSON.stringify(igStories)); } catch(e) {} }
let igSeenStories = {};   // personaId → true (fully seen)
let igStoryTimers = {};
let igCurrentCharId = null;
let igCurrentStoryIndex = 0;
let igCurrentStories = [];
let igStoryProgressInterval = null;
function renderIgStories() {
  const row = document.getElementById('igStoriesRow');
  if (!row) return;
  // --- Build user's own circle (always first, not clickable as story) ---
  const uName = (userProfile && userProfile.name) ? userProfile.name : '我的';
  const uAvatar = (userProfile && userProfile.avatar) ? userProfile.avatar : '';
  const uInner = uAvatar
    ? `<img src="${uAvatar}" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.parentNode.innerHTML='<i class=\\'fas fa-user\\' style=\\'font-size:22px;color:#aaa;\\'></i>'">`
    : `<i class="fas fa-user" style="font-size:22px;color:#aaa;"></i>`;
  const userCircle = `
    <div class="ig-story-item ig-user-item">
      <div class="ig-story-ring ig-user-ring">
        <div class="ig-story-inner">${uInner}</div>
      </div>
      <div class="ig-story-name">${uName}</div>
    </div>`;
  // --- Build character circles ---
  if (!personas || personas.length === 0) {
    row.innerHTML = userCircle + `<div class="ig-no-chars">尚无角色 · 先創建角色吧</div>`;
    return;
  }
  const charCircles = personas.map(p => {
    const hasStories = igStories[p.id] && igStories[p.id].length > 0;
    const seen = igSeenStories[p.id] === true || !hasStories; // no stories = grey too
    const avatarSrc = p.avatar || '';
    const inner = avatarSrc
      ? `<img src="${avatarSrc}" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.parentNode.innerHTML='<span style=\\'font-size:20px;font-weight:700;color:#888;\\'>${(p.name||'?')[0]}</span>'">`
      : `<span style="font-size:20px;font-weight:700;color:#888;">${(p.name||'?')[0]}</span>`;
    return `
      <div class="ig-story-item ig-char-item" onclick="openIgStory('${monoJsSingleQuote(p.id)}')">
        <div class="ig-story-ring${seen ? ' seen' : ''}">
          <div class="ig-story-inner">${inner}</div>
        </div>
        <div class="ig-story-name">${p.name}</div>
      </div>`;
  }).join('');
  row.innerHTML = userCircle + charCircles;
}
async function generateIgStoryForPersona(persona) {
  if (!apiConfig || !apiConfig.url || !apiConfig.key || !apiConfig.model) return null;
  const _igLang = _detectPersonaLang(persona);
  const _igLangOv = _langOverridePrompt(_igLang);
  const prompt = `你是${persona.name}，人设：${persona.persona || '普通人'}。${_igLangOv}
现在请你以第一人称，写1到2条Instagram Story的文字动态，要有生活感和真实感（可以关於食物、心情、场所、小事）。
規则：每条动态之间用 ||| 分隔，不要写任何解释或前言，直接给动态内容。`;
  try {
    const apiUrl = apiConfig.url.replace(/\/+$/, '') + '/chat/completions';
    const r = await fetch(apiUrl, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${apiConfig.key}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: apiConfig.model,
        messages: [
          { role: 'system', content: `你是${persona.name}，请完全用第一人称回答。` },
          { role: 'user', content: prompt }
        ],
        temperature: 0.9,
        max_tokens: 200
      })
    });
    if (!r.ok) {
      const errText = await r.text().catch(() => String(r.status));
      console.error(`[IG Story] ${r.status}:`, errText);
      _showApiErrorToast('IG Story 生成失败', new Error(`HTTP ${r.status}: ${errText.slice(0,80)}`));
      return null;
    }
    const data = await r.json();
    const raw = (data.choices?.[0]?.message?.content || '').trim();
    if (!raw) return null;
    // Try ||| split first, fall back to newline split
    let parts;
    if (raw.includes('|||')) {
      parts = raw.split('|||').map(s => s.trim()).filter(Boolean);
    } else {
      parts = raw.split('\n').map(s => s.replace(/^[\d\.\-\*\s]+/, '').trim()).filter(s => s.length > 2);
    }
    const storyTexts = parts.slice(0, 2);
    if (!storyTexts.length) return null;
    // If foreign language, translate each story
    if (_igLang && persona.enableTranslation !== false) {
      const translated = [];
      for (const t of storyTexts) {
        try {
          const _tr = await fetch(apiConfig.url.replace(/\/+$/, '') + '/chat/completions', {
            method: 'POST', headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: '將以下文字翻譯成简体中文，只返回翻譯结果：\n' + t }], max_tokens: 100, temperature: 0.2 })
          });
          const _td = _tr.ok ? await _tr.json() : null;
          translated.push({ text: t, translation: _td ? (_td.choices[0].message.content || '').trim() : '' });
        } catch(e) { translated.push({ text: t, translation: '' }); }
      }
      return translated;
    }
    return storyTexts;
  } catch(e) {
    console.error('[IG Story] error:', e);
    _showApiErrorToast('IG Story 生成失败', e);
    return null;
  }
}
async function refreshIgStories() {
  if (!apiConfig || !apiConfig.url || !apiConfig.key) {
    alert('请先配置API才能生成Story！');
    return;
  }
  if (!personas || personas.length === 0) {
    alert('尚无角色，请先創建角色。');
    return;
  }
  const btn = document.querySelector('.ig-refresh-btn');
  if (btn) btn.innerHTML = '<i class="fas fa-spinner fa-spin" style="font-size:8px;"></i>生成中';
  igStories = {};
  igSeenStories = {};
  // Generate ALL characters simultaneously (parallel)
  const now = new Date().toLocaleTimeString('zh-TW', { hour: '2-digit', minute: '2-digit' });
  const results = await Promise.all(
    personas.map(p => generateIgStoryForPersona(p).then(stories => ({ p, stories })).catch(() => ({ p, stories: null })))
  );
  let successCount = 0;
  results.forEach(({ p, stories }) => {
    if (stories && stories.length > 0) {
      igStories[p.id] = stories.map(s => typeof s === 'object' ? { text: s.text, translation: s.translation || '', time: now } : { text: s, time: now });
      successCount++;
    }
  });
  _saveIgStories();
  if (btn) {
    if (successCount === 0) {
      btn.innerHTML = '⚠️ 生成失败';
      setTimeout(() => { btn.innerHTML = '<i class="fas fa-sync-alt" style="margin-right:3px;font-size:8px;"></i>刷新'; }, 3000);
    } else {
      btn.innerHTML = '<i class="fas fa-sync-alt" style="margin-right:3px;font-size:8px;"></i>刷新';
    }
  }
  renderIgStories();
}
function openIgStory(personaId) {
  igCurrentCharId = personaId;
  const p = personas.find(x => x.id == personaId);
  if (!p) return;
  const stories = igStories[personaId];
  if (!stories || stories.length === 0) {
    // No stories yet — generate on demand
    const viewer = document.getElementById('igStoryViewer');
    viewer.classList.add('open');
    document.getElementById('igStoryCharAvatar').src = p.avatar || '';
    document.getElementById('igStoryCharName').textContent = p.name;
    document.getElementById('igStoryCharTime').textContent = '剛才';
    document.getElementById('igStoryLoading').style.display = 'block';
    document.getElementById('igStoryTextCard').style.display = 'none';
    document.getElementById('igStoryProgressBars').innerHTML = '<div class="ig-story-prog-bar"><div class="ig-story-prog-fill" style="width:0%"></div></div>';
    if (!apiConfig || !apiConfig.url || !apiConfig.key) {
      document.getElementById('igStoryLoading').innerHTML = '<i class="fas fa-exclamation-circle" style="margin-right:6px;"></i>请先配置API';
      return;
    }
    generateIgStoryForPersona(p).then(result => {
      if (!result || result.length === 0) {
        document.getElementById('igStoryLoading').innerHTML = '<i class="fas fa-exclamation-circle" style="margin-right:6px;"></i>生成失败，请重试';
        return;
      }
      igStories[personaId] = result.map(s => typeof s === 'object'
        ? { text: s.text, translation: s.translation || '', time: new Date().toLocaleTimeString('zh-TW', { hour: '2-digit', minute: '2-digit' }) }
        : { text: s, time: new Date().toLocaleTimeString('zh-TW', { hour: '2-digit', minute: '2-digit' }) });
      _saveIgStories();
      igCurrentStories = igStories[personaId];
      igCurrentStoryIndex = 0;
      showIgStorySlide(p, igCurrentStoryIndex);
    });
    return;
  }
  igCurrentStories = stories;
  igCurrentStoryIndex = 0;
  const viewer = document.getElementById('igStoryViewer');
  viewer.classList.add('open');
  document.getElementById('igStoryCharAvatar').src = p.avatar || '';
  document.getElementById('igStoryCharName').textContent = p.name;
  document.getElementById('igStoryLoading').style.display = 'none';
  showIgStorySlide(p, 0);
}
function showIgStorySlide(p, idx) {
  const stories = igStories[igCurrentCharId];
  if (!stories || idx >= stories.length) { closeIgStoryViewer(); return; }
  const story = stories[idx];
  document.getElementById('igStoryLoading').style.display = 'none';
  document.getElementById('igStoryTextCard').style.display = 'block';
  document.getElementById('igStoryText').textContent = story.text;
  document.getElementById('igStoryCharTime').textContent = story.time;
  document.getElementById('igStoryCharAvatar').src = p.avatar || '';
  document.getElementById('igStoryCharName').textContent = p.name;
  // Show translation if available
  const trEl = document.getElementById('igStoryTranslation');
  const trTextEl = document.getElementById('igStoryTranslationText');
  if (trEl && trTextEl) {
    if (story.translation) {
      trTextEl.textContent = story.translation;
      trEl.style.display = 'block';
    } else {
      trEl.style.display = 'none';
    }
  }
  // Progress bars
  const bars = document.getElementById('igStoryProgressBars');
  bars.innerHTML = stories.map((_, i) => {
    const pct = i < idx ? 100 : i === idx ? 0 : 0;
    return `<div class="ig-story-prog-bar"><div class="ig-story-prog-fill" id="igProg${i}" style="width:${pct}%"></div></div>`;
  }).join('');
  // Animate current bar
  if (igStoryProgressInterval) clearInterval(igStoryProgressInterval);
  let prog = 0;
  igStoryProgressInterval = setInterval(() => {
    prog = Math.min(prog + 1, 100);
    const bar = document.getElementById('igProg' + idx);
    if (bar) bar.style.width = prog + '%';
    if (prog >= 100) {
      clearInterval(igStoryProgressInterval);
      igStoryProgressInterval = null;
    }
  }, 50); // 5 seconds total
}
function igStoryTapNext() {
  if (igStoryProgressInterval) { clearInterval(igStoryProgressInterval); igStoryProgressInterval = null; }
  igCurrentStoryIndex++;
  const p = personas.find(x => x.id == igCurrentCharId);
  if (!p) { closeIgStoryViewer(); return; }
  showIgStorySlide(p, igCurrentStoryIndex);
}
function closeIgStoryViewer() {
  if (igStoryProgressInterval) { clearInterval(igStoryProgressInterval); igStoryProgressInterval = null; }
  // Mark this character's stories as fully seen
  if (igCurrentCharId !== null) {
    igSeenStories[igCurrentCharId] = true;
  }
  document.getElementById('igStoryViewer').classList.remove('open');
  renderIgStories();
}
