// ===================== COUPLE LOCATION APP =====================
let locRelations = [];
let locUserLocation = null;
let locCharLocations = {}; // personaId → [{ time, address }]
let locDailyTraces = {};   // personaId → [{ time, place, activity, isoDate }]
let locUserRegionName = '';       // user's own region (free text)
let locCharRegions = {};          // personaId → region text
let locCurrentTab = 'map';
let locSelectedCharId = null;     // currently displayed character on bottom map
let locLastTraceDate = '';
// per-map pan/zoom state
const _locMapState = {
  top: { scale: 1, tx: 0, ty: 0, lastDist: 0, lastX: 0, lastY: 0, dragging: false, pinching: false },
  bot: { scale: 1, tx: 0, ty: 0, lastDist: 0, lastX: 0, lastY: 0, dragging: false, pinching: false }
};
// ---------- persistence ----------
function loadLocData() {
  try { locRelations = JSON.parse(localStorage.getItem('mono_loc_relations') || '[]'); } catch(e) { locRelations = []; }
  try { locUserLocation = JSON.parse(localStorage.getItem('mono_loc_user_pos')); } catch(e) {}
  try { locCharLocations = JSON.parse(localStorage.getItem('mono_loc_char_pos') || '{}'); } catch(e) { locCharLocations = {}; }
  try { locDailyTraces = JSON.parse(localStorage.getItem('mono_loc_traces') || '{}'); } catch(e) { locDailyTraces = {}; }
  try { locCharRegions = JSON.parse(localStorage.getItem('mono_loc_char_regions') || '{}'); } catch(e) { locCharRegions = {}; }
  locUserRegionName = localStorage.getItem('mono_loc_user_region') || '';
  locLastTraceDate = localStorage.getItem('mono_loc_trace_date') || '';
  locSelectedCharId = localStorage.getItem('mono_loc_sel_char') ? parseInt(localStorage.getItem('mono_loc_sel_char')) : null;
}
function saveLocData() {
  localStorage.setItem('mono_loc_relations', JSON.stringify(locRelations));
  if (locUserLocation) localStorage.setItem('mono_loc_user_pos', JSON.stringify(locUserLocation));
  localStorage.setItem('mono_loc_char_pos', JSON.stringify(locCharLocations));
  localStorage.setItem('mono_loc_traces', JSON.stringify(locDailyTraces));
  localStorage.setItem('mono_loc_char_regions', JSON.stringify(locCharRegions));
  localStorage.setItem('mono_loc_user_region', locUserRegionName);
  localStorage.setItem('mono_loc_trace_date', locLastTraceDate);
  if (locSelectedCharId != null) localStorage.setItem('mono_loc_sel_char', locSelectedCharId);
}
// ---------- open / close ----------
function openLocationApp() {
  loadLocData();
  document.getElementById('locationPage').classList.add('active');
  _checkMidnightReset();
  _renderCharBar();
  renderLocMap();
  renderLocRelation();
}
function closeLocationApp() {
  document.getElementById('locationPage').classList.remove('active');
}
// ---------- tab switching ----------
function switchLocTab(tab) {
  locCurrentTab = tab;
  ['map','trace','relation'].forEach(t => {
    document.getElementById('locTab' + t.charAt(0).toUpperCase() + t.slice(1)).classList.toggle('active', t === tab);
  });
  document.getElementById('locMapView').style.display = tab === 'map' ? 'flex' : 'none';
  const tv = document.getElementById('locTraceView');
  tv.style.display = tab === 'trace' ? 'flex' : 'none';
  tv.style.flexDirection = 'column';
  document.getElementById('locRelationView').style.display = tab === 'relation' ? 'block' : 'none';
  if (tab === 'trace') renderLocTrace();
  if (tab === 'relation') renderLocRelation();
  if (tab === 'map') renderLocMap();
}
// ---------- character switcher bar ----------
function _renderCharBar() {
  const inner = document.getElementById('locCharBarInner');
  if (!inner) return;
  if (!locRelations || !locRelations.length) {
    inner.innerHTML = '<span class="loc-char-bar-hint">绑定角色后可切换</span>';
    return;
  }
  inner.innerHTML = locRelations.map(rel => {
    const p = personas.find(x => x.id == rel.personaId);
    if (!p) return '';
    const active = locSelectedCharId == rel.personaId;
    const avatarHtml = p.avatar
      ? `<img src="${p.avatar}" onerror="this.style.display='none'">`
      : `<span style="width:22px;height:22px;border-radius:50%;background:#ddd;display:inline-block;line-height:22px;text-align:center;font-size:9px;">${(p.name||'?')[0]}</span>`;
    return `<div class="loc-char-chip ${active ? 'active' : ''}" onclick="selectLocChar('${monoJsSingleQuote(p.id)}')">
      ${avatarHtml}
      <span>${p.name}</span>
    </div>`;
  }).join('');
}
function selectLocChar(personaId) {
  locSelectedCharId = personaId;
  saveLocData();
  _renderCharBar();
  _renderBotMap();
}
// ---------- Region settings modal ----------
function openLocSettingsModal() {
  // Fill user region input
  const uri = document.getElementById('locUserRegionInput');
  if (uri) uri.value = locUserRegionName;
  // Fill per-character rows
  const list = document.getElementById('locCharRegionList');
  if (!list) return;
  if (!locRelations || !locRelations.length) {
    list.innerHTML = '<div style="font-size:11px;color:#bbb;padding:6px 0;">先绑定角色才能设定TA的地区</div>';
  } else {
    list.innerHTML = '<div class="loc-settings-group-label" style="margin-bottom:8px;">各角色地区</div>' +
      locRelations.map(rel => {
        const p = personas.find(x => x.id == rel.personaId);
        if (!p) return '';
        const avatarHtml = p.avatar
          ? `<img src="${p.avatar}" onerror="this.style.display='none'" style="width:28px;height:28px;border-radius:50%;object-fit:cover;border:1px solid #eee;flex-shrink:0;">`
          : `<span style="width:28px;height:28px;border-radius:50%;background:#ddd;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;flex-shrink:0;">${(p.name||'?')[0]}</span>`;
        return `<div class="loc-char-region-row" style="display:flex;align-items:center;gap:8px;margin-bottom:10px;">
          ${avatarHtml}
          <span style="font-size:11px;font-weight:700;color:#1a1a1a;min-width:48px;flex-shrink:0;">${p.name}</span>
          <input type="text" class="loc-region-text-input" id="locCharRegion_${p.id}"
            value="${locCharRegions[p.id] || ''}" placeholder="例：韩国·首爾"/>
          <button class="loc-input-btn" style="font-size:9px;padding:5px 8px;" onclick="saveCharRegion('${monoJsSingleQuote(p.id)}')">保存</button>
        </div>`;
      }).join('');
  }
  document.getElementById('locSettingsModal').classList.add('open');
}
function closeLocSettingsModal() { document.getElementById('locSettingsModal').classList.remove('open'); }
function saveUserRegionSetting() {
  const v = (document.getElementById('locUserRegionInput')?.value || '').trim();
  if (!v) { alert('请输入地区名称'); return; }
  locUserRegionName = v;
  saveLocData();
  _renderTopMap();
  alert(`已保存我的地区：${v}`);
}
function saveCharRegion(personaId) {
  const v = (document.getElementById('locCharRegion_' + personaId)?.value || '').trim();
  if (!v) { alert('请输入地区名称'); return; }
  locCharRegions[personaId] = v;
  // reset that char's position data
  locCharLocations[personaId] = [];
  locDailyTraces[personaId] = [];
  saveLocData();
  if (locSelectedCharId == personaId) _renderBotMap();
  alert(`已保存 ${personas.find(x=>x.id==personaId)?.name||'角色'} 的地区：${v}`);
}
// ---------- AI map SVG generation ----------
const _mapSvgCache = {}; // regionText → svgInnerHTML
async function generateMapSvg(regionText, svgId) {
  const svg = document.getElementById(svgId);
  if (!svg) return;
  if (!regionText) { _drawFallbackMap(svg, '未知地区'); return; }
  // Check cache
  if (_mapSvgCache[regionText]) { svg.innerHTML = _mapSvgCache[regionText]; return; }
  svg.innerHTML = `<rect width="360" height="300" fill="#f0ece4"/>
    <text x="180" y="145" text-anchor="middle" font-size="11" fill="#bbb" font-family="sans-serif">地图生成中…</text>
    <text x="180" y="162" text-anchor="middle" font-size="10" fill="#ccc" font-family="sans-serif">${regionText}</text>`;
  if (!apiConfig?.url || !apiConfig?.key || !apiConfig?.model) {
    _drawFallbackMap(svg, regionText);
    return;
  }
  try {
    const prompt = `你是SVG地图生成器。为「${regionText}」生成地图SVG内容（viewBox 0 0 360 300）。
要求：
1. 背景 <rect width="360" height="300" fill="#f0ece4"/>
2. 2-3个公园 fill="#c8e6c9" rx="4"
3. 8-12个建築 fill="#d0cbc0" rx="2"，分布各处
4. 2-4条道路 path stroke="#ffffff" stroke-width="6" fill="none"（橫+縱）
5. 4-6个真实地名 text font-size="8" fill="#888" font-family="sans-serif"
6. 底部地区名 text x="180" y="292" text-anchor="middle" font-size="11" fill="#888" font-weight="bold"
只返回SVG元素代码，不含<svg>标签，不含markdown代码块。`;
    const r = await fetch(apiConfig.url.replace(/\/+$/,'') + '/chat/completions', {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: prompt }], temperature: 0.5, max_tokens: 1200 })
    });
    if (!r.ok) throw new Error();
    const data = await r.json();
    let raw = (data.choices?.[0]?.message?.content || '').trim().replace(/^```[\w]*\n?/,'').replace(/```$/,'').trim();
    if (raw.length > 60) {
      _mapSvgCache[regionText] = raw;
      svg.innerHTML = raw;
      return;
    }
  } catch(e) {}
  _drawFallbackMap(svg, regionText);
}
function _drawFallbackMap(svg, regionText) {
  const seed = (regionText||'').split('').reduce((a,c) => a + c.charCodeAt(0), 17);
  const rnd = (n,s=0) => ((seed*9301 + n*49297 + s*233) % 1000) / 1000;
  let h = `<rect width="360" height="300" fill="#f0ece4"/>`;
  // Parks
  for (let i=0;i<2;i++) {
    const x=20+Math.floor(rnd(i,1)*280), y=20+Math.floor(rnd(i,2)*220), w=30+Math.floor(rnd(i,3)*40), hh=20+Math.floor(rnd(i,4)*30);
    h += `<rect x="${x}" y="${y}" width="${w}" height="${hh}" fill="#c8e6c9" rx="4"/>`;
  }
  // Roads
  const ry1=80+Math.floor(rnd(0,9)*80), ry2=ry1+70+Math.floor(rnd(1,9)*50);
  const cx1=80+Math.floor(rnd(2,9)*80), cx2=cx1+90+Math.floor(rnd(3,9)*80);
  h += `<path d="M0,${ry1}L360,${ry1}M0,${ry2}L360,${ry2}M${cx1},0L${cx1},300M${cx2},0L${cx2},300" stroke="#fff" stroke-width="6" fill="none"/>`;
  // Buildings
  for (let i=0;i<10;i++) {
    const x=15+Math.floor(rnd(i,5)*310), y=15+Math.floor(rnd(i,6)*240), w=25+Math.floor(rnd(i,7)*45), hh=18+Math.floor(rnd(i,8)*40);
    h += `<rect x="${x}" y="${y}" width="${w}" height="${hh}" fill="#d0cbc0" rx="2"/>`;
  }
  h += `<text x="180" y="292" text-anchor="middle" font-size="11" fill="#888" font-weight="bold" font-family="sans-serif">${regionText}</text>`;
  svg.innerHTML = h;
}
function _addPin(canvasId, label, address, avatarSrc, leftPct, topPct) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  // Remove existing pin with same label
  canvas.querySelectorAll('.loc-pin').forEach(p => { if (p.dataset.label === label) p.remove(); });
  const pin = document.createElement('div');
  pin.className = 'loc-pin';
  pin.dataset.label = label;
  pin.style.left = leftPct + '%';
  pin.style.top = topPct + '%';
  const avatarHtml = avatarSrc
    ? `<img class="loc-pin-avatar" src="${avatarSrc}" onerror="this.style.display='none'">`
    : `<div class="loc-pin-avatar" style="background:#ddd;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;">${(label||'?')[0]}</div>`;
  pin.innerHTML = `${avatarHtml}<div class="loc-pin-label">${label}</div><div class="loc-pin-addr">${(address||'').slice(0,14)}</div><div class="loc-pin-pointer"></div>`;
  canvas.appendChild(pin);
}
// ---------- Render maps ----------
function _renderTopMap() {
  const region = locUserRegionName;
  generateMapSvg(region || '我的地区', 'locSvgTop');
  // Add user pin
  const canv = document.getElementById('locCanvasTop');
  if (canv) canv.querySelectorAll('.loc-pin').forEach(p => p.remove());
  if (locUserLocation) {
    _addPin('locCanvasTop', userProfile?.name || '我', locUserLocation.address || locUserLocation.name, userProfile?.avatar || '', 50, 50);
  }
  // Update tag
  const tag = document.getElementById('locMapTagTop');
  if (tag) tag.textContent = locUserRegionName ? `我 · ${locUserRegionName}` : '我的位置';
}
function _renderBotMap() {
  const noSel = document.getElementById('locCharNoSel');
  const touch = document.getElementById('locTouchBot');
  if (!locSelectedCharId || !locRelations.find(r => r.personaId == locSelectedCharId)) {
    if (noSel) noSel.style.display = 'flex';
    if (touch) touch.style.display = 'none';
    const tag = document.getElementById('locMapTagBot');
    if (tag) tag.textContent = '—';
    return;
  }
  if (noSel) noSel.style.display = 'none';
  if (touch) touch.style.display = 'block';
  const p = personas.find(x => x.id == locSelectedCharId);
  if (!p) return;
  const region = locCharRegions[locSelectedCharId] || '';
  generateMapSvg(region || `${p.name}的位置`, 'locSvgBot');
  // Add char pin
  const canv = document.getElementById('locCanvasBot');
  if (canv) canv.querySelectorAll('.loc-pin').forEach(pin => pin.remove());
  const locs = locCharLocations[locSelectedCharId] || [];
  const latest = locs.length ? locs[locs.length-1] : null;
  if (latest) {
    _addPin('locCanvasBot', p.name, latest.address, p.avatar || '', 50, 45);
  }
  const tag = document.getElementById('locMapTagBot');
  if (tag) tag.textContent = p.name + (region ? ` · ${region}` : '');
}
function renderLocMap() {
  _renderTopMap();
  _renderBotMap();
}
// ---------- Touch pan/zoom handlers ----------
function locTouchStart(e, side) {
  const s = _locMapState[side];
  if (e.touches.length === 1) {
    s.dragging = true; s.pinching = false;
    s.lastX = e.touches[0].clientX;
    s.lastY = e.touches[0].clientY;
  } else if (e.touches.length === 2) {
    s.pinching = true; s.dragging = false;
    s.lastDist = _touchDist(e.touches);
    s.lastX = (e.touches[0].clientX + e.touches[1].clientX) / 2;
    s.lastY = (e.touches[0].clientY + e.touches[1].clientY) / 2;
  }
  e.preventDefault();
}
function locTouchMove(e, side) {
  const s = _locMapState[side];
  const canvasId = side === 'top' ? 'locCanvasTop' : 'locCanvasBot';
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  if (s.pinching && e.touches.length === 2) {
    const newDist = _touchDist(e.touches);
    const ratio = newDist / (s.lastDist || newDist);
    const cx = (e.touches[0].clientX + e.touches[1].clientX) / 2;
    const cy = (e.touches[0].clientY + e.touches[1].clientY) / 2;
    const rect = canvas.parentElement.getBoundingClientRect();
    const px = cx - rect.left, py = cy - rect.top;
    const newScale = Math.max(0.5, Math.min(5, s.scale * ratio));
    s.tx = px - (px - s.tx) * (newScale / s.scale);
    s.ty = py - (py - s.ty) * (newScale / s.scale);
    s.scale = newScale;
    s.lastDist = newDist;
    s.lastX = cx; s.lastY = cy;
  } else if (s.dragging && e.touches.length === 1) {
    const dx = e.touches[0].clientX - s.lastX;
    const dy = e.touches[0].clientY - s.lastY;
    s.tx += dx; s.ty += dy;
    s.lastX = e.touches[0].clientX;
    s.lastY = e.touches[0].clientY;
  }
  canvas.style.transform = `translate(${s.tx}px, ${s.ty}px) scale(${s.scale})`;
  e.preventDefault();
}
function locTouchEnd(e, side) {
  const s = _locMapState[side];
  if (e.touches.length < 2) { s.pinching = false; }
  if (e.touches.length === 0) { s.dragging = false; }
}
function _touchDist(touches) {
  const dx = touches[0].clientX - touches[1].clientX;
  const dy = touches[0].clientY - touches[1].clientY;
  return Math.sqrt(dx*dx + dy*dy);
}
// ---------- User location ----------
function setUserLocation() {
  const input = document.getElementById('locUserInput');
  const val = input ? input.value.trim() : '';
  if (!val) { alert('请输入位置名称'); return; }
  locUserLocation = { name: val, address: val, time: new Date().toISOString() };
  saveLocData();
  if (input) input.value = '';
  _renderTopMap();
}
async function shareUserLocation() {
  if (!locUserLocation) { alert('请先设定你的位置'); return; }
  if (!locRelations || !locRelations.length) { alert('请先绑定关係角色'); return; }
  if (!apiConfig?.url || !apiConfig?.key) { alert('请先配置API'); return; }
  for (const rel of locRelations) {
    const p = personas.find(x => x.id == rel.personaId); if (!p) continue;
    if (!p.history) p.history = [];
    p.history.push({ role:'user', content:`__LOCATION_SHARE__|${locUserLocation.name}|${locUserLocation.address||locUserLocation.name}`, timestamp:Date.now(), msgType:'location' });
    try {
      const prompt = `你是${p.name}，人设：${p.persona||''}。用户分享了位置：「${locUserLocation.name}」。请简短自然地回应，不超过30字。`;
      const r = await fetch(apiConfig.url.replace(/\/+$/,'') + '/chat/completions', {
        method:'POST', headers:{'Authorization':`Bearer ${apiConfig.key}`,'Content-Type':'application/json'},
        body: JSON.stringify({ model:apiConfig.model, messages:[{role:'user',content:prompt}], temperature:0.88, max_tokens:80 })
      });
      if (r.ok) { const data = await r.json(); p.history.push({ role:'assistant', content:data.choices[0].message.content.trim(), timestamp:Date.now() }); }
    } catch(e) {}
  }
  saveData();
  alert(`已分享位置「${locUserLocation.name}」给所有绑定角色！`);
}
// ---------- Midnight reset ----------
function _checkMidnightReset() {
  const today = new Date().toLocaleDateString('zh-TW');
  if (locLastTraceDate && locLastTraceDate !== today) {
    locDailyTraces = {};
    locLastTraceDate = today;
    saveLocData();
  } else if (!locLastTraceDate) {
    locLastTraceDate = today;
    saveLocData();
  }
}
(function scheduleMidnightReset() {
  const now = new Date();
  const ms = new Date(now.getFullYear(),now.getMonth(),now.getDate()+1,0,0,5).getTime() - now.getTime();
  setTimeout(() => {
    locDailyTraces = {};
    locLastTraceDate = new Date().toLocaleDateString('zh-TW');
    saveLocData();
    renderLocTrace();
    scheduleMidnightReset();
  }, ms);
})();
// ---------- Trace generation ----------
async function generateFullDayTrace(persona, regionText) {
  if (!apiConfig?.url || !apiConfig?.key || !apiConfig?.model) return [];
  const now = new Date();
  const slots = [];
  let cur = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0);
  while (cur <= now) {
    slots.push(cur.toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit',hour12:false}));
    cur = new Date(cur.getTime() + 30*60*1000);
  }
  if (!slots.length) return [];
  const recentChat = ((persona.history||[]).slice(-8)).map(m=>`${m.role==='user'?'用户':persona.name}: ${(m.content||'').slice(0,60)}`).join('\n');
  const prompt = `你是${persona.name}，人设：${persona.persona||'普通人'}，所在地区：${regionText}。今天是${now.toLocaleDateString('zh-TW')}。
${recentChat ? '最近聊天：\n'+recentChat+'\n' : ''}
【语言要求：无論角色人设如何，行踪记录必须全程使用简体中文】
请根据人设和地区，生成以下时间点的行踪：${slots.join('、')}
格式（每行一条）：HH:MM | 地点名称 | 正在做的事（15字以内）
例：08:00 | 弘大咖啡厅 | 点了拿铁在备課
只需给行踪列表。`;
  try {
    const r = await fetch(apiConfig.url.replace(/\/+$/,'') + '/chat/completions', {
      method:'POST', headers:{'Authorization':`Bearer ${apiConfig.key}`,'Content-Type':'application/json'},
      body: JSON.stringify({ model:apiConfig.model, messages:[{role:'user',content:prompt}], temperature:0.85, max_tokens:800 })
    });
    if (!r.ok) return [];
    const data = await r.json();
    return _parseTraceLines(data.choices?.[0]?.message?.content||'', now);
  } catch(e) { return []; }
}
async function generateIncrementalTrace(persona, regionText, fromTimeStr) {
  if (!apiConfig?.url || !apiConfig?.key || !apiConfig?.model) return [];
  const now = new Date();
  const slots = [];
  const [fh,fm] = (fromTimeStr||'00:00').split(':').map(Number);
  let cur = new Date(now.getFullYear(),now.getMonth(),now.getDate(),fh,fm,0);
  cur = new Date(cur.getTime() + 30*60*1000);
  while (cur <= now) {
    slots.push(cur.toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit',hour12:false}));
    cur = new Date(cur.getTime() + 30*60*1000);
  }
  if (!slots.length) return [];
  const recentChat = ((persona.history||[]).slice(-8)).map(m=>`${m.role==='user'?'用户':persona.name}: ${(m.content||'').slice(0,60)}`).join('\n');
  const prompt = `你是${persona.name}，人设：${persona.persona||'普通人'}，所在地区：${regionText}。
${recentChat ? '最近聊天：\n'+recentChat+'\n' : ''}
【语言要求：无論角色人设如何，行踪记录必须全程使用简体中文】
继续生成以下时间点的行踪：${slots.join('、')}
格式：HH:MM | 地点名称 | 正在做的事（15字以内）`;
  try {
    const r = await fetch(apiConfig.url.replace(/\/+$/,'') + '/chat/completions', {
      method:'POST', headers:{'Authorization':`Bearer ${apiConfig.key}`,'Content-Type':'application/json'},
      body: JSON.stringify({ model:apiConfig.model, messages:[{role:'user',content:prompt}], temperature:0.85, max_tokens:600 })
    });
    if (!r.ok) return [];
    const data = await r.json();
    return _parseTraceLines(data.choices?.[0]?.message?.content||'', now);
  } catch(e) { return []; }
}
function _parseTraceLines(raw, now) {
  const traces = [];
  for (const line of raw.split('\n').map(l=>l.trim()).filter(l=>l.includes('|'))) {
    const parts = line.split('|').map(s=>s.trim());
    if (parts.length >= 3) traces.push({ time:parts[0], place:parts[1], activity:parts[2], isoDate:now.toLocaleDateString('zh-TW') });
    else if (parts.length === 2) traces.push({ time:parts[0], place:parts[1], activity:'', isoDate:now.toLocaleDateString('zh-TW') });
  }
  return traces;
}
async function updateLocTrace() {
  if (!locRelations || !locRelations.length) { alert('请先绑定角色'); return; }
  _checkMidnightReset();
  const btn = document.getElementById('locTraceUpdateBtn');
  if (btn) { btn.disabled=true; btn.innerHTML='<i class="fas fa-spinner fa-spin" style="font-size:9px;"></i> 生成中'; }
  for (const rel of locRelations) {
    const p = personas.find(x => x.id == rel.personaId); if (!p) continue;
    const region = locCharRegions[p.id] || locUserRegionName || '未知地区';
    const existing = locDailyTraces[p.id] || [];
    let newTraces = [];
    if (existing.length === 0) {
      newTraces = await generateFullDayTrace(p, region);
    } else {
      const lastTime = existing[existing.length-1].time || '00:00';
      newTraces = await generateIncrementalTrace(p, region, lastTime);
    }
    if (newTraces.length > 0) {
      locDailyTraces[p.id] = [...existing, ...newTraces];
      const last = newTraces[newTraces.length-1];
      if (!locCharLocations[p.id]) locCharLocations[p.id] = [];
      locCharLocations[p.id].push({ address: last.place, time: new Date().toISOString() });
      if (locCharLocations[p.id].length > 48) locCharLocations[p.id] = locCharLocations[p.id].slice(-48);
    }
  }
  saveLocData();
  renderLocTrace();
  if (locCurrentTab === 'map') _renderBotMap();
  if (btn) { btn.disabled=false; btn.innerHTML='<i class="fas fa-sync-alt" style="margin-right:3px;font-size:9px;"></i>更新行踪'; }
}
// ---------- Trace rendering ----------
function renderLocTrace() {
  _checkMidnightReset();
  const content = document.getElementById('locTraceContent');
  const empty = document.getElementById('locTraceEmpty');
  if (!content) return;
  if (!locRelations || !locRelations.length) {
    if (empty) empty.style.display = 'block';
    content.innerHTML = '';
    return;
  }
  if (empty) empty.style.display = 'none';
  let html = '';
  for (const rel of locRelations) {
    const p = personas.find(x => x.id == rel.personaId); if (!p) continue;
    const traces = (locDailyTraces[p.id] || []).slice();
    const avatarHtml = p.avatar
      ? `<img src="${p.avatar}" style="width:26px;height:26px;border-radius:50%;object-fit:cover;border:1px solid #eee;" onerror="this.style.display='none'">`
      : `<span style="width:26px;height:26px;border-radius:50%;background:#ddd;display:inline-flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;">${(p.name||'?')[0]}</span>`;
    html += `<div style="margin:10px 0 4px;">
      <div style="display:flex;align-items:center;gap:8px;padding:0 14px 8px;border-bottom:1px solid #f0f0f0;">
        ${avatarHtml}
        <span style="font-size:11px;font-weight:800;color:#1a1a1a;">${p.name}</span>
        <span style="font-size:9px;color:#bbb;text-transform:uppercase;">${rel.type==='couple'?'情侶':'朋友'}</span>
        <span style="margin-left:auto;font-size:9px;color:#aaa;">${traces.length} 条</span>
      </div>`;
    if (!traces.length) {
      html += `<div style="font-size:11px;color:#ccc;padding:10px 14px;">暂无行踪 · 请按「更新行踪」</div>`;
    } else {
      [...traces].reverse().forEach((t, i) => {
        html += `<div class="loc-trace-item">
          <div class="loc-trace-time">${t.time}</div>
          <div class="loc-trace-dot${i===0?' current':''}"></div>
          <div style="flex:1;min-width:0;">
            <div class="loc-trace-place">${t.place}</div>
            ${t.activity ? `<div class="loc-trace-activity">${t.activity}</div>` : ''}
          </div>
        </div>`;
      });
    }
    html += `</div>`;
  }
  content.innerHTML = html;
}
// ---------- Relation rendering ----------
function renderLocRelation() {
  const list = document.getElementById('locRelationList'); if (!list) return;
  if (!locRelations || !locRelations.length) {
    list.innerHTML=`<div class="loc-empty-msg"><i class="fas fa-heart" style="font-size:24px;margin-bottom:8px;display:block;color:#ddd;"></i>尚未绑定任何关係<br>点擊右上角「绑定」开始</div>`;
    return;
  }
  list.innerHTML = locRelations.map(rel => {
    const p = personas.find(x => x.id == rel.personaId); if (!p) return '';
    const locs = locCharLocations[rel.personaId] || [];
    const latest = locs.length ? locs[locs.length-1] : null;
    const avatarHtml = p.avatar
      ? `<img class="loc-relation-avatar" src="${p.avatar}" alt="${p.name}" onerror="this.style.display='none'">`
      : `<div class="loc-relation-avatar" style="background:#ddd;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;">${(p.name||'?')[0]}</div>`;
    return `<div class="loc-relation-item">
      ${avatarHtml}
      <div class="loc-relation-info">
        <div class="loc-relation-name">${p.name}</div>
        <div class="loc-relation-type">${rel.type==='couple'?'💑 情侶':'👥 朋友'}</div>
        <div class="loc-relation-location">${latest ? '📍 '+latest.address : '位置尚未更新'}</div>
      </div>
      <div class="loc-relation-actions">
        <button class="loc-rel-btn" onclick="selectLocChar(${rel.personaId});switchLocTab('map')">查看</button>
        <button class="loc-rel-btn danger" onclick="removeLocRelation(${rel.personaId})">解除</button>
      </div>
    </div>`;
  }).join('');
}
function removeLocRelation(personaId) {
  if (!confirm('确定解除绑定？')) return;
  locRelations = locRelations.filter(r => r.personaId != personaId);
  if (locSelectedCharId == personaId) locSelectedCharId = null;
  saveLocData();
  renderLocRelation();
  _renderCharBar();
  _renderBotMap();
}
// ---------- Bind modal ----------
function openLocBindModal() {
  const list = document.getElementById('locBindPersonaList');
  if (!personas || !personas.length) {
    list.innerHTML = '<div class="loc-empty-msg">尚无角色，请先創建角色</div>';
  } else {
    list.innerHTML = personas.map(p => {
      const already = locRelations.find(r => r.personaId == p.id);
      const avatarHtml = p.avatar
        ? `<img src="${p.avatar}" onerror="this.style.display='none'" style="width:36px;height:36px;border-radius:50%;object-fit:cover;border:1px solid #eee;">`
        : `<div style="width:36px;height:36px;border-radius:50%;background:#ddd;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;">${(p.name||'?')[0]}</div>`;
      return `<div class="loc-bind-persona-item">
        ${avatarHtml}
        <div class="loc-bind-persona-name">${p.name}</div>
        <select class="loc-bind-type-select" id="locBindType_${p.id}">
          <option value="">未绑定</option>
          <option value="couple" ${already?.type==='couple'?'selected':''}>情侶</option>
          <option value="friend" ${already?.type==='friend'?'selected':''}>朋友</option>
        </select>
        <button class="loc-rel-btn" onclick="applyLocBind('${monoJsSingleQuote(p.id)}')" style="font-size:9px;">设定</button>
      </div>`;
    }).join('');
  }
  document.getElementById('locBindModal').classList.add('open');
}
function closeLocBindModal() { document.getElementById('locBindModal').classList.remove('open'); }
function applyLocBind(personaId) {
  const sel = document.getElementById('locBindType_' + personaId); if (!sel) return;
  const type = sel.value;
  locRelations = locRelations.filter(r => r.personaId != personaId);
  if (type === 'couple') locRelations = locRelations.filter(r => r.type !== 'couple');
  if (type) locRelations.push({ personaId: parseInt(personaId)||personaId, type });
  saveLocData();
  closeLocBindModal();
  _renderCharBar();
  renderLocRelation();
  _renderBotMap();
  const pName = personas.find(x => x.id == personaId)?.name || '角色';
  alert(type ? `已绑定 ${pName} 为${type==='couple'?'情侶':'朋友'}！` : '已解除绑定');
}
