function renderMusicChat() {
  const area = document.getElementById('musicChatArea');
  if (!area) return;
  area.innerHTML = musicState.musicChatHistory.map((m, idx) => {
    if (m.role === 'system') {
      return `<div style="text-align:center;font-size:10px;color:#bbb;margin:6px 0;">${m.text}</div>`;
    }
    if (m.role === 'translation') {
      return `<div style="margin:0 8px 6px 44px;padding:5px 9px;border-left:2px solid #d0d0d0;font-size:10px;color:#999;font-style:italic;letter-spacing:0.3px;line-height:1.5;">${m.text}</div>`;
    }
    const p = m.persona ? personas.find(x => x.id == m.persona) : null;
    if (m.role === 'ai' && p) {
      const avatarHtml = p.avatar
        ? `<img class="music-chat-avatar" src="${p.avatar}">`
        : `<div class="music-chat-avatar-placeholder">${(p.name||'?')[0]}</div>`;
      // Check if next message is a translation row
      const nextMsg = musicState.musicChatHistory[idx + 1];
      const hasTranslation = nextMsg && nextMsg.role === 'translation';
      // Show retry if persona has foreign language but no translation follows
      const _mLang = _detectPersonaLang(p);
      let retryHtml = '';
      if (_mLang && !hasTranslation) {
        retryHtml = `<div class="music-chat-tr-retry" style="margin-top:5px;font-size:10px;color:#bbb;cursor:pointer;letter-spacing:0.5px;font-style:italic;user-select:none;" onclick="retryMusicChatTranslation(${idx},'${(m.text||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'")}')">翻譯失败 · 点擊重试</div>`;
      }
      return `<div class="music-chat-msg" data-music-idx="${idx}">
        ${avatarHtml}
        <div class="music-chat-bubble ai">${m.text}${retryHtml}</div>
      </div>`;
    } else {
      return `<div class="music-chat-msg user">
        <div class="music-chat-bubble user">${m.text}</div>
      </div>`;
    }
  }).join('');
  area.scrollTop = area.scrollHeight;
}
async function retryMusicChatTranslation(idx, text) {
  const retryEl = document.querySelector(`.music-chat-msg[data-music-idx="${idx}"] .music-chat-tr-retry`);
  if (retryEl) { retryEl.textContent = '翻譯中…'; retryEl.style.cursor = 'default'; retryEl.onclick = null; }
  if (!text || !apiConfig.url || !apiConfig.key || !apiConfig.model) {
    if (retryEl) { retryEl.textContent = '翻譯失败 · 点擊重试'; retryEl.style.cursor = 'pointer'; retryEl.onclick = function() { retryMusicChatTranslation(idx, text); }; }
    return;
  }
  try {
    const r = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
      method: 'POST', headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: '將以下文字翻譯成简体中文，只返回翻譯结果：\n' + text }], max_tokens: 150, temperature: 0.2 })
    });
    if (!r.ok) throw new Error('failed');
    const d = await r.json();
    const tr = (d.choices[0].message.content || '').trim();
    if (!tr) throw new Error('empty');
    // Insert translation row right after the AI message
    musicState.musicChatHistory.splice(idx + 1, 0, { role: 'translation', text: tr, persona: null });
    // Persist
    try { localStorage.setItem('mono_music_chat', JSON.stringify(musicState.musicChatHistory.slice(-100))); } catch(e) {}
    renderMusicChat();
  } catch(e) {
    if (retryEl) { retryEl.textContent = '翻譯失败 · 点擊重试'; retryEl.style.cursor = 'pointer'; retryEl.onclick = function() { retryMusicChatTranslation(idx, text); }; }
  }
}
