// Ensure all required fields exist on data loaded from old localStorage versions
if (!taskData.dailyChatCounts) taskData.dailyChatCounts = {};
if (!taskData.tasks) taskData.tasks = {};
if (!taskData.rewards) taskData.rewards = [];
if (!taskData.pendingRewards) taskData.pendingRewards = [];
