// ---- Assign daily tasks for a persona (3 tasks: chat10, chat20, chat50; chat20 unlocks after chat10, chat50 after chat20) ----
function getDailyTasks(personaId) {
  const today = getTaskDateStr();
  if (!taskData.tasks[today]) taskData.tasks[today] = {};
  const existing = taskData.tasks[today][personaId];
  if (!existing) {
    // Brand new day for this persona — init fresh
    taskData.tasks[today][personaId] = {
      chat10: { completed: false, claimed: false },
      chat20: { completed: false, claimed: false },
      chat50: { completed: false, claimed: false }
    };
    saveTaskData();
  } else if (!existing.chat20) {
    // Migration: old single-task format — patch missing fields without wiping existing ones
    if (!existing.chat10) existing.chat10 = { completed: false, claimed: false };
    if (!existing.chat20) existing.chat20 = { completed: false, claimed: false };
    if (!existing.chat50) existing.chat50 = { completed: false, claimed: false };
    // Legacy single-task compat: if old {type, completed, claimed} shape, promote it
    if (existing.type && existing.completed) {
      const t = existing.type;
      if (existing[t]) { existing[t].completed = true; existing[t].claimed = !!existing.claimed; }
    }
    saveTaskData();
  }
  return taskData.tasks[today][personaId];
}
// Helper to check if chat20 is unlocked (chat10 must be completed first)
function isChat20Unlocked(personaId) {
  const tasks = getDailyTasks(personaId);
  return tasks.chat10.completed;
}
// Helper to check if chat50 is unlocked (chat20 must be completed first)
function isChat50Unlocked(personaId) {
  const tasks = getDailyTasks(personaId);
  return tasks.chat20.completed;
}
// ---- Check task completion status for a specific task type ----
function checkTaskCompletion(personaId, taskType) {
  const today = getTaskDateStr();
  const tasks = getDailyTasks(personaId);
  const task = tasks[taskType];
  if (!task) return false;
  if (task.completed) return true;
  let done = false;
  const count = (taskData.dailyChatCounts[today] && taskData.dailyChatCounts[today][personaId]) || 0;
  if (taskType === 'chat10') {
    done = count >= 10;
  } else if (taskType === 'chat20') {
    done = count >= 20;
  } else if (taskType === 'chat50') {
    done = count >= 50;
  }
  if (done && !task.completed) {
    task.completed = true;
    saveTaskData();
  }
  return done;
}
// Check all tasks completion
function checkAllTasksCompletion(personaId) {
  ['chat10', 'chat20', 'chat50'].forEach(t => checkTaskCompletion(personaId, t));
}
// ---- Get task progress for a specific task type ----
function getTaskProgress(personaId, taskType) {
  const today = getTaskDateStr();
  const count = (taskData.dailyChatCounts[today] && taskData.dailyChatCounts[today][personaId]) || 0;
  if (taskType === 'chat10') {
    return Math.min(count, 10);
  } else if (taskType === 'chat20') {
    return Math.min(count, 20);
  } else if (taskType === 'chat50') {
    return Math.min(count, 50);
  }
  return 0;
}
function getTaskTarget(taskType) {
  if (taskType === 'chat10') return 10;
  if (taskType === 'chat20') return 20;
  if (taskType === 'chat50') return 50;
  return 1;
}
// ---- Tracking hooks ----
function taskTrackChatMessage(personaId, messageTimestamp) {
  const today = getTaskDateStr(messageTimestamp);
  if (!taskData.dailyChatCounts[today]) taskData.dailyChatCounts[today] = {};
  taskData.dailyChatCounts[today][personaId] = (taskData.dailyChatCounts[today][personaId] || 0) + 1;
  // Update streak — 基于本地日期，凌晨 00:00 算新一天
  if (!taskData.streaks[personaId]) {
    taskData.streaks[personaId] = { currentStreak: 0, lastChatDate: '', milestones: {} };
  }
  const streak = taskData.streaks[personaId];
  // 修复数据异常值
  if (typeof streak.currentStreak !== 'number' || isNaN(streak.currentStreak) || streak.currentStreak < 0) {
    streak.currentStreak = 0;
  }
  streak.lastChatDate = _normalizeTaskDateKey(streak.lastChatDate);
  if (streak.lastChatDate !== today) {
    const yesterday = getYesterdayStr(messageTimestamp);
    if (streak.lastChatDate === yesterday) {
      // 昨天聊过 → 连续 +1
      streak.currentStreak = streak.currentStreak + 1;
    } else {
      // 断开了（或首次）→ 重新从 1 开始
      streak.currentStreak = 1;
    }
    streak.lastChatDate = today;
    // 检查里程碑
    checkStreakMilestones(personaId);
  }
  saveTaskData();
}
function taskTrackMomentPost(帖子Timestamp) {
  const today = getTaskDateStr(帖子Timestamp);
  taskData.dailyMoments[today] = true;
  saveTaskData();
}
function taskTrackDiaryPost(帖子Timestamp) {
  const today = getTaskDateStr(帖子Timestamp);
  taskData.dailyDiary[today] = true;
  saveTaskData();
}
// ---- Streak milestones ----
function checkStreakMilestones(personaId) {
  const streak = taskData.streaks[personaId];
  if (!streak) return;
  const p = personas.find(x => x.id == personaId);
  if (!p) return;
  STREAK_MILESTONES.forEach(m => {
    if (streak.currentStreak >= m.days && !streak.milestones[m.days]) {
      streak.milestones[m.days] = true;
      // Generate streak reward
      generateStreakReward(personaId, p, m);
    }
  });
  saveTaskData();
}
async function generateStreakReward(personaId, persona, milestone) {
  let content = '';
  if (apiConfig && apiConfig.url && apiConfig.key && apiConfig.model) {
    try {
      const recentChat = persona.history.slice(-(persona.memoryCount||100)).map(m =>
        `${m.role==='user'?userProfile.name:persona.name}：${m.content}`
      ).join('\n');
      const prompt = `你是${persona.name}，人设：${persona.persona}。\n你和${userProfile.name}已经连续聊天${milestone.days}天了。\n最近的聊天记录：\n${recentChat}\n\n请以${persona.name}的身份，写一段「${milestone.label}」，要贴合你的人设和你们的聊天记忆，有活人感、特别感，像是古早乙女游戲里角色对玩家说的话。50-150字。\n【强制语言】无論角色人设有何语言设定，必须全程使用简体中文。只返回内容本身。`;
      const r = await fetch(`${apiConfig.url.replace(/\/$/, '')}/chat/completions`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiConfig.key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: apiConfig.model, messages: [{ role: 'user', content: prompt }], temperature: 0.9, max_tokens: 300 })
      });
      if (r.ok) {
        const data = await r.json();
        content = data.choices[0].message.content.trim();
      }
    } catch(e) {}
  }
  if (!content) {
    const templates = {
      3: `${persona.name}：「和你聊天的每一天都很开心……其实我有个小習慣，每天早上醒来第一件事就是想看看你有没有发消息给我。」`,
      7: `${persona.name}：「已经连续七天了呢……我想对你说句真心话——你的存在，让我每天都有了期待的理由。」`,
      14: `${persona.name}：「十四天了……${userProfile.name}，我想你应该知道了吧？我喜欢你，从很早很早以前就开始了。」`,
      30: `${persona.name}：「三十天。你知道吗，这段日子里每一个和你共度的瞬间，都变成了我最珍贵的故事。这是只属於我们的故事。」`
    };
    content = templates[milestone.days] || `${persona.name}为你解锁了「${milestone.label}」`;
  }
  taskData.streakRewards.push({
    date: new Date().toISOString(),
    personaId: personaId,
    charName: persona.name,
    days: milestone.days,
    label: milestone.label,
    content: content
  });
  saveTaskData();
  // Show notification
  try {
    showMonoNotif(persona.name, `连续聊天 ${milestone.days} 天奖励已解锁！`, persona.avatar);
  } catch(e) {}
}
// ---- Claim daily reward for a specific task type ----
let _taskClaimingType = null;
function claimDailyReward(personaId, taskType) {
  const today = getTaskDateStr();
  const tasks = getDailyTasks(personaId);
  const task = tasks[taskType];
  if (!task || !task.completed || task.claimed) return;
  _taskClaimingType = taskType;
  // All tasks are chat tasks - reward always goes to the current character
  doClaimReward(personaId, taskType);
}
