function _datingShowAutoAdvancePhase(day, phase) {
  var idx = DATING_SHOW_PHASES.indexOf(phase);
  if (idx < 0) idx = 0;
  if (idx >= DATING_SHOW_PHASES.length - 1) return { day: (parseInt(day, 10) || 1) + 1, phase: DATING_SHOW_PHASES[0] };
  return { day: parseInt(day, 10) || 1, phase: DATING_SHOW_PHASES[idx + 1] };
}
function _datingShowUserInitials() {
  var name = datingShowState && datingShowState.userProfile && datingShowState.userProfile.name || datingPrefs.userName || '你';
  return String(name).trim().charAt(0) || '你';
}
function _datingShowParticipantSummary(part) {
  var stats = part.stats || _datingShowNormalizeStats();
  return part.name + '｜' + (part.role || '') + '｜好感' + stats.favor + '｜醋意' + stats.jealousy + '｜占有欲' + stats.possession + '｜心机值' + stats.mindgame + '｜' + (part.personality || part.intro || '');
}
function _datingExtractStoryBeat(payload, state, kind, pickedGame) {
  var tag = '第' + state.day + '天·' + state.phase;
  var parts = [tag];
  // headline
  if (payload.headline) parts.push('「' + String(payload.headline).substring(0, 30) + '」');
  // game
  if (kind === 'game' && pickedGame) parts.push('游戏：' + pickedGame);
  // key events (director/host cues)
  if (payload.directorCue) parts.push('导演：' + String(payload.directorCue).substring(0, 40));
  if (payload.hostCue) parts.push('主持：' + String(payload.hostCue).substring(0, 40));
  // relationship changes
  var relLines = (payload.connectionLines || []).filter(function(l){ return l.from && l.to && l.status; });
  if (relLines.length) {
    parts.push('感情线：' + relLines.map(function(l){ return l.from + '→' + l.to + '(' + l.status + ')'; }).join('、'));
  }
  // stat changes (crushes)
  var crushLines = (payload.statUpdates || []).filter(function(s){ return s.currentCrush; });
  if (crushLines.length) {
    parts.push('心动：' + crushLines.map(function(s){ return (s.id || '') + '→' + s.currentCrush; }).join('、'));
  }
  // eliminations
  var outList = (payload.elimination && payload.elimination.out) || [];
  if (outList.length) parts.push('淘汰：' + outList.join('、'));
  // user input recorded
  if (kind === 'user' && state.logs.length) {
    var lastUser = state.logs.filter(function(l){ return l.type === 'user'; }).slice(-1)[0];
    if (lastUser) parts.push('用户发言：「' + String(lastUser.text).substring(0, 30) + '」');
  }
  return parts.join('｜');
}
function _datingShowPickGame(state) {
  var lib = (DATING_SHOW_LIBRARY[state.mode] || DATING_SHOW_LIBRARY.solo6).slice();
  if (!Array.isArray(state.usedGames)) state.usedGames = [];
  var available = lib.filter(function(g) { return state.usedGames.indexOf(g) < 0; });
  if (!available.length) {
    // 本季所有游戏都玩过了，重置记录重新来过
    state.usedGames = [];
    available = lib;
  }
  var picked = available[Math.floor(Math.random() * available.length)];
  state.usedGames.push(picked);
  return picked;
}
