          + '<div style="font-size:11px;font-weight:800;color:#111;margin-bottom:10px;line-height:1.6;">' + _esc(state.gameChoices.prompt || '请选择你的行动') + '</div>'
          + '<div style="display:flex;flex-direction:column;gap:7px;">'
