function saveDatingMemoryLimit() {
  var slider = document.getElementById('datingMemorySlider');
  if (!slider || !datingCurrentPid) return;
  var val = Math.max(10, Math.min(50000, parseInt(slider.value) || 100));
  var session = _getSession(datingCurrentPid);
  session.memoryLimit = val;
  saveDatingSessions();
  closeDatingChatOptionsModal();
  // Brief toast feedback
  var toast = document.createElement('div');
  toast.textContent = '已设定记忆 ' + Number(val).toLocaleString() + ' 条 ✓';
  toast.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#1a1a1a;color:#fff;padding:8px 18px;border-radius:20px;font-size:12px;font-weight:700;z-index:9999;pointer-events:none;opacity:1;transition:opacity 0.4s;';
  document.body.appendChild(toast);
  setTimeout(function(){ toast.style.opacity='0'; setTimeout(function(){ toast.remove(); }, 400); }, 1600);
}
