function _syncDatingPrefUI() {
  ['min回复','max回复','timeSense','userName'].forEach(function(k) {
    var el = document.getElementById('dpv_' + k);
    if (el) el.textContent = datingPrefs[k] || '-';
  });
  _syncDatingUserProfileCard();
}
function _syncDatingUserProfileCard() {
  var rn = datingPrefs.userRealName || '';
  var nn = datingPrefs.userNickname || '';
  var age = datingPrefs.userAge || '';
  var gender = datingPrefs.userGender || '';
  var bio = datingPrefs.userBio || '';
  // Display name: real name first, fallback to nickname
  var displayName = rn || nn || '未填写';
  var metaParts = [];
  if (gender) metaParts.push(gender);
  if (age) metaParts.push(age + ' 岁');
  var meta = metaParts.join(' · ');
  var nameEl = document.getElementById('datingUserProfileDisplayName');
  var metaEl = document.getElementById('datingUserProfileDisplayMeta');
  var bioEl  = document.getElementById('datingUserProfileBioPreview');
  var avEl   = document.getElementById('datingUserProfileAvatar');
  if (nameEl) nameEl.textContent = displayName;
  if (metaEl) metaEl.textContent = meta;
  if (bioEl) {
    if (bio) { bioEl.textContent = bio; bioEl.style.color = '#666'; bioEl.style.fontStyle = 'normal'; }
    else { bioEl.textContent = '点擊「编辑」填写你的个人资料，让心动对象更了解你'; bioEl.style.color = '#bbb'; bioEl.style.fontStyle = 'italic'; }
  }
  // Avatar: first letter of real name or nickname
  var initials = (rn || nn || '?').charAt(0).toUpperCase();
  if (avEl) avEl.textContent = initials;
  // Also sync form fields if visible
  var rnEl = document.getElementById('dpf_realName');
  var nkEl = document.getElementById('dpf_nickname');
  var agEl = document.getElementById('dpf_age');
  var gnEl = document.getElementById('dpf_gender');
  var biEl = document.getElementById('dpf_bio');
  if (rnEl) rnEl.value = rn;
  if (nkEl) nkEl.value = nn;
  if (agEl) agEl.value = age;
  if (gnEl) gnEl.value = gender;
  if (biEl) biEl.value = bio;
}
function toggleDatingProfileEdit() {
  var form = document.getElementById('datingProfileEditForm');
  if (!form) return;
  var isHidden = form.style.display === 'none';
  form.style.display = isHidden ? 'block' : 'none';
  if (isHidden) _syncDatingUserProfileCard(); // pre-fill form
}
function saveDatingUserProfile() {
  datingPrefs.userRealName = (document.getElementById('dpf_realName').value || '').trim();
  datingPrefs.userNickname = (document.getElementById('dpf_nickname').value || '').trim();
  datingPrefs.userAge      = (document.getElementById('dpf_age').value || '').trim();
  datingPrefs.userGender   = (document.getElementById('dpf_gender').value || '').trim();
  datingPrefs.userBio      = (document.getElementById('dpf_bio').value || '').trim();
  // Sync userName so existing nickname system still works
  if (datingPrefs.userNickname) datingPrefs.userName = datingPrefs.userNickname;
  else if (datingPrefs.userRealName) datingPrefs.userName = datingPrefs.userRealName;
  saveDatingPrefs();
  _syncDatingPrefUI();
  document.getElementById('datingProfileEditForm').style.display = 'none';
  // Brief save confirmation
  var btn = document.querySelector('.dating-profile-save-btn');
  if (btn) { btn.textContent = '✓ 已储存'; setTimeout(function(){ btn.textContent = '储存资料'; }, 1500); }
}
function _buildDatingUserProfileDesc() {
  // Returns a natural language string to inject into AI prompts
  var rn = datingPrefs.userRealName || '';
  var nn = datingPrefs.userNickname || '';
  var age = datingPrefs.userAge || '';
  var gender = datingPrefs.userGender || '';
  var bio = datingPrefs.userBio || '';
  var parts = [];
  if (rn) parts.push('真实姓名是「' + rn + '」');
  if (nn && nn !== rn) parts.push('昵称是「' + nn + '」');
  if (age) parts.push(age + '岁');
  if (gender) parts.push(gender + '性');
  if (bio) parts.push('个人介绍：' + bio);
  if (parts.length === 0) return '';
  return parts.join('，');
}
