// ── Time-sense scheduled proactive messages ──
function _scheduleDatingTimeSenseAll() {
  if (datingPrefs.timeSense === '关闭') return;
  Object.keys(datingSessions).forEach(function(pid) {
    var s = datingSessions[pid];
    if (!s.history || !s.history.length) return;
    var last = s.history[s.history.length-1];
    if (last.role !== 'user') return;
    var diff = Date.now() - (last.ts || 0);
    if (diff > 30*60*1000 && diff < 4*60*60*1000) {
      _datingNotifTimers[pid] = setTimeout(function() {
        delete _datingNotifTimers[pid];
        _sendDatingProactiveMsg(pid);
      }, 5000 + Math.random() * 20000);
    }
  });
}
// ── Export / Import integration ──
function getDatingExportData() {
  return {
    sessions: datingSessions,
    prefs: datingPrefs,
    icon: localStorage.getItem('mono_icon_dating') || null,
    showState: datingShowState
  };
}
function loadDatingImportData(data) {
  if (data.sessions) { datingSessions = data.sessions; saveDatingSessions(); }
  if (data.prefs)    { datingPrefs = data.prefs; saveDatingPrefs(); }
  if (data.icon)     { localStorage.setItem('mono_icon_dating', data.icon); _loadDatingIcon(); }
  if (data.showState && typeof data.showState === 'object') {
    datingShowState = Object.assign(datingShowDefaultState(), data.showState);
    datingShowSave();
  } else {
    datingShowLoad();
  }
  _syncDatingPrefUI();
  renderDatingContacts();
  renderDatingShowPage();
}
