  if (data.content && data.content[0] && data.content[0].text) return { text: String(data.content[0].text || '').trim(), finishReason: (data.stop_reason || '').toLowerCase(), data: data };
  if (data.choices && data.choices[0] && data.choices[0].message) return { text: String(data.choices[0].message.content || '').trim(), finishReason: String((data.choices[0].finish_reason || '')).toLowerCase(), data: data };
  if (data.choices && data.choices[0] && typeof data.choices[0].text === 'string') return { text: data.choices[0].text.trim(), finishReason: String((data.choices[0].finish_reason || '')).toLowerCase(), data: data };
  if (data.error) throw new Error(data.error.message || JSON.stringify(data.error).slice(0, 500));
  throw new Error('API 返回格式异常：找不到 content[0].text 或 choices[0].message.content');
