  var FULL_RECENT = 30;   // 最近 30 条完整
  var MAX_OLDER   = 60;   // 更早的条目最多再往前取 45 条（截断版）
  var fullStart  = Math.max(0, total - FULL_RECENT);
  var olderStart = Math.max(0, fullStart - MAX_OLDER);
