        + (isActive ? '<div class="pet-collection-active-badge">使用中</div>' : '')
        + '<img src="' + char.img() + '" alt="' + char.name + '">'
        + '<div class="pet-collection-item-name">' + char.emoji + ' ' + char.name + '</div>'
        + '<div class="pet-collection-stage">' + stages[p.stage || 0] + '</div>'
        + '<div style="font-size:8px;color:#bbb;">亲密 Lv' + Math.floor((p.intimacy||0)/5+1) + '</div>'
        + '</div>';
