function _petCheckStage() {
  const pet = _petState.pet; if (!pet) return;
  const elapsed = (Date.now() - pet.bornAt) / (1000*60*60*24);
  const newStage = elapsed >= 4 ? 2 : elapsed >= 1 ? 1 : 0;
  if (newStage > (pet.stage||0)) {
    pet.stage = newStage;
    const stageNames = ['幼崽期','成长期','完全体'];
    pet.archive = (pet.archive||[]).concat([{ ts:Date.now(), event:'成长到「'+stageNames[newStage]+'」！🌟' }]);
    _savePet();
  }
}
