function closePetTasksOverlay(e) {
  if (!e || e.target === document.getElementById('petTasksOverlay'))
    document.getElementById('petTasksOverlay').classList.remove('open');
}
function _refreshPetTasksOverlay() {
  const t = _loadPetTasks();
  const hasPet = !!_petState.pet;
  const TASKS = [
    { key:'checkin', icon:'📅', name:'每日簽到',   desc:'打开寵物屋自动完成',  reward:'扭蛋碎片 ×1', rType:'gacha' },
    { key:'feed',    icon:'🍽️', name:'投喂寵物一次', desc:'喂任意食物即可',       reward:'扭蛋碎片 ×1', rType:'gacha' },
    { key:'play',    icon:'🎮', name:'陪玩一次',    desc:'玩任意小游戲即可',    reward:'裝扮碎片 ×1', rType:'dress' },
    { key:'bath',    icon:'🛁', name:'帮寵物洗澡',  desc:'点擊洗澡按钮即可',    reward:'裝扮碎片 ×1', rType:'dress' },
    { key:'sleep',   icon:'💤', name:'哄寵物睡觉',  desc:'点擊哄睡按钮即可',    reward:'裝扮碎片 ×1', rType:'dress' },
  ];
  const canExGacha = (t.gachaFrags||0) >= 5;
  const canExDress  = (t.dressFrags||0) >= 10 && hasPet;
  const listHtml = TASKS.map(function(task) {
    const done    = !!t[task.key];
    const canClaim= done && !t[task.key+'_claimed'];
    const claimed = !!t[task.key+'_claimed'];
    let action;
    if (claimed)   action = '<div class="pet-task-row-done">✓ 已領取</div>';
    else if (canClaim) action = '<button class="pet-task-row-claim" onclick="petClaimTask(\''+task.key+'\')">領取</button>';
    else           action = '<div class="pet-task-row-reward">'+task.reward+'</div>';
    return '<div class="pet-task-row'+(claimed?' done':'')+'">'
      +'<div class="pet-task-row-icon">'+task.icon+'</div>'
      +'<div class="pet-task-row-info"><div class="pet-task-row-name">'+task.name+'</div><div class="pet-task-row-desc">'+task.desc+'</div></div>'
      +action+'</div>';
  }).join('');
  const exchangeHtml = ''
    +'<div class="pet-task-exchange-row">'
    +'<div class="pet-task-exchange-from">🎰 扭蛋碎片 × 5</div>'
    +'<div class="pet-task-exchange-arrow">→</div>'
    +'<div class="pet-task-exchange-to">免费扭蛋 × 1</div>'
    +'<button class="pet-task-exchange-btn"'+(canExGacha?' onclick="petExchangeFragment(\'gacha\')"':' disabled')+'>兌换</button>'
    +'</div>'
    +'<div class="pet-task-exchange-row">'
    +'<div class="pet-task-exchange-from">✨ 裝扮碎片 × 10</div>'
    +'<div class="pet-task-exchange-arrow">→</div>'
    +'<div class="pet-task-exchange-to">解锁随机裝扮 × 1</div>'
    +'<button class="pet-task-exchange-btn"'+(canExDress?' onclick="petExchangeFragment(\'dress\')"':' disabled')+'>兌换</button>'
    +'</div>';
  document.getElementById('petTasksSheetBody').innerHTML =
    '<div class="pet-tasks-sheet-frag-bar">'
    +'<div class="pet-tasks-frag-cell"><div class="pet-tasks-frag-icon">🎰</div><div class="pet-tasks-frag-info"><div class="pet-tasks-frag-count">'+(t.gachaFrags||0)+'</div><div class="pet-tasks-frag-label">扭蛋碎片</div></div></div>'
    +'<div class="pet-tasks-frag-divider"></div>'
    +'<div class="pet-tasks-frag-cell"><div class="pet-tasks-frag-icon">✨</div><div class="pet-tasks-frag-info"><div class="pet-tasks-frag-count">'+(t.dressFrags||0)+'</div><div class="pet-tasks-frag-label">裝扮碎片</div></div></div>'
    +'</div>'
    +'<div class="pet-tasks-sheet-list">'+listHtml+'</div>'
    +'<div class="pet-tasks-exchange-title">碎片兌换</div>'
    +exchangeHtml;
}
function petClaimTask(taskKey) {
  const t = _loadPetTasks();
  if (!t[taskKey] || t[taskKey+'_claimed']) return;
  const TASK_REWARDS = { checkin:'gacha', feed:'gacha', play:'dress', bath:'dress', sleep:'dress' };
  const rType = TASK_REWARDS[taskKey];
  if (rType === 'gacha') t.gachaFrags = (t.gachaFrags||0) + 1;
  else t.dressFrags = (t.dressFrags||0) + 1;
  t[taskKey+'_claimed'] = true;
  _savePetTasks(t);
  _petUpdateTaskDot();
  _refreshPetTasksOverlay();
}
function petExchangeFragment(type) {
  const t = _loadPetTasks();
  if (type === 'gacha') {
    if ((t.gachaFrags||0) < 5) return;
    t.gachaFrags -= 5;
    // Grant one free pull: reduce weeklyUsed by 1 (effectively +1 remaining)
    _petGacha.weeklyUsed = Math.max(0, (_petGacha.weeklyUsed||0) - 1);
    _savePetGacha();
    _savePetTasks(t);
    alert('兌换成功！获得免费扭蛋 ×1 🎰\n现在去扭蛋机试试吧！');
    _refreshPetTasksOverlay();
  } else if (type === 'dress') {
    if ((t.dressFrags||0) < 10) return;
    const pet = _petState.pet; if (!pet) return;
    const wb = PET_WARDROBE[pet.key];
    if (!wb) return;
    const d = _loadPetDress();
    const allItems = wb.clothes.concat(wb.furniture).map(function(i){ return i.key; });
    const locked = allItems.filter(function(k){ return !d.owned.includes(k); });
    if (locked.length === 0) { alert('目前寵物的所有裝扮都已解锁啦！✨'); return; }
    const unlocked = locked[Math.floor(Math.random() * locked.length)];
    d.owned.push(unlocked);
    _savePetDress(d);
    t.dressFrags -= 10;
    _savePetTasks(t);
    // Find item name
    const allItemData = wb.clothes.concat(wb.furniture);
    const item = allItemData.find(function(i){ return i.key === unlocked; });
    alert('兌换成功！解锁了「'+(item?item.name:unlocked)+'」'+( item?item.icon:'')+'✨\n快去点「裝扮」按钮穿戴吧！');
    _refreshPetTasksOverlay();
  }
}
// ── Dress Overlay ──
let _petDressSubTab = 'clothes';
function openPetDressOverlay() {
  _petDressSubTab = 'clothes';
  _refreshPetDressOverlay();
  document.getElementById('petDressOverlay').classList.add('open');
}
function closePetDressOverlay(e) {
  if (!e || e.target === document.getElementById('petDressOverlay'))
    document.getElementById('petDressOverlay').classList.remove('open');
}
function _refreshPetDressOverlay() {
  const pet = _petState.pet; if (!pet) return;
  const char  = PET_CHARS[pet.key] || PET_CHARS.kitty;
  const wb    = PET_WARDROBE[pet.key] || { clothes:[], furniture:[] };
  const d     = _loadPetDress();
  const intimacy = Math.floor((pet.intimacy||0) / 5);
  // Sub-tab active state
  document.querySelectorAll('.pet-dress-sheet-sub').forEach(function(el, i) {
    el.classList.toggle('active', (i === 0 && _petDressSubTab === 'clothes') || (i === 1 && _petDressSubTab === 'furniture'));
  });
  // Equipped chips
  const equippedEl = document.getElementById('petDressEquipped');
  const equippedKeys = Object.values(d.equipped || {}).filter(Boolean);
  const allItems = wb.clothes.concat(wb.furniture);
  if (equippedKeys.length > 0) {
    equippedEl.innerHTML = equippedKeys.map(function(k) {
      const it = allItems.find(function(i){ return i.key === k; });
      return '<div class="pet-dress-equipped-chip">'+(it ? it.icon+it.name : k)+'</div>';
    }).join('');
  } else {
    equippedEl.innerHTML = '<div style="font-size:10px;color:#bbb;">尚未穿戴任何裝扮</div>';
  }
  // Items grid
  const items = _petDressSubTab === 'clothes' ? wb.clothes : wb.furniture;
  function isUnlocked(item) {
    if (d.owned.includes(item.key)) return true;
    if (item.unlockType === 'intimacy') return intimacy >= item.unlockVal;
    if (item.unlockType === 'stage') return (pet.stage||0) >= item.unlockVal;
    return false;
  }
  function unlockHint(item) {
    if (item.unlockType === 'intimacy') return '亲密度 Lv'+item.unlockVal;
    if (item.unlockType === 'fragment') return '碎片×'+item.unlockVal+' 兌换';
    if (item.unlockType === 'stage') return ['幼崽期','成长期','完全体'][item.unlockVal]||'';
    return '';
  }
  const cat = _petDressSubTab;
  document.getElementById('petDressGrid').innerHTML = items.map(function(item) {
    const locked  = !isUnlocked(item);
    const isEquip = d.equipped && d.equipped[cat] === item.key;
    return '<div class="pet-dress-tile'+(isEquip?' equipped':'')+(locked?' locked':'')+'"'
      +(!locked ? ' onclick="petToggleEquip(\''+cat+'\',\''+item.key+'\')"' : '')+'>'
      +'<div class="pet-dress-tile-icon">'+item.icon+'</div>'
      +'<div class="pet-dress-tile-name">'+item.name+'</div>'
      +(isEquip ? '<div class="pet-dress-tile-badge">✓ 穿戴中</div>'
        : locked ? '<div class="pet-dress-tile-lock">🔒</div><div class="pet-dress-tile-hint">'+unlockHint(item)+'</div>'
        : '')
      +'</div>';
  }).join('');
}
function switchPetDressSubTab(sub) {
  _petDressSubTab = sub;
  _refreshPetDressOverlay();
}
function petToggleEquip(category, itemKey) {
  const d = _loadPetDress();
  if (!d.equipped) d.equipped = {};
  d.equipped[category] = (d.equipped[category] === itemKey) ? null : itemKey;
  _savePetDress(d);
  _refreshPetDressOverlay();
}
// ── Stat decay ──
function _petDecayStats() {
  const pet = _petState.pet; if (!pet) return;
  const now = Date.now();
  const lastCheck = pet.lastDecay || now;
  const hours = (now - lastCheck) / 3600000;
  if (hours < 0.05) return;
  pet.hunger = Math.max(0, (pet.hunger||80) - hours * 5);
  pet.mood = Math.max(0, (pet.mood||80) - hours * 3);
  pet.clean = Math.max(0, (pet.clean||80) - hours * 2);
  pet.energy = Math.max(0, (pet.energy||80) - hours * 2);
  pet.lastDecay = now;
  _savePet();
}
// Pre-load pet state from IndexedDB-backed storage after DB is ready
if (typeof window !== 'undefined' && typeof window.afterDB === 'function') {
  window.afterDB(function() {
    _reloadPetState();
    // Apply saved pet icon to home screen
    const petIconData = localStorage.getItem('mono_icon_pet');
    if (petIconData) {
      const petBox = document.getElementById('igPetIconBox');
      if (petBox) petBox.innerHTML = '<img class="custom-icon" src="' + petIconData + '" style="border-radius:18px;">';
    }
    const shopIconData = localStorage.getItem('mono_icon_shopApp');
    if (shopIconData) {
      const shopBox = document.getElementById('igShopIconBox');
      if (shopBox) shopBox.innerHTML = '<img class="custom-icon" src="' + shopIconData + '" style="border-radius:18px;">';
    }
  });
}
