// ── State helpers (multi-shop) ──
const SHOP_LIST_KEY = 'mono_shop_list';
let _shopActiveIdx = 0;
function _loadShopList() {
  try {
    // migrate legacy single-shop data
    const legacy = localStorage.getItem(SHOP_STORAGE_KEY);
    if (legacy) {
      const obj = JSON.parse(legacy);
      if (obj && obj.type) {
        const list = [obj];
        if (typeof safeSetItem==='function') safeSetItem(SHOP_LIST_KEY, JSON.stringify(list));
        else localStorage.setItem(SHOP_LIST_KEY, JSON.stringify(list));
        localStorage.removeItem(SHOP_STORAGE_KEY);
        return list;
      }
    }
    return JSON.parse(localStorage.getItem(SHOP_LIST_KEY)||'null') || [];
  } catch(e) { return []; }
}
function _saveShopList(list) {
  try {
    const str = JSON.stringify(list);
    if (typeof safeSetItem==='function') safeSetItem(SHOP_LIST_KEY, str);
    else localStorage.setItem(SHOP_LIST_KEY, str);
  } catch(e) {}
}
// These two are used everywhere — they read/write the ACTIVE shop
function _loadShop() {
  const list = _loadShopList();
  return list[_shopActiveIdx] || {};
}
function _saveShop(s) {
  const list = _loadShopList();
  list[_shopActiveIdx] = s;
  _saveShopList(list);
}
function _loadShopTasks() {
  try {
    const t = JSON.parse(localStorage.getItem(SHOP_TASKS_KEY)||'null') || {};
    const today = new Date().toDateString();
    if (t.date !== today) return { date:today, progress:{}, claimed:{}, achvProgress: t.achvProgress||{}, achvClaimed: t.achvClaimed||{} };
    return t;
  } catch(e) { return { date:new Date().toDateString(), progress:{}, claimed:{}, achvProgress:{}, achvClaimed:{} }; }
}
function _saveShopTasks(t) {
  try {
    if (typeof safeSetItem==='function') safeSetItem(SHOP_TASKS_KEY, JSON.stringify(t));
    else localStorage.setItem(SHOP_TASKS_KEY, JSON.stringify(t));
  } catch(e) {}
}
function _getShopCoins() {
  try { return parseInt(localStorage.getItem(SHOP_COINS_KEY)||'0',10)||0; } catch(e){ return 0; }
}
function _addShopCoins(n) {
  const c = _getShopCoins() + n;
  try { localStorage.setItem(SHOP_COINS_KEY, String(c)); } catch(e){}
  return c;
}
function _spendShopCoins(n) {
  const c = _getShopCoins();
  if (c < n) return false;
  try { localStorage.setItem(SHOP_COINS_KEY, String(c-n)); } catch(e){}
  return true;
}
let _shopTab = 'overview';
let _shopReportPeriod = 'day';
let _shopTrainingStaffId = null;
// ── Open / Close ──
function openShopApp() {
  _updateShopWalletChip();
  document.getElementById('shopAppPage').classList.add('active');
  const list = _loadShopList();
  if (!list.length) {
    _shopActiveIdx = 0;
    _renderShopSetup();
  } else {
    // Clamp active index
    if (_shopActiveIdx >= list.length) _shopActiveIdx = list.length - 1;
    _shopCheckFreshness();
    _shopTrackOpenHours();
    document.getElementById('shopAppTabs').style.display='flex';
    _renderShopSwitcherBar();
    switchShopTab('overview');
  }
}
function closeShopApp() { document.getElementById('shopAppPage').classList.remove('active'); }
