let _hD = (() => { try { return JSON.parse(localStorage.getItem('mono_health_v2')) || {}; } catch(e) { return {}; } })();
(function _hInit() {
  if (!_hD.periods)   _hD.periods   = [];
  if (!_hD.exercises) _hD.exercises = [];
  if (!_hD.steps)     _hD.steps     = {};
  if (!_hD.settings)  _hD.settings  = {};
  const s = _hD.settings;
  if (!s.stepGoal)         s.stepGoal = 8000;
  if (!s.cycleLen)         s.cycleLen = 28;
  if (!s.sharedPersonas)   s.sharedPersonas = {};
  if (!s.remindPersonas)   s.remindPersonas = {};
  if (!s.sitRemind)        s.sitRemind = false;
  if (!s.heightCm)         s.heightCm = 165;
  if (!s.weightKg)         s.weightKg = 55;
})();
function _hSave() {
  const _hJson = JSON.stringify(_hD);
  if (typeof safeSetItem === 'function') {
    safeSetItem('mono_health_v2', _hJson).catch(function() {
      localStorage.setItem('mono_health_v2', _hJson);
    });
  } else {
    localStorage.setItem('mono_health_v2', _hJson);
  }
}
