// ── AI health injection ──
function _buildHealthInjection(personaId) {
  if (!_hD.settings.sharedPersonas[String(personaId)]) return '';
  const st = _hGetStatus();
  if (st.type === 'unknown') return '';
  const fMap = { light:'少量', medium:'中量', heavy:'多量', very_heavy:'极多' };
  const pMap = { none:'无', mild:'轻微', moderate:'明显', severe:'严重' };
  let txt = '\n\n【用户健康信息——已获得用户授权，请自然融入对话，不要频繁提及】\n';
  if      (st.type === 'period')   txt += `用户当前处于经期第${st.day}天${st.flow ? '，经量'+fMap[st.flow] : ''}${(st.pain && st.pain!=='none') ? '，痛经'+pMap[st.pain] : ''}。请以符合你人设的方式适时表达关心（如提醒保暖、注意休息）。`;
  else if (st.type === 'soon')     txt += `用户经期预计${st.daysToNext}天后到来（约${st.nextDate}），可适当提醒。`;
  else if (st.type === 'ovulation')txt += `用户目前处于排卵期附近，下次经期约${st.daysToNext}天后（${st.nextDate}）。`;
  else if (st.type === 'safe')     txt += `用户处于安全期，下次经期约${st.daysToNext}天后（${st.nextDate}）。`;
  else if (st.type === 'overdue')  txt += `用户经期已推迟${st.days}天，可适当关心。`;
  txt += '\n（请仅在对话自然时机关心一次，不要每条消息都提及。）';
  return txt;
}
// ── Status helpers ──
function _hGetAvgCycle() {
  const ps = _hD.periods;
  if (ps.length < 2) return _hD.settings.cycleLen || 28;
  const sorted = [...ps].sort((a,b) => new Date(a.startDate)-new Date(b.startDate));
  let tot = 0, cnt = 0;
  for (let i = 1; i < sorted.length && i <= 3; i++) {
    const d = Math.round((new Date(sorted[i].startDate)-new Date(sorted[i-1].startDate))/86400000);
    if (d > 0 && d < 60) { tot += d; cnt++; }
  }
  return cnt > 0 ? Math.round(tot/cnt) : (_hD.settings.cycleLen || 28);
}
function _hGetStatus() {
  const ps = _hD.periods;
  const today = new Date(); today.setHours(0,0,0,0);
  if (!ps.length) return { type:'unknown' };
  const sorted = [...ps].sort((a,b) => new Date(b.startDate)-new Date(a.startDate));
  const last = sorted[0];
  const ls = new Date(last.startDate); ls.setHours(0,0,0,0);
  const le = last.endDate ? new Date(last.endDate) : null;
  if (le) le.setHours(0,0,0,0);
  if (today >= ls && (!le || today <= le))
    return { type:'period', day: Math.round((today-ls)/86400000)+1, flow:last.flow, pain:last.pain };
  const cyc = _hGetAvgCycle();
  const nx = new Date(ls); nx.setDate(nx.getDate()+cyc);
  const dtn = Math.round((nx-today)/86400000);
  const nxStr = nx.toISOString().slice(0,10);
  if (dtn < 0)  return { type:'overdue', days: Math.abs(dtn) };
  if (dtn <= 5) return { type:'soon', daysToNext:dtn, nextDate:nxStr };
  const ovS = new Date(ls); ovS.setDate(ovS.getDate()+cyc-14);
  const ovE = new Date(ovS); ovE.setDate(ovE.getDate()+4);
  if (today >= ovS && today <= ovE) return { type:'ovulation', daysToNext:dtn, nextDate:nxStr };
  return { type:'safe', daysToNext:dtn, nextDate:nxStr };
}
function _hGet今天Steps() {
  const k = new Date().toISOString().slice(0,10);
  return _hD.steps[k] || 0;
}
function _hGetWeekSteps() {
  const res = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(); d.setDate(d.getDate()-i);
    const k = d.toISOString().slice(0,10);
    res.push({ date:k, label:['日','一','二','三','四','五','六'][d.getDay()], steps:_hD.steps[k]||0, is今天:i===0 });
  }
  return res;
}
// ── Page switching ──
function _haSwitchPage(page) {
  _hPage = page;
  document.querySelectorAll('.ha-nav-tab').forEach(t => t.classList.remove('active'));
  const navEl = document.getElementById('hNav' + page.charAt(0).toUpperCase() + page.slice(1));
  if (navEl) navEl.classList.add('active');
  const titles = { home:'健康记录', steps:'步数', exercise:'运动', period:'经期', share:'共享', settings:'设置' };
  document.getElementById('haHeaderTitle').textContent = titles[page] || '健康记录';
  const hdr = document.getElementById('haHeaderRight');
  hdr.innerHTML = '';
  if (page === 'steps') {
    hdr.innerHTML = '<button class="ha-header-btn" onclick="_hOpenStepEdit()" title="修改步数"><i class="fas fa-pen"></i></button><button class="ha-header-btn" onclick="_hExportSteps()"><i class="fas fa-download"></i></button>';
  } else if (page === 'exercise') {
    hdr.innerHTML = '<button class="ha-header-btn" onclick="_hOpenTimer()"><i class="fas fa-stopwatch"></i></button><button class="ha-header-btn" onclick="_hOpenExModal(null)"><i class="fas fa-plus"></i></button>';
  } else if (page === 'period') {
    hdr.innerHTML = '<button class="ha-header-btn" onclick="_hOpenPModal(null)"><i class="fas fa-plus"></i></button>';
  } else {
    hdr.innerHTML = '<button class="ha-header-btn" onclick="closeHealthApp()"><i class="fas fa-times"></i></button>';
  }
  const fab = document.getElementById('haFab');
  fab.className = 'ha-fab' + ((page==='exercise'||page==='period') ? ' show' : '');
  _haRenderPage(document.getElementById('haBody'));
}
