  var senderName = msg.role === 'user' ? (up.name||'我') : msg.sender === 'pet' ? char.name : (pChar ? pChar.name : '夥伴');
  var menu = document.createElement('div');
  menu.className = 'msg-context-menu';
  menu.id = 'petChatCtxMenu';
  var btns = [
    { icon: 'fa-copy',       label: '复制', action: function(){ _petChatCopyMsg(msg.content); } },
    { icon: 'fa-quote-left', label: '引用', action: function(){ _petChatSetQuote(idx, senderName, msg.content); } },
    { icon: 'fa-trash-alt',  label: '刪除', action: function(){ _petChatDeleteMsg(idx); }, danger: true },
  ];
  btns.forEach(function(b) {
    var btn = document.createElement('div');
    btn.className = 'ctx-btn' + (b.danger ? ' danger' : '');
    btn.innerHTML = '<i class="fas ' + b.icon + '"></i><span>' + b.label + '</span>';
    btn.addEventListener('click', function(ev) { ev.stopPropagation(); b.action(); _petChatCloseMsgMenu(); });
    menu.appendChild(btn);
  });
  // Position menu near touch/click point
  menu.style.position = 'fixed';
  menu.style.zIndex   = '99999';
  document.body.appendChild(menu);
  var x = event.clientX || 0;
  var y = event.clientY || 0;
  var mw = menu.offsetWidth  || 180;
  var mh = menu.offsetHeight || 60;
  var vw = window.innerWidth;
  var vh = window.innerHeight;
  menu.style.left = Math.min(x, vw - mw - 8) + 'px';
  menu.style.top  = (y - mh - 8 < 0 ? y + 8 : y - mh - 8) + 'px';
