// ── FAB visibility ──
function updateFabVisibility() {
  const fab = document.getElementById('apiFab');
  const panel = document.getElementById('apiFabPanel');
  if (!fab) return;

  // Check whether any app page is currently visible/active.
  const visiblePages = Array.from(document.querySelectorAll('.page')).filter(function(el) {
    if (!el) return false;
    const isActive = el.classList.contains('active');
    const styleDisplay = (el.style && el.style.display) ? el.style.display : '';
    return isActive || (styleDisplay && styleDisplay !== 'none');
  });
  const homeScreen = document.getElementById('homeScreen');
  const isHome = !!(homeScreen && homeScreen.style.display !== 'none' && visiblePages.length === 0);

  // Check if any page2 app overlay is active
  const page2AppIds = ['locationPage','musicPage','datingAppPage','blackboxPage','taskPage','petAppPage','shopAppPage','healthAppPage','babyAppPage','decryptPage'];
  let anyPage2AppOpen = false;
  for (const pid of page2AppIds) {
    const el = document.getElementById(pid);
    if (el && (el.classList.contains('active') || (el.style.display && el.style.display !== 'none'))) {
      anyPage2AppOpen = true;
      break;
    }
  }
  
  if (fabEnabled && (!isHome || anyPage2AppOpen)) {
    fab.style.display = 'flex';
  } else {
    fab.style.display = 'none';
    if (panel) panel.classList.remove('show');
    fabPanelOpen = false;
  }
}
