// ============================================================
//  宝宝养成 · Baby App System  (v3 — multi-baby, siblings, twins, events)
// ============================================================
// ---- localStorage helpers ----
function getBabyData() {
  try { return JSON.parse(localStorage.getItem('mono_baby_data') || '{}'); } catch(e) { return {}; }
}
function saveBabyData(d) {
  localStorage.setItem('mono_baby_data', JSON.stringify(d));
}
function getFwSettings() {
  try {
    var s = JSON.parse(localStorage.getItem('mono_fw_settings') || '{}');
    if (!s.displayFamily) s.displayFamily = null;
    if (s.blur == null) s.blur = 0;
    // bgImage is stored in a separate key to avoid localStorage quota issues
    if (!s.bgImage || s.bgImage === '__ref__') {
      s.bgImage = localStorage.getItem('mono_fw_bg') || null;
    }
    return s;
  }
  catch(e) { return {displayFamily:null, blur:0, bgImage:null}; }
}
function saveFwSettings(s) {
  // Split bgImage into separate key (same pattern as chatBgImage / mono_bg_<id>)
  var sToStore = Object.assign({}, s);
  if (sToStore.bgImage && sToStore.bgImage !== '__ref__') {
    try {
      localStorage.setItem('mono_fw_bg', sToStore.bgImage);
      sToStore.bgImage = '__ref__';
    } catch(e) { /* quota exceeded - keep inline as fallback */ }
  } else if (!sToStore.bgImage) {
    localStorage.removeItem('mono_fw_bg');
    sToStore.bgImage = null;
  }
  localStorage.setItem('mono_fw_settings', JSON.stringify(sToStore));
}
function getPersonas() {
  if (typeof personas !== 'undefined' && personas && personas.length > 0) return personas;
  try { return JSON.parse(localStorage.getItem('mono_personas') || '[]'); } catch(e) { return []; }
}
function getUserProfile() {
  if (arguments.length > 0 && arguments[0]) {
    return monoResolveUserIdentityProfile(arguments[0]);
  }
  if (typeof userProfile !== 'undefined' && userProfile) return monoNormalizeUserProfile(userProfile);
  try { return monoNormalizeUserProfile(JSON.parse(localStorage.getItem('mono_user_profile') || '{"name":"我"}')); } catch(e) { return monoNormalizeUserProfile({name:'我'}); }
}
// ---- Multi-baby helpers ----
// babies are stored as data.babyList[personaId] = [ babyObj, ... ]  (array, order = birth order)
// legacy: data.babies[personaId] = babyObj  → auto-migrated on first load
function getBabyList(personaId) {
  var data = getBabyData();
  // Migration: if old single-baby exists, convert
  if (!data.babyList) data.babyList = {};
  if (!data.babyList[personaId]) {
    data.babyList[personaId] = [];
    if (data.babies && data.babies[personaId]) {
      var old = data.babies[personaId];
      old._babyIdx = 0;
      old._birthOrder = 0;
      if (!old.birthYear) old.birthYear = new Date().getFullYear() - Math.floor((parseInt(old.ageMonths)||0)/12);
      data.babyList[personaId] = [old];
      saveBabyData(data);
    }
  }
  return data.babyList[personaId] || [];
}
function saveBabyList(personaId, list) {
  var data = getBabyData();
  if (!data.babyList) data.babyList = {};
  data.babyList[personaId] = list;
  // Keep legacy pointer to first baby for backward compat
  if (!data.babies) data.babies = {};
  data.babies[personaId] = list[0] || null;
  saveBabyData(data);
}
// Get sibling label: always returns complete word (哥哥/姐姐/弟弟/妹妹)
// selfBirthYear < targetBirthYear → self is OLDER → target is 弟弟/妹妹
// selfBirthYear > targetBirthYear → self is YOUNGER → target is 哥哥/姐姐
// Same year: use array order as tiebreak (lower idx = older)
function getSiblingLabel(selfBirthYear, targetBirthYear, targetGender, selfArrayIdx, targetArrayIdx) {
  var sy = parseInt(selfBirthYear) || 0;
  var ty = parseInt(targetBirthYear) || 0;
  var isOlder = (sy < ty) || (sy === ty && (selfArrayIdx||0) < (targetArrayIdx||0));
  if (isOlder) {
    return targetGender === 'female' ? '妹妹' : '弟弟';
  } else {
    return targetGender === 'female' ? '姐姐' : '哥哥';
  }
}
// Get all sibling context string for a baby (used in AI profile strings)
function getSiblingContext(babies, selfIdx) {
  if (!babies || babies.length <= 1) return '';
  var self = babies[selfIdx];
  // Sort by birthYear to determine definitive birth order
  var sorted = babies.slice().sort(function(a,b){ return (parseInt(a.birthYear)||0)-(parseInt(b.birthYear)||0); });
  var selfRank = sorted.indexOf(self);
  if (selfRank < 0) selfRank = sorted.findIndex(function(b){ return b.name===self.name && b.birthYear===self.birthYear; });
  var selfOrderLabel = getBirthOrderLabel(selfRank, babies.length);
  var lines = [];
  babies.forEach(function(b, i) {
    if (i === selfIdx) return;
    var tgtRank = sorted.indexOf(b);
    if (tgtRank < 0) tgtRank = sorted.findIndex(function(sb){ return sb.name===b.name && sb.birthYear===b.birthYear; });
    var tgtOrderLabel = getBirthOrderLabel(tgtRank, babies.length);
    var label = getSiblingLabel(self.birthYear, b.birthYear, b.gender, selfIdx, i);
    var bYears = getAgeInYears(b.birthYear);
    var bAge = getAgeDisplayYears(b.birthYear);
    var bPersonalitySummary = b.personality ? b.personality.substring(0, 60) + (b.personality.length > 60 ? '…' : '') : '';
    var bStage = getBabyStageFromYears(bYears).label;
    lines.push((b.name||'宝宝') + '（' + tgtOrderLabel + '，' + self.name + '应叫TA「' + label + '」，' + bAge + '/' + bStage
      + (bPersonalitySummary ? '，性格：' + bPersonalitySummary : '') + '）');
  });
  var orderNote = selfOrderLabel ? '【本角色排行：' + selfOrderLabel + '】 ' : '';
  return lines.length
    ? orderNote + '兄弟姐妹（按出生年份排序）：' + lines.join('；')
      + '\n【称呼铁律】以上称呼（哥哥/姐姐/弟弟/妹妹）由出生年份顺序严格决定，成年后不变，必须写完整词，不得写「哥/弟」「姐/妹」。\n'
    : '';
}
// Compute age in years from birthYear (no months)
function getAgeInYears(birthYear) {
  var now = new Date().getFullYear();
  var age = now - parseInt(birthYear||now);
  return Math.max(0, age);
}
function getAgeDisplayYears(birthYear) {
  var age = getAgeInYears(birthYear);
  return age + '岁';
}
// Get stage from age in years
function getBabyStageFromYears(years) {
  years = parseInt(years) || 0;
  if (years < 1)  return { label: '新生儿', key: 'newborn' };
  if (years < 3)  return { label: '幼童期', key: 'infant' };
  if (years < 6)  return { label: '小童期', key: 'toddler' };
  if (years < 11) return { label: '儿童期', key: 'child' };
  if (years < 18) return { label: '青少年期', key: 'older' };
  if (years < 26) return { label: '青年', key: 'adult' };
  if (years < 40) return { label: '成年', key: 'adult' };
  return { label: '中年', key: 'adult' };
}
// Stage speaking style
function getStageDesc(stageKey, ageYears) {
  if (stageKey === 'newborn') return '只能发出咿呀声、哭声、笑声，无法说话';
  if (stageKey === 'infant') return '牙牙学语，叠词，简单情绪，偶尔说"妈妈""爸爸"';
  if (stageKey === 'toddler') return '简短奶声奶气的句子，好奇心强，喜欢撒娇';
  if (stageKey === 'child') return '完整短句，天真，会提问，会表达喜好，偶尔撒娇';
  if (stageKey === 'older') {
    var y = parseInt(ageYears) || 11;
    if (y <= 12) return '进入青春期前期，说话已经很流畅，开始有自己的小主意，偶尔顶嘴，但有时还会有孩子气的一面';
    if (y <= 14) return '青少年，说话直接有个性，有自己明确的喜好，会反驳父母，有时沉默不语，有时又突然活跃，偶尔露出幼稚一面；绝对不会说那种小孩子的奶声奶气话，不会撒娇要玩具，不会对玩具感兴趣';
    if (y <= 16) return '青少年中期，独立意识强，语气可以冷静甚至略显疏离，有自己的想法和观点，和家人之间有时有代沟，但内心依然在乎家人；说话方式接近成年人，有自己的语气习惯；不会有幼稚行为，除非其核心性格本就有幼稚的一面';
    return '青少年后期/接近成年，思维成熟，有独到见解，说话简洁有力，会关心家人但不轻易表达，有自己的生活圈和秘密；有时会像成年人一样开玩笑；完全不会有幼稚行为';
  }
  return '说话自然成熟，有真实的情感和生活，关心家人，聊天时不像汇报，会分享生活感受、情感状态和日常小事，有温度有烟火气';
}
// Ordinal label for birth order (中文)
function getBirthOrderLabel(idx, total) {
  if (total === 1) return '';
  var labels = ['老大','老二','老三','老四','老五'];
  return labels[idx] || ('第'+(idx+1)+'胎');
}
// Full baby profile string for API
function buildBabyProfileStr(baby, babies, selfIdx) {
  var years = getAgeInYears(baby.birthYear);
  var stage = getBabyStageFromYears(years);
  var ageDisp = getAgeDisplayYears(baby.birthYear);
  var sibCtx = getSiblingContext(babies, selfIdx);
  var genderLabel = baby.gender === 'female' ? '女孩' : baby.gender === 'male' ? '男孩' : '';
  var isTeenager = (stage.key === 'older');
  var teenNote = isTeenager ? '【重要：青少年行为准则】此角色已是青少年（' + years + '岁），绝对不会玩婴幼儿玩具、不会奶声奶气撒娇、不会有幼童行为。说话方式接近成年人，有自己独立的思想和判断。兴趣围绕青少年生活（学校/朋友/音乐/游戏/追剧/手机等）。偶尔幼稚的一面取决于其核心性格，且仅限于轻微的行为（如赌气、翻白眼、突然孩子气地笑等）。\n' : '';
  return '【' + (baby.name||'宝宝') + '的完整资料】\n'
    + '姓名：' + (baby.name||'宝宝') + '\n'
    + '年龄：' + ageDisp + '（' + stage.label + '）\n'
    + (genderLabel ? '性别：' + genderLabel + '\n' : '')
    + (baby.birthday ? '生日：' + baby.birthday + '\n' : '')
    + (sibCtx || '')
    + teenNote
    + (baby.appearance ? '外貌：' + baby.appearance + '\n' : '')
    + (baby.personality ? '性格：' + baby.personality + '\n' : '')
    + (baby.voiceStyle ? '说话风格：' + baby.voiceStyle + '\n' : '')
    + (baby.traits && baby.traits.length ? '特质：' + baby.traits.join('、') + '\n' : '')
    + (baby.habits && baby.habits.length ? '习惯：' + baby.habits.join('、') + '\n' : '')
    + (baby.interests && baby.interests.length ? '兴趣：' + baby.interests.join('、') + '\n' : '')
    + (baby.growthTendency ? '成长倾向：' + baby.growthTendency + '\n' : '')
    + (baby.inheritedFeatures ? '遗传特征：' + baby.inheritedFeatures + '\n' : '')
    + '说话方式：' + getStageDesc(stage.key, years);
}
