      + '<div style="font-size:9px;font-weight:800;color:rgba(255,255,255,0.28);letter-spacing:1.5px;text-transform:uppercase;">' + (emoji ? emoji + ' ' : '') + labelTxt + '</div>'
      + items.map(function(h){ return '<div style="font-size:11.5px;color:rgba(255,255,255,0.55);padding-left:6px;line-height:1.5;">· ' + h + '</div>'; }).join('')
      + '</div>';
