    html += '<div style="background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.08);border-radius:20px;padding:20px 18px;display:flex;flex-direction:column;gap:14px;margin-bottom:14px;">';
    // Header row: avatar + name + age
