  var speakerName = msg.role === 'user' ? (up.name||'我') : msg.role === 'persona' ? (persona ? persona.name : '角色') : (babies.find(function(b){ return b.name === msg.babyName; }) || babies[0] || {name:'宝宝'}).name;
  _babyChatQuoteMsg = { idx: idx, speaker: speakerName, content: msg.content };
