// Ultra-robust JSON parser for Gemini and other non-standard API models
function safeParseJSON(text, fallback) {
  if (!text) return fallback || {};
  text = String(text).trim();
  
  // Step 1: Try direct parse first
  try {
    return JSON.parse(text);
  } catch(e) {}
  
  // Step 2: Remove markdown code blocks
  try {
    var cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
    return JSON.parse(cleaned);
  } catch(e) {}
  
  // Step 3: Remove common markdown formatting
  try {
    var cleaned = text
      .replace(/^\*\*.*?\*\*\s*/g, '')  // **bold**
      .replace(/^###\s*/gm, '')  // ### headers
      .replace(/^-\s*/gm, '')    // - bullets
      .trim();
    return JSON.parse(cleaned);
  } catch(e) {}
  
  // Step 4: Try extracting the first JSON object or array
  try {
    // Find the first { or [
    var startIdx = -1;
    var startChar = '';
    for (var i = 0; i < text.length; i++) {
      if (text[i] === '{' || text[i] === '[') {
        startIdx = i;
        startChar = text[i];
        break;
      }
    }
    
    if (startIdx >= 0) {
      var endChar = startChar === '{' ? '}' : ']';
      var depth = 0;
      var inString = false;
      var escaped = false;
      var endIdx = -1;
      
      for (var i = startIdx; i < text.length; i++) {
        var ch = text[i];
        
        if (escaped) {
          escaped = false;
          continue;
        }
        
        if (ch === '\\') {
          escaped = true;
          continue;
        }
        
        if (ch === '"' && !escaped) {
          inString = !inString;
          continue;
        }
        
        if (!inString) {
          if (ch === startChar) depth++;
          else if (ch === endChar) {
            depth--;
            if (depth === 0) {
              endIdx = i + 1;
              break;
            }
          }
        }
      }
      
      if (endIdx > startIdx) {
        var extracted = text.substring(startIdx, endIdx);
        try {
          return JSON.parse(extracted);
        } catch(e) {}
      }
    }
  } catch(e) {}
  
  // Step 5: Try line-by-line parsing (for multiple JSON objects)
  try {
    var lines = text.split('\n');
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if ((line.startsWith('{') || line.startsWith('[')) && (line.endsWith('}') || line.endsWith(']'))) {
        return JSON.parse(line);
      }
    }
  } catch(e) {}
  
  // Step 6: Try to extract JSON from between specific markers
  try {
    // For Gemini: sometimes returns {"text": "...json..."}
    var jsonMatch = text.match(/"(?:text|content|reply|message|result)"\s*:\s*"([^"]*(?:\\.[^"]*)*)"/) ||
                    text.match(/"(?:text|content|reply|message|result)"\s*:\s*([\{\[].*)/);
    if (jsonMatch && jsonMatch[1]) {
      var extracted = jsonMatch[1];
      // Unescape if needed
      extracted = extracted.replace(/\\"/g, '"').replace(/\\\\/g, '\\');
      return JSON.parse(extracted);
    }
  } catch(e) {}
  
  // Step 7: Try to find JSON-like patterns and validate
  try {
    var patterns = [
      /\[\s*\{[\s\S]*?\}\s*\]/,  // Array of objects
      /\{[\s\S]*?\}/,                 // Object
      /\[[\s\S]*?\]/                  // Array
    ];
    
    for (var p = 0; p < patterns.length; p++) {
      var match = text.match(patterns[p]);
      if (match) {
        try {
          return JSON.parse(match[0]);
        } catch(e) {}
      }
    }
  } catch(e) {}
  
  // Step 8: Last resort - try to construct a valid response from the text
  if (fallback && Array.isArray(fallback)) {
    // If expecting an array, try to extract speaker:text pairs
    try {
      var lines = text.split('\n').filter(function(l) { return l.trim().length > 0; });
      var result = [];
      for (var i = 0; i < lines.length; i++) {
        var line = lines[i].trim();
        if (line.includes('：') || line.includes(':')) {
          var parts = line.split(/[：:]/);
          if (parts.length >= 2) {
            result.push({
              speaker: parts[0].trim(),
              text: parts.slice(1).join(':').trim()
            });
          }
        }
      }
      if (result.length > 0) return result;
    } catch(e) {}
  }
  // Step 9: Truncated JSON repair — auto-close incomplete JSON
  // Handles cases where max_tokens cuts off the response mid-JSON
  try {
    var t9 = text.trim();
    // Remove markdown fences
    t9 = t9.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
    var isArr = t9.charAt(0) === '[';
    var isObj = t9.charAt(0) === '{';
    if (isArr || isObj) {
      // Close all open strings, then close all open brackets/braces
      var stack = [];
      var inStr = false;
      var esc = false;
      for (var ci = 0; ci < t9.length; ci++) {
        var cc = t9[ci];
        if (esc) { esc = false; continue; }
        if (cc === '\\') { esc = true; continue; }
        if (cc === '"') { inStr = !inStr; continue; }
        if (!inStr) {
          if (cc === '{' || cc === '[') stack.push(cc);
          else if (cc === '}' || cc === ']') stack.pop();
        }
      }
      var tail = '';
      // If we're mid-string, close it
      if (inStr) tail += '"';
      // Close any incomplete object values: if last real char before truncation
      // is a colon or comma, add a safe placeholder
      var trimmed9 = t9.replace(/[,\s]+$/, '');
      if (/[:,]$/.test(trimmed9)) tail += '""';
      // Close all open brackets in reverse
      for (var si = stack.length - 1; si >= 0; si--) {
        tail += stack[si] === '{' ? '}' : ']';
      }
      var repaired = t9 + tail;
      try {
        var parsed9 = JSON.parse(repaired);
        // For objects: must have at least one real key
        if (isObj && parsed9 && typeof parsed9 === 'object' && Object.keys(parsed9).length > 0) return parsed9;
        // For arrays: keep even if some items are partial
        if (isArr && Array.isArray(parsed9) && parsed9.length > 0) return parsed9;
      } catch(e9) {}
    }
  } catch(e) {}
  // Log the problematic response for debugging
  console.error('Failed to parse JSON. Raw response:', text.substring(0, 500));
  console.error('Fallback value:', fallback);
  
  return fallback || {};
}
// ---- Drama tab (multi-baby, baby selector) ----
var _dramaSelectedBabies = []; // array of indices
function renderDramaTab(body, persona) {
  if (!body || !persona) return;
  var pid = persona.id;
  var babies = getBabyList(pid);
  if (babies.length === 0) {
    body.innerHTML = '<div class="baby-generate-section"><div style="font-size:26px;">🎭</div><div class="baby-generate-title">先生成宝宝才能看小剧场</div></div>';
    return;
  }
  var data = getBabyData();
  var dramaHistory = (data.dramaHistory || {})[pid] || [];
  var up = getUserProfile();
  // Init selected babies (all by default)
  if (!_dramaSelectedBabies.length || _dramaSelectedBabies.some(function(i){ return i >= babies.length; })) {
    _dramaSelectedBabies = babies.map(function(_,i){ return i; });
  }
  var headerHtml = '<div class="baby-drama-title-row">'
    + '<div class="baby-drama-title">日常小剧场</div>'
    + '<button class="baby-drama-refresh" onclick="generateDrama()">＋ 新剧场</button>'
    + '</div>';
  // Baby multi-select chips (only shown if > 1 baby)
  if (babies.length > 1) {
    headerHtml += '<div style="padding:6px 0 8px;border-bottom:0.5px solid rgba(255,255,255,0.06);margin-bottom:8px;">'
      + '<div style="font-size:9px;color:rgba(255,255,255,0.25);letter-spacing:0.5px;margin-bottom:6px;">选择参与宝宝（角色和用户必在）</div>'
      + '<div style="display:flex;flex-wrap:wrap;gap:6px;">'
      + babies.map(function(b, i) {
          var sel = _dramaSelectedBabies.indexOf(i) >= 0;
          return '<div onclick="toggleDramaBaby(' + i + ')" style="padding:5px 12px;border-radius:20px;font-size:10px;font-weight:700;cursor:pointer;border:1px solid rgba(255,255,255,' + (sel?'0.35':'0.1') + ');background:rgba(255,255,255,' + (sel?'0.12':'0.04') + ');color:rgba(255,255,255,' + (sel?'0.85':'0.35') + ');-webkit-tap-highlight-color:transparent;">'
            + (b.avatar ? '<img src="' + b.avatar + '" style="width:14px;height:14px;border-radius:50%;object-fit:cover;vertical-align:middle;margin-right:4px;">' : (b.emoji||'🍼') + ' ')
            + (b.name||'宝宝') + '</div>';
        }).join('')
      + '</div></div>';
  }
  var memberNames = [persona.name||'角色', up.name||'我'].concat(
    _dramaSelectedBabies.map(function(i){ return babies[i] && (babies[i].name||'宝宝'); }).filter(Boolean)
  );
  headerHtml += '<div style="display:flex;align-items:center;gap:6px;padding:4px 0 10px;border-bottom:0.5px solid rgba(255,255,255,0.06);margin-bottom:10px;">'
    + '<div style="font-size:9px;color:rgba(255,255,255,0.25);letter-spacing:0.5px;">成员：' + memberNames.join(' · ') + '</div>'
    + '</div>';
  var innerHtml = headerHtml;
  if (dramaHistory.length === 0) {
    innerHtml += '<div style="text-align:center;padding:24px 0;"><div style="font-size:26px;margin-bottom:10px;">🎬</div>'
      + '<div style="font-size:11px;color:rgba(255,255,255,0.3);letter-spacing:0.5px;">点击「＋ 新剧场」生成家庭小剧场</div></div>';
    body.innerHTML = '<div class="baby-drama-card">' + innerHtml + '</div>';
    return;
  }
  // Show all dramas in reverse order (newest first)
  var allDramasHtml = '';
  for (var di = dramaHistory.length - 1; di >= 0; di--) {
    var d = dramaHistory[di];
    var idx = di;
    var linesHtml = '';
    (d.lines || []).forEach(function(line) {
      var actionHtml = line.action ? '<div style="font-size:9px;color:rgba(255,255,255,0.25);font-style:italic;margin-bottom:2px;">' + line.action + '</div>' : '';
      linesHtml += '<div class="baby-drama-line" style="flex-direction:column;gap:2px;">'
        + '<span class="baby-drama-speaker">' + line.speaker + '</span>'
        + actionHtml
        + '<span class="baby-drama-text">' + line.text + '</span>'
        + '</div>';
    });
    var isFirst = (di === dramaHistory.length - 1);
    allDramasHtml += '<div style="background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,' + (isFirst?'0.1':'0.05') + ');border-radius:14px;padding:14px;margin-bottom:10px;">'
      + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">'
      + '<div class="baby-drama-scene">' + (d.scene || '') + '</div>'
      + '<button onclick="deleteDrama(' + idx + ')" style="background:none;border:none;color:rgba(255,60,60,0.45);font-size:11px;cursor:pointer;padding:2px 6px;border-radius:8px;font-family:inherit;-webkit-tap-highlight-color:transparent;" title="删除">✕</button>'
      + '</div>'
      + '<div class="baby-drama-dialogue">' + linesHtml + '</div>'
      + '</div>';
  }
  innerHtml += allDramasHtml;
  body.innerHTML = '<div class="baby-drama-card">' + innerHtml + '</div>';
}
function toggleDramaBaby(idx) {
  var pos = _dramaSelectedBabies.indexOf(idx);
  if (pos >= 0) {
    if (_dramaSelectedBabies.length <= 1) return; // keep at least 1
    _dramaSelectedBabies.splice(pos, 1);
  } else {
    _dramaSelectedBabies.push(idx);
  }
  var data = getBabyData();
  var ps = getPersonas();
  var persona = ps.find(function(p){ return p.id == data.currentFamily; }) || ps[0];
  renderDramaTab(document.getElementById('babyAppBody'), persona);
}
function deleteDrama(idx) {
  var data = getBabyData();
  var ps = getPersonas();
  var persona = ps.find(function(p){ return p.id == data.currentFamily; }) || ps[0];
  if (!persona) return;
  if (!data.dramaHistory || !data.dramaHistory[persona.id]) return;
  data.dramaHistory[persona.id].splice(idx, 1);
  saveBabyData(data);
  renderDramaTab(document.getElementById('babyAppBody'), persona);
}
