  if (!baby) return;
  var ps = getPersonas();
  var persona = ps.find(function(p){ return p.id == pid; });
  if (!persona) return;
  var up = getUserProfile();
  var years = getAgeInYears(baby.birthYear);
  var stage = getBabyStageFromYears(years);
  var ageDisp = getAgeDisplayYears(baby.birthYear);
  var body = document.getElementById('babyAppBody');
  if (body) {
    var loading = document.createElement('div');
    loading.id = 'milestoneLoading';
    loading.style.cssText = 'position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:rgba(30,30,30,0.95);border:1px solid rgba(255,255,255,0.12);border-radius:12px;padding:12px 20px;font-size:11px;color:rgba(255,255,255,0.6);z-index:4000;';
    loading.textContent = '✦ 正在生成里程碑故事…';
    document.body.appendChild(loading);
  }
  var profile = buildBabyProfileStr(baby, babies, babyIdx);
  var milestoneIsTeenager = (stage.key === 'older');
