    + '<div style="font-size:10px;color:rgba(255,255,255,0.3);margin-top:1px;">' + (statusLabel ? statusLabel + '  ·  ' : '') + '感情值 ' + (state.loveProgress || 0) + ' / 100</div>'
    + '</div>'
    + '<div style="display:flex;gap:6px;">'
