      chatHtml += '<div style="text-align:center;padding:10px 0;"><span style="font-size:10px;color:rgba(255,255,255,0.28);font-style:italic;background:rgba(255,255,255,0.04);border-radius:10px;padding:4px 14px;">' + msg.content + '</span></div>';
      return;
