    var senderName = isMe ? (baby.name || '宝宝') : (partner.name || '对象');
    var avatarContent = isMe
      ? (baby.avatar ? '<img src="' + baby.avatar + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">' : '<span style="font-size:11px;font-weight:700;color:rgba(255,255,255,0.6);">' + (baby.name||'宝').charAt(0) + '</span>')
      : (partner.avatar ? '<img src="' + partner.avatar + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">' : '<span style="font-size:11px;font-weight:700;color:rgba(255,255,255,0.6);">' + partnerInitial + '</span>');
