// ---- Grandchild Generation ----
async function generateGrandchild(pid, babyIdx) {
  var state = getLoveState(pid, babyIdx);
  if (state.status !== 'married') return;
  var children = state.children || [];
  if (children.length >= 4) { alert('已经有四个孩子了，不能再生了。'); return; }
  var babies = getBabyList(pid);
  var baby = babies[babyIdx];
  var partner = state.matches[state.selectedMatchIdx] || {};
  var ps = getPersonas();
  var persona = ps.find(function(p) { return p.id == pid; });
  var pName = persona ? persona.name : '角色';
  // Pick gender
  var genders = ['male', 'female'];
  var chosenGender = genders[Math.floor(Math.random() * 2)];
  var genderLabel = chosenGender === 'female' ? '女' : '男';
  var loadEl = document.createElement('div');
  loadEl.id = '_grandchildLoad';
  loadEl.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:rgba(20,20,20,0.96);border:1px solid rgba(255,255,255,0.12);border-radius:14px;padding:12px 20px;font-size:11px;color:rgba(255,255,255,0.5);z-index:5000;';
  loadEl.textContent = '正在生成孙子/孙女信息...';
  document.body.appendChild(loadEl);
  // Build sibling context
  var siblingDesc = children.length > 0
    ? ('已有孩子：' + children.map(function(c, i) { return c.name + '（' + (c.gender==='female'?'女':'男') + '，' + getAgeInYears(c.birthYear) + '岁）'; }).join('、'))
    : '暂无兄弟姐妹';
  // Build all family members for family awareness
  var babyBirthYear = parseInt(baby.birthYear) || (new Date().getFullYear() - 28);
  var partnerBirthYear = babyBirthYear + (Math.random() > 0.5 ? -2 : 2);
  var childBirthYear = new Date().getFullYear() - (children.length === 0 ? 1 : Math.floor(Math.random() * 3) + 1);
  // All babies (宝宝's siblings) for aunt/uncle awareness
  var siblingsOfBaby = babies.filter(function(b, i) { return i !== babyIdx; });
  var prompt = '请为以下夫妻生成他们的第' + (children.length + 1) + '个孩子的完整人物信息（该孩子是用户和角色的孙子/孙女）。\n\n'
    + '【父亲/母亲 · ' + (baby.gender === 'female' ? '妈妈' : '爸爸') + '】\n'
    + '姓名：' + (baby.name||'宝宝') + '\n外貌：' + (baby.appearance||'') + '\n性格：' + (baby.personality||'') + '\n\n'
    + '【' + (baby.gender === 'female' ? '父亲' : '母亲') + ' · ' + (baby.gender === 'female' ? '爸爸' : '妈妈') + '】\n'
    + '姓名：' + (partner.name||'') + '\n外貌：' + (partner.appearance||'') + '\n性格：' + (partner.personality||partner.bio||'') + '\n\n'
    + '【爷爷/奶奶 或 外公/外婆】\n角色名：' + pName + '（和用户）\n\n'
    + '【已有兄弟姐妹】' + siblingDesc + '\n'
    + '【新生孩子性别】' + genderLabel + '\n\n'
    + '请生成该孩子的完整信息，格式为以下JSON对象（只输出JSON，不要任何其他文字）：\n'
    + '{"name":"姓名（随机取名，符合父母姓氏风格）","gender":"' + chosenGender + '","birthYear":' + childBirthYear + ',"appearance":"外貌特征（100字，结合父母遗传）","personality":"性格描述（80字）","traits":["特质1","特质2","特质3"],"habits":["小习惯1","小习惯2"],"interests":["兴趣1","兴趣2"],"inheritedFeatures":"遗传了父母哪些特征（60字）","growthTendency":"成长倾向（60字）","birthStory":"出生故事（80字，温馨自然）","emoji":"一个代表该孩子的emoji（婴儿/孩子相关）"}';
  try {
    if (!apiConfig || !apiConfig.url || !apiConfig.key || !apiConfig.model) throw new Error('请先配置API');
    var resp = await fetch(apiConfig.url.replace(/\/$/, '') + '/chat/completions', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + apiConfig.key, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: apiConfig.model,
        messages: [
          { role: 'system', content: '你是一个专业的人物生成器，专门生成有真实感、立体感的人物档案。只输出纯JSON对象，不含任何说明文字。' },
          { role: 'user', content: prompt }
        ],
        max_tokens: 800, temperature: 0.9
      })
    });
    if (!resp.ok) throw new Error('API错误 ' + resp.status);
    var result = await resp.json();
    var txt = result.choices[0].message.content;
    var childData = safeParseJSON(txt, null);
    if (!childData || !childData.name) throw new Error('生成失败，请重试');
    // Build child object with full family context
    childData.birthYear = childBirthYear;
    childData.gender = chosenGender;
    childData.parentBabyIdx = babyIdx;
    childData.parentBabyName = baby.name || '宝宝';
    childData.parentPartnerName = partner.name || '';
    childData.grandparentPersonaId = pid;
    // Store sibling-of-baby list for family tree
    childData.babyUnclesAunts = siblingsOfBaby.map(function(b) {
      return { name: b.name, gender: b.gender, birthYear: b.birthYear };
    });
    state.children = state.children || [];
    state.children.push(childData);
    state.chatHistory.push({ role: 'narrator', content: (baby.name||'宝宝') + ' 与 ' + (partner.name||'TA') + ' 迎来了他们的孩子 ' + childData.name + '（' + genderLabel + '宝宝）。' });
    saveLoveState(pid, babyIdx, state);
    // Also store grandchild in a global grandchildren registry for birth certificate access
    var gcData = JSON.parse(localStorage.getItem('mono_grandchildren') || '{}');
    var gcKey = pid + '_' + babyIdx;
    gcData[gcKey] = state.children;
    localStorage.setItem('mono_grandchildren', JSON.stringify(gcData));
    await syncLoveStateNow(pid, babyIdx);
    loadEl.remove();
    // Open grandchild birth certificate
    openGrandchildBirthPage(pid, babyIdx, state.children.length - 1);
  } catch(e) {
    state.chatHistory.push({ role: 'narrator', content: '（孩子生成失败：' + (e.message||'').substring(0,40) + '）' });
    saveLoveState(pid, babyIdx, state);
    loadEl.remove();
    var p2 = getPersonas().find(function(p) { return p.id == pid; });
    renderLoveTab(document.getElementById('babyAppBody'), p2);
  }
}
