  // ─── Page context reader ───
  function _lcwGetPageContext() {
    try {
      var parts = [];
      var title = document.title;
      // 过滤掉应用自身名称，避免角色感知到内部系统名称
      var filteredTitle = title ? title.replace(/mono\s*heart/gi, '').replace(/^[\s\-\u2013\u2014\xb7|]+|[\s\-\u2013\u2014\xb7|]+$/g, '').trim() : '';
      if (filteredTitle && filteredTitle.length > 0) parts.push('页面标题：' + filteredTitle);
      // Try to read meaningful text from common areas
      var selectors = [
        'h1', 'h2', 'h3',
        '[class*="message"]', '[class*="chat"]', '[class*="content"]',
        '[class*="帖子"]', '[class*="feed"]', 'article', 'main',
        '[class*="timeline"]', '[class*="friend"]', '[class*="forum"]',
        '[class*="shop"]', '[class*="store"]', '[class*="health"]',
        '[class*="location"]', '[class*="map"]', '[class*="pet"]',
        '[class*="date"]', '[class*="match"]'
      ];
      var collected = '';
      selectors.forEach(function(sel) {
        try {
          document.querySelectorAll(sel).forEach(function(el) {
            if (el.offsetParent === null) return; // skip hidden
            var t = (el.innerText || el.textContent || '').trim();
            if (t && t.length > 5 && collected.indexOf(t.substring(0,20)) < 0) {
              collected += t.substring(0, 150) + '\n';
              if (collected.length > 1200) return;
            }
          });
        } catch(e2){}
      });
      if (collected) parts.push('页面内容片段：\n' + collected.substring(0, 1200));
      return parts.join('\n').trim();
    } catch(e) { return ''; }
  }
