// Simulate character cursor movement
function rpcSimulateCharAction() {
  if (!rpcState.isActive) return;
  var phone = document.getElementById('rpcVirtualPhone');
  var cursor = document.getElementById('rpcCursor');
  if (!phone || !cursor) return;
  cursor.classList.add('visible');
  var rect = phone.getBoundingClientRect();
  var x = Math.random() * 200 + 25;
  var y = Math.random() * 300 + 60;
  cursor.style.left = x + 'px';
  cursor.style.top = y + 'px';
  setTimeout(function(){
    cursor.classList.add('tap');
    setTimeout(function(){ cursor.classList.remove('tap'); }, 300);
  }, 400);
  if (rpcState.cursorTimer) clearTimeout(rpcState.cursorTimer);
  rpcState.cursorTimer = setTimeout(rpcSimulateCharAction, 3000 + Math.random()*3000);
}
// Force stop
function rpcForceStop() {
  if (!confirm('强制停止查岗？角色可能会生气...')) return;
  rpcEndSession(true);
}
function rpcEndSession(forced) {
  rpcState.isActive = false;
  if (rpcState.thoughtTimer) clearTimeout(rpcState.thoughtTimer);
  if (rpcState.cursorTimer) clearTimeout(rpcState.cursorTimer);
  if (rpcState.clockTimer) clearInterval(rpcState.clockTimer);
  var cursor = document.getElementById('rpcCursor');
  if (cursor) cursor.classList.remove('visible');
  document.getElementById('rpcThoughtBubble').classList.remove('show');
  // Generate summary
  rpcGenerateSummary(forced);
}
function rpcGenerateSummary(forced) {
  var p = rpcState.currentPersona;
  var duration = rpcState.startTime ? Math.round((Date.now()-rpcState.startTime)/1000) : 0;
  var prompt = '你是'+((p&&p.name)||'角色')+'，人设：'+((p&&p.persona)||'')+'。刚刚查了用户的手机，查了'+rpcState.appsOpened+'个应用，历时'+duration+'秒。'+(forced?'用户中途强制终止了查岗。':'查岗已完成。')+'\n\n生成查岗总结，返回JSON：\n{"mood":"你当前的心情emoji+4字","verdict":"你查完后的结论和感受（30-50字，用第一人称）","finding":"发现了什么（20字内）"}\n只返回JSON。禁止Markdown，禁止解释，禁止在JSON前后添加任何文字。';
  callAIAPI(prompt, function(resp) {
    try {
      var obj = JSON.parse(resp.match(/\{[\s\S]*\}/)?.[0] || '{}');
      rpcDisplaySummary(duration, obj, forced);
    } catch(e) { rpcDisplaySummary(duration, {mood:'😐 无语', verdict:'查完了...', finding:'没有异常'}, forced); }
  }, function(){ rpcDisplaySummary(duration, {mood:'😐 无语', verdict:'查完了。', finding:'无异常'}, forced); });
}
function rpcDisplaySummary(duration, obj, forced) {
  var stats = document.getElementById('rpcSummaryStats');
  if (stats) {
    stats.innerHTML = `
      <div class="rpc-summary-stat"><div class="rpc-summary-stat-num">${rpcState.appsOpened}</div><div class="rpc-summary-stat-label">已查应用</div></div>
      <div class="rpc-summary-stat"><div class="rpc-summary-stat-num">${duration}s</div><div class="rpc-summary-stat-label">查岗时长</div></div>
    `;
  }
  var moodEl = document.getElementById('rpcSummaryMood');
  if (moodEl) moodEl.textContent = obj.mood || '😐 无语';
  var verdictEl = document.getElementById('rpcSummaryVerdict');
  if (verdictEl) verdictEl.textContent = obj.verdict || '';
  document.getElementById('rpcSummaryOverlay').classList.add('open');
}
function rpcCloseSummary() {
  document.getElementById('rpcSummaryOverlay').classList.remove('open');
  document.getElementById('rpcMainOverlay').classList.remove('open');
  document.querySelectorAll('.rpc-app-page').forEach(p=>p.classList.remove('open'));
  // Send summary message to chat
  var p = rpcState.currentPersona;
  if (p) {
    var moodEl = document.getElementById('rpcSummaryMood');
    var verdictEl = document.getElementById('rpcSummaryVerdict');
    var mood = moodEl ? moodEl.textContent : '';
    var verdict = verdictEl ? verdictEl.textContent : '';
    rpcSendSystemMessage('[查岗结束 '+mood+'] ' + p.name + '：' + verdict);
  }
}
