function rpc2RememberOriginPersona() {
  try {
    if (typeof currentId !== 'undefined' && currentId != null) {
      rpc2State.originPersonaId = currentId;
    }
  } catch(e) {}
}
function rpc2RestoreOriginPersona() {
  try {
    var originId = rpc2State.originPersonaId;
    if (!originId || typeof selectPersona !== 'function' || typeof currentId === 'undefined') return;
    if (String(currentId) === String(originId)) return;
    if (!Array.isArray(personas) || !personas.some(function(item) { return String(item.id) === String(originId); })) return;
    selectPersona(originId);
  } catch(e) {}
}
// 加载设置
function rpc2LoadSettings() {
  try {
    var s = JSON.parse(localStorage.getItem('rpc2_settings') || '{}');
    rpc2State.settings = Object.assign({
      pin: '',
      showThought: true,
      allowOp: true,
      allowedApps: ['chat', 'moments', 'forum', 'novel', 'diary', 'shop', 'profile']
    }, s);
  } catch(e) { rpc2State.settings = {}; }
}
// 保存设置
function rpc2SaveSettings() {
  localStorage.setItem('rpc2_settings', JSON.stringify(rpc2State.settings));
}
// 更新锁屏时间
function rpc2UpdateLockTime() {
  var now = new Date();
  var h = now.getHours(), m = now.getMinutes();
  var timeStr = h + ':' + (m < 10 ? '0' : '') + m;
  var el = document.getElementById('rpc2LockTime');
  if (el) el.textContent = timeStr;
  
  var days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  var months = ['January', 'February', 'March', 'April', 'May', 'June', 
                'July', 'August', 'September', 'October', 'November', 'December'];
  var dateEl = document.getElementById('rpc2LockDate');
  if (dateEl) {
    dateEl.textContent = days[now.getDay()] + ', ' + months[now.getMonth()] + ' ' + now.getDate();
  }
}
