// PIN 输入
function rpc2PinKey(k) {
  if (rpc2State.pinEntry.length >= 6) return;
  rpc2State.pinEntry += k;
  rpc2UpdatePinDisplay();
  if (rpc2State.pinEntry.length >= 4) {
    setTimeout(rpc2CheckPin, 200);
  }
}
function rpc2PinDel() {
  rpc2State.pinEntry = rpc2State.pinEntry.slice(0, -1);
  rpc2UpdatePinDisplay();
}
function rpc2UpdatePinDisplay() {
  for (var i = 0; i < 6; i++) {
    var dot = document.getElementById('rpc2pd' + i);
    if (dot) {
      dot.classList.toggle('filled', i < rpc2State.pinEntry.length);
      dot.classList.remove('error');
    }
  }
}
function rpc2CheckPin() {
  var correct = rpc2State.settings.pin || '0000';
  if (rpc2State.pinEntry === correct || rpc2State.pinEntry.length >= 4) {
    rpc2UnlockSuccess();
  } else {
    var pd = document.getElementById('rpc2PinDisplay');
    for (var i = 0; i < 6; i++) {
      var d = document.getElementById('rpc2pd' + i);
      if (d) d.classList.add('error');
    }
    pd.classList.add('shake');
    setTimeout(function() {
      pd.classList.remove('shake');
      rpc2State.pinEntry = '';
      rpc2UpdatePinDisplay();
    }, 500);
  }
}
// 自动猜测密码
var rpc2AutoTryAttempts = 0;
var rpc2Guesses = ['0520', '1314', '1024', '0214', '1234', '0000'];
function rpc2AutoTryUnlock() {
  if (!document.getElementById('rpc2LockscreenOverlay').classList.contains('open')) return;
  
  var p = rpc2State.currentPersona;
  
  if (rpc2AutoTryAttempts < rpc2Guesses.length) {
    var guess = rpc2Guesses[rpc2AutoTryAttempts];
    document.getElementById('rpc2LockSubtitle').textContent = p?.name + ' 正在尝试：' + guess + '...';
    rpc2AutoTryAttempts++;
    
    rpc2State.pinEntry = guess;
    rpc2UpdatePinDisplay();
    
    var correct = rpc2State.settings.pin || '';
    if (guess === correct || rpc2AutoTryAttempts >= rpc2Guesses.length) {
      setTimeout(function() {
        if (rpc2AutoTryAttempts >= rpc2Guesses.length && guess !== correct) {
          document.getElementById('rpc2LockSubtitle').textContent = '密码错误... 换个方式试试！';
          setTimeout(rpc2UnlockSuccess, 1500);
        } else {
          rpc2UnlockSuccess();
        }
      }, 800);
    } else {
      var pd = document.getElementById('rpc2PinDisplay');
      pd.classList.add('shake');
      setTimeout(function() {
        pd.classList.remove('shake');
        rpc2AutoTryUnlock();
      }, 700);
    }
  }
}
// 解锁成功
function rpc2UnlockSuccess() {
  rpc2AutoTryAttempts = 0;
  document.getElementById('rpc2LockscreenOverlay').classList.remove('open');
  rpc2StartMainCheck();
}
// 开始主屏幕查岗
function rpc2StartMainCheck() {
  rpc2LoadSettings();
  var p = rpc2State.currentPersona;
  if (!p) return;
  
  rpc2State.isActive = true;
  rpc2State.startTime = Date.now();
  rpc2State.appsOpened = 0;
  
  // 设置控制栏
  document.getElementById('rpc2ControlAvatar').src = p.avatar || '';
  document.getElementById('rpc2ControlName').textContent = p.name || 'Character';
  document.getElementById('rpc2ControlAction').textContent = '正在浏览你的主屏幕...';
  document.getElementById('rpc2ControlBar').classList.add('active');
  
  // 设置心声弹窗
  document.getElementById('rpc2ThoughtAvatar').src = p.avatar || '';
  document.getElementById('rpc2ThoughtName').textContent = p.name || 'Character';
  document.getElementById('rpc2ThoughtText').innerHTML = '<div class="rpc2-thought-loading"><div class="rpc2-thought-loading-dots"><span></span><span></span><span></span></div>思考中...</div>';
  document.getElementById('rpc2ThoughtPopup').classList.add('active');
  
  // 显示光标
  var cursor = document.getElementById('rpc2Cursor');
  cursor.classList.add('visible');
  
  // 发送消息
  /* 查岗开始 — 不发系统消息 */
  
  // 开始模拟角色操作
  setTimeout(rpc2SimulateAction, 1500);
  
  // 生成第一个心声
  setTimeout(function() { rpc2GenerateThought('home'); }, 2000);
}
// 模拟角色操作（移动光标、点击应用）
function rpc2SimulateAction() {
  if (!rpc2State.isActive) return;
  
  var cursor = document.getElementById('rpc2Cursor');
  var phoneContainer = document.querySelector('.phone-container');
  if (!phoneContainer) {
    phoneContainer = document.body;
  }
  
  var rect = phoneContainer.getBoundingClientRect();
  
  // 随机移动光标到某个位置
  var targetX = rect.left + 50 + Math.random() * (rect.width - 100);
  var targetY = rect.top + 100 + Math.random() * (rect.height - 200);
  
  // 平滑移动光标
  rpc2MoveCursor(targetX, targetY, function() {
    // 模拟点击
    cursor.classList.add('tap');
    setTimeout(function() { cursor.classList.remove('tap'); }, 300);
    
    // 随机决定是否打开应用
    if (Math.random() < 0.4) {
      rpc2SimulateOpenApp();
    }
  });
  
  // 下一次操作
  if (rpc2State.cursorTimer) clearTimeout(rpc2State.cursorTimer);
  rpc2State.cursorTimer = setTimeout(rpc2SimulateAction, 2500 + Math.random() * 3000);
}
// 平滑移动光标
function rpc2MoveCursor(targetX, targetY, callback) {
  var cursor = document.getElementById('rpc2Cursor');
  var startX = rpc2State.cursorX;
  var startY = rpc2State.cursorY;
  var duration = 400 + Math.random() * 300;
  var startTime = Date.now();
  
  function animate() {
    var elapsed = Date.now() - startTime;
    var progress = Math.min(elapsed / duration, 1);
    // 缓动函数
    var eased = 1 - Math.pow(1 - progress, 3);
    
    var x = startX + (targetX - startX) * eased;
    var y = startY + (targetY - startY) * eased;
    
    cursor.style.left = x + 'px';
    cursor.style.top = y + 'px';
    rpc2State.cursorX = x;
    rpc2State.cursorY = y;
    
    if (progress < 1) {
      requestAnimationFrame(animate);
    } else {
      if (callback) callback();
    }
  }
  
  requestAnimationFrame(animate);
}
// ===== 聊天室内滑动手势动画 =====
// 在指定元素内循环模拟「上划」手势（像真人用拇指翻聊天记录）
function rpc2StartSwipeInEl(el) {
  rpc2StopSwipeAnim(); // 先停掉上一次
  if (!el) return;
  rpc2State.swipeAnimRunning = true;
  var cursor = document.getElementById('rpc2Cursor');
  if (cursor) cursor.classList.add('swipe');
  var SWIPE_UP_MS   = 900;  // 单次上划耗时（ms）
  var PAUSE_LIFT_MS = 280;  // 手指抬起停顿
  var PAUSE_DOWN_MS = 180;  // 手指放到底部停顿
  var cycleMs = SWIPE_UP_MS + PAUSE_LIFT_MS + PAUSE_DOWN_MS;
  var loopStart = null;
  function loop(ts) {
    if (!rpc2State.swipeAnimRunning) return;
    if (!loopStart) loopStart = ts;
    var elapsed = (ts - loopStart) % cycleMs;
    var rect = el.getBoundingClientRect();
    // 手指在聊天框右侧约 60% 处水平位置
    var cx = rect.left + rect.width * 0.6;
    // 上划范围：从可视区底部 80% 到顶部 20%
    var startY = rect.top + rect.height * 0.78;
    var endY   = rect.top + rect.height * 0.20;
    var cy;
    if (elapsed < SWIPE_UP_MS) {
      // 上划阶段 — ease-in-out cubic
      var t = elapsed / SWIPE_UP_MS;
      var ease = t < 0.5 ? 4*t*t*t : 1 - Math.pow(-2*t+2,3)/2;
      cy = startY + (endY - startY) * ease;
    } else {
      // 抬起 + 复位阶段，手指停在顶部
      cy = endY;
    }
    if (cursor && rect.width > 0) {
      cursor.style.left = cx + 'px';
      cursor.style.top  = cy + 'px';
      rpc2State.cursorX = cx;
      rpc2State.cursorY = cy;
    }
    rpc2State.swipeAnimFrame = requestAnimationFrame(loop);
  }
  rpc2State.swipeAnimFrame = requestAnimationFrame(loop);
}
// 停止滑动手势，光标恢复圆形
function rpc2StopSwipeAnim() {
  rpc2State.swipeAnimRunning = false;
  if (rpc2State.swipeAnimFrame) {
    cancelAnimationFrame(rpc2State.swipeAnimFrame);
    rpc2State.swipeAnimFrame = null;
  }
  var cursor = document.getElementById('rpc2Cursor');
  if (cursor) cursor.classList.remove('swipe');
}
// ===== 跳过当前聊天室 =====
function rpc2ShowSkipBtn() {
  var btn = document.getElementById('rpc2SkipBtn');
  if (btn) btn.classList.add('show');
}
function rpc2HideSkipBtn() {
  var btn = document.getElementById('rpc2SkipBtn');
  if (btn) btn.classList.remove('show');
}
function rpc2SkipCurrentChat() {
  if (typeof rpc2State.currentChatSkipFn === 'function') {
    rpc2State.currentChatSkipFn();
  }
}
// 模拟打开应用
function rpc2SimulateOpenApp() {
  var p = rpc2State.currentPersona;
  if (!p) return;
  
  var apps = rpc2State.settings.allowedApps || ['chat', 'moments', 'forum'];
  var appId = apps[Math.floor(Math.random() * apps.length)];
  
  rpc2State.appsOpened++;
  
  var appNames = {
    chat: '聊天',
    moments: '朋友圈',
    forum: '论坛',
    novel: '小说',
    diary: '日记',
    shop: '购物',
    profile: '个人主页',
    music: '音乐',
    location: '位置'
  };
  
  var appName = appNames[appId] || appId;
  document.getElementById('rpc2ControlAction').textContent = '正在查看 ' + appName + '...';
  
  // 模拟点击对应的应用图标
  var appEl = document.getElementById('app-' + appId);
  if (appEl) {
    appEl.click();
  }
  
  // 生成心声
  setTimeout(function() { rpc2GenerateThought(appId); }, 1000);
  
  // 一段时间后返回主屏幕
  setTimeout(function() {
    if (rpc2State.isActive) {
      var backBtn = document.querySelector('.app-back-btn');
      if (backBtn) backBtn.click();
      document.getElementById('rpc2ControlAction').textContent = '返回主屏幕...';
    }
  }, 4000 + Math.random() * 3000);
}
// 生成心声
function rpc2GenerateThought(context) {
  if (!rpc2State.settings.showThought) return;
  
  var p = rpc2State.currentPersona;
  if (!p) return;
  
  var contextNames = {
    home: '主屏幕',
    chat: '聊天记录',
    moments: '朋友圈',
    forum: '论坛帖子',
    novel: '阅读历史',
    diary: '日记',
    shop: '购物记录',
    profile: '个人主页'
  };
  
  var contextName = contextNames[context] || context;
  
  // 读取角色的聊天语言设置，默认简体中文
  var chatLang = (p.chatLanguage || p.language || p.lang || '简体中文');
  var langInstruction = '请用【' + chatLang + '】输出心声内容。';
  
  var prompt = '你是' + p.name + '，人设：' + (p.persona || '') + '。你正在查看对方手机的' + contextName + '。用第一人称写出你此刻的内心独白（1-2句，不超过50字），要符合你的性格和说话风格。直接写心声内容，不加引号。' + langInstruction;
  
  // 调用聊天软件已连接的 AI API
  rpc2CallAI(prompt, function(resp) {
    document.getElementById('rpc2ThoughtText').textContent = resp.trim();
  }, function() {
    // 失败时用预设（根据语言环境）
    var fallbackThoughts = [
      '哼，这是什么...',
      '让我看看...',
      '有意思...',
      '暂时没有异常，先继续看...'
    ];
    document.getElementById('rpc2ThoughtText').textContent = fallbackThoughts[Math.floor(Math.random() * fallbackThoughts.length)];
  });
}
// 强制停止查岗
function rpc2ForceStop() {
  if (!confirm('强制停止查岗？角色可能会生气...')) return;
  rpc2EndSession(true);
}
// 结束查岗
function rpc2EndSession(forced) {
  rpc2State.isActive = false;
  rpc2State.currentChatSkipFn = null;
  rpc2StopSwipeAnim();
  rpc2HideSkipBtn();
  // 清除定时器
  if (rpc2State.thoughtTimer) clearTimeout(rpc2State.thoughtTimer);
  if (rpc2State.cursorTimer) clearTimeout(rpc2State.cursorTimer);
  // 隐藏光标和控制栏
  document.getElementById('rpc2Cursor').classList.remove('visible');
  document.getElementById('rpc2ControlBar').classList.remove('active');
  document.getElementById('rpc2ThoughtPopup').classList.remove('active');
  // ── 将查岗内容与心声存入角色记忆 ──
  rpc2SaveInspectionMemory(forced);
  // 生成总结
  rpc2GenerateSummary(forced);
}
// 将本次查岗的浏览内容 + 心声写入角色 memoryCore
function rpc2SaveInspectionMemory(forced) {
  try {
    var p = rpc2State.currentPersona;
    if (!p) return;
    if (!p.memoryCore) p.memoryCore = [];
    var now = new Date();
    var dateStr = now.getFullYear() + '-' +
      String(now.getMonth() + 1).padStart(2, '0') + '-' +
      String(now.getDate()).padStart(2, '0');
    // 浏览内容摘要
    var inspected = rpc2State.inspectionLog.map(function(item) {
      return '【' + item.page + '】' + item.summary.slice(0, 120);
    }).join('\n');
    // 累积心声
    var thoughts = rpc2State.thoughtLog.map(function(t) {
      return '【' + t.page + '】' + t.thought;
    }).join('\n');
    if (!inspected && !thoughts) return;
    var memContent = '[反向查岗记录 ' + dateStr + (forced ? '（被中断）' : '') + ']\n' +
      (inspected ? '浏览内容：\n' + inspected + '\n' : '') +
      (thoughts  ? '查岗心声：\n' + thoughts : '');
    p.memoryCore.push({
      content: memContent,
      date: dateStr,
      auto: true,
      source: '反向查岗'
    });
    // 保存（直接持久化 personas 数组，避免触发 UI 表单覆盖其他角色数据）
    if (typeof saveData === 'function') saveData();
  } catch(e) { console.error('[RPC2] saveInspectionMemory error:', e); }
}
// 生成查岗总结
function rpc2GenerateSummary(forced) {
  var p = rpc2State.currentPersona;
  var duration = rpc2State.startTime ? Math.round((Date.now() - rpc2State.startTime) / 1000) : 0;
  document.getElementById('rpc2SummaryApps').textContent = rpc2State.appsOpened;
  document.getElementById('rpc2SummaryTime').textContent = duration + 's';
  var chatLangS = (p && (p.chatLanguage || p.language || p.lang)) || '简体中文';
  // 构建心声摘要供总结使用
  var thoughtsSummary = rpc2State.thoughtLog.length > 0
    ? '\n\n查岗中产生的心声（按顺序）：\n' +
      rpc2State.thoughtLog.map(function(t) { return '• [' + t.page + '] ' + t.thought; }).join('\n')
    : '';
  var prompt = '你是' + ((p && p.name) || '角色') + '，人设：' + ((p && p.persona) || '') +
    '。你刚刚查了对方的手机，查了' + rpc2State.appsOpened + '个内容区，历时' + duration + '秒。' +
    (forced ? '对方中途强制终止了查岗。' : '查岗已完成。') +
    thoughtsSummary +
    '\n\n请用【' + chatLangS + '】输出。生成查岗总结，返回JSON：\n' +
    '{"mood":"你当前的心情（emoji+4字以内）","verdict":"你查完后的结论和感受（30-50字，用第一人称，结合具体发现）"}\n只返回JSON。禁止Markdown，禁止解释，禁止在JSON前后添加任何文字。';
  rpc2CallAI(prompt, function(resp) {
    try {
      var obj = JSON.parse(resp.match(/\{[\s\S]*\}/)?.[0] || '{}');
      rpc2DisplaySummary(duration, obj, forced);
    } catch(e) {
      rpc2DisplaySummary(duration, { mood: '😐 平静', verdict: '查岗已完成。' }, forced);
    }
  }, function() {
    rpc2DisplaySummary(duration, { mood: '😐 平静', verdict: '查岗已完成。' }, forced);
  });
}
// 显示总结
function rpc2DisplaySummary(duration, obj, forced) {
  /* 存入 state 供查岗后发消息使用 */
  rpc2State.summaryResult = { mood: obj.mood || '', verdict: obj.verdict || '', forced: !!forced };
  document.getElementById('rpc2SummaryMood').textContent = obj.mood || '😐 平静';
  document.getElementById('rpc2SummaryVerdict').textContent = obj.verdict || '';
  document.getElementById('rpc2SummaryModal').classList.add('open');
  document.getElementById('rpc2RequestBackdrop').classList.add('open');
}
// 关闭总结 → 存入聊天记录 + 触发角色自动发消息
function rpc2CloseSummary() {
  document.getElementById('rpc2SummaryModal').classList.remove('open');
  document.getElementById('rpc2RequestBackdrop').classList.remove('open');
  var p = rpc2State.currentPersona;
  if (!p) return;
  /* 查岗结束总结 — 不发系统消息，改由自动发消息承接 */
  rpc2RestoreOriginPersona();
  // 延迟一秒后生成角色主动发送的消息（传入总结情绪保持连贯）
  setTimeout(function() { rpc2TriggerPostInspectionMessages(p, rpc2State.summaryResult); }, 1200);
}
// 查岗结束后角色主动发消息（情绪与总结连贯，记忆与查岗内容连贯）
function rpc2TriggerPostInspectionMessages(p, summaryResult) {
  try {
    var lang = p.chatLanguage || p.language || p.lang || '简体中文';
    var minC = p.min回复Count || 1;
    var maxC = p.max回复Count || 3;
    var count = Math.floor(Math.random() * (maxC - minC + 1)) + minC;
    count = Math.min(count, 5);
    /* 总结情绪上下文 */
    var summaryCtx = '';
    if (summaryResult && (summaryResult.mood || summaryResult.verdict)) {
      summaryCtx =
        '\n\n【你查岗结束后的综合心情与结论】\n' +
        '当前情绪：' + (summaryResult.mood || '平静') + '\n' +
        '你的判断：' + (summaryResult.verdict || '') +
        (summaryResult.forced ? '\n（注意：对方中途强制终止了查岗，你可能对此有反应）' : '');
    }
    /* 查岗内容上下文 */
    var inspCtx = '';
    if (rpc2State.inspectionLog.length > 0) {
      inspCtx = '\n\n【你在查岗中看到的内容摘要（请结合这些发现说话）】\n' +
        rpc2State.inspectionLog.slice(-10).map(function(item) {
          return '• [' + item.page + '] ' + item.summary.slice(0, 120);
        }).join('\n');
    }
    /* 心声上下文 */
    var thoughtCtx = '';
    if (rpc2State.thoughtLog.length > 0) {
      thoughtCtx = '\n\n【你在查岗过程中真实的内心反应（情感的来源）】\n' +
        rpc2State.thoughtLog.map(function(t) {
          return '• [' + t.page + '] ' + t.thought;
        }).join('\n');
    }
    /* 近期对话背景 */
    var recentChat = '';
    try {
      var hist = p.history || [];
      if (hist.length) {
        recentChat = '\n\n【你与用户近期对话（发消息时保持对话连贯性）】\n' +
          hist.slice(-6).map(function(m) {
            return (m.role === 'user' ? '用户' : p.name) + '：' + (m.content || '').slice(0, 60);
          }).join('\n');
      }
    } catch(e) {}
    var prompt =
      '你是' + p.name + '，人设：' + (p.persona || '') + '。' +
      recentChat + summaryCtx + inspCtx + thoughtCtx +
      '\n\n你刚刚查完了对方的手机，现在回到和对方的聊天界面，主动发' + count + '条消息。' +
      '你的情绪必须与你的查岗结论一致（见上方"综合心情与结论"），内容要结合你查岗中具体看到的内容（拐弯抹角、试探、质问、撒娇或表达情绪都行，要自然）。' +
      '消息要有递进感，可以表现出查岗后的心理变化过程。' +
      '每条消息用"###"分隔，不要加编号或引号，直接输出消息内容。' +
      '使用【' + lang + '】输出。';
    rpc2CallAI(prompt, function(resp) {
      try {
        var msgs = resp.trim().split('###').map(function(s) { return s.trim(); }).filter(Boolean);
        msgs = msgs.slice(0, count);
        if (!msgs.length) msgs = [resp.trim()];
        rpc2SendMessagesSequentially(p, msgs, 0);
      } catch(e) {}
    }, function() {});
  } catch(e) { console.error('[RPC2] 帖子InspectionMessages error:', e); }
}
// 按顺序逐条发送角色消息（每条间隔 1.5~3 秒）
function rpc2SendMessagesSequentially(p, msgs, idx) {
  if (idx >= msgs.length) return;
  try {
    if (!p.history) p.history = [];
    p.history.push({ role: 'char', content: msgs[idx] });
    if (typeof saveData === 'function') saveData();
    if (typeof currentId !== 'undefined' && String(currentId) === String(p.id) && typeof renderMessages === 'function') renderMessages();
    var box = document.getElementById('chatBox');
    if (box && typeof currentId !== 'undefined' && String(currentId) === String(p.id)) box.scrollTop = box.scrollHeight;
  } catch(e) {}
  var delay = 1500 + Math.random() * 1500;
  setTimeout(function() { rpc2SendMessagesSequentially(p, msgs, idx + 1); }, delay);
}
// 发送消息到聊天
function rpc2SendMessage(text) {
  try {
    var p = typeof getCurrentPersona === 'function' ? getCurrentPersona() : null;
    if (!p) return;
    var msgs = p.history || [];
    msgs.push({ role: 'char', content: text });
    p.history = msgs;
    if (typeof saveData === 'function') saveData();
    if (typeof renderMessages === 'function') renderMessages();
    var box = document.getElementById('chatBox');
    if (box) box.scrollTop = box.scrollHeight;
  } catch(e) {}
}
// 调用 AI API
function rpc2CallAI(prompt, onSuccess, onError) {
  try {
    /* 优先使用 app 自身的 apiConfig（存储在 mono_api） */
    var cfg = _getCurrentActiveApiConfig();
    var apiKey  = cfg.key   || (typeof getApiKey  === 'function' ? getApiKey()  : '') || localStorage.getItem('openai_api_key') || localStorage.getItem('api_key') || '';
    var model   = _getEffectiveApiModel(cfg.model || (typeof getModel === 'function' ? getModel() : ''));
    var baseUrl = ((cfg.url || (typeof getBaseUrl === 'function' ? getBaseUrl() : '') || 'https://api.openai.com/v1').replace(/\/+$/, ''));
    if (!apiKey) {
      onError(new Error('API Key required'));
      return;
    }
    var reqBody = _applyApiModel({
      messages: [{ role: 'user', content: prompt }],
      temperature: 0.85,
      max_tokens: 400
    }, model);
    fetch(baseUrl + '/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + apiKey
      },
      body: JSON.stringify(reqBody)
    })
    .then(function(r) { return r.json(); })
    .then(function(d) {
      var content = d.choices?.[0]?.message?.content || '';
      onSuccess(content);
    })
    .catch(onError);
  } catch(e) {
    onError(e);
  }
}
// ===== 心声弹窗拖动功能 =====
function rpc2InitThoughtDrag() {
  var popup = document.getElementById('rpc2ThoughtPopup');
  var header = document.getElementById('rpc2ThoughtHeader');
  
  header.addEventListener('mousedown', rpc2StartDrag);
  header.addEventListener('touchstart', rpc2StartDrag, { passive: false });
  
  document.addEventListener('mousemove', rpc2Drag);
  document.addEventListener('touchmove', rpc2Drag, { passive: false });
  
  document.addEventListener('mouseup', rpc2EndDrag);
  document.addEventListener('touchend', rpc2EndDrag);
}
function rpc2StartDrag(e) {
  var popup = document.getElementById('rpc2ThoughtPopup');
  rpc2State.isDragging = true;
  popup.classList.add('dragging');
  
  var clientX = e.touches ? e.touches[0].clientX : e.clientX;
  var clientY = e.touches ? e.touches[0].clientY : e.clientY;
  
  var rect = popup.getBoundingClientRect();
  rpc2State.dragOffsetX = clientX - rect.left;
  rpc2State.dragOffsetY = clientY - rect.top;
  
  e.preventDefault();
}
function rpc2Drag(e) {
  if (!rpc2State.isDragging) return;
  
  var popup = document.getElementById('rpc2ThoughtPopup');
  var clientX = e.touches ? e.touches[0].clientX : e.clientX;
  var clientY = e.touches ? e.touches[0].clientY : e.clientY;
  
  var newLeft = clientX - rpc2State.dragOffsetX;
  var newTop = clientY - rpc2State.dragOffsetY;
  
  // 限制在屏幕范围内
  newLeft = Math.max(0, Math.min(newLeft, window.innerWidth - popup.offsetWidth));
  newTop = Math.max(0, Math.min(newTop, window.innerHeight - popup.offsetHeight));
  
  popup.style.left = newLeft + 'px';
  popup.style.top = newTop + 'px';
  
  e.preventDefault();
}
function rpc2EndDrag() {
  if (rpc2State.isDragging) {
    var popup = document.getElementById('rpc2ThoughtPopup');
    popup.classList.remove('dragging');
    rpc2State.isDragging = false;
  }
}
// ===== 触发反向查岗（供外部调用）=====
