// ===== script-22 =====

/* ================================================================
   角色间私聊系统 (Inter-Character Chat · ICC)
================================================================ */
var iccState = {
  inspector: null,   // 发起查岗的角色
  target: null,      // 被发现可疑内容的联系人角色
  evidence: '',      // 触发对话的证据摘要
  messages: [],      // [{char:'inspector'|'target', name, text, emotion}]
  saved: false
};
function iccGetFriendlyErrorMessage(err) {
  var msg = String((err && err.message) || '').trim();
  if (!msg || msg === 'empty') return '生成失败，请重试';
  if (/unexpected non-whitespace character after json|unexpected token|json/i.test(msg)) {
    return '生成失败：返回格式不完整，请重试';
  }
  return msg;
}
/* ── 检测是否应触发角色间私聊 ──
   在 enterChatRoom 读完内容、生成心声后调用 */
function iccCheckAndMaybeTrigger(inspector, contact, summary, thoughtText) {
  /* 如果没有对应 persona 对象就跳过 */
  var targetPersona = null;
  try {
    if (typeof personas !== 'undefined') {
      targetPersona = personas.find(function(px) { return px.id == contact.id; }) || null;
    }
  } catch(e) {}
  /* target 角色必须存在且不是 inspector 自己 */
  if (!targetPersona) return;
  if (inspector.id == targetPersona.id) return;
  var lang = inspector.chatLanguage || inspector.language || inspector.lang || '简体中文';
  /* 让 AI 判断情绪强度（0-10），是否值得触发私聊 */
  var assessPrompt =
    '你是' + inspector.name + '，人设：' + (inspector.persona || '') + '。' +
    '你刚刚在用户手机里翻到了用户与「' + contact.name + '」的聊天记录：\n' +
    summary.slice(0, 500) + '\n' +
    '你的内心想法是：' + (thoughtText || '') + '\n' +
    '请判断你是否会想要直接联系「' + contact.name + '」来对峙或了解情况。' +
    '返回JSON：{"trigger":true/false,"intensity":0~10,"reason":"一句话理由（' + lang + '，20字内）","opening":"你主动发给对方的第一句话（' + lang + '，符合你性格，15~30字）"}\n只返回JSON。禁止Markdown，禁止解释，禁止在JSON前后添加任何文字。';
  rpc2CallAI(assessPrompt, function(resp) {
    try {
      var obj = _parseJsonFromText(resp, {}, 'object');
      if (obj.trigger && (obj.intensity || 0) >= 5) {
        /* 显示触发横幅 */
        iccShowBanner(inspector, targetPersona, summary, obj.opening || '');
      }
    } catch(e) {}
  }, function() {});
}
/* ── 显示横幅提示 ── */
function iccShowBanner(inspector, target, evidence, opening) {
  iccState.inspector = inspector;
  iccState.target    = target;
  iccState.evidence  = evidence;
  iccState.opening   = opening;
  iccState.messages  = [];
  iccState.saved     = false;
  var banner = document.getElementById('iccTriggerBanner');
  var bannerText = document.getElementById('iccTriggerBannerText');
  if (bannerText) bannerText.textContent = inspector.name + ' 想联系「' + target.name + '」...';
  if (banner) banner.classList.remove('hide');
  /* 8 秒后自动触发（如果用户没有手动关闭） */
  iccState._bannerTimer = setTimeout(function() {
    iccOpenFromBanner();
  }, 8000);
}
function iccOpenFromBanner() {
  clearTimeout(iccState._bannerTimer);
  iccDismissBanner();
  iccOpen();
}
function iccDismissBanner() {
  clearTimeout(iccState._bannerTimer);
  var banner = document.getElementById('iccTriggerBanner');
  if (banner) banner.classList.add('hide');
}
/* ── 打开私聊弹窗并对话 ── */
function iccOpen() {
  var inspector = iccState.inspector;
  var target    = iccState.target;
  if (!inspector || !target) return;
  /* 重置 UI */
  document.getElementById('iccNavNames').textContent = inspector.name + ' & ' + target.name;
  var avA = document.getElementById('iccNavAvatarA');
  var avB = document.getElementById('iccNavAvatarB');
  if (avA) avA.src = inspector.avatar || '';
  if (avB) avB.src = target.avatar || '';
  var chatArea = document.getElementById('iccChatArea');
  chatArea.innerHTML =
    '<div class="icc-loading" id="iccLoading">' +
      '<div class="icc-loading-dots"><span></span><span></span><span></span></div>' +
      '<div class="icc-loading-text" id="iccLoadingText">正在对话中...</div>' +
    '</div>';
  document.getElementById('iccFooter').style.display = 'none';
  document.getElementById('iccBackdrop').classList.add('open');
  document.getElementById('iccModal').classList.add('open');
  /* 对话 */
  iccGenerateDialogue(inspector, target, iccState.evidence, iccState.opening);
}
/* ── AI 对话 ── */
function iccGenerateDialogue(inspector, target, evidence, opening) {
  var lang = inspector.chatLanguage || inspector.language || inspector.lang || '简体中文';
  /* 构建两人的人设上下文 */
  var inspectorCtx = '【' + inspector.name + '】人设：' + (inspector.persona || '不明') +
    '；与用户关系：' + (inspector.nickname ? '昵称' + inspector.nickname : '恋人/好友') + '。';
  var targetCtx    = '【' + target.name + '】人设：' + (target.persona || '不明') + '。';
  /* 近期各自的聊天记忆 */
  var inspMem = '', targetMem = '';
  try {
    if (inspector.history && inspector.history.length) {
      inspMem = '（' + inspector.name + '近期状态：' +
        inspector.history.slice(-4).map(function(m) {
          return (m.role === 'user' ? '用户' : inspector.name) + '：' + (m.content || '').slice(0, 40);
        }).join('；') + '）';
    }
  } catch(e) {}
  try {
    if (target.history && target.history.length) {
      targetMem = '（' + target.name + '近期状态：' +
        target.history.slice(-4).map(function(m) {
          return (m.role === 'user' ? '用户' : target.name) + '：' + (m.content || '').slice(0, 40);
        }).join('；') + '）';
    }
  } catch(e) {}
  var prompt = [
    '现在模拟两个角色之间的私聊对话。',
    inspectorCtx + inspMem,
    targetCtx + targetMem,
    '【触发原因】',
    inspector.name + ' 在查对方（用户）的手机时，发现了用户与 ' + target.name + ' 的聊天内容：',
    evidence.slice(0, 600),
    '【对话规则】',
    '- ' + inspector.name + ' 是发起方，主动联系 ' + target.name + '（可能对峙、试探、质问或借口联系）',
    '- 第一条消息由 ' + inspector.name + ' 发出：' + (opening || '（请自行生成开场白）'),
    '- 对话要自然、符合双方性格，情绪真实，不要过于戏剧化',
    '- 生成 8~12 条消息的完整对话',
    '- 使用【' + lang + '】',
    '返回JSON数组，每条消息：',
    '[{"speaker":"' + inspector.name + '或' + target.name + '","text":"消息内容","emotion":"当前情绪（4字内，如：紧张、冷漠、委屈等）"}]',
    '只返回JSON数组。'
  ].join('\n');
  rpc2CallAI(prompt, function(resp) {
    try {
      var msgs = _parseJsonFromText(resp, [], 'array');
      if (!Array.isArray(msgs) || !msgs.length) throw new Error('empty');
      iccState.messages = msgs;
      iccRenderDialogue(inspector, target, msgs);
    } catch(e) {
      var chatArea = document.getElementById('iccChatArea');
      if (chatArea) chatArea.innerHTML =
        '<div class="icc-loading"><div class="icc-loading-text" style="color:#e05050;">' + iccGetFriendlyErrorMessage(e) + '</div></div>';
    }
  }, function(e) {
    var chatArea = document.getElementById('iccChatArea');
    if (chatArea) chatArea.innerHTML =
      '<div class="icc-loading"><div class="icc-loading-text" style="color:#e05050;">' + iccGetFriendlyErrorMessage(e) + '</div></div>';
  });
}
/* ── 逐条渲染消息（打字机效果，每条间隔 0.8~1.6 秒） ── */
function iccRenderDialogue(inspector, target, msgs) {
  var chatArea = document.getElementById('iccChatArea');
  chatArea.innerHTML = ''; /* 清除 loading */
  function renderOne(idx) {
    if (idx >= msgs.length) {
      /* 全部渲染完毕，显示底部操作栏 */
      var footer = document.getElementById('iccFooter');
      if (footer) footer.style.display = 'flex';
      return;
    }
    var msg = msgs[idx];
    var isInspector = (msg.speaker === inspector.name);
    var persona = isInspector ? inspector : target;
    /* 先显示打字中 */
    var typingRow = document.createElement('div');
    typingRow.className = 'icc-msg-row' + (isInspector ? ' right' : '');
    typingRow.innerHTML =
      '<img class="icc-msg-avatar" src="' + (persona.avatar || '') + '" alt="">' +
      '<div class="icc-typing"><span></span><span></span><span></span></div>';
    chatArea.appendChild(typingRow);
    chatArea.scrollTop = chatArea.scrollHeight;
    var delay = 900 + Math.random() * 800;
    setTimeout(function() {
      /* 替换打字中为气泡 */
      chatArea.removeChild(typingRow);
      var row = document.createElement('div');
      row.className = 'icc-msg-row' + (isInspector ? ' right' : '');
      row.innerHTML =
        '<img class="icc-msg-avatar" src="' + (persona.avatar || '') + '" alt="">' +
        '<div class="icc-msg-col">' +
          '<div class="icc-msg-name">' + (msg.speaker || persona.name) + '</div>' +
          '<div class="icc-bubble">' + _iccEsc(msg.text || '') + '</div>' +
          (msg.emotion ? '<div class="icc-emotion-tag">— ' + _iccEsc(msg.emotion) + '</div>' : '') +
        '</div>';
      chatArea.appendChild(row);
      chatArea.scrollTop = chatArea.scrollHeight;
      setTimeout(function() { renderOne(idx + 1); }, 500 + Math.random() * 400);
    }, delay);
  }
  renderOne(0);
}
function _iccEsc(s) {
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
/* ── 加入记忆 ── */
function iccSaveToMemory() {
  var btn = document.getElementById('iccSaveMemBtn');
  if (iccState.saved) return;
  if (btn) btn.disabled = true;
  var inspector = iccState.inspector;
  var target    = iccState.target;
  var msgs      = iccState.messages;
  if (!inspector || !target || !msgs.length) return;
  var now = new Date();
  var dateStr = now.getFullYear() + '-' +
    String(now.getMonth() + 1).padStart(2, '0') + '-' +
    String(now.getDate()).padStart(2, '0');
  var dialogue = msgs.map(function(m) {
    return (m.speaker || '?') + '：' + (m.text || '') + (m.emotion ? '（' + m.emotion + '）' : '');
  }).join('\n');
  var memContent =
    '[角色间私聊记录 ' + dateStr + ']\n' +
    inspector.name + ' 主动联系了 ' + target.name + '（起因：查岗时发现的聊天内容）\n' +
    dialogue;
  var memEntry = { content: memContent, date: dateStr, auto: true, source: '角色间私聊' };
  /* 写入 inspector */
  try {
    if (!inspector.memoryCore) inspector.memoryCore = [];
    inspector.memoryCore.push(memEntry);
  } catch(e) {}
  /* 写入 target */
  try {
    if (!target.memoryCore) target.memoryCore = [];
    target.memoryCore.push(memEntry);
  } catch(e) {}
  /* 统一持久化（避免触发 UI 表单覆盖其他角色数据） */
  try { if (typeof saveData === 'function') saveData(); } catch(e) {}
  iccState.saved = true;
  if (btn) {
    btn.innerHTML = '<i class="fas fa-check"></i> 已加入记忆';
    btn.style.background = '#4caf78';
    btn.disabled = false;
  }
}
/* ── 关闭 ── */
function iccClose() {
  document.getElementById('iccBackdrop').classList.remove('open');
  document.getElementById('iccModal').classList.remove('open');
  iccDismissBanner();
}


