  function olSetBabyPartnerMeta(pid, babyIdx, loveState, partnerCard) {
    if (typeof getBabyList !== 'function' || typeof saveBabyList !== 'function') return;
    const babies = getBabyList(pid) || [];
    if (!babies[babyIdx]) return;
    babies[babyIdx].loveStatus = loveState.status || 'single';
    babies[babyIdx].lovePartnerName = (partnerCard && partnerCard.name) || '';
    babies[babyIdx].lovePartnerInfo = partnerCard
      ? ((partnerCard.name || '对象') + '（' + olStatusLabel(loveState.status || 'single') + '）')
      : '';
    babies[babyIdx].lovePartnerMeta = partnerCard ? partnerCard.onlineSource : null;
    saveBabyList(pid, babies);
  }

  async function olUpdateMyRedlinePostStatus(childId, status) {
    const state = olState();
    let changed = false;
    state.redline帖子 = (state.redline帖子 || []).map(function(帖子) {
      if (String(帖子.ownerId) === String(state.profile.id) && String(帖子.childId) === String(childId)) {
        changed = true;
        return Object.assign({}, 帖子, { status: status || 'single' });
      }
      return 帖子;
    });
    if (changed) olSave(state);
    const sb = olClient(state);
    if (!sb) return;
    const myPost = (state.redline帖子 || []).find(function(帖子) {
      return String(帖子.ownerId) === String(state.profile.id) && String(帖子.childId) === String(childId);
    });
    if (!myPost) return;
    try {
      await sb.from('mh_online_redline_帖子s').upsert({
        id: myPost.id,
        owner_id: myPost.ownerId,
        owner_name: myPost.ownerName,
        child_id: myPost.childId,
        child_name: myPost.childName,
        age: myPost.age,
        avatar: myPost.avatar || '',
        bio: myPost.bio || '',
        status: status || 'single',
        created_at: myPost.createdAt || olNow()
      });
    } catch(e) {
      console.warn('[redline 帖子 status update]', e);
    }
  }

  function olApplyRemoteLoveLinkToLocal(row, silent) {
    const payload = olUnpackNote(row.note || '');
    if (!payload || !payload.childA || !payload.childB) return false;
    const localChild = olGetLocalChildProfile(row.child_a_id) || olGetLocalChildProfile(row.child_b_id);
    if (!localChild) return false;
    const myChild = String(localChild.childId) === String(payload.childA.childId) ? payload.childA : payload.childB;
    const partnerChild = String(localChild.childId) === String(payload.childA.childId) ? payload.childB : payload.childA;
    const parsed = olParseChildId(localChild.childId);
    if (!parsed || typeof getLoveState !== 'function' || typeof saveLoveState !== 'function') return false;
    const pid = parsed.personaId;
    const babyIdx = parsed.babyIdx;
    let loveState = getLoveState(pid, babyIdx);
    if ((loveState.onlineUpdatedAt || 0) > (row.updated_at || 0)) return false;
    loveState.matches = Array.isArray(loveState.matches) ? loveState.matches : [];
    let idx = loveState.matches.findIndex(function(m) {
      return String((m && m.onlineSource && m.onlineSource.sourceChildId) || '') === String(partnerChild.childId || '');
    });
    const partnerCard = {
      name: partnerChild.name || '联机对象',
      age: partnerChild.age || 18,
      gender: partnerChild.gender || '',
      job: '联机好友宝宝',
      mbti: partnerChild.mbti || '',
      bio: (partnerChild.bio || '来自联机好友的孩子对象').slice(0, 220),
      tags: olEnsureArrayUnique(['联机对象', payload.relationType === 'proposal' ? '已求婚' : '相亲中', partnerChild.parentUserName || '', partnerChild.parentPersonaName || '']),
      personality: partnerChild.personality || partnerChild.bio || '',
      appearance: partnerChild.appearance || '',
      firstMeetScenario: '你们通过联机红线邀请建立了关系，并在家庭软件的恋爱观察室继续发展。',
      avatar: partnerChild.avatar || '',
      onlineSource: {
        sourceType: 'online_friend_baby',
        linkId: row.id,
        sourceChildId: partnerChild.childId,
        ownerUserId: String(partnerChild.ownerId || ''),
        ownerUserName: partnerChild.parentUserName || partnerChild.ownerName || '',
        ownerPersonaId: partnerChild.personaId || '',
        ownerPersonaName: partnerChild.parentPersonaName || partnerChild.personaName || '',
        relationKind: payload.relationType || row.relation_type || 'date',
        parentUserName: partnerChild.parentUserName || '',
        parentPersonaName: partnerChild.parentPersonaName || '',
        sourceChildName: partnerChild.name || ''
      }
    };
    if (idx < 0) {
      loveState.matches.push(partnerCard);
      idx = loveState.matches.length - 1;
    } else {
      loveState.matches[idx] = Object.assign({}, loveState.matches[idx], partnerCard);
    }
    loveState.status = payload.status || 'dating';
    loveState.loveProgress = payload.loveProgress || 0;
    loveState.chatHistory = Array.isArray(payload.chatHistory) ? payload.chatHistory : [];
    loveState.children = Array.isArray(payload.children) ? payload.children : [];
    loveState.relationshipStage = payload.relationshipStage || 0;
    loveState.onlineLinkId = row.id;
    loveState.onlineUpdatedAt = row.updated_at || payload.updatedAt || olNow();
    loveState.onlineLinkMeta = {
      linkId: row.id,
      myChildId: myChild.childId,
      partnerChildId: partnerChild.childId,
      relationType: payload.relationType || row.relation_type || 'date',
      parentUserName: partnerChild.parentUserName || '',
      parentPersonaName: partnerChild.parentPersonaName || ''
    };
    loveState.selectedMatchIdx = loveState.status === 'single' ? -1 : idx;
    loveState.__skipOnlineSync = true;
    saveLoveState(pid, babyIdx, loveState);
    try { olSyncGrandchildrenRegistry(pid, babyIdx, loveState.children); } catch(e) {}
    try { olSetBabyPartnerMeta(pid, babyIdx, loveState, loveState.status === 'single' ? null : loveState.matches[idx]); } catch(e) {}
    try { olUpdateMyRedlinePostStatus(myChild.childId, loveState.status); } catch(e) {}
    try { olRefreshSyncedBabyViews(pid, babyIdx); } catch(e) {}
    if (!silent && loveState.status !== 'single') {
      alert((myChild.name || '孩子') + ' 与 ' + (partnerChild.name || '对象') + ' 的联机关系已同步到恋爱观察室。');
    }
    return true;
  }

  async function olSyncLoveStateForBaby(pid, babyIdx) {
    const state = olState();
    const sb = olClient(state);
    if (!sb || typeof getLoveState !== 'function') return;
    const loveState = getLoveState(pid, babyIdx);
    if (!loveState || !loveState.onlineLinkId || !loveState.onlineLinkMeta) return;
    const myChild = olGetLocalChildProfile(pid + '_' + babyIdx);
    if (!myChild) return;
    const partnerChildId = loveState.onlineLinkMeta.partnerChildId;
    const partnerMeta = loveState.matches.find(function(m) {
      return String((m && m.onlineSource && m.onlineSource.sourceChildId) || '') === String(partnerChildId || '');
    });
    const partnerChild = {
      childId: partnerChildId,
      name: partnerMeta ? partnerMeta.name : ((loveState.onlineLinkMeta && loveState.onlineLinkMeta.partnerChildName) || '联机对象'),
      age: partnerMeta ? partnerMeta.age : 18,
      gender: partnerMeta ? (partnerMeta.gender || '') : '',
      avatar: partnerMeta ? (partnerMeta.avatar || '') : '',
      bio: partnerMeta ? (partnerMeta.bio || '') : '',
      appearance: partnerMeta ? (partnerMeta.appearance || '') : '',
      personality: partnerMeta ? (partnerMeta.personality || '') : '',
      personaId: partnerMeta && partnerMeta.onlineSource ? (partnerMeta.onlineSource.ownerPersonaId || '') : '',
      personaName: partnerMeta && partnerMeta.onlineSource ? (partnerMeta.onlineSource.ownerPersonaName || '') : '',
      parentUserName: partnerMeta && partnerMeta.onlineSource ? (partnerMeta.onlineSource.parentUserName || partnerMeta.onlineSource.ownerUserName || '') : (loveState.onlineLinkMeta.parentUserName || ''),
      parentPersonaName: partnerMeta && partnerMeta.onlineSource ? (partnerMeta.onlineSource.parentPersonaName || partnerMeta.onlineSource.ownerPersonaName || '') : (loveState.onlineLinkMeta.parentPersonaName || ''),
      ownerName: partnerMeta && partnerMeta.onlineSource ? (partnerMeta.onlineSource.ownerUserName || '') : '',
      familyLabel: ((partnerMeta && partnerMeta.onlineSource ? (partnerMeta.onlineSource.parentUserName || '') : '') || loveState.onlineLinkMeta.parentUserName || '对方用户') + ' 与 ' + (((partnerMeta && partnerMeta.onlineSource ? (partnerMeta.onlineSource.parentPersonaName || '') : '') || loveState.onlineLinkMeta.parentPersonaName || '对方角色')) + ' 的孩子'
    };
    const payload = olBuildLoveLinkPayload(loveState.onlineLinkId, loveState.onlineLinkMeta.relationType, myChild, partnerChild, loveState);
    const pairUsers = [String(state.profile.id), String(partnerMeta && partnerMeta.onlineSource ? (partnerMeta.onlineSource.ownerUserId || '') : '')].sort();
    const row = {
      id: loveState.onlineLinkId,
      user_a: pairUsers[0] || String(state.profile.id),
      user_b: pairUsers[1] || String(state.profile.id),
      child_a_id: payload.childA.childId,
      child_b_id: payload.childB.childId,
      status: payload.status,
      relation_type: payload.relationType,
      note: olPackNote(payload),
      created_at: loveState.onlineCreatedAt || olNow(),
      updated_at: olNow()
    };
    await olUpdateMyRedlinePostStatus(myChild.childId, loveState.status || 'single');
    const res = await sb.from('mh_online_love_links').upsert(row);
    if (!res.error) {
      loveState.onlineUpdatedAt = row.updated_at;
      loveState.onlineCreatedAt = row.created_at;
      saveLoveState(pid, babyIdx, loveState);
      try { olSyncGrandchildrenRegistry(pid, babyIdx, loveState.children); } catch(e) {}
      try { olRefreshSyncedBabyViews(pid, babyIdx); } catch(e) {}
    }
  }

  function olDefaultState() {
    const now = olNow();
    return {
      activeTab: 'home',
      currentRoomId: '',
      profile: {
        id: olUid('user'),
        displayName: olGetUserName(),
        avatar: '',
        inviteCode: olInviteCode(),
        inviteExpiresAt: now + 24 * 60 * 60 * 1000,
        updatedAt: now
      },
      backend: {
        mode: 'supabase',
        supabaseUrl: '',
        supabaseAnonKey: '',
        autoSync: true
      },
      friends: [],
      friend请求Inbox: [],
      friend请求Outbox: [],
      sharedCards: [],
      rooms: [],
      roomResidents: {},
      messages: {},
      redline帖子: [],
      redlineActions: [],
      processedActionIds: [],
      lastSyncAt: 0
    };
  }

  function olState() {
    const base = olDefaultState();
    const legacy = olRead(OL_LEGACY_KEY, {});
    const saved = olRead(OL_KEY, Object.keys(legacy || {}).length ? legacy : {});
    const merged = Object.assign({}, base, saved);
    merged.profile = Object.assign({}, base.profile, saved.profile || {});
    merged.backend = Object.assign({}, base.backend, saved.backend || {});
    merged.friends = Array.isArray(saved.friends) ? saved.friends : [];
    merged.friend请求Inbox = Array.isArray(saved.friend请求Inbox) ? saved.friend请求Inbox : [];
    merged.friend请求Outbox = Array.isArray(saved.friend请求Outbox) ? saved.friend请求Outbox : [];
    merged.sharedCards = Array.isArray(saved.sharedCards) ? saved.sharedCards : [];
    merged.rooms = Array.isArray(saved.rooms) ? saved.rooms : [];
    merged.roomResidents = saved.roomResidents && typeof saved.roomResidents === 'object' ? saved.roomResidents : {};
    merged.messages = saved.messages && typeof saved.messages === 'object' ? saved.messages : {};
    merged.redline帖子 = Array.isArray(saved.redline帖子) ? saved.redline帖子 : [];
    merged.redlineActions = Array.isArray(saved.redlineActions) ? saved.redlineActions : [];
    merged.processedActionIds = Array.isArray(saved.processedActionIds) ? saved.processedActionIds : [];
    if (!merged.profile.inviteCode || olNow() > (merged.profile.inviteExpiresAt || 0)) {
      merged.profile.inviteCode = olInviteCode();
      merged.profile.inviteExpiresAt = olNow() + 24 * 60 * 60 * 1000;
    }
    if (!merged.profile.displayName) merged.profile.displayName = olGetUserName();
    return merged;
  }

  function olSave(state) {
    state.profile.updatedAt = olNow();
    olWrite(OL_KEY, state);
    window.__olState = state;
    return state;
  }

  function olClient(state) {
    state = state || olState();
    if (state.backend.mode !== 'supabase') return null;
    if (!state.backend.supabaseUrl || !state.backend.supabaseAnonKey) return null;
    if (!window.supabase || !window.supabase.createClient) return null;
    if (!window.__olSb || window.__olSbUrl !== state.backend.supabaseUrl) {
      window.__olSb = window.supabase.createClient(state.backend.supabaseUrl, state.backend.supabaseAnonKey);
      window.__olSbUrl = state.backend.supabaseUrl;
    }
    return window.__olSb;
  }

  function olPackNote(meta) {
    try { return '[MHJSON]' + JSON.stringify(meta || {}); } catch(e) { return '[MHJSON]{}'; }
  }
  function olUnpackNote(note) {
    const raw = String(note || '');
    if (raw.indexOf('[MHJSON]') === 0) {
      try { return JSON.parse(raw.slice(8)); } catch(e) {}
    }
    return { message: raw, status: 'pending' };
  }

  function olParseChildId(childId) {
    const raw = String(childId || '');
    const idx = raw.lastIndexOf('_');
    if (idx < 0) return null;
    const pid = raw.slice(0, idx);
    const bi = parseInt(raw.slice(idx + 1), 10);
    if (!pid || isNaN(bi)) return null;
    return { personaId: pid, babyIdx: bi };
  }

  function olFindRoomByMembers(rooms, ids) {
    const sorted = (ids || []).map(String).sort();
    return (rooms || []).find(function(r) {
      const ms = (r.members || []).map(String).sort();
      if (ms.length !== sorted.length) return false;
      for (let i = 0; i < ms.length; i++) if (ms[i] !== sorted[i]) return false;
      return true;
    });
  }

  async function olEnsureRemoteProfile(state) {
    const sb = olClient(state);
    if (!sb) return false;
    const payload = {
      id: state.profile.id,
      display_name: state.profile.displayName,
      invite_code: state.profile.inviteCode,
      invite_expires_at: state.profile.inviteExpiresAt,
      avatar: state.profile.avatar || '',
      updated_at: olNow()
    };
    const res = await sb.from('mh_online_profiles').upsert(payload);
    if (res.error) throw res.error;
    return true;
  }

  async function olEnsureDmRoom(state, uidA, uidB, titleHint) {
    const me = String(uidA);
    const other = String(uidB);
    if (!me || !other || me === other) return;
    const sorted = [me, other].sort();
    const dmId = 'dm__' + sorted[0] + '__' + sorted[1];
    const room = {
      id: dmId,
      title: titleHint || '好友私聊',
      owner_id: state.profile.id,
      owner_name: state.profile.displayName,
      members: sorted,
      created_at: olNow()
    };
    const sb = olClient(state);
    if (sb) {
      const up = await sb.from('mh_online_rooms').upsert(room);
      if (up.error) throw up.error;
    } else {
      const local = olState();
      const exists = olFindRoomByMembers(local.rooms, sorted);
      if (!exists) {
        local.rooms.unshift({
          id: dmId,
          title: room.title,
          ownerId: room.owner_id,
          ownerName: room.owner_name,
          members: sorted,
          createdAt: room.created_at
        });
        olSave(local);
      }
    }
  }

  function olMapActionRow(row) {
    const meta = olUnpackNote(row.note || '');
    return {
      id: row.id,
      帖子Id: row.帖子_id,
      fromUserId: row.from_user_id,
      fromUserName: row.from_user_name,
      toUserId: row.to_user_id,
      type: row.type,
      note: row.note || '',
      meta: meta,
      status: meta.status || 'pending',
      createdAt: row.created_at || 0
    };
  }

  function olEnsureArrayUnique(arr) {
    const map = {};
    const out = [];
    (arr || []).forEach(function(id) {
      const k = String(id || '');
      if (!k || map[k]) return;
      map[k] = true;
      out.push(k);
    });
    return out;
  }

  const OL_ROOM_PERSONA_MODES = {
    vibe: { label: '气氛组', desc: '负责接梗、点火、让房间别冷场。' },
    oracle: { label: '军师', desc: '负责拆解问题，给出有方向感的建议。' },
    roast: { label: '吐槽机', desc: '负责制造记忆点，轻微毒舌但不冒犯。' },
    radio: { label: '深夜电台', desc: '负责把话题说柔一点，像有陪伴感。' }
  };

  function olResidentModes() {
    return Object.keys(OL_ROOM_PERSONA_MODES);
  }

  function olResidentModeLabel(mode) {
    return (OL_ROOM_PERSONA_MODES[mode] && OL_ROOM_PERSONA_MODES[mode].label) || '气氛组';
  }

  function olResidentModeDesc(mode) {
    return (OL_ROOM_PERSONA_MODES[mode] && OL_ROOM_PERSONA_MODES[mode].desc) || '';
  }

  function olGetRoomResidents(state, roomId) {
    state = state || olState();
    const all = state.roomResidents && typeof state.roomResidents === 'object' ? state.roomResidents : {};
    return Array.isArray(all[roomId]) ? all[roomId] : [];
  }

  function olSetRoomResidents(state, roomId, residents) {
    state.roomResidents = state.roomResidents && typeof state.roomResidents === 'object' ? state.roomResidents : {};
    state.roomResidents[roomId] = Array.isArray(residents) ? residents : [];
    return state;
  }

  function olTrimResidentText(text, max) {
    return String(text || '').replace(/\s+/g, ' ').trim().slice(0, max || 18);
  }

  function olResidentPersonaHook(persona) {
    const raw = olTrimResidentText(persona && (persona.persona || persona.appearance || persona.relation || ''), 20);
    return raw || '有点特别的脑回路';
  }

  function olPickResidentMode(defaultMode) {
    const modes = olResidentModes();
    const current = modes.indexOf(defaultMode) >= 0 ? defaultMode : modes[0];
    const promptText = modes.map(function(mode, idx) {
      return (idx + 1) + '. ' + olResidentModeLabel(mode) + ' - ' + olResidentModeDesc(mode);
    }).join('\n');
    const raw = (prompt('选择角色入驻风格：\n\n' + promptText, String(modes.indexOf(current) + 1)) || '').trim();
    if (!raw) return current;
    const idx = parseInt(raw, 10) - 1;
    return modes[idx] || current;
  }

  function olBuildResident回复(persona, resident, triggerMsg, room, messages) {
    const latestText = olTrimResidentText(triggerMsg && triggerMsg.content, 18);
    const hook = olResidentPersonaHook(persona);
    const mode = resident.mode || 'vibe';
    const topic = latestText ? ('“' + latestText + '”') : '这个话题';
    const tail = hook ? (' 这句也很像 ta 那种「' + hook + '」的气质。') : '';
    const pool = {
      vibe: [
        '我来把房间温度拉一下，' + topic + ' 这事别聊成公告，聊成故事会更好玩。',
        topic + ' 我站先有氛围再有结论这边，不然这么好的房间会一下子降温。',
        '插个话，' + topic + ' 其实很适合继续展开，我已经闻到八卦和灵感一起冒头了。'
      ],
      oracle: [
        '军师视角补一句，' + topic + ' 先看谁最在意，再看谁最着急，答案通常就出来了。',
        '如果让我给路线，' + topic + ' 最稳的做法是先确认边界，再决定下一步。',
        topic + ' 不一定要立刻选答案，先拆成情绪、动机、后果，聊天会清楚很多。'
      ],
      roast: [
        '允许我毒舌半句，' + topic + ' 听起来像每个人都很会说，但还没人准备负责收尾。',
        '我先吐槽一下，' + topic + ' 这个走向已经很像深夜群聊名场面了，但我喜欢。',
        topic + ' 目前的气质属于“都觉得自己很冷静，实际已经上头”。'
      ],
      radio: [
        '我想把这句话说慢一点，' + topic + ' 背后更像是在说“希望有人真的懂我”。',
        '深夜电台插播，' + topic + ' 不急着赢，先让彼此被听见，房间会柔下来。',
        topic + ' 如果换个方式说，也许不是争论，是有人在认真求回应。'
      ]
    };
    const choices = pool[mode] || pool.vibe;
    const seed = (messages || []).length + String(resident.id || '').length + String(topic).length;
    return choices[seed % choices.length] + tail;
  }

  async function olPostResidentMessage(roomId, residentId, triggerMsg, forceMode) {
    const state = olState();
    const room = (state.rooms || []).find(function(r){ return String(r.id) === String(roomId); });
    if (!room) return;
    const residents = olGetRoomResidents(state, roomId);
    const idx = residents.findIndex(function(r){ return String(r.id) === String(residentId); });
    if (idx < 0) return;
    const resident = residents[idx];
    const persona = olGetPersonasSafe().find(function(p){ return String(p.id) === String(resident.personaId); });
    if (!persona) return alert('这个入驻角色的原始角色卡已经不存在了。');
    const allMsgs = state.messages[roomId] || [];
    const sourceMsg = triggerMsg || allMsgs[allMsgs.length - 1] || null;
    const content = olBuildResident回复(persona, resident, sourceMsg, room, allMsgs);
    const msg = {
      id: olUid('msg'),
      roomId: roomId,
      senderId: 'resident:' + resident.personaId,
      senderName: state.profile.displayName + ' 的驻场角色',
      speakerType: 'resident_persona',
      speakerName: resident.name + ' · ' + olResidentModeLabel(forceMode || resident.mode),
      speakerAvatar: resident.avatar || persona.avatar || '',
      content: content,
      createdAt: olNow()
    };
    state.messages[roomId] = state.messages[roomId] || [];
    state.messages[roomId].push(msg);
    residents[idx] = Object.assign({}, resident, { lastSpokeAt: msg.createdAt });
    olSetRoomResidents(state, roomId, residents);
    olSave(state);
    if (String(state.currentRoomId || '') === String(roomId) && document.getElementById('olRoomShell').style.display === 'flex') {
      olRenderRoom();
    } else {
      renderOnlineApp();
    }

    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_messages').insert({
        id: msg.id,
        room_id: msg.roomId,
        sender_id: msg.senderId,
        sender_name: msg.senderName,
        speaker_type: msg.speakerType,
        speaker_name: msg.speakerName,
        speaker_avatar: msg.speakerAvatar,
        content: msg.content,
        created_at: msg.createdAt
      });
      if (res.error) console.warn('[resident message]', res.error);
    }
  }

