  function olQuickOpenResidentLab() {
    const state = olState();
    if (!state.rooms.length) return alert('先创建一个聊天室。');
    olOpenRoom(state.currentRoomId || state.rooms[0].id);
    olCloseSheet(null, 'olQuickSheet');
  }

  function olApplyAcceptedRedlineActionLocal(state, action, silent) {
    const me = String(state.profile.id);
    const meta = action.meta || {};
    if ((meta.status || '') !== 'accepted') return false;
    if (state.processedActionIds.indexOf(action.id) !== -1) return false;

    const imFrom = String(action.fromUserId) === me;
    const imTo = String(action.toUserId) === me;
    if (!imFrom && !imTo) return false;

    const myChildId = imFrom ? meta.fromChildId : meta.toChildId;
    const partnerChildId = imFrom ? meta.toChildId : meta.fromChildId;
    const myChild = imFrom ? meta.fromChild : meta.toChild;
    const partnerChild = imFrom ? meta.toChild : meta.fromChild;
    const myParsed = olParseChildId(myChildId);
    if (!myParsed || !partnerChild) return false;

    if (typeof getLoveState !== 'function' || typeof saveLoveState !== 'function') return false;

    const pid = myParsed.personaId;
    const babyIdx = myParsed.babyIdx;
    let loveState = getLoveState(pid, babyIdx);
    loveState.matches = Array.isArray(loveState.matches) ? loveState.matches : [];

    const partnerKey = String(partnerChildId || '');
    let idx = loveState.matches.findIndex(function(m) {
      return String((m && m.onlineSource && m.onlineSource.sourceChildId) || '') === partnerKey;
    });
    const linkId = olMakeLoveLinkId(myChildId, partnerChildId);
    const partnerCard = {
      name: partnerChild.name || '联机对象',
      age: partnerChild.age || 18,
      gender: partnerChild.gender || '',
      job: '联机好友宝宝',
      mbti: partnerChild.mbti || '',
      bio: (partnerChild.bio || '来自联机好友的孩子对象').slice(0, 180),
      tags: olEnsureArrayUnique(['联机好友', action.type === 'proposal' ? '求婚成功' : '约会成功', partnerChild.parentUserName || partnerChild.ownerName || '', partnerChild.parentPersonaName || partnerChild.personaName || '']),
      personality: partnerChild.personality || partnerChild.bio || '',
      appearance: partnerChild.appearance || '',
      firstMeetScenario: '你们通过联机红线邀请认识，关系会在家庭软件的恋爱观察室持续同步。',
      avatar: partnerChild.avatar || '',
      onlineSource: {
        sourceType: 'online_friend_baby',
        linkId: linkId,
        sourceChildId: partnerChildId,
        ownerUserId: imFrom ? action.toUserId : action.fromUserId,
        ownerUserName: partnerChild.parentUserName || partnerChild.ownerName || (imFrom ? (meta.toUserName || '') : (meta.fromUserName || '')),
        ownerPersonaId: partnerChild.personaId || '',
        ownerPersonaName: partnerChild.parentPersonaName || partnerChild.personaName || '',
        relationKind: action.type || 'date',
        parentUserName: partnerChild.parentUserName || partnerChild.ownerName || '',
        parentPersonaName: partnerChild.parentPersonaName || partnerChild.personaName || '',
        sourceChildName: partnerChild.name || '联机对象'
      }
    };
    if (idx < 0) {
      loveState.matches.push(partnerCard);
      idx = loveState.matches.length - 1;
    } else {
      loveState.matches[idx] = Object.assign({}, loveState.matches[idx], partnerCard);
    }

    loveState.selectedMatchIdx = idx;
    if (action.type === 'proposal') {
      loveState.status = 'married';
      loveState.loveProgress = Math.max(90, loveState.loveProgress || 0);
    } else {
      loveState.status = 'dating';
      loveState.loveProgress = Math.max(62, loveState.loveProgress || 0);
    }
    loveState.children = Array.isArray(loveState.children) ? loveState.children : [];
    loveState.chatHistory = Array.isArray(loveState.chatHistory) ? loveState.chatHistory : [];
    loveState.chatHistory.push({
      role: 'narrator',
      content: (myChild && myChild.name ? myChild.name : '宝宝') + ' 与 ' + (partnerChild.name || '联机对象')
        + (action.type === 'proposal' ? ' 在联机里完成求婚并结为伴侣，关系已同步到家庭软件的恋爱观察室。' : ' 在联机里互相同意相亲 / 约会，关系已同步到家庭软件的恋爱观察室。')
    });
    loveState.onlineLinkId = linkId;
    loveState.onlineCreatedAt = loveState.onlineCreatedAt || olNow();
    loveState.onlineUpdatedAt = olNow();
    loveState.onlineLinkMeta = {
      linkId: linkId,
      myChildId: myChildId,
      partnerChildId: partnerChildId,
      relationType: action.type || 'date',
      parentUserName: partnerChild.parentUserName || '',
      parentPersonaName: partnerChild.parentPersonaName || '',
      partnerChildName: partnerChild.name || '联机对象'
    };
    saveLoveState(pid, babyIdx, loveState);
    try { olSyncGrandchildrenRegistry(pid, babyIdx, loveState.children); } catch(e) {}

    try {
      if (typeof _saveLoveMemoryToBaby === 'function') {
        _saveLoveMemoryToBaby(pid, babyIdx, loveState.matches[idx], loveState);
      } else if (typeof getBabyList === 'function' && typeof saveBabyList === 'function') {
        const babies = getBabyList(pid) || [];
        if (babies[babyIdx]) {
          babies[babyIdx].loveStatus = loveState.status;
          babies[babyIdx].lovePartnerName = partnerChild.name || '联机对象';
          babies[babyIdx].lovePartnerInfo = (partnerChild.name || '联机对象') + '（' + olStatusLabel(loveState.status) + '）';
          babies[babyIdx].lovePartnerMeta = partnerCard.onlineSource;
          saveBabyList(pid, babies);
        }
      }
    } catch(e) {}
    try { olUpdateMyRedlinePostStatus(myChildId, loveState.status); } catch(e) {}
    try { olRefreshSyncedBabyViews(pid, babyIdx); } catch(e) {}

    state.processedActionIds.unshift(action.id);
    state.processedActionIds = olEnsureArrayUnique(state.processedActionIds).slice(0, 400);
    if (!silent) alert(action.type === 'proposal' ? '求婚已互相确认，双方成年孩子已进入家庭软件的恋爱观察室。' : '约会邀请已互相确认，双方成年孩子已进入家庭软件的恋爱观察室。');
    return true;
  }

  function olAutoProcessAcceptedActions(state) {
    let changed = false;
    (state.redlineActions || []).forEach(function(a) {
      if ((a.status || '') === 'accepted') {
        const ok = olApplyAcceptedRedlineActionLocal(state, a, true);
        if (ok) changed = true;
      }
    });
    if (changed) olSave(state);
    return changed;
  }

  async function olSyncRemote(forceToast) {
    const state = olSave(olState());
    const sb = olClient(state);
    if (!sb) {
      if (forceToast) alert('当前是本地模式。填入 Supabase 地址和 anon key 后，就能跨手机真联机。');
      renderOnlineApp();
      return;
    }
    try {
      await olEnsureRemoteProfile(state);
      const me = state.profile.id;

      const friendRes = await sb.from('mh_online_friend_links').select('*').or('user_a.eq.' + me + ',user_b.eq.' + me);
      if (friendRes.error) throw friendRes.error;
      const friendIds = [];
      (friendRes.data || []).forEach(function(row) {
        const fid = row.user_a === me ? row.user_b : row.user_a;
        if (fid && friendIds.indexOf(fid) === -1) friendIds.push(fid);
      });

      let friends = [];
      if (friendIds.length) {
        const profileRes = await sb.from('mh_online_profiles').select('*').in('id', friendIds);
        if (profileRes.error) throw profileRes.error;
        friends = (profileRes.data || []).map(function(p) {
          return {
            id: p.id,
            name: p.display_name || '好友',
            inviteCode: p.invite_code || '',
            online: (olNow() - (p.updated_at || 0)) < 4 * 60 * 1000,
            updatedAt: p.updated_at || 0,
            avatar: p.avatar || ''
          };
        });
      }
      state.friends = friends;

      const reqInRes = await sb.from('mh_online_friend_requests').select('*').eq('to_user_id', me).eq('status', 'pending').order('created_at', { ascending: false });
      if (reqInRes.error) throw reqInRes.error;
      state.friend请求Inbox = (reqInRes.data || []).map(function(r) {
        return {
          id: r.id,
          fromUserId: r.from_user_id,
          fromUserName: r.from_user_name || '好友',
          toUserId: r.to_user_id,
          toUserName: r.to_user_name || state.profile.displayName,
          status: r.status || 'pending',
          note: r.note || '',
          createdAt: r.created_at || 0,
          updatedAt: r.updated_at || 0
        };
      });

      const reqOutRes = await sb.from('mh_online_friend_requests').select('*').eq('from_user_id', me).eq('status', 'pending').order('created_at', { ascending: false });
      if (reqOutRes.error) throw reqOutRes.error;
      state.friend请求Outbox = (reqOutRes.data || []).map(function(r) {
        return {
          id: r.id,
          fromUserId: r.from_user_id,
          fromUserName: r.from_user_name || state.profile.displayName,
          toUserId: r.to_user_id,
          toUserName: r.to_user_name || '好友',
          status: r.status || 'pending',
          note: r.note || '',
          createdAt: r.created_at || 0,
          updatedAt: r.updated_at || 0
        };
      });

      const cardOwnerIds = friendIds.concat([me]);
      if (cardOwnerIds.length) {
        const cardsRes = await sb.from('mh_online_persona_cards').select('*').in('owner_id', cardOwnerIds).order('created_at', { ascending: false });
        if (cardsRes.error) throw cardsRes.error;
        state.sharedCards = (cardsRes.data || []).map(function(c) {
          return {
            id: c.id,
            ownerId: c.owner_id,
            ownerName: c.owner_name,
            personaId: c.persona_id,
            name: c.name,
            avatar: c.avatar || '',
            appearance: c.appearance || '',
            persona: c.persona || '',
            summary: c.summary || '',
            createdAt: c.created_at || 0
          };
        });
      }

      const roomRes = await sb.from('mh_online_rooms').select('*').filter('members', 'cs', JSON.stringify([me])).order('created_at', { ascending: false });
      if (roomRes.error) throw roomRes.error;
      state.rooms = (roomRes.data || []).map(function(r) {
        return {
          id: r.id,
          title: r.title || '聊天室',
          ownerId: r.owner_id,
          ownerName: r.owner_name || '',
          members: Array.isArray(r.members) ? r.members : [],
          createdAt: r.created_at || 0
        };
      });

      const plazaRes = await sb.from('mh_online_redline_帖子s').select('*').order('created_at', { ascending: false }).limit(80);
      if (plazaRes.error) throw plazaRes.error;
      state.redline帖子 = (plazaRes.data || []).map(function(p) {
        return {
          id: p.id,
          ownerId: p.owner_id,
          ownerName: p.owner_name || '',
          childId: p.child_id,
          childName: p.child_name,
          age: p.age || 18,
          avatar: p.avatar || '',
          bio: p.bio || '',
          status: p.status || 'single',
          createdAt: p.created_at || 0
        };
      });

      const actInRes = await sb.from('mh_online_redline_actions').select('*').eq('to_user_id', me).order('created_at', { ascending: false }).limit(120);
      if (actInRes.error) throw actInRes.error;
      const actOutRes = await sb.from('mh_online_redline_actions').select('*').eq('from_user_id', me).order('created_at', { ascending: false }).limit(120);
      if (actOutRes.error) throw actOutRes.error;
      const allActs = (actInRes.data || []).concat(actOutRes.data || []);
      const used = {};
      state.redlineActions = allActs.filter(function(r) {
        if (used[r.id]) return false;
        used[r.id] = true;
        return true;
      }).map(olMapActionRow).sort(function(a, b) { return (b.createdAt || 0) - (a.createdAt || 0); });

      const loveARes = await sb.from('mh_online_love_links').select('*').eq('user_a', me).order('updated_at', { ascending: false }).limit(120);
      if (loveARes.error) throw loveARes.error;
      const loveBRes = await sb.from('mh_online_love_links').select('*').eq('user_b', me).order('updated_at', { ascending: false }).limit(120);
      if (loveBRes.error) throw loveBRes.error;
      const loveRows = (loveARes.data || []).concat(loveBRes.data || []);
      const loveUsed = {};
      loveRows.forEach(function(row) {
        if (!row || loveUsed[row.id]) return;
        loveUsed[row.id] = true;
        try { olApplyRemoteLoveLinkToLocal(row, true); } catch(err) { console.warn('[love link apply]', err); }
      });

      state.lastSyncAt = olNow();
      olAutoProcessAcceptedActions(state);
      olSave(state);

      if (state.currentRoomId && document.getElementById('olRoomShell').style.display === 'flex') {
        await olLoadRoomMessages(state.currentRoomId);
      }

      if (forceToast) alert('联机云端已同步完成。');
      renderOnlineApp();
    } catch (e) {
      console.warn('[online sync]', e);
      if (forceToast) {
        const msg = (e && e.message) ? e.message : '请检查表结构 / key / 网络';
        alert('云端同步失败：' + msg + '\n\n如你刚升级版本，请复制设置页SQL重新执行一次。');
      }
    }
  }

  async function olAddFriendByCode() {
    const code = (prompt('输入对方 6 位邀请码') || '').trim();
    if (!code) return;
    const state = olSave(olState());
    const sb = olClient(state);

    if (!sb) {
      const fakeId = 'local_' + code;
      if (state.friends.some(function(f){ return String(f.id) === fakeId || f.inviteCode === code; })) {
        alert('本地演示中该好友已存在。');
        return;
      }
      state.friend请求Outbox.unshift({
        id: olUid('fr'),
        fromUserId: state.profile.id,
        fromUserName: state.profile.displayName,
        toUserId: fakeId,
        toUserName: '好友 ' + code.slice(-2),
        status: 'pending',
        note: 'local',
        createdAt: olNow(),
        updatedAt: olNow()
      });
      olSave(state);
      renderOnlineApp();
      alert('本地演示模式：已发出好友申请。接入 Supabase 后将变成真实双向申请。');
      return;
    }

    try {
      await olEnsureRemoteProfile(state);
      const found = await sb.from('mh_online_profiles').select('*').eq('invite_code', code).gt('invite_expires_at', olNow()).limit(1);
      if (found.error) throw found.error;
      const other = (found.data || [])[0];
      if (!other) return alert('邀请码无效或已过期。');
      if (other.id === state.profile.id) return alert('不能添加自己。');

      const linkId = [state.profile.id, other.id].sort().join('__');
      const linkRes = await sb.from('mh_online_friend_links').select('id').eq('id', linkId).limit(1);
      if (!linkRes.error && (linkRes.data || []).length) return alert('你们已经是好友了。');

      const pendingRes = await sb.from('mh_online_friend_requests').select('id').eq('from_user_id', state.profile.id).eq('to_user_id', other.id).eq('status', 'pending').limit(1);
      if (!pendingRes.error && (pendingRes.data || []).length) return alert('你已经发过好友申请了，等待对方处理即可。');

      const req = {
        id: olUid('fr'),
        from_user_id: state.profile.id,
        from_user_name: state.profile.displayName,
        to_user_id: other.id,
        to_user_name: other.display_name || '好友',
        status: 'pending',
        note: '邀请码申请',
        created_at: olNow(),
        updated_at: olNow()
      };
      const ins = await sb.from('mh_online_friend_requests').insert(req);
      if (ins.error) throw ins.error;
      await olSyncRemote(false);
      alert('好友申请已发送。对方会在联机-好友申请里看到并可接受/拒绝。');
    } catch (e) {
      alert('发送好友申请失败：' + (e.message || '未知错误'));
    }
  }

  async function olHandleFriendRequest(reqId, decision) {
    const state = olSave(olState());
    const req = (state.friend请求Inbox || []).find(function(r){ return String(r.id) === String(reqId); });
    if (!req) return;

    if (decision !== 'accepted' && decision !== 'rejected') return;
    const sb = olClient(state);
    try {
      if (sb) {
        const up = await sb.from('mh_online_friend_requests').update({ status: decision, updated_at: olNow() }).eq('id', req.id);
        if (up.error) throw up.error;
        if (decision === 'accepted') {
          const pair = [state.profile.id, req.fromUserId].sort();
          const linkId = pair.join('__');
          const ins = await sb.from('mh_online_friend_links').upsert({ id: linkId, user_a: pair[0], user_b: pair[1], created_at: olNow() });
          if (ins.error) throw ins.error;
          await olEnsureDmRoom(state, state.profile.id, req.fromUserId, req.fromUserName + ' · 私聊');
        }
      } else {
        state.friend请求Inbox = (state.friend请求Inbox || []).filter(function(r){ return String(r.id) !== String(req.id); });
        if (decision === 'accepted') {
          if (!state.friends.some(function(f){ return String(f.id) === String(req.fromUserId); })) {
            state.friends.unshift({ id: req.fromUserId, name: req.fromUserName || '好友', inviteCode: '', online: true, updatedAt: olNow(), avatar: '' });
          }
          const localDm = olFindRoomByMembers(state.rooms, [state.profile.id, req.fromUserId]);
          if (!localDm) {
            state.rooms.unshift({ id: 'dm__' + [state.profile.id, req.fromUserId].sort().join('__'), title: (req.fromUserName || '好友') + ' · 私聊', ownerId: state.profile.id, ownerName: state.profile.displayName, members: [state.profile.id, req.fromUserId], createdAt: olNow() });
          }
        }
        olSave(state);
      }
      await olSyncRemote(false);
      renderOnlineApp();
      alert(decision === 'accepted' ? '已接受好友申请，双方自动互为好友并建立私聊。' : '已拒绝该好友申请。');
    } catch (e) {
      alert('处理申请失败：' + (e.message || '未知错误'));
    }
  }

  async function olDeleteFriend(friendId) {
    const state = olState();
    const friend = state.friends.find(function(f){ return String(f.id) === String(friendId); });
    if (!friend) return;
    if (!confirm('确定要删除这位好友吗？系统会解除好友关系，并清理双方私聊房间。')) return;
    const me = String(state.profile.id);
    const other = String(friendId);
    const pair = [me, other].sort();
    const linkId = pair.join('__');
    const dmId = 'dm__' + pair[0] + '__' + pair[1];
    state.friends = state.friends.filter(function(f){ return String(f.id) !== other; });
    state.friend请求Inbox = (state.friend请求Inbox || []).filter(function(r){ return String(r.fromUserId) !== other && String(r.toUserId) !== other; });
    state.friend请求Outbox = (state.friend请求Outbox || []).filter(function(r){ return String(r.fromUserId) !== other && String(r.toUserId) !== other; });
    state.rooms = (state.rooms || []).filter(function(room){ return String(room.id) !== dmId; });
    delete state.messages[dmId];
    if (String(state.currentRoomId || '') === String(dmId)) {
      state.currentRoomId = null;
      try { olCloseRoom(); } catch(e) {}
    }
    olSave(state);
    const sb = olClient(state);
    if (sb) {
      await sb.from('mh_online_messages').delete().eq('room_id', dmId);
      await sb.from('mh_online_rooms').delete().eq('id', dmId);
      await sb.from('mh_online_friend_links').delete().eq('id', linkId);
      await sb.from('mh_online_friend_requests').delete().eq('from_user_id', me).eq('to_user_id', other);
      await sb.from('mh_online_friend_requests').delete().eq('from_user_id', other).eq('to_user_id', me);
    }
    renderOnlineApp();
    alert('好友已删除。');
  }

  async function olPublishPersona(personaId) {
    const personas = olGetPersonasSafe();
    const persona = personas.find(function(p){ return String(p.id) === String(personaId); });
    if (!persona) return;
    const state = olSave(olState());
    const card = {
      id: olUid('card'),
      ownerId: state.profile.id,
      ownerName: state.profile.displayName,
      personaId: persona.id,
      name: persona.name || '未命名角色',
      avatar: persona.avatar || '',
      appearance: persona.appearance || '',
      persona: persona.persona || '',
      summary: (persona.persona || persona.appearance || '').slice(0, 160),
      createdAt: olNow()
    };
    state.sharedCards = [card].concat(state.sharedCards.filter(function(c){
      return !(String(c.ownerId) === String(card.ownerId) && String(c.personaId) === String(card.personaId));
    }));
    olSave(state);
    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_persona_cards').upsert({
        id: card.id,
        owner_id: card.ownerId,
        owner_name: card.ownerName,
        persona_id: card.personaId,
        name: card.name,
        avatar: card.avatar,
        appearance: card.appearance,
        persona: card.persona,
        summary: card.summary,
        created_at: card.createdAt
      });
      if (res.error) return alert('角色卡已保存到本地，但云端发布失败：' + res.error.message);
    }
    renderOnlineApp();
    alert('角色卡已发布。');
  }

  async function olUnpublishPersona(cardId) {
    const state = olState();
    const card = state.sharedCards.find(function(c){ return String(c.id) === String(cardId); });
    if (!card) return;
    if (String(card.ownerId) !== String(state.profile.id)) return alert('只能撤回自己发布的角色卡。');
    if (!confirm('确定要撤回这张角色卡吗？撤回后好友将不会再看到它。')) return;
    state.sharedCards = state.sharedCards.filter(function(c){ return String(c.id) !== String(card.id); });
    olSave(state);
    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_persona_cards').delete().eq('id', card.id);
      if (res.error) {
        await olSyncRemote(false);
        return alert('云端撤回失败：' + res.error.message);
      }
    }
    renderOnlineApp();
    alert('角色卡已撤回发布。');
  }

  function olImportCard(cardId) {
    const state = olState();
    const card = state.sharedCards.find(function(c){ return String(c.id) === String(cardId); });
    if (!card) return;

    const list = olGetPersonasSafe();
    const exists = list.some(function(p) {
      const src = p && p.onlineSource;
      if (src && String(src.cardId || '') === String(card.id)) return true;
      if (src && String(src.ownerId || '') === String(card.ownerId) && String(src.personaId || '') === String(card.personaId)) return true;
      return p.name === card.name && (p.persona || '') === (card.persona || '');
    });
    if (exists) return alert('该好友角色已在联络人中，重复添加已拦截。');

    const newP = {
      id: Date.now(),
      name: card.name,
      avatar: card.avatar || '',
      appearance: card.appearance || '',
      persona: card.persona || '',
      relation: '联机好友角色',
      history: [],
      memoryCore: [],
      createdAt: olNow(),
      onlineSource: {
        sourceType: 'online_friend_card',
        cardId: card.id,
        ownerId: card.ownerId,
        ownerName: card.ownerName,
        personaId: card.personaId
      }
    };
    list.unshift(newP);

    try {
      if (typeof personas !== 'undefined' && Array.isArray(personas)) personas = list;
    } catch(e) {}

    try {
      if (typeof saveData === 'function') saveData();
      else localStorage.setItem('mono_personas', JSON.stringify(list));
    } catch(e) {
      localStorage.setItem('mono_personas', JSON.stringify(list));
    }

    try { if (typeof renderContactList === 'function') renderContactList(); } catch(e) {}
    alert('好友角色已加入聊天软件联络人列表。');
  }

  async function olCreateRoom() {
    const state = olState();
    if (!state.friends.length) return alert('先有至少 1 位已通过申请的好友。');
    const names = state.friends.map(function(f, i){ return (i + 1) + '. ' + f.name; }).join('\n');
    const idxText = prompt('输入要邀请的好友序号，可多选，用逗号分隔。\n\n' + names);
    if (!idxText) return;
    const ids = idxText.split(',').map(function(x){ return parseInt(x.trim(), 10) - 1; }).filter(function(i){ return !isNaN(i) && state.friends[i]; }).map(function(i){ return state.friends[i].id; });
    if (!ids.length) return alert('没有选中有效好友。');
    if (ids.length > 9) return alert('每个聊天室最多 10 人（含你自己）。');
    const title = (prompt('聊天室名称', '联机群聊') || '联机群聊').trim() || '联机群聊';
    const room = {
      id: olUid('room'),
      title: title,
      ownerId: state.profile.id,
      ownerName: state.profile.displayName,
      members: [state.profile.id].concat(ids),
      createdAt: olNow()
    };
    state.rooms.unshift(room);
    state.messages[room.id] = state.messages[room.id] || [];
    olSave(state);
    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_rooms').insert({
        id: room.id,
        title: room.title,
        owner_id: room.ownerId,
        owner_name: room.ownerName,
        members: room.members,
        created_at: room.createdAt
      });
      if (res.error) return alert('聊天室已创建到本地，但云端创建失败：' + res.error.message);
    }
    renderOnlineApp();
    olOpenRoom(room.id);
  }

  async function olDeleteRoom(roomId) {
    const state = olState();
    const room = state.rooms.find(function(r){ return String(r.id) === String(roomId); });
    if (!room) return;
    if (!confirm('确定要永久删除这个聊天室吗？聊天室本身和全部消息都会被删除。')) return;
    state.rooms = state.rooms.filter(function(r){ return String(r.id) !== String(roomId); });
    delete state.messages[roomId];
    if (state.roomResidents && typeof state.roomResidents === 'object') delete state.roomResidents[roomId];
    if (String(state.currentRoomId || '') === String(roomId)) {
      state.currentRoomId = null;
      try { olCloseRoom(); } catch(e) {}
    }
    olSave(state);
    const sb = olClient(state);
    if (sb) {
      const msgRes = await sb.from('mh_online_messages').delete().eq('room_id', roomId);
      if (msgRes.error) {
        await olSyncRemote(false);
        return alert('删除聊天室消息失败：' + msgRes.error.message);
      }
      const roomRes = await sb.from('mh_online_rooms').delete().eq('id', roomId);
      if (roomRes.error) {
        await olSyncRemote(false);
        return alert('删除聊天室失败：' + roomRes.error.message);
      }
    }
    renderOnlineApp();
    alert('聊天室已永久删除。');
  }

  async function olClearRoomMessages(roomId) {
    const state = olState();
    const room = state.rooms.find(function(r){ return String(r.id) === String(roomId); });
    if (!room) return;
    if (!confirm('确定要永久删除这个聊天室里的全部聊天记录吗？聊天室会保留。')) return;
    state.messages[roomId] = [];
    olSave(state);
    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_messages').delete().eq('room_id', roomId);
      if (res.error) {
        await olSyncRemote(false);
        return alert('清空聊天室消息失败：' + res.error.message);
      }
    }
    if (String(state.currentRoomId || '') === String(roomId) && document.getElementById('olRoomShell').style.display === 'flex') {
      olRenderRoom();
    }
    renderOnlineApp();
    alert('聊天室聊天记录已清空。');
  }

  async function olLoadRoomMessages(roomId) {
    const state = olState();
    const sb = olClient(state);
    if (!sb) return state.messages[roomId] || [];
    const res = await sb.from('mh_online_messages').select('*').eq('room_id', roomId).order('created_at', { ascending: true });
    if (res.error) throw res.error;
    const msgs = (res.data || []).map(function(m) {
      return {
        id: m.id,
        roomId: m.room_id,
        senderId: m.sender_id,
        senderName: m.sender_name,
        speakerType: m.speaker_type,
        speakerName: m.speaker_name,
        speakerAvatar: m.speaker_avatar || '',
        content: m.content || '',
        createdAt: m.created_at || 0
      };
    });
    state.messages[roomId] = msgs;
    olSave(state);
    return msgs;
  }

  function olOpenRoom(roomId) {
    const state = olState();
    state.currentRoomId = roomId;
    if (state.roomResidents && typeof state.roomResidents === 'object' && state.roomResidents[roomId]) {
      delete state.roomResidents[roomId];
    }
    olSave(state);
    document.getElementById('olRoomShell').style.display = 'flex';
    olRenderRoom();
    olRefreshCurrentRoom();
    olStartRoomTicker();
  }

  function olCloseRoom() {
    document.getElementById('olRoomShell').style.display = 'none';
    olCloseSheet(null, 'olResidentSheet');
    olStopRoomTicker();
  }

  async function olRefreshCurrentRoom() {
    const state = olState();
    const roomId = state.currentRoomId;
    if (!roomId) return;
    try {
      await olLoadRoomMessages(roomId);
      olRenderRoom();
    } catch (e) {
      console.warn('[online room refresh]', e);
    }
  }

  async function olSendMessage() {
    const state = olState();
    const roomId = state.currentRoomId;
    if (!roomId) return;
    const contentEl = document.getElementById('olRoomInput');
    const speakerEl = document.getElementById('olRoomSpeaker');
    const text = (contentEl.value || '').trim();
    if (!text) return;
    const rawSpeaker = speakerEl.value || 'user';
    let speakerType = 'user';
    let speakerName = state.profile.displayName;
    let speakerAvatar = '';
    if (rawSpeaker.indexOf('persona:') === 0) {
      const pid = rawSpeaker.slice('persona:'.length);
      const persona = olGetPersonasSafe().find(function(p){ return String(p.id) === String(pid); });
      if (persona) {
        speakerType = 'persona';
        speakerName = persona.name || '角色';
        speakerAvatar = persona.avatar || '';
      }
    }
    const msg = {
      id: olUid('msg'),
      roomId: roomId,
      senderId: state.profile.id,
      senderName: state.profile.displayName,
      speakerType: speakerType,
      speakerName: speakerName,
      speakerAvatar: speakerAvatar,
      content: text,
      createdAt: olNow()
    };
    state.messages[roomId] = state.messages[roomId] || [];
    state.messages[roomId].push(msg);
    olSave(state);
    contentEl.value = '';
    olRenderRoom();

    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_messages').insert({
        id: msg.id,
        room_id: msg.roomId,
        sender_id: msg.senderId,
        sender_name: msg.senderName,
        speaker_type: msg.speakerType,
        speaker_name: msg.speakerName,
        speaker_avatar: msg.speakerAvatar,
        content: msg.content,
        created_at: msg.createdAt
      });
      if (res.error) alert('消息已发到本地，但云端发送失败：' + res.error.message);
    }
    olMaybeTriggerResident回复(roomId, msg);
  }

  async function olPublishRedline(childId) {
    const state = olState();
    const child = olGetLocalChildProfile(childId) || olGetAdultChildren().find(function(c){ return String(c.id) === String(childId); });
    if (!child) return;
    if (!olCanStartRedline(child.loveStatus)) {
      return alert(child.name + ' 当前状态为「' + olStatusLabel(child.loveStatus) + '」，不能重复发布相亲 / 求婚。');
    }
    const 帖子 = {
      id: olUid('redline'),
      ownerId: state.profile.id,
      ownerName: state.profile.displayName,
      childId: child.id,
      childName: child.name,
      age: child.age,
      avatar: child.avatar || '',
      bio: (child.bio || '已成年，可相识、约会、求婚、结婚、生孩子。').slice(0, 240),
      status: child.loveStatus || 'single',
      createdAt: olNow()
    };
    state.redline帖子 = [帖子].concat(state.redline帖子.filter(function(p){ return String(p.childId) !== String(child.id) || String(p.ownerId) !== String(state.profile.id); }));
    olSave(state);
    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_redline_帖子s').upsert({
        id: 帖子.id,
        owner_id: 帖子.ownerId,
        owner_name: 帖子.ownerName,
        child_id: 帖子.childId,
        child_name: 帖子.childName,
        age: 帖子.age,
        avatar: 帖子.avatar,
        bio: 帖子.bio,
        status: 帖子.status,
        created_at: 帖子.createdAt
      });
      if (res.error) return alert('红线已存本地，但云端发布失败：' + res.error.message);
    }
    renderOnlineApp();
    alert('已发布到红线广场。');
  }

  async function olUnpublishRedline(帖子Id) {
    const state = olState();
    const 帖子 = state.redline帖子.find(function(p){ return String(p.id) === String(帖子Id); });
    if (!帖子) return;
    if (String(帖子.ownerId) !== String(state.profile.id)) return alert('只能撤回自己发布的红线卡。');
    if (!confirm('确定要撤回这张红线卡吗？撤回后好友将不会再在红线广场看到它。')) return;
    state.redline帖子 = state.redline帖子.filter(function(p){ return String(p.id) !== String(帖子.id); });
    olSave(state);
    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_redline_帖子s').delete().eq('id', 帖子.id);
      if (res.error) {
        await olSyncRemote(false);
        return alert('云端撤回失败：' + res.error.message);
      }
    }
    renderOnlineApp();
    alert('红线卡已撤回发布。');
  }

  function olFindMineRedlineCandidates(state) {
    return olGetAdultChildren().filter(function(c){
      return olCanStartRedline(c.loveStatus);
    }).map(function(c){
      const existing = (state.redline帖子 || []).find(function(p){
        return String(p.ownerId) === String(state.profile.id) && String(p.childId) === String(c.id);
      });
      const full = olGetLocalChildProfile(c.id) || c;
      return {
        childId: full.id || c.id,
        childName: full.name || c.name,
        age: full.age || c.age,
        avatar: full.avatar || '',
        bio: full.bio || '',
        appearance: full.appearance || '',
        personality: full.personality || '',
        gender: full.gender || '',
        personaId: full.personaId || c.personaId || '',
        personaName: full.personaName || c.personaName || '',
        personaSummary: full.personaSummary || '',
        ownerName: state.profile.displayName,
        parentUserName: full.parentUserName || olGetUserNameSafe(),
        parentPersonaName: full.parentPersonaName || full.personaName || '',
        familyLabel: full.familyLabel || '',
        loveStatus: full.loveStatus || 'single',
        fromPostId: existing ? existing.id : ''
      };
    });
  }

  function olChooseMyChildForInvite(state) {
    const candidates = olFindMineRedlineCandidates(state);
    if (!candidates.length) return null;
    if (candidates.length === 1) return candidates[0];
    const text = candidates.map(function(c, i) {
      return (i + 1) + '. ' + c.childName + '（' + olDescribeGender(c.gender) + '，' + c.age + '岁，' + (c.parentUserName || '用户') + ' 与 ' + (c.parentPersonaName || c.personaName || '角色') + ' 的孩子，状态：' + olStatusLabel(c.loveStatus || 'single') + '）';
    }).join('\n');
    const idx = parseInt((prompt('选择要发起邀请的孩子序号：\n\n' + text) || '').trim(), 10) - 1;
    if (isNaN(idx) || !candidates[idx]) return null;
    return candidates[idx];
  }

  async function olSendRedlineAction(帖子Id, type) {
    const state = olState();
    const 帖子 = state.redline帖子.find(function(p){ return String(p.id) === String(帖子Id); });
    if (!帖子) return;
    if (String(帖子.ownerId) === String(state.profile.id)) return alert('这是你自己的帖子。');

    const fromChild = olChooseMyChildForInvite(state);
    if (!fromChild) return alert('你还没有可用于邀请的成年孩子，或尚未选择。');
    if (!olCanStartRedline(fromChild.loveStatus)) {
      return alert(fromChild.childName + ' 当前状态为「' + olStatusLabel(fromChild.loveStatus || 'single') + '」，不能发起新的邀请。');
    }
    if (!olCanStartRedline(帖子.status)) {
      return alert(帖子.childName + ' 当前状态为「' + olStatusLabel(帖子.status || 'single') + '」，暂时不能接受新的邀请。');
    }

    const parsedTo = olParseChildId(帖子.childId) || {};
    const toPersona = olGetPersonasSafe().find(function(pp){ return String(pp.id) === String(parsedTo.personaId); });
    const payload = {
      v: 2,
      status: 'pending',
      type: type,
      fromUserId: state.profile.id,
      fromUserName: state.profile.displayName,
      toUserId: 帖子.ownerId,
      toUserName: 帖子.ownerName || '对方',
      fromPostId: fromChild.fromPostId || '',
      toPostId: 帖子.id,
      fromChildId: fromChild.childId,
      toChildId: 帖子.childId,
      fromChild: {
        childId: fromChild.childId,
        name: fromChild.childName,
        age: fromChild.age,
        gender: fromChild.gender || '',
        avatar: fromChild.avatar || '',
        bio: fromChild.bio || '',
        appearance: fromChild.appearance || '',
        personality: fromChild.personality || '',
        traits: fromChild.traits || [],
        interests: fromChild.interests || [],
        habits: fromChild.habits || [],
        personaId: fromChild.personaId || '',
        personaName: fromChild.personaName || '',
        ownerName: state.profile.displayName,
        parentUserName: fromChild.parentUserName || olGetUserNameSafe(),
        parentPersonaName: fromChild.parentPersonaName || fromChild.personaName || '',
        personaSummary: fromChild.personaSummary || '',
        familyLabel: fromChild.familyLabel || ''
      },
      toChild: {
        childId: 帖子.childId,
        name: 帖子.childName,
        age: 帖子.age,
        gender: 帖子.gender || '',
        avatar: 帖子.avatar || '',
        bio: 帖子.bio || '',
        appearance: 帖子.appearance || '',
        personality: 帖子.personality || '',
        personaId: parsedTo.personaId || '',
        personaName: toPersona ? (toPersona.name || '') : '',
        ownerName: 帖子.ownerName || '',
        parentUserName: 帖子.ownerName || '',
        parentPersonaName: toPersona ? (toPersona.name || '') : '',
        familyLabel: (帖子.ownerName || '某用户') + ' 的孩子'
      },
      message: type === 'proposal' ? '发起求婚邀请' : '发起约会邀请',
      createdAt: olNow()
    };

    const action = {
      id: olUid('act'),
      帖子Id: 帖子.id,
      fromUserId: state.profile.id,
      fromUserName: state.profile.displayName,
      toUserId: 帖子.ownerId,
      type: type,
      meta: payload,
      note: olPackNote(payload),
      status: 'pending',
      createdAt: olNow()
    };

    state.redlineActions.unshift(action);
    olSave(state);

    const sb = olClient(state);
    if (sb) {
      const res = await sb.from('mh_online_redline_actions').insert({
        id: action.id,
        帖子_id: action.帖子Id,
        from_user_id: action.fromUserId,
        from_user_name: action.fromUserName,
        to_user_id: action.toUserId,
        type: action.type,
        note: action.note,
        created_at: action.createdAt
      });
      if (res.error) return alert('邀请已存本地，但云端发送失败：' + res.error.message);
    }
    renderOnlineApp();
    alert(type === 'proposal' ? '求婚邀请已发出，等待对方在邀请收件箱处理。' : '约会邀请已发出，等待对方在邀请收件箱处理。');
  }

  async function olRespondRedlineAction(actionId, decision) {
    const state = olState();
    const action = (state.redlineActions || []).find(function(a){ return String(a.id) === String(actionId); });
    if (!action) return;
    if (decision !== 'accepted' && decision !== 'rejected') return;

    const meta = Object.assign({}, action.meta || {}, { status: decision, respondedAt: olNow() });
    action.status = decision;
    action.meta = meta;
    action.note = olPackNote(meta);

    const myChildId = String(String(action.toUserId) === String(state.profile.id) ? (meta.toChildId || '') : (meta.fromChildId || ''));
    const myChildNow = olGetLocalChildProfile(myChildId);
    if (decision === 'accepted') {
      if (!myChildNow) return alert('当前本地找不到该成年孩子，无法处理邀请。');
      if (!olCanStartRedline(myChildNow.loveStatus)) {
        return alert('该成年孩子当前状态为「' + olStatusLabel(myChildNow.loveStatus) + '」，不能同时接受新的相亲 / 求婚邀请。');
      }
    }

    const sb = olClient(state);
    try {
      if (sb) {
        const up = await sb.from('mh_online_redline_actions').update({ note: action.note }).eq('id', action.id);
        if (up.error) throw up.error;
      }

      if (decision === 'accepted') {
        olApplyAcceptedRedlineActionLocal(state, action, false);
        try {
          const pair = [String(action.fromUserId), String(action.toUserId)].sort();
          const linkId = pair.join('__');
          if (sb) {
            await sb.from('mh_online_friend_links').upsert({ id: linkId, user_a: pair[0], user_b: pair[1], created_at: olNow() });
            const localState = olState();
            const localMeta = action.meta || {};
            const localMyChildId = String(String(action.fromUserId) === String(localState.profile.id) ? (localMeta.fromChildId || '') : (localMeta.toChildId || ''));
            const parsed = olParseChildId(localMyChildId);
            if (parsed) {
              await olSyncLoveStateForBaby(parsed.personaId, parsed.babyIdx);
            }
          }
        } catch(e) {
          console.warn('[redline accept ensure link]', e);
        }
      }

      olSave(state);
      await olSyncRemote(false);
      renderOnlineApp();
      if (decision === 'rejected') alert('已拒绝该邀请。');
    } catch (e) {
      alert('处理邀请失败：' + (e.message || '未知错误'));
    }
  }

  function olSwitchTab(tab) {
    const state = olState();
    state.activeTab = tab;
    olSave(state);
    renderOnlineApp();
  }

  function olOpenSheet(id) {
    const el = document.getElementById(id);
    if (el) el.style.display = 'flex';
  }

  function olCloseSheet(e, id) {
    if (e && e.target && e.target.id !== id) return;
    const el = document.getElementById(id);
    if (el) el.style.display = 'none';
  }

  function olRenderBars(state) {
    const tabHtml = OL_TABS.map(function(t) {
      const cls = state.activeTab === t.key ? 'online-tab-btn active' : 'online-tab-btn';
      return '<button class="' + cls + '" onclick="olSwitchTab(\'' + t.key + '\')"><i class="fas ' + t.icon + '" style="margin-right:6px;"></i>' + t.label + '</button>';
    }).join('');
    const bottomHtml = OL_TABS.slice(0, 5).map(function(t) {
      const cls = state.activeTab === t.key ? 'online-bottom-btn active' : 'online-bottom-btn';
      return '<div class="' + cls + '" onclick="olSwitchTab(\'' + t.key + '\')"><strong><i class="fas ' + t.icon + '"></i></strong>' + t.label + '</div>';
    }).join('');
    document.getElementById('olTabBar').innerHTML = tabHtml;
    document.getElementById('olBottomNav').innerHTML = bottomHtml;
  }

  function olRenderHome(state) {
    const remote = !!olClient(state);
    const adultChildren = olGetAdultChildren();
    const cards = state.sharedCards.filter(function(c){ return String(c.ownerId) === String(state.profile.id); });
    const pendingReqCount = state.friend请求Inbox.length;
    const pendingInviteCount = state.redlineActions.filter(function(a){ return String(a.toUserId) === String(state.profile.id) && a.status === 'pending'; }).length;

    document.getElementById('olPanelHome').innerHTML =
      '<div class="online-hero-card">'
      + '<div class="online-hero-top"><div><div class="online-hero-name">' + olEsc(state.profile.displayName) + '</div><div class="online-hero-meta">已支持自动刷新：好友申请、聊天室消息、红线邀请会定时同步。<br>当前模式：' + (remote ? 'Supabase 真联机' : '本地演示模式') + '</div></div><div class="online-status-pill ' + (remote ? 'ok' : 'warn') + '">' + (remote ? '已连云端' : '待接云端') + '</div></div>'
      + '<div class="online-hero-stats">'
      + '<div class="online-stat"><div class="online-stat-val">' + state.friends.length + '</div><div class="online-stat-label">好友</div></div>'
      + '<div class="online-stat"><div class="online-stat-val">' + pendingReqCount + '</div><div class="online-stat-label">待处理申请</div></div>'
      + '<div class="online-stat"><div class="online-stat-val">' + pendingInviteCount + '</div><div class="online-stat-label">红线邀请</div></div>'
      + '<div class="online-stat"><div class="online-stat-val">' + cards.length + '</div><div class="online-stat-label">已分享角色</div></div>'
      + '<div class="online-stat"><div class="online-stat-val">' + adultChildren.length + '</div><div class="online-stat-label">18+ 孩子</div></div>'
      + '</div>'
      + '<div class="online-code-row"><div class="online-code-box"><div class="online-code-label">当前邀请码</div><div class="online-code-val">' + olEsc(state.profile.inviteCode) + '</div></div>'
      + '<button class="online-mini-btn" onclick="olManualInvite()">手动刷新码</button>'
      + '<button class="online-mini-btn" onclick="olAddFriendByCode()">发申请</button></div>'
      + '<div class="online-chip-wrap"><button class="online-chip-btn" onclick="olSwitchTab(\'friends\')">看好友申请</button><button class="online-chip-btn" onclick="olCreateRoom()">创建聊天室</button><button class="online-chip-btn" onclick="olSwitchTab(\'redline\')">处理红线邀请</button><button class="online-chip-btn" onclick="olSyncRemote(true)">立即同步</button></div>'
      + '</div>'
      + '<div class="online-card"><div class="online-card-title">联机说明</div><div class="online-card-desc">现在是申请制好友：A 发申请后，B 会在联机-好友页看到申请并可接受/拒绝；接受后双方自动互为好友。红线约会 / 求婚邀请会先选择具体的成年孩子，接受后不会进入联机聊天室，而是直接同步到双方家庭软件的恋爱观察室，并继续同步聊天、生孩子、分手 / 离婚等状态。</div></div>';
  }

  function olRenderFriends(state) {
    const reqInbox = state.friend请求Inbox.map(function(r) {
      return '<div class="online-list-item"><div class="online-item-top"><div><div class="online-item-name">' + olEsc(r.fromUserName || '好友') + '</div><div class="online-item-sub">申请于 ' + olShortTime(r.createdAt) + '</div></div><span class="online-status-pill warn">待处理</span></div><div class="online-item-actions"><button class="online-mini-btn" onclick="olHandleFriendRequest(\'' + olEsc(r.id) + '\',\'accepted\')">接受</button><button class="online-mini-btn" onclick="olHandleFriendRequest(\'' + olEsc(r.id) + '\',\'rejected\')">拒绝</button></div></div>';
    }).join('') || '<div class="online-empty">暂无新的好友申请。</div>';

    const reqOut = state.friend请求Outbox.map(function(r) {
      return '<div class="online-list-item"><div class="online-item-top"><div><div class="online-item-name">发给 ' + olEsc(r.toUserName || '好友') + '</div><div class="online-item-sub">' + olShortTime(r.createdAt) + '</div></div><span class="online-status-pill">等待中</span></div></div>';
    }).join('') || '<div class="online-empty">你还没有发出中的申请。</div>';

    const items = state.friends.length ? state.friends.map(function(f) {
      return '<div class="online-list-item"><div class="online-item-top"><div class="online-flex-row"><div class="online-avatar">' + (f.avatar ? '<img src="' + olEsc(f.avatar) + '">' : '<i class="fas fa-user"></i>') + '</div><div><div class="online-item-name">' + olEsc(f.name) + '</div><div class="online-item-sub">' + (f.online ? '在线中' : '最近在线 ' + olShortTime(f.updatedAt || 0)) + '</div></div></div><span class="online-status-pill ' + (f.online ? 'ok' : '') + '">' + (f.online ? 'online' : 'idle') + '</span></div><div class="online-badges"><span class="online-badge">邀请码 ' + olEsc(f.inviteCode || '------') + '</span></div><div class="online-item-actions"><button class="online-mini-btn" onclick="olCreateRoom()">拉进聊天室</button><button class="online-mini-btn" onclick="olSwitchTab(\'personas\')">看角色卡</button><button class="online-mini-btn" onclick="olDeleteFriend(\'' + olEsc(f.id) + '\')">删除好友</button></div></div>';
    }).join('') : '<div class="online-empty">还没有好友。先输入邀请码发申请。</div>';

    document.getElementById('olPanelFriends').innerHTML =
      '<div class="online-card"><div class="online-card-title">好友系统</div><div class="online-card-desc">输入邀请码后会先发申请；对方接受后才会互加为好友。</div><div class="online-code-row"><div class="online-code-box"><div class="online-code-label">我的邀请码</div><div class="online-code-val">' + olEsc(state.profile.inviteCode) + '</div></div><button class="online-mini-btn" onclick="olAddFriendByCode()">输入邀请码</button></div></div>'
      + '<div class="online-card"><div class="online-card-title">好友申请（收件箱）</div><div class="online-list">' + reqInbox + '</div></div>'
      + '<div class="online-card"><div class="online-card-title">我发出的申请</div><div class="online-list">' + reqOut + '</div></div>'
      + '<div class="online-card"><div class="online-card-title">好友列表</div><div class="online-list">' + items + '</div></div>';
  }

  function olRenderPersonas(state) {
    const myCards = olGetPersonasSafe().map(function(p) {
      const sharedCard = state.sharedCards.find(function(c){ return String(c.ownerId) === String(state.profile.id) && String(c.personaId) === String(p.id); });
      const shared = !!sharedCard;
      return '<div class="online-list-item"><div class="online-item-top"><div class="online-flex-row"><div class="online-avatar">' + (p.avatar ? '<img src="' + olEsc(p.avatar) + '">' : '<i class="fas fa-user-astronaut"></i>') + '</div><div><div class="online-item-name">' + olEsc(p.name || '未命名角色') + '</div><div class="online-item-sub">' + olEsc((p.persona || p.appearance || '暂无设定').slice(0, 80)) + '</div></div></div><span class="online-status-pill ' + (shared ? 'ok' : '') + '">' + (shared ? '已分享' : '未分享') + '</span></div><div class="online-item-actions"><button class="online-mini-btn" onclick="olPublishPersona(\'' + olEsc(p.id) + '\')">' + (shared ? '重新发布' : '发布到云端') + '</button>' + (sharedCard ? '<button class="online-mini-btn" onclick="olUnpublishPersona(\'' + olEsc(sharedCard.id) + '\')">撤回发布</button>' : '') + '</div></div>';
    }).join('') || '<div class="online-empty">本地还没有角色，先去角色系统创建角色吧。</div>';

    const friendCards = state.sharedCards.filter(function(c){ return String(c.ownerId) !== String(state.profile.id); }).map(function(c) {
      return '<div class="online-list-item"><div class="online-item-top"><div class="online-flex-row"><div class="online-avatar">' + (c.avatar ? '<img src="' + olEsc(c.avatar) + '">' : '<i class="fas fa-id-badge"></i>') + '</div><div><div class="online-item-name">' + olEsc(c.name) + '</div><div class="online-item-sub">来自 ' + olEsc(c.ownerName || '好友') + '</div></div></div><span class="online-status-pill">角色卡</span></div><div class="online-badges"><span class="online-badge">' + olEsc((c.summary || c.appearance || '暂无描述').slice(0, 120)) + '</span></div><div class="online-item-actions"><button class="online-mini-btn" onclick="olImportCard(\'' + olEsc(c.id) + '\')">加入联络人</button></div></div>';
    }).join('') || '<div class="online-empty">好友还没有分享角色卡。</div>';

    document.getElementById('olPanelPersonas').innerHTML =
      '<div class="online-card"><div class="online-card-title">我的角色卡</div><div class="online-card-desc">发布后只同步角色设定，不包含聊天记录。</div><div class="online-list">' + myCards + '</div></div>'
      + '<div class="online-card"><div class="online-card-title">好友分享区</div><div class="online-list">' + friendCards + '</div></div>';
  }

  function olRenderRooms(state) {
    const items = state.rooms.map(function(r) {
      const msgs = state.messages[r.id] || [];
      const last = msgs[msgs.length - 1];
      return '<div class="online-list-item"><div class="online-item-top"><div><div class="online-item-name">' + olEsc(r.title) + '</div><div class="online-item-sub">' + r.members.length + ' 人 · ' + (last ? olEsc((last.speakerName || last.senderName) + '：' + last.content.slice(0, 22)) : '还没有消息') + '</div></div><span class="online-status-pill">room</span></div><div class="online-item-actions"><button class="online-mini-btn" onclick="olOpenRoom(\'' + olEsc(r.id) + '\')">进入聊天室</button><button class="online-mini-btn" onclick="olClearRoomMessages(\'' + olEsc(r.id) + '\')">清空聊天</button><button class="online-mini-btn" onclick="olDeleteRoom(\'' + olEsc(r.id) + '\')">删除聊天室</button></div></div>';
    }).join('') || '<div class="online-empty">还没有聊天室。添加好友后可自动有私聊房间。</div>';

    document.getElementById('olPanelRooms').innerHTML =
      '<div class="online-card"><div class="online-card-title">实时聊天室</div><div class="online-card-desc">自动轮询刷新已开启，进入房间后会定时更新消息。</div><div class="online-item-actions"><button class="online-mini-btn" onclick="olCreateRoom()">创建聊天室</button><button class="online-mini-btn" onclick="olSyncRemote(true)">同步房间</button></div></div>'
      + '<div class="online-card"><div class="online-card-title">我的聊天室</div><div class="online-list">' + items + '</div></div>';
  }

  function olRenderRedline(state) {
    const myUid = String(state.profile.id);
    const inbox = state.redlineActions.filter(function(a){ return String(a.toUserId) === myUid && a.status === 'pending'; }).map(function(a) {
      const label = a.type === 'proposal' ? '求婚邀请' : '约会邀请';
      const who = a.meta && a.meta.fromChild ? a.meta.fromChild.name : (a.fromUserName || '对方');
      const mine = a.meta && a.meta.toChild ? a.meta.toChild.name : '你的孩子';
      const fromGender = a.meta && a.meta.fromChild ? olDescribeGender(a.meta.fromChild.gender) : '未注明';
      const mineGender = a.meta && a.meta.toChild ? olDescribeGender(a.meta.toChild.gender) : '未注明';
      const fromParents = a.meta && a.meta.fromChild ? ((a.meta.fromChild.parentUserName || a.fromUserName || '某用户') + ' 与 ' + (a.meta.fromChild.parentPersonaName || a.meta.fromChild.personaName || '某角色')) : (a.fromUserName || '某用户');
      const mineParents = a.meta && a.meta.toChild ? ((a.meta.toChild.parentUserName || state.profile.displayName) + ' 与 ' + (a.meta.toChild.parentPersonaName || a.meta.toChild.personaName || '某角色')) : '你的家庭';
      return '<div class="online-list-item"><div class="online-item-top"><div><div class="online-item-name">' + olEsc(label) + ' · 来自 ' + olEsc(a.fromUserName || '未知用户') + '</div><div class="online-item-sub">' + olEsc((who || 'TA') + '（' + fromGender + '） → ' + (mine || '') + '（' + mineGender + '）') + ' · ' + olShortTime(a.createdAt) + '</div></div><span class="online-status-pill warn">待处理</span></div><div class="online-badges"><span class="online-badge">' + olEsc(fromParents + ' 的孩子') + '</span><span class="online-badge">' + olEsc(mineParents + ' 的孩子') + '</span></div><div class="online-item-actions"><button class="online-mini-btn" onclick="olShowActionChildProfile(\'' + olEsc(a.id) + '\',\'from\')">查看对方孩子</button><button class="online-mini-btn" onclick="olShowActionChildProfile(\'' + olEsc(a.id) + '\',\'to\')">查看我方孩子</button><button class="online-mini-btn" onclick="olRespondRedlineAction(\'' + olEsc(a.id) + '\',\'accepted\')">接受</button><button class="online-mini-btn" onclick="olRespondRedlineAction(\'' + olEsc(a.id) + '\',\'rejected\')">拒绝</button></div></div>';
    }).join('') || '<div class="online-empty">暂无待处理邀请。</div>';

    const mine = olGetAdultChildren().map(function(c) {
      const full = olGetLocalChildProfile(c.id) || c;
      const disabled = olCanStartRedline(full.loveStatus) ? '' : ' style="opacity:0.55;cursor:not-allowed;" disabled';
      const myPost = (state.redline帖子 || []).find(function(p){ return String(p.ownerId) === String(state.profile.id) && String(p.childId) === String(full.id); });
      return '<div class="online-list-item"><div class="online-item-top"><div class="online-flex-row"><div class="online-avatar">' + (full.avatar ? '<img src="' + olEsc(full.avatar) + '">' : '<i class="fas fa-heart"></i>') + '</div><div><div class="online-item-name">' + olEsc(full.name) + '</div><div class="online-item-sub">' + full.age + ' 岁 · ' + olEsc(olDescribeGender(full.gender)) + ' · ' + olEsc(full.familyLabel || (full.personaName + ' 的孩子')) + '</div></div></div><span class="online-status-pill">' + (myPost ? '已发布' : olEsc(olStatusLabel(full.loveStatus || 'single'))) + '</span></div><div class="online-badges"><span class="online-badge">已生孩子 ' + full.childCount + ' 位</span><span class="online-badge">' + olEsc((full.bio || '暂无简介').slice(0, 90)) + '</span></div><div class="online-item-actions"><button class="online-mini-btn" onclick="olShowLocalChildProfile(\'' + olEsc(full.id) + '\')">查看资料</button><button class="online-mini-btn" onclick="olPublishRedline(\'' + olEsc(full.id) + '\')"'+ disabled + '>' + (myPost ? '重新发布' : '发布到广场') + '</button>' + (myPost ? '<button class="online-mini-btn" onclick="olUnpublishRedline(\'' + olEsc(myPost.id) + '\')">撤回发布</button>' : '') + '</div></div>';
    }).join('') || '<div class="online-empty">宝宝系统里还没有满 18 岁的孩子。</div>';

    const plaza = state.redline帖子.filter(function(p){ return String(p.ownerId) !== myUid; }).map(function(p) {
      const disabled = olCanStartRedline(p.status) ? '' : ' style="opacity:0.55;cursor:not-allowed;" disabled';
      return '<div class="online-list-item"><div class="online-item-top"><div class="online-flex-row"><div class="online-avatar">' + (p.avatar ? '<img src="' + olEsc(p.avatar) + '">' : '<i class="fas fa-ring"></i>') + '</div><div><div class="online-item-name">' + olEsc(p.childName) + '</div><div class="online-item-sub">' + p.age + ' 岁 · 来自 ' + olEsc((p.ownerName || '未知用户') + ' 的成年孩子') + '</div></div></div><span class="online-status-pill">' + olEsc(olStatusLabel(p.status || 'single')) + '</span></div><div class="online-badges"><span class="online-badge">' + olEsc((p.bio || '暂无简介').slice(0, 120)) + '</span></div><div class="online-item-actions"><button class="online-mini-btn" onclick="olShowPostChildProfile(\'' + olEsc(p.id) + '\')">查看人设</button><button class="online-mini-btn" onclick="olSendRedlineAction(\'' + olEsc(p.id) + '\', \'date\')"'+ disabled + '>约会邀请</button><button class="online-mini-btn" onclick="olSendRedlineAction(\'' + olEsc(p.id) + '\', \'proposal\')"'+ disabled + '>求婚邀请</button></div></div>';
    }).join('') || '<div class="online-empty">广场暂时还没有其他人发布。</div>';

    const processed = state.redlineActions.filter(function(a){ return a.status !== 'pending'; }).slice(0, 8).map(function(a){
      const st = a.status === 'accepted' ? '已接受' : '已拒绝';
      const peer = String(a.toUserId) === myUid ? (a.fromUserName || '对方') : ((a.meta && a.meta.toUserName) || '对方');
      const fromNm = a.meta && a.meta.fromChild ? a.meta.fromChild.name : '对方孩子';
      const toNm = a.meta && a.meta.toChild ? a.meta.toChild.name : '我方孩子';
      return '<div class="online-list-item"><div class="online-item-top"><div><div class="online-item-name">' + olEsc(peer) + ' · ' + (a.type === 'proposal' ? '求婚' : '约会') + '</div><div class="online-item-sub">' + olEsc(fromNm + ' → ' + toNm) + ' · ' + olShortTime(a.createdAt) + '</div></div><span class="online-status-pill ' + (a.status === 'accepted' ? 'ok' : '') + '">' + st + '</span></div></div>';
    }).join('') || '<div class="online-empty">暂无历史处理记录。</div>';

    document.getElementById('olPanelRedline').innerHTML =
      '<div class="online-card"><div class="online-card-title">邀请收件箱</div><div class="online-card-desc">你收到的约会 / 求婚邀请会出现在这里。邀请不是以用户本人名义发起，而是由具体的成年孩子发起；接受后会直接写入双方家庭软件的恋爱观察室。</div><div class="online-list">' + inbox + '</div></div>'
      + '<div class="online-card"><div class="online-card-title">我的可发布对象</div><div class="online-list">' + mine + '</div></div>'
      + '<div class="online-card"><div class="online-card-title">红线广场</div><div class="online-list">' + plaza + '</div></div>'
      + '<div class="online-card"><div class="online-card-title">邀请处理记录</div><div class="online-list">' + processed + '</div></div>';
  }

  function olRenderSettings(state) {
    const remote = !!olClient(state);
    const hasConfig = !!(state.backend.supabaseUrl && state.backend.supabaseAnonKey);
    const statusColor = remote ? '#22c55e' : (hasConfig ? '#f59e0b' : '#ef4444');
    const statusText = remote ? '✅ 已连接 Supabase，可跨手机联机' : (hasConfig ? '⚠️ 已填写信息，请点击测试连接' : '❌ 未配置，请填写下方信息');

    document.getElementById('olPanelSettings').innerHTML =
      /* ── 新手教程入口 ── */
      '<div class="ol-tutorial-banner" onclick="olOpenTutorial()">'
      + '<div class="ol-tutorial-banner-left">'
      + '<div class="ol-tutorial-banner-icon">🚀</div>'
      + '<div>'
      + '<div class="ol-tutorial-banner-title">新手教程</div>'
      + '<div class="ol-tutorial-banner-sub">第一次连接？点这里，5 分钟搞定云端配置</div>'
      + '</div>'
      + '</div>'
      + '<div class="ol-tutorial-banner-arrow"><i class="fas fa-chevron-right"></i></div>'
      + '</div>'
      /* ── 当前状态卡片 ── */
      + '<div class="online-card" style="border-left:3px solid ' + statusColor + ';margin-bottom:12px;">'
      + '<div class="online-card-title">当前状态</div>'
      + '<div class="online-card-desc" style="font-weight:600;color:' + statusColor + ';">' + statusText + '</div>'
      + '<div class="online-card-desc" style="margin-top:4px;">上次同步：' + (state.lastSyncAt ? olShortTime(state.lastSyncAt) : '尚未同步') + '</div>'
      + '</div>'
      + '<div class="online-card"><div class="online-card-title">Supabase 联机配置</div>'
      + '<div class="online-card-desc">本版本新增了好友申请与恋爱观察室同步表，请复制下方 SQL 执行一次升级。</div>'
      + '<div style="margin-top:10px;"><div class="online-tiny" style="margin-bottom:6px;">显示名称</div><input class="online-field" id="olDisplayName" value="' + olEsc(state.profile.displayName) + '" placeholder="你的联机昵称"></div>'
      + '<div style="margin-top:10px;"><div class="online-tiny" style="margin-bottom:6px;">Supabase URL</div><input class="online-field" id="olSbUrl" value="' + olEsc(state.backend.supabaseUrl || '') + '" placeholder="https://xxxxxxxxxxxx.supabase.co"></div>'
      + '<div style="margin-top:10px;"><div class="online-tiny" style="margin-bottom:6px;">Supabase anon key</div><textarea class="online-textarea" id="olSbKey" placeholder="粘贴 anon key">' + olEsc(state.backend.supabaseAnonKey || '') + '</textarea></div>'
      + '<input type="hidden" id="olBackendMode" value="supabase">'
      + '<div class="online-item-actions" style="margin-top:12px;">'
      + '<button class="online-mini-btn" style="background:#1a1a1a;color:#fff;" onclick="olSaveSettings()">保存设置</button>'
      + '<button class="online-mini-btn" onclick="olSyncRemote(true)">测试连接</button>'
      + '<button class="online-mini-btn" onclick="olCopySql()">复制建表 SQL</button>'
      + '</div>'
      + '<div class="online-setting-code" id="olSqlBlock">' + olEsc(OL_SQL) + '</div></div>';
  }

  /* ═══════════════════════════════════════════════
     新手教程弹窗
  ═══════════════════════════════════════════════ */
