async function csCallChatApi(prompt, maxTokens) {
  if (!apiConfig || !apiConfig.url || !apiConfig.key || !apiConfig.model) {
    throw new Error('请先在 API Config 里配置并保存聊天 API。');
  }
  var endpoint = String(apiConfig.url || '').replace(/\/+$/, '');
  if (!/\/chat\/completions$/i.test(endpoint)) endpoint += '/chat/completions';
  var resp = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Authorization': 'Bearer ' + apiConfig.key,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(_applyApiModel({
      messages: [{ role: 'user', content: prompt }],
      temperature: 0.85,
      max_tokens: maxTokens || 1400
    }, apiConfig.model))
  });
  if (!resp.ok) {
    var errText = await resp.text().catch(function(){ return ''; });
    throw new Error('API 请求失败：' + resp.status + ' ' + errText.slice(0, 160));
  }
  var data = await resp.json();
  var text = typeof _extractAssistantMessageContent === 'function'
    ? _extractAssistantMessageContent(data)
    : (((data || {}).choices || [])[0] || {}).message?.content || '';
  return String(text || '').trim();
}
function csExtractJsonArray(text) {
  var raw = String(text || '').trim();
  if (!raw) return [];
  var fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) raw = fenced[1].trim();
  try {
    var parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch(e) {}
  var start = raw.indexOf('[');
  var end = raw.lastIndexOf(']');
  if (start >= 0 && end > start) {
    try {
      var partial = JSON.parse(raw.slice(start, end + 1));
      return Array.isArray(partial) ? partial : [];
    } catch(e2) {}
  }
  return [];
}
function csExtractJsonObject(text) {
  var raw = String(text || '').trim();
  if (!raw) return {};
  var fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) raw = fenced[1].trim();
  try {
    var parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch(e) {}
  var start = raw.indexOf('{');
  var end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try {
      var partial = JSON.parse(raw.slice(start, end + 1));
      return partial && typeof partial === 'object' && !Array.isArray(partial) ? partial : {};
    } catch(e2) {}
  }
  return {};
}
async function csTryGenerateImage(prompt) {
  if (!apiConfig || !apiConfig.url || !apiConfig.key || !apiConfig.model) return '';
  var endpoints = csGetApiBases().map(function(base) {
    return String(base).replace(/\/+$/, '') + '/images/generations';
  });
  for (var i = 0; i < endpoints.length; i++) {
    try {
      var resp = await fetch(endpoints[i], {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + apiConfig.key,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: apiConfig.model,
          prompt: prompt,
          n: 1,
          size: '1024x1024',
          response_format: 'b64_json'
        })
      });
      if (!resp.ok) continue;
      var data = await resp.json();
      var item = data && data.data && data.data[0] ? data.data[0] : null;
      if (!item) continue;
      if (item.b64_json) return 'data:image/png;base64,' + item.b64_json;
      if (item.url) return item.url;
    } catch(err) {}
  }
  return '';
}
