function csApplyScaleToInner(widget, inner, baseW, baseH) {
  if (!widget || !inner) return;
  var w = widget.offsetWidth || baseW;
  var h = widget.offsetHeight || baseH;
  var scale = Math.min(w / baseW, h / baseH);
  var tx = Math.max(0, (w - baseW * scale) / 2);
  var ty = Math.max(0, (h - baseH * scale) / 2);
  inner.style.transform = 'translate(' + tx + 'px,' + ty + 'px) scale(' + scale + ')';
}
function csEnsurePlacedHomeWidget(id) {
  var el = document.getElementById(id);
  if (!el || el.style.display === 'none' || el.classList.contains('iph-placed')) {
    if (el && !el.dataset.dragId) el.dataset.dragId = id;
    return;
  }
  var parent = el.parentElement;
  if (!parent) return;
  var er = el.getBoundingClientRect();
  var pr = parent.getBoundingClientRect();
  var w = er.width || el.offsetWidth || 152;
  var h = er.height || el.offsetHeight || 152;
  var x = Math.max(0, er.left - pr.left);
  var y = Math.max(0, er.top - pr.top + (parent.scrollTop || 0));
  if (id === 'coupleSpaceWidget' && parent.id === 'homePage3') {
    x = 16;
    y = 16;
    w = 152;
    h = 152;
  }
  el.dataset.dragId = id;
  el.classList.add('iph-placed');
  el.style.position = 'absolute';
  el.style.left = x + 'px';
  el.style.top = y + 'px';
  el.style.width = w + 'px';
  el.style.height = h + 'px';
  el.style.margin = '0';
  el.style.flexShrink = '0';
  try {
    var pos = JSON.parse(localStorage.getItem('mono_iph_positions_v3') || '{}');
    if (!pos[id]) {
      pos[id] = { x: x, y: y, w: w, h: h, parentId: parent.id || 'homePage1' };
      localStorage.setItem('mono_iph_positions_v3', JSON.stringify(pos));
    }
  } catch(e) {}
  setTimeout(function() {
    if (typeof window._iphInjectResizeHandles === 'function') window._iphInjectResizeHandles();
  }, 40);
}
function renderCoupleSpaceWidget() {
  var widget = document.getElementById('coupleSpaceWidget');
  if (!widget) return;
  csEnsurePlacedHomeWidget('coupleSpaceWidget');
  var bg = document.getElementById('coupleSpaceWidgetBg');
  var inner = document.getElementById('coupleSpaceWidgetInner');
  var nameEl = document.getElementById('csWidgetAnnivName');
  var dayEl = document.getElementById('csWidgetDays');
  var dateEl = document.getElementById('csWidgetAnnivDate');
  var namesEl = document.getElementById('csWidgetNames');
  var captionEl = document.getElementById('csWidgetCaption');
  var persona = csGetActivePersona();
  var profile = csGetActiveProfile();
  if (!persona || !profile) {
    widget.classList.remove('has-custom-bg');
    if (bg) bg.style.backgroundImage = '';
    if (dayEl) dayEl.textContent = 'D-0';
    if (nameEl) nameEl.textContent = '选择纪念日';
    if (dateEl) dateEl.textContent = '在情侣空间里设定';
    if (namesEl) namesEl.textContent = '你 · TA';
    if (captionEl) captionEl.textContent = '点击进入情侣空间';
    csApplyScaleToInner(widget, inner, 152, 152);
    renderCoupleCalendarWidgets();
    return;
  }
  var ann = csGetDisplayAnniversary(profile);
  var info = ann ? csCountdownInfo(ann.date) : { label:'D-0', nextLabel:'未设定' };
  if (profile.widgetBackground) {
    widget.classList.add('has-custom-bg');
    if (bg) bg.style.backgroundImage = 'url("' + profile.widgetBackground + '")';
  } else {
    widget.classList.remove('has-custom-bg');
    if (bg) bg.style.backgroundImage = '';
  }
  if (dayEl) dayEl.textContent = info.label;
  if (nameEl) nameEl.textContent = ann ? ann.name : '选择纪念日';
  if (dateEl) dateEl.textContent = info.nextLabel;
  var userIdentity = csGetUserIdentityForPersona(persona);
  if (namesEl) namesEl.textContent = ((userIdentity && userIdentity.name) || '你') + ' · ' + csPersonaDisplayName(persona);
  if (captionEl) captionEl.textContent = profile.coupleNickname || (profile.duoSignature || '点击进入情侣空间');
  csApplyScaleToInner(widget, inner, 152, 152);
  renderCoupleCalendarWidgets();
}
function csMoodIconNode(mood, cls, title) {
  if (!mood) return '<span class="cs-mood-empty-box ' + cls + '" title="' + csEsc(title || '') + '"></span>';
  return '<span class="cs-mood-icon-box ' + cls + '" title="' + csEsc(title || mood.label) + '">' + csMoodSpriteNode(mood.id || mood.icon, 'cs-mood-sprite', mood.label) + '</span>';
}
function csGetMoodCalendarData(profile, monthOffset) {
  var base = new Date();
  base = new Date(base.getFullYear(), base.getMonth() + (monthOffset || 0), 1);
  var first = new Date(base.getFullYear(), base.getMonth(), 1);
  var offset = (first.getDay() + 6) % 7;
  var start = new Date(base.getFullYear(), base.getMonth(), 1 - offset);
  var days = [];
  for (var i = 0; i < 42; i++) {
    var cur = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
    var ymd = cur.getFullYear() + '-' + String(cur.getMonth()+1).padStart(2, '0') + '-' + String(cur.getDate()).padStart(2, '0');
    var entry = profile.moodMap[ymd] || {};
    days.push({
      day: cur.getDate(),
      ymd: ymd,
      userMood: entry.user ? csMoodById(entry.user) : null,
      charMood: entry.char ? csMoodById(entry.char) : null,
      inMonth: cur.getMonth() === base.getMonth(),
      isToday: ymd === csTodayStr()
    });
  }
  return {
    monthLabel: (base.getMonth() + 1) + '月',
    yearLabel: base.getFullYear() + '年',
    days: days
  };
}
function csGetCurrentWeekMoodData(profile) {
  var now = new Date();
  var weekStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - ((now.getDay() + 6) % 7));
  var days = [];
  var weekEnd = null;
  for (var i = 0; i < 7; i++) {
    var cur = new Date(weekStart.getFullYear(), weekStart.getMonth(), weekStart.getDate() + i);
    var ymd = cur.getFullYear() + '-' + String(cur.getMonth()+1).padStart(2, '0') + '-' + String(cur.getDate()).padStart(2, '0');
    var entry = (profile && profile.moodMap && profile.moodMap[ymd]) || {};
    weekEnd = cur;
    days.push({
      day: cur.getDate(),
      ymd: ymd,
      userMood: entry.user ? csMoodById(entry.user) : null,
      charMood: entry.char ? csMoodById(entry.char) : null,
      inMonth: true,
      isToday: ymd === csTodayStr()
    });
  }
  return {
    monthLabel: '本周',
    yearLabel: weekStart.getFullYear() + '年 ' + (weekStart.getMonth() + 1) + '/' + weekStart.getDate() + ' - ' + (weekEnd.getMonth() + 1) + '/' + weekEnd.getDate(),
    days: days
  };
}
function renderCoupleCalendarWidgets() {
  var widgets = document.querySelectorAll('.photo-widget-couple-calendar');
  if (!widgets.length) return;
  var persona = csGetActivePersona();
  var profile = csGetActiveProfile();
  var cal = profile ? csGetCurrentWeekMoodData(profile) : null;
  widgets.forEach(function(widget) {
    var id = widget.id;
    var inner = widget.querySelector('.pw-couple-cal-inner');
    var petEl = widget.querySelector('.pw-cc-pet');
    var monthEl = document.getElementById(id + '_month');
    var yearEl = document.getElementById(id + '_year');
    var gridEl = document.getElementById(id + '_grid');
    var footEl = document.getElementById(id + '_foot');
    if (!gridEl) return;
    if (petEl && !petEl.querySelector('.pw-cc-pet-sprite')) petEl.innerHTML = csMoodSpriteNode('cute', 'pw-cc-pet-sprite', '乖乖');
    if (!profile || !persona || !cal) {
      if (monthEl) monthEl.textContent = '本周';
      if (yearEl) yearEl.textContent = '未绑定角色';
      if (footEl) footEl.textContent = '绑定后同步';
      gridEl.innerHTML = new Array(7).fill('<div class="pw-cc-day"><div class="pw-cc-daynum">·</div><div class="pw-cc-icons"><span class="pw-cc-empty"></span><span class="pw-cc-empty"></span></div></div>').join('');
    } else {
      if (monthEl) monthEl.textContent = cal.monthLabel;
      if (yearEl) yearEl.textContent = cal.yearLabel;
      if (footEl) footEl.textContent = csPersonaDisplayName(persona) + ' 本周同步';
      gridEl.innerHTML = cal.days.map(function(day) {
        return '<div class="pw-cc-day' + (day.inMonth ? '' : ' other') + (day.isToday ? ' today' : '') + '">'
          + '<div class="pw-cc-daynum">' + day.day + '</div>'
          + '<div class="pw-cc-icons">'
          + (day.charMood ? '<span class="pw-cc-icon-box">' + csMoodSpriteNode(day.charMood.id || day.charMood.icon, 'pw-cc-sprite', day.charMood.label) + '</span>' : '<span class="pw-cc-empty"></span>')
          + (day.userMood ? '<span class="pw-cc-icon-box">' + csMoodSpriteNode(day.userMood.id || day.userMood.icon, 'pw-cc-sprite', day.userMood.label) + '</span>' : '<span class="pw-cc-empty"></span>')
          + '</div>'
          + '</div>';
      }).join('');
    }
    csApplyScaleToInner(widget, inner, 224, 224);
  });
}
function renderMoodCalendar(profile) {
  var cal = csGetMoodCalendarData(profile, csMoodMonthOffset);
  var selectedDate = csGetSelectedMoodDate();
  var weekdays = ['一','二','三','四','五','六','日'];
  var html = weekdays.map(function(day){ return '<div class="cs-mood-weekday-ref">' + day + '</div>'; }).join('');
  cal.days.forEach(function(day) {
    html += '<div class="cs-mood-day-ref' + (day.inMonth ? '' : ' other') + (day.isToday ? ' today' : '') + (day.ymd === selectedDate ? ' selected' : '') + '" data-mood-date="' + day.ymd + '" onclick="csPickMoodDate(\'' + day.ymd + '\')">'
      + '<div class="cs-mood-daynum">' + day.day + '</div>'
      + '<div class="cs-mood-icons-stack">'
      + csMoodIconNode(day.charMood, 'char', '角色')
      + csMoodIconNode(day.userMood, 'user', '用户')
      + '</div>'
      + '</div>';
  });
  return {
    monthLabel: cal.monthLabel,
    yearLabel: cal.yearLabel,
    html: html
  };
}
function csRenderHero(profile, persona, ann, count, userName, togetherDays) {
  var personaDisplayName = csPersonaDisplayName(persona);
  var userIdentity = csGetUserIdentityForPersona(persona);
  return ''
    + '<section class="cs-hero' + (profile.coverImage ? ' has-cover' : '') + '">'
    + '<div class="cs-hero-bg" style="background-image:url(\'' + csEsc(profile.coverImage) + '\')"></div>'
    + '<div class="cs-hero-inner">'
    + '<div class="cs-hero-top">'
    + '<div><div class="cs-kicker">Couple Space</div><div class="cs-title">双人专属封面</div><div class="cs-subtitle">已绑定角色：' + csEsc(personaDisplayName) + '。纪念日会同步进角色记忆，聊天时也会被角色记住。</div></div>'
    + '<div class="cs-chip"><i class="fas fa-heart"></i> 已绑定</div>'
    + '</div>'
    + '<div class="cs-avatars"><div class="cs-avatar">' + csGetAvatarSrc(userIdentity, userName) + '</div><div class="cs-avatar-link"><i class="fas fa-link"></i></div><div class="cs-avatar">' + csGetAvatarSrc(persona, persona.name || 'T') + '</div></div>'
    + '<div class="cs-name-line">' + csEsc(userName) + ' × ' + csEsc(personaDisplayName) + '</div>'
    + '<div class="cs-pair-nickname">' + csEsc(profile.coupleNickname || (userName + ' × ' + personaDisplayName)) + '<br>' + csEsc(profile.duoSignature || '把重要的心情和纪念日都留在这里。') + '</div>'
    + '<div class="cs-hero-stats">'
    + '<div class="cs-stat"><div class="cs-stat-label">Love Day</div><div class="cs-stat-value">Day ' + togetherDays + '</div><div class="cs-stat-sub">在一起日期 · ' + csEsc(csFormatDate(profile.togetherSince)) + '</div></div>'
    + '<div class="cs-stat"><div class="cs-stat-label">Widget Countdown</div><div class="cs-stat-value">' + csEsc(count.label) + '</div><div class="cs-stat-sub">' + csEsc((ann ? ann.name : '纪念日') + ' · ' + count.nextLabel) + '</div></div>'
    + '</div>'
    + '<div class="cs-actions">'
    + '<button class="cs-btn" onclick="csUploadCover()">更换双人封面</button>'
    + '<button class="cs-btn light" onclick="csUploadBackground()">更换情侣背景</button>'
    + '<button class="cs-btn light" onclick="csUploadWidgetBackground()">桌件背景图</button>'
    + '<button class="cs-btn ghost" onclick="openCoupleBindSheet()">切换绑定角色</button>'
    + '<button class="cs-btn ghost" onclick="csUnbindPersona()">解绑</button>'
    + '</div>'
    + '</div>'
    + '</section>';
}
function csRenderTabBar() {
  var tabs = [
    { id:'overview', label:'封面' },
    { id:'anniversary', label:'纪念日' },
    { id:'gallery', label:'相册' },
    { id:'footprints', label:'足迹' },
    { id:'moods', label:'情绪' }
  ];
  return '<div class="cs-tabbar">' + tabs.map(function(tab) {
    return '<button class="cs-tab' + (csActiveTab === tab.id ? ' active' : '') + '" onclick="csSetTab(\'' + tab.id + '\')">' + tab.label + '</button>';
  }).join('') + '</div>';
}
function csRenderOverviewTab(profile) {
  return ''
    + '<section class="cs-section">'
    + '<div class="cs-section-head"><div><div class="cs-section-title">基础设定</div><div class="cs-section-desc">把双人资料、专属昵称和桌件显示内容整理在一个标签里，不再和其他模块堆在同一页。</div></div></div>'
    + '<div class="cs-form-grid">'
    + '<div class="cs-field"><label>专属昵称</label><input id="csCoupleNicknameInput" class="cs-input" value="' + csEsc(profile.coupleNickname || '') + '" placeholder="例如：白昼恋人"></div>'
    + '<div class="cs-field"><label>在一起第一天</label><input id="csTogetherInput" class="cs-input" type="date" value="' + csEsc(profile.togetherSince || '') + '"></div>'
    + '<div class="cs-field full"><label>双人签名</label><textarea id="csDuoSignatureInput" class="cs-textarea" placeholder="写下你们的双人签名...">' + csEsc(profile.duoSignature || '') + '</textarea></div>'
    + '<div class="cs-field full"><label>桌件显示纪念日</label><select class="cs-select" onchange="csSetWidgetAnniversary(this.value)">' + profile.anniversaries.map(function(item){ return '<option value="' + csEsc(item.id) + '"' + (item.id === profile.selectedAnniversaryId ? ' selected' : '') + '>' + csEsc(item.name) + ' · ' + csEsc(csFormatDate(item.date)) + '</option>'; }).join('') + '</select></div>'
    + '</div>'
    + '<div class="cs-actions" style="margin-top:12px;"><button class="cs-btn" onclick="csSaveOverview()">保存基础设定</button></div>'
    + '</section>';
}
function csRenderAnniversaryTab(profile, sortedAnns) {
  return ''
    + '<section class="cs-section">'
    + '<div class="cs-section-head"><div><div class="cs-section-title">纪念日倒计时</div><div class="cs-section-desc">生日、在一起纪念日、告白日、情人节、见面日会自动提醒，也可以无限新增。所有纪念日都会写入该角色的记忆。</div></div></div>'
    + '<div class="cs-anniv-list">' + sortedAnns.map(function(item) {
      var info = csCountdownInfo(item.date);
      return '<div class="cs-anniv-card">'
        + '<div class="cs-anniv-top"><div class="cs-anniv-tag"><i class="fas fa-heart"></i>' + csEsc(item.auto ? '自动提醒' : '自定义') + '</div><div style="display:flex;gap:6px;"><button class="cs-mini-btn' + (item.id === profile.selectedAnniversaryId ? ' dark' : '') + '" onclick="csSetWidgetAnniversary(\'' + csEsc(item.id) + '\')">' + (item.id === profile.selectedAnniversaryId ? '桌件显示中' : '设为桌件') + '</button><button class="cs-mini-btn danger" onclick="csRemoveAnniversary(\'' + csEsc(item.id) + '\')">删除</button></div></div>'
        + '<div class="cs-form-grid">'
        + '<div class="cs-field"><label>名称</label><input class="cs-input" value="' + csEsc(item.name || '') + '" onchange="csUpdateAnniversaryField(\'' + csEsc(item.id) + '\',\'name\',this.value)"></div>'
        + '<div class="cs-field"><label>日期</label><input class="cs-input" type="date" value="' + csEsc(item.date || '') + '" onchange="csUpdateAnniversaryField(\'' + csEsc(item.id) + '\',\'date\',this.value)"></div>'
        + '</div>'
        + '<div class="cs-pill-row" style="margin-top:10px;"><span class="cs-pill">' + csEsc(info.label) + '</span><span class="cs-pill">' + csEsc(info.nextLabel) + '</span></div>'
        + '</div>';
    }).join('') + '</div>'
    + '<div class="cs-form-grid" style="margin-top:12px;">'
    + '<div class="cs-field"><label>新增纪念日</label><input id="csNewAnnivName" class="cs-input" placeholder="例如：第一次旅行"></div>'
    + '<div class="cs-field"><label>纪念类型</label><select id="csNewAnnivType" class="cs-select"><option value="custom">自定义</option><option value="birthday">生日</option><option value="meet">见面日</option><option value="trip">旅行日</option><option value="proposal">求婚日</option></select></div>'
    + '<div class="cs-field full"><label>日期</label><input id="csNewAnnivDate" class="cs-input" type="date"></div>'
    + '</div>'
    + '<div class="cs-actions" style="margin-top:12px;"><button class="cs-btn" onclick="csAddAnniversary()">添加纪念日</button></div>'
    + '</section>'
    + '<section class="cs-section">'
    + '<div class="cs-section-head"><div><div class="cs-section-title">纪念日日历</div><div class="cs-section-desc">把常驻提醒整理成单独模块，桌件与情侣空间可以共用同一份纪念日数据。</div></div></div>'
    + '<div class="cs-calendar-grid">' + sortedAnns.map(function(item) {
      var info = csCountdownInfo(item.date);
      return '<div class="cs-calendar-item"><div><div class="cs-calendar-date">' + csEsc(csFormatDate(item.date).slice(5)) + '</div><div class="cs-calendar-name">' + csEsc(item.name || '纪念日') + '</div></div><div class="cs-calendar-count">' + csEsc(info.label) + ' · 下一次在 ' + info.nextLabel + '</div></div>';
    }).join('') + '</div>'
    + '</section>';
}
function csRenderGalleryTab(profile, persona) {
  var items = csGetGalleryItems(profile);
  var counts = csGalleryCounts(items);
  var recent = items.slice(0, 4);
  var personaDisplayName = csPersonaDisplayName(persona);
  return ''
    + '<section class="cs-section">'
    + '<div class="cs-section-head"><div><div class="cs-section-title">相册合集</div><div class="cs-section-desc">这里会像 iOS 相簿一样整理你们的照片流。点击具体相片后，才会展开看那张照片的详细内容描述。</div></div><div class="cs-actions"><button class="cs-btn light" onclick="csGenerateAlbumIdeas()">' + (csBusy.album ? '生成中...' : 'AI生成相片') + '</button><button class="cs-btn" onclick="csPickGalleryUpload()">上传照片</button></div></div>'
    + (items.length ? '<div class="cs-gallery-grid"><div class="cs-gallery-ios-shell">'
      + '<div class="cs-gallery-summary-card"><div class="cs-gallery-summary-top"><div><div class="cs-gallery-summary-kicker">Recents</div><div class="cs-gallery-summary-title">最近项目</div><div class="cs-gallery-summary-sub">' + csEsc(personaDisplayName + ' 与你共同保存下来的日常、互动和纪念性瞬间。') + '</div></div><div class="cs-gallery-summary-count">' + items.length + ' 张相片</div></div>'
      + '<div class="cs-gallery-mosaic"><div class="cs-gallery-mosaic-main">' + (recent[0] ? csRenderGalleryTile(recent[0], 'main') : '') + '</div><div class="cs-gallery-mosaic-sub">' + (recent[1] ? csRenderGalleryTile(recent[1], 'side') : '<div class="cs-gallery-photo-tile side"><div class="cs-gallery-placeholder"><div class="t1">Album</div><div class="t2">等待新的瞬间</div></div></div>') + (recent[2] ? csRenderGalleryTile(recent[2], 'side') : '<div class="cs-gallery-photo-tile side"><div class="cs-gallery-placeholder"><div class="t1">Memory</div><div class="t2">继续收藏你们的日常</div></div></div>') + '</div></div></div>'
      + '<div class="cs-gallery-list">'
      + '<div class="cs-gallery-row"><div class="cs-gallery-row-stack">' + csGalleryRowStack(items) + '</div><div class="cs-gallery-row-main"><div class="cs-gallery-row-title">所有照片</div><div class="cs-gallery-row-sub">双人相簿里保存的全部瞬间</div></div><div class="cs-gallery-row-count">' + counts.total + '</div></div>'
      + '<div class="cs-gallery-row"><div class="cs-gallery-row-stack">' + csGalleryRowStack(items.filter(function(item){ return item.type === 'ai'; })) + '</div><div class="cs-gallery-row-main"><div class="cs-gallery-row-title">AI 生成</div><div class="cs-gallery-row-sub">依照当前连接 API 生成的真实照片感画面</div></div><div class="cs-gallery-row-count">' + counts.ai + '</div></div>'
      + '<div class="cs-gallery-row"><div class="cs-gallery-row-stack">' + csGalleryRowStack(items.filter(function(item){ return item.type === 'upload'; })) + '</div><div class="cs-gallery-row-main"><div class="cs-gallery-row-title">已上传</div><div class="cs-gallery-row-sub">用户自己添加的照片与碎片记录</div></div><div class="cs-gallery-row-count">' + counts.upload + '</div></div>'
      + '<div class="cs-gallery-row"><div class="cs-gallery-row-stack">' + csGalleryRowStack(items.filter(function(item){ return item.allowMoments; })) + '</div><div class="cs-gallery-row-main"><div class="cs-gallery-row-title">可发朋友圈</div><div class="cs-gallery-row-sub">允许角色在朋友圈引用使用的照片</div></div><div class="cs-gallery-row-count">' + counts.moments + '</div></div>'
      + '</div>'
      + '<div class="cs-gallery-collection"><div class="cs-gallery-collection-head"><div class="cs-gallery-collection-title">全部照片</div><div class="cs-gallery-collection-desc">点开单张相片查看详细描述</div></div><div class="cs-gallery-ios-grid">'
      + items.map(function(item) {
        return '<div class="cs-gallery-card" onclick="csOpenGalleryDetail(\'' + csEsc(item.id) + '\')">'
          + csRenderGalleryTile(item, '')
          + '<div class="cs-gallery-card-meta"><div class="cs-gallery-card-title">' + csEsc(item.title || '未命名相片') + '</div><div class="cs-gallery-card-sub">' + csEsc(item.desc || csGalleryStory(item)) + '</div></div></div>';
      }).join('')
      + '</div></div></div></div>'
      : '<div class="cs-empty">还没有相册内容。可以先生成真实照片感的 AI 相片，或上传你们的合照、碎片和日常照片。</div>')
    + '</section>';
}
function csRenderFootprintsTab(profile) {
  return ''
    + '<section class="cs-section">'
    + '<div class="cs-section-head"><div><div class="cs-section-title">足迹打卡</div><div class="cs-section-desc">AI 足迹会使用当前 API 生成地点方案；如果接口支持生图，也会为足迹生成画面。</div></div><div class="cs-actions"><button class="cs-btn light" onclick="csGenerateFootprints()">' + (csBusy.footprints ? '生成中...' : 'AI生成足迹') + '</button></div></div>'
    + (profile.footprints.length ? '<div class="cs-footprint-list">' + profile.footprints.map(function(item) {
      var palette = item.palette || ['#f4f1ee', '#ddd6d2'];
      return '<div class="cs-footprint-item"><div class="cs-footprint-cover' + (item.image ? ' has-image' : '') + '" style="' + (!item.image ? ('background:linear-gradient(145deg,' + palette[0] + ',' + palette[1] + ');') : '') + '">' + (item.image ? '<img src="' + csEsc(item.image) + '">' : '<div class="cs-gallery-placeholder"><div class="t1">' + csEsc(item.title || 'Footprint') + '</div><div class="t2">' + csEsc(item.location || '共同坐标') + '</div></div>') + '</div><div class="cs-footprint-body"><div class="cs-footprint-title">' + csEsc(item.title || '足迹') + '</div><div class="cs-footprint-desc">' + csEsc(item.desc || '') + '</div><div class="cs-footprint-meta"><span class="cs-pill">' + csEsc(item.location || '未填写地点') + '</span><span class="cs-pill">' + csEsc((item.date || '') + (item.time ? (' · ' + item.time) : '')) + '</span><button class="cs-mini-btn danger" onclick="csDeleteFootprint(\'' + csEsc(item.id) + '\')">删除</button></div></div></div>';
    }).join('') + '</div>' : '<div class="cs-empty">还没有足迹。试试生成一组 AI 恋爱地图，或者手动记录今天的约会地点。</div>')
    + '<div class="cs-form-grid" style="margin-top:12px;">'
    + '<div class="cs-field"><label>地点标题</label><input id="csFootTitle" class="cs-input" placeholder="例如：第一次一起去的书店"></div>'
    + '<div class="cs-field"><label>地点 / 城市</label><input id="csFootLoc" class="cs-input" placeholder="例如：首尔 / 弘大 / 小店名"></div>'
    + '<div class="cs-field"><label>日期</label><input id="csFootDate" class="cs-input" type="date"></div>'
    + '<div class="cs-field"><label>时间</label><input id="csFootTime" class="cs-input" type="time"></div>'
    + '<div class="cs-field full"><label>描述</label><textarea id="csFootDesc" class="cs-textarea" placeholder="记录一下今天的约会细节、地点和心情..."></textarea></div>'
    + '</div>'
    + '<div class="cs-actions" style="margin-top:12px;"><button class="cs-btn light" onclick="csPickFootprintPhoto()">添加图片</button><button class="cs-btn" onclick="csAddManualFootprint()">保存足迹</button></div>'
    + '<div class="cs-upload-preview" id="csFootPreview"><img src=""></div>'
    + '</section>';
}
function csRenderMoodTab(profile, persona, mood, moodCalendar) {
  var selectedDate = csGetSelectedMoodDate();
  var selectedEntry = (profile.moodMap && profile.moodMap[selectedDate]) || {};
  var selectedCharMood = selectedEntry.char ? csMoodById(selectedEntry.char) : null;
  var isTodaySelected = selectedDate === csTodayStr();
  return ''
    + '<section class="cs-section">'
    + '<div class="cs-section-head"><div><div class="cs-section-title">每日情绪</div><div class="cs-section-desc">角色情绪在上、用户情绪在下。角色只根据当天和这个角色的聊天内容自动判断。</div></div></div>'
    + '<div class="cs-mood-ref-card">'
    + '<div class="cs-mood-card-top"><div class="cs-mood-pet-left">' + csMoodSpriteNode('cute', 'cs-mood-pet-sprite', '乖乖') + '</div><div class="cs-mood-title-wrap"><div class="cs-mood-title-main">' + csEsc(moodCalendar.monthLabel) + '</div><div class="cs-mood-title-sub">' + csEsc(moodCalendar.yearLabel) + '</div></div></div>'
    + '<div class="cs-mood-nav"><button class="cs-icon-btn" onclick="csShiftMoodMonth(-1)"><i class="fas fa-chevron-left"></i></button><div class="cs-inline-note">角色在上 · 用户在下</div><button class="cs-icon-btn" onclick="csShiftMoodMonth(1)"><i class="fas fa-chevron-right"></i></button></div>'
    + '<div class="cs-mood-grid-ref">' + moodCalendar.html + '</div>'
    + '</div>'
    + '<div class="cs-mood-panel"><div class="cs-inline-note">角色今日情绪：<span class="cs-mood-inline-pill"><span class="cs-mood-icon-box">' + csMoodSpriteNode(mood.id || mood.icon, 'cs-mood-sprite', mood.label) + '</span>' + csEsc(mood.label) + '</span>' + (selectedEntry._manualChar && isTodaySelected ? ' 已手动修改' : ' 默认按当天聊天自动判断') + '</div>'
    + '<div class="cs-inline-note" style="margin-top:8px;">当前正在编辑：<span class="cs-mood-inline-pill">' + csEsc(csFormatDate(selectedDate)) + (selectedDate === csTodayStr() ? ' · 今天' : '') + '</span> 用户可以随时修改任意日期的心情。</div>'
    + '<div class="cs-inline-note" style="margin-top:10px;">角色情绪</div>'
    + '<div class="cs-mood-picker-ref">' + CS_MOODS.map(function(item) {
      var picked = selectedCharMood && selectedCharMood.id === item.id;
      return '<div class="cs-mood-choice' + (picked ? ' active' : '') + '" onclick="csSelectCharMood(\'' + item.id + '\')">' + csMoodSpriteNode(item.id || item.icon, 'cs-mood-choice-sprite', item.label) + '<div class="cs-mood-option-label">' + csEsc(item.label) + '</div></div>';
    }).join('') + '</div>'
    + (isTodaySelected ? '<div class="cs-actions" style="margin-top:10px;"><button class="cs-btn light" onclick="csResetCharMoodAuto()">恢复今天的自动判断</button></div>' : '')
    + '<div class="cs-inline-note" style="margin-top:12px;">用户情绪</div>'
    + '<div class="cs-mood-picker-ref">' + CS_MOODS.map(function(item) {
      var picked = selectedEntry.user === item.id;
      return '<div class="cs-mood-choice' + (picked ? ' active' : '') + '" onclick="csSelectUserMood(\'' + item.id + '\')">' + csMoodSpriteNode(item.id || item.icon, 'cs-mood-choice-sprite', item.label) + '<div class="cs-mood-option-label">' + csEsc(item.label) + '</div></div>';
    }).join('') + '</div></div>'
    + '</section>';
}
function renderCoupleSpace() {
  renderCoupleSpaceWidget();
  var stage = document.getElementById('coupleSpaceStage');
  if (!stage) return;
  var persona = csGetActivePersona();
  var profile = csGetActiveProfile();
  if (!persona || !profile) {
    stage.style.backgroundImage = '';
    stage.style.backgroundSize = '';
    stage.style.backgroundPosition = '';
    stage.innerHTML = ''
      + '<section class="cs-hero"><div class="cs-hero-inner">'
      + '<div class="cs-hero-top"><div><div class="cs-kicker">Couple Space</div><div class="cs-title">情侣空间</div><div class="cs-subtitle">绑定一个角色后，这里会生成双人专属封面、纪念日、相册、足迹和情绪日历。</div></div><div class="cs-chip"><i class="fas fa-link"></i> 未绑定</div></div>'
      + '<div class="cs-avatars"><div class="cs-avatar">' + csGetAvatarSrc(getUserProfile(), (userProfile && userProfile.name) || '你') + '</div><div class="cs-avatar-link"><i class="fas fa-heart"></i></div><div class="cs-avatar">TA</div></div>'
      + '<div class="cs-actions"><button class="cs-btn" onclick="openCoupleBindSheet()">选择角色并开始</button></div>'
      + '</div></section>'
      + '<section class="cs-section"><div class="cs-section-title">待开启内容</div><div class="cs-section-desc">绑定之后会自动开启桌件纪念日倒计时、恋爱天数、纪念日日历、双人相册、足迹打卡，以及按当天聊天内容自动判断的角色心情日历。</div></section>';
    csRenderGalleryDetailOverlay();
    return;
  }
  profile = csEnsureProfile(persona.id);
  if (profile.backgroundImage) {
    stage.style.backgroundImage = 'linear-gradient(rgba(255,255,255,0.72), rgba(245,245,247,0.9)), url("' + profile.backgroundImage + '")';
    stage.style.backgroundSize = 'cover';
    stage.style.backgroundPosition = 'center';
  } else {
    stage.style.backgroundImage = '';
    stage.style.backgroundSize = '';
    stage.style.backgroundPosition = '';
  }
  var ann = csGetDisplayAnniversary(profile);
  var count = ann ? csCountdownInfo(ann.date) : { label:'D-0', nextLabel:'未设定' };
  var mood = csSetAutoCharMood();
  var moodCalendar = renderMoodCalendar(profile);
  var userIdentity = csGetUserIdentityForPersona(persona);
  var userName = (userIdentity && userIdentity.name) || '你';
  var togetherDays = csLoveDays(profile);
  var sortedAnns = profile.anniversaries.slice().sort(function(a, b) {
    return (csCountdownInfo(a.date).days || 9999) - (csCountdownInfo(b.date).days || 9999);
  });
  if (csActiveTab !== 'gallery' && csGalleryDetailId) csGalleryDetailId = '';
  var bodyHtml = '';
  if (csActiveTab === 'anniversary') bodyHtml = csRenderAnniversaryTab(profile, sortedAnns);
  else if (csActiveTab === 'gallery') bodyHtml = csRenderGalleryTab(profile, persona);
  else if (csActiveTab === 'footprints') bodyHtml = csRenderFootprintsTab(profile);
  else if (csActiveTab === 'moods') bodyHtml = csRenderMoodTab(profile, persona, mood, moodCalendar);
  else bodyHtml = csRenderOverviewTab(profile);
  stage.innerHTML = csRenderHero(profile, persona, ann, count, userName, togetherDays) + csRenderTabBar() + bodyHtml;
  if (csActiveTab === 'moods') {
    Array.prototype.forEach.call(stage.querySelectorAll('.cs-mood-day-ref[data-mood-date]'), function(el) {
      var ymd = el.getAttribute('data-mood-date');
      if (!ymd) return;
      el.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();
        csPickMoodDate(ymd);
      });
    });
  }
  csRenderGalleryDetailOverlay();
}
function handleGalleryUpload(input) {
  var profile = csGetActiveProfile();
  if (!profile || !input || !input.files || !input.files.length) return;
  Array.prototype.slice.call(input.files).forEach(function(file, idx) {
    csReadFile(file, async function(dataUrl) {
      var shortDesc = '已上传到双人共用相册。';
      var detail = '这张照片已经保存进双人相簿，等待更完整的内容记录。';
      var title = file.name.replace(/\.[^.]+$/, '') || '上传照片';
      var viewpoint = '旁观镜头';
      var shotAt = '共享相册';
      try {
        var aiDesc = await csDescribeImageWithChatApi(dataUrl, { preferredViewpoint: '角色视角' });
        if (aiDesc && typeof aiDesc === 'object') {
          if (aiDesc.title) title = aiDesc.title;
          if (aiDesc.desc) shortDesc = aiDesc.desc;
          if (aiDesc.detail) detail = aiDesc.detail;
          viewpoint = csNormalizeGalleryViewpoint(aiDesc.viewpoint, '旁观镜头');
          if (aiDesc.shotAt) shotAt = aiDesc.shotAt;
        }
      } catch(e) {
        shortDesc = '当前聊天 API 没有返回短注脚，但照片已保存。';
        detail = '当前聊天 API 没有返回详细描述，但这张照片已经保存在双人相簿里。';
      }
      var itemId = 'cs_gallery_upload_' + Date.now() + '_' + idx;
      profile.gallery.unshift({
        id: itemId,
        type: 'upload',
        title: title,
        desc: shortDesc,
        detail: detail,
        viewpoint: viewpoint,
        shotAt: shotAt,
        image: dataUrl,
        palette: ['#f3f3f4', '#d9d9dd'],
        allowMoments: false,
        roleViewRequestedAt: 0,
        createdAt: Date.now()
      });
      csGalleryDetailId = itemId;
      csSave();
      renderCoupleSpace();
    }, { maxSize: 1400, quality: 0.82 });
  });
  input.value = '';
}
function handleFootprintUpload(input) {
  if (!input || !input.files || !input.files[0]) return;
  csReadFile(input.files[0], function(dataUrl) {
    csPendingFootprintImage = dataUrl;
    var preview = document.getElementById('csFootPreview');
    if (preview) {
      preview.style.display = 'block';
      var img = preview.querySelector('img');
      if (img) img.src = dataUrl;
    }
  }, { maxSize: 1280, quality: 0.82 });
  input.value = '';
}
window.openCoupleSpacePage = function() {
  if (typeof window._iphIsEditMode === 'function' && window._iphIsEditMode()) return;
  csReloadStateFromStorage();
  csHydrateMediaRefs().then(function(changed) {
    if (changed) renderCoupleSpace();
  }).catch(function(){});
  renderCoupleSpace();
  openApp('coupleSpacePage');
};
