// ===== script-26 =====

(function() {
'use strict';
var CS_STORE = 'mono_couple_space_v1';
function monoCsClone(value) {
  try { return JSON.parse(JSON.stringify(value == null ? {} : value)); } catch(e) {}
  if (!value || typeof value !== 'object') return {};
  return Array.isArray(value) ? value.slice() : Object.assign({}, value);
}
function monoCsLoadState() {
  try {
    var raw = JSON.parse(localStorage.getItem(CS_STORE) || 'null');
    return raw && typeof raw === 'object' ? raw : {};
  } catch(e) {
    return {};
  }
}
function monoCsEnsureStateShape(state) {
  if (!state || typeof state !== 'object') state = {};
  if (!state.profiles || typeof state.profiles !== 'object') state.profiles = {};
  if (!state.activePersonaId) state.activePersonaId = '';
  return state;
}
function monoCsDataImage(value) {
  return (typeof value === 'string' && value.indexOf('data:image') === 0) ? value : '';
}
function monoCsCollectFromProfile(profileId, profile, stripMode, assets) {
  if (!profile || typeof profile !== 'object') return;
  function pullField(obj, field, key) {
    if (!obj || typeof obj !== 'object') return;
    var dataUrl = monoCsDataImage(obj[field]);
    if (!dataUrl) return;
    assets[key] = dataUrl;
    if (stripMode) obj[field] = '';
  }
  pullField(profile, 'coverImage', 'profile:' + profileId + ':coverImage');
  pullField(profile, 'backgroundImage', 'profile:' + profileId + ':backgroundImage');
  pullField(profile, 'widgetBackground', 'profile:' + profileId + ':widgetBackground');
  if (Array.isArray(profile.gallery)) {
    profile.gallery.forEach(function(item, index) {
      if (!item || typeof item !== 'object') return;
      var itemId = item.id != null ? String(item.id) : String(index);
      pullField(item, 'image', 'profile:' + profileId + ':gallery:' + itemId + ':image');
    });
  }
  if (Array.isArray(profile.footprints)) {
    profile.footprints.forEach(function(item, index) {
      if (!item || typeof item !== 'object') return;
      var itemId = item.id != null ? String(item.id) : String(index);
      pullField(item, 'image', 'profile:' + profileId + ':footprints:' + itemId + ':image');
    });
  }
}
function monoCsCollectAssetsAndMaybeStrip(sourceState, stripMode) {
  var state = monoCsEnsureStateShape(monoCsClone(sourceState));
  var assets = {};
  Object.keys(state.profiles).forEach(function(profileId) {
    monoCsCollectFromProfile(profileId, state.profiles[profileId], stripMode, assets);
  });
  return { state: state, mediaAssets: assets };
}
function monoCsFindById(list, itemId) {
  if (!Array.isArray(list)) return null;
  for (var i = 0; i < list.length; i++) {
    var item = list[i];
    if (item && String(item.id) === String(itemId)) return item;
  }
  return null;
}
function monoCsRestoreAssetsIntoState(baseState, pack) {
  var state = monoCsEnsureStateShape(monoCsClone(baseState));
  var mediaAssets = (pack && pack.mediaAssets && typeof pack.mediaAssets === 'object') ? pack.mediaAssets : {};
  var restored = 0;
  Object.keys(mediaAssets).forEach(function(key) {
    var dataUrl = monoCsDataImage(mediaAssets[key]);
    if (!dataUrl) return;
    var parts = String(key).split(':');
    if (parts.length < 4 || parts[0] !== 'profile') return;
    var profileId = parts[1];
    var fieldType = parts[2];
    var profile = state.profiles[profileId];
    if (!profile || typeof profile !== 'object') return;
    if (fieldType === 'coverImage' || fieldType === 'backgroundImage' || fieldType === 'widgetBackground') {
      profile[fieldType] = dataUrl;
      restored += 1;
      return;
    }
    if (parts.length < 5) return;
    var itemId = parts[3];
    var field = parts[4];
    if (field !== 'image') return;
    if (fieldType === 'gallery') {
      var galleryItem = monoCsFindById(profile.gallery, itemId);
      if (galleryItem) {
        galleryItem.image = dataUrl;
        restored += 1;
      }
      return;
    }
    if (fieldType === 'footprints') {
      var footItem = monoCsFindById(profile.footprints, itemId);
      if (footItem) {
        footItem.image = dataUrl;
        restored += 1;
      }
    }
  });
  return { state: state, restored: restored };
}
window._monoExportCoupleSpaceStateForStorage = function() {
  var source = (typeof window._monoExportCoupleSpaceState === 'function') ? window._monoExportCoupleSpaceState() : monoCsLoadState();
  return monoCsCollectAssetsAndMaybeStrip(source, true).state;
};
window._monoCollectCoupleSpaceImageAssetsForExport = function() {
  var source = (typeof window._monoExportCoupleSpaceState === 'function') ? window._monoExportCoupleSpaceState() : monoCsLoadState();
  var result = monoCsCollectAssetsAndMaybeStrip(source, false);
  return { mediaAssets: result.mediaAssets };
};
window._monoRestoreCoupleSpaceImageAssetsFromImport = function(pack) {
  var restored = monoCsRestoreAssetsIntoState(monoCsLoadState(), pack);
  try {
    localStorage.setItem(CS_STORE, JSON.stringify(restored.state));
  } catch(e) {}
  try {
    if (typeof window._monoApplyCoupleSpaceState === 'function') window._monoApplyCoupleSpaceState(restored.state);
    else if (typeof window.renderCoupleSpace === 'function') window.renderCoupleSpace();
  } catch(e2) {}
  try {
    if (typeof window.renderCoupleCalendarWidgets === 'function') window.renderCoupleCalendarWidgets();
  } catch(e3) {}
  return Promise.resolve(restored.restored || 0);
};
})();


