(function(){
// ========== BG Test Panel ==========
window.openBgTestPanel = function(mode) {
  const overlay = document.getElementById('bgTestPanelOverlay');
  overlay.style.display = 'flex';
  document.getElementById('bgTestLog').innerHTML = '';
  document.getElementById('bgTestPanelTitle').textContent = mode === 'test' ? '后台自动消息 · 强制测试' : '后台自动消息 · 诊断';
  document.getElementById('bgTestPanelSubtitle').textContent = mode === 'test' ? '绕过时间限制，强制触发一次完整发送流程' : '检查 SW 及 IDB 配置是否正常';
  document.getElementById('bgTestPendingBar').style.display = 'none';
  _refreshSwStatusBar();
  if (mode) setTimeout(() => runBgTest(mode), 400);
};
window.closeBgTestPanel = function() {
  document.getElementById('bgTestPanelOverlay').style.display = 'none';
};
function _refreshSwStatusBar() {
  const regEl = document.getElementById('bgTestSwReg');
  const ctrlEl = document.getElementById('bgTestSwCtrl');
  const notifEl = document.getElementById('bgTestSwNotif');
  if (!('serviceWorker' in navigator)) {
    regEl.textContent = '❌ 当前浏览器不支持 Service Worker';
    return;
  }
  navigator.serviceWorker.getRegistration().then(reg => {
    if (!reg) {
      regEl.innerHTML = '❌ SW <span style="color:#ff4d4f">未注册</span>';
    } else {
      const state = reg.active ? 'active' : reg.installing ? 'installing' : reg.waiting ? 'waiting' : '未知';
      regEl.innerHTML = '✅ SW已注册 <span style="color:#52c41a;font-weight:600">' + state + '</span>';
    }
    const ctrl = navigator.serviceWorker.controller;
    ctrlEl.textContent = ctrl ? '✅ Controller: 已控制' : '⚠️ Controller: 无（需刷新页面）';
  }).catch(() => { regEl.textContent = '❌ SW 查询失败'; });
  if ('Notification' in window) {
    const p = Notification.permission;
    notifEl.textContent = p === 'granted' ? '🔔 通知权限: 已授权' : p === 'denied' ? '🔕 通知权限: 已拒绝' : '⚠️ 通知权限: 未授权';
    notifEl.style.color = p === 'granted' ? '#52c41a' : p === 'denied' ? '#ff4d4f' : '#fa8c16';
  } else {
    notifEl.textContent = '❌ 不支持通知API';
  }
}
window.runBgTest = function(mode) {
  const logEl = document.getElementById('bgTestLog');
  const spinner = document.getElementById('bgTestSpinner');
  logEl.innerHTML = '';
  spinner.style.display = 'block';
  document.getElementById('bgTestDiagnoseBtn').disabled = true;
  document.getElementById('bgTestSendBtn').disabled = true;
  _refreshSwStatusBar();
  const sw = navigator.serviceWorker && (navigator.serviceWorker.controller ||
    (window._swRegistration && window._swRegistration.active));
  if (!sw) {
    _bgTestAppendLog('❌ Service Worker 未激活或未控制当前页面。\n请尝试：\n1. 刷新页面后再测试\n2. 检查浏览器是否支持SW\n3. 检查是否在HTTPS或localhost下运行', 'error');
    spinner.style.display = 'none';
    document.getElementById('bgTestDiagnoseBtn').disabled = false;
    document.getElementById('bgTestSendBtn').disabled = false;
    return;
  }
  // First sync current config to SW
  try { if (typeof syncBgConfigToSW === 'function') syncBgConfigToSW(); } catch(e){}
  setTimeout(() => {
    sw.帖子Message({ type: mode === 'test' ? 'BG_TEST' : 'BG_DIAGNOSE' });
  }, 600);
};
window.syncAndRediagnose = function() {
  const logEl = document.getElementById('bgTestLog');
  logEl.innerHTML = '';
  _bgTestAppendLog('🔄 正在将当前配置同步至 SW IDB…', 'info');
  try {
    if (typeof syncBgConfigToSW === 'function') syncBgConfigToSW();
    setTimeout(() => {
      _bgTestAppendLog('✅ 同步完成，正在重新诊断…', 'info');
      runBgTest('diagnose');
    }, 800);
  } catch(e) {
    _bgTestAppendLog('❌ 同步失败：' + e.message, 'error');
  }
};
window.forceSyncBgMsgs = function() {
  try {
    if (typeof syncBgMessagesToPage === 'function') {
      syncBgMessagesToPage();
      document.getElementById('bgTestPendingBar').style.display = 'none';
      _bgTestAppendLog('✅ 已触发消息同步，请查看对应聊天室', 'success');
    }
  } catch(e) {}
};
function _bgTestAppendLog(msg, level) {
  const logEl = document.getElementById('bgTestLog');
  const line = document.createElement('div');
  line.className = 'log-' + (level || 'info');
  line.textContent = msg;
  logEl.appendChild(line);
  logEl.scrollTop = logEl.scrollHeight;
}
// Listen for SW messages
if (navigator.serviceWorker) {
  navigator.serviceWorker.addEventListener('message', function(e) {
    if (!e.data) return;
    if (e.data.type === 'BG_TEST_LOG') {
      if (document.getElementById('bgTestPanelOverlay').style.display !== 'none') {
        _bgTestAppendLog(e.data.msg, e.data.level);
        // Check for pending msgs mention
        if (e.data.msg && e.data.msg.includes('待同步')) {
          document.getElementById('bgTestPendingBar').style.display = 'block';
        }
      }
    }
    if (e.data.type === 'BG_TEST_DONE') {
      document.getElementById('bgTestSpinner').style.display = 'none';
      const d = document.getElementById('bgTestDiagnoseBtn');
      const s = document.getElementById('bgTestSendBtn');
      if (d) d.disabled = false;
      if (s) s.disabled = false;
      // Auto sync after test
      if (typeof syncBgMessagesToPage === 'function') {
        try { syncBgMessagesToPage(); } catch(e){}
      }
    }
  });
}
})();


