function diaryCoverAddSticker(event) {
  const file = event.target.files[0];
  if (!file) return;
  const statusEl = document.getElementById('diaryCoverBgRemoveStatus');
  statusEl.textContent = '正在处理图片...';
  
  const reader = new FileReader();
  reader.onload = (e) => {
    // Simple bg removal: load onto canvas and use threshold-based approach
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width; canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0);
      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const d = imgData.data;
      // Get corner color as background sample
      const bgR = d[0], bgG = d[1], bgB = d[2];
      for (let i = 0; i < d.length; i += 4) {
        const dr = Math.abs(d[i]-bgR), dg = Math.abs(d[i+1]-bgG), db = Math.abs(d[i+2]-bgB);
        if (dr + dg + db < 80) d[i+3] = 0;
      }
      ctx.putImageData(imgData, 0, 0);
      const src = canvas.toDataURL('image/png');
      
      const s = _dbGetSettings(_dce_ownerId);
      if (!s.decos) s.decos = [];
      s.decos.push({ type: 'sticker', src, x: 50, y: 50, w: 50, h: 50, id: Date.now() });
      statusEl.textContent = '贴纸已添加！';
      setTimeout(() => { statusEl.textContent = ''; }, 2000);
      _updateCoverPreview();
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

