function _updateCoverPreview() {
  const preview = document.getElementById('diaryCoverPreview');
  if (!preview || !_dce_ownerId) return;
  const s = _dbGetSettings(_dce_ownerId);
  preview.style.background = s.coverBg || COVER_COLORS[0];

  // Static base content
  let baseHtml = '';
  if (s.coverImage) {
    baseHtml = `<img src="${s.coverImage}" style="width:90px;height:80px;object-fit:cover;border:2px solid rgba(255,255,255,0.85);box-shadow:0 2px 6px rgba(0,0,0,0.1);display:block;margin:20px auto 0;border-radius:2px;pointer-events:none;">`;
  } else {
    baseHtml = `<div style="font-family:'Cormorant Garamond',serif;font-size:11px;font-style:italic;color:rgba(42,39,38,0.5);text-align:center;padding:40px 10px 0;pointer-events:none;">my diary</div>`;
  }
  preview.innerHTML = `<div style="position:relative;width:100%;height:100%;overflow:visible;">${baseHtml}</div>`;
  const container = preview.firstChild;

  const PREV_W = 140, PREV_H = 192;
  const scaleX = PREV_W / 160, scaleY = PREV_H / 220;

  (s.decos || []).forEach((deco, idx) => {
    const px = deco.x * scaleX / 100 * PREV_W;
    const py = deco.y * scaleY / 100 * PREV_H;

    const el = document.createElement('div');
    el.style.cssText = `position:absolute;left:${px}px;top:${py}px;transform:translate(-50%,-50%);cursor:move;user-select:none;touch-action:none;`;

    if (deco.type === 'text') {
      const span = document.createElement('span');
      span.style.cssText = `font-family:'${deco.font}',serif;font-size:${Math.round(deco.size*0.85)}px;color:${deco.color};white-space:nowrap;pointer-events:none;font-style:italic;display:block;`;
      span.textContent = deco.content;
      el.appendChild(span);
    } else if (deco.type === 'sticker') {
      const img = document.createElement('img');
      img.src = deco.src;
      img.style.cssText = `width:${Math.round((deco.w||50)*scaleX)}px;height:${Math.round((deco.h||50)*scaleY)}px;object-fit:contain;pointer-events:none;display:block;`;
      el.appendChild(img);
    }

    // Delete button
    const del = document.createElement('div');
    del.style.cssText = 'position:absolute;right:-7px;top:-7px;width:14px;height:14px;background:#e74c3c;border-radius:50%;cursor:pointer;color:#fff;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:bold;z-index:10;line-height:1;';
    del.textContent = '×';
    del.title = '删除';
    del.addEventListener('mousedown', e => { e.stopPropagation(); e.preventDefault(); });
    del.addEventListener('touchstart', e => { e.stopPropagation(); }, {passive:true});
    del.addEventListener('click', e => {
      e.stopPropagation();
      s.decos.splice(idx, 1);
      _dbSaveBookSettings();
      _updateCoverPreview();
    });
    el.appendChild(del);

    // Drag logic
    let sx, sy, sl, st2;
    const onStart = (e) => {
      if (e.target === del) return;
      e.preventDefault(); e.stopPropagation();
      const touch = e.touches ? e.touches[0] : e;
      sx = touch.clientX; sy = touch.clientY;
      sl = parseFloat(el.style.left); st2 = parseFloat(el.style.top);
      document.addEventListener('mousemove', onDrag);
      document.addEventListener('mouseup', onEnd);
      document.addEventListener('touchmove', onDrag, {passive:false});
      document.addEventListener('touchend', onEnd);
    };
    const onDrag = (e) => {
      e.preventDefault();
      const touch = e.touches ? e.touches[0] : e;
      const nx = Math.max(0, Math.min(PREV_W, sl + (touch.clientX - sx)));
      const ny = Math.max(0, Math.min(PREV_H, st2 + (touch.clientY - sy)));
      el.style.left = nx + 'px';
      el.style.top = ny + 'px';
      deco.x = nx * 100 / (scaleX * PREV_W);
      deco.y = ny * 100 / (scaleY * PREV_H);
    };
    const onEnd = () => {
      document.removeEventListener('mousemove', onDrag);
      document.removeEventListener('mouseup', onEnd);
      document.removeEventListener('touchmove', onDrag);
      document.removeEventListener('touchend', onEnd);
      _dbSaveBookSettings();
    };
    el.addEventListener('mousedown', onStart);
    el.addEventListener('touchstart', onStart, {passive:false});

    container.appendChild(el);
  });
}

