function diaryPageStickerSelected(event) {
  const file = event.target.files[0];
  if (!file) return;
  if (!_dps_targetEntryId) return;
  
  const statusEl = document.getElementById('diaryImgStickerStatus');
  statusEl.textContent = '正在处理...';
  
  const reader = new FileReader();
  reader.onload = (e) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const size = 120;
      canvas.width = size; canvas.height = size;
      const ctx = canvas.getContext('2d');
      
      const shape = _dce_stickerShape;
      
      if (shape === 'nobg') {
        // Background removal
        canvas.width = img.width; canvas.height = img.height;
        ctx.drawImage(img, 0, 0);
        const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const d = imgData.data;
        const bgR = d[0], bgG = d[1], bgB = d[2];
        for (let i = 0; i < d.length; i += 4) {
          if (Math.abs(d[i]-bgR)+Math.abs(d[i+1]-bgG)+Math.abs(d[i+2]-bgB) < 80) d[i+3] = 0;
        }
        ctx.putImageData(imgData, 0, 0);
      } else {
        // Draw with clip shape
        ctx.save();
        if (shape === 'circle') {
          ctx.beginPath(); ctx.arc(size/2, size/2, size/2, 0, Math.PI*2); ctx.clip();
        } else if (shape === 'rect-round') {
          const rr = 12;
          ctx.beginPath(); ctx.moveTo(rr,0); ctx.lineTo(size-rr,0); ctx.quadraticCurveTo(size,0,size,rr);
          ctx.lineTo(size,size-rr); ctx.quadraticCurveTo(size,size,size-rr,size);
          ctx.lineTo(rr,size); ctx.quadraticCurveTo(0,size,0,size-rr); ctx.lineTo(0,rr); ctx.quadraticCurveTo(0,0,rr,0); ctx.closePath(); ctx.clip();
        } else if (shape === 'square-round') {
          const sq = 8;
          ctx.beginPath(); ctx.roundRect ? ctx.roundRect(0,0,size,size,sq) : (ctx.rect(0,0,size,size)); ctx.clip();
        }
        // Draw image centered/cropped
        const ar = img.width / img.height;
        let sw, sh, sx, sy;
        if (ar > 1) { sh = img.height; sw = sh; sx = (img.width-sw)/2; sy = 0; }
        else { sw = img.width; sh = sw; sx = 0; sy = (img.height-sh)/2; }
        ctx.drawImage(img, sx, sy, sw, sh, 0, 0, size, size);
        ctx.restore();
        
        // Border
        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
        ctx.lineWidth = 3;
        if (shape === 'circle') { ctx.beginPath(); ctx.arc(size/2,size/2,size/2-1.5,0,Math.PI*2); ctx.stroke(); }
      }
      
      const src = canvas.toDataURL('image/png');
      
      // Save sticker
      const entryKey = String(_dps_targetEntryId);
      if (!_db_pageStickers[entryKey]) _db_pageStickers[entryKey] = [];
      _db_pageStickers[entryKey].push({ id: Date.now(), src, x: 30, y: 40, w: 80, h: 80 });
      _dbSavePageStickers();
      
      statusEl.textContent = '贴纸已添加！';
      setTimeout(() => {
        diaryCloseImgStickerModal();
        _renderPageStickers(parseInt(entryKey));
      }, 600);
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function _renderPageStickers(entryId) {
  // Remove old sticker layer
  const pageEl = document.getElementById('diaryCurrentPage');
  if (!pageEl) return;
  let stickerLayer = pageEl.querySelector('.diary-page-sticker-layer');
  if (stickerLayer) stickerLayer.remove();
  
  const stickers = _db_pageStickers[String(entryId)] || [];
  if (stickers.length === 0) return;
  
  stickerLayer = document.createElement('div');
  stickerLayer.className = 'diary-page-sticker-layer';
  stickerLayer.style.cssText = 'position:absolute;inset:0;pointer-events:none;z-index:5;';
  
  stickers.forEach((st, idx) => {
    const el = document.createElement('div');
    el.className = 'diary-page-sticker';
    el.style.cssText = `left:${st.x}%;top:${st.y}%;width:${st.w}px;height:${st.h}px;pointer-events:all;`;
    el.innerHTML = `<img src="${st.src}" style="width:100%;height:100%;object-fit:contain;display:block;" draggable="false">
      <div class="diary-sticker-delete" onclick="diaryDeletePageSticker(${entryId},${idx})" title="删除">&#x2715;</div>
      <div class="diary-sticker-resize"></div>`;
    
    // Make draggable
    _makeDraggable(el, (pct_x, pct_y) => {
      st.x = pct_x; st.y = pct_y;
      _dbSavePageStickers();
    });
    
    // Make resizable
    const resizeHandle = el.querySelector('.diary-sticker-resize');
    _makeResizable(el, resizeHandle, (w, h) => {
      st.w = w; st.h = h;
      _dbSavePageStickers();
    });
    
    stickerLayer.appendChild(el);
  });
  
  pageEl.appendChild(stickerLayer);
}

function diaryDeletePageSticker(entryId, idx) {
  const key = String(entryId);
  if (!_db_pageStickers[key]) return;
  _db_pageStickers[key].splice(idx, 1);
  _dbSavePageStickers();
  _renderPageStickers(entryId);
}

// ─────────────────────────────────────────────────────────────
//  DRAG & RESIZE HELPERS
// ─────────────────────────────────────────────────────────────
function _makeDraggable(el, onMove) {
  // onMove(new_pct_x, new_pct_y) - percentages relative to offsetParent
  let startClientX, startClientY, startPctX, startPctY;

  const onStart = (e) => {
    if (e.target.classList.contains('diary-sticker-resize') ||
        e.target.classList.contains('diary-sticker-delete')) return;
    e.preventDefault(); e.stopPropagation();
    const touch = e.touches ? e.touches[0] : e;
    startClientX = touch.clientX;
    startClientY = touch.clientY;
    startPctX = parseFloat(el.style.left) || 0;
    startPctY = parseFloat(el.style.top) || 0;
    document.addEventListener('mousemove', onDrag);
    document.addEventListener('mouseup', onEnd);
    document.addEventListener('touchmove', onDrag, {passive: false});
    document.addEventListener('touchend', onEnd);
  };

  const onDrag = (e) => {
    e.preventDefault();
    const touch = e.touches ? e.touches[0] : e;
    const parent = el.offsetParent || el.parentElement;
    const pw = parent ? parent.offsetWidth : 300;
    const ph = parent ? parent.offsetHeight : 400;
    const dxPct = (touch.clientX - startClientX) / pw * 100;
    const dyPct = (touch.clientY - startClientY) / ph * 100;
    const nx = Math.min(92, Math.max(0, startPctX + dxPct));
    const ny = Math.min(92, Math.max(0, startPctY + dyPct));
    el.style.left = nx + '%';
    el.style.top = ny + '%';
    onMove(nx, ny);
  };

  const onEnd = () => {
    document.removeEventListener('mousemove', onDrag);
    document.removeEventListener('mouseup', onEnd);
    document.removeEventListener('touchmove', onDrag);
    document.removeEventListener('touchend', onEnd);
  };

  el.addEventListener('mousedown', onStart);
  el.addEventListener('touchstart', onStart, {passive: false});
}

function _makeResizable(el, handle, onResize) {
  let startX, startY, startW, startH;
  const onStart = (e) => {
    e.preventDefault(); e.stopPropagation();
    const touch = e.touches ? e.touches[0] : e;
    startX = touch.clientX; startY = touch.clientY;
    startW = el.offsetWidth; startH = el.offsetHeight;
    document.addEventListener('mousemove', onDrag); document.addEventListener('mouseup', onEnd);
    document.addEventListener('touchmove', onDrag, {passive:false}); document.addEventListener('touchend', onEnd);
  };
  const onDrag = (e) => {
    e.preventDefault();
    const touch = e.touches ? e.touches[0] : e;
    const w = Math.max(30, startW + touch.clientX - startX);
    const h = Math.max(30, startH + touch.clientY - startY);
    el.style.width = w + 'px'; el.style.height = h + 'px';
    onResize(w, h);
  };
  const onEnd = () => {
    document.removeEventListener('mousemove', onDrag); document.removeEventListener('mouseup', onEnd);
    document.removeEventListener('touchmove', onDrag); document.removeEventListener('touchend', onEnd);
  };
  handle.addEventListener('mousedown', onStart);
  handle.addEventListener('touchstart', onStart, {passive:false});
}

