function diaryMainBgSelected(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    localStorage.setItem(KEY_MAIN_BG, e.target.result);
    _applyDiaryMainBg();
  };
  reader.readAsDataURL(file);
  event.target.value = '';
}
function diaryRemoveMainBg() {
  localStorage.removeItem(KEY_MAIN_BG);
  _applyDiaryMainBg();
}

function _diaryModuleInit() {
  _dbLoadAll();
  _applyDiaryMainBg();
  // Hook into openApp for diaryPage
  const origOpenApp = window.openApp;
  if (typeof origOpenApp === 'function') {
    window.openApp = function(pageId) {
      origOpenApp.apply(this, arguments);
      if (pageId === 'diaryPage') {
        setTimeout(() => { renderDiaryShelf(); _applyDiaryMainBg(); }, 50);
      }
      try { if (typeof updateFabVisibility === 'function') updateFabVisibility(); } catch(e) {}
    };
  }
  
  // Also hook into switchPage
  const origSwitchPage = window.switchPage;
  if (typeof origSwitchPage === 'function') {
    window.switchPage = function(pageId, navEl, evt) {
      origSwitchPage.apply(this, arguments);
      if (pageId === 'diaryPage') {
        setTimeout(() => { renderDiaryShelf(); _applyDiaryMainBg(); }, 50);
      }
      try { if (typeof updateFabVisibility === 'function') updateFabVisibility(); } catch(e) {}
    };
  }
  
  // Initial render if diary page is already shown
  if (document.getElementById('diaryPage') && document.getElementById('diaryPage').classList.contains('active')) {
    renderDiaryShelf();
  }
}

