  const dateOptions = _monoCollectChatDateOptions(p);
  const firstDated = dateOptions.find(function(key) { return key !== 'undated'; }) || '';
  const lastDated = dateOptions.filter(function(key) { return key !== 'undated'; }).slice(-1)[0] || firstDated;
  const chipsHtml = dateOptions.length
    ? dateOptions.map(function(key) {
        return '<button type="button" onclick="window.monoApplyChatDatePreset && window.monoApplyChatDatePreset(\'' + key + '\')" style="border:none;background:#f4f4f4;color:#333;padding:7px 10px;border-radius:999px;font-size:10px;cursor:pointer;font-family:inherit;">' + _escHtml(_monoMsgDateLabel(key)) + '</button>';
      }).join('')
    : '<div style="font-size:10px;color:#999;">当前还没有带日期的聊天室记录。</div>';
  const overlay = document.createElement('div');
  overlay.id = 'monoChatCleanupModal';
  overlay.className = 'confirm-overlay';
  overlay.innerHTML = ''
    + '<div class="confirm-box" style="max-width:430px;width:min(430px,100%);max-height:calc(100vh - 32px);overflow-y:auto;padding:18px 18px 16px;border-radius:18px;">'
    + '<h3 style="display:flex;align-items:center;gap:7px;margin-bottom:10px;"><i class="fas fa-calendar-check" style="color:#1a1a1a;"></i>聊天室记录管理</h3>'
    + '<p style="line-height:1.7;margin-bottom:12px;">这里只会处理 <b>' + _escHtml(p.name) + '</b> 的线上聊天室消息，只会清空聊天内容本身，不会影响黑盒、日记、线下剧情、角色设定或角色本身。</p>'
    + '<div style="background:linear-gradient(180deg,#fafafa 0%,#f6f6f6 100%);border:1px solid #ececec;border-radius:14px;padding:12px 12px 10px;margin:10px 0 14px;text-align:left;">'
    + '<div style="font-size:10px;color:#999;letter-spacing:1px;text-transform:uppercase;margin-bottom:8px;">按日期范围处理</div>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">'
    + '<label style="display:flex;flex-direction:column;gap:5px;font-size:10px;color:#888;">开始日期<input id="monoChatDateStart" type="date" value="' + firstDated + '" onchange="window._monoUpdateChatRangeSummary && window._monoUpdateChatRangeSummary()" style="width:100%;box-sizing:border-box;border:1px solid #ddd;border-radius:10px;padding:9px 10px;font-size:12px;font-family:inherit;background:#fff;"></label>'
    + '<label style="display:flex;flex-direction:column;gap:5px;font-size:10px;color:#888;">结束日期<input id="monoChatDateEnd" type="date" value="' + lastDated + '" onchange="window._monoUpdateChatRangeSummary && window._monoUpdateChatRangeSummary()" style="width:100%;box-sizing:border-box;border:1px solid #ddd;border-radius:10px;padding:9px 10px;font-size:12px;font-family:inherit;background:#fff;"></label>'
    + '</div>'
    + '<label style="display:flex;align-items:center;gap:7px;font-size:11px;color:#666;margin-top:10px;cursor:pointer;"><input id="monoChatIncludeUndated" type="checkbox" onchange="window._monoUpdateChatRangeSummary && window._monoUpdateChatRangeSummary()" style="accent-color:#1a1a1a;">包含无日期消息</label>'
