        avatar: settings.avatar || meta.avatar || makeAvatar((settings.name || meta.name || '导').charAt(0), '#f2f2f2', '#1a1a1a'),
        history: Array.isArray(data.history) ? data.history : [],
        memoryCore: settings.memoryCore || [],
        diaryIncludeOfflineMemory: settings.diaryIncludeOfflineMemory !== false,
        momentsIncludeOfflineMemory: settings.momentsIncludeOfflineMemory !== false,
        lastHeartVoice: settings.lastHeartVoice || null,
        heartVoiceGenerateEnabled: settings.heartVoiceGenerateEnabled !== false,
        chatTheme: normalizeChatTheme(settings.chatTheme || 'default'),
        frostedTitleColor: settings.frostedTitleColor || '#ffffff',
