  function monoHeartHistoryKey() {
    return window.MONO_HEART_VOICE_HISTORY_KEY || HEART_HISTORY_KEY_FALLBACK;
  }

  function monoGetHeartItems() {
    const all = monoSafeJson(localStorage.getItem(monoHeartHistoryKey()), []);
    const cutoff = Date.now() - 3 * 24 * 60 * 60 * 1000;
    return (Array.isArray(all) ? all : []).filter(function(item) {
      return item && (!item.ts || item.ts >= cutoff);
    });
  }

  function monoFmtTs(ts) {
    const d = new Date(ts || Date.now());
    if (Number.isNaN(d.getTime())) return '';
    const now = new Date();
    const sameDay = d.toDateString() === now.toDateString();
    const hm = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
    return sameDay ? ('今天 ' + hm) : ((d.getMonth() + 1) + '/' + d.getDate() + ' ' + hm);
  }

  function monoDateKey(ts) {
    if (!ts) return 'undated';
    const d = new Date(ts);
    if (Number.isNaN(d.getTime())) return 'undated';
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return y + '-' + m + '-' + day;
  }

  function monoDateLabel(key) {
    if (!key || key === 'undated') return '无日期消息';
    return key;
  }

  function monoMessageText(message, persona) {
    if (!message) return '';
    if (message.msgType === 'sticker') {
      const sender = message.role === 'user' ? monoGetUserName() : ((persona && persona.name) || '角色');
      const caption = String(message.caption || '').trim();
      return caption ? ('[' + sender + '发送了表情包：' + caption + ']') : ('[' + sender + '发送了表情包]');
    }
    if (message.msgType === 'image') return '[图片] ' + String(message.imageCaption || message.content || '').trim();
    if (message.msgType === 'voice') return '[语音] ' + String(message.transcript || message.content || '').trim();
    if (message.msgType === 'forwarded_帖子') return '[转发] ' + String((message.fwdData && message.fwdData.content) || message.content || '').trim();
    if (message.msgType === 'social_share_card') return (typeof window !== 'undefined' && typeof window.monoBuildSocialShareHistoryText === 'function') ? window.monoBuildSocialShareHistoryText(message.socialShareData || {}) : ('[社媒转发] ' + String(message.content || '').trim());
    if (message.msgType === 'takeout_card') return '[外卖卡片]';
    if (message.msgType === 'location_card') return (typeof _buildLocationHistoryText === 'function') ? _buildLocationHistoryText(message.locationData || {}, message.role) : ('[定位分享] ' + String(message.content || '').trim());
    if (message.msgType === 'order_notify' || message.msgType === 'pay_request' || message.msgType === 'receive_notify') {
      return (typeof _buildOrderHistoryText === 'function') ? _buildOrderHistoryText(message) : String(message.content || '').trim();
    }
    return String(message.content || '').trim();
  }

  function monoDownloadText(filename, text) {
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(function() { URL.revokeObjectURL(url); }, 1000);
  }

  function monoDownloadJson(filename, data) {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(function() { URL.revokeObjectURL(url); }, 1000);
  }

