    if (!persona) {
      alert('请先打开一个角色聊天室。');
      return;
    }
    const base = monoBuildPersonaExportBase(persona);
    let out;
    if (mode === 'settings') out = { type: 'mono_persona_settings', version: base.version, meta: base.meta, settings: base.settings };
    else if (mode === 'chat') out = { type: 'mono_persona_chat', version: base.version, meta: base.meta, history: base.history, offlineSessions: base.offlineSessions };
    else out = { type: 'mono_persona_bundle', version: base.version, meta: base.meta, settings: base.settings, history: base.history, offlineSessions: base.offlineSessions };
    monoDownloadJson((persona.name || '角色') + '_' + mode + '.json', out);
