  window.monoImportPersonaPackage = function(event) {
    const input = event && event.target;
    const file = input && input.files && input.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function(loadEvent) {
      try {
        const data = monoSafeJson(String(loadEvent.target && loadEvent.target.result || ''), null);
        if (!data) throw new Error('文件内容为空或格式无效');
        const list = monoGetPersonas();
        const persona = monoBuildImportedPersona(data);
        list.push(persona);
        monoImportOfflineSessions(persona.id, data.offlineSessions);
        try {
          if (typeof currentId !== 'undefined') currentId = persona.id;
        } catch (err) {
          window.currentId = persona.id;
        }
        monoSaveAll();
        monoRenderAll();
        monoSelectPersonaById(persona.id);
        monoCloseChatModal();
        const addModal = document.getElementById('monoAddPersonaModal');
        if (addModal) addModal.style.display = 'none';
        alert('已导入为新角色，并创建对应聊天室。');
      } catch (err) {
        alert('导入失败：' + err.message);
      } finally {
        if (input) input.value = '';
      }
    };
    reader.readAsText(file);
  };

