// ===== music-mini-bar-drag =====

(function() {
  'use strict';
  var bar, isDragging = false, startX, startY, startLeft, startTop, isFloating = false;
  var SNAP_THRESHOLD = 40; // px from edge to snap back

  function initDrag() {
    bar = document.getElementById('musicMiniBar');
    if (!bar) return;

    bar.addEventListener('mousedown', onDragStart, { passive: false });
    bar.addEventListener('touchstart', onDragStart, { passive: false });
    document.addEventListener('mousemove', onDragMove, { passive: false });
    document.addEventListener('touchmove', onDragMove, { passive: false });
    document.addEventListener('mouseup', onDragEnd);
    document.addEventListener('touchend', onDragEnd);
  }

  function getBarControls() {
    // Buttons inside the bar should not start drag
    return bar ? bar.querySelectorAll('button, input, select, a') : [];
  }

  function onDragStart(e) {
    bar = document.getElementById('musicMiniBar');
    if (!bar || !bar.classList.contains('visible')) return;
    var target = e.target;
    // Don't drag if clicking buttons
    var controls = getBarControls();
    for (var i = 0; i < controls.length; i++) {
      if (controls[i] === target || controls[i].contains(target)) return;
    }
    e.preventDefault();
    isDragging = true;
    var touch = e.touches ? e.touches[0] : e;
    startX = touch.clientX;
    startY = touch.clientY;
    var rect = bar.getBoundingClientRect();
    startLeft = rect.left;
    startTop = rect.top;
    bar.classList.add('dragging');
    // Transition to absolute positioning for free movement
    if (!isFloating) {
      bar.style.left = startLeft + 'px';
      bar.style.top = startTop + 'px';
      bar.style.bottom = 'auto';
      bar.style.right = 'auto';
      bar.style.width = rect.width + 'px';
    }
  }

  function onDragMove(e) {
    if (!isDragging) return;
    e.preventDefault();
    var touch = e.touches ? e.touches[0] : e;
    var dx = touch.clientX - startX;
    var dy = touch.clientY - startY;
    var newLeft = startLeft + dx;
    var newTop = startTop + dy;
    // Clamp to viewport
    var vw = window.innerWidth, vh = window.innerHeight;
    var barW = bar.offsetWidth, barH = bar.offsetHeight;
    newLeft = Math.max(0, Math.min(vw - barW, newLeft));
    newTop = Math.max(0, Math.min(vh - barH, newTop));
    bar.style.left = newLeft + 'px';
    bar.style.top = newTop + 'px';
  }

  function onDragEnd(e) {
    if (!isDragging) return;
    isDragging = false;
    bar.classList.remove('dragging');
    var rect = bar.getBoundingClientRect();
    var vw = window.innerWidth, vh = window.innerHeight;
    var distBottom = vh - (rect.top + rect.height);
    var distLeft = rect.left;
    var distRight = vw - (rect.left + rect.width);
    var distTop = rect.top;
    // Snap back to bottom bar if close to bottom
    if (distBottom < SNAP_THRESHOLD && rect.left < 20) {
      // Snap back to original full-width bottom bar
      bar.style.left = '0';
      bar.style.right = '0';
      bar.style.top = 'auto';
      bar.style.bottom = '60px';
      bar.style.width = '';
      bar.classList.remove('floating');
      isFloating = false;
    } else {
      // Float
      bar.classList.add('floating');
      isFloating = true;
      // Snap horizontally to nearest edge if very close
      if (distLeft < 10) bar.style.left = '8px';
      if (distRight < 10) bar.style.left = (vw - bar.offsetWidth - 8) + 'px';
      if (distTop < 10) bar.style.top = '8px';
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initDrag);
  } else {
    setTimeout(initDrag, 300);
  }
  // Re-init after music bar becomes visible
  var _mmObs = new MutationObserver(function() { if (!bar) initDrag(); });
  _mmObs.observe(document.body, { childList: true, subtree: false });
})();


