// ===== MONO PATCH v3: NPC user-contact relationship awareness =====
(function(){
  function esc(v){
    try { return (typeof monoRolePhoneEsc === 'function') ? monoRolePhoneEsc(v) : String(v == null ? '' : v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
    catch(e){ return String(v == null ? '' : v); }
  }
  function loadPersonas(){
    try { if (typeof personas !== 'undefined' && Array.isArray(personas)) return personas; } catch(e){}
    try { return JSON.parse(localStorage.getItem('mono_personas') || '[]') || []; } catch(e){ return []; }
  }
  function savePersonas(list){
    try { localStorage.setItem('mono_personas', JSON.stringify(list || [])); } catch(e) {}
    try { if (typeof personas !== 'undefined' && Array.isArray(personas)) { personas.length = 0; (list || []).forEach(function(p){ personas.push(p); }); } } catch(e) {}
  }
  function nextPersonaId(){
    return 'roleNpcPersona_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
  }
  function userMaskNodeId(maskId){ return '__user_mask__:' + String(maskId || ''); }
  function roleNpcNodeId(npcId){
    try { if (typeof monoRoleNpcNodeId === 'function') return monoRoleNpcNodeId(npcId); } catch(e) {}
    return '__npc__:' + String(npcId || '');
  }
  function getMask(maskId){
    if (!maskId) return null;
    try { if (typeof monoGetUserMask === 'function') return monoGetUserMask(maskId); } catch(e) {}
    try { var masks = JSON.parse(localStorage.getItem('mono_user_masks') || '[]') || []; return masks.find(function(m){ return String(m.id) === String(maskId); }) || null; } catch(e) { return null; }
  }
  function resolveNodeName(nodeId, fallback){
    try { if (typeof _mwResolveNodeName === 'function') return _mwResolveNodeName(nodeId, fallback || '关联对象'); } catch(e) {}
    return fallback || String(nodeId || '关联对象');
  }
  function compactLines(lines){
    var seen = {};
    return (lines || []).map(function(x){ return String(x || '').trim(); }).filter(function(x){ if(!x || seen[x]) return false; seen[x]=true; return true; });
  }
  function relationLine(e){
    if (!e) return '';
    var a = e.a || resolveNodeName(e.aId, '对象A');
    var b = e.b || resolveNodeName(e.bId, '对象B');
    var label = e.label || '有关联';
    var detail = e.detail ? ('：' + e.detail) : '';
    return a + ' ↔ ' + b + '｜' + label + detail;
  }
  function getRelationshipEntries(ownerPersona, npc){
    var rels=[];
    try { if (typeof mwGetRelEntries === 'function') rels = mwGetRelEntries() || []; } catch(e) { rels=[]; }
    var ownerId = String(ownerPersona && ownerPersona.id || '');
    var npcNode = roleNpcNodeId(npc && npc.id);
    var userNodes = ['__user__'];
    if (ownerPersona && ownerPersona.userMaskId) userNodes.push(userMaskNodeId(ownerPersona.userMaskId));
    if (Array.isArray(npc && npc.linkNotes)) {
      npc.linkNotes.forEach(function(link){
        if (link && link.nodeId && (String(link.nodeType || '').indexOf('mask') >= 0 || String(link.nodeId).indexOf('__user_mask__:') === 0 || String(link.nodeId) === '__user__')) userNodes.push(String(link.nodeId));
      });
    }
    var ownerNpc=[], npcUser=[], ownerUser=[], indirect=[];
    rels.forEach(function(e){
      var a=String(e.aId||''), b=String(e.bId||'');
      if (!a && e.a && String(e.a) === String(ownerPersona && ownerPersona.name)) a=ownerId;
      if (!b && e.b && String(e.b) === String(ownerPersona && ownerPersona.name)) b=ownerId;
      var hasOwner = a===ownerId || b===ownerId;
      var hasNpc = a===npcNode || b===npcNode;
      var hasUser = userNodes.indexOf(a)>=0 || userNodes.indexOf(b)>=0;
      if (hasOwner && hasNpc) ownerNpc.push(relationLine(e));
      else if (hasNpc && hasUser) npcUser.push(relationLine(e));
      else if (hasOwner && hasUser) ownerUser.push(relationLine(e));
      else if (hasNpc || hasOwner || hasUser) indirect.push(relationLine(e));
    });
    return { ownerNpc: compactLines(ownerNpc), npcUser: compactLines(npcUser), ownerUser: compactLines(ownerUser), indirect: compactLines(indirect).slice(0,8) };
  }
  function buildNpcUserRelationContext(ownerPersona, npc){
    ownerPersona = ownerPersona || {};
    npc = npc || {};
    var mask = getMask(ownerPersona.userMaskId || '');
    var userLabel = mask ? ('用户面具「' + (mask.name || '未命名面具') + '」') : '默认用户';
    var lines = [];
    lines.push('【用户联络人关系认知】');
    lines.push('这个 NPC 是从角色「' + (ownerPersona.name || npc.ownerPersonaName || '某角色') + '」的角色微信 / 关系图中添加到用户联络人列表的。');
    lines.push('当前用户身份：' + userLabel + '。NPC 在用户聊天室里必须按这个用户身份理解用户，不要把不同用户面具混成同一个人。');
    if (mask) {
      var maskText = ((mask.bio || '') + ' ' + (mask.personaSpec || '')).trim();
      if (maskText) lines.push('该用户面具设定：' + maskText);
    }
    lines.push('NPC 与来源角色「' + (ownerPersona.name || npc.ownerPersonaName || '某角色') + '」的关系：' + (npc.relationSummary || '有关联') + (npc.relationDetail ? ' — ' + npc.relationDetail : ''));
    if (Array.isArray(npc.linkNotes) && npc.linkNotes.length) {
      lines.push('NPC 已知直接关联：');
      npc.linkNotes.forEach(function(link){
        if (!link) return;
        lines.push('· ' + (link.name || resolveNodeName(link.nodeId, '关联对象')) + '｜' + (link.label || '有关联') + (link.detail ? '：' + link.detail : ''));
      });
    }
    var rel = getRelationshipEntries(ownerPersona, npc);
    if (rel.ownerUser.length) { lines.push('用户 ↔ 来源角色关系：'); rel.ownerUser.forEach(function(x){ lines.push('· ' + x); }); }
    if (rel.npcUser.length) { lines.push('NPC ↔ 用户直接关系：'); rel.npcUser.forEach(function(x){ lines.push('· ' + x); }); }
    if (rel.ownerNpc.length) { lines.push('NPC ↔ 来源角色关系图记录：'); rel.ownerNpc.forEach(function(x){ lines.push('· ' + x); }); }
    if (!rel.npcUser.length) lines.push('如果关系图没有写明 NPC 与用户的直接关系，NPC 也必须通过「用户 ↔ 来源角色 ↔ NPC」这条间接关系理解用户和自己的联系。');
    if (rel.indirect.length) { lines.push('其他可能影响称呼和态度的间接关系：'); rel.indirect.forEach(function(x){ lines.push('· ' + x); }); }
    lines.push('对话规则：NPC 和用户聊天时，要记得用户与来源角色的关系、NPC 与来源角色的关系，以及 NPC 与用户可能是直接或间接关系；称呼、态度、边界感和记忆都要跟这些关系一致。');
    return compactLines(lines).join('\n');
  }
  function personaTextWithContext(ownerPersona, npc, context){
    var base = String(npc && npc.persona || '').trim() || (String(npc && npc.name || 'NPC') + '是' + String(ownerPersona && ownerPersona.name || '该角色') + '世界关系图中的NPC。身份：' + String(npc && npc.identity || '未填写') + '。关系：' + String(npc && (npc.relationSummary || npc.relationDetail) || '有关联') + '。');
    base = base.replace(/\n*【用户联络人关系认知】[\s\S]*$/,'').trim();
    return base + '\n\n' + context;
  }
  function isNpcInUserContacts(npc){
    if (!npc || !npc.id) return false;
    return loadPersonas().some(function(p){ return p && String(p._roleNpcId || '') === String(npc.id); });
  }
  window.monoRoleNpcUserContactButtonHtml = function(ownerPersona, npc){
    var added = isNpcInUserContacts(npc);
    var ownerId = ownerPersona && ownerPersona.id ? String(ownerPersona.id) : '';
    var npcId = npc && npc.id ? String(npc.id) : '';
    return '<button class="role-phone-mini-btn" onclick="event.stopPropagation(); monoToggleRoleNpcUserContact(\'' + esc(ownerId) + '\', \'' + esc(npcId) + '\')">' + (added ? '移出用户联络人' : '加到用户联络人') + '</button>';
  };
  window.monoToggleRoleNpcUserContact = function(ownerPersonaId, npcId){
    var ownerPersona = null, npc = null;
    try { ownerPersona = (typeof monoGetPersonaById === 'function') ? monoGetPersonaById(ownerPersonaId) : null; } catch(e) {}
    try { npc = (typeof monoFindRoleNpcById === 'function') ? monoFindRoleNpcById(npcId) : null; } catch(e) {}
    if (!ownerPersona || !npc) return;
    if (isNpcInUserContacts(npc)) {
      try { window.monoRemoveRoleNpcUserContact(npc); } catch(e) {}
    } else {
      try { window.monoSyncRoleNpcToUserContact(ownerPersona, npc); } catch(e) { console.warn('[NPC加入用户联络人失败]', e); }
    }
    try { if (typeof monoOpenRolePhone === 'function') monoOpenRolePhone(ownerPersona.id); } catch(e) { try { if (typeof monoRenderRolePhonePage === 'function') monoRenderRolePhonePage(ownerPersona); } catch(_) {} }
    try { if (typeof renderContactList === 'function') renderContactList(); } catch(e) {}
  };
  window.monoSyncRoleNpcToUserContact = function(ownerPersona, npc){
    if (!ownerPersona || !npc || !npc.id || !npc.name) return null;
    var list = loadPersonas();
    var idx = list.findIndex(function(p){ return p && String(p._roleNpcId || '') === String(npc.id); });
    var old = idx >= 0 ? list[idx] : null;
    var id = old && old.id ? old.id : nextPersonaId();
    var histKey = 'mono_hist_' + id;
    var directHist = [];
    try { directHist = JSON.parse(localStorage.getItem(histKey) || '[]') || []; } catch(e) { directHist = []; }
    if (!Array.isArray(directHist)) directHist = [];
    var relationContext = buildNpcUserRelationContext(ownerPersona, npc);
    var next = Object.assign({}, old || {}, {
      id: id,
      name: String(npc.name || '').trim(),
      avatar: npc.avatar || (old && old.avatar) || '',
      persona: personaTextWithContext(ownerPersona, npc, relationContext),
      memoryCore: (old && old.memoryCore) || '',
      gender: (old && old.gender) || '',
      userMaskId: ownerPersona.userMaskId || (old && old.userMaskId) || '',
      _roleNpcPersona: true,
      _roleNpcId: String(npc.id),
      _roleNpcOwnerId: String(ownerPersona.id || npc.ownerPersonaId || ''),
      _roleNpcOwnerName: String(ownerPersona.name || npc.ownerPersonaName || ''),
      _roleNpcIdentity: String(npc.identity || ''),
      _roleNpcRelationSummary: String(npc.relationSummary || ''),
      _roleNpcRelationDetail: String(npc.relationDetail || ''),
      _roleNpcLinkNotes: Array.isArray(npc.linkNotes) ? npc.linkNotes : [],
      _roleNpcUserRelationContext: relationContext,
      updatedAt: Date.now(),
      history: '__hist_ref__'
    });
    if (idx >= 0) list[idx] = next; else list.push(next);
    savePersonas(list);
    // Replace the old relationship-awareness context instead of stacking duplicates.
    directHist = directHist.filter(function(m){ return !(m && m._roleNpcUserRelationContext === true); });
    directHist.unshift({
      role: 'system',
      content: relationContext,
      _hiddenContext: true,
      _roleNpcUserRelationContext: true,
      timestamp: Date.now()
    });
    var roomId = npc.roomId || '';
    if (!roomId && typeof monoEnsureRoleNpcRoom === 'function') {
      try { roomId = monoEnsureRoleNpcRoom(ownerPersona, npc); } catch(e) {}
    }
    if (roomId && typeof ccGetHistory === 'function') {
      try {
        var ccHist = ccGetHistory(roomId) || [];
        directHist = directHist.filter(function(m){ return !(m && m._roleNpcRoomMirrorId === roomId); });
        if (ccHist.length) {
          directHist.push({
            role: 'user',
            content: '【NPC记忆同步｜来自角色自己的联络人聊天室】\n你曾经在「' + (ownerPersona.name || '某角色') + '」的角色微信 有用户参与的群聊室里发生过以下对话。你在和用户聊天时也必须记得这些经历、关系和说过的话，并结合上面的用户/角色/NPC关系理解用户。\n' + ccHist.map(function(m){ return (m.sender || '未知') + '：' + ((m.content || m.transcript || '').toString()); }).join('\n'),
            _hiddenContext: true,
            _roleNpcRoomMemory: true,
            _roleNpcRoomMirrorId: roomId,
            timestamp: Date.now()
          });
        }
      } catch(e) {}
    }
    try { localStorage.setItem(histKey, JSON.stringify(directHist)); } catch(e) {}
    return next;
  };
})();


