// ===== mono-role-wechat-v4-hotfix =====

(function(){
  'use strict';
  function esc(value){
    return String(value == null ? '' : value)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  }
  function getPersonasSafe(){
    try { if (typeof loadPersonas === 'function') return loadPersonas() || []; } catch(e) {}
    try { if (Array.isArray(window.personas)) return window.personas; } catch(e) {}
    try { if (typeof personas !== 'undefined' && Array.isArray(personas)) return personas; } catch(e) {}
    return [];
  }
  function getPersonaByIdSafe(id){
    var sid = String(id == null ? '' : id);
    try { if (typeof monoGetPersonaById === 'function') { var p0 = monoGetPersonaById(sid); if (p0) return p0; } } catch(e) {}
    return getPersonasSafe().find(function(p){ return p && String(p.id) === sid; }) || null;
  }
  function cleanupOldRoleChatDrawer(){
    var sec = document.getElementById('ccRoomDrawerSection');
    if (sec && sec.parentNode) sec.parentNode.removeChild(sec);
    // Extra safety: if an older script recreated or rendered a section, hide anything headed as 角色聊天室 inside the main contacts drawer.
    var drawer = document.getElementById('contactsDrawer');
    if (!drawer) return;
    Array.prototype.slice.call(drawer.querySelectorAll('#ccRoomDrawerSection')).forEach(function(x){ if (x && x.parentNode) x.parentNode.removeChild(x); });
  }
  window.renderCcRoomDrawer = function(){ cleanupOldRoleChatDrawer(); };

  var originalOpenRolePhonePage = window.monoOpenRolePhonePage;
  function forceOpenRolePhonePage(ownerPersonaId){
    cleanupOldRoleChatDrawer();
    var drawer = document.getElementById('contactsDrawer');
    if (drawer) drawer.classList.remove('open');
    var owner = getPersonaByIdSafe(ownerPersonaId);
    if (!owner) {
      try { alert('没有找到这个角色，无法打开角色微信。'); } catch(e) {}
      return;
    }
    try {
      if (typeof originalOpenRolePhonePage === 'function') {
        originalOpenRolePhonePage.call(window, owner.id);
      } else {
        if (typeof monoRolePhoneEnsureUi === 'function') monoRolePhoneEnsureUi();
        if (window._rolePhoneState) window._rolePhoneState.ownerPersonaId = String(owner.id);
        if (typeof monoRenderRolePhonePage === 'function') monoRenderRolePhonePage();
      }
    } catch(err) {
      console.warn('[角色微信打开失败，使用备用打开方式]', err);
      try {
        if (typeof monoRolePhoneEnsureUi === 'function') monoRolePhoneEnsureUi();
        if (window._rolePhoneState) window._rolePhoneState.ownerPersonaId = String(owner.id);
        if (typeof monoRenderRolePhonePage === 'function') monoRenderRolePhonePage();
      } catch(e2) { console.warn('[角色微信备用打开失败]', e2); }
    }
    setTimeout(function(){
      var page = document.getElementById('rolePhonePage');
      if (page) {
        page.classList.add('open');
        page.style.display = 'flex';
        page.style.zIndex = '99999';
        page.style.pointerEvents = 'auto';
      }
    }, 0);
  }
  window.monoOpenRolePhonePage = forceOpenRolePhonePage;
  window.openRolePhonePage = forceOpenRolePhonePage;

  window.closeRolePhonePage = function(){
    var page = document.getElementById('rolePhonePage');
    if (page) { page.classList.remove('open'); page.style.display = 'none'; }
  };

  window.renderRolePhoneDrawer = function(){
    cleanupOldRoleChatDrawer();
    var section = document.getElementById('rolePhoneDrawerSection');
    if (!section) return;
    var list = getPersonasSafe().filter(function(p){ return p && !p._roleNpcPersona; });
    if (!list.length) { section.style.display = 'none'; section.innerHTML = ''; return; }
    var html = '<div style="padding:8px 16px 4px;display:flex;align-items:center;justify-content:space-between;">'
      + '<span style="font-size:9px;color:#888;text-transform:uppercase;letter-spacing:2px;font-weight:700;">特定角色</span>'
      + '<span style="font-size:9px;color:#bbb;">角色微信</span></div>';
    html += list.map(function(p){
      var npcCount = 0, threadCount = 0;
      try { if (typeof monoGetRoleNpcs === 'function') npcCount = (monoGetRoleNpcs(p.id) || []).length; } catch(e) {}
      try { if (typeof monoGetRolePhoneThreads === 'function') threadCount = (monoGetRolePhoneThreads(p) || []).length; } catch(e) {}
      var avatarHtml = p.avatar
        ? '<img src="' + esc(p.avatar) + '" class="contact-avatar">'
        : '<div class="contact-avatar" style="display:flex;align-items:center;justify-content:center;background:#5f5f6b;color:#fff;font-weight:700;">' + esc((String(p.name || '?').trim().charAt(0) || '?')) + '</div>';
      return '<div class="contact-item mono-role-phone-entry" data-role-phone-persona-id="' + esc(p.id) + '" style="padding:10px 14px;">'
        + avatarHtml
        + '<div style="flex:1;min-width:0;">'
        + '<div class="contact-name">' + esc(p.name || '未命名角色') + '</div>'
        + '<div class="contact-sub" style="font-size:11px;">聊天室 ' + threadCount + ' · NPC ' + npcCount + '</div>'
        + '</div>'
        + '<i class="fas fa-chevron-right" style="font-size:10px;color:#bbb;"></i>'
        + '</div>';
    }).join('');
    section.innerHTML = html;
    section.style.display = 'block';
  };

  document.addEventListener('click', function(evt){
    var item = evt.target && evt.target.closest ? evt.target.closest('[data-role-phone-persona-id]') : null;
    if (!item) return;
    evt.preventDefault();
    evt.stopPropagation();
    forceOpenRolePhonePage(item.getAttribute('data-role-phone-persona-id'));
  }, true);

  function boot(){
    cleanupOldRoleChatDrawer();
    try { window.renderRolePhoneDrawer(); } catch(e) {}
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot); else boot();
  setTimeout(boot, 200);
  setTimeout(boot, 1000);
})();


