/* MONO PATCH v5: 修复角色微信里的“新建角色聊天室”按钮没反应。
   原因：v4 为了强制打开角色微信，把 rolePhonePage 的 z-index 提到 99999；
   原本的新建聊天室弹窗 z-index 只有 9600，会被角色微信页面盖住。
   同时补上角色微信专用入口函数 monoOpenCcRoomDialogFromRolePhone。 */
(function(){
  'use strict';
  var rolePhoneRoomOwnerId = '';

  function getPersonasSafe(){
    try { if (typeof loadPersonas === 'function') return loadPersonas() || []; } catch(e) {}
    try { if (Array.isArray(window.personas)) return window.personas; } catch(e) {}
    try { if (typeof personas !== 'undefined' && Array.isArray(personas)) return personas; } catch(e) {}
    return [];
  }
  function getPersonaByIdSafe(id){
    var sid = String(id == null ? '' : id);
    try { if (typeof monoGetPersonaById === 'function') { var p0 = monoGetPersonaById(sid); if (p0) return p0; } } catch(e) {}
    return getPersonasSafe().find(function(p){ return p && String(p.id) === sid; }) || null;
  }
  function makeCcModalTopMost(){
    var modal = document.getElementById('ccNewRoomModal');
    if (modal) {
      modal.style.zIndex = '100020';
      modal.style.pointerEvents = 'auto';
    }
  }
  function preselectOwnerInRoomDialog(ownerPersona){
    if (!ownerPersona) return;
    var modal = document.getElementById('ccNewRoomModal');
    var list = document.getElementById('ccNewRoomMemberList');
    if (!modal || !list || modal.style.display === 'none') return;
    var inputs = Array.prototype.slice.call(list.querySelectorAll('input[type=checkbox]'));
    var ownerInput = inputs.find(function(chk){ return String(chk.value || '') === String(ownerPersona.name || ''); });
    if (!ownerInput) {
      // 如果原函数没有把该角色列出来，给用户一个明确提示，而不是看起来没反应。
      try { alert('这个角色暂时不能创建角色聊天室。请先在关系图里给该角色和另一位角色建立关系。'); } catch(e) {}
      return;
    }
    ownerInput.checked = true;
    ownerInput.disabled = true;
    ownerInput.setAttribute('data-role-phone-owner', '1');
    var label = ownerInput.closest('label');
    if (label) {
      label.style.borderColor = '#1a1a1a';
      label.style.background = '#f4f4f4';
      if (!label.querySelector('.mono-role-phone-owner-badge')) {
        var badge = document.createElement('div');
        badge.className = 'mono-role-phone-owner-badge';
        badge.textContent = '当前角色，已自动选择';
        badge.style.cssText = 'font-size:10px;color:#555;margin-top:3px;font-weight:700;';
        var meta = label.querySelector('div[style*="flex:1"]') || label;
        meta.appendChild(badge);
      }
    }
    var nameInput = document.getElementById('ccNewRoomName');
    if (nameInput && !nameInput.value.trim()) {
      nameInput.placeholder = ownerPersona.name + ' 和另一位角色的聊天室';
    }
    try {
      if (typeof _ccValidateRoomMemberSelection === 'function') _ccValidateRoomMemberSelection(list, mwGetRelEntries());
    } catch(e) {}
  }

  window.monoOpenCcRoomDialogFromRolePhone = function(ownerPersonaId){
    rolePhoneRoomOwnerId = String(ownerPersonaId == null ? '' : ownerPersonaId);
    var owner = getPersonaByIdSafe(rolePhoneRoomOwnerId);
    if (!owner) {
      try { alert('没有找到当前角色，无法新建角色聊天室。'); } catch(e) {}
      return;
    }
    try {
      if (typeof openNewCcRoomDialog === 'function') {
        openNewCcRoomDialog();
      } else {
        throw new Error('openNewCcRoomDialog is not defined');
      }
    } catch(err) {
      console.warn('[角色微信新建聊天室入口失败]', err);
      try { alert('新建角色聊天室窗口打开失败，请刷新页面后再试。'); } catch(e) {}
      return;
    }
    // 等原函数完成 DOM 渲染后，把弹窗盖到角色微信上层，并自动选择当前角色。
    setTimeout(function(){
      makeCcModalTopMost();
      preselectOwnerInRoomDialog(owner);
      var modal = document.getElementById('ccNewRoomModal');
      if (modal && modal.style.display !== 'none') modal.style.display = 'flex';
    }, 0);
    setTimeout(function(){
      makeCcModalTopMost();
      preselectOwnerInRoomDialog(owner);
    }, 80);
  };

  // 加固：即使别的地方打开同一个弹窗，也让它不会被 rolePhonePage 盖住。
  var oldOpenNewCcRoomDialog = window.openNewCcRoomDialog;
  if (typeof oldOpenNewCcRoomDialog === 'function') {
    window.openNewCcRoomDialog = function(){
      var result = oldOpenNewCcRoomDialog.apply(this, arguments);
      setTimeout(makeCcModalTopMost, 0);
      return result;
    };
  }

  // 加固创建：如果从某个角色微信里创建，确保聊天室成员一定包含该角色，创建后刷新角色微信列表。
  var oldCreateNewCcRoom = window.createNewCcRoom;
  if (typeof oldCreateNewCcRoom === 'function') {
    window.createNewCcRoom = function(){
      var owner = getPersonaByIdSafe(rolePhoneRoomOwnerId);
      var list = document.getElementById('ccNewRoomMemberList');
      if (owner && list) {
        var ownerInput = Array.prototype.slice.call(list.querySelectorAll('input[type=checkbox]')).find(function(chk){
          return String(chk.value || '') === String(owner.name || '');
        });
        if (ownerInput) ownerInput.checked = true;
      }
      var beforeRooms = [];
      try { beforeRooms = (typeof ccGetRooms === 'function' ? ccGetRooms() : []).map(function(r){ return r && r.id; }); } catch(e) {}
      var result = oldCreateNewCcRoom.apply(this, arguments);
      setTimeout(function(){
        try {
          if (owner && typeof ccGetRooms === 'function' && typeof ccSaveRooms === 'function') {
            var rooms = ccGetRooms();
            var beforeSet = {};
            beforeRooms.forEach(function(id){ beforeSet[String(id)] = true; });
            var changed = false;
            rooms.forEach(function(room){
              if (room && !beforeSet[String(room.id)] && Array.isArray(room.members) && room.members.indexOf(owner.name) >= 0) {
                room._rolePhoneCreated = true;
                room._rolePhoneOwnerPersonaId = String(owner.id);
                changed = true;
              }
            });
            if (changed) ccSaveRooms(rooms);
          }
          if (typeof monoRenderRolePhonePage === 'function') monoRenderRolePhonePage();
          var page = document.getElementById('rolePhonePage');
          if (page) { page.classList.add('open'); page.style.display = 'flex'; page.style.zIndex = '99999'; }
        } catch(e) { console.warn('[角色微信聊天室创建后刷新失败]', e); }
      }, 120);
      return result;
    };
  }
})();


