// ===== mono-role-wechat-v6-legacy-room-sync-hotfix =====

(function(){
  'use strict';

  function asStr(v){ return String(v == null ? '' : v); }
  function norm(v){ return asStr(v).trim().toLowerCase(); }
  function getPersonasSafe(){
    try { if (typeof loadPersonas === 'function') return loadPersonas() || []; } catch(e) {}
    try { if (Array.isArray(window.personas)) return window.personas; } catch(e) {}
    try { if (typeof personas !== 'undefined' && Array.isArray(personas)) return personas; } catch(e) {}
    return [];
  }
  function getPersonaByIdSafe(id){
    var sid = asStr(id);
    try { if (typeof monoGetPersonaById === 'function') { var p0 = monoGetPersonaById(sid); if (p0) return p0; } } catch(e) {}
    return getPersonasSafe().find(function(p){ return p && asStr(p.id) === sid; }) || null;
  }
  function personaAliases(p){
    if (!p) return [];
    var arr = [p.id, p.name, p.nickname, p.displayName, p.realName].filter(Boolean).map(asStr);
    var out = [];
    arr.forEach(function(x){ if (out.indexOf(x) < 0) out.push(x); });
    return out;
  }
  function roomMemberValues(room){
    if (!room) return [];
    var vals = [];
    ['members','memberNames','participants','participantNames','names','characters'].forEach(function(k){
      var v = room[k];
      if (Array.isArray(v)) vals = vals.concat(v);
    });
    ['memberIds','personaIds','participantIds','characterIds','ids'].forEach(function(k){
      var v = room[k];
      if (Array.isArray(v)) vals = vals.concat(v);
    });
    if (room.ownerPersonaId) vals.push(room.ownerPersonaId);
    if (room._tdOwnerPersonaId) vals.push(room._tdOwnerPersonaId);
    if (room._rolePhoneOwnerPersonaId) vals.push(room._rolePhoneOwnerPersonaId);
    return vals.map(function(v){
      if (v && typeof v === 'object') return v.id || v.name || v.nickname || JSON.stringify(v);
      return v;
    }).filter(function(v){ return asStr(v).trim(); }).map(asStr);
  }
  function roomHasPersona(room, persona){
    if (!room || !persona) return false;
    if (asStr(room._tdOwnerPersonaId) === asStr(persona.id)) return true;
    if (asStr(room._rolePhoneOwnerPersonaId) === asStr(persona.id)) return true;
    var aliases = personaAliases(persona).map(norm).filter(Boolean);
    var values = roomMemberValues(room).map(norm);
    return aliases.some(function(a){ return values.indexOf(a) >= 0; });
  }
  function normalizeLegacyRoomMembers(room){
    if (!room) return false;
    var changed = false;
    var ps = getPersonasSafe();
    var values = roomMemberValues(room);
    var ids = Array.isArray(room._rolePhoneMemberPersonaIds) ? room._rolePhoneMemberPersonaIds.slice() : [];
    var names = Array.isArray(room.members) ? room.members.slice() : [];
    ps.forEach(function(p){
      var aliases = personaAliases(p).map(norm);
      var matched = values.some(function(v){ return aliases.indexOf(norm(v)) >= 0; });
      if (matched) {
        if (ids.indexOf(asStr(p.id)) < 0) { ids.push(asStr(p.id)); changed = true; }
        if (names.indexOf(asStr(p.name)) < 0) { names.push(asStr(p.name)); changed = true; }
      }
    });
    if (ids.length) {
      room._rolePhoneMemberPersonaIds = ids;
      room._rolePhoneVisible = true;
      if (!Array.isArray(room.members) || room.members.length < names.length) {
        room.members = names;
        changed = true;
      }
    }
    return changed;
  }
  function syncLegacyCcRoomsToRolePhones(){
    if (typeof ccGetRooms !== 'function' || typeof ccSaveRooms !== 'function') return [];
    var rooms = [];
    try { rooms = ccGetRooms() || []; } catch(e) { rooms = []; }
    var changed = false;
    rooms.forEach(function(room){ if (normalizeLegacyRoomMembers(room)) changed = true; });
    if (changed) {
      try { ccSaveRooms(rooms); } catch(e) {}
    }
    return rooms;
  }
  window.monoSyncLegacyCcRoomsToRolePhones = syncLegacyCcRoomsToRolePhones;

  // 关键修复：角色微信不要只看新建标记；旧版已存在的角色聊天室只要成员里包含该角色，就显示在该角色微信。
  window.monoGetRolePhoneThreads = function(ownerPersona){
    if (!ownerPersona) return [];
    var rooms = syncLegacyCcRoomsToRolePhones();
    var seen = {};
    return rooms.filter(function(room){
      var hit = roomHasPersona(room, ownerPersona);
      if (!hit && Array.isArray(room._rolePhoneMemberPersonaIds)) {
        hit = room._rolePhoneMemberPersonaIds.map(asStr).indexOf(asStr(ownerPersona.id)) >= 0;
      }
      if (!hit) return false;
      var id = asStr(room.id || room.name || JSON.stringify(room));
      if (seen[id]) return false;
      seen[id] = true;
      return true;
    }).sort(function(a,b){
      return (Number(b.updatedAt || b.createdAt || 0) || 0) - (Number(a.updatedAt || a.createdAt || 0) || 0);
    });
  };

  // 打开角色微信前先迁移旧数据，确保“之前建立”的聊天室马上出现。
  var oldOpen = window.monoOpenRolePhonePage;
  if (typeof oldOpen === 'function') {
    window.monoOpenRolePhonePage = function(ownerPersonaId){
      syncLegacyCcRoomsToRolePhones();
      return oldOpen.apply(this, arguments);
    };
  }
  var oldRender = window.monoRenderRolePhonePage;
  if (typeof oldRender === 'function') {
    window.monoRenderRolePhonePage = function(){
      syncLegacyCcRoomsToRolePhones();
      return oldRender.apply(this, arguments);
    };
  }

  // 如果从旧入口/其他功能创建了角色聊天室，也立即补齐角色微信索引。
  var oldCreate = window.createNewCcRoom;
  if (typeof oldCreate === 'function') {
    window.createNewCcRoom = function(){
      var result = oldCreate.apply(this, arguments);
      setTimeout(function(){
        syncLegacyCcRoomsToRolePhones();
        try { if (typeof monoRenderRolePhonePage === 'function') monoRenderRolePhonePage(); } catch(e) {}
      }, 60);
      return result;
    };
  }

  // 首次加载就跑一次，避免需要先新建/刷新才出现。
  setTimeout(syncLegacyCcRoomsToRolePhones, 0);
})();


