    // This global lexical variable is used by monoSaveNpcEditor(), so update it here.
    try { _roleNpcEditorContext = { ownerPersonaId: String(ownerPersona.id), npcId: '__new__' }; } catch(e) { window._roleNpcEditorContext = { ownerPersonaId: String(ownerPersona.id), npcId: '__new__' }; }
    var options = getOptions(ownerPersona);
