      + '<div class="npc-editor-sheet">'
      + '  <div class="npc-editor-head"><div class="npc-editor-title">自定义 NPC 设定</div><button type="button" class="npc-editor-close" onclick="closeNpcEditorOverlay()">✕</button></div>'
      + '  <div class="npc-editor-body">'
      + '    <div class="npc-editor-grid">'
      + '      <div><label class="npc-editor-label">名字</label><input id="npcEditorName" class="npc-editor-input" type="text" placeholder="NPC 的名字"></div>'
      + '      <div><label class="npc-editor-label">身份</label><input id="npcEditorIdentity" class="npc-editor-input" type="text" placeholder="例：邻居 / 同学 / 常去咖啡店店员"></div>'
      + '      <div><label class="npc-editor-label">与 ' + esc(ownerPersona.name || '该角色') + ' 的关系</label><input id="npcEditorRelationSummary" class="npc-editor-input" type="text" placeholder="例：旧同事 / 朋友 / 竞争对手"></div>'
      + '      <div><label class="npc-editor-label">关系图描述</label><textarea id="npcEditorRelationDetail" class="npc-editor-textarea" placeholder="写这个 NPC 在关系图里和该角色的关系细节，会自动同步到关系图。"></textarea></div>'
      + '      <div><label class="npc-editor-label">详细人设</label><textarea id="npcEditorPersona" class="npc-editor-textarea" placeholder="完整写这个 NPC 的背景、个性、说话方式、和角色之间的故事。"></textarea></div>'
      + '      <div>'
      + '        <label class="npc-editor-label">与其他角色 / 用户面具的关联</label>'
      + '        <div style="display:flex;gap:8px;align-items:center;">'
      + '          <select id="npcEditorLinkTarget" class="npc-editor-select" style="flex:1;">'
      +              options.map(function(opt){ return '<option value="' + esc(String(opt.id)) + '" data-name="' + esc(opt.name || '') + '" data-type="' + esc(opt.isMask ? 'mask' : (opt.isUser ? 'user' : 'persona')) + '">' + esc(opt.name || '关联对象') + '</option>'; }).join('')
      + '          </select>'
      + '          <button type="button" class="role-phone-btn" style="padding:10px 12px;" onclick="monoAddNpcEditorLinkRow()">添加</button>'
      + '        </div>'
      + '        <div id="npcEditorLinksWrap"></div>'
