// ===== MONO PATCH v10: fix custom NPC editor close/cancel/save buttons =====
(function(){
  function getOverlay(){ return document.getElementById('npcEditorOverlay'); }
  function forceHideNpcEditor(){
    var overlay = getOverlay();
    if (!overlay) return false;
    try { overlay.classList.remove('open'); } catch(e) {}
    overlay.style.display = 'none';
    overlay.style.pointerEvents = 'none';
    return false;
  }
  // Keep a reference to the current save function before wrapping it.
  var previousSave = (typeof window.monoSaveNpcEditor === 'function') ? window.monoSaveNpcEditor : null;

  window.closeNpcEditorOverlay = function(){
    return forceHideNpcEditor();
  };

  window.monoSaveNpcEditor = function(){
    var overlay = getOverlay();
    try {
      if (previousSave && previousSave !== window.monoSaveNpcEditor) {
        previousSave.call(window);
      }
    } catch(err) {
      console.error('[v10 NPC保存失败]', err);
      alert('保存失败：' + (err && err.message ? err.message : '请检查 NPC 资料是否填写完整。'));
      return false;
    }
    // The original save function usually closes the modal. Force-hide as a backup because v9 opened it with inline display:flex.
    try {
      if (overlay && overlay.classList.contains('open')) forceHideNpcEditor();
    } catch(e) {}
    return false;
  };

  // Every time the editor is opened, allow clicks again. Some old openers only add .open, some set display:flex.
  var previousOpen = (typeof window.monoOpenCustomNpcEditor === 'function') ? window.monoOpenCustomNpcEditor : null;
  if (previousOpen) {
    window.monoOpenCustomNpcEditor = function(ownerPersonaId, evt){
      var result = previousOpen.call(window, ownerPersonaId, evt);
      var overlay = getOverlay();
      if (overlay) {
        overlay.style.display = 'flex';
        overlay.style.pointerEvents = 'auto';
        overlay.style.zIndex = '100500';
      }
      return result;
    };
  }

  // Capture fallback: fixes inline onclick not firing when another overlay/listener intercepts the click.
  document.addEventListener('click', function(e){
    var overlay = getOverlay();
    if (!overlay || !overlay.classList.contains('open')) return;
    var target = e.target;
    if (!target) return;

    // Click on the dark backdrop closes the editor.
    if (target === overlay) {
      e.preventDefault();
      e.stopPropagation();
      forceHideNpcEditor();
      return;
    }

    var closeBtn = target.closest ? target.closest('.npc-editor-close') : null;
    if (closeBtn) {
      e.preventDefault();
      e.stopPropagation();
      forceHideNpcEditor();
      return;
    }

    var deleteOrCancel = target.closest ? target.closest('.npc-editor-delete') : null;
    if (deleteOrCancel) {
      var txt = (deleteOrCancel.textContent || '').replace(/\s+/g, '');
      // In the custom-NPC popup this button is cancel. In the edit popup it may be permanent delete, so do not hijack delete.
      if (txt.indexOf('取消') >= 0 || txt.toLowerCase().indexOf('cancel') >= 0) {
        e.preventDefault();
        e.stopPropagation();
        forceHideNpcEditor();
        return;
      }
    }

    var saveBtn = target.closest ? target.closest('.npc-editor-save') : null;
    if (saveBtn) {
      e.preventDefault();
      e.stopPropagation();
      window.monoSaveNpcEditor();
      return;
    }
  }, true);

  // Make sure existing opened editor buttons are clickable even if v9 left pointer styles inconsistent.
  document.addEventListener('DOMContentLoaded', function(){
    var overlay = getOverlay();
    if (overlay) overlay.style.pointerEvents = 'auto';
  });
})();


