// ===== MONO PATCH v11: fix Relationship Map back/save buttons after opening from Role WeChat =====
(function(){
  'use strict';

  function relModal(){ return document.getElementById('mwRelMapModal'); }

  function isRelMapOpen(){
    var m = relModal();
    if (!m) return false;
    return m.style.display !== 'none' && (m.classList.contains('open') || m.style.display === 'flex');
  }

  function hardenRelMapLayer(){
    var m = relModal();
    if (!m) return;
    m.style.display = 'flex';
    m.style.flexDirection = 'column';
    // Must be higher than rolePhonePage (99999), NPC editor (100500), room dialogs, and app overlays.
    m.style.zIndex = '100900';
    m.style.pointerEvents = 'auto';
    m.classList.add('open');

    var head = m.firstElementChild;
    if (head) {
      head.style.position = 'relative';
      head.style.zIndex = '100901';
      head.style.pointerEvents = 'auto';
      var buttons = head.querySelectorAll('button');
      if (buttons[0]) {
        buttons[0].classList.add('mw-relmap-back-btn');
        buttons[0].setAttribute('type', 'button');
        buttons[0].style.pointerEvents = 'auto';
        buttons[0].style.position = 'relative';
        buttons[0].style.zIndex = '100902';
      }
      if (buttons[1]) {
        buttons[1].classList.add('mw-relmap-save-btn');
        buttons[1].setAttribute('type', 'button');
        buttons[1].style.pointerEvents = 'auto';
        buttons[1].style.position = 'relative';
        buttons[1].style.zIndex = '100902';
      }
    }
  }

  function forceCloseRelMap(){
    var m = relModal();
    if (!m) return false;
    try { m.classList.remove('open'); } catch(e) {}
    m.style.display = 'none';
    // Returning to My/profile page should remain possible after closing from role wechat.
    try {
      var profile = document.getElementById('profilePage');
      if (profile) {
        profile.style.pointerEvents = 'auto';
        profile.style.zIndex = profile.style.zIndex || '';
      }
    } catch(e) {}
    return false;
  }

  function forceSaveRelMap(){
    try { if (typeof mwRenderRelMapSvg === 'function') mwRenderRelMapSvg(); } catch(e) {}
    try { if (typeof mwInjectRelationshipsIntoChars === 'function') mwInjectRelationshipsIntoChars(); } catch(e) {}
    try { if (typeof syncLegacyCharRoomsToRolePhones === 'function') syncLegacyCharRoomsToRolePhones(); } catch(e) {}
    try { alert('✅ 关系图已保存！\n\n角色的关系记忆已更新，AI 将根据关系图生成符合逻辑的内容。'); } catch(e) {}
    forceCloseRelMap();
    return false;
  }

  // Wrap original functions so every route into this modal uses the same fixed layer/buttons.
  var oldOpen = (typeof window.openRelationshipMap === 'function') ? window.openRelationshipMap : null;
  window.openRelationshipMap = function(){
    var ret;
    try { if (oldOpen) ret = oldOpen.apply(window, arguments); } catch(err) { console.warn('[v11 openRelationshipMap original failed]', err); }
    hardenRelMapLayer();
    try { if (typeof mwRenderRelEntries === 'function') mwRenderRelEntries(); } catch(e) {}
    try { if (typeof mwRenderRelMapSvg === 'function') mwRenderRelMapSvg(); } catch(e) {}
    return ret;
  };

  window.closeRelationshipMap = function(){ return forceCloseRelMap(); };
  window.saveRelationshipMap = function(){ return forceSaveRelMap(); };

  // Capture fallback: fixes cases where inline onclick does not fire or another listener blocks bubbling.
  document.addEventListener('click', function(e){
    if (!isRelMapOpen()) return;
    var target = e.target;
    if (!target || !target.closest) return;
    var m = relModal();
    if (!m || !m.contains(target)) return;

    var back = target.closest('.mw-relmap-back-btn');
    var save = target.closest('.mw-relmap-save-btn');

    // Fallback identification for older DOM that has no classes yet.
    if (!back && !save) {
      var btn = target.closest('button');
      if (btn && m.firstElementChild && m.firstElementChild.contains(btn)) {
        var txt = (btn.textContent || '').replace(/\s+/g, '');
        if (txt.indexOf('保存') >= 0) save = btn;
        else back = btn;
      }
    }

    if (back) {
      e.preventDefault();
      e.stopPropagation();
      forceCloseRelMap();
      return;
    }
    if (save) {
      e.preventDefault();
      e.stopPropagation();
      forceSaveRelMap();
      return;
    }
  }, true);

  // If v9 opens the modal manually after calling openRelationshipMap, harden it shortly afterward too.
  setTimeout(function(){ if (isRelMapOpen()) hardenRelMapLayer(); }, 0);
})();


