      if (updateBtn) { updateBtn.disabled=false; updateBtn.innerHTML=oldUpdate || '<i class="fas fa-sync-alt" style="margin-right:3px;font-size:9px;"></i>更新行踪'; }
      setTimeout(function(){ try { if (typeof renderLocTrace === 'function') renderLocTrace(); } catch(e){} }, 0);
