    if(/工作|开会|开会|会议|会議/.test(act)) return '办公室';
    if(/吃|饭|飯/.test(act)) return '附近餐厅';
    if(/喝咖啡|咖啡/.test(act)) return '咖啡厅';
    if(/换衣|换衣|穿衣|试穿|試穿|休息|收拾/.test(act)) return '家里';
