    var bubW = Math.max(BUB_MIN_W, Math.min(BUB_MAX_W, maxLW + BUB_HPAD * 2 + 4));
    var bubH = Math.max(48, lines.length * LINE_H + BUB_VPAD * 2);
    var hasName = !isRight && !!sender;
    var nameH = hasName ? NAME_H : 0;
