// ===== mono-frosted-title-color-bundle =====

(function(){
  function getCurrentFrostedColor(){
    try {
      /* Per-role only: never reuse the old value already sitting on #chatPage,
         otherwise one character's glass title color leaks into another character. */
      var p = (typeof personas !== 'undefined' && typeof currentId !== 'undefined')
        ? personas.find(function(x){ return String(x.id) === String(currentId); })
        : null;
      return (p && p.frostedTitleColor) ? p.frostedTitleColor : '#ffffff';
    } catch(e) { return '#ffffff'; }
  }
  function isFrostedPage(page){
    return !!(page && (page.classList.contains('chat-theme-frosted') || page.classList.contains('bubble-preset-frosted')));
  }
  function forceFrostedTitleColor(){
    try {
      var page = document.getElementById('chatPage');
      if (!isFrostedPage(page)) return;
      var c = getCurrentFrostedColor();
      page.style.setProperty('--theme-frosted-name-color', c);
      page.style.setProperty('--mono-frosted-ui-color', c);
      page.style.setProperty('--mono-frosted-title-ui-color', c);

      var selectors = [
        '#headName', '#headHeartVoice', '#headHeartVoiceInner', '#headHeartVoiceInner *',
        '#offlineModeBtn', '#offlineModeBtn *',
        '#chatContactsBtn', '#chatContactsBtn *',
        '.chat-header-back-btn', '.chat-header-back-btn *',
        '.call-header-btn', '.call-header-btn *',
        '.chat-header button', '.chat-header button *', '.chat-footer button', '.chat-footer button *',
        '.chat-plus-btn', '.chat-plus-btn *', '.chat-voice-record-btn', '.chat-voice-record-btn *',
        '.plus-panel-btn', '.plus-panel-btn *'
      ];
      page.querySelectorAll(selectors.join(',')).forEach(function(el){
        el.style.setProperty('color', c, 'important');
        el.style.setProperty('fill', 'currentColor', 'important');
        el.style.setProperty('stroke', 'currentColor', 'important');
      });
    } catch(e) {}
  }
  var oldApplyBubbleStyles = window.applyBubbleStyles;
  if (typeof oldApplyBubbleStyles === 'function' && !oldApplyBubbleStyles.__frostedColorHeartOfflinePatched) {
    var patched = function(p){
      var r = oldApplyBubbleStyles.apply(this, arguments);
      setTimeout(forceFrostedTitleColor, 0);
      setTimeout(forceFrostedTitleColor, 80);
      return r;
    };
    patched.__frostedColorHeartOfflinePatched = true;
    window.applyBubbleStyles = patched;
  }
  var oldLivePreviewBubble = window.livePreviewBubble;
  if (typeof oldLivePreviewBubble === 'function' && !oldLivePreviewBubble.__frostedColorHeartOfflinePatched) {
    var patchedPreview = function(){
      var r = oldLivePreviewBubble.apply(this, arguments);
      setTimeout(forceFrostedTitleColor, 0);
      return r;
    };
    patchedPreview.__frostedColorHeartOfflinePatched = true;
    window.livePreviewBubble = patchedPreview;
  }
  document.addEventListener('DOMContentLoaded', function(){
    forceFrostedTitleColor();
    var input = document.getElementById('pFrostedTitleColor');
    if (input) input.addEventListener('input', function(){ setTimeout(forceFrostedTitleColor, 0); });
    var page = document.getElementById('chatPage');
    if (page && window.MutationObserver) {
      new MutationObserver(function(){ forceFrostedTitleColor(); }).observe(page, { childList:true, subtree:true, attributes:true, attributeFilter:['class','style'] });
    }
  });
  window.addEventListener('load', forceFrostedTitleColor);
  document.addEventListener('click', function(){ setTimeout(forceFrostedTitleColor, 0); }, true);
  setInterval(forceFrostedTitleColor, 1600);
})();

