// ===== monoBottomSafeInsetRestoreFixScript =====

(function(){
  function visibleHeight(el){
    if(!el) return 0;
    var cs = window.getComputedStyle(el);
    if(cs.display === 'none' || cs.visibility === 'hidden') return 0;
    return Math.ceil(el.getBoundingClientRect().height || 0);
  }
  function updateAppBottomGap(){
    try {
      var gap = (document.body && document.body.classList.contains('ios-fullscreen')) ? 10 : 14;
      document.documentElement.style.setProperty('--mono-app-bottom-safe-gap', gap + 'px');
    } catch(e) {}
  }
  function updateChatBottomStack(){
    try {
      var page = document.getElementById('chatPage');
      if(!page) return;
      var total = 0;
      ['typingArea','quotePreview','multiDeleteBar'].forEach(function(id){
        total += visibleHeight(document.getElementById(id));
      });
      total += visibleHeight(page.querySelector('.chat-footer'));
      page.style.setProperty('--mono-chat-bottom-stack', Math.max(0, total) + 'px');
    } catch(e) {}
  }
  var _scheduled = false;
  function scheduleRun(){
    if(_scheduled) return;
    _scheduled = true;
    requestAnimationFrame(function(){
      _scheduled = false;
      run();
    });
  }
  function run(){
    updateAppBottomGap();
    updateChatBottomStack();
  }
  window.monoBottomSafeInsetRestoreFix = run;
  window.monoScheduleBottomSafeInsetRestoreFix = scheduleRun;
  ['DOMContentLoaded','load','resize','orientationchange'].forEach(function(ev){
    window.addEventListener(ev, function(){
      scheduleRun();
      setTimeout(scheduleRun, 120);
    }, {passive:true});
  });
  if(window.visualViewport){
    window.visualViewport.addEventListener('resize', function(){ setTimeout(scheduleRun, 40); }, {passive:true});
  }
  document.addEventListener('input', function(){ setTimeout(scheduleRun, 40); }, true);
  document.addEventListener('click', function(){ setTimeout(scheduleRun, 40); setTimeout(scheduleRun, 220); }, true);
  document.addEventListener('DOMContentLoaded', function(){
    if(window.ResizeObserver){
      var ro = new ResizeObserver(scheduleRun);
      ['typingArea','quotePreview','multiDeleteBar','chatBox'].forEach(function(id){
        var el = document.getElementById(id);
        if(el) ro.observe(el);
      });
      var footer = document.querySelector('#chatPage .chat-footer');
      if(footer) ro.observe(footer);
    }
    scheduleRun();
  });
})();


