// ===== monoNonChatBottomMaskFixScript =====

(function(){
  function firstOpaqueColor(root){
    if(!root) return '';
    var list = [root].concat(Array.prototype.slice.call(root.querySelectorAll('*')).slice(0, 80));
    for(var i=0;i<list.length;i++){
      var el = list[i];
      var cs = window.getComputedStyle(el);
      if(!cs) continue;
      if(cs.display === 'none' || cs.visibility === 'hidden') continue;
      var bg = cs.backgroundColor || '';
      if(bg && bg !== 'transparent' && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'rgba(0,0,0,0)') return bg;
    }
    return '#ffffff';
  }
  function applyMask(){
    try {
      document.querySelectorAll('.page').forEach(function(page){
        if(page.id === 'chatPage') {
          if(page.style.getPropertyValue('--mono-active-page-bottom-bg')) page.style.removeProperty('--mono-active-page-bottom-bg');
          return;
        }
        if(!page.classList.contains('active') || page.style.display === 'none') {
          if(page.style.getPropertyValue('--mono-active-page-bottom-bg')) page.style.removeProperty('--mono-active-page-bottom-bg');
          return;
        }
        var forceBlack = page.id === 'dreamPage' || page.id === 'decryptPage';
        var color = forceBlack ? '#000000' : firstOpaqueColor(page);
        if(page.style.getPropertyValue('--mono-active-page-bottom-bg') !== String(color || '#ffffff')) {
          page.style.setProperty('--mono-active-page-bottom-bg', color || '#ffffff');
        }
      });
    } catch(e) {}
  }
  var _maskScheduled = false;
  function scheduleMask(){
    if(_maskScheduled) return;
    _maskScheduled = true;
    requestAnimationFrame(function(){
      _maskScheduled = false;
      applyMask();
    });
  }
  window.monoNonChatBottomMaskFix = applyMask;
  window.monoScheduleNonChatBottomMaskFix = scheduleMask;
  ['DOMContentLoaded','load','resize','orientationchange'].forEach(function(ev){
    window.addEventListener(ev, function(){
      scheduleMask();
      setTimeout(scheduleMask, 120);
    }, {passive:true});
  });
  document.addEventListener('click', function(){ setTimeout(scheduleMask, 40); setTimeout(scheduleMask, 220); }, true);
  document.addEventListener('input', function(){ setTimeout(scheduleMask, 40); }, true);
  document.addEventListener('DOMContentLoaded', function(){
    scheduleMask();
  });
})();


