// ===== monoFixRefreshHooks =====

(function(){
  function scheduleHeaderOnly(){
    try { if (typeof window.monoScheduleCleanGlassChatFix === 'function') window.monoScheduleCleanGlassChatFix(); } catch(e) {}
  }
  function afterNav(){
    setTimeout(scheduleHeaderOnly, 0);
    setTimeout(scheduleHeaderOnly, 80);
    setTimeout(scheduleHeaderOnly, 220);
  }
  function wrap(name){
    var fn = window[name];
    if(typeof fn !== 'function' || fn.__monoFixWrapped) return;
    var wrapped = function(){
      var result = fn.apply(this, arguments);
      afterNav();
      return result;
    };
    wrapped.__monoFixWrapped = true;
    window[name] = wrapped;
  }
  function install(){
    ['openApp','_showAppPage','goHome','openGroupChat','closeGroupChat','openDatingApp','closeDatingApp','openDatingChatRoom','closeDatingChatRoom'].forEach(wrap);
    afterNav();
  }
  window.monoInstallFixRefreshHooks = install;
  document.addEventListener('DOMContentLoaded', install);
  window.addEventListener('load', install, {passive:true});
})();


