// ===== monoDirectOldKeyboardAllInputsPatchScript =====

(function(){
  function setOldViewportVars(){
    try{
      var root = document.documentElement;
      root.style.setProperty('--mono-app-vh', '1vh');
      root.style.setProperty('--mono-keyboard-offset', '0px');
    }catch(e){}
  }
  function isEditable(el){
    return !!(el && el.matches && el.matches('input, textarea, select, [contenteditable="true"]'));
  }
  function getKeyboardLift(){
    try{
      /* Hard-disable composer lifting.
         Some mobile browsers paint the system security/autofill accessory bar
         inside the transformed chat footer, which creates the white "密保" strip. */
      return 0;
    }catch(e){ return 0; }
  }
  function updateChatComposerLift(){
    try{
      setOldViewportVars();
      var active = document.activeElement;
      var isChatInput = !!(active && active.id === 'userInput');
      if(isChatInput && typeof window.closePlusPanel === 'function') window.closePlusPanel();
      var lift = 0;
      document.documentElement.style.setProperty('--mono-chat-input-lift', lift + 'px');
      document.body.classList.remove('mono-chat-composer-focused');
      if(isChatInput){
        var box = document.getElementById('chatBox');
        setTimeout(function(){ try{ if(box) box.scrollTop = box.scrollHeight; }catch(e){} }, 80);
      }
    }catch(e){}
  }
  function scrollFocusedInputIntoView(el){
    try{
      if(!isEditable(el)) return;
      setOldViewportVars();
      /* Chat composer is handled by local lifting, not whole-page resizing. */
      if(el.id === 'userInput') { updateChatComposerLift(); return; }
      setTimeout(function(){
        try{ el.scrollIntoView({block:'center', inline:'nearest', behavior:'smooth'}); }catch(e){ try{ el.scrollIntoView(false); }catch(_){} }
      }, 260);
    }catch(e){}
  }
  window.updateMonoViewportMetrics = function(){ setOldViewportVars(); updateChatComposerLift(); };
  window.monoRestoreOldKeyboardModeAllInputs = function(){ setOldViewportVars(); updateChatComposerLift(); };
  ['DOMContentLoaded','load','resize','orientationchange'].forEach(function(ev){
    window.addEventListener(ev, function(){ setOldViewportVars(); setTimeout(updateChatComposerLift, 80); }, {passive:true});
  });
  document.addEventListener('focusin', function(e){
    document.documentElement.classList.add('mono-input-focused');
    if(e && e.target && e.target.id === 'userInput'){
      try{ if(typeof window.closePlusPanel === 'function') window.closePlusPanel(); }catch(_e){}
    }
    scrollFocusedInputIntoView(e.target);
    setTimeout(function(){ scrollFocusedInputIntoView(e.target); updateChatComposerLift(); }, 420);
  }, true);
  document.addEventListener('focusout', function(){
    setTimeout(function(){
      if(!isEditable(document.activeElement)) document.documentElement.classList.remove('mono-input-focused');
      document.body.classList.remove('mono-chat-composer-focused');
      document.documentElement.style.setProperty('--mono-chat-input-lift','0px');
      setOldViewportVars();
    }, 120);
  }, true);
  if(window.visualViewport){
    window.visualViewport.addEventListener('resize', function(){ setOldViewportVars(); setTimeout(updateChatComposerLift, 20); }, {passive:true});
    window.visualViewport.addEventListener('scroll', function(){ setOldViewportVars(); setTimeout(updateChatComposerLift, 20); }, {passive:true});
  }
  setOldViewportVars();
})();


