// ===== monoGlassEmptyStickerFabFixV4Script =====

(function(){
  'use strict';

  function clampNumber(v, min, max){
    v = Number(v);
    if (!isFinite(v)) v = min;
    return Math.max(min, Math.min(max, v));
  }

  /* 1) 玻璃主题空聊天室高度修复 */
  function monoFixGlassEmptyChatLayout(){
    try {
      var page = document.getElementById('chatPage');
      if (!page || !document.body.classList.contains('chat-page-active')) return;
      var isGlass = page.classList.contains('chat-theme-frosted') || page.classList.contains('bubble-preset-frosted') || document.body.classList.contains('chat-theme-frosted-active') || document.body.classList.contains('chat-preset-frosted-active');
      if (!isGlass) return;
      var host = page.parentElement || document.querySelector('.phone-screen') || document.querySelector('.phone-container');
      var hostRect = host ? host.getBoundingClientRect() : null;
      var h = hostRect && hostRect.height ? hostRect.height : window.innerHeight;
      if (h && h > 200) document.documentElement.style.setProperty('--mono-chat-page-h', Math.round(h) + 'px');
      page.style.display = 'flex';
      page.style.flexDirection = 'column';
      page.style.overflow = 'hidden';
      page.style.minHeight = '0';
      var box = document.getElementById('chatBox');
      if (box) {
        box.style.flex = '1 1 auto';
        box.style.minHeight = '0';
        box.style.height = 'auto';
        box.style.overflowY = 'auto';
      }
      var footer = page.querySelector('.chat-footer');
      if (footer) {
        footer.style.flex = '0 0 auto';
        footer.style.marginTop = 'auto';
        footer.style.position = 'relative';
      }
    } catch(e) {}
  }
  window.monoFixGlassEmptyChatLayout = monoFixGlassEmptyChatLayout;
  ['DOMContentLoaded','load','resize','orientationchange'].forEach(function(ev){
    window.addEventListener(ev, function(){
      monoFixGlassEmptyChatLayout();
      setTimeout(monoFixGlassEmptyChatLayout, 80);
      setTimeout(monoFixGlassEmptyChatLayout, 260);
    }, {passive:true});
  });
  document.addEventListener('click', function(){ setTimeout(monoFixGlassEmptyChatLayout, 0); }, true);
  document.addEventListener('input', function(){ setTimeout(monoFixGlassEmptyChatLayout, 0); }, true);
  var oldRenderMessages = window.renderMessages;
  if (typeof oldRenderMessages === 'function' && !oldRenderMessages.__monoGlassEmptyWrapped) {
    var wrappedRenderMessages = function(){
      var r = oldRenderMessages.apply(this, arguments);
      setTimeout(monoFixGlassEmptyChatLayout, 0);
      return r;
    };
    wrappedRenderMessages.__monoGlassEmptyWrapped = true;
    window.renderMessages = wrappedRenderMessages;
  }

  /* 2) 批量表情包 URL：支持 URL（描述）/ URL(描述)，描述直接写入 caption。 */
  function monoParseStickerUrlLine(line){
    line = String(line || '').trim();
    if (!line) return null;
    var url = line;
    var caption = '';
    var m = line.match(/^(.*?)[\s　]*[（(]([^（）()]*)[）)]\s*$/);
    if (m && /^https?:\/\//i.test((m[1] || '').trim())) {
      url = (m[1] || '').trim();
      caption = (m[2] || '').trim();
    }
    url = url.trim();
    if (!/^https?:\/\//i.test(url)) return null;
    return { url: url, caption: caption };
  }
  window.monoParseStickerUrlLine = monoParseStickerUrlLine;

  function monoSplitStickerBulkInput(raw){
    raw = String(raw || '').trim();
    if (!raw) return [];
    return raw.split(/\r?\n/).map(monoParseStickerUrlLine).filter(Boolean);
  }
  window.monoSplitStickerBulkInput = monoSplitStickerBulkInput;

  window.importStickerUrlsBulk = async function(){
    var textarea = document.getElementById('stickerBulkUrlInput');
    var statusEl = document.getElementById('stickerBulkUrlStatus');
    var raw = (textarea && textarea.value || '').trim();
    if (!raw) { alert('请先粘贴图片 URL'); return; }
    var items = monoSplitStickerBulkInput(raw);
    if (!items.length) { alert('没有识别到有效的图片 URL'); return; }
    var autoDesc = !!(document.getElementById('stickerBulkUrlAutoDesc') || {}).checked;
    if (autoDesc && typeof isVisionApiConfigured === 'function' && !isVisionApiConfigured()) { alert('请先在设置里配置图片识别 API'); return; }
    var libs = getStickerLibraries();
    var targetLib = libs.find(function(lib) { return lib.id === getCurrentStickerLibraryId(); }) || libs[0];
    if (!targetLib) { alert('没有可用的表情包库'); return; }
    if (statusEl) statusEl.style.display = 'block';
    var successCount = 0;
    for (var i = 0; i < items.length; i++) {
      var item = items[i];
      var caption = item.caption || '';
      if (statusEl) statusEl.innerHTML = '<i class="fas fa-spinner fa-spin" style="margin-right:4px;"></i>正在导入第 ' + (i + 1) + ' / ' + items.length + ' 个 URL...';
      if (!caption && autoDesc) {
        try {
          var base64 = await urlToBase64(item.url).catch(function() { return item.url; });
          caption = await describeImageWithVisionApi(base64);
        } catch(e) { caption = ''; }
      }
      targetLib.stickers.push({ src: item.url, caption: caption, isUrl: true, _visionDesc: caption });
      successCount++;
    }
    saveStickerLibraries(libs);
    if (textarea) textarea.value = '';
    if (statusEl) statusEl.style.display = 'none';
    if (typeof renderStickerManageView === 'function') renderStickerManageView();
    if (typeof renderStickerSendView === 'function') renderStickerSendView();
    alert('成功导入 ' + successCount + ' 个 URL 表情包到“' + targetLib.name + '”');
  };

  var oldBatchStickerAddUrl = window.batchStickerAddUrl;
  window.batchStickerAddUrl = function(){
    try {
      if (window._batchStickerSlots && _batchStickerSlots.length >= 10) { alert('最多添加10个表情包'); return; }
      var urlInput = document.getElementById('batchStickerUrlInput');
      var parsed = monoParseStickerUrlLine(urlInput && urlInput.value);
      if (!parsed) { alert('请输入有效的URL'); return; }
      _batchStickerSlots.push({ src: parsed.url, desc: parsed.caption || '', status: parsed.caption ? 'success' : 'pending', isUrl: true });
      if (urlInput) urlInput.value = '';
      renderBatchStickerSlots();
      if (!parsed.caption && typeof isVisionApiConfigured === 'function' && isVisionApiConfigured()) {
        autoBatchDescribeByIndex(_batchStickerSlots.length - 1);
      }
    } catch(e) {
      if (typeof oldBatchStickerAddUrl === 'function') return oldBatchStickerAddUrl.apply(this, arguments);
      throw e;
    }
  };

  /* 3) 浮动 API 面板定位：按真实视窗和面板尺寸重新夹住，避免 top 变负数。 */
  function monoClampFabButton(){
    try {
      var fab = document.getElementById('apiFab');
      if (!fab || fab.style.display === 'none') return;
      var rect = fab.getBoundingClientRect();
      var x = clampNumber(rect.left, 8, Math.max(8, window.innerWidth - 52));
      var y = clampNumber(rect.top, 8, Math.max(8, window.innerHeight - 52));
      if (Math.abs(x - rect.left) > 1 || Math.abs(y - rect.top) > 1) {
        fab.style.left = x + 'px';
        fab.style.top = y + 'px';
        fab.style.right = 'auto';
        fab.style.bottom = 'auto';
        try { localStorage.setItem('mono_fab_position', JSON.stringify({ x: x, y: y })); } catch(e) {}
      }
    } catch(e) {}
  }
  window.monoClampFabButton = monoClampFabButton;

  window.positionFabPanel = function(){
    var fab = document.getElementById('apiFab');
    var panel = document.getElementById('apiFabPanel');
    if (!fab || !panel) return;
    monoClampFabButton();
    var vw = Math.max(320, window.innerWidth || document.documentElement.clientWidth || 320);
    var vh = Math.max(320, window.innerHeight || document.documentElement.clientHeight || 320);
    var margin = 10;
    var fabRect = fab.getBoundingClientRect();
    var panelW = Math.min(260, vw - margin * 2);
    panel.style.width = panelW + 'px';
    panel.style.maxHeight = Math.max(180, vh - margin * 2) + 'px';
    var measuredH = panel.scrollHeight || panel.offsetHeight || 300;
    var panelH = Math.min(measuredH, vh - margin * 2);
    panel.style.maxHeight = panelH + 'px';
    var left;
    if (fabRect.left >= vw / 2) left = fabRect.left - panelW - 10;
    else left = fabRect.right + 10;
    if (left < margin) left = margin;
    if (left + panelW > vw - margin) left = vw - panelW - margin;
    var top = fabRect.top + (fabRect.height / 2) - (panelH / 2);
    if (top < margin) top = margin;
    if (top + panelH > vh - margin) top = vh - panelH - margin;
    top = clampNumber(top, margin, Math.max(margin, vh - panelH - margin));
    panel.style.left = Math.round(left) + 'px';
    panel.style.top = Math.round(top) + 'px';
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
    panel.style.transformOrigin = (fabRect.left >= vw / 2 ? 'center right' : 'center left');
  };

  var oldOpenFabPanel = window.openFabPanel;
  window.openFabPanel = function(){
    var panel = document.getElementById('apiFabPanel');
    if (!panel) return;
    if (typeof updateFabPanel === 'function') updateFabPanel();
    monoClampFabButton();
    window.positionFabPanel();
    panel.classList.add('show');
    window.fabPanelOpen = true;
  };
  window.addEventListener('resize', function(){
    monoFixGlassEmptyChatLayout();
    monoClampFabButton();
    var panel = document.getElementById('apiFabPanel');
    if (panel && panel.classList.contains('show')) window.positionFabPanel();
  }, {passive:true});
  window.addEventListener('orientationchange', function(){
    setTimeout(function(){
      monoFixGlassEmptyChatLayout();
      monoClampFabButton();
      var panel = document.getElementById('apiFabPanel');
      if (panel && panel.classList.contains('show')) window.positionFabPanel();
    }, 120);
  }, {passive:true});
  setTimeout(function(){ monoFixGlassEmptyChatLayout(); monoClampFabButton(); }, 300);
})();


