// ===== script-67 =====

(function(){
  'use strict';
  /* ===== v5: URL 表情包显示修复 =====
     修复点：
     1) 兼容 src / url / image / stickerSrc 等字段，避免保存字段和显示字段不一致。
     2) URL（描述）导入时，确保括号描述不会残留在图片 src 里。
     3) 渲染 img 时做 HTML 属性转义，避免 URL 里的 &、引号、括号等破坏标签。
     4) 给远程图片加 referrerpolicy="no-referrer"，减少部分图床防盗链导致不显示。
     5) 加载失败时显示可点击打开原图的提示，而不是空白。 */

  function monoEscapeAttr(value){
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }
  window.monoEscapeAttr = monoEscapeAttr;

  function monoEscapeHtml(value){
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }
  window.monoEscapeHtml = monoEscapeHtml;

  function monoCleanStickerUrl(raw){
    var text = String(raw == null ? '' : raw).trim();
    if (!text) return '';
    text = text.replace(/&amp;/g, '&').replace(/^['"]+|['"]+$/g, '').trim();
    if (text.indexOf('//') === 0) text = 'https:' + text;

    // 如果整条内容是：URL（描述）/ URL(描述)，只保留 URL。
    if (typeof window.monoParseStickerUrlLine === 'function') {
      try {
        var parsed = window.monoParseStickerUrlLine(text);
        if (parsed && parsed.url) text = parsed.url;
      } catch(e) {}
    } else {
      var m = text.match(/^(.*?)[\s　]*[（(]([^（）()]*)[）)]\s*$/);
      if (m && /^https?:\/\//i.test((m[1] || '').trim())) text = (m[1] || '').trim();
    }
    return text;
  }
  window.monoCleanStickerUrl = monoCleanStickerUrl;

  function monoStickerSrc(item){
    if (!item) return '';
    if (typeof item === 'string') return monoCleanStickerUrl(item);
    var raw = item.src || item.url || item.image || item.imageUrl || item.stickerSrc || item.dataUrl || item.base64 || '';
    return monoCleanStickerUrl(raw);
  }
  window.monoStickerSrc = monoStickerSrc;

  function monoStickerCaption(item){
    if (!item || typeof item === 'string') return '';
    var cap = item.caption || item.desc || item.description || item._visionDesc || '';
    if (!cap && (item.src || item.url)) {
      try {
        var parsed = (typeof window.monoParseStickerUrlLine === 'function') ? window.monoParseStickerUrlLine(item.src || item.url) : null;
        if (parsed && parsed.caption) cap = parsed.caption;
      } catch(e) {}
    }
    return String(cap || '').trim();
  }
  window.monoStickerCaption = monoStickerCaption;

  window._normalizeStickerItem = function(item){
    var out = Object.assign({}, item || {});
    var src = monoStickerSrc(item);
    var caption = monoStickerCaption(item);
    out.src = src;
    out.url = src;
    out.stickerSrc = src;
    out.caption = caption;
    out._visionDesc = out._visionDesc || caption || '';
    out.isUrl = !!(/^https?:\/\//i.test(src));
    return out;
  };

  function monoStickerImgHtml(src, caption, extraStyle){
    var safeSrc = monoEscapeAttr(monoCleanStickerUrl(src));
    var safeCaption = monoEscapeAttr(caption || 'sticker');
    var fallback = "this.style.display='none';var p=this.parentNode;if(p&&!p.querySelector('.mono-sticker-img-failed')){var d=document.createElement('div');d.className='mono-sticker-img-failed';d.innerHTML='图片加载失败<br><small>点击打开</small>';p.appendChild(d);}";
    return '<img src="' + safeSrc + '" alt="' + safeCaption + '" referrerpolicy="no-referrer" loading="lazy" decoding="async" onerror="' + fallback + '" style="width:100%;height:100%;object-fit:cover;display:block;' + (extraStyle || '') + '">';
  }
  window.monoStickerImgHtml = monoStickerImgHtml;

  function monoOpenStickerOriginalUrl(e, src){
    try {
      if (!src || !/^https?:\/\//i.test(src)) return;
      var target = e && e.target;
      if (target && target.classList && target.classList.contains('mono-sticker-img-failed')) {
        window.open(src, '_blank');
      }
    } catch(err) {}
  }
  window.monoOpenStickerOriginalUrl = monoOpenStickerOriginalUrl;

  var style = document.createElement('style');
  style.id = 'mono-sticker-url-display-fix-style';
  style.textContent = `
    .sticker-item, .slot-preview, .bubble-sticker { background:#f3f3f3; }
    .mono-sticker-img-failed {
      position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center;
      text-align:center; color:#999; font-size:9px; line-height:1.35; padding:6px; background:#f5f5f5; cursor:pointer;
    }
    .mono-sticker-img-failed small { font-size:8px; color:#aaa; margin-top:2px; }
  `;
  if (!document.getElementById(style.id)) document.head.appendChild(style);

  // 重新保存时统一清洗已有表情包数据，修复旧数据字段不一致。
  var oldSaveStickerLibraries = window.saveStickerLibraries;
  window.saveStickerLibraries = function(libs){
    var safe = (Array.isArray(libs) ? libs : []).map(function(lib, index){
      return {
        id: lib && lib.id ? lib.id : ('sticker_lib_import_' + index),
        name: lib && lib.name ? lib.name : ('表情包库 ' + (index + 1)),
        stickers: Array.isArray(lib && lib.stickers) ? lib.stickers.map(window._normalizeStickerItem) : []
      };
    });
    if (typeof oldSaveStickerLibraries === 'function') return oldSaveStickerLibraries(safe);
    localStorage.setItem('mono_sticker_libraries_v2', JSON.stringify(safe));
  };

  // 打开表情包面板时，自动清洗一次旧数据。
  function monoNormalizeStoredStickerLibraries(){
    try {
      var libs = getStickerLibraries();
      var before = JSON.stringify(libs);
      libs = libs.map(function(lib){
        lib.stickers = (lib.stickers || []).map(window._normalizeStickerItem).filter(function(s){ return !!s.src; });
        return lib;
      });
      if (JSON.stringify(libs) !== before) saveStickerLibraries(libs);
    } catch(e) {}
  }
  window.monoNormalizeStoredStickerLibraries = monoNormalizeStoredStickerLibraries;

  // 覆盖批量 URL 导入：保存前清洗 URL，并且字段同时写 src/url/stickerSrc。
  window.importStickerUrlsBulk = async function(){
    var textarea = document.getElementById('stickerBulkUrlInput');
    var statusEl = document.getElementById('stickerBulkUrlStatus');
    var raw = (textarea && textarea.value || '').trim();
    if (!raw) { alert('请先粘贴图片 URL'); return; }
    var items = (typeof monoSplitStickerBulkInput === 'function')
      ? monoSplitStickerBulkInput(raw)
      : raw.split(/\r?\n/).map(function(line){ return { url: monoCleanStickerUrl(line), caption: '' }; }).filter(function(x){ return /^https?:\/\//i.test(x.url); });
    if (!items.length) { alert('没有识别到有效的图片 URL'); return; }

    var autoDesc = !!(document.getElementById('stickerBulkUrlAutoDesc') || {}).checked;
    if (autoDesc && typeof isVisionApiConfigured === 'function' && !isVisionApiConfigured()) { alert('请先在设置里配置图片识别 API'); return; }

    var libs = getStickerLibraries();
    var targetLib = libs.find(function(lib) { return lib.id === getCurrentStickerLibraryId(); }) || libs[0];
    if (!targetLib) { alert('没有可用的表情包库'); return; }
    if (statusEl) statusEl.style.display = 'block';

    var successCount = 0;
    for (var i = 0; i < items.length; i++) {
      var item = items[i];
      var cleanUrl = monoCleanStickerUrl(item.url);
      if (!/^https?:\/\//i.test(cleanUrl)) continue;
      var caption = String(item.caption || '').trim();
      if (statusEl) statusEl.innerHTML = '<i class="fas fa-spinner fa-spin" style="margin-right:4px;"></i>正在导入第 ' + (i + 1) + ' / ' + items.length + ' 个 URL...';
      if (!caption && autoDesc) {
        try {
          var imgData = await urlToBase64(cleanUrl).catch(function() { return cleanUrl; });
          caption = await describeImageWithVisionApi(imgData);
        } catch(e) { caption = ''; }
      }
      targetLib.stickers.push(window._normalizeStickerItem({ src: cleanUrl, url: cleanUrl, stickerSrc: cleanUrl, caption: caption, isUrl: true, _visionDesc: caption }));
      successCount++;
    }
    saveStickerLibraries(libs);
    if (textarea) textarea.value = '';
    if (statusEl) statusEl.style.display = 'none';
    if (typeof renderStickerManageView === 'function') renderStickerManageView();
    if (typeof renderStickerSendView === 'function') renderStickerSendView();
    alert('成功导入 ' + successCount + ' 个 URL 表情包到“' + targetLib.name + '”');
  };

  // 覆盖管理库渲染，避免 URL 特殊字符破坏 <img>。
  window.renderStickerManageView = function(){
    monoNormalizeStoredStickerLibraries();
    var libs = getStickerLibraries();
    var currentLibId = getCurrentStickerLibraryId();
    var currentLib = getStickerLibraryById(currentLibId) || libs[0] || { id: '', name: '默认表情包库', stickers: [] };
    var stickers = (currentLib.stickers || []).map(function(s, idx) {
      return Object.assign({}, window._normalizeStickerItem(s), { _libraryId: currentLib.id, _libraryIndex: idx });
    }).filter(function(s){ return !!s.src; });
    var grid = document.getElementById('stickerManageGrid');
    var toolbar = document.getElementById('stickerLibraryToolbar');
    if (!grid) return;
    if (toolbar) {
      toolbar.innerHTML = libs.map(function(lib) {
        var active = lib.id === currentLib.id;
        return '<button type="button" onclick="setCurrentStickerLibrary(\'' + monoEscapeAttr(lib.id) + '\')" style="border:none;border-radius:999px;padding:7px 10px;font-size:10px;cursor:pointer;background:' + (active ? '#1a1a1a' : '#f1f1f1') + ';color:' + (active ? '#fff' : '#333') + ';">' + monoEscapeHtml(lib.name) + '（' + (lib.stickers || []).length + '）</button>';
      }).join('') +
      '<button type="button" onclick="createStickerLibrary()" style="border:none;border-radius:999px;padding:7px 10px;font-size:10px;cursor:pointer;background:#e8f0fe;color:#1a73e8;">+ 新建表情包库</button>' +
      (currentLib.id ? '<button type="button" onclick="renameStickerLibrary(\'' + monoEscapeAttr(currentLib.id) + '\')" style="border:none;border-radius:999px;padding:7px 10px;font-size:10px;cursor:pointer;background:#fff3cd;color:#856404;">重命名</button>' : '') +
      (currentLib.id ? '<button type="button" onclick="deleteStickerLibrary(\'' + monoEscapeAttr(currentLib.id) + '\')" style="border:none;border-radius:999px;padding:7px 10px;font-size:10px;cursor:pointer;background:#fdecea;color:#b42318;">删除当前库</button>' : '') +
      (currentLib.id ? '<button type="button" onclick="exportStickerLibrary(\'' + monoEscapeAttr(currentLib.id) + '\')" style="border:none;border-radius:999px;padding:7px 10px;font-size:10px;cursor:pointer;background:#e8f5e9;color:#1b5e20;">导出当前库</button>' : '') +
      '<button type="button" onclick="importStickerLibrary()" style="border:none;border-radius:999px;padding:7px 10px;font-size:10px;cursor:pointer;background:#ede7f6;color:#5e35b1;">导入表情库文件</button>';
    }
    grid.style.display = 'grid';
    grid.style.gridTemplateColumns = 'repeat(4, 1fr)';
    grid.style.gridAutoRows = 'max-content';
    grid.style.gap = '8px';
    grid.style.padding = '12px';
    grid.style.alignContent = 'start';
    grid.style.minHeight = '0';
    grid.style.width = '100%';
    var html = stickers.map(function(s, i){
      var src = monoStickerSrc(s);
      return '<div class="sticker-item" onclick="monoOpenStickerOriginalUrl(event, \'' + monoEscapeAttr(src) + '\')" style="position:relative;display:block;min-width:0;min-height:0;">' +
        monoStickerImgHtml(src, s.caption) +
        '<div class="sticker-item-overlay">' +
          '<button class="sticker-overlay-btn" onclick="event.stopPropagation();editStickerCaption(\'' + monoEscapeAttr(currentLib.id) + '\', ' + i + ')">✏️ 编辑</button>' +
          '<button class="sticker-overlay-btn" style="background:rgba(255,80,80,0.9);color:#fff;" onclick="event.stopPropagation();deleteSticker(\'' + monoEscapeAttr(currentLib.id) + '\', ' + i + ')">🗑 删除</button>' +
        '</div>' +
      '</div>';
    }).join('');
    html += '<div class="sticker-add-btn" onclick="openStickerAddModal(\'' + monoEscapeAttr(currentLib.id) + '\')"><i class="fas fa-plus"></i><span>添加</span></div>';
    html += '<div class="sticker-add-btn" onclick="openBatchStickerModal()" style="border-color:#1a73e8;color:#1a73e8;"><i class="fas fa-layer-group"></i><span>批量添加</span></div>';
    grid.innerHTML = html;
  };

  // 覆盖选择发送渲染。
  window.renderStickerSendView = function(){
    monoNormalizeStoredStickerLibraries();
    var stickers = _stickerSendLibraryFilter === 'all' ? getStickers() : getStickers([_stickerSendLibraryFilter]);
    stickers = stickers.map(window._normalizeStickerItem).filter(function(s){ return !!s.src; });
    var libs = getStickerLibraries();
    var grid = document.getElementById('stickerSendView');
    if (!grid) return;
    grid.style.display = 'grid';
    grid.style.gridTemplateColumns = 'repeat(4, 1fr)';
    grid.style.gridAutoRows = 'max-content';
    grid.style.gap = '8px';
    grid.style.padding = '12px';
    grid.style.alignContent = 'start';
    grid.style.minHeight = '0';
    grid.style.width = '100%';
    var toolbar = '<div style="grid-column:1/-1;display:flex;flex-wrap:wrap;gap:6px;">' +
      '<button type="button" onclick="setStickerSendLibraryFilter(\'all\')" style="border:none;border-radius:999px;padding:6px 10px;font-size:10px;cursor:pointer;background:' + (_stickerSendLibraryFilter === 'all' ? '#1a1a1a' : '#f1f1f1') + ';color:' + (_stickerSendLibraryFilter === 'all' ? '#fff' : '#333') + ';">全部</button>' +
      libs.map(function(lib) {
        var active = _stickerSendLibraryFilter === lib.id;
        return '<button type="button" onclick="setStickerSendLibraryFilter(\'' + monoEscapeAttr(lib.id) + '\')" style="border:none;border-radius:999px;padding:6px 10px;font-size:10px;cursor:pointer;background:' + (active ? '#1a1a1a' : '#f1f1f1') + ';color:' + (active ? '#fff' : '#333') + ';">' + monoEscapeHtml(lib.name) + '</button>';
      }).join('') +
    '</div>';
    if (!stickers.length) {
      grid.innerHTML = toolbar + '<div style="grid-column:1/-1;text-align:center;padding:30px;color:#bbb;"><i class="fas fa-smile" style="font-size:28px;display:block;margin-bottom:8px;"></i><div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;">表情包库为空<br>前往管理库添加</div></div>';
      return;
    }
    grid.innerHTML = toolbar + stickers.map(function(s, i){
      var src = monoStickerSrc(s);
      return '<div class="sticker-item" onclick="sendStickerFromLibrary(' + i + ')" title="' + monoEscapeAttr(s.caption || '') + '" style="display:block;min-width:0;min-height:0;">' +
        monoStickerImgHtml(src, s.caption) +
        '<div class="sticker-item-overlay"><div style="font-size:8px;color:#fff;text-align:center;padding:0 4px;">' + monoEscapeHtml(s.caption || '无描述') + (s._libraryName ? '<br><span style="opacity:0.8;">[' + monoEscapeHtml(s._libraryName) + ']</span>' : '') + '</div></div>' +
      '</div>';
    }).join('');
  };

  // 覆盖发送，确保发出的消息一定有 stickerSrc。
  var oldSendStickerFromLibrary = window.sendStickerFromLibrary;
  window.sendStickerFromLibrary = function(idx){
    try {
      if (!currentId) { closeStickerModal(); return; }
      var stickers = _stickerSendLibraryFilter === 'all' ? getStickers() : getStickers([_stickerSendLibraryFilter]);
      stickers = stickers.map(window._normalizeStickerItem).filter(function(s){ return !!s.src; });
      var s = stickers[idx];
      if (!s || !s.src) return;
      var p = personas.find(function(x){ return x.id == currentId; });
      var ts = Date.now();
      p.history.push({ role: 'user', msgType: 'sticker', stickerSrc: s.src, src: s.src, caption: s.caption, content: '[表情包' + (s.caption ? '（' + s.caption + '）' : '') + ']', timestamp: ts });
      p._lastUserChatTs = ts;
      p.lastUserMessageTime = ts;
      saveData(); renderMessages(); renderContactList();
      closeStickerModal();
      if (typeof _handleAuto回复AfterSend === 'function') _handleAuto回复AfterSend(currentId);
    } catch(e) {
      if (typeof oldSendStickerFromLibrary === 'function') return oldSendStickerFromLibrary.apply(this, arguments);
      throw e;
    }
  };

  // 覆盖批量添加弹窗里的 URL 预览，避免图片失败后直接空白。
  var oldRenderBatchStickerSlots = window.renderBatchStickerSlots;
  window.renderBatchStickerSlots = function(){
    try {
      var container = document.getElementById('batchStickerSlots');
      if (!container) return oldRenderBatchStickerSlots && oldRenderBatchStickerSlots();
      if (!_batchStickerSlots.length) {
        container.innerHTML = '<div style="text-align:center;padding:30px;color:#ccc;font-size:10px;text-transform:uppercase;letter-spacing:1px;">点击上方按钮添加表情包<br>最多可同时添加10个</div>';
        return;
      }
      container.innerHTML = _batchStickerSlots.map(function(slot, i){
        slot.src = monoCleanStickerUrl(slot.src);
        var statusClass = slot.status === 'success' ? 'success' : slot.status === 'error' ? 'error' : slot.status === 'loading' ? 'loading' : '';
        var statusText = slot.status === 'success' ? '✓ 已识别/已填写描述' : slot.status === 'error' ? '✗ 识别失败' : slot.status === 'loading' ? '识别中...' : '待识别';
        var descPreview = slot.desc ? slot.desc.slice(0, 30) + (slot.desc.length > 30 ? '...' : '') : '';
        return '<div class="batch-sticker-slot">' +
          '<div class="slot-preview" style="position:relative;" onclick="monoOpenStickerOriginalUrl(event, \'' + monoEscapeAttr(slot.src) + '\')">' + monoStickerImgHtml(slot.src, slot.desc) + '</div>' +
          '<div class="slot-info"><div style="font-size:10px;font-weight:700;">#' + (i+1) + (descPreview ? ' · ' + monoEscapeHtml(descPreview) : '') + '</div><div class="slot-status ' + statusClass + '">' + statusText + '</div></div>' +
          '<span class="slot-remove" onclick="removeBatchStickerSlot(' + i + ')"><i class="fas fa-times"></i></span>' +
        '</div>';
      }).join('');
    } catch(e) {
      if (typeof oldRenderBatchStickerSlots === 'function') return oldRenderBatchStickerSlots.apply(this, arguments);
      throw e;
    }
  };

  var oldOpenStickerModal = window.openStickerModal;
  window.openStickerModal = function(){
    monoNormalizeStoredStickerLibraries();
    if (typeof oldOpenStickerModal === 'function') return oldOpenStickerModal.apply(this, arguments);
    var modal = document.getElementById('stickerModal');
    if (modal) modal.classList.add('show');
    if (typeof renderStickerSendView === 'function') renderStickerSendView();
  };
})();



;
// ===== script-68 =====

/* ===== MONO PATCH v6: 玻璃主题表情包库弹层完整显示修复 =====
   目的：表情包库原本作为 chatPage 内部 absolute 弹层，玻璃主题 chatPage 使用 overflow:hidden/grid 高度后会被裁切。
   做法：打开表情包库时把弹层临时提升到 body 层级，并使用 fixed + 100dvh 安全区布局。 */
(function(){
  if (window.__monoStickerModalViewportPatchV6) return;
  window.__monoStickerModalViewportPatchV6 = true;

  function ensureStickerViewportStyle(){
    if (document.getElementById('monoStickerViewportPatchStyleV6')) return;
    var style = document.createElement('style');
    style.id = 'monoStickerViewportPatchStyleV6';
    style.textContent = `
      /* 表情包库弹层：脱离聊天室内部裁切，固定在真实屏幕视口 */
      body.mono-sticker-modal-open {
        overflow: hidden !important;
        touch-action: none;
      }
      body.mono-sticker-modal-open #stickerModal.sticker-modal-overlay,
      #stickerModal.mono-sticker-viewport-fixed.sticker-modal-overlay {
        position: fixed !important;
        left: 0 !important;
        right: 0 !important;
        top: 0 !important;
        bottom: 0 !important;
        width: 100vw !important;
        height: 100dvh !important;
        min-height: 100dvh !important;
        max-height: 100dvh !important;
        z-index: 999999 !important;
        display: none;
        align-items: flex-end !important;
        justify-content: center !important;
        padding: calc(env(safe-area-inset-top, 0px) + 10px) 10px calc(env(safe-area-inset-bottom, 0px) + 10px) !important;
        box-sizing: border-box !important;
        overflow: hidden !important;
        background: rgba(0,0,0,0.46) !important;
        backdrop-filter: blur(10px) saturate(1.05);
        -webkit-backdrop-filter: blur(10px) saturate(1.05);
      }
      body.mono-sticker-modal-open #stickerModal.sticker-modal-overlay.show,
      #stickerModal.mono-sticker-viewport-fixed.sticker-modal-overlay.show {
        display: flex !important;
      }
      #stickerModal.mono-sticker-viewport-fixed .sticker-modal-box {
        width: min(100%, 520px) !important;
        height: min(84dvh, calc(100dvh - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px) - 28px)) !important;
        max-height: none !important;
        min-height: min(520px, 70dvh) !important;
        border-radius: 22px 22px 0 0 !important;
        overflow: hidden !important;
        display: flex !important;
        flex-direction: column !important;
        box-sizing: border-box !important;
      }
      #stickerModal.mono-sticker-viewport-fixed .sticker-modal-header,
      #stickerModal.mono-sticker-viewport-fixed .sticker-modal-tabs {
        flex: 0 0 auto !important;
      }
      #stickerModal.mono-sticker-viewport-fixed #stickerSendView,
      #stickerModal.mono-sticker-viewport-fixed .sticker-grid {
        flex: 1 1 auto !important;
        min-height: 0 !important;
        overflow-y: auto !important;
        -webkit-overflow-scrolling: touch !important;
        overscroll-behavior: contain !important;
        box-sizing: border-box !important;
      }
      #stickerModal.mono-sticker-viewport-fixed #stickerManageView {
        flex: 1 1 auto !important;
        min-height: 0 !important;
        overflow-y: auto !important;
        -webkit-overflow-scrolling: touch !important;
        overscroll-behavior: contain !important;
        box-sizing: border-box !important;
      }
      #stickerModal.mono-sticker-viewport-fixed #stickerManageGrid {
        min-height: 0 !important;
        overflow: visible !important;
      }
      /* 小屏幕再压低一点，避免顶部或底部被 iOS 工具栏/安全区吃掉 */
      @media (max-height: 700px) {
        #stickerModal.mono-sticker-viewport-fixed .sticker-modal-box {
          height: calc(100dvh - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px) - 20px) !important;
          min-height: 0 !important;
        }
      }
      @supports not (height: 100dvh) {
        body.mono-sticker-modal-open #stickerModal.sticker-modal-overlay,
        #stickerModal.mono-sticker-viewport-fixed.sticker-modal-overlay {
          height: 100vh !important;
          min-height: 100vh !important;
          max-height: 100vh !important;
        }
        #stickerModal.mono-sticker-viewport-fixed .sticker-modal-box {
          height: min(84vh, calc(100vh - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px) - 28px)) !important;
        }
      }
    `;
    document.head.appendChild(style);
  }

  function portalStickerModal(){
    ensureStickerViewportStyle();
    var modal = document.getElementById('stickerModal');
    if (!modal) return null;
    modal.classList.add('mono-sticker-viewport-fixed');
    if (modal.parentElement !== document.body) {
      modal.setAttribute('data-mono-original-parent', 'chatPage');
      document.body.appendChild(modal);
    }
    return modal;
  }

  var oldOpen = window.openStickerModal;
  window.openStickerModal = function(){
    var modal = portalStickerModal();
    document.body.classList.add('mono-sticker-modal-open');
    try {
      if (typeof closePlusPanel === 'function') closePlusPanel();
      if (typeof getStickerLibraries === 'function') getStickerLibraries();
      if (typeof renderStickerSendView === 'function') renderStickerSendView();
      if (modal) modal.classList.add('show');
      if (typeof switchStickerTab === 'function') switchStickerTab('send');
    } catch(e) {
      if (typeof oldOpen === 'function') return oldOpen.apply(this, arguments);
      throw e;
    }
    setTimeout(function(){
      var box = modal && modal.querySelector('.sticker-modal-box');
      var view = modal && modal.querySelector('#stickerSendView');
      if (box) box.scrollTop = 0;
      if (view) view.scrollTop = 0;
    }, 0);
  };

  var oldClose = window.closeStickerModal;
  window.closeStickerModal = function(){
    var modal = document.getElementById('stickerModal');
    if (modal) modal.classList.remove('show');
    document.body.classList.remove('mono-sticker-modal-open');
    if (typeof oldClose === 'function') {
      try { oldClose.apply(this, arguments); } catch(e) {}
    }
  };

  // 点遮罩空白处关闭；点内容区不关闭。
  document.addEventListener('click', function(e){
    var modal = document.getElementById('stickerModal');
    if (!modal || !modal.classList.contains('show')) return;
    if (e.target === modal) {
      e.preventDefault();
      if (typeof closeStickerModal === 'function') closeStickerModal();
    }
  }, true);

  // iOS 旋转屏幕/地址栏变化后，重新计算滚动区域。
  window.addEventListener('resize', function(){
    var modal = document.getElementById('stickerModal');
    if (!modal || !modal.classList.contains('show')) return;
    modal.classList.remove('mono-sticker-viewport-fixed');
    void modal.offsetHeight;
    modal.classList.add('mono-sticker-viewport-fixed');
  });
})();


