// ===== mono-moments-forward-modal-v7-script =====

(function(){
  'use strict';
  function ensureForwardOverlayOnBody(){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (!overlay) return null;
    overlay.classList.add('mono-fwd-fixed-overlay');
    /* 关键：从 phone-container / momentsPage 内提升到 body，避免当前页面层级挡住弹窗，导致退出朋友圈才看见 */
    if (overlay.parentElement !== document.body) {
      try { document.body.appendChild(overlay); } catch(e) {}
    }
    return overlay;
  }
  function safeText(v){ return (v == null ? '' : String(v)); }
  function safeHtml(v){
    return safeText(v).replace(/[&<>'"]/g, function(ch){
      return ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[ch];
    });
  }
  function openOverlay(){
    var overlay = ensureForwardOverlayOnBody();
    if (!overlay) return;
    overlay.classList.add('open','mono-force-open');
    overlay.style.display = 'flex';
    overlay.style.visibility = 'visible';
    overlay.style.opacity = '1';
    document.body.classList.add('mono-fwd-modal-open');
  }
  function closeOverlay(){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (!overlay) return;
    overlay.classList.remove('open','mono-force-open');
    overlay.style.display = 'none';
    document.body.classList.remove('mono-fwd-modal-open');
  }
  window.openFwdPersonaModal = function(帖子Data){
    try {
      if (!window.personas || !personas.length) { alert('请先创建一个角色后再转发！'); return; }
      window._fwdPayload = 帖子Data || null;
      var list = document.getElementById('fwdPersonaList');
      if (!list) return;
      list.innerHTML = personas.map(function(p){
        var avatar = safeHtml(p.avatar || '');
        var name = safeHtml(p.name || '未命名角色');
        var subRaw = safeText(p.persona || '');
        var sub = safeHtml(subRaw.slice(0, 22) + (subRaw.length > 22 ? '…' : ''));
        return '<div class="fwd-persona-item" onclick="doForwardToPersona(\'' + monoJsSingleQuote(p.id) + '\')">'
          + '<img src="'+ avatar +'" alt="'+ name +'" onerror="this.style.opacity=.25">'
          + '<div><div class="fwd-persona-item-name">'+ name +'</div>'
          + '<div class="fwd-persona-item-sub">'+ sub +'</div></div></div>';
      }).join('');
      openOverlay();
      setTimeout(openOverlay, 0);
      setTimeout(openOverlay, 80);
    } catch(err) {
      console.warn('openFwdPersonaModal v7 failed:', err);
      alert('打开转发页面失败：' + (err && err.message ? err.message : err));
    }
  };
  window.closeFwdPersonaModal = function(e){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (e && overlay && e.target !== overlay) return;
    closeOverlay();
    window._fwdPayload = null;
  };
  /* 防止旧函数直接移除 open 后留下 body 锁定 */
  document.addEventListener('click', function(e){
    var cancel = e.target && e.target.closest && e.target.closest('.fwd-persona-cancel');
    if (cancel && document.getElementById('fwdPersonaOverlay')) {
      closeOverlay();
      window._fwdPayload = null;
    }
  }, true);
  document.addEventListener('keydown', function(e){
    if (e.key === 'Escape') {
      var overlay = document.getElementById('fwdPersonaOverlay');
      if (overlay && overlay.classList.contains('open')) {
        closeOverlay();
        window._fwdPayload = null;
      }
    }
  });
  document.addEventListener('DOMContentLoaded', ensureForwardOverlayOnBody);
  setTimeout(ensureForwardOverlayOnBody, 500);
})();


