// ===== mono-moments-forward-role-source-v8-script =====

(function(){
  'use strict';
  function getForwardPersonas(){
    /* 关键修复：原角色数组是顶层 let personas，不会挂到 window.personas。
       v7 用 window.personas 判断，所以会误判为空并提示“需要创建角色”。 */
    try {
      if (typeof personas !== 'undefined' && Array.isArray(personas)) return personas;
    } catch(e) {}
    try {
      if (Array.isArray(window.personas)) return window.personas;
    } catch(e) {}
    try {
      var raw = localStorage.getItem('mono_personas');
      var parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed : [];
    } catch(e) {}
    return [];
  }
  function setForwardPayload(data){
    try { if (typeof _fwdPayload !== 'undefined') { _fwdPayload = data || null; return; } } catch(e) {}
    try { window._fwdPayload = data || null; } catch(e) {}
  }
  function getForwardPayload(){
    try { if (typeof _fwdPayload !== 'undefined') return _fwdPayload; } catch(e) {}
    return window._fwdPayload || null;
  }
  function clearForwardPayload(){ setForwardPayload(null); }
  function ensureForwardOverlayOnBody(){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (!overlay) return null;
    overlay.classList.add('mono-fwd-fixed-overlay');
    if (overlay.parentElement !== document.body) {
      try { document.body.appendChild(overlay); } catch(e) {}
    }
    return overlay;
  }
  function safeText(v){ return (v == null ? '' : String(v)); }
  function safeHtml(v){
    return safeText(v).replace(/[&<>'"]/g, function(ch){
      return ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[ch];
    });
  }
  function openOverlay(){
    var overlay = ensureForwardOverlayOnBody();
    if (!overlay) return;
    overlay.classList.add('open','mono-force-open');
    overlay.style.display = 'flex';
    overlay.style.visibility = 'visible';
    overlay.style.opacity = '1';
    document.body.classList.add('mono-fwd-modal-open');
  }
  function closeOverlay(){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (!overlay) return;
    overlay.classList.remove('open','mono-force-open');
    overlay.style.display = 'none';
    document.body.classList.remove('mono-fwd-modal-open');
  }

  window.openFwdPersonaModal = function(帖子Data){
    try {
      var ps = getForwardPersonas().filter(function(p){ return p && p.id != null; });
      var list = document.getElementById('fwdPersonaList');
      if (!list) return alert('打开转发页面失败：找不到角色列表容器。');
      setForwardPayload(帖子Data || null);
      if (!ps.length) {
        list.innerHTML = '<div class="fwd-persona-empty">当前没有可转发的角色。<br>如果你已经创建过角色，请先返回聊天页让角色数据加载完成后再试。</div>';
        openOverlay();
        return;
      }
      list.innerHTML = ps.map(function(p){
        var avatar = safeHtml(p.avatar || '');
        var name = safeHtml(p.name || '未命名角色');
        var subRaw = safeText(p.persona || '');
        var sub = safeHtml(subRaw.slice(0, 22) + (subRaw.length > 22 ? '…' : ''));
        var id = String(p.id).replace(/[^\w.-]/g, '');
        return '<div class="fwd-persona-item" data-fwd-pid="'+ safeHtml(id) +'">'
          + '<img src="'+ avatar +'" alt="'+ name +'" onerror="this.style.opacity=.25">'
          + '<div><div class="fwd-persona-item-name">'+ name +'</div>'
          + '<div class="fwd-persona-item-sub">'+ sub +'</div></div></div>';
      }).join('');
      openOverlay();
      setTimeout(openOverlay, 0);
      setTimeout(openOverlay, 80);
    } catch(err) {
      console.warn('openFwdPersonaModal v8 failed:', err);
      alert('打开转发页面失败：' + (err && err.message ? err.message : err));
    }
  };

  /* 用事件代理转发，避免 innerHTML onclick 在某些 id 格式下失效 */
  document.addEventListener('click', function(e){
    var item = e.target && e.target.closest && e.target.closest('#fwdPersonaList .fwd-persona-item[data-fwd-pid]');
    if (!item) return;
    var pid = item.getAttribute('data-fwd-pid');
    if (!pid) return;
    try { window.doForwardToPersona(pid); } catch(err) { alert('转发失败：' + (err && err.message ? err.message : err)); }
  }, true);

  var oldClose = window.closeFwdPersonaModal;
  window.closeFwdPersonaModal = function(e){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (e && overlay && e.target !== overlay) return;
    closeOverlay();
    clearForwardPayload();
  };

  /* 包一层原转发函数：确保它读到的是顶层 let _fwdPayload，不是 window._fwdPayload。 */
  var oldDoForward = window.doForwardToPersona;
  window.doForwardToPersona = function(personaId){
    var payload = getForwardPayload();
    if (!payload) return alert('转发失败：没有找到要转发的内容。');
    setForwardPayload(payload);
    if (typeof oldDoForward === 'function') return oldDoForward(personaId);
    alert('转发失败：找不到原转发函数。');
  };

  document.addEventListener('DOMContentLoaded', ensureForwardOverlayOnBody);
  setTimeout(ensureForwardOverlayOnBody, 300);
})();


