// ===== mono-moments-forward-v9-script =====

(function(){
  'use strict';

  function safeText(v){ return v == null ? '' : String(v); }
  function safeHtml(v){
    return safeText(v).replace(/[&<>'"]/g, function(ch){
      return ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'})[ch];
    });
  }
  function getPersonasSafe(){
    try { if (typeof personas !== 'undefined' && Array.isArray(personas)) return personas; } catch(e) {}
    try { if (Array.isArray(window.personas)) return window.personas; } catch(e) {}
    try {
      var raw = localStorage.getItem('mono_personas');
      var parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed : [];
    } catch(e) {}
    return [];
  }
  function setPayloadSafe(data){
    var payload = data || null;
    try { if (typeof _fwdPayload !== 'undefined') _fwdPayload = payload; } catch(e) {}
    try { window._fwdPayload = payload; } catch(e) {}
    try { window.__monoLastForwardPayload = payload; } catch(e) {}
    try {
      if (payload) sessionStorage.setItem('__monoLastForwardPayload', JSON.stringify(payload));
      else sessionStorage.removeItem('__monoLastForwardPayload');
    } catch(e) {}
  }
  function getPayloadSafe(){
    try { if (typeof _fwdPayload !== 'undefined' && _fwdPayload) return _fwdPayload; } catch(e) {}
    try { if (window._fwdPayload) return window._fwdPayload; } catch(e) {}
    try { if (window.__monoLastForwardPayload) return window.__monoLastForwardPayload; } catch(e) {}
    try {
      var raw = sessionStorage.getItem('__monoLastForwardPayload');
      if (raw) return JSON.parse(raw);
    } catch(e) {}
    return null;
  }
  function ensureOverlay(){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (!overlay) return null;
    overlay.classList.add('mono-fwd-fixed-overlay');
    if (overlay.parentElement !== document.body) {
      try { document.body.appendChild(overlay); } catch(e) {}
    }
    return overlay;
  }
  function openOverlay(){
    var overlay = ensureOverlay();
    if (!overlay) return;
    overlay.classList.add('open','mono-force-open');
    overlay.style.display = 'flex';
    overlay.style.visibility = 'visible';
    overlay.style.opacity = '1';
    document.body.classList.add('mono-fwd-modal-open');
  }
  function closeOverlay(clear){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (overlay) {
      overlay.classList.remove('open','mono-force-open');
      overlay.style.display = 'none';
    }
    document.body.classList.remove('mono-fwd-modal-open');
    if (clear !== false) setPayloadSafe(null);
  }

  var nativeDoForward = null;
  try {
    nativeDoForward = window.doForwardToPersona;
    while (nativeDoForward && nativeDoForward.__monoWrappedForward && nativeDoForward.__monoOriginalForward) {
      nativeDoForward = nativeDoForward.__monoOriginalForward;
    }
  } catch(e) {}

  window.openFwdPersonaModal = function(帖子Data){
    try {
      setPayloadSafe(帖子Data || null);
      var list = document.getElementById('fwdPersonaList');
      if (!list) return alert('打开转发页面失败：找不到角色列表容器。');
      var ps = getPersonasSafe().filter(function(p){ return p && p.id != null; });
      if (!ps.length) {
        list.innerHTML = '<div class="fwd-persona-empty">当前没有可转发的角色。<br>如果已经创建过角色，请先返回聊天页让角色数据加载完成后再试。</div>';
      } else {
        list.innerHTML = ps.map(function(p){
          var id = safeHtml(p.id);
          var avatar = safeHtml(p.avatar || '');
          var name = safeHtml(p.name || '未命名角色');
          var subRaw = safeText(p.persona || '');
          var sub = safeHtml(subRaw.slice(0, 22) + (subRaw.length > 22 ? '…' : ''));
          return '<div class="fwd-persona-item" data-fwd-pid="'+ id +'">'
            + '<img src="'+ avatar +'" alt="'+ name +'" onerror="this.style.opacity=.25">'
            + '<div><div class="fwd-persona-item-name">'+ name +'</div>'
            + '<div class="fwd-persona-item-sub">'+ sub +'</div></div></div>';
        }).join('');
      }
      openOverlay();
      setTimeout(openOverlay, 0);
      setTimeout(openOverlay, 80);
    } catch(err) {
      console.warn('openFwdPersonaModal v9 failed:', err);
      alert('打开转发页面失败：' + (err && err.message ? err.message : err));
    }
  };

  window.closeFwdPersonaModal = function(e){
    var overlay = document.getElementById('fwdPersonaOverlay');
    if (e && overlay && e.target !== overlay) return;
    closeOverlay(true);
  };

  function forwardDirect(personaId){
    var payload = getPayloadSafe();
    if (!payload) {
      /* 之前这里弹“没有找到转发内容”，但旧 onclick 还会继续执行，造成“报错但其实转发成功”。
         v9 不再误报；只在真的没有 payload 且无法转发时安静返回。 */
      console.warn('MONO forward skipped: payload missing before click.');
      return false;
    }
    setPayloadSafe(payload);
    if (typeof nativeDoForward === 'function') {
      nativeDoForward(personaId);
    } else {
      var ps = getPersonasSafe();
      var p = ps.find(function(x){ return String(x.id) === String(personaId); });
      if (!p) return alert('转发失败：找不到选择的角色。');
      if (!p.history) p.history = [];
      p.history.push({
        role: 'user',
        msgType: 'forwarded_帖子',
        fwdData: payload,
        content: '[转发了一篇' + (payload.source === 'forum' ? '论坛帖子' : '朋友圈动态') + ']',
        time: Date.now()
      });
      try { if (typeof saveData === 'function') saveData(); } catch(e) {}
      try { if (typeof openApp === 'function') openApp('chatPage'); } catch(e) {}
      try { if (typeof selectPersona === 'function') selectPersona(personaId); } catch(e) {}
    }
    closeOverlay(true);
    setTimeout(function(){
      try {
        if (typeof openApp === 'function') openApp('chatPage');
        if (typeof selectPersona === 'function') selectPersona(personaId);
        document.querySelectorAll('.nav-item').forEach(function(n){ n.classList.remove('active'); });
        var navChat = document.getElementById('nav-chat');
        if (navChat) navChat.classList.add('active');
        var box = document.getElementById('chatBox');
        if (box) box.scrollTop = box.scrollHeight;
      } catch(e) {}
    }, 80);
    return true;
  }

  window.doForwardToPersona = function(personaId){ return forwardDirect(personaId); };
  window.doForwardToPersona.__monoWrappedForward = true;
  window.doForwardToPersona.__monoOriginalForward = nativeDoForward;

  document.addEventListener('click', function(e){
    var item = e.target && e.target.closest && e.target.closest('#fwdPersonaList .fwd-persona-item[data-fwd-pid]');
    if (!item) return;
    e.preventDefault();
    e.stopPropagation();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    var pid = item.getAttribute('data-fwd-pid');
    if (pid) forwardDirect(pid);
  }, true);

  document.addEventListener('click', function(e){
    var cancel = e.target && e.target.closest && e.target.closest('.fwd-persona-cancel');
    if (cancel) {
      e.preventDefault();
      closeOverlay(true);
    }
  }, true);

  document.addEventListener('DOMContentLoaded', ensureOverlay);
  setTimeout(ensureOverlay, 300);
})();


