/* === MONO MULTIWORLD SWITCH FINAL FIX v3 ===
   修复 v2 误报“找不到该世界”：
   - 世界列表同时从 raw localStorage、proxy localStorage 读取并合并
   - 点击按钮时直接信任 data-mw-switch 的世界 id
   - 若 raw 列表缺失该 id，会先补回世界列表再切换，避免刷新后 active 世界丢失
*/
(function(){
  'use strict';
  if (window.__monoMultiWorldSwitchFinalFixV3) return;
  window.__monoMultiWorldSwitchFinalFixV3 = true;

  function rawLS(){ return window._monoRawLocalStorage || window.localStorage; }
  function parseList(raw){
    try { var arr = JSON.parse(raw || '[]'); return Array.isArray(arr) ? arr : []; }
    catch(e){ return []; }
  }
  function uniqMerge(a,b){
    var map = {}, out = [];
    (a || []).concat(b || []).forEach(function(w){
      if (!w || !w.id) return;
      var id = String(w.id);
      if (!map[id]) { map[id] = Object.assign({}, w, { id: id }); out.push(map[id]); }
      else { Object.assign(map[id], w, { id: id }); }
    });
    return out;
  }
  function getWorldsMerged(){
    var raw = [];
    var prox = [];
    try { raw = parseList(rawLS().getItem('mono_multiworld_worlds')); } catch(e) {}
    try { prox = parseList(window.localStorage.getItem('mono_multiworld_worlds')); } catch(e) {}
    return uniqMerge(raw, prox);
  }
  function saveWorldsEverywhere(worlds){
    var json = JSON.stringify(worlds || []);
    try { rawLS().setItem('mono_multiworld_worlds', json); } catch(e) {}
    try { window.localStorage.setItem('mono_multiworld_worlds', json); } catch(e) {}
    try {
      if (window._idb) {
        var tx = window._idb.transaction('kv', 'readwrite');
        tx.objectStore('kv').put(json, 'mono_multiworld_worlds');
      }
    } catch(e) {}
  }
  function ensureWorldExists(worldId, fallbackName){
    worldId = String(worldId || '').trim();
    if (!worldId) return null;
    var worlds = getWorldsMerged();
    var world = worlds.find(function(w){ return w && String(w.id) === worldId; });
    if (!world) {
      world = { id: worldId, name: fallbackName || '未命名世界', desc: '', userPersona: '', createdAt: Date.now() };
      worlds.push(world);
      saveWorldsEverywhere(worlds);
    } else {
      saveWorldsEverywhere(worlds);
    }
    return world;
  }
  function writeActive(worldId, done){
    worldId = String(worldId || '').trim();
    try { rawLS().setItem('mono_multiworld_enabled', 'true'); } catch(e) {}
    try { rawLS().setItem('mono_multiworld_active', worldId); } catch(e) {}
    try { window.localStorage.setItem('mono_multiworld_enabled', 'true'); } catch(e) {}
    try { window.localStorage.setItem('mono_multiworld_active', worldId); } catch(e) {}
    try { if (window.__monoRealLSSet) window.__monoRealLSSet('mono_multiworld_active', worldId); } catch(e) {}
    var finished = false;
    function finish(){ if (finished) return; finished = true; if (done) done(); }
    try {
      if (window._idb) {
        var tx = window._idb.transaction('kv', 'readwrite');
        var st = tx.objectStore('kv');
        st.put('true', 'mono_multiworld_enabled');
        st.put(worldId, 'mono_multiworld_active');
        tx.oncomplete = finish;
        tx.onerror = finish;
        setTimeout(finish, 400);
        return;
      }
    } catch(e) {}
    finish();
  }
  function finalSwitch(worldId, fallbackName){
    worldId = String(worldId || '').trim();
    if (!worldId) { alert('世界 ID 为空，请重新打开“我的”再试。'); return; }
    ensureWorldExists(worldId, fallbackName);
    writeActive(worldId, function(){
      try { sessionStorage.setItem('mono_after_world_switch', worldId); } catch(e) {}
      (window.monoSafeReload ? window.monoSafeReload('legacy') : location.reload());
    });
  }
  function confirmSwitch(worldId, fallbackName){
    worldId = String(worldId || '').trim();
    if (!worldId) { alert('世界 ID 为空，请重新打开“我的”再试。'); return; }
    var world = ensureWorldExists(worldId, fallbackName);
    var name = (world && world.name) || fallbackName || '该世界';
    var old = document.getElementById('monoMwFinalConfirm');
    if (old) old.remove();
    var div = document.createElement('div');
    div.id = 'monoMwFinalConfirm';
    div.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:20px;';
    div.innerHTML = '<div style="width:min(320px,92vw);background:#fff;border-radius:18px;padding:22px;box-shadow:0 18px 60px rgba(0,0,0,.25);font-family:inherit;">'
      + '<div style="font-weight:800;font-size:16px;margin-bottom:8px;">切换世界</div>'
      + '<div style="font-size:13px;line-height:1.6;color:#333;margin-bottom:18px;">进入「<b></b>」？页面会重新载入到该世界。</div>'
      + '<div style="display:flex;gap:10px;">'
      + '<button type="button" data-final-cancel style="flex:1;padding:10px;border-radius:12px;border:1px solid #ddd;background:#f6f6f6;font-weight:700;font-family:inherit;">取消</button>'
      + '<button type="button" data-final-ok style="flex:1;padding:10px;border-radius:12px;border:0;background:#1a1a1a;color:#fff;font-weight:800;font-family:inherit;">进入</button>'
      + '</div></div>';
    document.body.appendChild(div);
    var b = div.querySelector('b'); if (b) b.textContent = name;
    div.querySelector('[data-final-cancel]').onclick = function(){ div.remove(); };
    div.querySelector('[data-final-ok]').onclick = function(){ div.remove(); finalSwitch(worldId, name); };
  }
  function getButtonWorldName(btn){
    try {
      var card = btn.closest('div[style*="display:flex"]');
      var title = card && card.querySelector('div[style*="font-size:13px"]');
      return title ? (title.textContent || '').replace('当前','').trim() : '';
    } catch(e) { return ''; }
  }
  function install(){
    try { window.mwSwitchWorld = function(id){ confirmSwitch(id); }; } catch(e) {}
    try { mwSwitchWorld = window.mwSwitchWorld; } catch(e) {}
  }
  document.addEventListener('click', function(e){
    var btn = e.target && e.target.closest && e.target.closest('[data-mw-switch]');
    if (!btn) return;
    var id = btn.getAttribute('data-mw-switch');
    if (!id) return;
    e.preventDefault();
    e.stopPropagation();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    confirmSwitch(id, getButtonWorldName(btn));
  }, true);
  install();
  document.addEventListener('DOMContentLoaded', install);
  setTimeout(install, 250);
  setTimeout(install, 1000);
})();


