  function entHasApi(){
    try {
      return !!(apiConfig && apiConfig.url && apiConfig.key);
    } catch(e) {
      return false;
    }
  }
  function entApiUrl(){
    try { if (typeof getApiUrl === 'function') return getApiUrl(); } catch(e) {}
    try { if (typeof _buildApiChatCandidates === 'function' && apiConfig && apiConfig.url) return _buildApiChatCandidates(apiConfig.url)[0]; } catch(e2) {}
    try { return String(apiConfig.url || '').replace(/\/+$/, '') + '/chat/completions'; } catch(e3) { return ''; }
  }
  function entApplyModel(body){
    try {
      if (typeof _applyApiModel === 'function') return _applyApiModel(body, apiConfig.model || apiConfig);
    } catch(e) {}
    if (apiConfig && apiConfig.model) body.model = apiConfig.model;
    return body;
  }
  function entExtractContent(data){
    try {
      if (typeof _extractAssistantMessageContent === 'function') return String(_extractAssistantMessageContent(data) || '');
    } catch(e) {}
    try {
      return String((((data || {}).choices || [])[0] || {}).message.content || '');
    } catch(e2) {
      return '';
    }
  }
  function entParseJson(raw){
    raw = String(raw || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
    if (!raw) return null;
    try { return JSON.parse(raw); } catch(e) {}
    var matchObj = raw.match(/\{[\s\S]*\}/);
    if (matchObj) { try { return JSON.parse(matchObj[0]); } catch(e2) {} }
    var matchArr = raw.match(/\[[\s\S]*\]/);
    if (matchArr) { try { return JSON.parse(matchArr[0]); } catch(e3) {} }
    return null;
  }
  function entIndustrySpecificityGuide(mode){
    var common = [
      '所有文案都要像真实娱乐圈从业语境，不要写成设定简介、内容梗概或空泛总结。',
      '文字必须尽量落到具体讨论点，比如哪句采访、哪组图、哪类镜头、哪种粉圈争论、哪种商务顾虑、哪种媒体口径。',
      '不要只写“热度上升”“争议变大”“资源变好”“口碑下滑”这种抽象话，要写清是谁在讨论、为什么被讨论、具体在吵什么。',
      '允许出现真实的小细节，比如站姐图、群访、候场、路透、控评、切词条、品牌观望、超话风向、后援会态度、采访措辞。',
      '不要动不动“封神”“赢麻了”“全网都在夸”；真实娱乐圈更多是分层讨论、局部出圈、圈内外温差和风向拉扯。'
    ];
    if (mode === 'comments') common.push('评论要像真实微博用户，不要像同一个人批量发言；有人很短、有人阴阳、有人认真分析，但都要围绕具体点。');
    if (mode === 'briefing') common.push('公司简报要像内部日报，明确写今天谁最受关注、哪条舆论最危险、哪个环节出问题、接下来先处理什么。');
    if (mode === 'hot') common.push('热搜摘要要像真实词条发酵，不要只写“状态绝了”，要具体到造型、发言、同框、作品切片或爆料内容。');
    if (mode === 'marketing') common.push('营销号内容要像真的娱乐号口吻，能看出是在放风、试水、带节奏、捧人还是半真半假吊话题。');
    if (mode === 'paparazzi') common.push('狗仔事件要写出被拍到的场景、时间感、镜头感和最容易被解读的点，不要只写“被拍到了”。');
    if (mode === 'redcarpet') common.push('红毯内容要具体到造型路线、镜头反馈、媒体提问、同场对象和粉圈最在意的细节。');
    if (mode === 'interview') common.push('采访问题和回答要像真实媒体会问、艺人会答的话，不要像系统示例。');
    if (mode === 'pr') common.push('公关处理结果要像真实复盘，明确谁买账、谁更生气、舆论怎么偏移、下一步为什么这么做。');
    return common.join('\n');
  }
  async function entAskJson(prompt, fallbackData, maxTokens){
    if (!entHasApi()) return entDeepCopy(fallbackData);
    try {
      var url = entApiUrl();
      var fetchFn = window.__monoV15OriginalFetch || window.__monoV17RawFetch || window.__monoOriginalFetch || window.fetch;
      var body = entApplyModel({
        messages: [
          { role:'system', content:'你是娱乐圈生态系统生成器。请严格只输出 JSON，不要输出 Markdown、解释或额外前缀。所有文案使用简体中文。生成时不要套模板，不要机械重复，不要默认所有内容都往“赢了、封神、逆袭、全网夸”方向走。允许复杂、暧昧、翻车、拉扯、平淡、黑红、错位、冷场、空转、反转等结果。你可以在符合角色和公司逻辑的前提下大胆发挥创意，内容范围要广，措辞要新。最重要的是要像真实娱乐圈生态，不要像概括介绍。' },
          { role:'user', content: prompt + '\n\n通用额外要求：\n1. 避免重复最近已经生成过的意象、句式和标题。\n2. 不要只照着参考信息改写，要在逻辑内做扩展。\n3. 不要总写同一种结局或同一种情绪。\n4. 如果涉及舆论，允许观点分裂，不要强行统一口径。\n5. 不要空泛，不要 general，要更贴地、更像真实娱乐圈系统会生成出来的内容。\n6. 能具体就不要抽象，能写明讨论点就不要只写“争议很大”“状态很好”。\n7. 最近生成过的内容参考（禁止直接复用）：\n' + (entRecentCreativeSnippets(18) || '无') + '\n\n具体度要求：\n' + entIndustrySpecificityGuide('generic') }
        ],
        temperature: 0.96,
        max_tokens: maxTokens || 1800,
        stream: false
      });
      var headers = { 'Content-Type':'application/json' };
      if (apiConfig && apiConfig.key) headers.Authorization = 'Bearer ' + apiConfig.key;
      var resp = await fetchFn(url, { method:'POST', headers:headers, body:JSON.stringify(body) });
      if (!resp.ok) throw new Error('API错误 ' + resp.status);
      var data = await resp.json();
      var parsed = entParseJson(entExtractContent(data));
      return parsed && typeof parsed === 'object' ? parsed : entDeepCopy(fallbackData);
    } catch(err) {
      console.warn('[entertainment api fallback]', err);
      return entDeepCopy(fallbackData);
    }
  }
  async function entRunBusy(label, fn){
    entState.ui.busy = label || '生成中';
    entSaveState();
    entRenderApp();
    try {
      await fn();
    } catch(err) {
      console.error('[entertainment busy action failed]', err);
      entToast((label || '生成') + '失败：' + (err && err.message || '未知错误'));
    } finally {
      entState.ui.busy = '';
      entSaveState();
      entRenderApp();
    }
  }
  function entAddPersonaToCompany(personaId){
    var persona = entFindPersona(personaId);
    if (!persona) return entToast('没找到这个角色。');
    var exists = entState.roster.find(function(item){ return String(item.sourcePersonaId) === String(personaId); });
    if (exists) return entToast('这个角色已经在公司里了。');
    var prof = entFallbackArtistProfile(persona, {});
    var artist = entNormalizeArtist({
      id: entUid('artist'),
      sourcePersonaId: persona.id,
      name: persona.name || '未命名角色',
      avatar: persona.avatar || '',
      profession: prof.profession,
      publicIdentity: prof.publicIdentity,
      publicPersona: prof.publicPersona,
      privatePersona: prof.privatePersona,
      fanName: prof.fanName,
      color: prof.color,
      debutStatus: prof.debutStatus,
      intro: prof.intro,
      fans: prof.stats.fans,
      heat: prof.stats.heat,
      reputation: prof.stats.reputation,
      risk: prof.stats.risk,
      cp: prof.stats.cp,
      commercial: prof.stats.commercial,
      mystery: prof.stats.mystery,
      mood: prof.mood,
      weiboName: (persona.name || '艺人') + 'Official'
    });
    entState.roster.push(artist);
    entState.company.favoritism[artist.id] = entState.company.favoritism[artist.id] || entRand(28, 58);
    entState.ui.selectedArtist = artist.id;
    if (!entState.ui.pairA) entState.ui.pairA = artist.id;
    else if (!entState.ui.pairB && entState.ui.pairA !== artist.id) entState.ui.pairB = artist.id;
    entRecordEvent('roster', '艺人加入公司', artist.name + ' 已进入 ' + entState.company.name, 'artist', artist.id);
    entSaveState();
    entRenderApp();
    entRenderPersonaSheet();
  }
  async function entGenerateCompanyProfile(){
    var companyName = (document.getElementById('entCompanyName') || {}).value || entState.company.name;
    var companyStyle = (document.getElementById('entCompanyStyle') || {}).value || entState.company.style;
    var companyFocus = (document.getElementById('entCompanyFocus') || {}).value || entState.company.focus;
    entState.company.name = companyName;
    entState.company.style = companyStyle;
    entState.company.focus = companyFocus;
    await entRunBusy('正在生成公司定位', async function(){
      var fallback = entFallbackCompanySummary();
      var res = await entAskJson(
        '请为娱乐公司生成 JSON 对象，字段为 {"summary":"","dailyMood":"","lastPriority":"","officialAccountName":""}。公司名：' + companyName + '。公司风格：' + companyStyle + '。核心发展方向：' + companyFocus + '。',
        Object.assign({ officialAccountName: companyName + ' 官方' }, fallback),
        900
      );
      entState.company.summary = res.summary || fallback.summary;
      entState.company.dailyMood = res.dailyMood || fallback.dailyMood;
      entState.company.lastPriority = res.lastPriority || fallback.lastPriority;
      entState.company.officialAccountName = res.officialAccountName || (companyName + ' 官方');
      entRecordEvent('company', '公司定位更新', entState.company.summary, 'company', 'company-official');
    });
  }
  function entSaveCompanyFromInputs(){
    entState.company.name = ((document.getElementById('entCompanyName') || {}).value || entState.company.name).trim() || entState.company.name;
    entState.company.style = ((document.getElementById('entCompanyStyle') || {}).value || entState.company.style).trim() || entState.company.style;
    entState.company.focus = ((document.getElementById('entCompanyFocus') || {}).value || entState.company.focus).trim() || entState.company.focus;
    entSaveState();
    entRenderApp();
    entToast('公司设定已保存');
  }
  function entSavePlayerFromInputs(){
    entState.player.enabled = !!(document.getElementById('entPlayerEnabled') || {}).checked;
    entState.player.mode = ((document.getElementById('entPlayerMode') || {}).value || entState.player.mode);
    entState.player.stageName = ((document.getElementById('entPlayerStageName') || {}).value || entState.player.stageName).trim() || entState.player.stageName;
    entState.player.publicRole = ((document.getElementById('entPlayerPublicRole') || {}).value || entState.player.publicRole).trim() || entState.player.publicRole;
    entState.player.debutStatus = ((document.getElementById('entPlayerDebutStatus') || {}).value || entState.player.debutStatus).trim() || entState.player.debutStatus;
    entState.player.publicPersona = ((document.getElementById('entPlayerPublicPersona') || {}).value || entState.player.publicPersona).trim() || entState.player.publicPersona;
    entState.player.privatePersona = ((document.getElementById('entPlayerPrivatePersona') || {}).value || entState.player.privatePersona).trim() || entState.player.privatePersona;
    entState.player.fanName = ((document.getElementById('entPlayerFanName') || {}).value || entState.player.fanName).trim() || entState.player.fanName;
    entState.player.color = ((document.getElementById('entPlayerColor') || {}).value || entState.player.color).trim() || entState.player.color;
    if (entState.player.enabled) {
      entState.ui.selectedAccount = 'player-self';
      entState.ui.selectedArtist = 'player-self';
      if (!entState.ui.pairA) entState.ui.pairA = 'player-self';
    } else {
      if (String(entState.ui.selectedArtist) === 'player-self') entState.ui.selectedArtist = (entState.roster[0] && entState.roster[0].id) || '';
      if (String(entState.ui.selectedAccount) === 'player-self') entState.ui.selectedAccount = 'company-official';
      if (String(entState.ui.pairA) === 'player-self') entState.ui.pairA = '';
      if (String(entState.ui.pairB) === 'player-self') entState.ui.pairB = '';
    }
    entEnsureSelections();
    entSaveState();
    entRenderApp();
    entToast('用户娱乐圈身份已保存');
  }
