  async function entApplyPrAction(controversyId, action){
    var controversy = (entState.controversies || []).find(function(item){ return String(item.id) === String(controversyId); });
    if (!controversy) return entToast('这条争议已经不存在，先重新生成或刷新公司系统。');
    await entRunBusy('正在执行处理方案', async function(){
      var base = entFallbackPrActionOutcome(controversy, action);
      var prompt = [
        '请输出 JSON，字段为 {"status":"","summary":"","publicShift":"","fanShift":"","mediaShift":"","nextAction":"","followUp":"","heatDelta":0,"riskDelta":0,"reputationDelta":0}。',
        '这是娱乐圈公司系统里的争议处理结果生成。',
        '要直接写执行这个方案之后发生了什么、舆论怎么变、下一步该干什么，不要空话，不要模板感，不要重复前文。',
        '具体度要求：\n' + entIndustrySpecificityGuide('pr'),
        '争议标题：' + controversy.title,
        '事件经过：' + controversy.story,
        '当前热度：' + controversy.heat,
        '粉丝态度：' + controversy.fanAttitude,
        '路人态度：' + controversy.publicAttitude,
        '媒体态度：' + controversy.mediaAttitude,
        '用户选择的处理方案：' + action
      ].join('\n');
      var res = await entAskJson(prompt, base, 1800);
      var result = {
        id: base.id,
        action: action,
        status: res.status || base.status,
        summary: res.summary || base.summary,
        publicShift: res.publicShift || base.publicShift,
        fanShift: res.fanShift || base.fanShift,
        mediaShift: res.mediaShift || base.mediaShift,
        nextAction: res.nextAction || base.nextAction,
        followUp: res.followUp || base.followUp,
        heatDelta: Number(res.heatDelta),
        riskDelta: Number(res.riskDelta),
        reputationDelta: Number(res.reputationDelta),
        ts: entNow()
      };
      if (!isFinite(result.heatDelta)) result.heatDelta = base.heatDelta;
      if (!isFinite(result.riskDelta)) result.riskDelta = base.riskDelta;
      if (!isFinite(result.reputationDelta)) result.reputationDelta = base.reputationDelta;
      controversy.status = result.status;
      controversy.resolution = action;
      controversy.resolutionSummary = result.summary;
      controversy.nextAction = result.nextAction;
      controversy.followUp = result.followUp;
      controversy.latestPublicShift = result.publicShift;
      controversy.latestFanShift = result.fanShift;
      controversy.latestMediaShift = result.mediaShift;
      controversy.lastHandledAt = result.ts;
      controversy.heat = Math.max(1, Number(controversy.heat || 0) + result.heatDelta);
      controversy.actionHistory = Array.isArray(controversy.actionHistory) ? controversy.actionHistory : [];
      controversy.actionHistory.unshift(result);
      controversy.actionHistory = controversy.actionHistory.slice(0, 12);
      entAdjustTalentStats(controversy.targetId, {
        risk: result.riskDelta,
        reputation: result.reputationDelta,
        heat: result.heatDelta
      });
      if (action === '公司声明' && !(entState.statements || []).some(function(item){ return String(item.controversyId) === String(controversy.id); })) {
        entState.statements.unshift(entFallbackStatement(controversy));
        entState.statements = entState.statements.slice(0, 80);
      }
      entRecordEvent('pr', '争议处理已执行', controversy.title + ' · 方案：' + action + ' · ' + result.summary, 'controversy', controversy.id);
      entState.ui.detailType = 'controversy';
      entState.ui.detailId = controversy.id;
      entSaveState();
      entRenderApp();
      entToast('已执行方案：' + action + '，处理后续已生成');
    });
  }
