  function entUpsertRelationship(rel){
    var idx = entState.relationships.findIndex(function(item){
      return (String(item.aId) === String(rel.aId) && String(item.bId) === String(rel.bId)) ||
             (String(item.aId) === String(rel.bId) && String(item.bId) === String(rel.aId));
    });
    if (idx >= 0) entState.relationships[idx] = Object.assign({}, entState.relationships[idx], rel);
    else entState.relationships.unshift(rel);
    entState.relationships = entState.relationships.slice(0, 80);
  }
