        var account帖子 = (entState.帖子s || []).filter(function(帖子){ return String(帖子.authorId) === String(selected.id); });
        body += account帖子.length ? account帖子.map(entWeiboPostHtml).join('') : '<div class="ent-empty" style="margin:16px;">这个账号还没有发过微博。</div>';
