(function(){
  if (window.__mtSubstituteClickFallbackLoaded) return;
  window.__mtSubstituteClickFallbackLoaded = true;
  function isSubstituteButton(el){
    if(!el) return false;
    var btn = el.closest && el.closest('.plus-panel-btn,button,[role="button"],.plus-item,.plus-btn');
    var target = btn || el;
    var txt = (target.textContent || '').replace(/\s+/g,'').trim();
    return txt === '替身局' || txt === '替身';
  }
  document.addEventListener('click', function(e){
    if(!isSubstituteButton(e.target)) return;
    if(e.__mtSubHandled) return;
    e.__mtSubHandled = true;
    e.preventDefault();
    e.stopPropagation();
    if(e.stopImmediatePropagation) e.stopImmediatePropagation();
    try { if (typeof window.closePlusPanel === 'function') window.closePlusPanel(); } catch(_e){}
    setTimeout(function(){
      if (typeof window.mtOpenGameModal === 'function') {
        window.mtOpenGameModal();
      } else {
        console.error('[替身局] mtOpenGameModal 未注册，可能是脚本加载失败。');
        alert('替身局脚本还没加载完成，请刷新页面或重新打开加号菜单。');
      }
    }, 30);
  }, true);
})();


