(function(){
  function mtBindSubstituteFallback(){
    try{
      document.querySelectorAll('button,.plus-item,.chat-plus-item,.app-btn,[data-action]').forEach(function(el){
        var txt=(el.textContent||'').trim();
        if(txt==='替身局' || txt==='替身'){
          if(el.dataset.mtSubClickBound==='1') return;
          el.dataset.mtSubClickBound='1';
          el.addEventListener('click', function(ev){
            if(ev.__mtSubHandled) return;
            ev.__mtSubHandled = true;
            try{
              if (typeof window.mtOpenGameModal === 'function'){
                ev.preventDefault(); ev.stopPropagation(); if(ev.stopImmediatePropagation) ev.stopImmediatePropagation();
                window.mtOpenGameModal();
              }
            }catch(e){ console.warn('替身局打开失败', e); }
          }, true);
        }
      });
    }catch(e){}
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', mtBindSubstituteFallback);
  else mtBindSubstituteFallback();
  setTimeout(mtBindSubstituteFallback, 800);
})();


