    + '<input id="locationShareLabelInput" class="location-share-input" placeholder="地址便签（可选），例如：家 / 学校 / 公司 / 常去咖啡厅">'
    + '<div class="location-share-label-row"><button type="button" class="location-share-label-chip" onclick="monoSetLocationShareLabel(&quot;家&quot;)">家</button><button type="button" class="location-share-label-chip" onclick="monoSetLocationShareLabel(&quot;学校&quot;)">学校</button><button type="button" class="location-share-label-chip" onclick="monoSetLocationShareLabel(&quot;公司&quot;)">公司</button><button type="button" class="location-share-label-chip" onclick="monoSetLocationShareLabel(&quot;常去地点&quot;)">常去地点</button></div>'
    + '<input id="locationShareNoteInput" class="location-share-input" placeholder="备注（可选），例如：我在这里等你">'
    + '<input id="locationShareLatInput" type="hidden"><input id="locationShareLngInput" type="hidden"><input id="locationShareAccuracyInput" type="hidden"><input id="locationShareMapUrlInput" type="hidden">'
    + '<div style="margin:2px 0 12px;">' + renderLocationCardInner({title:'定位预览', address:'地图预览会显示在这里'}) + '</div>'
    + '<button class="location-share-send" onclick="confirmSendLocationShare()">发送定位卡片</button>'
