function confirmSendLocationShare() {
  if (!currentId) return;
  var p = personas.find(function(x){ return x.id == currentId; });
  if (!p) return;
  if (!Array.isArray(p.history)) {
    try { p.history = JSON.parse(localStorage.getItem('mono_hist_' + p.id) || '[]') || []; } catch(e) { p.history = []; }
  }
  var title = (document.getElementById('locationShareTitleInput') || {}).value || '';
  var address = (document.getElementById('locationShareAddressInput') || {}).value || '';
  var addressLabel = (document.getElementById('locationShareLabelInput') || {}).value || '';
  var note = (document.getElementById('locationShareNoteInput') || {}).value || '';
  var lat = (document.getElementById('locationShareLatInput') || {}).value || '';
  var lng = (document.getElementById('locationShareLngInput') || {}).value || '';
  var accuracy = (document.getElementById('locationShareAccuracyInput') || {}).value || '';
  var mapUrl = (document.getElementById('locationShareMapUrlInput') || {}).value || '';
  title = String(title).trim(); address = String(address).trim(); addressLabel = String(addressLabel).trim().slice(0, 16); note = String(note).trim();
  if (!address && !title && !(lat && lng)) { alert('请至少填写地点名称或地址，或点击获取当前真实位置'); return; }
  var resolvedUserIdentity = (typeof monoResolveUserIdentityProfile === 'function') ? monoResolveUserIdentityProfile(p) : (userProfile || {});
  var modalForLandmark = document.getElementById('locationShareModal');
  var landmarkName = modalForLandmark ? (modalForLandmark.getAttribute('data-landmark-name') || '') : '';
  var landmarkType = modalForLandmark ? (modalForLandmark.getAttribute('data-landmark-type') || '') : '';
  var loc = _normalizeLocationData({ title: title || address || landmarkName || '我的当前位置', address: address || title || landmarkName, addressLabel: addressLabel, note: note, lat: lat, lng: lng, accuracy: accuracy, mapUrl: mapUrl, landmarkName: landmarkName || title, landmarkType: landmarkType, source: (lat && lng) ? 'device_geolocation_landmark' : 'manual', locatedAt: Date.now(), senderName: (resolvedUserIdentity && (resolvedUserIdentity.name || resolvedUserIdentity.displayName)) || (userProfile && userProfile.name) || '你' }, 'user');
  var msg = { role:'user', msgType:'location_card', locationData: loc, content: _buildLocationHistoryText(loc, 'user'), timestamp: Date.now(), userMaskId: (resolvedUserIdentity && resolvedUserIdentity.maskId) || '' };
  if (typeof currentQuoteMsg !== 'undefined' && currentQuoteMsg) msg.quote = (typeof monoBuildQuotePayload === 'function') ? monoBuildQuotePayload(currentQuoteMsg) : { role: currentQuoteMsg.role, content: currentQuoteMsg.content, displayContent: currentQuoteMsg.displayContent || currentQuoteMsg.content, msgType: currentQuoteMsg.msgType || '', senderName: currentQuoteMsg.senderName || '' };
  p.history.push(msg);
  p._lastUserChatTs = msg.timestamp;
  p.lastUserMessageTime = msg.timestamp;
  try { if (typeof cancelQuote === 'function') cancelQuote(); } catch(e) {}
  closeLocationShareModal();
  try { saveData(); } catch(e) {}
  try { renderMessages(); } catch(e) {}
  try { renderContactList(); } catch(e) {}
  try { var chatBox = document.getElementById('chatBox'); if (chatBox) chatBox.scrollTop = chatBox.scrollHeight; } catch(e) {}
  try { if (typeof taskTrackChatMessage === 'function') taskTrackChatMessage(currentId, msg.timestamp); } catch(e) {}
  var _tdOutcome = { skipDefaultAuto回复: false };
  if (typeof tdHandleUserMessageInActiveGame === 'function') {
    Promise.resolve(tdHandleUserMessageInActiveGame(p, msg)).then(function(out){
      if (!(out && out.skipDefaultAuto回复) && typeof _handleAuto回复AfterSend === 'function') _handleAuto回复AfterSend(currentId);
    }).catch(function(){ if (typeof _handleAuto回复AfterSend === 'function') _handleAuto回复AfterSend(currentId); });
  } else if (typeof _handleAuto回复AfterSend === 'function') {
    _handleAuto回复AfterSend(currentId);
  }
}

(function patchLocationOneShotCards(){
  var _oldBuild = typeof monoBuildOneShotRichMessagePrompt === 'function' ? monoBuildOneShotRichMessagePrompt : null;
  monoBuildOneShotRichMessagePrompt = function(p) {
    var base = _oldBuild ? _oldBuild(p) : '';
    if (!base) return base;
    if (base.indexOf('[card:location') !== -1) return base;
    return base.replace('5. 聊天截图： [card:screenshot|title=聊天对象或群名|caption=可选配文|messages=左边人:内容;'+(p && p.name ? p.name : '我')+':内容;左边人:内容]',
      '5. 聊天截图： [card:screenshot|title=聊天对象或群名|caption=可选配文|messages=左边人:内容;'+(p && p.name ? p.name : '我')+':内容;左边人:内容]\n6. 定位分享卡： [card:location|title=地点名称/地标名|address=完整地址/可读位置|label=地址便签可选例如家/学校/公司|note=可选备注]')
      + '\n【定位分享卡规则】\n- 定位分享卡是微信式地址卡片，前端会渲染为真实定位卡，不要写成“（定位消息）”文字。\n- 用户发送定位分享、角色发送定位分享，必须使用同一个前端定位卡片组件渲染；卡片大小、圆角、阴影、标题区、地址区、地图预览、绿色定位图标、底部“位置”栏完全一致，只根据消息发送方显示在左侧或右侧。\n- 角色不能把定位卡写成普通文字，不能写“我发送了一个定位卡/定位消息：xxx”；必须只输出 [card:location|title=地点名称|address=完整地址|label=地址便签|note=备注]，由前端转成真正的定位分享卡片。\n- 不要频繁主动发定位；普通聊天只允许极低概率主动触发，概率约 2%，并且必须符合角色人设、关系亲密度、当前剧情和最近对话，不能无理由发送。\n- 允许的定位玩法包括：位置报备卡、约见地点卡、行程预告卡、记忆地点卡、报平安卡、NPC/多角色联动地点卡。\n- 只有当用户问你在哪里、让你报备当前位置、问之后的地址/行程/约见地点，或对话明确围绕地点、路线、见面位置时，才高概率考虑发送；用户之前要求“到了告诉我/到家发我定位”时，可以按报平安逻辑发送。\n- 主动发送仍然必须低频：普通聊天约 2%；聊到地点但用户没问约 5%；角色到达重要地点约 10%；用户之前要求报备约 40%；用户直接问位置/行程/地址约 70%–90%，并根据角色性格自动上下调整。\n- 是否发送仍要符合你的人设：谨慎、冷淡或注重隐私的角色可以少发或先用文字回应；愿意报备/亲密/正在约见的角色可以直接发。\n- address 必须是一个可读的具体地点、店铺、地标或地址；title 是卡片上方显示的地点名。不要输出经纬度当地址。\n- label 是可选地址便签，例如“家”“学校”“公司”“宿舍”“常去咖啡厅”。只有对话里自然需要说明这个地点身份时才填；不要每张卡都强行写。\n';
  };
  var _oldExtract = typeof monoExtractOneShotRichMessages === 'function' ? monoExtractOneShotRichMessages : null;
  monoExtractOneShotRichMessages = function(rawContent) {
    var out = { text: String(rawContent || ''), cards: [] };
    try {
      var lines = out.text.split(/\n/);
      var kept = [];
      lines.forEach(function(line){
        var m = String(line || '').trim().match(/^\[card\s*:\s*([a-zA-Z_\-\u4e00-\u9fa5]+)\s*\|([\s\S]*?)\]\s*$/);
        if (!m) { kept.push(line); return; }
        var typeRaw = String(m[1] || '').trim().toLowerCase();
        var kv = (typeof monoParseKvTagBody === 'function') ? monoParseKvTagBody(m[2] || '') : {};
        var type = typeRaw;
        if (/转|transfer/.test(typeRaw)) type = 'transfer';
        else if (/intimate|亲密|亲密/.test(typeRaw)) type = 'intimate';
        else if (/takeout|外卖|外卖/.test(typeRaw)) type = 'takeout';
        else if (/text.*image|文字图|文字图/.test(typeRaw)) type = 'text_image';
        else if (/screen|截图|截图/.test(typeRaw)) type = 'screenshot';
        else if (/location|map|定位|地址|位置/.test(typeRaw)) type = 'location';
        if (out.cards.length < 2) out.cards.push({ type:type, data:kv });
      });
      out.text = kept.join('\n').trim();
    } catch(e) { return _oldExtract ? _oldExtract(rawContent) : out; }
    return out;
  };
  var _oldClean = typeof monoCleanFakeRichMessageText === 'function' ? monoCleanFakeRichMessageText : null;
  monoCleanFakeRichMessageText = function(s) {
    var t = _oldClean ? _oldClean(s) : String(s || '');
    return String(t || '')
      .replace(/[（(]\s*(?:定位消息|定位分享|位置消息|地址卡片|地图卡片)\s*[）)]/g, '')
      .replace(/\[\s*(?:定位消息|定位分享|位置消息|地址卡片|地图卡片)\s*\]/g, '')
      .trim();
  };
  var _oldPush = typeof monoPushOneShotRichCards === 'function' ? monoPushOneShotRichCards : null;
  monoPushOneShotRichCards = function(p, cards, personaName, userName) {
    if (!p || !Array.isArray(cards) || !cards.length) return false;
    var pushed = false;
    var rest = [];
    cards.forEach(function(card){
      var type = String(card && card.type || '').toLowerCase();
      if (/location|map|定位|地址|位置/.test(type)) {
        var d = (card && card.data) || {};
        var loc = _normalizeLocationData({ title:d.title || d.name || d.place, address:d.address || d.addr || d.location || d.place || d.title, addressLabel:d.label || d.tag || d.addressLabel || d.addressTag, note:d.note || d.desc, lat:d.lat || d.latitude, lng:d.lng || d.longitude, accuracy:d.accuracy, mapUrl:d.mapUrl || d.url, senderName: personaName || '角色' }, 'assistant', personaName || '角色');
        if (!loc.address && !loc.title) return;
        p.history.push({ role:'assistant', msgType:'location_card', locationData:loc, content:_buildLocationHistoryText(loc, 'assistant'), timestamp:Date.now() });
        pushed = true;
      } else {
        rest.push(card);
      }
    });
    if (_oldPush && rest.length) pushed = _oldPush(p, rest, personaName, userName) || pushed;
    return pushed;
  };
})();



