  window.confirmSendSocialShare=function(){var pid=selectedSharePersonaId||val('socialSharePersona')||getCurrentId(); if(!pid){alert('请先选择角色');return;} var p=getPersonaById(pid); if(!p){alert('找不到这个角色，请重新选择');return;} if(!Array.isArray(p.history))p.history=[]; var data=getFormData(); if(!data.url&&!data.title&&!data.desc&&!data.cover){alert('请先读取/粘贴一个分享链接、文字内容或图片');return;} data.sourceLabel='用户从社交平台分享给角色'; data.senderIntent='user_shared_social_platform_content_to_character'; try{if(data.url)localStorage.setItem('monoSocialLastProcessedClipboardLink',simpleHash(data.rawText||data.url));}catch(_){ } var msg={role:'user',msgType:'social_share_card',socialShareData:data,content:window.monoBuildSocialShareHistoryText(data),timestamp:Date.now(),shareSource:'user_social_platform_forward',displayHint:'你从社交平台转发给角色的内容'}; p.history.push(msg); try{p._lastUserChatTs=msg.timestamp;p.lastUserMessageTime=msg.timestamp;}catch(e){} try{saveData();}catch(e){try{localStorage.setItem('mono_personas',JSON.stringify(getPersonas()));}catch(_){}} closeSocialShareModal(); try{setCurrentPersona(pid);}catch(e){} setTimeout(function(){try{renderContactList();}catch(e){} try{renderMessages(); var box=document.getElementById('chatBox'); if(box)box.scrollTop=box.scrollHeight;}catch(e){} try{if(typeof _handleAuto回复AfterSend==='function')_handleAuto回复AfterSend(pid);}catch(e){}},80);};
  function parseLaunchShare(){try{var u=new URL(location.href); var sp=u.searchParams; if(!sp.has('monoShareTarget')&&!sp.has('url')&&!sp.has('text')&&!sp.has('title'))return null; var data=normalizeShareData({url:sp.get('url')||'',title:sp.get('title')||'',text:sp.get('text')||''}); history.replaceState({},document.title,location.pathname+location.hash); return data;}catch(e){return null;}}
