  const DEFAULT_ICON="<svg viewBox='0 0 52 52' fill='none' xmlns='http://www.w3.org/2000/svg' style='width:40px;height:40px;'><rect x='8' y='12' width='36' height='28' rx='9' fill='#555'/><path d='M23 20.5L34 26L23 31.5V20.5Z' fill='#f2f2f2'/></svg>";
  let state=null; let ui={screen:'home',chip:'全部',query:'',draft:'',results:[],current:'',last:'home',loading:false}; let player={timer:null,playing:false,time:0};
  function esc(s){return String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]||c));}
  function toast(m){try{ if(typeof showToast==='function')showToast(m); else if(typeof toastSoft==='function')toastSoft(m); else alert(m);}catch(e){alert(m)}}
  function uid(){return 'yt_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7)}
  function count(n){n=Number(n||0); if(n>=1e8)return(n/1e8).toFixed(1).replace(/\.0$/,'')+'亿'; if(n>=1e4)return(n/1e4).toFixed(1).replace(/\.0$/,'')+'万'; return String(Math.max(0,Math.round(n)));}
