  async function gen(opts={}){ui.loading=true;ui.error='';render();try{const need=Number(opts.count||3);const oldTitles=Array.isArray(opts.avoidTitles)?opts.avoidTitles:[];let raw=await ask(buildPrompt(Object.assign({},opts,{count:need,avoidTitles:oldTitles,diversitySeed:Date.now()})),opts.mode==='search'?5200:5400);let result,vs=[];try{result=videosFromRaw(raw);vs=result.videos;}catch(firstErr){console.warn('[YouTube] first JSON parse failed, retry compact', firstErr);raw=await ask(buildPrompt(Object.assign({},opts,{count:need,avoidTitles:oldTitles,diversitySeed:Date.now()+':compact',compactRetry:true})),opts.mode==='search'?4800:5000);result=videosFromRaw(raw);vs=result.videos;}if(vs.length>0 && vs.length<need){console.warn('[YouTube] partial videos parsed; showing generated videos only',vs.length,need);return vs.slice(0,need);}if(vs.length!==need){console.warn('[YouTube] videos count not exact, retry once',vs.length,need);raw=await ask(buildPrompt(Object.assign({},opts,{count:need,retry:true,avoidTitles:oldTitles,diversitySeed:Date.now()+':retry',compactRetry:true}))+'\n\n上一次返回的视频数量不是 '+need+' 条。请严格返回刚好 '+need+' 条 videos，并保证 JSON 完整闭合。',opts.mode==='search'?4600:4800);result=videosFromRaw(raw);vs=result.videos;}if(vs.length>0)return vs.slice(0,need);throw new Error('API 没有返回任何完整视频对象。');}catch(e){console.error('[YouTube generate failed]',e);ui.error='生成失败：'+(e&&e.message?e.message:'未知错误');try{if(typeof _showApiErrorToast==='function')_showApiErrorToast('YouTube 生成失败',e)}catch(_){}return []}finally{ui.loading=false}}
