// ===== mono-mt-reopen-second-click-fix =====

(function(){
  if (window.__monoMtReopenSecondClickFix) return;
  window.__monoMtReopenSecondClickFix = true;

  function mtFixModalState(){
    try { window.__mtOpenGameModalBusy = false; } catch(e) {}
    var modal = document.getElementById('matchTestModal');
    if (modal) {
      modal.classList.remove('closing','closed','hidden','hide');
      modal.style.pointerEvents = '';
      modal.style.visibility = '';
      modal.style.opacity = '';
    }
  }

  function mtActuallyVisible(){
    var modal = document.getElementById('matchTestModal');
    if (!modal) return false;
    var cs = window.getComputedStyle ? getComputedStyle(modal) : null;
    return modal.style.display === 'flex' || (cs && cs.display !== 'none' && modal.getAttribute('aria-hidden') !== 'true');
  }

  function mtForceOpenShell(){
    var modal = document.getElementById('matchTestModal');
    if (!modal) return;
    modal.style.display = 'flex';
    modal.setAttribute('aria-hidden','false');
    modal.style.pointerEvents = '';
    modal.style.visibility = '';
    modal.style.opacity = '';
    try { modal.scrollTop = 0; } catch(e) {}
  }

  function mtForceCloseShell(){
    var modal = document.getElementById('matchTestModal');
    if (!modal) return;
    modal.style.display = 'none';
    modal.setAttribute('aria-hidden','true');
    modal.style.pointerEvents = '';
  }

  var rawOpen = window.mtOpenGameModal;
  if (typeof rawOpen === 'function' && !rawOpen.__monoReopenWrapped) {
    var wrappedOpen = async function(){
      mtFixModalState();
      var ret;
      try {
        ret = rawOpen.apply(this, arguments);
        if (ret && typeof ret.then === 'function') await ret;
      } finally {
        window.__mtOpenGameModalBusy = false;
        // 如果旧逻辑已成功初始化但被关闭残留状态挡住，这里只恢复外壳显示；不会改替身局内容逻辑。
        setTimeout(function(){
          var modal = document.getElementById('matchTestModal');
          if (modal && modal.getAttribute('aria-hidden') === 'false' && !mtActuallyVisible()) mtForceOpenShell();
        }, 0);
      }
    };
    wrappedOpen.__monoReopenWrapped = true;
    window.mtOpenGameModal = wrappedOpen;
  }

  var rawClose = window.mtCloseGameModal;
  if (typeof rawClose === 'function' && !rawClose.__monoReopenWrapped) {
    var wrappedClose = function(){
      try {
        return rawClose.apply(this, arguments);
      } finally {
        window.__mtOpenGameModalBusy = false;
        mtForceCloseShell();
      }
    };
    wrappedClose.__monoReopenWrapped = true;
    window.mtCloseGameModal = wrappedClose;
  }

  // 有些移动端点击关闭后，下一次加号菜单打开时会残留旧遮罩状态；重新点替身局时先释放 busy，再走原功能。
  document.addEventListener('pointerdown', function(e){
    var el = e.target && e.target.closest ? e.target.closest('.plus-panel-btn,button,[role="button"],.plus-item,.plus-btn') : null;
    if (!el) return;
    var txt = (el.textContent || '').replace(/\s+/g,'').trim();
    if (txt === '替身局' || txt === '替身') mtFixModalState();
  }, true);
})();


