    let igStore={};
    try{ igStore = (typeof igStories!=='undefined' ? igStories : null) || window.igStories || JSON.parse(localStorage.getItem('mono_ig_stories')||'{}') || {}; }catch(e){ igStore={}; }
    const stories=[{id:'me',name:userName,avatar:userAvatar,isUser:true,hasStories:false,storyLines:[]}];
