      const persona=item.personaId?findPersonaById(item.personaId):findPersonaByName(item.user||'');
      if(!persona || typeof window.monoInstagramNeedsTranslation!=='function' || !window.monoInstagramNeedsTranslation(persona)) continue;
      if(typeof _monoShouldTranslateTextForPersona==='function' && !_monoShouldTranslateTextForPersona(String(item.text||''), persona, (typeof _detectPersonaLang==='function' ? _detectPersonaLang(persona) : ''))) continue;
      if(typeof window.monoInstagramTranslateText!=='function') break;
      try{ item.translation=await window.monoInstagramTranslateText(item.text||'',persona); }catch(e){ item.translation=''; }
