  async function submitCompose(){const cap=(document.getElementById('insComposeCaption')||{}).value||''; const visual=(document.getElementById('insComposeVisual')||{}).value||''; let type=(document.getElementById('insComposeType')||{}).value||'photo'; if(ui.busyImages)return toast('图片还在识图中，请稍等一下'); if(!String(cap).trim()&&!String(visual).trim()&&!insPendingImages.length)return toast('请至少写文案、画面描述或上传图片'); if(insPendingImages.length>1 && type!=='carousel') type='carousel'; const imageSummary=composeImageSummary(); const publicVisual=(visual||(!insPendingImages.length?(cap||''):'')).trim(); const visualPages=type==='carousel'?(splitPieces(visual||'').length?splitPieces(visual):(!insPendingImages.length?splitPieces(cap):[])).slice(0,2):[]; const 帖子=normPost({id:uid(),username:getCurrentUserName()||'You',avatar:getCurrentUserAvatar()||'',personaId:'user',type:type,location:(document.getElementById('insComposeLocation')||{}).value||'',music:(document.getElementById('insComposeMusic')||{}).value||'',caption:cap||'',visualHint:publicVisual||'',visualPages:visualPages,images:insPendingImages.slice(0,2),imageDescs:insPendingImageDescs.slice(0,2),aiVisualContext:imageSummary,likes:0,comments:0,shares:0,time:'',createdAt:Date.now(),isUser:true}); if(Array.isArray(帖子.images)&&帖子.images.length&&typeof window.monoPersistIgGeneratedPostImages==='function'){try{await window.monoPersistIgGeneratedPostImages(帖子);}catch(e){}} state.user帖子.unshift(帖子); save(); close评论(); ui.screen='home'; render(); toast('已发布到 Instagram'); const result=await generate评论(帖子,true); if(result.comments&&result.comments.length){state.comments[帖子.id]=result.comments; 帖子.comments=result.comments.length;} if(result.activities&&result.activities.length){updatePostLikeActors(帖子,result.activities); state.activities=mergedActivities(result.activities);} save(); render();}
