  function doSend(id,pid){const 帖子=findPost(id); let role=null; try{role=getPersonas().find(x=>String(x.id)===String(pid));}catch(e){} if(!帖子||!role)return toast('没有找到角色'); if(!Array.isArray(role.history))role.history=[]; const pages=buildMediaPages(帖子); const images=Array.isArray(帖子.images)?帖子.images.slice(0,2):[]; const imageDescs=Array.isArray(帖子.imageDescs)?帖子.imageDescs.slice(0,2):[]; const pageTranslations=Array.isArray(帖子.mediaTranslationPages)?帖子.mediaTranslationPages.slice(0,2):[]; const pageBundle=Array.from({length:Math.max(pages.length,images.length,imageDescs.length,1)}).map(function(_,idx){return {text:String(pages[idx]||pages[0]||'').trim(),translation:String(pageTranslations[idx]||'').trim(),image:String(images[idx]||'').trim(),imageDesc:String(imageDescs[idx]||'').trim()};}).slice(0,2); const imageInfo=imageDescs.filter(Boolean).join(' / '); const data={platform:'Instagram',type:帖子.type==='Reel'?'Reel':'Post',url:'https://instagram.com/p/'+帖子.id,title:帖子.username+' 的 '+(帖子.type==='Reel'?'Reel':'Post'),author:帖子.username,desc:'Instagram 内容：'+(帖子.caption||'（无文案）')+'\n视觉线索：'+(帖子.visualHint||'')+(imageInfo?('\n图片内容：'+imageInfo):'')+'\n音乐：'+(帖子.music||''),cover:(images[0]||''),hideDetailPreview:true,note:'用户从 Instagram 软件转发给角色。请像已经看过帖子/Reel 一样回应。',instagramPost:{id:String(帖子.id||''),type:帖子.type==='Reel'?'Reel':'Post',username:帖子.username||'',avatar:帖子.avatar||'',music:帖子.music||'',musicTranslation:帖子.musicTranslation||'',location:帖子.location||'',caption:帖子.caption||'',captionTranslation:帖子.captionTranslation||'',createdAt:Number(帖子.createdAt||Date.now()),images:images,pages:pageBundle,pageCount:pageBundle.length}}; role.history.push({role:'user',msgType:'social_share_card',socialShareData:data,content:typeof monoBuildSocialShareHistoryText==='function'?monoBuildSocialShareHistoryText(data):('[用户从 Instagram 转发]\n'+data.title),timestamp:Date.now(),shareSource:'instagram_app_forward',displayHint:'你从 Instagram 软件转发给角色的内容'}); try{if(typeof saveData==='function')saveData();}catch(e){} document.getElementById('insMenu').className='ins-menu'; toast('已转发给角色');}
  async function openStory(id){
    if(id==='me') return openCompose();
    const p=getPersonas().find(x=>String(x.id)===String(id));
    if(!p) return toast('没有找到这个角色');
    close评论();
    await hydrateExistingStoryTranslations(p);
    try{
      const viewer=document.getElementById('igStoryViewer');
      if(viewer){
        viewer.style.zIndex='99999';
        viewer.style.position='absolute';
      }
    }catch(e){}
    try{
      if(typeof openIgStory==='function'){
        openIgStory(id);
        setTimeout(function(){
          try{
            const viewer=document.getElementById('igStoryViewer');
            if(viewer){
              viewer.style.zIndex='99999';
              viewer.style.position='absolute';
              viewer.classList.add('open');
            }
          }catch(e){}
        },30);
        return;
      }
    }catch(e){
      console.warn('[INS story] openIgStory failed', e);
    }
    try{
      if(typeof generateIgStoryForPersona==='function'){
        const result=await generateIgStoryForPersona(p);
        if(result && result.length){
          try{
            if(typeof igStories==='undefined') window.igStories={};
            (typeof igStories!=='undefined'?igStories:window.igStories)[p.id]=result.map(s=>typeof s==='object'?{text:s.text,translation:s.translation||'',time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}:{text:String(s),time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})});
            localStorage.setItem('mono_ig_stories', JSON.stringify(typeof igStories!=='undefined'?igStories:window.igStories));
          }catch(_){}
          if(typeof openIgStory==='function') openIgStory(id);
          return;
        }
      }
    }catch(e){ console.warn('[INS story] generate fallback failed', e); }
    toast('Instagram 桌件快拍功能还没准备好');
  }
  function placeIcon(){const el=document.getElementById('app-instagram'); if(!el)return; try{el.dataset.dragId='app-instagram'; let saved=JSON.parse(localStorage.getItem('mono_iph_positions_v3')||'{}'); let yt=saved['app-youtube']||{x:16,y:208,parentId:'homePage3'}; let dec=saved['app-decrypt']; let ent=saved['app-entertainment']; let gap=84; if(dec&&ent&&dec.parentId===ent.parentId&&Number.isFinite(Number(dec.x))&&Number.isFinite(Number(ent.x))){gap=Math.max(60,Math.round(Number(ent.x)-Number(dec.x)))||84;} let def={x:(Number(yt.x)||16)+gap,y:(Number(yt.y)||180),parentId:yt.parentId||'homePage3'}; let pos=saved['app-instagram']; let wrong=!pos||(String(pos.parentId||'homePage3')==='homePage3'&&Number(pos.x)===180&&Number(pos.y)===180); if(wrong){pos=def; saved['app-instagram']=pos; localStorage.setItem('mono_iph_positions_v3',JSON.stringify(saved));} const parent=document.getElementById(pos.parentId||def.parentId); if(parent&&el.parentElement!==parent)parent.appendChild(el); el.classList.add('iph-placed'); el.style.left=(typeof pos.x==='number'?pos.x:def.x)+'px'; el.style.top=(typeof pos.y==='number'?pos.y:def.y)+'px'; el.style.margin='0'; el.style.flexShrink='0';}catch(e){}}
  async function openApp(){clearHomeEditMode(); try{await syncInstagramStateFromIdbIfNeeded();}catch(e){} try{await ensureInstagramPersonasLoaded();}catch(e){} load(); try{await ensureInstagramPersonasLoaded();}catch(e){} syncThreads(); ui.screen='home'; const page=document.getElementById('instagramPage'); if(!page)return; page.style.display='flex'; page.classList.add('active'); page.style.flexDirection='column'; if(typeof _showAppPage==='function'){try{_showAppPage('instagramPage');}catch(e){}} clearHomeEditMode(); render(); if(!state.feed.length && getPersonas().length)await generateFeed(); else {render(); hydrateMissingFeedTranslations(6); hydrateVisibleStoredInstagramImages(4); try{if(typeof window.monoMigrateInstagramPostImageStorage==='function') await window.monoMigrateInstagramPostImageStorage(120);}catch(e){}} try{if(typeof window.monoSetInstagramPostImageDisplayMode==='function') await window.monoSetInstagramPostImageDisplayMode('full');}catch(e){} try{if(typeof updateFabVisibility==='function')updateFabVisibility();}catch(e){}}
