      document.body.classList.remove('home-edit-active','editing-home','iph-editing','dragging','is-dragging','edit-mode');
      document.documentElement.classList.remove('home-edit-active','editing-home','iph-editing','dragging','is-dragging','edit-mode');
      window.isHomeEditing=false; window.homeEditMode=false; window.iphEditMode=false; window.isDraggingHomeIcon=false;
