// ===== mono-instagram-current-chat-api-fix =====

(function(){
  if(window.__monoInstagramCurrentChatApiFix) return;
  window.__monoInstagramCurrentChatApiFix = true;
  function normalizeCfg(c){
    c = c || {};
    var out = {
      url: String(c.url || c.baseURL || c.baseUrl || c.apiUrl || c.endpoint || '').trim(),
      key: String(c.key || c.apiKey || c.token || '').trim(),
      model: String(c.model || c.modelName || '').trim()
    };
    try { if (typeof _normalizeApiConfigObject === 'function') out = _normalizeApiConfigObject(out); } catch(e) {}
    return out;
  }
  function readJSON(k){ try { return JSON.parse(localStorage.getItem(k) || 'null'); } catch(e) { return null; } }
  function getCurrentChatApi(){
    var candidates = [];
    // 只读取聊天软件当前正在使用的 API：优先 active/effective，其次 chat feature；不再单独读取 instagram feature 或默认 preset 主 API。
    try { if (typeof _getCurrentActiveApiConfig === 'function') candidates.push(_getCurrentActiveApiConfig()); } catch(e) {}
    try {
      var activeId = localStorage.getItem('mono_active_api') || 'preset';
      if (activeId && activeId !== 'preset') {
        var apis = readJSON('mono_secondary_apis') || [];
        var hit = Array.isArray(apis) ? apis.find(function(x){ return x && String(x.id) === String(activeId); }) : null;
        if (hit) candidates.push(hit);
      }
    } catch(e) {}
    try { var eff = readJSON('mono_effective_api'); if(eff) candidates.push(eff); } catch(e) {}
    try { if (typeof monoGetApiForFeature === 'function') candidates.push(monoGetApiForFeature('chat')); } catch(e) {}
    try { if (typeof apiConfig !== 'undefined') candidates.push(apiConfig); } catch(e) {}
    try { if (window.apiConfig) candidates.push(window.apiConfig); } catch(e) {}
    ['mono_current_api','chat_api_config','mono_api_config','apiConfig','mono_api'].forEach(function(k){ var v=readJSON(k); if(v) candidates.push(v); });
    for (var i=0;i<candidates.length;i++) {
      var c = normalizeCfg(candidates[i]);
      if (c.url && c.key) {
        if (!c.model) {
          try { if (typeof apiConfig !== 'undefined' && apiConfig && apiConfig.model) c.model = apiConfig.model; } catch(e) {}
          try { if (typeof getSelectedModel === 'function') c.model = getSelectedModel() || c.model; } catch(e) {}
        }
        try { window.apiConfig = Object.assign({}, c); } catch(e) {}
        return c;
      }
    }
    return null;
  }
  async function chatComplete(messages, opts){
    var cfg = getCurrentChatApi();
    if (!cfg || !cfg.url || !cfg.key) throw new Error('没有读取到聊天软件当前 API 连接，请先确认聊天室本身可以正常回复。');
    var payload = { messages: messages, temperature: (opts && opts.temperature) || 0.85, max_tokens: (opts && opts.max_tokens) || 500, stream: false };
    try { if (typeof _applyApiModel === 'function') Object.assign(payload, _applyApiModel(payload, cfg.model || cfg)); else if (cfg.model) payload.model = cfg.model; } catch(e) { if (cfg.model) payload.model = cfg.model; }
    if (typeof _compatibleChatCompletion !== 'function') throw new Error('聊天软件 API 兼容层不可用');
    var resp = await _compatibleChatCompletion(cfg.url, cfg.key, payload, {});
    var raw = '';
    var ok = true;
    var status = '';
    if (typeof resp === 'string') {
      raw = resp;
    } else if (resp && typeof resp.text === 'function') {
      ok = resp.ok !== false;
      status = resp.status || '';
      raw = await resp.text();
    } else if (resp && typeof resp === 'object') {
      raw = JSON.stringify(resp);
    }
    if (/^\s*</.test(raw)) throw new Error('API 返回了 HTML，不是模型内容，请检查聊天软件当前 API Base URL。');
    var data = null; try { data = JSON.parse(raw); } catch(e) { data = { raw: raw }; }
    if (!ok) throw new Error('API 请求失败：' + status + ' ' + String((data && data.error && (data.error.message || data.error)) || raw).slice(0,220));
    var txt = '';
    try { txt = data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content || ''; } catch(e) {}
    if (!txt) { try { txt = data.candidates[0].content.parts.map(function(p){return p.text||''}).join(''); } catch(e) {} }
    if (!txt && typeof data.content === 'string') txt = data.content;
    if (!txt && typeof data.raw === 'string') txt = data.raw;
    return String(txt || '').trim();
  }
  function splitStories(raw){
    raw = String(raw || '').trim().replace(/^```(?:text|json)?\s*/i,'').replace(/\s*```$/,'').trim();
    var parts = raw.indexOf('|||') >= 0 ? raw.split('|||') : raw.split(/\n+/);
    return parts.map(function(s){ return s.replace(/^[\d\.\-\*\s]+/,'').trim(); }).filter(function(s){ return s.length > 1; }).slice(0,2);
  }
  function needsTranslationForPersona(persona){
    var lang = '';
    try { lang = (typeof _detectPersonaLang === 'function') ? String(_detectPersonaLang(persona) || '').toLowerCase().trim() : ''; } catch(e) { lang = ''; }
    if (!lang) return false;
    if (lang === 'zh' || lang === 'zh-cn' || lang.indexOf('zh-') === 0) return false;
    return !persona || persona.enableTranslation !== false;
  }
  async function translateTextForPersona(text, persona){
    var clean = String(text || '').trim();
    var lang = '';
    try { lang = (typeof _detectPersonaLang === 'function') ? String(_detectPersonaLang(persona) || '').toLowerCase().trim() : ''; } catch(e) { lang = ''; }
    if (!clean || !needsTranslationForPersona(persona)) return '';
    try { if (typeof _monoShouldTranslateTextForPersona === 'function' && !_monoShouldTranslateTextForPersona(clean, persona, lang)) return ''; } catch(e) {}
    try {
      var prompt = (typeof buildTranslationPrompt === 'function')
        ? buildTranslationPrompt(clean, 'zh')
        : ('将以下文字翻译成简体中文，只返回翻译结果：\n' + clean);
      var raw = await chatComplete([
        { role:'system', content:'你是翻译器，只返回简体中文译文，不要解释。' },
        { role:'user', content:prompt }
      ], { temperature:0.2, max_tokens: Math.max(80, Math.min(500, clean.length * 4)) });
      return String(raw || '').replace(/^```(?:text)?\s*/i,'').replace(/\s*```$/,'').trim();
    } catch(e) {
      return '';
    }
  }
  async function translateListForPersona(list, persona){
    var items = (Array.isArray(list) ? list : []).map(function(item){ return String(item || '').trim(); }).filter(Boolean);
    if (!items.length || !needsTranslationForPersona(persona)) return [];
    var out = [];
    for (var i = 0; i < items.length; i++) out.push(await translateTextForPersona(items[i], persona));
    return out;
  }
  window.monoInstagramGetCurrentChatApi = getCurrentChatApi;
  window.monoInstagramChatComplete = chatComplete;
  window.monoInstagramNeedsTranslation = needsTranslationForPersona;
  window.monoInstagramTranslateText = translateTextForPersona;
  window.monoInstagramTranslateList = translateListForPersona;
  var syncApiWindow = function(){ try { var c=getCurrentChatApi(); if(c) window.apiConfig = Object.assign({}, c); } catch(e) {} };
  syncApiWindow(); setTimeout(syncApiWindow, 200); setTimeout(syncApiWindow, 1200);

  window.generateIgStoryForPersona = async function(persona){
    var p = persona || {};
    var langOv = '';
    try { langOv = (typeof _langOverridePrompt === 'function' && typeof _detectPersonaLang === 'function') ? _langOverridePrompt(_detectPersonaLang(p)) : ''; } catch(e) {}
    var prompt = '你是' + (p.name || '角色') + '，人设：' + (p.persona || '普通人') + '。' + langOv + '\n现在请你以第一人称写 1 到 2 条 Instagram Story 文字动态，要有真实生活感，可以关于食物、心情、场所、小事、今天的状态。\n规则：每条动态之间用 ||| 分隔，不要解释，不要标题，直接返回动态内容。';
    try {
      var raw = await chatComplete([{role:'system',content:'你是角色 Instagram Story 生成器，只返回 Story 文案。'}, {role:'user',content:prompt}], {temperature:0.9,max_tokens:260});
      var parts = splitStories(raw);
      if (!parts.length) return null;
      var now = new Date().toLocaleTimeString('zh-CN', {hour:'2-digit', minute:'2-digit'});
      if (needsTranslationForPersona(p)) {
        var translations = await translateListForPersona(parts, p);
        return parts.map(function(t, idx){ return { text: t, translation: (translations[idx] || '').trim(), time: now }; });
      }
      return parts.map(function(t){ return { text: t, translation: '', time: now }; });
    } catch(e) {
      try { if (typeof _showApiErrorToast === 'function') _showApiErrorToast('IG Story 生成失败', e); } catch(_) {}
      try { if (typeof showToast === 'function') showToast('IG Story 生成失败：' + (e.message || e)); } catch(_) {}
      return null;
    }
  };

  window.refreshIgStories = async function(){
    var roles = [];
    try { roles = Array.isArray(personas) ? personas : []; } catch(e) { roles = []; }
    if (!roles.length) { alert('尚无角色，请先创建角色。'); return; }
    var btn = document.querySelector('.ig-refresh-btn');
    if (btn) btn.innerHTML = '<i class="fas fa-spinner fa-spin" style="margin-right:3px;font-size:8px;"></i>生成中';
    try { window.igStories = {}; window.igSeenStories = {}; } catch(e) {}
    var now = new Date().toLocaleTimeString('zh-CN', {hour:'2-digit', minute:'2-digit'});
    var results = await Promise.all(roles.map(function(p){ return window.generateIgStoryForPersona(p).then(function(stories){ return {p:p, stories:stories}; }).catch(function(){ return {p:p, stories:null}; }); }));
    var ok = 0;
    try {
      results.forEach(function(r){
        if (r.stories && r.stories.length) {
          window.igStories[r.p.id] = r.stories.map(function(s){ return typeof s === 'object' ? {text:s.text, translation:s.translation||'', time:s.time||now} : {text:String(s), translation:'', time:now}; });
          ok++;
        }
      });
      localStorage.setItem('mono_ig_stories', JSON.stringify(window.igStories || {}));
    } catch(e) {}
    if (btn) btn.innerHTML = '<i class="fas fa-sync-alt" style="margin-right:3px;font-size:8px;"></i>同步快拍';
    try { if (typeof renderIgStories === 'function') renderIgStories(); } catch(e) {}
    try { if (typeof openInstagramApp === 'function') { /* keep page state */ } } catch(e) {}
    if (!ok) alert('IG Story 生成失败：没有成功生成内容，请确认聊天室当前 API 能正常回复。');
  };
})();


