// ===== mono-instagram-safe-icon-position-nav-patch-script =====

(function(){
  if(window.__monoInstagramSafeIconPositionNavPatch) return;
  window.__monoInstagramSafeIconPositionNavPatch = true;
  var INSTAGRAM_DEFAULT_SVG = "<svg viewBox='0 0 52 52' xmlns='http://www.w3.org/2000/svg' style='width:38px;height:38px;'><rect x='10' y='10' width='32' height='32' rx='10' fill='none' stroke='#555' stroke-width='3'/><circle cx='26' cy='26' r='7.2' fill='none' stroke='#555' stroke-width='3'/><circle cx='35.5' cy='16.8' r='2.5' fill='#555'/></svg>";
  function readPos(){ try { return JSON.parse(localStorage.getItem('mono_iph_positions_v3') || '{}') || {}; } catch(e){ return {}; } }
  function writePos(p){ try { localStorage.setItem('mono_iph_positions_v3', JSON.stringify(p || {})); } catch(e){} }
  function calcGap(pos){
    var d=pos['app-decrypt'], e=pos['app-entertainment'];
    if(d && e && String(d.parentId||'homePage3')===String(e.parentId||'homePage3')){
      var gap=Math.round(Number(e.x)-Number(d.x));
      if(Number.isFinite(gap) && gap>40 && gap<180) return gap;
    }
    return 84;
  }
  function wantedPos(pos){
    var yt=pos['app-youtube'] || {x:16,y:208,parentId:'homePage3'};
    var gap=calcGap(pos);
    return {x:(Number(yt.x)||16)+gap, y:(Number(yt.y)||180), parentId:yt.parentId||'homePage3'};
  }
  function fixInstagramPosition(forceKnownWrong){
    var el=document.getElementById('app-instagram');
    if(!el) return;
    el.dataset.dragId='app-instagram';
    var pos=readPos();
    var want=wantedPos(pos);
    var cur=pos['app-instagram'];
    var isMissing=!cur;
    var isOldDefault=cur && String(cur.parentId||'homePage3')==='homePage3' && Number(cur.x)===180 && Number(cur.y)===180;
    if(isMissing || isOldDefault || forceKnownWrong){
      cur=want;
      pos['app-instagram']=cur;
      writePos(pos);
    }
    var parent=document.getElementById(cur.parentId || want.parentId);
    if(parent && el.parentElement!==parent) parent.appendChild(el);
    el.classList.add('iph-placed');
    el.style.left=(Number.isFinite(Number(cur.x))?Number(cur.x):want.x)+'px';
    el.style.top=(Number.isFinite(Number(cur.y))?Number(cur.y):want.y)+'px';
    el.style.margin='0';
    el.style.flexShrink='0';
  }
  function applyInstagramCustomIcon(){
    var box=document.getElementById('instagramHomeIconBox');
    if(!box) return;
    var icon='';
    try { icon=localStorage.getItem('mono_icon_instagram') || ''; } catch(e){}
    if(icon){ box.innerHTML='<img class="custom-icon" src="'+String(icon).replace(/"/g,'&quot;')+'" style="border-radius:16px;">'; }
  }
  function ensureInstagramInCustomizeConfig(){
    try{
      if(Array.isArray(window.APP_ICONS_CONFIG) && !window.APP_ICONS_CONFIG.some(function(x){return x&&x.key==='instagram';})){
        window.APP_ICONS_CONFIG.push({key:'instagram',label:'Instagram',icon:'fa-instagram',type:'page3',defaultSvg:INSTAGRAM_DEFAULT_SVG});
        if(typeof window.renderIconCustomizeGrid==='function') window.renderIconCustomizeGrid();
      }
    }catch(e){}
  }
  function patchResetAllIcons(){
    try{
      if(typeof window.resetAllIcons==='function' && !window.resetAllIcons.__insSafeWrapped){
        var raw=window.resetAllIcons;
        window.resetAllIcons=function(){
          var ret=raw.apply(this, arguments);
          try{
            var box=document.getElementById('instagramHomeIconBox');
            if(box) box.innerHTML=INSTAGRAM_DEFAULT_SVG;
          }catch(e){}
          return ret;
        };
        window.resetAllIcons.__insSafeWrapped=true;
      }
    }catch(e){}
  }
  function run(){ ensureInstagramInCustomizeConfig(); fixInstagramPosition(false); applyInstagramCustomIcon(); patchResetAllIcons(); }
  document.addEventListener('DOMContentLoaded', run);
  window.addEventListener('load', run, {passive:true});
  setTimeout(run,0); setTimeout(run,300); setTimeout(run,1000);
  // 如果主屏幕位置系统后续重新套用旧值，这里只修正“旧默认 180,180”，不会覆盖用户手动拖动后的自定义位置。
  var oldRender=window.renderInstagramHomeIcon;
  window.renderInstagramHomeIcon=function(){ try{ if(typeof oldRender==='function') oldRender.apply(this, arguments); }catch(e){} fixInstagramPosition(false); applyInstagramCustomIcon(); };
})();


