// ===== mono-home-widget-delete-restore-script =====

(function(){
  if(window.__monoHomeWidgetDeleteRestoreFix) return;
  window.__monoHomeWidgetDeleteRestoreFix = true;
  function isHomeEditing(){
    try{
      return document.body.classList.contains('home-edit-active') ||
             document.body.classList.contains('editing-home') ||
             document.documentElement.classList.contains('home-edit-active') ||
             document.documentElement.classList.contains('editing-home') ||
             (document.getElementById('homeScreen') && (
               document.getElementById('homeScreen').classList.contains('home-edit-active') ||
               document.getElementById('homeScreen').classList.contains('editing-home')
             ));
    }catch(e){ return false; }
  }
  function restoreDeleteButtons(){
    if(!isHomeEditing()) return;
    try{
      var root = document.getElementById('homeScreen') || document.querySelector('.home-screen') || document.body;
      root.querySelectorAll('.hw-delete-btn,.pw-delete-btn').forEach(function(btn){
        if(btn.closest('#instagramPage')) return;
        var holder = btn.closest('.is-dragging-source');
        if(holder){
          btn.style.display = 'none';
          return;
        }
        btn.style.removeProperty('display');
        btn.style.removeProperty('visibility');
        btn.style.removeProperty('pointer-events');
        btn.style.visibility = 'visible';
        btn.style.pointerEvents = 'auto';
      });
    }catch(e){}
  }
  function bindDeleteButtons(){
    try{
      document.querySelectorAll('#homeScreen .hw-delete-btn,#homeScreen .pw-delete-btn,.home-screen .hw-delete-btn,.home-screen .pw-delete-btn').forEach(function(btn){
        if(btn.closest('#instagramPage') || btn.__monoDeleteRestoreBound) return;
        btn.__monoDeleteRestoreBound = true;
        ['pointerdown','mousedown','touchstart'].forEach(function(type){
          btn.addEventListener(type,function(ev){ ev.stopPropagation(); },{capture:true,passive:true});
        });
        btn.addEventListener('click',function(ev){ ev.stopPropagation(); },true);
      });
    }catch(e){}
  }
  function tick(){ restoreDeleteButtons(); bindDeleteButtons(); }
  document.addEventListener('DOMContentLoaded',function(){ setTimeout(tick,50); setTimeout(tick,400); });
  ['click','pointerdown','touchstart','touchend'].forEach(function(type){
    document.addEventListener(type,function(){ setTimeout(tick,0); },true);
  });
  try{
    new MutationObserver(function(){ tick(); }).observe(document.documentElement,{attributes:true,attributeFilter:['class']});
    new MutationObserver(function(){ tick(); }).observe(document.body,{attributes:true,attributeFilter:['class'],childList:true,subtree:true});
  }catch(e){}
  setInterval(function(){ if(isHomeEditing()) tick(); }, 1800);
})();


