// ===== mono-home-widget-delete-click-hard-script =====

(function(){
  if(window.__monoHomeWidgetDeleteClickHardFix) return;
  window.__monoHomeWidgetDeleteClickHardFix = true;

  function homeEditOn(){
    var hs = document.getElementById('homeScreen') || document.querySelector('.home-screen');
    return !!(hs && hs.classList && hs.classList.contains('home-edit-active')) ||
           document.body.classList.contains('home-edit-active') ||
           document.body.classList.contains('editing-home');
  }
  function closestDeleteBtn(t){
    return t && t.closest ? t.closest('#homeScreen .hw-delete-btn,#homeScreen .pw-delete-btn,.home-screen .hw-delete-btn,.home-screen .pw-delete-btn') : null;
  }
  function widgetIdFromBtn(btn){
    var host = btn && btn.closest && btn.closest('[data-drag-id], .home-calendar-widget, .home-photo-widget, .ig-widget, .memo-widget, .family-widget, .couple-space-widget, .photo-widget-airdrop, .photo-widget-tv, .photo-widget-kodak, .photo-widget-spotify, .photo-widget-receipt, .photo-widget-custom-image, .photo-widget-livechat, .photo-widget-decrypt-secret, .photo-widget-couple-calendar');
    if(!host) return '';
    return host.getAttribute('data-drag-id') || host.id || '';
  }
  var regularLabels = {
    homeCalendarWidget:'日历桌件',
    'home图片Widget':'照片桌件',
    igWidget:'Instagram 桌件',
    memoWidget:'备忘录桌件',
    familyWidget:'Family 桌件',
    coupleSpaceWidget:'情侣空间桌件'
  };
  function doDelete(btn, ev){
    if(!btn || btn.closest('#instagramPage') || !homeEditOn()) return false;
    if(ev){
      try{ ev.preventDefault(); }catch(e){}
      try{ ev.stopImmediatePropagation(); }catch(e){}
      try{ ev.stopPropagation(); }catch(e){}
    }
    var id = widgetIdFromBtn(btn);
    if(!id) return true;
    if(btn.classList.contains('hw-delete-btn') || regularLabels[id]){
      if(typeof window.deleteRegularWidget === 'function') window.deleteRegularWidget(id, regularLabels[id] || '桌件');
      else {
        var el = document.getElementById(id);
        if(el) el.style.display = 'none';
      }
    }else{
      if(typeof window.deleteCustomWidget === 'function') window.deleteCustomWidget(id);
      else {
        var el2 = document.getElementById(id);
        if(el2) el2.remove();
      }
    }
    return true;
  }

  // 在 capture 阶段拦截，避免主屏幕拖拽系统先 preventDefault 后吞掉 click。
  ['pointerdown','touchstart','mousedown'].forEach(function(type){
    document.addEventListener(type,function(ev){
      var btn = closestDeleteBtn(ev.target);
      if(btn && homeEditOn()){
        try{ ev.stopImmediatePropagation(); }catch(e){}
        try{ ev.stopPropagation(); }catch(e){}
      }
    }, true);
  });
  ['click','touchend','pointerup','mouseup'].forEach(function(type){
    document.addEventListener(type,function(ev){
      var btn = closestDeleteBtn(ev.target);
      if(btn) doDelete(btn, ev);
    }, true);
  });
})();


