// ===== mono-sticker-covered-buttons-fix-script =====

(function(){
  if (window.__monoStickerCoveredButtonsFix) return;
  window.__monoStickerCoveredButtonsFix = true;

  function byId(id){ return document.getElementById(id); }
  function moveToBody(el){
    if (el && el.parentElement !== document.body) {
      try { document.body.appendChild(el); } catch(e) {}
    }
    return el;
  }
  function ensurePanelsOnTop(){
    moveToBody(byId('stickerModal'));
    moveToBody(byId('stickerAddModal'));
    moveToBody(byId('batchStickerModal'));
  }
  function activateOverlay(el){
    if (!el) return;
    moveToBody(el);
    el.classList.add('show');
    el.style.pointerEvents = 'auto';
  }
  function deactivateOverlay(el){
    if (!el) return;
    el.classList.remove('show');
  }

  // 打开表情包库时，先把主弹层和两个子弹窗都搬到 body，避免受 chatPage overflow / z-index 影响。
  var oldOpenStickerModal = window.openStickerModal;
  window.openStickerModal = function(){
    ensurePanelsOnTop();
    document.body.classList.add('mono-sticker-modal-open');
    if (typeof oldOpenStickerModal === 'function') return oldOpenStickerModal.apply(this, arguments);
    var modal = byId('stickerModal');
    activateOverlay(modal);
    if (typeof renderStickerSendView === 'function') renderStickerSendView();
    if (typeof switchStickerTab === 'function') switchStickerTab('send');
  };

  var oldSwitchStickerTab = window.switchStickerTab;
  window.switchStickerTab = function(tab){
    ensurePanelsOnTop();
    if (typeof oldSwitchStickerTab === 'function') oldSwitchStickerTab.apply(this, arguments);
    var send = byId('stickerSendView');
    var manage = byId('stickerManageView');
    if (send) {
      send.style.pointerEvents = tab === 'send' ? 'auto' : 'none';
      if (tab !== 'send') send.style.display = 'none';
    }
    if (manage) {
      manage.style.pointerEvents = tab === 'manage' ? 'auto' : 'none';
      if (tab === 'manage') {
        manage.style.display = 'block';
        manage.style.position = 'relative';
        manage.style.zIndex = '2';
      } else {
        manage.style.display = 'none';
      }
    }
  };

  var oldOpenStickerAddModal = window.openStickerAddModal;
  window.openStickerAddModal = function(libraryId, editIdx){
    ensurePanelsOnTop();
    if (typeof oldOpenStickerAddModal === 'function') {
      oldOpenStickerAddModal.apply(this, arguments);
      activateOverlay(byId('stickerAddModal'));
      return false;
    }
    activateOverlay(byId('stickerAddModal'));
    return false;
  };

  var oldCloseStickerAddModal = window.closeStickerAddModal;
  window.closeStickerAddModal = function(){
    deactivateOverlay(byId('stickerAddModal'));
    if (typeof oldCloseStickerAddModal === 'function') {
      try { oldCloseStickerAddModal.apply(this, arguments); } catch(e) {}
    }
  };

  var oldOpenBatchStickerModal = window.openBatchStickerModal;
  window.openBatchStickerModal = function(){
    ensurePanelsOnTop();
    if (typeof oldOpenBatchStickerModal === 'function') {
      oldOpenBatchStickerModal.apply(this, arguments);
      activateOverlay(byId('batchStickerModal'));
      return false;
    }
    if (window._batchStickerSlots) window._batchStickerSlots = [];
    if (typeof renderBatchStickerSlots === 'function') renderBatchStickerSlots();
    var area = byId('batchStickerUrlArea');
    var progress = byId('batchStickerProgress');
    if (area) area.style.display = 'none';
    if (progress) progress.style.display = 'none';
    activateOverlay(byId('batchStickerModal'));
    return false;
  };

  var oldCloseBatchStickerModal = window.closeBatchStickerModal;
  window.closeBatchStickerModal = function(){
    deactivateOverlay(byId('batchStickerModal'));
    if (typeof oldCloseBatchStickerModal === 'function') {
      try { oldCloseBatchStickerModal.apply(this, arguments); } catch(e) {}
    }
  };

  // 捕获阶段兜底：如果透明层先吃掉点击，也直接触发目标按钮原本的功能。
  document.addEventListener('click', function(e){
    var target = e.target && e.target.closest ? e.target.closest('button, .sticker-add-btn, .sticker-preview-area') : null;
    if (!target) return;
    // MONO FIX: 这个兜底只能在表情包弹窗内部生效，避免误拦截副API/其它页面的“添加”按钮。
    if (!target.closest('#stickerModal, #stickerAddModal, #batchStickerModal')) return;
    var text = (target.textContent || '').replace(/\s+/g, ' ').trim();
    var onclick = target.getAttribute && (target.getAttribute('onclick') || '');

    if (/openBatchStickerModal/.test(onclick) || text.indexOf('批量添加') !== -1) {
      e.preventDefault(); e.stopPropagation();
      window.openBatchStickerModal();
      return;
    }
    if (/openStickerAddModal/.test(onclick) || text === '添加') {
      e.preventDefault(); e.stopPropagation();
      window.openStickerAddModal();
      return;
    }
    if (/batchStickerAddFromAlbum/.test(onclick) || text.indexOf('从相簿选择') !== -1) {
      e.preventDefault(); e.stopPropagation();
      var input = byId('batchStickerFileInput');
      if (input) input.click();
      else if (typeof batchStickerAddFromAlbum === 'function') batchStickerAddFromAlbum();
      return;
    }
    if (/batchStickerToggleUrlInput/.test(onclick) || text.indexOf('输入URL') !== -1) {
      e.preventDefault(); e.stopPropagation();
      if (typeof batchStickerToggleUrlInput === 'function') batchStickerToggleUrlInput();
      else {
        var area = byId('batchStickerUrlArea');
        if (area) area.style.display = area.style.display === 'none' ? 'block' : 'none';
      }
      return;
    }
  }, true);

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', ensurePanelsOnTop, { once:true });
  } else {
    ensurePanelsOnTop();
  }
})();


