// ===== mono-sticker-library-dialog-top-fix-script =====

(function(){
  if (window.__monoStickerLibraryDialogTopFix) return;
  window.__monoStickerLibraryDialogTopFix = true;

  function byId(id){ return document.getElementById(id); }
  function moveToBody(el){
    if (el && el.parentElement !== document.body) {
      try { document.body.appendChild(el); } catch(e) {}
    }
    return el;
  }
  function forceTop(el, z){
    if (!el) return;
    moveToBody(el);
    el.style.position = 'fixed';
    el.style.inset = '0';
    el.style.zIndex = String(z);
    el.style.pointerEvents = 'auto';
  }
  function ensureDialogTop(){
    forceTop(byId('monoDialogOverlay'), 2147483646);
    forceTop(byId('monoSystemAlertOverlay'), 2147483644);
    moveToBody(byId('stickerModal'));
    moveToBody(byId('stickerAddModal'));
    moveToBody(byId('batchStickerModal'));
  }
  function ensureManageClickable(){
    var ids = ['stickerManageView','stickerLibraryToolbar','stickerUrlInput','stickerBulkUrlInput','stickerBulkUrlAutoDesc'];
    ids.forEach(function(id){
      var el = byId(id);
      if (!el) return;
      el.style.pointerEvents = 'auto';
      el.style.position = el.style.position || 'relative';
      if (id !== 'stickerManageView') el.style.zIndex = '2147483305';
    });
    var sections = document.querySelectorAll('#stickerManageView .sticker-url-section, #stickerManageView button, #stickerLibraryToolbar button');
    sections.forEach(function(el){
      el.style.pointerEvents = 'auto';
      el.style.position = el.style.position || 'relative';
      el.style.zIndex = '2147483305';
      el.style.touchAction = 'manipulation';
    });
  }

  // 包一层应用内弹窗函数：每次打开前/打开后都搬到 body 顶层。
  ['monoInAppForm','monoInAppPrompt','monoInAppConfirm'].forEach(function(name){
    var oldFn = window[name];
    if (typeof oldFn !== 'function' || oldFn.__monoStickerDialogWrapped) return;
    var wrapped = function(){
      ensureDialogTop();
      var result = oldFn.apply(this, arguments);
      setTimeout(ensureDialogTop, 0);
      setTimeout(ensureDialogTop, 30);
      return result;
    };
    wrapped.__monoStickerDialogWrapped = true;
    window[name] = wrapped;
  });

  // 重新渲染管理页后，马上把按钮区抬高，避免被 grid/遮罩盖住。
  var oldRenderManage = window.renderStickerManageView;
  if (typeof oldRenderManage === 'function' && !oldRenderManage.__monoStickerManageWrapped) {
    var wrappedRender = function(){
      var res = oldRenderManage.apply(this, arguments);
      ensureDialogTop();
      ensureManageClickable();
      setTimeout(ensureManageClickable, 0);
      return res;
    };
    wrappedRender.__monoStickerManageWrapped = true;
    window.renderStickerManageView = wrappedRender;
  }

  var oldSwitch = window.switchStickerTab;
  if (typeof oldSwitch === 'function' && !oldSwitch.__monoStickerDialogSwitchWrapped) {
    var wrappedSwitch = function(tab){
      var res = oldSwitch.apply(this, arguments);
      if (tab === 'manage') {
        ensureDialogTop();
        ensureManageClickable();
        setTimeout(ensureManageClickable, 0);
      }
      return res;
    };
    wrappedSwitch.__monoStickerDialogSwitchWrapped = true;
    window.switchStickerTab = wrappedSwitch;
  }

  // 捕获这些按钮，先把 dialog 提到顶层，再放行原本 onclick；这样不重写原导入逻辑。
  document.addEventListener('click', function(ev){
    var btn = ev.target && ev.target.closest ? ev.target.closest('#stickerManageView button, #stickerLibraryToolbar button') : null;
    if (!btn) return;
    var txt = (btn.textContent || '').replace(/\s+/g,' ').trim();
    var oc = btn.getAttribute('onclick') || '';
    if (/createStickerLibrary|renameStickerLibrary|deleteStickerLibrary|importStickerFromUrl|importStickerUrlsBulk|openStickerAddModal|openBatchStickerModal/.test(oc) || /新建表情包库|重命名|删除当前库|导入表情包|批量导入 URL 表情包/.test(txt)) {
      ensureDialogTop();
      ensureManageClickable();
      setTimeout(ensureDialogTop, 0);
      setTimeout(ensureDialogTop, 50);
    }
  }, true);

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ ensureDialogTop(); ensureManageClickable(); }, {once:true});
  } else {
    ensureDialogTop();
    ensureManageClickable();
  }
})();


