// ===== mono-role-image-per-persona-failover-v1 =====

(function(){
  if (window.__monoRoleImagePerPersonaFailoverV1) return;
  window.__monoRoleImagePerPersonaFailoverV1 = true;

  function txt(v){ return String(v == null ? '' : v); }

  function getUserName(){
    try {
      if (window.userProfile && window.userProfile.name) return window.userProfile.name;
    } catch(e) {}
    return '用户';
  }

  function recentContext(p){
    try {
      var hist = p && Array.isArray(p.history) ? p.history : [];
      return hist
        .filter(function(m){ return m && !m._hiddenContext && !m._systemNote && !m.imageGenerating && !m.msgType; })
        .slice(-8)
        .map(function(m){
          return (m.role === 'user' ? getUserName() : (p.name || '角色')) + '：' + txt(m.content).replace(/\s+/g,' ').slice(0,120);
        })
        .join('\n');
    } catch(e) {
      return '';
    }
  }

  function latestUserText(p){
    try {
      var hist = p && Array.isArray(p.history) ? p.history : [];
      for (var i = hist.length - 1; i >= 0; i--) {
        var m = hist[i];
        if (m && m.role === 'user' && !m.msgType && txt(m.content).trim()) {
          return txt(m.content).trim();
        }
      }
    } catch(e) {}
    return '';
  }

  function buildFallbackDesc(p, userText){
    var base = txt(userText || latestUserText(p)).trim();
    var ctx = recentContext(p);
    var roleName = (p && p.name) || '角色';

    if (!base && ctx) base = ctx.split('\n').pop() || '';
    if (!base) base = '角色现在身边的日常场景';

    base = base
      .replace(/发(张|个)?(图|图片|照片)|拍(张|个)?给我看|给我看|看看|想看|show me|send/i, '')
      .replace(/\s+/g, ' ')
      .trim();

    var desc = base || '身边随手能拍到的生活细节';
    return roleName + '亲手拿手机随手拍给用户看的照片，画面是' + desc + '相关的眼前细节，第一视角或近距离手持手机视角，普通生活光线，构图随意，像真实手机相册照片';
  }

  function trimPrompt(prompt){
    var s = txt(prompt).trim();
    if (s.length <= 2600) return s;
    var head = s.slice(0, 1800);
    var tail = s.slice(-650);
    return head + '\n\n【中间过长内容已自动省略，避免某个角色人设/世界书导致生图失败】\n\n' + tail;
  }

  function strengthenRoleShot(prompt){
    var s = txt(prompt).trim();
    if (!s) return s;
    if (s.indexOf('【单角色生图失败兜底规则】') >= 0) return trimPrompt(s);
    s += '\n\n【单角色生图失败兜底规则】\n';
    s += '如果角色人设、世界书、角色专属生图指令互相冲突，以“角色亲手拿手机拍给用户的真实生活照”为最高优先级。\n';
    s += '不要因为角色设定复杂就改成第三人称摄影机、大片写真、海报、棚拍或AI绘画。\n';
    s += '默认角色不出镜，除非用户明确要求自拍/露脸/本人；优先拍角色眼前能顺手拍到的物品、环境、餐食、桌面、窗外、手部、衣角、正在做的事。\n';
    s += '保持真实普通手机照片质感：轻微手抖、普通光线、随意裁切、生活杂物、构图不完美。';
    return trimPrompt(s);
  }

  // 某个角色的“图片描述生成”失败时，不要整条生图失败，改用最近用户请求和聊天上下文生成兜底描述。
  if (typeof window.monoGenerateFinalImageDescriptionWithChatApi === 'function' && !window.monoGenerateFinalImageDescriptionWithChatApi.__monoPersonaFailoverWrapped) {
    var oldDesc = window.monoGenerateFinalImageDescriptionWithChatApi;
    var wrappedDesc = async function(p, userText, explicit){
      try {
        var desc = await oldDesc.apply(this, arguments);
        desc = txt(desc).trim();
        if (desc) return desc;
      } catch(e) {
        console.warn('[单角色生图描述生成失败，启用兜底描述]', e);
      }
      return buildFallbackDesc(p || {}, userText || '');
    };
    wrappedDesc.__monoPersonaFailoverWrapped = true;
    window.monoGenerateFinalImageDescriptionWithChatApi = wrappedDesc;
  }

  if (typeof window.monoBuildImagePromptFromDescription === 'function' && !window.monoBuildImagePromptFromDescription.__monoPersonaFailoverWrapped) {
    var oldBuildFromDesc = window.monoBuildImagePromptFromDescription;
    var wrappedBuild = function(finalDescription, p){
      var prompt = oldBuildFromDesc.apply(this, arguments);
      return strengthenRoleShot(prompt);
    };
    wrappedBuild.__monoPersonaFailoverWrapped = true;
    window.monoBuildImagePromptFromDescription = wrappedBuild;
  }

  if (typeof window.monoBuildImagePrompt === 'function' && !window.monoBuildImagePrompt.__monoPersonaFailoverWrapped) {
    var oldBuild = window.monoBuildImagePrompt;
    var wrappedBuild2 = function(p, finalDescription){
      var prompt = oldBuild.apply(this, arguments);
      return strengthenRoleShot(prompt);
    };
    wrappedBuild2.__monoPersonaFailoverWrapped = true;
    window.monoBuildImagePrompt = wrappedBuild2;
  }

  // 最终请求前再截断一次，避免某个角色的人设/世界书/图设太长导致 API 拒绝。
  if (!window.__monoPersonaImagePromptTrimFetchWrapped && typeof window.fetch === 'function') {
    window.__monoPersonaImagePromptTrimFetchWrapped = true;
    var oldFetch = window.fetch.bind(window);
    window.fetch = function(input, init){
      try {
        var url = (typeof input === 'string') ? input : (input && input.url ? input.url : '');
        if (/\/images\/generations(?:\?|$)/i.test(url) && init && init.body) {
          var body = typeof init.body === 'string' ? JSON.parse(init.body) : init.body;
          if (body && typeof body === 'object') {
            if (typeof body.prompt === 'string') body.prompt = strengthenRoleShot(body.prompt);
            body.size = body.size || '1024x1024';
            body.response_format = body.response_format || 'b64_json';
            init = Object.assign({}, init, { body: JSON.stringify(body) });
          }
        }
      } catch(e) {}
      return oldFetch(input, init);
    };
  }
})();


