// ===== mono-image-persona-summary-current-editor-fix-v2 =====

(function(){
  if (window.__monoImagePersonaSummaryCurrentEditorFixV2) return;
  window.__monoImagePersonaSummaryCurrentEditorFixV2 = true;

  function txt(v){ return String(v == null ? '' : v); }
  function hasEditorOpen(){
    return !!(document.getElementById('pName') && document.getElementById('pPersona'));
  }
  function listPersonas(){
    try { return Array.isArray(window.personas) ? window.personas : []; } catch(e) { return []; }
  }
  function byId(id){
    if (id == null || id === '') return null;
    return listPersonas().find(function(p){ return String(p.id) === String(id); }) || null;
  }
  function findEditingPersona(){
    var candidates = [];
    try { candidates.push(window.currentId); } catch(e) {}
    try { candidates.push(window.editingPersonaId); } catch(e) {}
    try { candidates.push(window.selectedPersonaId); } catch(e) {}
    try { if (window.currentPersona && window.currentPersona.id) candidates.push(window.currentPersona.id); } catch(e) {}
    for (var i=0;i<candidates.length;i++){
      var p = byId(candidates[i]);
      if (p) return p;
    }
    return null;
  }
  function editorSnapshot(){
    var p = findEditingPersona();
    return {
      id: p && p.id,
      target: p || null,
      name: txt((document.getElementById('pName')||{}).value || (p && p.name) || '角色').trim() || '角色',
      nick: txt((document.getElementById('pNick')||{}).value || (p && p.nickname) || '').trim(),
      persona: txt((document.getElementById('pPersona')||{}).value || (p && p.persona) || '').trim(),
      imagePrompt: txt((document.getElementById('pImagePrompt')||{}).value || (p && p.imagePrompt) || '').trim(),
      imageStylePrompt: txt((document.getElementById('pImageStylePrompt')||{}).value || (p && p.imageStylePrompt) || '').trim(),
      imagePersonaSummary: txt((document.getElementById('pImagePersonaSummary')||{}).value || (p && p.imagePersonaSummary) || '').trim()
    };
  }
  function status(text, good){
    var el = document.getElementById('monoImagePersonaSummaryStatus');
    if (!el) return;
    el.textContent = text || '';
    el.style.color = good ? '#6b7280' : '#b91c1c';
  }
  function getChatApi(){
    try { if (typeof window._getCurrentActiveApiConfig === 'function') { var a = window._getCurrentActiveApiConfig(); if (a && a.url && a.key) return a; } } catch(e) {}
    try { if (typeof window.monoGetCurrentChatImageTextApiConfig === 'function') { var b = window.monoGetCurrentChatImageTextApiConfig(); if (b && b.url && b.key) return b; } } catch(e) {}
    return null;
  }
  function applyModel(payload, model){
    try { if (typeof window._applyApiModel === 'function') return window._applyApiModel(payload, model); } catch(e) {}
    if (model && !payload.model) payload.model = model;
    return payload;
  }
  async function chatComplete(cfg, payload){
    if (typeof window._compatibleChatCompletion === 'function') {
      return await window._compatibleChatCompletion(cfg.url, cfg.key, payload, {});
    }
    var endpoint = String(cfg.url || '').replace(/\/$/, '').replace(/\/chat\/completions$/i, '') + '/chat/completions';
    return await fetch(endpoint, {
      method:'POST',
      headers:{ 'Authorization':'Bearer ' + cfg.key, 'Content-Type':'application/json' },
      body:JSON.stringify(payload)
    });
  }
  function extractAssistant(data, raw){
    try { if (typeof window._extractAssistantMessageContent === 'function') return txt(window._extractAssistantMessageContent(data)); } catch(e) {}
    try {
      if (data && data.choices && data.choices[0] && data.choices[0].message) return txt(data.choices[0].message.content);
      if (data && data.text) return txt(data.text);
    } catch(e) {}
    return txt(raw);
  }
  function cleanSummary(s){
    s = txt(s).trim().replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
    try {
      var obj = JSON.parse(s);
      if (obj && typeof obj === 'object') s = obj.summary || obj.text || obj.content || s;
    } catch(e) {}
    return txt(s).replace(/^人设总结[:：]?/,'').replace(/^[“"]|[”"]$/g,'').trim().slice(0,500);
  }

  async function generateFromCurrentEditor(){
    if (!hasEditorOpen()) {
      status('请先打开角色设置页面。', false);
      return;
    }
    var snap = editorSnapshot();
    if (!snap.persona) {
      status('当前角色设置里还没有填写人设，无法总结。', false);
      return;
    }
    var cfg = getChatApi();
    if (!cfg || !cfg.url || !cfg.key) {
      status('没有读取到当前聊天连接的 API。', false);
      return;
    }

    var btn = document.getElementById('monoGenerateImagePersonaSummaryBtn');
    if (btn) { btn.disabled = true; btn.textContent = '生成人设总结中...'; }
    status('正在用当前聊天连接的 API 生成人设总结...', true);

    try {
      var system = [
        '你现在只负责把角色完整人设压缩成“供生图参考的人设总结”。',
        '之后生图不会再放整段人设，只会放这段总结。',
        '只提炼会影响图片生成的内容：身份、年龄感、气质、外形特征、常见穿搭/风格、生活环境、和用户关系、适合出现在图片里的习惯或氛围。',
        '不要照抄原人设，不要长篇剧情复述。',
        '80到220字左右，一段话，直接输出总结文本，不要标题，不要JSON。'
      ].join('\n');
      var user = [
        '角色名：' + snap.name,
        snap.nick ? ('昵称/称呼：' + snap.nick) : '',
        '完整角色人设：\n' + snap.persona,
        snap.imagePrompt ? ('当前生图内容指令：' + snap.imagePrompt) : '',
        snap.imageStylePrompt ? ('当前图片风格指令：' + snap.imageStylePrompt) : ''
      ].filter(Boolean).join('\n');

      var payload = applyModel({
        messages:[{role:'system',content:system},{role:'user',content:user}],
        temperature:0.5,
        max_tokens:220,
        stream:false
      }, cfg.model);

      var resp = await chatComplete(cfg, payload);
      var raw = await resp.text();
      if (!resp.ok) throw new Error('HTTP ' + resp.status + '：' + raw.slice(0,180));
      var data; try { data = JSON.parse(raw); } catch(e) { data = { text: raw }; }
      var summary = cleanSummary(extractAssistant(data, raw));
      if (!summary) throw new Error('API 没有返回可用总结。');

      var textarea = document.getElementById('pImagePersonaSummary');
      if (textarea) textarea.value = summary;

      // 如果能识别到已有角色，先临时写入；保存设定时还会再写一次。
      var target = findEditingPersona();
      if (target) {
        target.imagePersonaSummary = summary;
        try { if (typeof window.saveData === 'function') window.saveData(); } catch(e) {}
      }

      status('已生成。你可以手动修改，点保存设定后会正式保存到角色。', true);
      return summary;
    } catch(err) {
      console.warn('[人设总结生成失败]', err);
      status('生成人设总结失败：' + txt(err && err.message || err).slice(0,160), false);
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '人设总结（靠当前聊天连接的API）'; }
    }
  }

  function ensureUiFixed(){
    var styleEl = document.getElementById('pImageStylePrompt');
    if (!styleEl) return;
    var wrap = document.getElementById('monoImagePersonaSummaryWrap');
    if (!wrap && typeof window._mipsEnsureUi === 'function') {
      try { window._mipsEnsureUi(); } catch(e) {}
      wrap = document.getElementById('monoImagePersonaSummaryWrap');
    }
    if (!wrap) return;
    var btn = document.getElementById('monoGenerateImagePersonaSummaryBtn');
    if (btn && !btn.__currentEditorFixed) {
      btn.__currentEditorFixed = true;
      btn.onclick = function(e){ e.preventDefault(); e.stopPropagation(); generateFromCurrentEditor(); return false; };
    }
    var p = findEditingPersona();
    var el = document.getElementById('pImagePersonaSummary');
    if (el && p && !el.value) el.value = p.imagePersonaSummary || '';
  }

  if (typeof window.openEditor === 'function' && !window.openEditor.__mipsCurrentFixWrapped) {
    var oldOpen = window.openEditor;
    var openWrap = function(){
      var ret = oldOpen.apply(this, arguments);
      setTimeout(ensureUiFixed, 0);
      setTimeout(ensureUiFixed, 150);
      return ret;
    };
    openWrap.__mipsCurrentFixWrapped = true;
    window.openEditor = openWrap;
  }

  if (typeof window.savePersona === 'function' && !window.savePersona.__mipsCurrentFixWrapped) {
    var oldSave = window.savePersona;
    var saveWrap = function(){
      var summary = txt((document.getElementById('pImagePersonaSummary')||{}).value).trim();
      var ret = oldSave.apply(this, arguments);
      setTimeout(function(){
        var p = findEditingPersona();
        if (p) {
          p.imagePersonaSummary = summary;
          try { if (typeof window.saveData === 'function') window.saveData(); } catch(e) {}
        }
      }, 0);
      return ret;
    };
    saveWrap.__mipsCurrentFixWrapped = true;
    window.savePersona = saveWrap;
  }

  window.monoGenerateImagePersonaSummary = generateFromCurrentEditor;
  window.monoGenerateImagePersonaSummaryFromCurrentEditor = generateFromCurrentEditor;
  window.monoImagePersonaSummaryEnsureUiFixed = ensureUiFixed;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(ensureUiFixed, 200); });
  } else {
    setTimeout(ensureUiFixed, 200);
  }
})();


