// ===== mono-image-recent-chat-separate-context-v1 =====

(function(){
  if (window.__monoImageRecentChatSeparateContextV1) return;
  window.__monoImageRecentChatSeparateContextV1 = true;

  function txt(v){ return String(v == null ? '' : v); }

  function buildRecentChatContext(p){
    try {
      var hist = p && Array.isArray(p.history) ? p.history : [];
      var rows = hist
        .filter(function(m){
          return m && !m._hiddenContext && !m._systemNote && !m.imageGenerating;
        })
        .slice(-10)
        .map(function(m){
          var speaker = m.role === 'user' ? '用户' : ((p && p.name) || '角色');
          var content = txt(m.content || '');
          if (m.msgType === 'image') content = '[图片]' + (m.imageDesc || m.imageCaption || '');
          if (m.msgType === 'sticker') content = '[表情包]' + (m.stickerDesc || '');
          if (m.msgType === 'voice') content = '[语音]' + content;
          content = content.replace(/\s+/g, ' ').trim();
          if (!content) return '';
          return speaker + '：' + content.slice(0, 140);
        })
        .filter(Boolean);
      return rows.join('\n');
    } catch(e) {
      return '';
    }
  }

  function appendRecentChatRule(prompt, p){
    var s = txt(prompt).trim();
    if (!s) return s;
    if (s.indexOf('【最近聊天独立参考】') !== -1) return s;

    var recent = buildRecentChatContext(p);
    var block = [
      '',
      '【最近聊天独立参考】',
      '最近聊天只用来判断“这次图片现在该拍什么、拍哪里、拍什么物品/动作/场景”，不能当成人设总结，也不能覆盖角色设定。',
      '如果用户刚刚明确要求看某个东西，图片必须优先回应最近聊天里的具体要求。',
      '如果最近聊天和生图内容指令冲突，以用户最近明确要求为当前图片内容优先；但图片风格仍参考图片风格指令。',
      recent ? ('最近聊天记录：\n' + recent) : '最近聊天记录：（暂无）'
    ].join('\n');

    return s + '\n' + block;
  }

  if (typeof window.monoBuildImagePromptFromDescription === 'function' && !window.monoBuildImagePromptFromDescription.__recentChatSeparateWrapped) {
    var oldBuildFrom = window.monoBuildImagePromptFromDescription;
    var wrappedBuildFrom = function(finalDescription, p){
      var base = oldBuildFrom.apply(this, arguments);
      return appendRecentChatRule(base, p);
    };
    wrappedBuildFrom.__recentChatSeparateWrapped = true;
    window.monoBuildImagePromptFromDescription = wrappedBuildFrom;
  }

  if (typeof window.monoBuildImagePrompt === 'function' && !window.monoBuildImagePrompt.__recentChatSeparateWrapped) {
    var oldBuild = window.monoBuildImagePrompt;
    var wrappedBuild = function(p, finalDescription){
      var base = oldBuild.apply(this, arguments);
      return appendRecentChatRule(base, p);
    };
    wrappedBuild.__recentChatSeparateWrapped = true;
    window.monoBuildImagePrompt = wrappedBuild;
  }

  // 最终发到生图 API 前再补一层，防止某些链路没走 build prompt。
  if (!window.__monoRecentChatSeparateFetchWrapped && typeof window.fetch === 'function') {
    window.__monoRecentChatSeparateFetchWrapped = true;
    var oldFetch = window.fetch.bind(window);
    window.fetch = function(input, init){
      try {
        var url = (typeof input === 'string') ? input : (input && input.url ? input.url : '');
        if (/\/images\/generations(?:\?|$)/i.test(url) && init && init.body) {
          var body = typeof init.body === 'string' ? JSON.parse(init.body) : init.body;
          if (body && typeof body === 'object') {
            body.size = body.size || '1024x1024';
            body.response_format = body.response_format || 'b64_json';
            init = Object.assign({}, init, { body: JSON.stringify(body) });
          }
        }
      } catch(e) {}
      return oldFetch(input, init);
    };
  }
})();


