// ===== mono-image-persona-summary-persist-v1 =====

(function(){
  if (window.__monoImagePersonaSummaryPersistV1) return;
  window.__monoImagePersonaSummaryPersistV1 = true;

  var LS_KEY = 'mono_image_persona_summary_map_v1';
  var DB_NAME = 'MonoImagePersonaSummaryDB';
  var STORE = 'kv';
  var IDB_KEY = 'summaryMap';

  function txt(v){ return String(v == null ? '' : v); }
  function safeParse(s, fallback){ try { return JSON.parse(s); } catch(e){ return fallback; } }
  function listPersonas(){ try { return Array.isArray(window.personas) ? window.personas : []; } catch(e){ return []; } }
  function getById(id){ return listPersonas().find(function(p){ return String(p.id) === String(id); }) || null; }
  function summaryEl(){ return document.getElementById('pImagePersonaSummary'); }

  function openDb(){
    return new Promise(function(resolve){
      try {
        if (!window.indexedDB) return resolve(null);
        var req = indexedDB.open(DB_NAME, 1);
        req.onupgradeneeded = function(){
          var db = req.result;
          if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE);
        };
        req.onsuccess = function(){ resolve(req.result); };
        req.onerror = function(){ resolve(null); };
      } catch(e){ resolve(null); }
    });
  }
  async function idbGetMap(){
    try {
      var db = await openDb();
      if (!db) return {};
      return await new Promise(function(resolve){
        try {
          var tx = db.transaction(STORE, 'readonly');
          var req = tx.objectStore(STORE).get(IDB_KEY);
          req.onsuccess = function(){ resolve(req.result || {}); };
          req.onerror = function(){ resolve({}); };
        } catch(e){ resolve({}); }
      });
    } catch(e){ return {}; }
  }
  async function idbSetMap(map){
    try {
      var db = await openDb();
      if (!db) return;
      await new Promise(function(resolve){
        try {
          var tx = db.transaction(STORE, 'readwrite');
          tx.objectStore(STORE).put(map || {}, IDB_KEY);
          tx.oncomplete = function(){ resolve(); };
          tx.onerror = function(){ resolve(); };
        } catch(e){ resolve(); }
      });
    } catch(e) {}
  }

  function lsGetMap(){ return safeParse(localStorage.getItem(LS_KEY) || '{}', {}); }
  function lsSetMap(map){ try { localStorage.setItem(LS_KEY, JSON.stringify(map || {})); } catch(e) {} }
  function cleanMap(map){
    var out = {};
    Object.keys(map || {}).forEach(function(k){
      var v = txt(map[k]).trim();
      if (v) out[String(k)] = v;
    });
    return out;
  }

  async function getMergedMap(){
    var map = cleanMap(lsGetMap());
    var idbMap = cleanMap(await idbGetMap());
    var changed = false;
    Object.keys(idbMap).forEach(function(k){ if (!map[k] && idbMap[k]) { map[k] = idbMap[k]; changed = true; } });
    if (changed) lsSetMap(map);
    return map;
  }

  function findEditingPersona(){
    var ids=[];
    try{ ids.push(window.currentId); }catch(e){}
    try{ ids.push(window.editingPersonaId); }catch(e){}
    try{ ids.push(window.selectedPersonaId); }catch(e){}
    for (var i=0;i<ids.length;i++){ if (ids[i] != null && ids[i] !== '') { var p=getById(ids[i]); if (p) return p; } }
    return null;
  }

  function mergeMapIntoPersonasSync(map){
    var arr = listPersonas();
    var changed = false;
    arr.forEach(function(p){
      if (!p) return;
      var id = String(p.id);
      var fromMap = txt(map[id]).trim();
      if (fromMap && txt(p.imagePersonaSummary).trim() !== fromMap) {
        p.imagePersonaSummary = fromMap;
        changed = true;
      }
    });
    return changed;
  }

  async function persistMap(map){
    map = cleanMap(map);
    lsSetMap(map);
    await idbSetMap(map);
  }

  async function persistCurrentPersonaSummary(){
    var p = findEditingPersona();
    var el = summaryEl();
    if (!p || !el) return;
    var summary = txt(el.value).trim();
    p.imagePersonaSummary = summary;
    var map = await getMergedMap();
    if (summary) map[String(p.id)] = summary; else delete map[String(p.id)];
    await persistMap(map);
    try { if (typeof window.saveData === 'function') window.saveData(); } catch(e) {}
  }

  async function persistAllPersonaSummaries(){
    var map = await getMergedMap();
    listPersonas().forEach(function(p){
      if (!p) return;
      var s = txt(p.imagePersonaSummary).trim();
      if (s) map[String(p.id)] = s;
    });
    await persistMap(map);
  }

  async function hydrateAllPersonaSummaries(){
    var map = await getMergedMap();
    var changed = mergeMapIntoPersonasSync(map);
    // also if persona has summary but map lacks it, backfill map
    listPersonas().forEach(function(p){
      if (!p) return;
      var id = String(p.id);
      var s = txt(p.imagePersonaSummary).trim();
      if (s && !map[id]) { map[id] = s; changed = true; }
    });
    if (changed) {
      await persistMap(map);
      try { if (typeof window.saveData === 'function') window.saveData(); } catch(e) {}
    }
    var editP = findEditingPersona();
    var el = summaryEl();
    if (editP && el && !txt(el.value).trim()) el.value = txt(editP.imagePersonaSummary).trim();
  }

  // Hook savePersona so summary really stays in persona + localStorage + IndexedDB.
  if (typeof window.savePersona === 'function' && !window.savePersona.__summaryPersistWrapped) {
    var oldSave = window.savePersona;
    var wrapped = function(){
      var el = summaryEl();
      var currentSummary = el ? txt(el.value).trim() : '';
      var ret = oldSave.apply(this, arguments);
      setTimeout(function(){
        try {
          var p = findEditingPersona();
          if (p) p.imagePersonaSummary = currentSummary;
          persistCurrentPersonaSummary();
        } catch(e) {}
      }, 0);
      return ret;
    };
    wrapped.__summaryPersistWrapped = true;
    window.savePersona = wrapped;
  }

  // Hook saveData as extra insurance.
  if (typeof window.saveData === 'function' && !window.saveData.__summaryPersistWrapped) {
    var oldSaveData = window.saveData;
    var wrappedSaveData = function(){
      listPersonas().forEach(function(p){
        if (!p) return;
        p.imagePersonaSummary = txt(p.imagePersonaSummary).trim();
      });
      var ret = oldSaveData.apply(this, arguments);
      persistAllPersonaSummaries();
      return ret;
    };
    wrappedSaveData.__summaryPersistWrapped = true;
    window.saveData = wrappedSaveData;
  }

  // Export: before original export runs, ensure summaries are hydrated into personas so backup contains them.
  if (typeof window.exportAllData === 'function' && !window.exportAllData.__summaryPersistWrapped) {
    var oldExport = window.exportAllData;
    var wrappedExport = async function(){
      await hydrateAllPersonaSummaries();
      return oldExport.apply(this, arguments);
    };
    wrappedExport.__summaryPersistWrapped = true;
    window.exportAllData = wrappedExport;
  }

  // Import: after original import completes, persist imported summaries to LS + IDB.
  if (typeof window.confirmImport === 'function' && !window.confirmImport.__summaryPersistWrapped) {
    var oldConfirmImport = window.confirmImport;
    var wrappedImport = async function(){
      var ret = await oldConfirmImport.apply(this, arguments);
      setTimeout(function(){ hydrateAllPersonaSummaries(); persistAllPersonaSummaries(); }, 60);
      return ret;
    };
    wrappedImport.__summaryPersistWrapped = true;
    window.confirmImport = wrappedImport;
  }

  // Open editor: refill textarea from persona/map so it won't look cleared after reopen.
  if (typeof window.openEditor === 'function' && !window.openEditor.__summaryPersistWrapped) {
    var oldOpen = window.openEditor;
    var wrappedOpen = function(){
      var ret = oldOpen.apply(this, arguments);
      setTimeout(function(){ hydrateAllPersonaSummaries(); }, 50);
      setTimeout(function(){ hydrateAllPersonaSummaries(); }, 220);
      return ret;
    };
    wrappedOpen.__summaryPersistWrapped = true;
    window.openEditor = wrappedOpen;
  }

  // If user edits textarea directly, mirror into current persona in-memory.
  document.addEventListener('input', function(ev){
    if (ev && ev.target && ev.target.id === 'pImagePersonaSummary') {
      try {
        var p = findEditingPersona();
        if (p) p.imagePersonaSummary = txt(ev.target.value).trim();
      } catch(e) {}
    }
  }, true);

  window.monoHydrateImagePersonaSummaries = hydrateAllPersonaSummaries;
  window.monoPersistImagePersonaSummary = persistCurrentPersonaSummary;
  window.monoPersistAllImagePersonaSummaries = persistAllPersonaSummaries;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(hydrateAllPersonaSummaries, 120); });
  } else {
    setTimeout(hydrateAllPersonaSummaries, 120);
  }
})();


;
// ===== mono-image-persona-summary-save-button-hardfix-v2 =====

(function(){
  if (window.__monoImagePersonaSummarySaveButtonHardfixV2) return;
  window.__monoImagePersonaSummarySaveButtonHardfixV2 = true;

  var LS_KEY = 'mono_image_persona_summary_map_v1';
  var DB_NAME = 'MonoImagePersonaSummaryDB';
  var STORE = 'kv';
  var IDB_KEY = 'summaryMap';
  var pendingSummary = null;

  function txt(v){ return String(v == null ? '' : v); }
  function parseJson(s, fb){ try { return JSON.parse(s); } catch(e){ return fb; } }
  function personasList(){ try { return Array.isArray(window.personas) ? window.personas : []; } catch(e){ return []; } }

  function getMap(){
    return parseJson(localStorage.getItem(LS_KEY) || '{}', {});
  }
  function setMap(map){
    try { localStorage.setItem(LS_KEY, JSON.stringify(map || {})); } catch(e) {}
    saveMapToIdb(map || {});
  }
  function openDb(){
    return new Promise(function(resolve){
      try {
        if (!window.indexedDB) return resolve(null);
        var req = indexedDB.open(DB_NAME, 1);
        req.onupgradeneeded = function(){
          var db = req.result;
          if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE);
        };
        req.onsuccess = function(){ resolve(req.result); };
        req.onerror = function(){ resolve(null); };
      } catch(e){ resolve(null); }
    });
  }
  async function saveMapToIdb(map){
    try {
      var db = await openDb();
      if (!db) return;
      var tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).put(map || {}, IDB_KEY);
    } catch(e) {}
  }
  async function loadMapFromIdb(){
    try {
      var db = await openDb();
      if (!db) return {};
      return await new Promise(function(resolve){
        try {
          var tx = db.transaction(STORE, 'readonly');
          var req = tx.objectStore(STORE).get(IDB_KEY);
          req.onsuccess = function(){ resolve(req.result || {}); };
          req.onerror = function(){ resolve({}); };
        } catch(e){ resolve({}); }
      });
    } catch(e){ return {}; }
  }

  function findById(id){
    if (id == null || id === '') return null;
    return personasList().find(function(p){ return String(p.id) === String(id); }) || null;
  }

  function findEditorTarget(){
    var ids = [];
    try { ids.push(window.currentId); } catch(e){}
    try { ids.push(window.editingPersonaId); } catch(e){}
    try { ids.push(window.selectedPersonaId); } catch(e){}
    for (var i=0;i<ids.length;i++){
      var p = findById(ids[i]);
      if (p) return p;
    }
    return null;
  }

  function captureSummary(){
    var el = document.getElementById('pImagePersonaSummary');
    var summary = txt(el && el.value).trim();
    var target = findEditorTarget();
    pendingSummary = {
      summary: summary,
      id: target && target.id != null ? String(target.id) : '',
      name: txt((document.getElementById('pName')||{}).value).trim(),
      persona: txt((document.getElementById('pPersona')||{}).value).trim(),
      time: Date.now()
    };
    if (target) {
      target.imagePersonaSummary = summary;
      writeSummaryForPersona(target, summary);
    }
    return pendingSummary;
  }

  function resolvePendingTarget(){
    if (!pendingSummary) return findEditorTarget();
    if (pendingSummary.id) {
      var byId = findById(pendingSummary.id);
      if (byId) return byId;
    }
    return null;
  }

  function writeSummaryForPersona(p, summary){
    if (!p || p.id == null) return;
    summary = txt(summary).trim();
    p.imagePersonaSummary = summary;
    var map = getMap();
    if (summary) map[String(p.id)] = summary;
    else delete map[String(p.id)];
    setMap(map);
  }

  function commitPendingSummary(){
    if (!pendingSummary) return;
    var p = resolvePendingTarget();
    if (!p) return;
    writeSummaryForPersona(p, pendingSummary.summary);
    try {
      var slim = parseJson(localStorage.getItem('mono_personas') || '[]', []);
      if (Array.isArray(slim)) {
        var changed = false;
        slim.forEach(function(item){
          if (item && String(item.id) === String(p.id)) {
            item.imagePersonaSummary = txt(pendingSummary.summary).trim();
            changed = true;
          }
        });
        if (changed) localStorage.setItem('mono_personas', JSON.stringify(slim));
      }
    } catch(e) {}
    try { if (typeof window.saveData === 'function') window.saveData(); } catch(e) {}
  }

  // 直接拦截底部 SAVE 按钮：在原 savePersona 运行前先抓住框里的值，避免弹窗关闭后读不到。
  document.addEventListener('click', function(ev){
    try {
      var btn = ev.target && ev.target.closest ? ev.target.closest('button') : null;
      if (!btn) return;
      var text = txt(btn.textContent).trim().toLowerCase();
      var isSave = text === 'save' || text === '保存' || text === '保存设定';
      var hasEditor = !!(document.getElementById('pImagePersonaSummary') && document.getElementById('pPersona'));
      if (isSave && hasEditor) {
        captureSummary();
        setTimeout(commitPendingSummary, 80);
        setTimeout(commitPendingSummary, 280);
        setTimeout(commitPendingSummary, 800);
      }
    } catch(e) {}
  }, true);

  // 再包一层 savePersona：不管按钮还是键盘触发，都保存。
  if (typeof window.savePersona === 'function' && !window.savePersona.__summaryButtonHardWrapped) {
    var oldSave = window.savePersona;
    var wrapped = function(){
      captureSummary();
      var ret = oldSave.apply(this, arguments);
      setTimeout(commitPendingSummary, 80);
      setTimeout(commitPendingSummary, 280);
      setTimeout(commitPendingSummary, 800);
      return ret;
    };
    wrapped.__summaryButtonHardWrapped = true;
    window.savePersona = wrapped;
  }

  async function hydrateFromAllStores(){
    var map = getMap();
    var idbMap = await loadMapFromIdb();
    Object.keys(idbMap || {}).forEach(function(k){ if (!map[k]) map[k] = idbMap[k]; });

    var changed = false;
    personasList().forEach(function(p){
      if (!p || p.id == null) return;
      var id = String(p.id);
      var fromMap = txt(map[id]).trim();
      var fromPersona = txt(p.imagePersonaSummary).trim();
      if (fromMap && !fromPersona) {
        p.imagePersonaSummary = fromMap;
        changed = true;
      } else if (fromPersona && !fromMap) {
        map[id] = fromPersona;
        changed = true;
      }
    });
    if (changed) {
      setMap(map);
      try { if (typeof window.saveData === 'function') window.saveData(); } catch(e){}
    }

    var target = findEditorTarget();
    var el = document.getElementById('pImagePersonaSummary');
    if (target && el && !txt(el.value).trim()) {
      el.value = txt(target.imagePersonaSummary || map[String(target.id)] || '').trim();
    }
  }

  if (typeof window.openEditor === 'function' && !window.openEditor.__summaryHydrateHardWrapped) {
    var oldOpen = window.openEditor;
    var openWrap = function(){
      var ret = oldOpen.apply(this, arguments);
      setTimeout(hydrateFromAllStores, 80);
      setTimeout(hydrateFromAllStores, 300);
      return ret;
    };
    openWrap.__summaryHydrateHardWrapped = true;
    window.openEditor = openWrap;
  }

  if (typeof window.exportAllData === 'function' && !window.exportAllData.__summaryExportHardWrapped) {
    var oldExport = window.exportAllData;
    var exportWrap = async function(){
      await hydrateFromAllStores();
      return oldExport.apply(this, arguments);
    };
    exportWrap.__summaryExportHardWrapped = true;
    window.exportAllData = exportWrap;
  }

  if (typeof window.confirmImport === 'function' && !window.confirmImport.__summaryImportHardWrapped) {
    var oldImport = window.confirmImport;
    var importWrap = async function(){
      var ret = await oldImport.apply(this, arguments);
      setTimeout(hydrateFromAllStores, 120);
      setTimeout(hydrateFromAllStores, 600);
      return ret;
    };
    importWrap.__summaryImportHardWrapped = true;
    window.confirmImport = importWrap;
  }

  window.monoCommitCurrentImagePersonaSummary = function(){
    captureSummary();
    commitPendingSummary();
  };
  window.monoHydrateImagePersonaSummaries = hydrateFromAllStores;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(hydrateFromAllStores, 200); });
  } else {
    setTimeout(hydrateFromAllStores, 200);
  }
})();


