// ===== mono-image-persona-summary-display-hardfix-v3 =====

(function(){
  if (window.__monoImagePersonaSummaryDisplayHardfixV3) return;
  window.__monoImagePersonaSummaryDisplayHardfixV3 = true;

  var ID_MAP_KEY = 'mono_image_persona_summary_map_v1';
  var SIG_MAP_KEY = 'mono_image_persona_summary_sig_map_v1';
  var DB_NAME = 'MonoImagePersonaSummaryDB';
  var STORE = 'kv';
  var IDB_ID_KEY = 'summaryMap';
  var IDB_SIG_KEY = 'summarySigMap';

  function txt(v){ return String(v == null ? '' : v); }
  function parse(s, fb){ try { return JSON.parse(s); } catch(e){ return fb; } }
  function personasList(){ try { return Array.isArray(window.personas) ? window.personas : []; } catch(e){ return []; } }
  function el(id){ return document.getElementById(id); }
  function summaryEl(){ return el('pImagePersonaSummary'); }
  function normalize(s){ return txt(s).replace(/\s+/g,' ').trim(); }
  function smallHash(str){
    str = txt(str);
    var h = 2166136261;
    for (var i=0;i<str.length;i++){ h ^= str.charCodeAt(i); h += (h<<1)+(h<<4)+(h<<7)+(h<<8)+(h<<24); }
    return String(h >>> 0);
  }
  function currentFormSig(){
    var name = normalize((el('pName')||{}).value);
    var persona = normalize((el('pPersona')||{}).value);
    return name ? (name + '::' + smallHash(persona)) : '';
  }
  function personaSig(p){
    if (!p) return '';
    var name = normalize(p.name);
    var persona = normalize(p.persona);
    return name ? (name + '::' + smallHash(persona)) : '';
  }
  function idMap(){ return parse(localStorage.getItem(ID_MAP_KEY) || '{}', {}); }
  function sigMap(){ return parse(localStorage.getItem(SIG_MAP_KEY) || '{}', {}); }
  function setIdMap(m){ try { localStorage.setItem(ID_MAP_KEY, JSON.stringify(m || {})); } catch(e){} idbPut(IDB_ID_KEY, m || {}); }
  function setSigMap(m){ try { localStorage.setItem(SIG_MAP_KEY, JSON.stringify(m || {})); } catch(e){} idbPut(IDB_SIG_KEY, m || {}); }

  function openDb(){
    return new Promise(function(resolve){
      try {
        if (!window.indexedDB) return resolve(null);
        var req = indexedDB.open(DB_NAME, 1);
        req.onupgradeneeded = function(){
          var db = req.result;
          if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE);
        };
        req.onsuccess = function(){ resolve(req.result); };
        req.onerror = function(){ resolve(null); };
      } catch(e){ resolve(null); }
    });
  }
  async function idbGet(key){
    try {
      var db = await openDb();
      if (!db) return {};
      return await new Promise(function(resolve){
        try {
          var tx = db.transaction(STORE, 'readonly');
          var req = tx.objectStore(STORE).get(key);
          req.onsuccess = function(){ resolve(req.result || {}); };
          req.onerror = function(){ resolve({}); };
        } catch(e){ resolve({}); }
      });
    } catch(e){ return {}; }
  }
  async function idbPut(key, val){
    try {
      var db = await openDb();
      if (!db) return;
      var tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).put(val || {}, key);
    } catch(e){}
  }

  function findById(id){
    if (id == null || id === '') return null;
    return personasList().find(function(p){ return String(p.id) === String(id); }) || null;
  }
  function findTarget(){
    var ids = [];
    try { ids.push(window.currentId); } catch(e){}
    try { ids.push(window.editingPersonaId); } catch(e){}
    try { ids.push(window.selectedPersonaId); } catch(e){}
    for (var i=0;i<ids.length;i++){
      var p = findById(ids[i]);
      if (p) return p;
    }
    return null;
  }

  function writeSlimPersonaField(pid, summary){
    try {
      var arr = parse(localStorage.getItem('mono_personas') || '[]', []);
      if (!Array.isArray(arr)) return;
      var changed = false;
      arr.forEach(function(p){
        if (p && String(p.id) === String(pid)) {
          p.imagePersonaSummary = txt(summary).trim();
          changed = true;
        }
      });
      if (changed) localStorage.setItem('mono_personas', JSON.stringify(arr));
    } catch(e){}
  }

  var lastCaptured = null;

  function captureFromEditor(){
    var area = summaryEl();
    if (!area) return null;
    var summary = txt(area.value).trim();
    var p = findTarget();
    var formSig = currentFormSig();
    lastCaptured = {
      summary: summary,
      id: p && p.id != null ? String(p.id) : '',
      sig: p ? personaSig(p) : formSig,
      formSig: formSig,
      name: normalize((el('pName')||{}).value),
      persona: normalize((el('pPersona')||{}).value),
      time: Date.now()
    };
    if (p) {
      p.imagePersonaSummary = summary;
      if (summary) {
        var im = idMap(); im[String(p.id)] = summary; setIdMap(im);
        var sm = sigMap(); sm[personaSig(p)] = summary; if (formSig) sm[formSig] = summary; setSigMap(sm);
        writeSlimPersonaField(p.id, summary);
      }
    } else if (summary && formSig) {
      var sm2 = sigMap(); sm2[formSig] = summary; setSigMap(sm2);
    }
    return lastCaptured;
  }

  function commitCaptured(){
    if (!lastCaptured) captureFromEditor();
    if (!lastCaptured) return;
    var summary = txt(lastCaptured.summary).trim();
    var p = lastCaptured.id ? findById(lastCaptured.id) : null;
    if (!p) p = findTarget();
    var im = idMap();
    var sm = sigMap();

    if (summary) {
      if (lastCaptured.formSig) sm[lastCaptured.formSig] = summary;
      if (lastCaptured.sig) sm[lastCaptured.sig] = summary;
    }

    if (p) {
      p.imagePersonaSummary = summary;
      if (summary) {
        im[String(p.id)] = summary;
        sm[personaSig(p)] = summary;
      } else {
        delete im[String(p.id)];
      }
      writeSlimPersonaField(p.id, summary);
    }

    setIdMap(im);
    setSigMap(sm);
  }

  async function hydrateMaps(){
    var im = idMap();
    var sm = sigMap();
    var idbIm = await idbGet(IDB_ID_KEY);
    var idbSm = await idbGet(IDB_SIG_KEY);
    Object.keys(idbIm || {}).forEach(function(k){ if (!im[k]) im[k] = idbIm[k]; });
    Object.keys(idbSm || {}).forEach(function(k){ if (!sm[k]) sm[k] = idbSm[k]; });

    var changed = false;
    personasList().forEach(function(p){
      if (!p || p.id == null) return;
      var pid = String(p.id);
      var psig = personaSig(p);
      var fromPersona = txt(p.imagePersonaSummary).trim();
      var fromId = txt(im[pid]).trim();
      var fromSig = txt(sm[psig]).trim();
      var best = fromPersona || fromId || fromSig;
      if (best) {
        if (txt(p.imagePersonaSummary).trim() !== best) { p.imagePersonaSummary = best; changed = true; }
        if (!im[pid]) { im[pid] = best; changed = true; }
        if (psig && !sm[psig]) { sm[psig] = best; changed = true; }
      }
    });

    if (changed) {
      setIdMap(im);
      setSigMap(sm);
      try { if (typeof window.saveData === 'function') window.saveData(); } catch(e){}
    }
    return { id: im, sig: sm };
  }

  async function forceFillEditor(){
    var area = summaryEl();
    if (!area) return;
    var maps = await hydrateMaps();
    var p = findTarget();
    var formSig = currentFormSig();
    var value = '';
    if (p) value = txt(p.imagePersonaSummary || maps.id[String(p.id)] || maps.sig[personaSig(p)]).trim();
    if (!value && formSig) value = txt(maps.sig[formSig]).trim();

    // 重点：重新打开角色设置时，旧脚本可能把框设为空；这里强制回填。
    if (value) area.value = value;
  }

  // 覆盖旧同步函数，避免旧函数用空值覆盖 textarea。
  if (typeof window._mipsSyncUiFromPersona === 'function' && !window._mipsSyncUiFromPersona.__displayHardfix) {
    window._mipsSyncUiFromPersona = function(){
      setTimeout(forceFillEditor, 0);
      setTimeout(forceFillEditor, 120);
    };
    window._mipsSyncUiFromPersona.__displayHardfix = true;
  }

  function watchSaveClick(ev){
    try {
      var btn = ev.target && ev.target.closest ? ev.target.closest('button') : null;
      if (!btn) return;
      var text = txt(btn.textContent).trim().toLowerCase();
      var isSave = text === 'save' || text === '保存' || text === '保存设定';
      if (isSave && summaryEl() && el('pPersona')) {
        captureFromEditor();
        setTimeout(commitCaptured, 20);
        setTimeout(commitCaptured, 160);
        setTimeout(commitCaptured, 500);
        setTimeout(commitCaptured, 1200);
      }
    } catch(e){}
  }
  document.addEventListener('click', watchSaveClick, true);
  document.addEventListener('submit', function(){ captureFromEditor(); setTimeout(commitCaptured, 80); }, true);
  document.addEventListener('input', function(ev){
    if (ev && ev.target && ev.target.id === 'pImagePersonaSummary') captureFromEditor();
  }, true);

  if (typeof window.savePersona === 'function' && !window.savePersona.__displayHardfix) {
    var oldSave = window.savePersona;
    var wrappedSave = function(){
      captureFromEditor();
      var ret = oldSave.apply(this, arguments);
      setTimeout(commitCaptured, 20);
      setTimeout(commitCaptured, 160);
      setTimeout(commitCaptured, 500);
      setTimeout(commitCaptured, 1200);
      return ret;
    };
    wrappedSave.__displayHardfix = true;
    window.savePersona = wrappedSave;
  }

  if (typeof window.openEditor === 'function' && !window.openEditor.__displayHardfix) {
    var oldOpen = window.openEditor;
    var wrappedOpen = function(){
      var ret = oldOpen.apply(this, arguments);
      setTimeout(forceFillEditor, 0);
      setTimeout(forceFillEditor, 120);
      setTimeout(forceFillEditor, 400);
      setTimeout(forceFillEditor, 1000);
      return ret;
    };
    wrappedOpen.__displayHardfix = true;
    window.openEditor = wrappedOpen;
  }

  if (typeof window.exportAllData === 'function' && !window.exportAllData.__summaryDisplayHardfix) {
    var oldExport = window.exportAllData;
    var wrappedExport = async function(){
      await hydrateMaps();
      return oldExport.apply(this, arguments);
    };
    wrappedExport.__summaryDisplayHardfix = true;
    window.exportAllData = wrappedExport;
  }

  if (typeof window.confirmImport === 'function' && !window.confirmImport.__summaryDisplayHardfix) {
    var oldImport = window.confirmImport;
    var wrappedImport = async function(){
      var ret = await oldImport.apply(this, arguments);
      setTimeout(hydrateMaps, 100);
      setTimeout(hydrateMaps, 800);
      return ret;
    };
    wrappedImport.__summaryDisplayHardfix = true;
    window.confirmImport = wrappedImport;
  }

  window.monoForceFillImagePersonaSummary = forceFillEditor;
  window.monoCommitImagePersonaSummaryNow = function(){ captureFromEditor(); commitCaptured(); forceFillEditor(); };
  window.monoHydrateImagePersonaSummaries = hydrateMaps;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){
      setTimeout(hydrateMaps, 120);
      setTimeout(forceFillEditor, 500);
    });
  } else {
    setTimeout(hydrateMaps, 120);
    setTimeout(forceFillEditor, 500);
  }
})();


