// ===== mono-image-settings-panel-restore-v1 =====

(function(){
  if (window.__monoImageSettingsPanelRestoreV1) return;
  window.__monoImageSettingsPanelRestoreV1 = true;

  function txt(v){ return String(v == null ? '' : v); }

  function ensureImageSettingsPanel(){
    var allow = document.getElementById('pAllowImageGen');
    var fields = document.getElementById('pImageGenFields');

    // 如果原来的生图设置容器被旧补丁/旧回填逻辑弄没了，就重建。
    if (!fields) {
      var anchor = allow ? allow.closest('label,div') : null;
      if (!anchor) {
        var personaArea = document.getElementById('pPersona');
        anchor = personaArea ? personaArea.parentNode : null;
      }
      if (!anchor || !anchor.parentNode) return;

      fields = document.createElement('div');
      fields.id = 'pImageGenFields';
      fields.style.cssText = 'display:none;margin-top:10px;padding:10px;border:1px solid #eee;border-radius:12px;background:#fafafa;';
      fields.innerHTML =
        '<div style="font-size:11px;color:#666;margin:6px 0 4px;">生图内容指令</div>' +
        '<textarea id="pImagePrompt" placeholder="例如：必须符合角色身份和当前场景；只生成角色正在看到/正在做的画面；不要生成文字水印。" style="width:100%;min-height:78px;border:1px solid #ddd;border-radius:8px;padding:8px;font-size:11px;line-height:1.6;outline:none;background:#fff;"></textarea>' +
        '<div style="font-size:11px;color:#666;margin:8px 0 4px;">图片风格指令</div>' +
        '<textarea id="pImageStylePrompt" placeholder="例如：韩系灰白感、真实手机随手拍、自然光、细节真实、不要过度精修。" style="width:100%;min-height:70px;border:1px solid #ddd;border-radius:8px;padding:8px;font-size:11px;line-height:1.6;outline:none;background:#fff;"></textarea>' +
        '<label style="display:flex;align-items:center;gap:8px;margin-top:8px;font-size:11px;color:#333;"><input id="pImageAutoSend" type="checkbox">允许角色低频主动发图</label>';
      anchor.parentNode.insertBefore(fields, anchor.nextSibling);
    }

    // 如果某些 textarea 被删了，只补回缺失的，不覆盖用户原内容。
    if (!document.getElementById('pImagePrompt')) {
      fields.insertAdjacentHTML('afterbegin',
        '<div style="font-size:11px;color:#666;margin:6px 0 4px;">生图内容指令</div>' +
        '<textarea id="pImagePrompt" placeholder="例如：必须符合角色身份和当前场景；只生成角色正在看到/正在做的画面；不要生成文字水印。" style="width:100%;min-height:78px;border:1px solid #ddd;border-radius:8px;padding:8px;font-size:11px;line-height:1.6;outline:none;background:#fff;"></textarea>'
      );
    }

    if (!document.getElementById('pImageStylePrompt')) {
      var prompt = document.getElementById('pImagePrompt');
      (prompt || fields).insertAdjacentHTML(prompt ? 'afterend' : 'beforeend',
        '<div style="font-size:11px;color:#666;margin:8px 0 4px;">图片风格指令</div>' +
        '<textarea id="pImageStylePrompt" placeholder="例如：韩系灰白感、真实手机随手拍、自然光、细节真实、不要过度精修。" style="width:100%;min-height:70px;border:1px solid #ddd;border-radius:8px;padding:8px;font-size:11px;line-height:1.6;outline:none;background:#fff;"></textarea>'
      );
    }

    if (!document.getElementById('pImageAutoSend')) {
      fields.insertAdjacentHTML('beforeend',
        '<label style="display:flex;align-items:center;gap:8px;margin-top:8px;font-size:11px;color:#333;"><input id="pImageAutoSend" type="checkbox">允许角色低频主动发图</label>'
      );
    }

    // 人设总结必须在图片风格指令下面，但不能替换掉图片风格指令。
    var stylePrompt = document.getElementById('pImageStylePrompt');
    var summaryWrap = document.getElementById('monoImagePersonaSummaryWrap');
    if (!summaryWrap && stylePrompt) {
      summaryWrap = document.createElement('div');
      summaryWrap.id = 'monoImagePersonaSummaryWrap';
      summaryWrap.style.marginTop = '8px';
      summaryWrap.innerHTML =
        '<div style="font-size:11px;color:#666;margin:8px 0 6px;line-height:1.6;">人设总结（只总结人设；生图时会和生图内容指令、图片风格指令一起使用）</div>' +
        '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:6px;">' +
        '<button type="button" id="monoGenerateImagePersonaSummaryBtn" style="padding:8px 10px;border:1px solid #d8d8d8;border-radius:8px;background:#fff;font-size:11px;line-height:1.4;color:#111;">人设总结（只总结人设）</button>' +
        '<div id="monoImagePersonaSummaryStatus" style="font-size:10px;color:#6b7280;line-height:1.5;flex:1;min-width:180px;"></div>' +
        '</div>' +
        '<textarea id="pImagePersonaSummary" placeholder="点击上方按钮，只根据角色人设生成人设总结。保存设定后，生图 prompt 会同时参考：生图内容指令、图片风格指令、这里的人设总结；不会再塞入整段完整人设。" style="width:100%;min-height:82px;border:1px solid #ddd;border-radius:8px;padding:8px;font-size:11px;line-height:1.6;outline:none;background:#fff;"></textarea>';
      stylePrompt.insertAdjacentElement('afterend', summaryWrap);
    } else if (summaryWrap && stylePrompt && summaryWrap.previousElementSibling !== stylePrompt) {
      stylePrompt.insertAdjacentElement('afterend', summaryWrap);
    }

    // 恢复显示逻辑：勾选允许生图时显示完整设置；没勾选时隐藏设置。
    var checked = allow ? !!allow.checked : false;
    fields.style.display = checked ? 'block' : 'none';

    if (allow && !allow.__imageSettingsRestoreBound) {
      allow.__imageSettingsRestoreBound = true;
      allow.addEventListener('change', function(){
        var f = document.getElementById('pImageGenFields');
        if (f) f.style.display = allow.checked ? 'block' : 'none';
      });
    }

    // 回填当前角色已有的值，避免重建后为空。
    try {
      var p = null;
      if (typeof window.currentId !== 'undefined' && Array.isArray(window.personas)) {
        p = window.personas.find(function(x){ return String(x.id) === String(window.currentId); });
      }
      if (p) {
        var pi = document.getElementById('pImagePrompt');
        var ps = document.getElementById('pImageStylePrompt');
        var pa = document.getElementById('pImageAutoSend');
        var sum = document.getElementById('pImagePersonaSummary');
        if (pi && !pi.value) pi.value = p.imagePrompt || '';
        if (ps && !ps.value) ps.value = p.imageStylePrompt || '';
        if (pa) pa.checked = !!p.imageAutoSend;
        if (sum && !sum.value) sum.value = p.imagePersonaSummary || '';
      }
    } catch(e) {}

    // 重新绑定人设总结按钮，如果之前补丁的绑定丢了。
    try {
      if (typeof window.monoEnsurePersonaOnlyImageSummaryUi === 'function') window.monoEnsurePersonaOnlyImageSummaryUi();
      if (typeof window.monoForceFillImagePersonaSummary === 'function') window.monoForceFillImagePersonaSummary();
    } catch(e) {}
  }

  if (typeof window.openEditor === 'function' && !window.openEditor.__imageSettingsPanelRestoreWrapped) {
    var oldOpen = window.openEditor;
    var wrappedOpen = function(){
      var ret = oldOpen.apply(this, arguments);
      setTimeout(ensureImageSettingsPanel, 0);
      setTimeout(ensureImageSettingsPanel, 120);
      setTimeout(ensureImageSettingsPanel, 400);
      return ret;
    };
    wrappedOpen.__imageSettingsPanelRestoreWrapped = true;
    window.openEditor = wrappedOpen;
  }

  // 保存时确保这些字段都不会因为 DOM 缺失被保存成空。
  if (typeof window.savePersona === 'function' && !window.savePersona.__imageSettingsPanelRestoreWrapped) {
    var oldSave = window.savePersona;
    var wrappedSave = function(){
      ensureImageSettingsPanel();
      return oldSave.apply(this, arguments);
    };
    wrappedSave.__imageSettingsPanelRestoreWrapped = true;
    window.savePersona = wrappedSave;
  }

  window.monoRestoreImageSettingsPanel = ensureImageSettingsPanel;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(ensureImageSettingsPanel, 200); });
  } else {
    setTimeout(ensureImageSettingsPanel, 200);
  }
})();


