// ===== mono-image-prompt-use-summary-only-hardfix-v1 =====

(function(){
  if (window.__monoImagePromptUseSummaryOnlyHardfixV1) return;
  window.__monoImagePromptUseSummaryOnlyHardfixV1 = true;

  function txt(v){ return String(v == null ? '' : v); }
  function getPersonas(){
    try { return Array.isArray(window.personas) ? window.personas : []; } catch(e) { return []; }
  }
  function hasSummary(p){
    return !!(p && txt(p.imagePersonaSummary).trim());
  }
  function cloneWithSummaryOnly(p){
    if (!p || typeof p !== 'object') return p;
    var summary = txt(p.imagePersonaSummary).trim();
    if (!summary) return p;

    var clone = Object.assign({}, p);

    // 关键：只把“人设总结”作为 persona 传入生图相关链路。
    // 不删除 imagePrompt / imageStylePrompt，因为生图 prompt 仍然需要：
    // 1. 生图内容指令 2. 图片风格指令 3. 人设总结
    clone.persona = summary;
    clone.imagePersonaSummary = summary;
    clone._fullPersonaRemovedForImagePrompt = true;
    return clone;
  }

  function currentPersonaWithSummaryFallback(p){
    if (hasSummary(p)) return p;

    // 如果传进来的 p 因为旧缓存没有 summary，只按角色 id 从全局 personas 找最新版本。
    try {
      var list = getPersonas();
      if (p && p.id != null) {
        var byId = list.find(function(x){ return String(x.id) === String(p.id); });
        if (hasSummary(byId)) return Object.assign({}, p, { imagePersonaSummary: byId.imagePersonaSummary });
      }
    } catch(e) {}
    return p;
  }

  function sanitizePersonaObjectForImage(p){
    return cloneWithSummaryOnly(currentPersonaWithSummaryFallback(p));
  }

  // 1) 图片描述生成阶段：聊天 API 生成图片描述 prompt 时，只传人设总结，不传完整人设。
  if (typeof window.monoGenerateFinalImageDescriptionWithChatApi === 'function' && !window.monoGenerateFinalImageDescriptionWithChatApi.__summaryOnlyHardWrapped) {
    var oldGenDesc = window.monoGenerateFinalImageDescriptionWithChatApi;
    var wrappedGenDesc = async function(p, userText, explicit){
      return await oldGenDesc.call(this, sanitizePersonaObjectForImage(p), userText, explicit);
    };
    wrappedGenDesc.__summaryOnlyHardWrapped = true;
    window.monoGenerateFinalImageDescriptionWithChatApi = wrappedGenDesc;
  }

  // 2) 最终生图 prompt 包装阶段：也只传人设总结。
  if (typeof window.monoBuildImagePromptFromDescription === 'function' && !window.monoBuildImagePromptFromDescription.__summaryOnlyHardWrapped) {
    var oldBuildFromDescription = window.monoBuildImagePromptFromDescription;
    var wrappedBuildFromDescription = function(finalDescription, p){
      return oldBuildFromDescription.call(this, finalDescription, sanitizePersonaObjectForImage(p));
    };
    wrappedBuildFromDescription.__summaryOnlyHardWrapped = true;
    window.monoBuildImagePromptFromDescription = wrappedBuildFromDescription;
  }

  if (typeof window.monoBuildImagePrompt === 'function' && !window.monoBuildImagePrompt.__summaryOnlyHardWrapped) {
    var oldBuildImagePrompt = window.monoBuildImagePrompt;
    var wrappedBuildImagePrompt = function(p, finalDescription){
      return oldBuildImagePrompt.call(this, sanitizePersonaObjectForImage(p), finalDescription);
    };
    wrappedBuildImagePrompt.__summaryOnlyHardWrapped = true;
    window.monoBuildImagePrompt = wrappedBuildImagePrompt;
  }

  function replaceFullPersonaTextWithSummary(str){
    var out = txt(str);
    var list = getPersonas();

    list.forEach(function(p){
      var full = txt(p && p.persona).trim();
      var summary = txt(p && p.imagePersonaSummary).trim();
      if (!full || !summary || full === summary) return;

      // 直接替换完整人设片段，避免旧函数/旧缓存把整段 persona 塞进聊天 API prompt。
      if (out.indexOf(full) >= 0) {
        out = out.split(full).join(summary);
      }

      // 兼容旧模板："你是X。人设：完整人设。你对用户..."
      var name = txt(p.name).trim();
      if (name) {
        var escapedName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        var re = new RegExp('(你是' + escapedName + '[\\s\\S]{0,40}?人设[:：])([\\s\\S]*?)(。你对用户|\\n|\\r)', 'g');
        out = out.replace(re, function(match, prefix, body, suffix){
          // 只在 body 看起来包含原完整人设时替换，避免误改普通句子。
          if (txt(body).indexOf(full.slice(0, Math.min(30, full.length))) >= 0 || body.length > summary.length + 80) {
            return prefix + summary + suffix;
          }
          return match;
        });
      }
    });

    return out;
  }

  function sanitizeChatBody(body){
    if (!body || typeof body !== 'object') return body;

    // 只处理“聊天 API 生成图片描述文字 prompt”的请求，不影响普通聊天。
    var isImageDescRequest = false;
    try {
      var msgText = JSON.stringify(body.messages || []);
      isImageDescRequest =
        msgText.indexOf('角色即将在聊天室发送的一张图片') >= 0 ||
        msgText.indexOf('最终图片描述 prompt') >= 0 ||
        msgText.indexOf('生成图片描述') >= 0 ||
        msgText.indexOf('图片画面描述') >= 0;
    } catch(e) {}

    if (!isImageDescRequest) return body;

    try {
      if (Array.isArray(body.messages)) {
        body.messages = body.messages.map(function(m){
          if (m && typeof m.content === 'string') {
            return Object.assign({}, m, { content: replaceFullPersonaTextWithSummary(m.content) });
          }
          return m;
        });
      }
    } catch(e) {}

    return body;
  }

  function sanitizeImageBody(body){
    if (!body || typeof body !== 'object') return body;
    if (typeof body.prompt === 'string') {
      body.prompt = replaceFullPersonaTextWithSummary(body.prompt);
    }
    return body;
  }

  // 3) 最后一层保险：真正发请求前，再把完整人设从图片描述聊天请求 / 生图请求里剔除。
  if (!window.__monoImageSummaryOnlyFetchWrapped && typeof window.fetch === 'function') {
    window.__monoImageSummaryOnlyFetchWrapped = true;
    var oldFetch = window.fetch.bind(window);

    window.fetch = function(input, init){
      try {
        var url = (typeof input === 'string') ? input : (input && input.url ? input.url : '');
        if (init && init.body && typeof init.body === 'string') {
          var body = JSON.parse(init.body);

          if (/\/chat\/completions(?:\?|$)/i.test(url)) {
            var cleanChatBody = sanitizeChatBody(body);
            init = Object.assign({}, init, { body: JSON.stringify(cleanChatBody) });
          }

          if (/\/images\/generations(?:\?|$)/i.test(url)) {
            var cleanImageBody = sanitizeImageBody(body);
            cleanImageBody.size = cleanImageBody.size || '1024x1024';
            cleanImageBody.response_format = cleanImageBody.response_format || 'b64_json';
            init = Object.assign({}, init, { body: JSON.stringify(cleanImageBody) });
          }
        }
      } catch(e) {}
      return oldFetch(input, init);
    };
  }

  window.monoSanitizePersonaForImagePrompt = sanitizePersonaObjectForImage;
  window.monoReplaceFullPersonaWithImageSummary = replaceFullPersonaTextWithSummary;
})();


