// ===== mono-image-default-role-pov-daily-not-face-v1 =====

(function(){
  if (window.__monoImageDefaultRolePovDailyNotFaceV1) return;
  window.__monoImageDefaultRolePovDailyNotFaceV1 = true;

  function txt(v){ return String(v == null ? '' : v); }

  function userExplicitlyWantsRole(text){
    var t = txt(text).toLowerCase();
    return /(想看你|看看你|看一下你|看下你|看你本人|看看你本人|看你现在|你现在长什么样|你的样子|你的脸|露脸|露个脸|自拍|自拍照|发你自己|发张你|发个你|你的照片|本人照片|你本人|show me you|your face|selfie|send.*you|photo of you|picture of you)/i.test(t);
  }

  function latestUserText(p){
    try {
      var hist = p && Array.isArray(p.history) ? p.history : [];
      for (var i = hist.length - 1; i >= 0; i--) {
        var m = hist[i];
        if (m && m.role === 'user' && !m.msgType && txt(m.content).trim()) return txt(m.content).trim();
      }
    } catch(e) {}
    return '';
  }

  function shouldAllowRoleAppearance(p, prompt){
    return userExplicitlyWantsRole(latestUserText(p)) || userExplicitlyWantsRole(prompt);
  }

  function dailyRolePovRules(allowRole){
    if (allowRole) {
      return [
        '',
        '【角色本人出镜条件】',
        '用户这次明确要求想看角色本人/自拍/露脸，所以可以让角色本人出镜。',
        '但画面仍必须像角色自己临时拿前置或后置手机拍给用户的普通生活照，不是摄影师帮拍，不是第三人称机位，不是写真大片。',
        '人物姿势自然、随意，不要摆拍；皮肤保留真实纹理，不要磨皮、美颜、棚拍光。'
      ].join('\n');
    }

    return [
      '',
      '【默认生图主体硬性规则】',
      '默认不要生成角色本人，不要生成角色正脸，不要生成全身写真，不要让角色站在镜头前当主体。',
      '这张图应该是“角色视角下的日常”：像角色本人拿手机顺手拍下自己眼前的生活画面，然后发给用户。',
      '优先拍角色正在看到/正在做/手边能拍到的东西：桌面、餐食、饮料、电脑、书本、窗外、街边、便利店、房间角落、衣角、手部、影子、手边物品、正在做的事。',
      '可以出现角色的手、袖口、衣角、腿部局部、背包、物品，但不要把角色本人脸和身体作为主角。',
      '禁止莫名其妙的第三人称摄影机角度、旁观镜头、摄影师帮拍、远景跟拍、监控视角、房间角落固定机位。',
      '如果用户只是说“发图/拍给我看/给我看看”，但没有明确说想看你本人，就理解为角色拍自己的日常给用户看，而不是拍角色的脸。'
    ].join('\n');
  }

  function strengthenPrompt(prompt, p){
    var s = txt(prompt).trim();
    if (!s) return s;
    if (s.indexOf('【默认生图主体硬性规则】') >= 0 || s.indexOf('【角色本人出镜条件】') >= 0) return s;
    var allow = shouldAllowRoleAppearance(p, s);
    return s + '\n' + dailyRolePovRules(allow);
  }

  if (typeof window.monoBuildImagePromptFromDescription === 'function' && !window.monoBuildImagePromptFromDescription.__dailyPovNoFaceWrapped) {
    var oldBuildFrom = window.monoBuildImagePromptFromDescription;
    var wrappedBuildFrom = function(finalDescription, p){
      var base = oldBuildFrom.apply(this, arguments);
      return strengthenPrompt(base, p);
    };
    wrappedBuildFrom.__dailyPovNoFaceWrapped = true;
    window.monoBuildImagePromptFromDescription = wrappedBuildFrom;
  }

  if (typeof window.monoBuildImagePrompt === 'function' && !window.monoBuildImagePrompt.__dailyPovNoFaceWrapped) {
    var oldBuild = window.monoBuildImagePrompt;
    var wrappedBuild = function(p, finalDescription){
      var base = oldBuild.apply(this, arguments);
      return strengthenPrompt(base, p);
    };
    wrappedBuild.__dailyPovNoFaceWrapped = true;
    window.monoBuildImagePrompt = wrappedBuild;
  }

  // 聊天 API 生成“图片描述文字 prompt”时也加规则，避免第一步就写成角色写真。
  if (typeof window.monoGenerateFinalImageDescriptionWithChatApi === 'function' && !window.monoGenerateFinalImageDescriptionWithChatApi.__dailyPovNoFaceWrapped) {
    var oldDesc = window.monoGenerateFinalImageDescriptionWithChatApi;
    var wrappedDesc = async function(p, userText, explicit){
      var desc = await oldDesc.apply(this, arguments);
      var allow = userExplicitlyWantsRole(userText) || userExplicitlyWantsRole(desc);
      if (!allow) {
        desc = txt(desc)
          .replace(/角色正脸写真|正脸写真|全身写真|半身写真|精修自拍|人物写真|站在镜头前|对着镜头摆拍/gi, '')
          .replace(/拍(他|她|角色)的脸|角色的脸|露脸/gi, '拍角色眼前的日常细节')
          .trim();
      }
      return desc;
    };
    wrappedDesc.__dailyPovNoFaceWrapped = true;
    window.monoGenerateFinalImageDescriptionWithChatApi = wrappedDesc;
  }

  // 最后一层：真正发给 /images/generations 前再追加规则。这里拿不到 p，就用 prompt 本身判断是否明确要求本人。
  if (!window.__monoDailyPovNoFaceFetchWrapped && typeof window.fetch === 'function') {
    window.__monoDailyPovNoFaceFetchWrapped = true;
    var oldFetch = window.fetch.bind(window);

    window.fetch = function(input, init){
      try {
        var url = (typeof input === 'string') ? input : (input && input.url ? input.url : '');
        if (/\/images\/generations(?:\?|$)/i.test(url) && init && init.body) {
          var body = typeof init.body === 'string' ? JSON.parse(init.body) : init.body;
          if (body && typeof body === 'object' && typeof body.prompt === 'string') {
            var allow = userExplicitlyWantsRole(body.prompt);
            if (body.prompt.indexOf('【默认生图主体硬性规则】') < 0 && body.prompt.indexOf('【角色本人出镜条件】') < 0) {
              body.prompt = body.prompt.trim() + '\n' + dailyRolePovRules(allow);
            }
            body.size = body.size || '1024x1024';
            body.response_format = body.response_format || 'b64_json';
            init = Object.assign({}, init, { body: JSON.stringify(body) });
          }
        }
      } catch(e) {}
      return oldFetch(input, init);
    };
  }

  window.monoImageUserExplicitlyWantsRole = userExplicitlyWantsRole;
})();


