(function(){
  if (window.__monoImagePortrait3x4HardfixV1) return;
  window.__monoImagePortrait3x4HardfixV1 = true;

  function txt(v){ return String(v == null ? '' : v); }

  function addPortraitRules(prompt){
    var s = txt(prompt).trim();
    if (!s) return s;
    if (s.indexOf('【画幅比例硬性要求】') >= 0) return s;
    return s + '\n' + [
      '',
      '【画幅比例硬性要求】',
      '最终图片不要正方形。',
      '最终图片必须是像手机拍照那种竖版 3:4 比例。',
      '构图按手机竖向随手拍来理解，不要做成方形封面图。'
    ].join('\n');
  }

  if (typeof window.monoBuildImagePromptFromDescription === 'function' && !window.monoBuildImagePromptFromDescription.__portrait3x4Wrapped) {
    var oldBuildFrom = window.monoBuildImagePromptFromDescription;
    var wrappedBuildFrom = function(finalDescription, p){
      var base = oldBuildFrom.apply(this, arguments);
      return addPortraitRules(base);
    };
    wrappedBuildFrom.__portrait3x4Wrapped = true;
    window.monoBuildImagePromptFromDescription = wrappedBuildFrom;
  }

  if (typeof window.monoBuildImagePrompt === 'function' && !window.monoBuildImagePrompt.__portrait3x4Wrapped) {
    var oldBuild = window.monoBuildImagePrompt;
    var wrappedBuild = function(p, finalDescription){
      var base = oldBuild.apply(this, arguments);
      return addPortraitRules(base);
    };
    wrappedBuild.__portrait3x4Wrapped = true;
    window.monoBuildImagePrompt = wrappedBuild;
  }

  if (!window.__monoPortrait3x4FetchWrapped && typeof window.fetch === 'function') {
    window.__monoPortrait3x4FetchWrapped = true;
    var oldFetch = window.fetch.bind(window);
    window.fetch = function(input, init){
      try {
        var url = (typeof input === 'string') ? input : (input && input.url ? input.url : '');
        if (/\/images\/generations(?:\?|$)/i.test(url) && init && init.body) {
          var body = typeof init.body === 'string' ? JSON.parse(init.body) : init.body;
          if (body && typeof body === 'object') {
            if (typeof body.prompt === 'string') body.prompt = addPortraitRules(body.prompt);
            // 改成手机竖版 3:4，而不是正方形。
            body.size = '768x1024';
            body.response_format = body.response_format || 'b64_json';
            init = Object.assign({}, init, { body: JSON.stringify(body) });
          }
        }
      } catch(e) {}
      return oldFetch(input, init);
    };
  }

  window.monoPreferredImageSize = '768x1024';
})();


