  var FIELD = 'allowInstagramPostImageGen';
  var running = new Set();

  function txt(v){ return String(v == null ? '' : v); }
  function parse(s, fb){ try { return JSON.parse(s); } catch(e){ return fb; } }
  function getPersonas(){ try { return Array.isArray(window.personas) ? window.personas : (Array.isArray(personas) ? personas : []); } catch(e){ return []; } }
  function sig(p){ return p ? (txt(p.id).trim() || txt(p.name).trim()) : ''; }
  function getPerm(){ return parse(localStorage.getItem(PERM_KEY) || '{}', {}); }
