      var p = findPersona(post.personaId, post.username || post.displayName);
      if (!allowedIg(p)) return;
      var media = card.querySelector('.ins-media, .ins-image-generating-media');
      if (!media) return;
      var status = statusOf(post);
      if (hasRenderedImages(post)) {
        media.outerHTML = imageMedia(post);
      } else if (status === 'error') {
        if (media.classList.contains('ins-media')) media.innerHTML = errorHtml(post);
        else media.outerHTML = errorHtml(post);
      } else {
        if (media.classList.contains('ins-media')) media.innerHTML = loadingHtml();
      }
      var statusBox = card.querySelector('.ins-post-status');
