// ===== mono-ticket-machine-v15-slot-printer-script =====

(function(){
  if(window.__monoTicketMachineV15SlotPrinterFix) return;
  window.__monoTicketMachineV15SlotPrinterFix = true;
  function ensureSlotPrinter(){
    document.querySelectorAll('#ticketMachinePage .tm-typewriter-zone').forEach(function(zone){
      if(!zone) return;
      var shell = zone.querySelector('.tm-printer-slot-shell');
      if(!shell){
        shell = document.createElement('div');
        shell.className = 'tm-printer-slot-shell';
        shell.innerHTML = '<div class="tm-printer-slot"></div>';
        zone.insertBefore(shell, zone.firstChild);
      }
    });
    document.querySelectorAll('#ticketMachinePage .tm-empty-paper').forEach(function(el){
      if(!el || el.dataset.v15Patched==='1') return;
      el.innerHTML = '<div style="font-size:26px;font-weight:1000;letter-spacing:1.6px;margin-bottom:18px;color:#222;">BRANCH TICKET</div><div style="width:100%;border-top:1.5px dashed rgba(0,0,0,.24);margin-bottom:18px"></div><div style="font-size:12px;line-height:1.8;color:#555;">投入钱币后，人生分叉票会从上方缝隙直接打印出来。<br>打印时会出现纸张下拉、轻微弧度与文字逐步印出的效果。</div>';
      el.dataset.v15Patched='1';
    });
  }
  function playPrinterSound(){
    try{
      var Ctx = window.AudioContext || window.webkitAudioContext;
      if(!Ctx) return;
      var ctx = new Ctx();
      var master = ctx.createGain();
      master.gain.value = 0.028;
      master.connect(ctx.destination);
      var now = ctx.currentTime + 0.02;
      function burst(start, dur, amp, freq){
        var buffer = ctx.createBuffer(1, Math.max(1, Math.floor(ctx.sampleRate * dur)), ctx.sampleRate);
        var data = buffer.getChannelData(0);
        for(var i=0;i<data.length;i++) data[i] = (Math.random()*2-1) * (1 - i/data.length);
        var noise = ctx.createBufferSource();
        noise.buffer = buffer;
        var filter = ctx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.frequency.value = freq;
        filter.Q.value = 0.6;
        var gain = ctx.createGain();
        gain.gain.setValueAtTime(amp, start);
        gain.gain.exponentialRampToValueAtTime(0.0001, start + dur);
        noise.connect(filter); filter.connect(gain); gain.connect(master);
        noise.start(start); noise.stop(start + dur);
      }
      for(var n=0;n<10;n++) burst(now + n*0.08, 0.075, 0.8, 1200 + (n%3)*260);
      var osc = ctx.createOscillator();
      var og = ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(88, now);
      osc.frequency.exponentialRampToValueAtTime(56, now + 0.95);
      og.gain.setValueAtTime(0.018, now);
      og.gain.exponentialRampToValueAtTime(0.0001, now + 1.0);
      osc.connect(og); og.connect(master); osc.start(now); osc.stop(now + 1.02);
      setTimeout(function(){ try{ ctx.close(); }catch(e){} }, 1500);
    }catch(e){}
  }
  function patchPrintAction(){
    if(typeof window.tmInsertCoinAndPrint !== 'function' || window.tmInsertCoinAndPrint.__v15Wrapped) return;
    var orig = window.tmInsertCoinAndPrint;
    window.tmInsertCoinAndPrint = function(){
      playPrinterSound();
      ensureSlotPrinter();
      return orig.apply(this, arguments);
    };
    window.tmInsertCoinAndPrint.__v15Wrapped = true;
  }
  document.addEventListener('DOMContentLoaded', function(){ ensureSlotPrinter(); patchPrintAction(); });
  window.addEventListener('load', function(){ ensureSlotPrinter(); patchPrintAction(); }, {passive:true});
  setTimeout(function(){ ensureSlotPrinter(); patchPrintAction(); }, 40);
  setTimeout(function(){ ensureSlotPrinter(); patchPrintAction(); }, 500);
  setInterval(function(){ ensureSlotPrinter(); patchPrintAction(); }, 1200);
})();


