    if(provider) provider.value = s.provider || 'minimax';
    if(key) key.value = s.key || '';
    if(len) len.value = String(s.lengthMs || 30000);
    if(mini) mini.value = s.minimaxModel || 'music-2.6-free';
    if(eleven) eleven.value = s.elevenModel || 'music_v1';
    if(sunoModel) sunoModel.value = s.sunoModel || 'V5_5';
    if(sunoMode) sunoMode.value = s.sunoMode || 'auto';
    if(sunoBase) sunoBase.value = s.sunoBaseUrl || 'https://api.sunoapi.org';
    if(sunoCb) sunoCb.value = s.sunoCallbackUrl || AMS_SUNO_DEFAULT_CALLBACK_URL;
    if(inst) inst.checked = !!s.instrumental;
    amsRefreshProviderHint();
    amsRenderHistory();
