  window.melodyCopyField = async function(kind){ var song=currentSong(); if(!song){ popup('没有内容','请先生成或打开一首歌。'); return; } var text = kind==='style' ? fullStyleForSuno(song) : (song.lyrics||''); if(!text){ popup('没有内容', kind==='style' ? '这首歌还没有曲风描述。' : '这首歌还没有歌词。'); return; } try { await navigator.clipboard.writeText(text); setStatus(kind==='style' ? '曲风和人声设定已复制，可粘贴到 Suno 的 style / 风格。' : '歌词已复制，可粘贴到 Suno 的 lyrics / 歌词。', false); } catch(e){ popup('复制失败','浏览器不允许自动复制，请手动复制。'); } };
