// ===== mono-melody-studio-v40-vinyl-script =====

(function(){
  if(window.__monoMelodyStudioV40Vinyl) return;
  window.__monoMelodyStudioV40Vinyl = true;

  function melodyPageVisible(){
    try{
      var page = document.getElementById('aiMusicStudioPage');
      if(!page) return false;
      var cs = window.getComputedStyle ? getComputedStyle(page) : null;
      if(cs && (cs.display === 'none' || cs.visibility === 'hidden')) return false;
      if(page.offsetParent !== null) return true;
      var rect = page.getBoundingClientRect ? page.getBoundingClientRect() : null;
      return !!(rect && (rect.width > 0 || rect.height > 0));
    }catch(e){ return false; }
  }

  function buildVinyl(){
    var cover = document.getElementById('v38Cover');
    if(!cover) return;

    var existingDisc = cover.querySelector('.v39-vinyl-disc');
    if(existingDisc){
      syncVinylSpin();
      return;
    }

    var img = cover.querySelector('img');
    var fallback = cover.querySelector('.v38-cover-fallback');
    var html = '';

    if(img){
      html =
        '<div class="v39-vinyl-disc">' +
          '<div class="v39-vinyl-art"><img src="' + img.src + '" alt=""></div>' +
          '<div class="v39-vinyl-cap"></div>' +
        '</div>';
    }else{
      var letter = '?';
      if(fallback) letter = fallback.textContent || '?';
      html =
        '<div class="v39-vinyl-disc">' +
          '<div class="v39-vinyl-art"><div class="v39-vinyl-fallback">' + letter + '</div></div>' +
          '<div class="v39-vinyl-cap"></div>' +
        '</div>';
    }

    cover.innerHTML = html;
    syncVinylSpin();
  }

  function syncVinylSpin(){
    var audio = document.getElementById('v38Audio');
    var disc = document.querySelector('#v38Cover .v39-vinyl-disc');
    if(!audio || !disc) return;

    if(audio.src && !audio.paused){
      disc.classList.add('spinning');
    }else{
      disc.classList.remove('spinning');
    }
  }

  function bindAudio(){
    var audio = document.getElementById('v38Audio');
    if(!audio || audio.__v40VinylBound) return;
    audio.__v40VinylBound = true;

    ['play','pause','ended','emptied','loadstart'].forEach(function(evt){
      audio.addEventListener(evt, function(){
        setTimeout(syncVinylSpin, 30);
      });
    });
  }

  function refresh(){
    bindAudio();
    buildVinyl();
    syncVinylSpin();
  }

  document.addEventListener('click', function(){
    setTimeout(refresh, 60);
  }, true);

  document.addEventListener('DOMContentLoaded', function(){
    setTimeout(refresh, 80);
  });

  window.addEventListener('load', function(){
    setTimeout(refresh, 120);
  });

  setInterval(function(){ if(melodyPageVisible()) refresh(); }, 1800);
})();


