      if(window.event && window.event.stopPropagation) window.event.stopPropagation();
      document.querySelectorAll('#aiMusicStudioPage .v38-record-menu.open').forEach(function(menu){
        if(menu.id !== 'menu_' + id) menu.classList.remove('open');
      });
      var el = document.getElementById('menu_' + id);
      if(el) el.classList.toggle('open');
