// ===== mono-melody-studio-v42-cover-upload-script =====

(function(){
  if(window.__monoMelodyStudioV42CoverUpload) return;
  window.__monoMelodyStudioV42CoverUpload = true;

  var LIB_KEY = 'mono_melody_studio_v1';
  var pendingCoverSongId = '';

  function parseJson(raw, fallback){
    try { return raw ? JSON.parse(raw) : fallback; } catch(e){ return fallback; }
  }

  function loadLib(){
    var lib = parseJson(localStorage.getItem(LIB_KEY), { songs:[], currentSongId:'' }) || {};
    if(!Array.isArray(lib.songs)) lib.songs = [];
    return lib;
  }

  function saveLib(lib){
    localStorage.setItem(LIB_KEY, JSON.stringify(lib || { songs:[] }));
  }

  function showMsg(title, msg){
    try {
      if(typeof popup === 'function') return popup(title, msg);
    } catch(e){}
    alert((title || '提示') + '\n' + (msg || ''));
  }

  function ensureCoverInput(){
    var input = document.getElementById('v42SongCoverInput');
    if(input) return input;

    input = document.createElement('input');
    input.id = 'v42SongCoverInput';
    input.type = 'file';
    input.accept = 'image/*';
    input.style.display = 'none';

    input.addEventListener('change', function(){
      var file = input.files && input.files[0];
      input.value = '';
      if(!file) return;

      if(!/^image\//i.test(file.type || '')){
        showMsg('上传失败', '请选择图片文件。');
        return;
      }

      var reader = new FileReader();
      reader.onload = function(){
        var dataUrl = String(reader.result || '');
        var lib = loadLib();
        var id = pendingCoverSongId || lib.currentSongId;
        var target = lib.songs.find(function(song){
          return String(song && song.id) === String(id);
        });

        if(!target){
          showMsg('上传失败', '没有找到这首歌。');
          return;
        }

        target.cover = dataUrl;
        target.updatedAt = Date.now();
        saveLib(lib);

        try {
          if(typeof window.melodyOpenSong === 'function') window.melodyOpenSong(target.id);
          else if(typeof window.melodyRender === 'function') window.melodyRender();
        } catch(e){}

        setTimeout(function(){
          try {
            if(typeof window.melodyRender === 'function') window.melodyRender();
          } catch(e){}
        }, 80);

        showMsg('封面已更新', '这张图片已经覆盖到这首歌的黑胶封面上。');
      };

      reader.onerror = function(){
        showMsg('上传失败', '读取图片时出错。');
      };

      reader.readAsDataURL(file);
    });

    document.body.appendChild(input);
    return input;
  }

  window.melodyChooseCover = function(songId){
    var lib = loadLib();
    pendingCoverSongId = songId || lib.currentSongId || '';
    if(!pendingCoverSongId){
      showMsg('无法上传', '请先选择一首歌曲。');
      return;
    }
    ensureCoverInput().click();
  };

  function addCurrentCoverButton(){
    var row = document.querySelector('#aiMusicStudioPage .v38-copy-row');
    if(!row || document.getElementById('v42CurrentCoverBtn')) return;

    var btn = document.createElement('button');
    btn.id = 'v42CurrentCoverBtn';
    btn.className = 'v42-cover-btn';
    btn.textContent = '上传封面';
    btn.type = 'button';
    btn.onclick = function(){
      window.melodyChooseCover();
    };
    row.appendChild(btn);
  }

  function addRecordCoverButtons(){
    document.querySelectorAll('#aiMusicStudioPage .v38-record-menu').forEach(function(menu){
      if(menu.querySelector('.v42-cover-menu-btn')) return;

      var id = String(menu.id || '').replace(/^menu_/, '');
      var actions = menu.querySelector('.v38-record-actions');
      if(!actions) return;

      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'v42-cover-menu-btn';
      btn.textContent = '上传封面';
      btn.onclick = function(e){
        if(e && e.stopPropagation) e.stopPropagation();
        window.melodyChooseCover(id);
      };

      var deleteBtn = Array.from(actions.querySelectorAll('button')).find(function(b){
        return (b.textContent || '').indexOf('删除') >= 0;
      });

      if(deleteBtn) actions.insertBefore(btn, deleteBtn);
      else actions.appendChild(btn);
    });
  }

  function enhance(){
    ensureCoverInput();
    addCurrentCoverButton();
    addRecordCoverButtons();
  }

  function melodyPageVisible(){
    try{
      var page = document.getElementById('aiMusicStudioPage');
      if(!page) return false;
      var cs = window.getComputedStyle ? getComputedStyle(page) : null;
      if(cs && (cs.display === 'none' || cs.visibility === 'hidden')) return false;
      if(page.offsetParent !== null) return true;
      var rect = page.getBoundingClientRect ? page.getBoundingClientRect() : null;
      return !!(rect && (rect.width > 0 || rect.height > 0));
    }catch(e){ return false; }
  }

  document.addEventListener('DOMContentLoaded', function(){
    setTimeout(enhance, 80);
  });

  window.addEventListener('load', function(){
    setTimeout(enhance, 150);
  }, { passive:true });

  document.addEventListener('click', function(){
    setTimeout(enhance, 80);
  }, true);

  setInterval(function(){ if(melodyPageVisible()) enhance(); }, 2400);
})();


