// ===== mono-melody-studio-v43-full-vinyl-cover-script =====

(function(){
  if(window.__monoMelodyStudioV43FullVinyl) return;
  window.__monoMelodyStudioV43FullVinyl = true;

  function melodyPageVisible(){
    try{
      var page = document.getElementById('aiMusicStudioPage');
      if(!page) return false;
      var cs = window.getComputedStyle ? getComputedStyle(page) : null;
      if(cs && (cs.display === 'none' || cs.visibility === 'hidden')) return false;
      if(page.offsetParent !== null) return true;
      var rect = page.getBoundingClientRect ? page.getBoundingClientRect() : null;
      return !!(rect && (rect.width > 0 || rect.height > 0));
    }catch(e){ return false; }
  }

  function applyFullVinylMode(){
    var cover = document.getElementById('v38Cover');
    if(!cover) return;

    var disc = cover.querySelector('.v39-vinyl-disc');
    if(!disc) return;

    var art = disc.querySelector('.v39-vinyl-art');
    if(!art) return;

    // 如果旧结构里还保留中间小图，就强制让它铺满整张圆盘
    art.style.inset = '0';
    art.style.borderRadius = '50%';

    var img = art.querySelector('img');
    if(img){
      img.style.width = '100%';
      img.style.height = '100%';
      img.style.objectFit = 'cover';
      img.style.borderRadius = '50%';
    }

    var cap = disc.querySelector('.v39-vinyl-cap');
    if(cap) cap.style.display = 'none';
  }

  document.addEventListener('DOMContentLoaded', function(){
    setTimeout(applyFullVinylMode, 100);
  });

  window.addEventListener('load', function(){
    setTimeout(applyFullVinylMode, 150);
  }, { passive:true });

  document.addEventListener('click', function(){
    setTimeout(applyFullVinylMode, 80);
  }, true);

  setInterval(function(){ if(melodyPageVisible()) applyFullVinylMode(); }, 1800);
})();


