// ===== mono-melody-studio-v45-home-icon-script =====

(function(){
  if(window.__monoMelodyStudioV45HomeIcon) return;
  window.__monoMelodyStudioV45HomeIcon = true;

  var ICON_KEY = 'aiMusicStudio';
  var DRAG_ID = 'app-ai-music-studio';
  var POS_KEY = 'mono_iph_positions_v3';

  var DEFAULT_SVG =
    "<svg viewBox='0 0 52 52' xmlns='http://www.w3.org/2000/svg' style='width:38px;height:38px;'>" +
      "<path d='M19 35.5V16.5L36 13.5V31.5' fill='none' stroke='#555' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'/>" +
      "<circle cx='18' cy='36' r='4.8' fill='none' stroke='#555' stroke-width='3'/>" +
      "<circle cx='35' cy='32' r='4.8' fill='none' stroke='#555' stroke-width='3'/>" +
      "<path d='M19 21L36 18' stroke='#555' stroke-width='2.1' stroke-linecap='round'/>" +
    "</svg>";

  function parse(raw, fallback){
    try { return raw ? JSON.parse(raw) : fallback; } catch(e){ return fallback; }
  }

  function savePositions(pos){
    try { localStorage.setItem(POS_KEY, JSON.stringify(pos || {})); } catch(e){}
  }

  function getPositions(){
    return parse(localStorage.getItem(POS_KEY), {}) || {};
  }

  function num(v, fallback){
    v = Number(v);
    return Number.isFinite(v) ? v : fallback;
  }

  function buildDefaultPos(pos){
    var dr = pos['app-dressing-room'] || {};
    var ins = pos['app-instagram'] || {};
    var pageId = 'homePage3';

    var drX = num(dr.x, 180);
    var drY = num(dr.y, 128);
    var insX = num(ins.x, 96);
    var insY = num(ins.y, 208);

    return {
      parentId: String(ins.parentId || dr.parentId || pageId),
      // 换装室下方 + Instagram 正右方：默认第三页第二排第三个位置
      x: Number.isFinite(Number(dr.x)) ? drX : (insX + 84),
      y: Number.isFinite(Number(ins.y)) ? insY : (drY + 80)
    };
  }

  function isOldOrInvalidSaved(saved){
    if(!saved || typeof saved !== 'object') return true;
    var x = Number(saved.x), y = Number(saved.y);
    if(!Number.isFinite(x) || !Number.isFinite(y)) return true;
    // 旧版旋律工房曾经被放到很靠下的位置；没有用户移动过时自动迁移到新预设位置。
    if(String(saved.parentId || 'homePage3') === 'homePage3' && Math.abs(x - 246) <= 3 && Math.abs(y - 468) <= 3) return true;
    return false;
  }

  function refreshIcon(){
    var box = document.getElementById('aiMusicStudioHomeIconBox');
    if(!box) return;
    var custom = '';
    try { custom = localStorage.getItem('mono_icon_' + ICON_KEY) || ''; } catch(e){}
    if(custom){
      box.innerHTML = '<img class="custom-icon" src="' + String(custom).replace(/"/g,'&quot;') + '">';
    }else{
      box.innerHTML = DEFAULT_SVG;
    }
  }

  function ensureElement(){
    var el = document.getElementById(DRAG_ID);
    var page3 = document.getElementById('homePage3');
    if(!el){
      el = document.createElement('div');
      el.id = DRAG_ID;
      el.className = 'ig-music-icon-wrap ai-music-studio-home-entry iph-placed';
      el.dataset.dragId = DRAG_ID;
      el.setAttribute('data-drag-id', DRAG_ID);
      el.setAttribute('onclick','openAiMusicStudioApp()');

      var box = document.createElement('div');
      box.className = 'ig-music-icon-box';
      box.id = 'aiMusicStudioHomeIconBox';
      el.appendChild(box);

      var label = document.createElement('div');
      label.className = 'ig-music-icon-label';
      label.textContent = '旋律工坊';
      el.appendChild(label);

      if(page3) page3.appendChild(el);
    }else{
      el.classList.add('ig-music-icon-wrap','ai-music-studio-home-entry','iph-placed');
      el.dataset.dragId = DRAG_ID;
      el.setAttribute('data-drag-id', DRAG_ID);
      el.setAttribute('onclick','openAiMusicStudioApp()');

      if(!document.getElementById('aiMusicStudioHomeIconBox')){
        var b = document.createElement('div');
        b.className = 'ig-music-icon-box';
        b.id = 'aiMusicStudioHomeIconBox';
        el.insertBefore(b, el.firstChild);
      }

      var labelEl = el.querySelector('.ig-music-icon-label');
      if(!labelEl){
        labelEl = document.createElement('div');
        labelEl.className = 'ig-music-icon-label';
        el.appendChild(labelEl);
      }
      labelEl.textContent = '旋律工房';
    }

    el.style.display = 'flex';
    el.style.visibility = 'visible';
    el.style.opacity = '1';

    refreshIcon();
    return el;
  }

  function placeIcon(){
    var el = ensureElement();
    if(!el) return;

    var pos = getPositions();
    var def = buildDefaultPos(pos);
    var saved = pos[DRAG_ID];

    if(isOldOrInvalidSaved(saved)){
      saved = def;
      pos[DRAG_ID] = saved;
      savePositions(pos);
    }

    var parent = document.getElementById(saved.parentId || def.parentId || 'homePage3');
    if(parent && el.parentElement !== parent) parent.appendChild(el);

    el.classList.add('iph-placed');
    el.style.left = num(saved.x, def.x) + 'px';
    el.style.top = num(saved.y, def.y) + 'px';
    el.style.margin = '0';
    el.style.flexShrink = '0';
  }

  function ensureConfig(){
    try{
      var cfg = null;
      try { if(Array.isArray(APP_ICONS_CONFIG)) cfg = APP_ICONS_CONFIG; } catch(e){}
      if(!cfg && Array.isArray(window.APP_ICONS_CONFIG)) cfg = window.APP_ICONS_CONFIG;
      if(cfg && !cfg.some(function(x){ return x && x.key === ICON_KEY; })){
        cfg.push({ key:ICON_KEY, label:'旋律工房', icon:'fa-music', type:'page3', defaultSvg:DEFAULT_SVG });
      }
      if(cfg){
        cfg.forEach(function(item){
          if(item && item.key === ICON_KEY){
            item.label = '旋律工房';
            item.type = 'page3';
            item.defaultSvg = DEFAULT_SVG;
          }
        });
      }
      if(typeof renderIconCustomizeGrid === 'function') renderIconCustomizeGrid();
    }catch(e){}
  }

  function patchCustomIcon(){
    try{
      var orig = window.applyCustomIcon;
      if(typeof orig === 'function' && !orig.__melodyV45Patched){
        window.applyCustomIcon = function(appKey, imgData){
          if(appKey === ICON_KEY){
            try { localStorage.setItem('mono_icon_' + ICON_KEY, String(imgData || '')); } catch(e){}
            refreshIcon();
            return;
          }
          return orig.apply(this, arguments);
        };
        window.applyCustomIcon.__melodyV45Patched = true;
      }
    }catch(e){}
  }

  function patchResetIcons(){
    try{
      var orig = window.resetAllIcons;
      if(typeof orig === 'function' && !orig.__melodyV45Patched){
        window.resetAllIcons = function(){
          var ret = orig.apply(this, arguments);
          try { localStorage.removeItem('mono_icon_' + ICON_KEY); } catch(e){}
          refreshIcon();
          return ret;
        };
        window.resetAllIcons.__melodyV45Patched = true;
      }
    }catch(e){}
  }

  function run(){
    ensureConfig();
    patchCustomIcon();
    patchResetIcons();
    placeIcon();
  }

  window.renderAiMusicStudioHomeIcon = run;
  window.melodyStudioPlaceHomeIcon = placeIcon;

  document.addEventListener('DOMContentLoaded', run);
  window.addEventListener('load', run, {passive:true});
  setTimeout(run, 0);
  setTimeout(run, 400);
  setTimeout(run, 1200);
  setInterval(function(){
    try { placeIcon(); } catch(e){}
  }, 2800);
})();


