// ===== mono-melody-studio-runtime-bundle =====

(function(){
  if(window.__monoMelodyStudioV46NoFlash) return;
  window.__monoMelodyStudioV46NoFlash = true;

  var ICON_KEY = 'aiMusicStudio';
  var DEFAULT_SVG =
    "<svg viewBox='0 0 52 52' xmlns='http://www.w3.org/2000/svg' style='width:38px;height:38px;'>" +
      "<path d='M19 35.5V16.5L36 13.5V31.5' fill='none' stroke='#555' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'/>" +
      "<circle cx='18' cy='36' r='4.8' fill='none' stroke='#555' stroke-width='3'/>" +
      "<circle cx='35' cy='32' r='4.8' fill='none' stroke='#555' stroke-width='3'/>" +
      "<path d='M19 21L36 18' stroke='#555' stroke-width='2.1' stroke-linecap='round'/>" +
    "</svg>";

  function stableIconHTML(){
    var custom = '';
    try { custom = localStorage.getItem('mono_icon_' + ICON_KEY) || ''; } catch(e){}
    return custom
      ? '<img class="custom-icon" src="' + String(custom).replace(/"/g,'&quot;') + '" style="width:100%;height:100%;object-fit:cover;border-radius:16px;display:block;">'
      : DEFAULT_SVG;
  }

  function normalizeIcon(){
    var el = document.getElementById('app-ai-music-studio');
    var box = document.getElementById('aiMusicStudioHomeIconBox');
    if(!el || !box) return;

    el.classList.add('ig-music-icon-wrap','ai-music-studio-home-entry','iph-placed');
    el.dataset.dragId = 'app-ai-music-studio';
    el.setAttribute('data-drag-id','app-ai-music-studio');
    el.setAttribute('onclick','openAiMusicStudioApp()');
    el.style.display = 'flex';
    el.style.visibility = 'visible';
    el.style.opacity = '1';

    var html = stableIconHTML();
    if(box.innerHTML !== html) box.innerHTML = html;

    var label = el.querySelector('.ig-music-icon-label');
    if(label) label.textContent = '旋律工坊';
  }

  // 拦截旧脚本/自定义图标刷新后，把图标稳定回同一个版本。
  var observer = null;
  function watch(){
    var box = document.getElementById('aiMusicStudioHomeIconBox');
    if(!box || observer) return;
    observer = new MutationObserver(function(){
      clearTimeout(window.__melodyV46IconFixTimer);
      window.__melodyV46IconFixTimer = setTimeout(normalizeIcon, 20);
    });
    observer.observe(box, { childList:true, subtree:true, attributes:true });
  }

  function tick(){
    normalizeIcon();
    watch();
  }

  document.addEventListener('DOMContentLoaded', tick);
  window.addEventListener('load', tick, {passive:true});
  document.addEventListener('click', function(){ setTimeout(tick, 60); }, true);
  setTimeout(tick, 0);
  setTimeout(tick, 300);
  setTimeout(tick, 900);
  setInterval(tick, 1800);
})();

/* ===== mono-melody-studio-v47-non-json-fallback-script ===== */
(function(){
  if(window.__monoMelodyStudioV47NonJsonFallback) return;
  window.__monoMelodyStudioV47NonJsonFallback = true;

  function pickLabel(text, patterns){
    text = String(text || '');
    for(var i=0;i<patterns.length;i++){
      var re = patterns[i];
      var m = text.match(re);
      if(m && m[1]) return String(m[1]).trim().replace(/^["“”'‘’]+|["“”'‘’]+$/g,'');
    }
    return '';
  }

  function stripCodeFence(text){
    return String(text || '')
      .replace(/^```(?:json|JSON|text|lyrics)?\s*/,'')
      .replace(/```\s*$/,'')
      .trim();
  }

  function stripJsonLookingNoise(text){
    text = stripCodeFence(text);
    // 如果模型返回了类似 JSON 但解析失败，尽量把 JSON 键名去掉，留下可读歌词
    return text
      .replace(/^\s*[\{\[]\s*/,'')
      .replace(/\s*[\}\]]\s*$/,'')
      .replace(/"?(title|songTitle|歌名|topic|concept|stylePrompt|melodyDescription|arrangement|moodTags|language)"?\s*[:：]\s*/gi, function(all, key){
        if(/lyrics|歌词/i.test(key)) return '';
        return '\n';
      })
      .replace(/^[\s",]+|[\s",]+$/g,'')
      .trim();
  }

  function cleanLyricsFromText(text){
    text = stripCodeFence(text);
    var lines = text.split(/\r?\n/).map(function(line){ return line.trim(); });
    var keep = [];
    var inLyrics = false;
    lines.forEach(function(line){
      if(!line) { if(keep.length) keep.push(''); return; }
      if(/^(lyrics|歌词|歌詞)\s*[:：]/i.test(line)){
        inLyrics = true;
        var rest = line.replace(/^(lyrics|歌词|歌詞)\s*[:：]\s*/i,'').trim();
        if(rest) keep.push(rest);
        return;
      }
      if(/^(title|歌名|topic|主题|主題|concept|概念|style|stylePrompt|曲风|曲风|风格|风格|melody|旋律|arrangement|编曲|编曲|moodTags|language)\s*[:：]/i.test(line)){
        if(inLyrics) inLyrics = false;
        return;
      }
      if(/^\s*[\[\(（]?(verse|chorus|bridge|outro|intro|hook|pre chorus|post chorus|interlude|solo|build up|break|主歌|副歌|桥段|橋段|前奏|尾奏)[\]\)）]?/i.test(line)){
        inLyrics = true;
        keep.push(line);
        return;
      }
      if(inLyrics || keep.length){
        keep.push(line);
      }
    });
    var lyrics = keep.join('\n').replace(/\n{3,}/g,'\n\n').trim();
    if(!lyrics || lyrics.length < 20) lyrics = stripJsonLookingNoise(text);
    return lyrics;
  }

  function firstLyricLine(lyrics){
    var line = String(lyrics || '').split(/\r?\n/).map(function(x){ return x.trim(); }).find(function(x){
      return x && !/^\[.*\]$/.test(x) && !/^(verse|chorus|bridge|intro|outro|hook)/i.test(x);
    });
    return line || '';
  }

  window.melodyCompleteSongObject = function(obj, rawText, persona, language, requirements){
    rawText = stripCodeFence(rawText || '');
    var base = (obj && typeof obj === 'object') ? Object.assign({}, obj) : {};

    var title = base.title || base.songTitle || base.name || pickLabel(rawText, [
      /(?:title|songTitle|歌名|歌曲名)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var style = base.stylePrompt || base.style || base.musicStyle || base.genre || pickLabel(rawText, [
      /(?:stylePrompt|style|music style|genre|曲风|曲风|风格|风格)\s*[:：]\s*([^\n\r]+)/i,
      /(?:旋律|melody|melodyDescription)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var melody = base.melodyDescription || base.melody || pickLabel(rawText, [
      /(?:melodyDescription|melody|旋律描述|旋律)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var arrangement = base.arrangement || base.production || pickLabel(rawText, [
      /(?:arrangement|production|编曲|编曲)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var topic = base.topic || base.theme || pickLabel(rawText, [
      /(?:topic|theme|主题|主題)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var concept = base.concept || base.description || pickLabel(rawText, [
      /(?:concept|概念|歌曲概念)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var lyrics = base.lyrics || base.lyric || base.songLyrics || base.words || '';
    if(Array.isArray(lyrics)) lyrics = lyrics.join('\n');
    lyrics = String(lyrics || '').trim();
    if(!lyrics) lyrics = cleanLyricsFromText(rawText);

    if(!title){
      var first = firstLyricLine(lyrics);
      title = first ? first.slice(0,28) : ((persona && persona.name ? persona.name : '角色') + ' 的新歌');
    }

    if(!style){
      style = (requirements ? requirements + '，' : '') + 'emotional indie pop, clean vocal, cinematic but intimate, suitable for Suno style prompt';
    }
    if(!melody){
      melody = '旋律以清晰主歌和可记忆副歌推进，副歌有重复 hook，行尾带押韵或近似押韵；歌词有文艺意象和留白，情绪从克制到释放，适合粘贴到 Suno 的 style / 风格框。';
    }
    if(!arrangement){
      arrangement = '简洁鼓组、柔和 bass、空气感 synth 或吉他层次，副歌稍微打开空间。';
    }
    if(!topic) topic = concept || title;
    if(!concept) concept = topic || (requirements || title);

    var tags = base.moodTags || base.tags || [];
    if(typeof tags === 'string') tags = tags.split(/[,，、|]/).map(function(x){ return x.trim(); }).filter(Boolean);
    if(!Array.isArray(tags) || !tags.length) tags = ['角色创作','可复制到Suno','旋律工房'];

    return {
      title:String(title || '').trim(),
      topic:String(topic || '').trim(),
      concept:String(concept || '').trim(),
      language:base.language || language || '',
      lyrics:String(lyrics || '').trim(),
      stylePrompt:String(style || '').trim(),
      melodyDescription:String(melody || '').trim(),
      arrangement:String(arrangement || '').trim(),
      moodTags:tags
    };
  };
})();

/* ===== mono-melody-studio-v48-object-object-fix-script ===== */
(function(){
  if(window.__monoMelodyStudioV48ObjectFix) return;
  window.__monoMelodyStudioV48ObjectFix = true;

  function isPlainObject(v){
    return v && typeof v === 'object' && !Array.isArray(v);
  }

  function cleanText(s){
    return String(s == null ? '' : s)
      .replace(/\[object Object\]/g, '')
      .replace(/\[object Promise\]/g, '')
      .replace(/\s+\n/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
  }

  function textFrom(value, preferredKeys){
    if(value == null) return '';
    if(typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return cleanText(value);

    if(Array.isArray(value)){
      return cleanText(value.map(function(item){
        return textFrom(item, preferredKeys);
      }).filter(Boolean).join('\n'));
    }

    if(isPlainObject(value)){
      preferredKeys = preferredKeys || [];

      for(var i=0;i<preferredKeys.length;i++){
        var k = preferredKeys[i];
        if(value[k] != null){
          var found = textFrom(value[k], preferredKeys);
          if(found) return found;
        }
      }

      // 常见歌词结构：{ sections:[{type:"Verse", lines:[...]}] }
      if(Array.isArray(value.sections)){
        return cleanText(value.sections.map(function(sec){
          if(!sec) return '';
          var label = textFrom(sec.type || sec.name || sec.title || sec.label, []);
          var body = textFrom(sec.lines || sec.text || sec.content || sec.lyrics, preferredKeys);
          return (label ? '[' + label + ']\n' : '') + body;
        }).filter(Boolean).join('\n\n'));
      }

      // 常见分段对象：{ verse:"...", chorus:"..." }
      var sectionKeys = ['intro','verse','preChorus','pre_chorus','chorus','hook','bridge','outro','主歌','副歌','桥段','橋段','前奏','尾奏'];
      var parts = [];
      sectionKeys.forEach(function(k){
        if(value[k] != null){
          var body = textFrom(value[k], preferredKeys);
          if(body) parts.push('[' + k + ']\n' + body);
        }
      });
      if(parts.length) return cleanText(parts.join('\n\n'));

      // 最后兜底：把对象里的可读字段逐条展开，绝不让它变成 [object Object]
      var out = [];
      Object.keys(value).forEach(function(k){
        if(k === 'id' || k === 'raw' || k === 'trace_id') return;
        var v = textFrom(value[k], preferredKeys);
        if(v) out.push(v);
      });
      return cleanText(out.join('\n'));
    }

    return '';
  }

  function pickLabel(text, patterns){
    text = String(text || '');
    for(var i=0;i<patterns.length;i++){
      var m = text.match(patterns[i]);
      if(m && m[1]) return cleanText(m[1]).replace(/^["“”'‘’]+|["“”'‘’]+$/g,'');
    }
    return '';
  }

  function stripCodeFence(text){
    return String(text || '')
      .replace(/^```(?:json|JSON|text|lyrics)?\s*/,'')
      .replace(/```\s*$/,'')
      .trim();
  }

  function cleanLyricsFromText(text){
    text = stripCodeFence(text);
    var lines = text.split(/\r?\n/).map(function(line){ return line.trim(); });
    var keep = [];
    var inLyrics = false;

    lines.forEach(function(line){
      if(!line){ if(keep.length) keep.push(''); return; }

      if(/^(lyrics|lyric|歌词|歌詞)\s*[:：]/i.test(line)){
        inLyrics = true;
        var rest = line.replace(/^(lyrics|lyric|歌词|歌詞)\s*[:：]\s*/i,'').trim();
        if(rest) keep.push(rest);
        return;
      }

      if(/^(title|歌名|topic|主题|主題|concept|概念|style|stylePrompt|曲风|曲风|风格|风格|melody|旋律|arrangement|编曲|编曲|moodTags|language)\s*[:：]/i.test(line)){
        if(inLyrics) inLyrics = false;
        return;
      }

      if(/^\s*[\[\(（]?(verse|chorus|bridge|outro|intro|hook|pre chorus|post chorus|interlude|solo|build up|break|主歌|副歌|桥段|橋段|前奏|尾奏)[\]\)）]?/i.test(line)){
        inLyrics = true;
        keep.push(line);
        return;
      }

      if(inLyrics || keep.length) keep.push(line);
    });

    var lyrics = cleanText(keep.join('\n'));
    if(!lyrics || lyrics.length < 20) lyrics = cleanText(text);
    return lyrics;
  }

  function firstLyricLine(lyrics){
    return String(lyrics || '').split(/\r?\n/).map(function(x){ return x.trim(); }).find(function(x){
      return x && !/^\[.*\]$/.test(x) && !/^(verse|chorus|bridge|intro|outro|hook|主歌|副歌)/i.test(x);
    }) || '';
  }

  window.melodyCompleteSongObject = function(obj, rawText, persona, language, requirements){
    rawText = stripCodeFence(rawText || '');
    var base = isPlainObject(obj) ? obj : {};

    // 有些模型会包在 song/data/result/content 里面
    if(isPlainObject(base.song)) base = base.song;
    else if(isPlainObject(base.data)) base = base.data;
    else if(isPlainObject(base.result)) base = base.result;
    else if(isPlainObject(base.content)) base = base.content;

    var title = textFrom(base.title || base.songTitle || base.name || base.歌名 || base['歌曲名'], ['text','content','value','name','title']);
    if(!title) title = pickLabel(rawText, [/(?:title|songTitle|歌名|歌曲名)\s*[:：]\s*([^\n\r]+)/i]);

    var lyrics = textFrom(base.lyrics || base.lyric || base.songLyrics || base.words || base.sections || base.歌词 || base['歌詞'], [
      'lyrics','lyric','songLyrics','text','content','lines','sections','words','value'
    ]);
    if(!lyrics) lyrics = cleanLyricsFromText(rawText);

    var style = textFrom(base.stylePrompt || base.style || base.musicStyle || base.genre || base.曲风 || base['曲风'] || base['风格'] || base['风格'], [
      'stylePrompt','style','musicStyle','genre','description','text','content','value'
    ]);
    if(!style) style = pickLabel(rawText, [
      /(?:stylePrompt|style|music style|genre|曲风|曲风|风格|风格)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var melody = textFrom(base.melodyDescription || base.melody || base.旋律 || base['旋律描述'], [
      'melodyDescription','melody','description','text','content','value'
    ]);
    if(!melody) melody = pickLabel(rawText, [
      /(?:melodyDescription|melody|旋律描述|旋律)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var arrangement = textFrom(base.arrangement || base.production || base.instrumentation || base.编曲 || base['编曲'], [
      'arrangement','production','instrumentation','description','text','content','value'
    ]);
    if(!arrangement) arrangement = pickLabel(rawText, [
      /(?:arrangement|production|instrumentation|编曲|编曲)\s*[:：]\s*([^\n\r]+)/i
    ]);

    var topic = textFrom(base.topic || base.theme || base.主题 || base['主題'], ['topic','theme','text','content','value']);
    if(!topic) topic = pickLabel(rawText, [/(?:topic|theme|主题|主題)\s*[:：]\s*([^\n\r]+)/i]);

    var concept = textFrom(base.concept || base.description || base.summary || base.概念 || base['歌曲概念'], [
      'concept','description','summary','text','content','value'
    ]);
    if(!concept) concept = pickLabel(rawText, [/(?:concept|概念|歌曲概念|summary|description)\s*[:：]\s*([^\n\r]+)/i]);

    if(!title){
      var first = firstLyricLine(lyrics);
      title = first ? first.slice(0,28) : ((persona && persona.name ? persona.name : '角色') + ' 的新歌');
    }

    if(!style){
      style = (requirements ? requirements + '，' : '') + 'Korean clean indie pop, poetic lyrics, soft vocal, cinematic but minimal, delicate imagery, clear chorus, suitable for Suno style prompt';
    }
    if(!melody){
      melody = '旋律以清晰主歌和可记忆副歌推进，副歌有重复 hook，行尾带押韵或近似押韵；歌词有文艺意象和留白，情绪从克制到释放，适合粘贴到 Suno 的 style / 风格框。';
    }
    if(!arrangement){
      arrangement = '简洁鼓组、柔和 bass、空气感 synth 或吉他层次，副歌稍微打开空间。';
    }
    if(!topic) topic = concept || title;
    if(!concept) concept = topic || (requirements || title);

    var tags = base.moodTags || base.tags || base.moods || [];
    if(typeof tags === 'string') tags = tags.split(/[,，、|]/).map(function(x){ return cleanText(x); }).filter(Boolean);
    if(Array.isArray(tags)){
      tags = tags.map(function(x){ return textFrom(x, ['name','label','text','value']); }).filter(Boolean);
    }
    if(!Array.isArray(tags) || !tags.length) tags = ['角色创作','Suno风格','旋律工房'];

    return {
      title:cleanText(title),
      topic:cleanText(topic),
      concept:cleanText(concept),
      language:cleanText(textFrom(base.language || language || '', ['name','value','text'])),
      lyrics:cleanText(lyrics),
      stylePrompt:cleanText(style),
      melodyDescription:cleanText(melody),
      arrangement:cleanText(arrangement),
      moodTags:tags
    };
  };
})();

/* ===== mono-melody-studio-v51-format-fix-script ===== */
(function(){
  if(window.__monoMelodyStudioV51FormatFix) return;
  window.__monoMelodyStudioV51FormatFix = true;

  function isPlainObject(v){
    return v && typeof v === 'object' && !Array.isArray(v);
  }

  function stripFence(s){
    return String(s || '')
      .replace(/^```(?:json|JSON|text)?\s*/,'')
      .replace(/```\s*$/,'')
      .trim();
  }

  function decodeEscapes(str){
    str = String(str == null ? '' : str);
    // 如果本身就是 JSON string 的表现形式，优先用 JSON.parse 解码
    if (/^"(?:[\s\S]*)"$/.test(str.trim())) {
      try { return JSON.parse(str.trim()); } catch(e) {}
    }
    return str
      .replace(/\\r\\n/g, '\n')
      .replace(/\\n/g, '\n')
      .replace(/\\t/g, '\t')
      .replace(/\\"/g, '"')
      .replace(/\\'/g, "'")
      .replace(/\\\\/g, '\\');
  }

  function cleanLineText(str){
    str = decodeEscapes(stripFence(str || ''));
    return String(str || '')
      .replace(/\uFEFF/g,'')
      .replace(/\r\n/g,'\n')
      .replace(/\r/g,'\n')
      .replace(/\n{3,}/g,'\n\n')
      .trim();
  }

  function maybeParseJsonString(str){
    str = cleanLineText(str);
    if(!str) return null;
    if (!/^\s*[\{\[]/.test(str)) return null;
    try { return JSON.parse(str); } catch(e) {}
    // 尝试修掉一些常见问题
    try {
      var fixed = str
        .replace(/,\s*([\}\]])/g, '$1');
      return JSON.parse(fixed);
    } catch(e2) {}
    return null;
  }

  function extractLyricsFromJsonLikeString(str){
    str = stripFence(String(str || ''));
    if(!str) return '';
    // 优先完整 JSON parse
    var parsed = maybeParseJsonString(str);
    if(parsed){
      return extractLyricsFromAnything(parsed);
    }
    // 退化到正则抓取 "lyrics":"..."
    var m = str.match(/"lyrics"\s*:\s*"([\s\S]*?)"\s*(?:,\s*"|,\s*$|\}\s*$)/i);
    if(m && m[1]){
      return cleanLineText(m[1]);
    }
    return '';
  }

  function extractLyricsFromAnything(value){
    if(value == null) return '';
    if(typeof value === 'string'){
      var s = cleanLineText(value);
      if(/^\s*[\{\[]/.test(s) && /"lyrics"\s*:/.test(s)) {
        var nested = extractLyricsFromJsonLikeString(s);
        if(nested) return nested;
      }
      return s;
    }
    if(Array.isArray(value)){
      return value.map(extractLyricsFromAnything).filter(Boolean).join('\n');
    }
    if(isPlainObject(value)){
      if(value.lyrics != null) return extractLyricsFromAnything(value.lyrics);
      if(value.songLyrics != null) return extractLyricsFromAnything(value.songLyrics);
      if(value.words != null) return extractLyricsFromAnything(value.words);
      if(Array.isArray(value.sections)){
        return value.sections.map(function(sec){
          if(!sec) return '';
          var label = cleanLineText(sec.type || sec.name || sec.title || '');
          var body = extractLyricsFromAnything(sec.lines || sec.text || sec.content || sec.lyrics || '');
          return (label ? '[' + label + ']\n' : '') + body;
        }).filter(Boolean).join('\n\n');
      }
      var keys = ['intro','verse','preChorus','pre_chorus','chorus','hook','bridge','outro','主歌','副歌','桥段','橋段','前奏','尾奏'];
      var parts = [];
      keys.forEach(function(k){
        if(value[k] != null){
          var body = extractLyricsFromAnything(value[k]);
          if(body) parts.push('[' + k + ']\n' + body);
        }
      });
      if(parts.length) return parts.join('\n\n');
    }
    return '';
  }

  function normalizeSong(song, rawText){
    if(!song || typeof song !== 'object') song = {};
    rawText = cleanLineText(rawText || '');

    // 如果整个 song 或某个字段其实是 JSON 字符串，先展开
    ['title','topic','concept','lyrics','stylePrompt','melodyDescription','arrangement'].forEach(function(k){
      if(typeof song[k] === 'string'){
        var nested = maybeParseJsonString(song[k]);
        if(nested && isPlainObject(nested)){
          song = Object.assign({}, nested, song);
          if(k === 'lyrics' && nested.lyrics != null) song.lyrics = nested.lyrics;
        }
      }
    });

    // 如果 lyrics 明显还是一整个 JSON，重新抽真正歌词
    var lyrics = extractLyricsFromAnything(song.lyrics);
    if((!lyrics || /"title"\s*:|"topic"\s*:|"concept"\s*:/.test(lyrics)) && rawText){
      var nestedLyrics = extractLyricsFromJsonLikeString(rawText);
      if(nestedLyrics) lyrics = nestedLyrics;
    }
    song.lyrics = cleanLineText(lyrics);

    function normalizeField(v){
      if(v == null) return '';
      if(typeof v === 'string'){
        var nested = maybeParseJsonString(v);
        if(nested && isPlainObject(nested)){
          return cleanLineText(
            nested.text || nested.content || nested.value || nested.name || nested.title || ''
          );
        }
        return cleanLineText(v)
          .replace(/^\s*"+|"+\s*$/g,'')
          .replace(/^\s*'+|'+\s*$/g,'')
          .trim();
      }
      if(typeof v === 'number' || typeof v === 'boolean') return String(v);
      if(Array.isArray(v)) return v.map(normalizeField).filter(Boolean).join(', ');
      if(isPlainObject(v)){
        return cleanLineText(
          v.text || v.content || v.value || v.name || v.title || ''
        );
      }
      return '';
    }

    song.title = normalizeField(song.title || song.songTitle || '');
    song.topic = normalizeField(song.topic || song.theme || '');
    song.concept = normalizeField(song.concept || song.description || '');
    song.stylePrompt = normalizeField(song.stylePrompt || song.style || song.genre || '');
    song.melodyDescription = normalizeField(song.melodyDescription || song.melody || '');
    song.arrangement = normalizeField(song.arrangement || song.production || '');

    if(!song.lyrics && rawText){
      song.lyrics = cleanLineText(rawText);
    }

    // 最终保险：如果歌词里还混着 JSON 键，最后再清理一次
    if(/"title"\s*:|"topic"\s*:|"concept"\s*:|"language"\s*:/.test(song.lyrics)){
      var finalLyrics = extractLyricsFromJsonLikeString(song.lyrics);
      if(finalLyrics) song.lyrics = cleanLineText(finalLyrics);
    }

    return song;
  }

  // 包一层旧的 melodyCompleteSongObject
  if(typeof window.melodyCompleteSongObject === 'function' && !window.melodyCompleteSongObject.__v51Wrapped){
    var oldComplete = window.melodyCompleteSongObject;
    window.melodyCompleteSongObject = function(obj, rawText, persona, language, requirements){
      var result = oldComplete(obj, rawText, persona, language, requirements);
      return normalizeSong(result, rawText);
    };
    window.melodyCompleteSongObject.__v51Wrapped = true;
  }

  // 渲染歌词前再做一次格式修复
  function patchRender(){
    var oldRender = window.renderPlayer;
    if(typeof oldRender === 'function' && !oldRender.__v51Wrapped){
      window.renderPlayer = function(song){
        if(song && typeof song === 'object'){
          song = normalizeSong(song, song.lyrics || '');
        }
        return oldRender.call(this, song);
      };
      window.renderPlayer.__v51Wrapped = true;
    }
  }

  document.addEventListener('DOMContentLoaded', function(){ setTimeout(patchRender, 50); });
  window.addEventListener('load', function(){ setTimeout(patchRender, 120); }, {passive:true});
  setTimeout(patchRender, 300);
})();


;
// ===== mono-melody-studio-v52-no-truncate-script =====

(function(){
  if(window.__monoMelodyStudioV52NoTruncate) return;
  window.__monoMelodyStudioV52NoTruncate = true;

  function looksTruncated(text){
    text = String(text || '').trim();
    if(!text) return false;
    if(/[.…]\s*$/.test(text)) return true;
    if(/(后续略|未完待续|to be continued|continued|省略|以下省略)/i.test(text)) return true;
    return false;
  }

  function warnIfTruncated(){
    try{
      var lyrics = document.getElementById('v38Lyrics');
      var status = document.getElementById('v38Status');
      if(!lyrics || !status) return;
      var text = lyrics.textContent || '';
      if(looksTruncated(text)){
        status.textContent = '这次接口返回内容像是被截断了。请点“重新生成”，新版已提高输出长度限制。';
        status.classList.add('error');
      }
    }catch(e){}
  }

  document.addEventListener('click', function(){ setTimeout(warnIfTruncated, 300); }, true);
  window.addEventListener('load', function(){ setTimeout(warnIfTruncated, 600); }, {passive:true});
})();


