  function escapeTheaterSimplifyObject(value){
    if(typeof value === 'string') return escapeTheaterToSimplifiedText(value);
    if(Array.isArray(value)) return value.map(escapeTheaterSimplifyObject);
    if(value && typeof value === 'object'){
      Object.keys(value).forEach(function(k){ value[k] = escapeTheaterSimplifyObject(value[k]); });
    }
    return value;
  }
  function normalizeGame(obj, opts){
    obj = obj && typeof obj === 'object' ? obj : {};
    var game = {
      id: uid('game'),
      createdAt: Date.now(),
      updatedAt: Date.now(),
      mode: opts.mode || 'single',
      selectedPersonaIds: opts.personaIds || [],
      setting: opts.setting || {},
      title: String(obj.title||'').trim(),
      logline: String(obj.logline||'').trim(),
      storyBackground: String(obj.storyBackground||'').trim(),
      entryIncident: String(obj.entryIncident||'').trim(),
      openingHook: String(obj.openingHook||'').trim(),
      userIdentity: String(obj.userIdentity||'').trim(),
      characterIdentities: normalizeArray(obj.characterIdentities),
      room: String(obj.room||'').trim(),
      atmosphere: String(obj.atmosphere||'').trim(),
      difficulty: String(obj.difficulty||opts.setting.difficulty||'').trim(),
      truthPlan: obj.truthPlan && typeof obj.truthPlan === 'object' ? obj.truthPlan : {},
      progressionPlan: obj.progressionPlan && typeof obj.progressionPlan === 'object' ? obj.progressionPlan : {},
      currentStage: Math.max(1, parseInt(obj.currentStage || 1, 10) || 1),
      maxStage: Math.max(4, parseInt(obj.maxStage || 6, 10) || 6),
      escapeProgress: Math.max(0, Math.min(100, parseInt(obj.escapeProgress || 0, 10) || 0)),
      dangerProgress: Math.max(0, Math.min(100, parseInt(obj.dangerProgress || 0, 10) || 0)),
      turnCount: 0,
      actTitle: String(obj.actTitle||'').trim(),
      objective: String(obj.objective||'').trim(),
      sceneText: String(obj.sceneText||'').trim(),
      inventory: normalizeArray(obj.inventory).map(function(x){return Object.assign({id:uid('item')}, x||{});}),
      clues: normalizeArray(obj.clues).map(function(x){return Object.assign({id:uid('clue')}, x||{});}),
      activePuzzles: normalizeArray(obj.activePuzzles).map(function(x){return Object.assign({id:uid('puzzle'), solved:false}, x||{});}),
      choices: normalizeArray(obj.choices).map(function(x){return Object.assign({id:uid('choice')}, x||{});}).slice(0,7),
      characterReactions: normalizeArray(obj.characterReactions),
      log: normalizeArray(obj.log),
      ending: obj.ending || null,
      completed: !!obj.ending,
      uniquenessSignature: String(obj.uniquenessSignature || buildSignature(obj)).slice(0,1600)
    };
    if(!game.title || !game.storyBackground || !game.userIdentity || !game.entryIncident || !game.sceneText || !game.choices.length){
      throw new Error('API返回内容缺少逃生背景故事、用户身份、进入原因、剧情正文或选择按钮。请重新生成。');
    }
    if(!game.truthPlan || !game.truthPlan.coreTruth || !game.progressionPlan || !Array.isArray(game.progressionPlan.requiredSteps) || game.progressionPlan.requiredSteps.length < 3){
      throw new Error('API返回内容缺少开局真相蓝图或通关路线。请重新生成。');
    }
    if(game.mode === 'withRoles' && (!game.characterIdentities || game.characterIdentities.length < 1)){
      throw new Error('API返回内容缺少参与角色身份设定。请重新生成。');
    }
    return game;
  }
  function mergeGameUpdate(game, obj, actionText){
    obj = obj && typeof obj === 'object' ? obj : {};
    game.updatedAt = Date.now();
    game.turnCount = Math.max(0, parseInt(game.turnCount || 0, 10) || 0) + 1;
    if(obj.sceneText) game.sceneText = String(obj.sceneText);
    if(obj.objective) game.objective = String(obj.objective);
    if(obj.actTitle) game.actTitle = String(obj.actTitle);
    if(obj.truthPlan && typeof obj.truthPlan === 'object') game.truthPlan = Object.assign({}, game.truthPlan || {}, obj.truthPlan);
    if(obj.progressionPlan && typeof obj.progressionPlan === 'object') game.progressionPlan = Object.assign({}, game.progressionPlan || {}, obj.progressionPlan);
    if(obj.currentStage != null) game.currentStage = Math.max(1, parseInt(obj.currentStage, 10) || game.currentStage || 1);
    if(obj.maxStage != null) game.maxStage = Math.max(4, parseInt(obj.maxStage, 10) || game.maxStage || 6);
    if(obj.escapeProgress != null) game.escapeProgress = Math.max(0, Math.min(100, parseInt(obj.escapeProgress, 10) || 0));
    if(obj.dangerProgress != null) game.dangerProgress = Math.max(0, Math.min(100, parseInt(obj.dangerProgress, 10) || 0));
    normalizeArray(obj.inventoryRemoveIds).forEach(function(id){ game.inventory = (game.inventory||[]).filter(function(it){return String(it.id)!==String(id);}); });
    normalizeArray(obj.inventoryAdd).forEach(function(it){ if(it){ game.inventory.push(Object.assign({id:uid('item')}, it)); } });
    normalizeArray(obj.cluesAdd).forEach(function(c){ if(c){ game.clues.push(Object.assign({id:uid('clue')}, c)); } });
    normalizeArray(obj.activePuzzlesAdd).forEach(function(p){ if(p){ game.activePuzzles.push(Object.assign({id:uid('puzzle'), solved:false}, p)); } });
    normalizeArray(obj.puzzleUpdates).forEach(function(up){
      var p = (game.activePuzzles||[]).find(function(x){return String(x.id)===String(up.id);});
      if(p){ Object.assign(p, up); }
    });
    game.choices = normalizeArray(obj.choices).map(function(x){return Object.assign({id:uid('choice')}, x||{});}).slice(0,7);
    game.characterReactions = normalizeArray(obj.characterReactions);
    var entry = String(obj.eventLogEntry || actionText || '').trim();
    if(entry) game.log = (game.log||[]).concat([{time:Date.now(), text:entry}]).slice(-80);
    if(obj.ending){
      game.ending = obj.ending;
      game.completed = true;
      game.choices = [];
    }
    game.uniquenessSignature = String(obj.uniquenessSignature || game.uniquenessSignature || buildSignature(game)).slice(0,1600);
    return game;
  }
