      id: String(cfg.id || ''),
      name: String(cfg.name || ''),
      url: String(cfg.url || cfg.baseUrl || '').trim().replace(/\/+$/,''),
      key: String(cfg.key || cfg.apiKey || '').trim(),
      model: String(cfg.model || '').trim() || '__auto__'
