  window.monoGetStrictActiveApiConfig = function(){ return applyStrictActive(); };
  window._getCurrentActiveApiConfig = window.monoGetStrictActiveApiConfig;
  window._getCurrentEffectiveApiConfig = window.monoGetStrictActiveApiConfig;

  document.addEventListener('visibilitychange', function(){ if (!document.hidden) { try { applyStrictActive(); } catch(e) {} } });
