    writeProxy(EFF_KEY, JSON.stringify(cfg)); writeRaw(EFF_KEY, JSON.stringify(cfg));
    writeProxy(CFG_KEY, JSON.stringify(cfg)); writeRaw(CFG_KEY, JSON.stringify(cfg));
