  /* 5) 角色自动语音频率：按“本轮”判断，不按每条气泡重复抽奖；10% 就接近 10% */
  window.tryPersonaSendVoice = async function(p, textMessages){
    try { ttsConfig = JSON.parse(localStorage.getItem('mono_tts_config') || '{}'); } catch(e) {}
    if (!p || !p.allowVoice) return;
    var list = (Array.isArray(textMessages) ? textMessages : [textMessages]).map(function(x){ return String(x||'').trim(); }).filter(function(x){ return x && x.replace(/\s+/g,'').length >= 2; });
    if (!list.length) return;
    var rawFreq = p.voiceFreq;
    var probMap = { all:1, always:1, high:0.30, mid:0.18, medium:0.18, low:0.10, rare:0.05, none:0 };
    var prob = probMap[String(rawFreq||'mid').toLowerCase()];
    if (prob == null) {
      var n = parseFloat(String(rawFreq).replace('%',''));
      prob = isFinite(n) ? (n > 1 ? n/100 : n) : 0.18;
    }
    prob = Math.max(0, Math.min(1, prob));
    var isAll = prob >= 0.999;
    if (!isAll && Math.random() > prob) return;
    var ttsEnabled = !!(ttsConfig && ttsConfig.enabled);
    var normalized = function(v){ return String(v || '').replace(/\s+/g,'').trim(); };
    function findTarget(msg){
      var nMsg = normalized(msg);
      for (var h=(p.history||[]).length-1; h>=0; h--) { var it=p.history[h]||{}; if(it.role==='assistant' && it.msgType!=='voice' && normalized(it.content)===nMsg) return h; }
      for (var h2=(p.history||[]).length-1; h2>=0; h2--) { var it2=p.history[h2]||{}; if(it2.role==='assistant' && it2.msgType!=='voice' && String(it2.content||'').trim()) return h2; }
      return -1;
    }
    var candidates = isAll ? list : [list[Math.floor(Math.random()*list.length)]];
    for (var i=0;i<candidates.length;i++){
      var msg = candidates[i]; var idx = findTarget(msg); if (idx < 0) continue;
      var original = String((p.history[idx] && p.history[idx].content) || msg || '').trim();
      var duration = (typeof calcVoiceDuration === 'function') ? calcVoiceDuration(original) : Math.max(2, Math.round(original.length/4));
      await new Promise(function(r){ setTimeout(r, 180 + Math.random()*260); });
      if (!ttsEnabled) {
        p.history[idx] = Object.assign({}, p.history[idx] || {}, { role:'assistant', msgType:'voice', content:original, duration:duration, audioUrl:'', timestamp:(p.history[idx]&&p.history[idx].timestamp)||Date.now(), _ttsSimulated:true });
        saveAll(); if (String((typeof currentId!=='undefined'?currentId:'')) === String(p.id) && typeof renderMessages==='function') renderMessages();
        continue;
      }
      try {
        var voiceLang = (typeof _monoResolvePersonaTtsLang === 'function') ? _monoResolvePersonaTtsLang(p) : (p.voiceLang || 'zh');
        var ttsMsg = (typeof _stripSpokenTranslation === 'function' ? _stripSpokenTranslation(original) : original) || original;
        var audioUrl = await callTtsAudio(ttsMsg, p.voiceId || '', parseFloat(p.voiceSpeed)||1, voiceLang);
        if (!audioUrl) throw new Error('TTS 没有返回音频地址');
        p.history[idx] = Object.assign({}, p.history[idx] || {}, { role:'assistant', msgType:'voice', content:original, duration:duration, audioUrl:audioUrl, timestamp:(p.history[idx]&&p.history[idx].timestamp)||Date.now(), _ttsProvider:(ttsConfig.provider||'minimax') });
      } catch(e) {
        p.history[idx] = Object.assign({}, p.history[idx] || {}, { role:'assistant', msgType:'voice', content:original, duration:duration, audioUrl:'', timestamp:(p.history[idx]&&p.history[idx].timestamp)||Date.now(), _ttsError:e.message||String(e) });
      }
      saveAll(); if (String((typeof currentId!=='undefined'?currentId:'')) === String(p.id) && typeof renderMessages==='function') renderMessages();
    }
  };

