// ===== mono-wb-entries-scroll-final-fix-js =====

(function(){
  if (window.__monoWbEntriesScrollFinalFix) return;
  window.__monoWbEntriesScrollFinalFix = true;

  function fixWbEntriesModal(){
    try {
      var modal = document.getElementById('wbEntriesModal');
      var list = document.getElementById('wbEntriesList');
      var content = modal ? modal.querySelector('.wb-modal-content') : null;
      if (!modal || !list || !content) return;
      content.style.display = 'flex';
      content.style.flexDirection = 'column';
      content.style.overflow = 'hidden';
      content.style.height = 'min(82dvh, 620px)';
      content.style.maxHeight = 'min(82dvh, 620px)';
      list.style.flex = '1 1 auto';
      list.style.minHeight = '0';
      list.style.overflowY = 'auto';
      list.style.overflowX = 'hidden';
      list.style.webkitOverflowScrolling = 'touch';
      list.style.touchAction = 'pan-y';
      list.setAttribute('data-mono-scroll-fixed', '1');
    } catch(e) {}
  }

  var oldOpen = window.openWbEntries;
  if (typeof oldOpen === 'function' && !oldOpen.__monoScrollFixed) {
    var wrapped = function(){
      var ret = oldOpen.apply(this, arguments);
      setTimeout(function(){
        fixWbEntriesModal();
        try {
          var list = document.getElementById('wbEntriesList');
          if (list) list.scrollTop = 0;
        } catch(e) {}
      }, 0);
      setTimeout(fixWbEntriesModal, 80);
      return ret;
    };
    wrapped.__monoScrollFixed = true;
    window.openWbEntries = wrapped;
  }

  var oldRender = window.renderWbEntries;
  if (typeof oldRender === 'function' && !oldRender.__monoScrollFixed) {
    var rwrap = function(){
      var ret = oldRender.apply(this, arguments);
      setTimeout(fixWbEntriesModal, 0);
      return ret;
    };
    rwrap.__monoScrollFixed = true;
    window.renderWbEntries = rwrap;
  }

  document.addEventListener('DOMContentLoaded', function(){
    fixWbEntriesModal();
    document.addEventListener('click', function(ev){
      var card = ev.target && ev.target.closest ? ev.target.closest('.wb-card') : null;
      if (card) setTimeout(fixWbEntriesModal, 60);
    }, true);
  });

  /* 避免外层页面/弹窗把 iOS 的 touchmove 吃掉，列表本身允许竖向滚动 */
  document.addEventListener('touchmove', function(ev){
    try {
      var list = ev.target && ev.target.closest ? ev.target.closest('#wbEntriesList') : null;
      if (list) ev.stopPropagation();
    } catch(e) {}
  }, { passive: true, capture: true });
})();


