// ===== monoChatInputVerticalCenterPatchScript =====

(function(){
  if (window.__monoChatInputVerticalCenterPatch) return;
  window.__monoChatInputVerticalCenterPatch = true;
  function normalizeChatInput(){
    try {
      var input = document.getElementById('userInput');
      if (!input) return;
      input.removeAttribute('readonly');
      input.readOnly = false;
      input.disabled = false;
      input.style.boxSizing = 'border-box';
      input.style.lineHeight = '20px';
      input.style.paddingTop = '10px';
      input.style.paddingBottom = '10px';
      input.style.minHeight = '42px';
      if (!input.value) input.style.height = '42px';
    } catch(e) {}
  }
  document.addEventListener('DOMContentLoaded', normalizeChatInput, {passive:true});
  window.addEventListener('load', normalizeChatInput, {passive:true});
  document.addEventListener('focusin', function(e){ if (e && e.target && e.target.id === 'userInput') normalizeChatInput(); }, true);
  document.addEventListener('input', function(e){
    try {
      if (!e || !e.target || e.target.id !== 'userInput') return;
      var input = e.target;
      input.style.lineHeight = '20px';
      input.style.paddingTop = '10px';
      input.style.paddingBottom = '10px';
      input.style.height = '42px';
      var next = Math.min(Math.max(input.scrollHeight, 42), 108);
      input.style.height = next + 'px';
    } catch(_) {}
  }, true);
  ['openApp','openChat','renderMessages'].forEach(function(name){
    try {
      var fn = window[name];
      if (typeof fn !== 'function' || fn.__monoInputCenterWrapped) return;
      var wrapped = function(){
        var r = fn.apply(this, arguments);
        setTimeout(normalizeChatInput, 0);
        setTimeout(normalizeChatInput, 120);
        return r;
      };
      wrapped.__monoInputCenterWrapped = true;
      window[name] = wrapped;
    } catch(e) {}
  });
  setTimeout(normalizeChatInput, 300);
})();


