  function readJson(key, fallback){
    var txt = '';
    try { txt = rawStore().getItem(key) || ''; } catch(e) {}
    if (!txt) { try { txt = localStorage.getItem(key) || ''; } catch(e) {} }
    if (!txt) return fallback;
    try { return JSON.parse(txt); } catch(e) { return fallback; }
  }
