        gender: String(p.gender || ''),
        avatar: String(p.avatar || ''),
        momentsNickname: String(p.momentsNickname || p.name || '用户'),
        momentsSignature: String(p.momentsSignature || ''),
        momentsBanner: String(p.momentsBanner || ''),
