        name: String(m.name || '未命名面具'), avatar: String(m.avatar || ''), hasCustomAvatar: !!m.hasCustomAvatar,
        bio: String(m.bio || ''), personaSpec: String(m.personaSpec || ''), createdAt: Number(m.createdAt) || Date.now(), updatedAt: Number(m.updatedAt) || Date.now()
