    var backupMasks = readJson('mono_user_masks_backup_v11', []);
    var snapMasks = readJson(MASKS_KEY, null);
    var legacyMasks = readJson('mono_user_masks_stable_v1', null);
    [currentMasks, rawMasks, backupMasks, snapMasks && snapMasks.masks, legacyMasks && legacyMasks.masks].forEach(function(arr){ if (Array.isArray(arr)) maskSources = maskSources.concat(arr); });
    var byId = {};
