  function avatarLooksHumanLike(text){
    var s=txt(text).toLowerCase();
    if(!s) return false;
    return /(人像|真人|写真|自拍|脸|面部|半身|上半身|女孩|女生|女人|少女|男孩|男生|男人|少年|姐姐|妹妹|哥哥|弟弟|小姐|先生|学姐|学长|女友|男友|couple selfie|selfie|portrait|human|person|girl|boy|woman|man|female|male)/.test(s);
  }
  function resolveAvatarStyleCode(raw, mode, extraText, opts){
    opts=opts||{};
    var s=txt(raw).trim().toLowerCase();
    var mix=(s+' '+txt(extraText).toLowerCase()).trim();
    var explicitStylized = opts.allowStylized === true || avatarExplicitlyRequestsStylized([raw, extraText, opts.userText||''].join(' '));
    var codes=avatarStyleCodeList();
    for(var i=0;i<codes.length;i++){
      if(s===codes[i]){
        return codes[i];
      }
    }
    if(/韩漫cp|漫画cp|情侣漫|配对漫|manhwa cp|manga cp/.test(mix)) return 'korean_couple_selfie';
    if(/日漫|韩漫|漫画|anime|manga|manhwa/.test(mix)) return mode==='pair' ? 'korean_couple_selfie' : 'korean_real';
    if(/棉花娃娃|娃娃|chibi/.test(mix)) return explicitStylized ? 'dream_soft' : (mode==='pair' ? 'korean_couple_selfie' : 'korean_real');
    if(/q版|软萌/.test(mix)) return explicitStylized ? 'dream_soft' : (mode==='pair' ? 'korean_couple_selfie' : 'korean_real');
    if(/像素/.test(mix)) return explicitStylized ? 'dream_soft' : (mode==='pair' ? 'korean_couple_selfie' : 'korean_real');
    if(/表情包|梗图|搞笑|meme/.test(mix)) return mode==='pair' ? 'korean_couple_selfie' : 'korean_real';
    if(/猫|狗|宠物|小狗|小猫/.test(mix)) return mode==='pair' ? 'korean_couple_selfie' : 'korean_real';
    if(/黑白|极简|全黑|emo|冷淡/.test(mix)) return 'cool_gloomy';
    if(/手绘|涂鸦|简笔/.test(mix)) return explicitStylized ? 'dream_soft' : (mode==='pair' ? 'korean_couple_selfie' : 'korean_real');
    if(/梦核|朦胧|软糯|柔焦/.test(mix)) return 'dream_soft';
    if(/港风|复古|胶片/.test(mix)) return 'ins_blogger';
    if(/校园|校服|放学|课桌/.test(mix)) return mode==='pair' ? 'korean_couple_selfie' : 'korean_real';
    if(/博主|ins|小众|生活方式/.test(mix)) return 'ins_blogger';
    if(/物品|耳机|帽子|玩偶|甜品|书本|围巾|相机|游戏机/.test(mix)) return 'object_avatar';
    if(/厌世|病娇|冷白|阴郁/.test(mix)) return 'cool_gloomy';
    if(/韩系||自拍|被窝|情侣|闺蜜|配对|couple|pair|matching/.test(mix)) return mode==='pair' ? 'korean_couple_selfie' : 'korean_real';
    return mode==='pair' ? 'korean_couple_selfie' : 'korean_real';
  }
