  async function callAvatarPromptModel(messages, p, maxTokens){
    var cfg=currentApi();
    if(!cfg||!cfg.url||!cfg.key||!cfg.model) throw new Error('请先配置当前聊天 API');
    var payload = (typeof _applyApiModel === 'function') ? _applyApiModel({messages:messages,temperature:Math.min(1,Number(p&&p.temperature||0.85)),max_tokens:maxTokens||700,stream:false}, cfg.model) : {model:cfg.model,messages:messages,temperature:.85,max_tokens:maxTokens||700,stream:false};
    var resp;
    if(typeof _compatibleChatCompletion==='function') resp=await _compatibleChatCompletion(cfg.url,cfg.key,payload,{});
    else resp=await fetch(txt(cfg.url).replace(/\/$/,'')+'/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+cfg.key,'Content-Type':'application/json'},body:JSON.stringify(payload)});
    var t=await resp.text();
    if(!resp.ok) throw new Error('头像描述生成失败 HTTP '+resp.status+' '+t.slice(0,120));
    var data; try{data=JSON.parse(t);}catch(e){data={text:t};}
    return cleanAi((typeof _extractAssistantMessageContent==='function')?_extractAssistantMessageContent(data):(data.text||t));
  }
  function parsePairPlan(raw, p){
    var txtRaw=txt(raw).trim();
    if(!txtRaw) return null;
    try{
      var s=txtRaw.replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();
      var obj=JSON.parse(s);
      if(obj && (obj.roleAvatarPrompt||obj.userAvatarPrompt)) return normalizePairPlan(obj, p);
    }catch(e){}
    var pname=(p&&p.name)||'角色', uname=userNameFor(p);
    return normalizePairPlan({
      theme:'同组配对头像',
      style:'统一风格的配对头像',
      styleCode: resolveAvatarStyleCode(txtRaw, 'pair', txtRaw, { userText: txtRaw }),
      roleAvatarPrompt:txtRaw + '。这是'+pname+'使用的那一张。',
      userAvatarPrompt:txtRaw + '。这是'+uname+'使用的那一张。',
      negativePrompt:'避免廉价 AI 感，避免不成对。'
    }, p);
  }
  function normalizePairPlan(plan, p){
    plan=plan && typeof plan==='object' ? Object.assign({}, plan) : {};
    var pname=(p&&p.name)||'角色', uname=userNameFor(p);
    var theme=txt(plan.theme||'同组配对头像').trim() || '同组配对头像';
    var styleText=txt(plan.style||plan.styleLabel||'').trim();
    var role=txt(plan.roleAvatarPrompt||'').trim();
    var user=txt(plan.userAvatarPrompt||'').trim();
    var neg=txt(plan.negativePrompt||'').trim();
    var styleCode=resolveAvatarStyleCode(plan.styleCode || styleText || theme, 'pair', [theme, styleText, role, user].join(' '), { userText: [theme, styleText, role, user].join(' ') });
    var styleLabel=avatarStylePresetLabel(styleCode);
    var sameNorm=role.replace(/\s+/g,'').slice(0,220) === user.replace(/\s+/g,'').slice(0,220);
    var tooSimilar = !role || !user || sameNorm || role === user || role.indexOf(user) >= 0 || user.indexOf(role) >= 0;
    if(tooSimilar){
      var seed=txt(role||user||theme||'同组配对头像');
      role='共同主题：'+theme+'。选中的内置风格：'+styleLabel+'。这是 '+pname+' 使用的那张，必须是配对组里的角色侧。构图偏左或偏角色侧，主体必须优先体现 '+pname+' 的设定，不可被用户资料覆盖。画面主体、表情、视线、动作、姿势、手势、服装或代表元素要与用户那张明显不同，但仍保持同组呼应。原始方向：'+seed;
      user='共同主题：'+theme+'。选中的内置风格：'+styleLabel+'。这是 '+uname+' 使用的那张，必须是配对组里的用户侧。构图偏右或偏用户侧，主体优先参考用户资料与用户头像描述。画面主体、表情、视线、动作、姿势、手势、服装或代表元素要与角色那张明显不同，但仍保持同组呼应。原始方向：'+seed;
    }
    role+='。这张只给角色 '+pname+' 用。严禁把用户头像描述直接套到这张上。'+avatarRoleGenderRule(p);
    user+='。这张只给用户 '+uname+' 用。用户资料只参考用户那张，不可反向污染角色那张。'+avatarUserGenderRule(p);
    plan.theme=theme;
    plan.style=styleLabel;
    plan.styleCode=styleCode;
    plan.roleAvatarPrompt=role;
    plan.userAvatarPrompt=user;
    plan.negativePrompt=neg || '避免两张图一样；避免角色和用户分不清；避免角色被生成为错误性别；避免廉价 AI 感；避免像海报或立绘。';
    return plan;
  }
