  function buildAvatarPrompt(desc, p, kind, pairPlan){
    var base = 'Square 1:1 avatar image, clean composition for circular profile icon, centered subject, recognizable at small size, no watermark, no text, safe for social profile use. ';
    var styleCode=resolveAvatarStyleCode(pairPlan && (pairPlan.styleCode || pairPlan.style), kind==='pair' ? 'pair' : 'single', txt(desc), { userText: txt((pairPlan && pairPlan._sourceUserText) || '') });
    var styleLabel=avatarStylePresetLabel(styleCode);
    var personaSummary=txt(p && (p.imagePersonaSummary || '')).trim();
    var personaFull=txt(p && p.persona).trim();
    var realismContext=[txt(desc), txt(p&&p.imageStylePrompt), txt((pairPlan && pairPlan._sourceUserText) || '')].join(' ');
    var explicitStylized = avatarExplicitlyRequestsStylized(realismContext);
    var humanLike = avatarLooksHumanLike([desc, personaSummary, personaFull].join(' '));
    var compactSinglePortrait = kind==='single' && humanLike;
    var personaHint='';
    if(kind==='single') personaHint = personaSummary || personaFull;
    else if(pairPlan && pairPlan._owner==='role') personaHint = personaSummary || personaFull;
    var extra = compactSinglePortrait
      ? [
          'Make this a believable real-life social avatar portrait, not poster art and not a beauty-filter AI face.',
          'Use natural smartphone-photo realism: realistic skin texture, subtle asymmetry, natural hairline, natural eye size, natural jawline, casual styling, ordinary real-life lighting.',
          'The face, age impression, vibe, hairstyle tendency, expression, clothing mood, and overall presence must strongly match the role persona instead of a generic attractive template.',
          'The chosen internal style code only controls mood, color, and composition. Do not let style override portrait realism or the role identity.',
          'Chosen internal style: '+styleCode+' ('+styleLabel+'). Keep the style subtle and avatar-appropriate.'
        ]
      : [
          'Overall style rule: make it feel like a real social-media avatar, not poster art.',
          'Content priority rule: the subject matter, mood, props, pose, scene choice, and relationship cues must come primarily from the character persona, character memory, current relationship, current emotional state, and any explicit avatar-content or avatar-style request. Recent chat context is only a light reference unless it explicitly asks for avatar content or style.',
          'Portrait fidelity rule: if this image contains a human or human-like character, the face, vibe, age impression, styling, hair tendency, expression, and overall presence must strongly match the role persona rather than a generic attractive template.',
          humanLike
            ? 'Portrait realism rule: make it look like a believable phone-camera social avatar. Keep realistic skin texture, subtle asymmetry, natural hairline and baby hairs, natural eye size, natural jawline, casual styling, and real-life lighting. Avoid glossy porcelain skin, influencer template face, studio glamour retouch, uncanny symmetry, fake eyelashes, and CGI beauty-filter look.'
            : 'If a human-like subject appears, still avoid uncanny AI beauty-filter look and keep it grounded in believable real-life texture.',
          'Prefer East Asian social avatar aesthetics, soft daily-life feeling, profile-icon readability.',
          explicitStylized
            ? 'The user explicitly requested a stylized or non-photoreal look. Keep that request, but preserve avatar usability and avoid cheap AI artifacts.'
            : 'Default realism rule: regardless of the chosen style code, render it as a believable real-life avatar first. Human/selfie styles should look like natural phone photos. Animal/pet/meme styles should look like real pets, real plush toys, or real meme screenshots. Object-avatar styles should look like real photographed objects. Dreamy, gloomy, black-and-white, or vintage styles should feel like edited real photos, not flat illustration.',
          explicitStylized
            ? 'If the chosen style is anime/comic/chibi/pixel/doodle, keep it high quality, clean, and avatar-friendly rather than poster-like.'
            : 'Do not switch to obvious anime, cartoon, chibi, pixel art, doodle, or cotton-doll illustration unless the user explicitly asked for that non-realistic style.',
          'If anime/comic style is explicitly requested, use clean Japanese or Korean manga/manhwa avatar quality, not cheap AI animal cartoon.',
          'If animal/cartoon style is used, keep it simple, cute, meme-like, profile-picture friendly, and grounded in realistic texture or real toy/photo logic.',
          'Built-in style library is enabled. The chosen internal style for this image is: '+styleCode+' ('+styleLabel+'). You must follow this selected style strictly instead of falling back to a generic style. '+avatarStylePresetGuide(styleCode, kind==='pair'?'pair':'single')
        ];
    if(kind==='pair') extra.push('This must clearly belong to a matching pair avatar set and visually relate to its counterpart.');
    if(pairPlan && pairPlan.theme) extra.push('Shared pair theme: '+txt(pairPlan.theme));
    if(pairPlan && pairPlan.style) extra.push('Shared pair style label: '+txt(pairPlan.style));
    if(pairPlan && pairPlan.negativePrompt) extra.push('Avoid: '+txt(pairPlan.negativePrompt));
    if(pairPlan && pairPlan._sourceUserText && avatarChatHasExplicitDirective(pairPlan._sourceUserText)) extra.push('Explicit avatar request anchor for this image: '+txt(pairPlan._sourceUserText).slice(0,900));
    if(kind==='single') extra.push(avatarRoleGenderHardPrompt(p));
    if(kind==='single') extra.push(avatarRoleGenderSourceOfTruthPromptEn(p));
    if(kind==='pair' && pairPlan && pairPlan._owner==='role') extra.push('Owner side: role/avatar owner. User profile reference must NOT override this image. '+avatarRoleGenderRule(p)+' '+avatarRoleGenderHardPrompt(p));
    if(kind==='pair' && pairPlan && pairPlan._owner==='role') extra.push(avatarRoleGenderSourceOfTruthPromptEn(p));
    if(kind==='pair' && pairPlan && pairPlan._owner==='user') extra.push('Owner side: user/avatar owner. This image should absorb user profile reference appropriately. '+avatarUserGenderRule(p)+' '+avatarUserGenderHardPrompt(p));
    if(personaHint) extra.push('Character persona anchor for this image: '+personaHint);
    if(personaHint) extra.push('If this becomes a portrait, convert the persona anchor into visible portrait cues: age impression, facial vibe, temperament, grooming, hairstyle tendency, clothing mood, eye expression, and social presence should all feel like this exact character.');
    return base + txt(desc) + '\nStyle notes from character setting: ' + txt(p&&p.imageStylePrompt) + '\n' + extra.join('\n') + '\nUse moderate resolution suitable for avatar, not a poster. If the image is portrait-like, prefer realistic smartphone-photo fidelity over stylized beauty-filter rendering.';
  }
  function compressImage(src, maxSize, quality){
    return new Promise(function(resolve){
      if(!src || !/^data:image\//.test(src)) return resolve(src);
      var img=new Image();
      img.onload=function(){
        try{
          var size=maxSize||384, w=img.naturalWidth||img.width, h=img.naturalHeight||img.height;
          var side=Math.min(w,h), sx=Math.max(0,(w-side)/2), sy=Math.max(0,(h-side)/2);
          var c=document.createElement('canvas'); c.width=size; c.height=size;
          var ctx=c.getContext('2d'); ctx.imageSmoothingEnabled=true; ctx.imageSmoothingQuality='high';
          ctx.drawImage(img,sx,sy,side,side,0,0,size,size);
          var out='';
          try{ out=c.toDataURL('image/webp', quality||0.78); }catch(e){ out=c.toDataURL('image/jpeg', quality||0.78); }
          resolve(out||src);
        }catch(e){ resolve(src); }
      };
      img.onerror=function(){resolve(src);};
      img.src=src;
    });
  }
  async function genImageFromDesc(desc, p, kind, pairPlan){
    var cfg=imageApi();
    if(!cfg||!cfg.url||!cfg.key||!cfg.model) throw new Error('请先配置生图 API');
    var prompt=buildAvatarPrompt(desc,p,kind,pairPlan);
    var raw=await monoCallImageChatCompletions(prompt,cfg);
    return await compressImage(raw,384,0.78);
  }
  function replaceOldAvatarEverywhere(oldSrc,newSrc){
    if(!oldSrc||!newSrc||oldSrc===newSrc) return;
    try{
      for(var i=0;i<localStorage.length;i++){
        var k=localStorage.key(i); if(!k) continue;
        var v=localStorage.getItem(k); if(v && v.indexOf(oldSrc)!==-1) localStorage.setItem(k, v.split(oldSrc).join(newSrc));
      }
    }catch(e){}
    try{ document.querySelectorAll('img').forEach(function(img){ if(img.src===oldSrc || img.getAttribute('src')===oldSrc) img.src=newSrc; }); }catch(e){}
  }
  function applyPersonaAvatar(p, src, desc, source){
    if(!p||!src) return;
    var old=p.avatar||'';
    p.avatar=src;
    delete p.originalAvatar; delete p.prevAvatar; delete p.avatarHistory; delete p._oldAvatar;
    p.lastAvatarGenAt=Date.now();
    p.lastAvatarGenDesc=desc||'';
    p.avatarGeneratedByRole=true;
    replaceOldAvatarEverywhere(old,src);
    if(Array.isArray(p.history)) p.history.push({role:'system',msgType:'avatar_notice',content:(p.name||'角色')+'换了头像',timestamp:Date.now(),_avatarChangeNotice:true});
    mem(p,'我把头像换成了新的头像。头像内容：'+(desc||'未记录')+'。我知道这是我现在正在使用的头像。', source||'角色换头像');
    if(typeof saveData==='function') saveData();
    try{ if(monoCurrentPersonaId()==p.id && typeof renderMessages==='function') renderMessages({forceScrollToBottom:true}); }catch(e){}
    try{ if(typeof renderContactList==='function') renderContactList(); }catch(e){}
    try{ if(typeof renderMoments==='function') renderMoments(); }catch(e){}
  }

  async function triggerAvatarFollowupReply(p, facts){
    if(!p || !Array.isArray(p.history)) return false;
    if(p._avatarFollowupBusy) return false;
    if(typeof triggerAuto回复 !== 'function' && typeof window.triggerAuto回复 !== 'function') return false;
    if(!apiConfig || !apiConfig.url || !apiConfig.key || !apiConfig.model) return false;
    p._avatarFollowupBusy = true;
    try{
      p.history.push({
        role:'system',
        content:'【必须紧接上一件事继续聊天】你刚刚已经成功换好了头像。现在请像普通聊天那样，基于当前聊天内容、世界书、人设、内置世界书、记忆、用户刚才的要求，以及刚刚换头像这件事，自然继续发送后续回复。第一条回复必须承接“刚换头像/配对头像”这件事，不要突然开启无关新话题。你要知道自己换成了什么头像，也知道这次换头像是怎么发生的。不要把自己说成系统，不要输出生图指令、占位符、URL、Markdown图片或技术说明。补充信息：'+txt(facts||''),
        _hiddenContext:true,
        _systemNote:false,
        _monoImageReplyHint:true,
        _avatarFollowupHint:true,
        timestamp:Date.now()+2
      });
      if(typeof saveData==='function') saveData();
      try{ if(monoCurrentPersonaId()==p.id && typeof renderMessages==='function') renderMessages({forceScrollToBottom:true}); }catch(e){}
      p._monoSkipNextAvatarRetrigger = true;
      if(monoCurrentPersonaId() == p.id){
        var fn = (typeof triggerAuto回复 === 'function') ? triggerAuto回复 : window.triggerAuto回复;
        await fn();
        return true;
      }
      return false;
    }catch(e){
      console.warn('[mono avatar followup reply]', e);
      return false;
    }finally{
      setTimeout(function(){ try{ p._avatarFollowupBusy = false; }catch(e){} }, 1200);
    }
  }
