  async function _drBuildAndShowCoupleCollage(personaId, result, wrapId, previewId, recordId, isUserPage) {
    var userRefs = result && result.userOutfitData ? _drCollectUploadedRefsFromOutfit(personaId, result.userOutfitData, true, '用户') : _drCollectUploadedRefsFromText(personaId, result && result.userOutfit || '', true, '用户');
    var charRefs = result && result.charOutfitData ? _drCollectUploadedRefsFromOutfit(personaId, result.charOutfitData, false, '角色') : _drCollectUploadedRefsFromText(personaId, result && result.charOutfit || '', false, '角色');
    if (!userRefs.length && !charRefs.length) { _drClearCollagePreview(wrapId, previewId); return ''; }
    var groups = [];
    if (userRefs.length) groups.push({ label: (_getUserProfile().name || '用户'), refs: userRefs });
    if (charRefs.length) groups.push({ label: (_getCurrentPersona() || {}).name || '角色', refs: charRefs });
    var src = await _drBuildWardrobeCollage(groups);
    if (!src) { _drClearCollagePreview(wrapId, previewId); return ''; }
    _drRenderCollagePreview(wrapId, previewId, src);
    if (_drState.coupleOutfit) _drState.coupleOutfit.collageSrc = src;
    if (recordId) _drUpdateRecord('couple', recordId, { collageSrc: src }, !!isUserPage);
    return src;
  }

  function _drWardrobeNamesByCat(personaId, isUser) {
    var out = {};
    _getWardrobeCats(personaId, isUser).forEach(function(cat){
      out[cat] = _getWardrobe(personaId, cat, isUser).map(_drNormalizeWardrobeItem).map(function(it){ return it.name; }).filter(Boolean);
    });
    return out;
  }

  function _drRestrictOutfitToWardrobe(personaId, outfit, isUser) {
    var restricted = { '上装':'无', '下装':'无', '外套':'无', '鞋':'无', '配饰':'无' };
    var maps = _drWardrobeNamesByCat(personaId, isUser);
    Object.keys(restricted).forEach(function(cat){
      var val = _drStringifyFieldValue((outfit || {})[cat]);
      if (!val || val === '无') return;
      var found = _drFindWardrobeMatchForOutfitItem(personaId, cat, val, isUser);
      if (!found) {
        var list = (maps[cat] || []).map(function(x){ return String(x || '').trim(); }).filter(Boolean);
        for (var i = 0; i < list.length; i++) {
          var nm = list[i];
          var nn = _drSimpleTextNorm(nm), vv = _drSimpleTextNorm(val);
          if (vv.indexOf(nn) >= 0 || nn.indexOf(vv) >= 0) { found = { name: nm }; break; }
        }
      }
      restricted[cat] = found && found.name ? found.name : '无';
    });
    return restricted;
  }


  function _drRestrictOutfitToWardrobeDynamic(personaId, outfit, isUser) {
    var cats = _getWardrobeCats(personaId, isUser).filter(function(cat){ return _getWardrobe(personaId, cat, isUser).length; });
    var out = {};
    var allText = Object.entries(outfit || {}).map(function(kv){ return kv[0] + ' ' + _drStringifyFieldValue(kv[1]); }).join('；');
    var allNorm = _drSimpleTextNorm(allText);
    cats.forEach(function(cat){
      var items = _getWardrobe(personaId, cat, isUser).map(_drNormalizeWardrobeItem).filter(function(it){ return it.name; });
      var direct = _drStringifyFieldValue((outfit || {})[cat]);
      var chosen = [];
      if (direct && direct !== '无') {
        items.forEach(function(it){
          var nn = _drSimpleTextNorm(it.name);
          var dd = _drSimpleTextNorm((it.detailDesc || '') + ' ' + (it.desc || '') + ' ' + (it.visionDesc || ''));
          var vv = _drSimpleTextNorm(direct);
          if ((nn && (vv.indexOf(nn) >= 0 || nn.indexOf(vv) >= 0)) || (dd && vv.indexOf(dd) >= 0)) chosen.push(it.name);
        });
        // 如果 API 把其他分类的单品塞进默认五类里，不要把无效 direct 原样显示；继续从全文里找真实衣柜单品。
        if (!chosen.length) {
          items.forEach(function(it){
            var nn = _drSimpleTextNorm(it.name);
            if (nn && allNorm.indexOf(nn) >= 0) chosen.push(it.name);
          });
        }
      } else {
        items.forEach(function(it){
          var nn = _drSimpleTextNorm(it.name);
          if (nn && allNorm.indexOf(nn) >= 0) chosen.push(it.name);
        });
      }
      chosen = chosen.filter(function(x, i, arr){ return x && arr.indexOf(x) === i; });
      if (chosen.length) out[cat] = chosen.join('、');
    });
    if (Object.keys(out).length < Math.min(3, cats.length)) {
      cats.forEach(function(cat){
        if (out[cat]) return;
        var first = _getWardrobe(personaId, cat, isUser).map(_drNormalizeWardrobeItem).filter(function(it){ return it.name; })[0];
        if (first && first.name && Object.keys(out).length < Math.min(5, cats.length)) out[cat] = first.name;
      });
    }
    if (!Object.keys(out).length) out = { '衣柜单品':'当前衣柜没有可用单品' };
    return out;
  }

  function _drManualPickerHtml(personaId, isUser, scopeId) {
    var cats = _getWardrobeCats(personaId, isUser);
    var blocks = cats.map(function(cat){
      var items = _getWardrobe(personaId, cat, isUser).map(_drNormalizeWardrobeItem).filter(function(x){ return x.name; });
      var rows = items.map(function(item, idx){
        var key = scopeId + '__' + encodeURIComponent(cat) + '__' + idx;
        var img = item.imageSrc ? '<img src="' + String(item.imageSrc).replace(/"/g,'&quot;') + '">' : '<div class="dr-shop-placeholder"><i class="fas fa-shirt"></i></div>';
        return '<div class="dr-manual-item">'
          + '<label class="dr-manual-item-top">'
          + '<span class="dr-manual-check"><input type="checkbox" data-manual-key="' + key + '" data-cat="' + _escapeHtml(cat) + '" data-name="' + _escapeHtml(item.name) + '" onchange="drManualToggleNote(this)"></span>'
          + '<div class="dr-shop-img">' + img + '</div>'
          + '<div class="dr-manual-item-name" title="' + _escapeHtml(item.name) + '">' + _escapeHtml(item.name) + '</div>'
          + '<div class="dr-shop-meta">' + _escapeHtml(cat + (item.source === 'upload' ? ' · 图片单品' : '')) + '</div>'
          + '</label>'
          + '<input class="dr-custom-input dr-manual-note" placeholder="这件单品怎么穿/戴（选填）" maxlength="40">'
          + '</div>';
      }).join('');
      return '<div class="dr-manual-cat"><div class="dr-manual-cat-title">' + _escapeHtml(cat) + '</div><div class="dr-manual-shop-grid">' + (rows || '<div class="dr-manual-empty">这个分类暂无单品</div>') + '</div></div>';
    }).join('');
    return '<div class="dr-manual-builder">' + (blocks || '<div class="dr-manual-empty">当前衣柜没有单品</div>') + '</div>';
  }

  window.drManualToggleNote = function(input) {
    if (!input) return;
    var wrap = input.closest ? input.closest('.dr-manual-item') : null;
    if (!wrap && input.parentNode) wrap = input.parentNode.parentNode;
    var note = wrap ? wrap.querySelector('.dr-manual-note') : null;
    if (wrap) wrap.classList.toggle('selected', !!input.checked);
    if (note) {
      note.style.display = input.checked ? 'block' : 'none';
      if (!input.checked) note.value = '';
    }
  };

  function _drCollectManualSelection(containerId) {
    var root = document.getElementById(containerId);
    var result = {};
    if (!root) return result;
    var inputs = root.querySelectorAll('input[type="checkbox"][data-cat][data-name]');
    inputs.forEach(function(cb){
      if (!cb.checked) return;
      var cat = cb.getAttribute('data-cat') || '其他';
      var name = cb.getAttribute('data-name') || '单品';
      var wrap = cb.closest ? cb.closest('.dr-manual-item') : cb.parentNode.parentNode;
      var note = wrap && wrap.querySelector('.dr-manual-note') ? wrap.querySelector('.dr-manual-note').value.trim() : '';
      var text = name + (note ? '（' + note + '）' : '');
      if (!result[cat]) result[cat] = [];
      result[cat].push(text);
    });
    return result;
  }

  function _drManualSelectionToOutfit(map) {
    var outfit = {};
    Object.keys(map || {}).forEach(function(cat){
      if (!map[cat] || !map[cat].length) return;
      outfit[cat] = map[cat].join('、');
    });
    return outfit;
  }

