    if (displayEl) displayEl.innerHTML = Object.entries(result.outfit).map(function(kv){ return kv[1] && kv[1] !== '无' ? '<div class="dr-outfit-item"><div class="dr-outfit-category">' + kv[0] + '</div><div class="dr-outfit-value">' + kv[1] + '</div></div>' : ''; }).join('') + '<div class="dr-outfit-reason">搭配方式：用户手动从衣柜选择并填写穿戴方式</div>';
    var coordStoryHintEl = document.getElementById('drCoordStoryContent');
    if (coordStoryHintEl) coordStoryHintEl.innerHTML = '<div style="font-size:12px;color:#bbb;">点击下方按钮生成这套穿搭触发的剧情</div>';
    await _drBuildAndShowSingleCollage(p.id, picked, targetIsUser, 'drCoordCollageWrap', 'drCoordCollagePreview', 'coord', _drState.coordRecordId, targetIsUser ? (_getUserProfile().name || '用户') : (p.name || '角色'), 'picked');
    var reactionTxt = await _generateReaction(p, result, 'drCoordReactionContent', !targetIsUser);
    var scoreTxt = await _generateScore(p, result, 'drCoordScoreGrid');
    _drUpdateRecord('coord', _drState.coordRecordId, { reactionText: reactionTxt || '', scoreText: scoreTxt || '' }, targetIsUser);
    var imgBtn = document.getElementById('drCoordGenImgBtn');
    if (imgBtn) imgBtn.style.display = p.allowImageGen === true ? 'flex' : 'none';
    _drToast('已完成手动搭配');
