  function _drCollectLocalStorageKeys() {
    var out = {};
    function addFromStore(store) {
      try {
        for (var i = 0; i < store.length; i++) {
          var k = store.key(i);
          if (!k) continue;
          if (/^mono_dr_/.test(k)) out[k] = store.getItem(k);
          var m = k.match(/^mono_mw_[^_]+_(mono_dr_.+)$/);
          if (m && !out[m[1]]) out[m[1]] = store.getItem(k);
        }
      } catch(e) {}
    }
    addFromStore(localStorage);
    try { if (window._monoRawLocalStorage) addFromStore(window._monoRawLocalStorage); } catch(e) {}
    return out;
  }

  function _drPersistBackupPack() {
    try {
      var pack = { version:'dressing-room-v1', savedAt:Date.now(), keys:_drCollectLocalStorageKeys() };
      localStorage.setItem('mono_dr_backup_pack_v1', JSON.stringify(pack));
      try { if (window._monoRawLocalStorage) window._monoRawLocalStorage.setItem('mono_dr_backup_pack_v1', JSON.stringify(pack)); } catch(e) {}
      try { if (window._monoIdbBlobSet) window._monoIdbBlobSet('mono_dr_backup_pack_v1', pack).catch(function(){}); } catch(e) {}
    } catch(e) {}
  }

  async function _drRestoreBackupPackIfNeeded() {
    try {
      var hasAny = Object.keys(_drCollectLocalStorageKeys()).some(function(k){ return k !== 'mono_dr_backup_pack_v1'; });
      var raw = localStorage.getItem('mono_dr_backup_pack_v1') || (window._monoRawLocalStorage && window._monoRawLocalStorage.getItem('mono_dr_backup_pack_v1')) || '';
      var pack = raw ? JSON.parse(raw) : null;
      if (!pack && window._monoIdbBlobGet) pack = await window._monoIdbBlobGet('mono_dr_backup_pack_v1').catch(function(){ return null; });
      if (!pack || !pack.keys) return;
      Object.keys(pack.keys).forEach(function(k){
        if (!/^mono_dr_/.test(k)) return;
        if (!hasAny || !localStorage.getItem(k)) localStorage.setItem(k, pack.keys[k]);
      });
    } catch(e) {}
  }

  window._monoCollectDressingRoomExport = function() {
    _drPersistBackupPack();
    return { version:'dressing-room-v1', exportedAt:Date.now(), keys:_drCollectLocalStorageKeys() };
  };

  window._monoRestoreDressingRoomImport = async function(pack) {
    try {
      var keys = pack && pack.keys ? pack.keys : {};
      Object.keys(keys).forEach(function(k){ if (/^mono_dr_/.test(k)) localStorage.setItem(k, keys[k]); });
      _drPersistBackupPack();
      if (typeof drRenderWardrobe === 'function') drRenderWardrobe();
      if (typeof _drRenderAllRecords === 'function') _drRenderAllRecords();
    } catch(e) {}
  };

  window._monoCollectDressingRoomImageAssetsForExport = function() {
    var out = { version:'dressing-room-images-v1', keys:{}, imageCount:0 };
    try {
      var all = _drCollectLocalStorageKeys();
      Object.keys(all).forEach(function(k){
        if (!/^mono_dr_/.test(k)) return;
        var raw = String(all[k] || '');
        if (!raw) return;
        if (/data:image\//i.test(raw)) {
          out.keys[k] = raw;
          var matches = raw.match(/data:image\//ig);
          out.imageCount += matches ? matches.length : 0;
        }
      });
    } catch(e) {}
    return out;
  };

  window._monoRestoreDressingRoomImageAssetsFromImport = async function(pack) {
    try {
      var keys = pack && pack.keys ? pack.keys : {};
      Object.keys(keys).forEach(function(k){
        if (!/^mono_dr_/.test(k)) return;
        localStorage.setItem(k, String(keys[k] || ''));
        try { if (window._monoRawLocalStorage) window._monoRawLocalStorage.setItem(k, String(keys[k] || '')); } catch(e) {}
      });
      _drPersistBackupPack();
      if (typeof drRenderWardrobe === 'function') drRenderWardrobe();
      if (typeof _drRenderAllRecords === 'function') _drRenderAllRecords();
    } catch(e) {}
  };

  // ── API helper: use the exact current chat API route/compat layer ──
  async function _drApiCall(prompt, maxTokens) {
    maxTokens = maxTokens || 600;
    var api = null;
    try {
      api = (typeof _getCurrentActiveApiConfig === 'function') ? _getCurrentActiveApiConfig() : null;
    } catch(e) { api = null; }
    if (!api || !api.url || !api.key) {
      try { api = (typeof apiConfig !== 'undefined') ? apiConfig : null; } catch(e) { api = null; }
    }
    if (typeof _normalizeApiConfigObject === 'function') api = _normalizeApiConfigObject(api || {});
    api = api || { url: '', key: '', model: '' };
    if (!api.url || !api.key) return '请先在聊天软件的 API 连接里配置当前 API';

    var strictJsonMode = /DR_STRICT_JSON_OUTPUT/.test(String(prompt || ''));
    var sysText = strictJsonMode
      ? '你是换装室的结构化造型生成器。你必须严格输出可被 JSON.parse 解析的 JSON；禁止输出 Markdown、解释、代码块、标题、前后缀。所有结果仍要贴合当前角色人设、记忆、聊天上下文和用户资料。'
      : '你是换装室的造型生成器。所有结果必须尽量贴合当前角色人设、记忆、聊天上下文和用户资料。';
    var payload = {
      messages: [
        { role: 'system', content: sysText },
        { role: 'user', content: prompt }
      ],
      temperature: strictJsonMode ? 0.25 : 0.92,
      max_tokens: maxTokens,
      stream: false
    };
    if (api.model && api.model !== 'AUTO_MODEL_SENTINEL' && api.model !== '__auto__') payload.model = api.model;

    function extractFromData(data) {
      try {
        if (typeof data === 'string') return data.trim();
        if (typeof _extractAssistantMessageContent === 'function') {
          var extracted = _extractAssistantMessageContent(data);
          if (extracted) return String(extracted).trim();
        }
        var c = data && data.choices && data.choices[0];
        var msg = c && c.message && c.message.content;
        if (Array.isArray(msg)) msg = msg.map(function(part){ return typeof part === 'string' ? part : (part && (part.text || part.content) || ''); }).join('');
        if (typeof msg === 'string') return msg.trim();
        if (typeof data.output_text === 'string') return data.output_text.trim();
        if (data && data.error) return typeof data.error === 'string' ? data.error : JSON.stringify(data.error);
        if (data && data.message) return String(data.message);
        return JSON.stringify(data);
      } catch(e) { return String(data || ''); }
    }

    try {
      var resp;
      if (typeof _compatibleChatCompletion === 'function') {
        // 关键修复：直接复用聊天软件里的 API 兼容层，支持当前悬浮 API / 副 API / OpenAI兼容 / Gemini / Claude / 反代。
        resp = await _compatibleChatCompletion(api.url, api.key, payload, {});
      } else {
        var ep = (typeof _buildApiChatCandidates === 'function' ? _buildApiChatCandidates(api.url)[0] : (String(api.url || '').replace(/\/$/, '') + '/chat/completions'));
        resp = await fetch(ep, {
          method: 'POST',
          headers: { 'Authorization': 'Bearer ' + api.key, 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
      }

      // 兼容层有些会直接返回字符串或 JSON 对象，不一定是原生 Response。
      if (typeof resp === 'string') return resp.trim();
      if (resp && typeof resp.json !== 'function' && typeof resp.text !== 'function') return extractFromData(resp);

      var rawText = '';
      if (resp && typeof resp.text === 'function') {
        try { rawText = await resp.text(); } catch(e) { rawText = ''; }
      }
      if (resp && resp.ok === false) {
        // 不再 throw；把 API 的异常原文作为生成内容交给页面兜底渲染，避免出现“解析失败”。
        return rawText || ('API 返回状态 ' + (resp.status || '异常'));
      }
      if (!rawText && resp && typeof resp.json === 'function') {
        try { return extractFromData(await resp.json()); } catch(e) { return ''; }
      }
      try { return extractFromData(JSON.parse(rawText)); }
      catch(e) { return String(rawText || '').trim(); }
    } catch(e) {
      // 网络/兼容层异常也不再向外抛出，让页面以普通内容展示。
      return (e && e.message) ? ('API连接返回：' + e.message) : 'API连接返回异常';
    }
  }

  function _drExtractBalancedJson(text, startChar) {
    var raw = String(text || '');
    var endChar = startChar === '[' ? ']' : '}';
    var start = raw.indexOf(startChar);
    while (start >= 0) {
      var depth = 0, inStr = false, esc = false;
      for (var i = start; i < raw.length; i++) {
        var ch = raw.charAt(i);
        if (inStr) {
          if (esc) esc = false;
          else if (ch === '\\') esc = true;
          else if (ch === '"') inStr = false;
          continue;
        }
        if (ch === '"') { inStr = true; continue; }
        if (ch === startChar) depth++;
        else if (ch === endChar) {
          depth--;
          if (depth === 0) return raw.slice(start, i + 1);
        }
      }
      start = raw.indexOf(startChar, start + 1);
    }
    return '';
  }

  function _safeParseJSON(raw, preferredShape) {
    if (raw == null) return null;
    if (typeof raw === 'object') return raw;
    var text = String(raw)
      .replace(/^\uFEFF/, '')
      .replace(/```(?:json|JSON)?/g, '')
      .replace(/```/g, '')
      .trim();
    function tryParse(t) { try { return JSON.parse(t); } catch(e) { return null; } }
    function repair(t) {
      return String(t || '')
        .replace(/[“”]/g, '"')
        .replace(/[‘’]/g, "'")
        .replace(/[，]/g, ',')
        .replace(/[：]/g, ':')
        .replace(/\/\*[\s\S]*?\*\//g, '')
        .replace(/(^|[^:])\/\/.*$/gm, '$1')
        .replace(/,\s*([}\]])/g, '$1');
    }
    var direct = tryParse(text) || tryParse(repair(text));
    if (direct) return direct;

    if (typeof _parseJsonFromText === 'function') {
      try {
        var parsedByMain = _parseJsonFromText(text, null, preferredShape || 'object');
        if (parsedByMain) return parsedByMain;
      } catch(e) {}
    }

    var shapes = preferredShape === 'array' ? ['[', '{'] : ['{', '['];
    for (var i = 0; i < shapes.length; i++) {
      var snippet = _drExtractBalancedJson(text, shapes[i]);
      if (!snippet) continue;
      var parsed = tryParse(snippet) || tryParse(repair(snippet));
      if (parsed) return parsed;
    }
    return null;
  }

  async function _drCallJSON(prompt, maxTokens, preferredShape) {
    var raw = await _drApiCall(prompt, maxTokens);
    // 不再二次请求/重新生成：只在本地做 JSON 提取与宽容解析，避免重复扣费和内容变掉。
    return _safeParseJSON(raw, preferredShape || 'object');
  }

  // ── Strict JSON prompt helper: 从源头要求 API 返回准确 JSON，而不是事后重新生成 ──
  function _drStrictJsonRules(schemaText, extraRules) {
    return '\n\n【DR_STRICT_JSON_OUTPUT】' +
      '\n你现在进入严格 JSON 输出模式。必须逐条遵守：' +
      '\n1. 最终回答只能是一个合法 JSON，不能出现 Markdown、```json、解释、标题、前后缀、问候语。' +
      '\n2. JSON 必须可被 JSON.parse 直接解析；所有 key 必须使用英文双引号。' +
      '\n3. 字符串值必须使用英文双引号；禁止使用中文引号、单引号、注释、尾随逗号。' +
      '\n4. 禁止在 JSON 之外输出任何字符；第一个字符必须是 ' + (String(schemaText || '').trim().charAt(0) === '[' ? '[' : '{') + '，最后一个字符必须是 ' + (String(schemaText || '').trim().charAt(0) === '[' ? ']' : '}') + '。' +
      '\n5. 必须严格使用下面的字段名和层级，不要新增外层字段，不要把 JSON 写成自然语言。' +
      '\n6. 没有内容的字段也要保留，用 "无" 或空字符串 ""，不要省略字段。' +
      '\n【唯一允许的 JSON 结构】\n' + schemaText +
      (extraRules ? '\n【字段内容要求】\n' + extraRules : '') +
      '\n再次确认：只输出 JSON 本体。';
  }


  // ── JSON Parse 兜底：绝不因为 JSON parse 失败而中断显示 / 不二次请求 API ──
  function _drCleanRawText(raw) {
    return String(raw == null ? '' : raw)
      .replace(/```(?:json|JSON|javascript|js)?/g, '')
      .replace(/```/g, '')
      .replace(/^\s*(好的|可以|当然|以下是|输出|结果)[:：，,。\s]*/i, '')
      .trim();
  }

  function _drPickFieldText(raw, names) {
    var text = _drCleanRawText(raw);
    for (var i = 0; i < names.length; i++) {
      var n = names[i];
      var re = new RegExp('(?:^|[\\n,，;；])\\s*["“”]?' + n + '["“”]?\\s*[:：-]\\s*([^\\n,，;；]+)', 'i');
      var m = text.match(re);
      if (m && m[1]) return m[1].replace(/["“”]/g, '').trim();
    }
    return '';
  }

  function _drStringifyFieldValue(v) {
    function flat(x) {
      if (x == null) return '';
      if (typeof x === 'string' || typeof x === 'number' || typeof x === 'boolean') return String(x).trim();
      if (Array.isArray(x)) return x.map(flat).filter(Boolean).join('，');
      if (typeof x === 'object') {
        var preferred = [x.desc, x.description, x.text, x.content, x.item, x.name, x.单品, x.描述, x.款式, x.style, x.value];
        var hit = preferred.map(flat).filter(Boolean).find(Boolean);
        if (hit) return hit;
        return Object.keys(x).map(function(k){ return flat(x[k]); }).filter(Boolean).join('，');
      }
      return '';
    }
    var s = flat(v)
      .replace(/^['"“”]+|['"“”]+$/g, '')
      .replace(/^[:：\-\s]+/, '')
      .replace(/[\r\n]+/g, ' ')
      .replace(/\s{2,}/g, ' ')
      .trim();
    if (/^[\[{(]+$/.test(s)) return '';
    if (/^(object\s*object|undefined|null|nan)$/i.test(s)) return '';
    return s;
  }

  function _drGuessOutfitCategory(label, value) {
    var s = String((label || '') + ' ' + (value || '')).toLowerCase();
    if (/外套|大衣|风衣|夹克|开衫|西装|blazer|jacket|coat|outer|cardigan/.test(s)) return '外套';
    if (/鞋|靴|拖鞋|凉鞋|高跟|运动鞋|sneaker|loafer|boot|shoes|shoe|heels|sandals/.test(s)) return '鞋';
    if (/裤|裙|短裤|长裤|牛仔裤|半裙|裤装|下装|bottom|pants|trousers|jeans|skirt|shorts/.test(s)) return '下装';
    if (/上衣|上装|衬衫|t恤|tee|卫衣|毛衣|针织|背心|吊带|内衬|打底|shirt|top|blouse|hoodie|sweater|knit|camisole/.test(s)) return '上装';
    if (/配饰|饰品|耳机|项链|戒指|手链|眼镜|包|帽|围巾|领带|耳环|手表|腰带|发夹|accessor|headphone|earphone|airpods|necklace|ring|bracelet|glasses|bag|hat|scarf|tie|earring|watch|belt/.test(s)) return '配饰';
    return '';
  }

  function _drInferOutfitFromText(text) {
    text = _drCleanRawText(text || '');
    var out = { '上装':'', '下装':'', '外套':'', '鞋':'', '配饰':'' };
    if (!text) return out;
    // First try explicit category patterns in one-line or multi-line text.
    [
      ['上装', /(?:^|[\n；;,，])\s*(?:上装|上衣|top|tops)\s*[:：=\-]\s*([^\n；;]+)/i],
      ['下装', /(?:^|[\n；;,，])\s*(?:下装|裤子|裙子|bottom|bottoms)\s*[:：=\-]\s*([^\n；;]+)/i],
      ['外套', /(?:^|[\n；;,，])\s*(?:外套|外层|outer|jacket|coat)\s*[:：=\-]\s*([^\n；;]+)/i],
      ['鞋', /(?:^|[\n；;,，])\s*(?:鞋|鞋子|shoes|shoe)\s*[:：=\-]\s*([^\n；;]+)/i],
      ['配饰', /(?:^|[\n；;,，])\s*(?:配饰|饰品|accessory|accessories)\s*[:：=\-]\s*([^\n；;]+)/i]
    ].forEach(function(pair){
      var m = text.match(pair[1]);
      if (m && m[1]) out[pair[0]] = _drStringifyFieldValue(m[1]);
    });
    // Then scan free-form lines / bullet points and classify them by content.
    text.split(/[\n；;]+/).forEach(function(line){
      line = String(line || '').replace(/^\s*[-*•\d.、)）]+\s*/, '').trim();
      if (!line) return;
      var m = line.match(/^([^:：=\-]{1,12})\s*[:：=\-]\s*(.+)$/);
      var label = m ? m[1].trim() : '';
      var val = _drStringifyFieldValue(m ? m[2] : line);
      if (!val || /^(无|none|null)$/i.test(val)) return;
      var cat = _drGuessOutfitCategory(label, val);
      if (cat && !out[cat]) out[cat] = val;
    });
    return out;
  }

  function _drNormalizeOutfitMap(obj) {
    var out = { '上装':'', '下装':'', '外套':'', '鞋':'', '配饰':'' };
    if (!obj || typeof obj !== 'object') return out;
    if (obj.outfit && typeof obj.outfit === 'object') obj = obj.outfit;
    var keyMap = {
      '上装':'上装','上衣':'上装','内搭':'上装','内衬':'上装','打底':'上装','衣服':'上装','上半身':'上装','upper':'上装','upperbody':'上装','upper_body':'上装','top':'上装','tops':'上装','shirt':'上装','blouse':'上装','hoodie':'上装','sweater':'上装',
      '下装':'下装','裤子':'下装','裤装':'下装','裙子':'下装','半裙':'下装','下半身':'下装','lower':'下装','lowerbody':'下装','lower_body':'下装','bottom':'下装','bottoms':'下装','pants':'下装','trousers':'下装','skirt':'下装','shorts':'下装',
      '外套':'外套','外层':'外套','外搭':'外套','大衣':'外套','夹克':'外套','outerwear':'外套','outer':'外套','jacket':'外套','coat':'外套','blazer':'外套','cardigan':'外套',
      '鞋':'鞋','鞋子':'鞋','鞋履':'鞋','footwear':'鞋','shoes':'鞋','shoe':'鞋','boots':'鞋','sneakers':'鞋',
      '包':'配饰','包包':'配饰','配饰':'配饰','饰品':'配饰','首饰':'配饰','耳机':'配饰','项链':'配饰','戒指':'配饰','眼镜':'配饰','帽子':'配饰','accessory':'配饰','accessories':'配饰','jewelry':'配饰','bag':'配饰','hat':'配饰','headphones':'配饰'
    };
    Object.keys(obj).forEach(function(rawKey){
      var rawVal = obj[rawKey];
      var keyRaw = String(rawKey || '').trim();
      var keyNorm = keyRaw.toLowerCase().replace(/[\s\-_]/g, '');
      var normalizedKey = keyMap[keyRaw] || keyMap[keyRaw.toLowerCase()] || keyMap[keyNorm] || _drGuessOutfitCategory(keyRaw, rawVal);
      if (!normalizedKey) return;
      var val = _drStringifyFieldValue(rawVal);
      if (val) out[normalizedKey] = val;
    });
    return out;
  }

  function _drEnsureCompleteOutfit(outfit) {
    var base = { '上装':'无', '下装':'无', '外套':'无', '鞋':'无', '配饰':'无' };
    outfit = outfit && typeof outfit === 'object' ? outfit : {};
    Object.keys(outfit).forEach(function(k){
      var v = _drStringifyFieldValue(outfit[k]);
      if (!v || v === '无') return;
      if (base.hasOwnProperty(k)) {
        base[k] = v;
      } else {
        var guessed = _drGuessOutfitCategory(k, v);
        if (guessed && base[guessed] === '无') base[guessed] = v;
        else base[k] = v; // keep extra category instead of losing API content
      }
    });
    var knownHas = ['上装','下装','外套','鞋','配饰'].some(function(k){ return base[k] && base[k] !== '无'; });
    if (!knownHas) {
      var extra = Object.keys(base).filter(function(k){ return !({ '上装':1,'下装':1,'外套':1,'鞋':1,'配饰':1 })[k] && base[k] && base[k] !== '无'; }).map(function(k){ return k + '：' + base[k]; }).join('；');
      if (extra) base['上装'] = extra.slice(0, 180);
    }
    return base;
  }

  function _drCoerceOutfit(raw, parsed) {
    var text = _drCleanRawText(raw);
    var outfit = null, reason = '', vibe = '';

    if (parsed && parsed.outfit && typeof parsed.outfit === 'object') {
      outfit = _drNormalizeOutfitMap(parsed.outfit);
      reason = _drStringifyFieldValue(parsed.reason || parsed.理由 || parsed['选装理由']);
      vibe = _drStringifyFieldValue(parsed.vibe || parsed.氛围 || parsed['整体氛围']);
    }
    if (!outfit && parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      var candidate = _drNormalizeOutfitMap(parsed);
      var hasCat = Object.keys(candidate).some(function(k){ return candidate[k]; });
      if (hasCat) {
        outfit = candidate;
        reason = _drStringifyFieldValue(parsed.reason || parsed.理由 || parsed['选装理由']);
        vibe = _drStringifyFieldValue(parsed.vibe || parsed.氛围 || parsed['整体氛围']);
      }
    }

    if (!outfit) {
      outfit = _drInferOutfitFromText(text);
      reason = _drStringifyFieldValue(_drPickFieldText(text, ['reason','理由','选装理由','搭配理由'])) || '';
      vibe = _drStringifyFieldValue(_drPickFieldText(text, ['vibe','氛围','整体氛围'])) || '';
    }

    var found = Object.keys(outfit).some(function(k){ return _drStringifyFieldValue(outfit[k]); });
    if (!found) {
      var rawShort = text || 'API 已返回内容，但格式不是 JSON。';
      outfit = { '上装': rawShort.slice(0, 180) };
    }
    Object.keys(outfit).forEach(function(k){ outfit[k] = _drStringifyFieldValue(outfit[k]); });
    outfit = _drEnsureCompleteOutfit(outfit);
    return { outfit: outfit, reason: reason, vibe: vibe };
  }

  function _drCoerceStringArray(raw, parsed) {
    if (Array.isArray(parsed)) return parsed.map(function(x){ return typeof x === 'string' ? x : (x && (x.name || x.item || x.text || x.单品)) || ''; }).filter(Boolean);
    if (parsed && typeof parsed === 'object') {
      var arr = parsed.items || parsed.list || parsed.data || parsed.result || parsed.单品 || parsed.推荐;
      if (Array.isArray(arr)) return _drCoerceStringArray('', arr);
    }
    var text = _drCleanRawText(raw);
    return text.split(/[\n；;]+/).map(function(line){
      return line.replace(/^\s*[-*•\d.、)）]+\s*/, '').replace(/^['"“”]|['"“”]$/g, '').trim();
    }).filter(function(x){ return x && x.length > 1; }).slice(0, 8);
  }

  function _drCleanScoreText(v) {
    function flatten(x) {
      if (x == null) return '';
      if (typeof x === 'number' || typeof x === 'boolean') return String(x);
      if (Array.isArray(x)) return x.map(flatten).filter(Boolean).join('；');
      if (typeof x === 'object') {
        var preferred = [
          x.summary, x.comment, x.evaluation, x.verdict, x.review,
          x.text, x.content, x.description, x.desc, x.analysis,
          x.reason, x.value, x.score, x.result
        ];
        var hit = preferred.map(flatten).filter(Boolean).find(Boolean);
        if (hit) return hit;
        return Object.keys(x).map(function(k){ return flatten(x[k]); }).filter(Boolean).join('；');
      }
      var raw = _drCleanRawText(x);
      var looksJsonLike = /^[\[{]/.test(raw) || /"(overallScore|summary|scores|label|value|comment|evaluation|verdict|review|text|content)"/i.test(raw);
      if (looksJsonLike) {
        var parsed = _safeParseJSON(raw);
        if (parsed && parsed !== x) {
          var parsedText = flatten(parsed);
          if (parsedText) return parsedText;
        }
      }
      var picked = _drPickFieldText(raw, ['summary','comment','evaluation','verdict','review','value','content','text','评语','评价','总评','说明']);
      return picked || raw;
    }
    var s = flatten(v)
      .replace(/^['"“”`]+|['"“”`]+$/g, '')
      .replace(/\\n/g, ' ')
      .replace(/[*`#>]+/g, ' ')
      .replace(/\b(overallScore|summary|scores|label|value|comment|evaluation|verdict|review|content|text)\b\s*[:：]/gi, '')
      .replace(/^\s*(summary|comment|evaluation|verdict|review|value|content|text|总评|评价|评语|说明)\s*[:：-]\s*/i, '')
      .replace(/[{}[\]]/g, ' ')
      .replace(/(^|\s)[,，;；]+/g, '$1')
      .replace(/\s{2,}/g, ' ')
      .trim();
    if (/^(object\s*object|undefined|null|nan)$/i.test(s)) return '';
    return s;
  }

  function _drCleanScoreLabel(v) {
    var s = _drCleanScoreText(v)
      .replace(/^\s*(label|title|name|项目|评分项)\s*[:：-]\s*/i, '')
      .trim();
    if (s.length > 24) s = s.slice(0, 24).trim();
    return s || 'AI评分';
  }

  function _drCoerceScores(raw, parsed) {
    function normalizeEntries(arr) {
      return (Array.isArray(arr) ? arr : []).map(function(s) {
        if (s == null) return null;
        if (typeof s !== 'object') return { label: 'AI评分', value: _drCleanScoreText(s) || '待补充' };
        var label = _drCleanScoreLabel(s.label || s.name || s.title || s.key || 'AI评分');
        var value = s.value;
        if (value && typeof value === 'object') value = value.value != null ? value.value : value.score != null ? value.score : value;
        value = (typeof value === 'number') ? value : _drCleanScoreText(value);
        if (/^\d{1,3}$/.test(String(value))) value = Math.max(0, Math.min(100, parseInt(value, 10)));
        if (!label) label = 'AI评分';
        if (value === '' || value == null) value = '待补充';
        return { label: label, value: value };
      }).filter(Boolean).slice(0, 6);
    }
    function normalizeSummary(obj, textFallback) {
      var overall = obj && (obj.overallScore != null ? obj.overallScore : obj.totalScore != null ? obj.totalScore : obj.score != null ? obj.score : '');
      if (/^\d{1,3}$/.test(String(overall))) overall = Math.max(0, Math.min(100, parseInt(overall, 10)));
      var summary = _drCleanScoreText(obj && (obj.summary || obj.comment || obj.evaluation || obj.verdict || obj.review) || textFallback || '');
      return { overallScore: overall, summary: summary };
    }
    if (parsed && parsed.scores && Array.isArray(parsed.scores)) {
      var meta = normalizeSummary(parsed, '');
      return { scores: normalizeEntries(parsed.scores), overallScore: meta.overallScore, summary: meta.summary };
    }
    if (parsed && parsed.scores && typeof parsed.scores === 'object') {
      var metaObj = normalizeSummary(parsed, '');
      var scoreEntries = Object.keys(parsed.scores).map(function(k){ return { label: k, value: parsed.scores[k] }; });
      return { scores: normalizeEntries(scoreEntries), overallScore: metaObj.overallScore, summary: metaObj.summary };
    }
    if (Array.isArray(parsed)) return { scores: normalizeEntries(parsed), overallScore: '', summary: '' };
    var text = _drCleanRawText(raw);
    var scores = [];
    text.split(/[\n；;]/).forEach(function(line){
      var m = line.match(/^\s*[-*•\d.、)）]*\s*([^:：-]{2,12})\s*[:：-]\s*(.+?)\s*$/);
      if (m) scores.push({ label: _drCleanScoreLabel(m[1]), value: _drCleanScoreText(m[2]) });
    });
    if (!scores.length && text) scores.push({ label: 'AI评价', value: _drCleanScoreText(text).slice(0, 120) });
    if (!scores.length) scores = [{ label: 'AI评价', value: '本次评分未结构化返回' }];
    return { scores: normalizeEntries(scores), overallScore: '', summary: _drCleanScoreText(text).slice(0, 120) };
  }

  function _drLooksLikeTemplateScores(scores) {
    scores = Array.isArray(scores) ? scores : [];
    if (!scores.length) return true;
    var labels = scores.map(function(s){ return String(s && s.label || '').trim(); });
    var values = scores.map(function(s){ return String(s && s.value == null ? '' : s.value).trim(); });
    var labelJoined = labels.join(' | ');
    var genericCount = labels.filter(function(label){ return /^评分项[\d一二三四五六七八九十a-z]*$/i.test(label) || /^ai评分|ai评价$/i.test(label); }).length;
    var suspiciousLabels = /适配人设|暧昧张力|被搭讪概率|角色本人满意度|触发剧情|氛围感|对视升温度|情侣默契指数|路人回头率/.test(labelJoined);
    var suspiciousValues = values.filter(function(v){ return /^(92|88|90|81|76|高|很高|偏高|很顺)$/.test(v); }).length >= Math.min(3, values.length);
    return genericCount >= Math.min(2, labels.length) || suspiciousLabels || suspiciousValues;
  }
  function _drScoreSummaryId(targetGridId) {
    if (targetGridId === 'drScoreGrid') return 'drScoreSummary';
    if (targetGridId === 'drCoordScoreGrid') return 'drCoordScoreSummary';
    if (targetGridId === 'drCoupleScoreGrid') return 'drCoupleScoreSummary';
    return '';
  }
  function _drRenderScoreSummary(targetGridId, result) {
    var id = _drScoreSummaryId(targetGridId);
    if (!id) return;
    var el = document.getElementById(id);
    if (!el) return;
    var overall = result && result.overallScore;
    var summary = String(result && result.summary || '').trim();
    if (!summary && overall === '') {
      el.style.display = 'none';
      el.innerHTML = '';
      return;
    }
    var main = overall !== '' ? ('总评得分：' + overall + ' / 100') : '评委总评';
    el.innerHTML = '<div class="dr-score-summary-title">评委总评</div><div class="dr-score-summary-main">' + _escapeHtml(main) + '</div>' + (summary ? '<div class="dr-score-summary-text">' + _escapeHtml(summary) + '</div>' : '');
    el.style.display = 'block';
  }

  function _drRecentRecordSnippet(rec) {
    if (!rec) return '';
    var outfitText = rec.outfit ? _drOutfitItemsText(rec.outfit) : [rec.userOutfit, rec.charOutfit].filter(Boolean).join(' / ');
    var vibeText = [rec.vibe, rec.reason, rec.eval, rec.occasion].filter(Boolean).join('；');
    return [outfitText, vibeText].filter(Boolean).join(' ｜ ').slice(0, 220);
  }
  function _drBuildRecentAvoidHint(personaId, isUser, includeCouple) {
    var rows = [];
    ['today','coord'].forEach(function(type){
      _drGetRecords(type, personaId, isUser).slice(0, 3).forEach(function(rec){
        var s = _drRecentRecordSnippet(rec);
        if (s) rows.push(type + '：' + s);
      });
    });
    if (includeCouple) {
      _drGetRecords('couple', personaId, isUser).slice(0, 2).forEach(function(rec){
        var s = _drRecentRecordSnippet(rec);
        if (s) rows.push('couple：' + s);
      });
    }
    if (!rows.length) return '';
    return '\n\n【最近已生成过的方向，尽量避开重复】\n' + rows.join('\n') + '\n请主动避开这些最近结果里已经出现过的主色调、版型组合、鞋履路线、配饰组合、氛围关键词和常见套话，不要只做轻微改字。';
  }

  function _drCoerceCouple(raw, parsed) {
    if (parsed && (parsed.userOutfit || parsed.charOutfit || parsed.eval)) return parsed;
    var text = _drCleanRawText(raw);
    return {
      userOutfit: _drPickFieldText(text, ['userOutfit','用户穿搭','我的穿搭','用户']) || text.slice(0, 120),
      charOutfit: _drPickFieldText(text, ['charOutfit','角色穿搭','角色']) || text.slice(120, 240) || text.slice(0, 120),
      eval: _drPickFieldText(text, ['eval','评价','氛围']) || text.slice(0, 90)
    };
  }


  // ── Dressing Room gender overrides ──
  function _drGenderLabel(v) {
    v = String(v || '').trim().toLowerCase();
    if (v === 'male' || v === '男' || v === '男性') return '男';
    if (v === 'female' || v === '女' || v === '女性') return '女';
    if (v === 'other' || v === 'neutral' || v === '中性' || v === '其他') return '其他/中性';
    return '';
  }
  function _drGenderCode(v) {
    v = String(v || '').trim().toLowerCase();
    if (/^(male|man|boy|男|男性|男生)$/.test(v)) return 'male';
    if (/^(female|woman|girl|女|女性|女生)$/.test(v)) return 'female';
    if (/^(other|neutral|nonbinary|non-binary|中性|其他|非二元)$/.test(v)) return 'other';
    return '';
  }
  function _drGenderKey(type, personaId) { return 'mono_dr_gender_' + type + '_' + (personaId || 'default'); }
  function _drGetGenderOverride(type, personaId) {
    try { return localStorage.getItem(_drGenderKey(type, personaId || _drState.selectedPersonaId)) || ''; } catch(e) { return ''; }
  }
  function _drGetPersonaGender(persona) {
    var id = persona && persona.id || _drState.selectedPersonaId;
    return _drGenderLabel(_drGetGenderOverride('char', id)) || _drGenderLabel(persona && (persona.gender || persona.sex || persona.roleGender || persona.selfGender)) || '未知';
  }
  function _drGetUserGender(personaId) {
    var ov = _drGenderLabel(_drGetGenderOverride('user', personaId || _drState.selectedPersonaId));
    if (ov) return ov;
    var up = _getUserProfile();
    return _drGenderLabel(up.gender || up.sex || up.userGender) || '未知';
  }
  function _drRefreshGenderControls() {
    var pid = _drState.selectedPersonaId || '';
    var cs = document.getElementById('drCharGenderSelect');
    var us = document.getElementById('drUserGenderSelect');
    if (cs) cs.value = _drGenderCode(_drGetGenderOverride('char', pid));
    if (us) us.value = _drGenderCode(_drGetGenderOverride('user', pid));
  }
  window.drSetDressingGender = function(type, value) {
    var pid = _drState.selectedPersonaId || 'default';
    value = _drGenderCode(value);
    try {
      if (value) localStorage.setItem(_drGenderKey(type, pid), value);
      else localStorage.removeItem(_drGenderKey(type, pid));
      try { _drPersistBackupPack(); } catch(e) {}
    } catch(e) {}
    drSetCoordMode(_drState.coordMode);
    _drToast((type === 'char' ? '角色性别' : '我的性别') + (value ? '已设为：' + _drGenderLabel(value) : '已改为自动读取'));
  };

  // ── Get current persona ──
  function _getCurrentPersona() {
    if (!_drState.selectedPersonaId) return null;
    try {
      var ps = JSON.parse(localStorage.getItem('mono_personas') || '[]');
      return ps.find(function(p) { return String(p.id) === String(_drState.selectedPersonaId); }) || null;
    } catch(e) { return null; }
  }

  // ── Get recent chat history ──
  function _getRecentHistory(personaId) {
    try {
      var hist = JSON.parse(localStorage.getItem('mono_hist_' + personaId) || '[]');
      return hist.slice(-30).map(function(m) { return (m.role === 'user' ? '用户' : '角色') + '：' + (m.content || '').substring(0, 120); }).join('\n');
    } catch(e) { return ''; }
  }

  // ── Get core memory ──
  function _getCoreMemory(persona) {
    if (!persona || !persona.memoryCore) return '';
    return Array.isArray(persona.memoryCore) ? persona.memoryCore.map(function(m) { return m.content || m; }).join('\n') : '';
  }

  // ── Get user profile ──
  function _getUserProfile() {
    try {
      var up = typeof userProfile !== 'undefined' ? userProfile : JSON.parse(localStorage.getItem('mono_user_profile') || '{}');
      return up || {};
    } catch(e) { return {}; }
  }

  // ── Build persona context string ──
  function _buildPersonaContext(persona) {
    if (!persona) return '';
    var gender = _drGetPersonaGender(persona);
    var ctx = '角色名：' + persona.name + '\n';
    if (gender && gender !== '未知') ctx += '换装室锁定性别：' + gender + '（生成造型必须服从）\n';
    ctx += '人设：' + (persona.persona || '').substring(0, 500) + '\n';
    var mem = _getCoreMemory(persona);
    if (mem) ctx += '核心记忆：' + mem.substring(0, 300) + '\n';
    var hist = _getRecentHistory(persona.id);
    if (hist) ctx += '近期聊天记录（最近30条）：\n' + hist.substring(0, 1000) + '\n';
    return ctx;
  }

  // ── Toast ──
  function _drToast(msg) {
    var t = document.getElementById('drToast');
    if (!t) return;
    t.textContent = msg;
    t.classList.add('show');
    setTimeout(function() { t.classList.remove('show'); }, 2200);
  }

  // ── Set button loading state ──
  function _setBtnLoading(btnId, loading, icon, label) {
    var btn = document.getElementById(btnId);
    if (!btn) return;
    btn.disabled = loading;
    if (loading) {
      btn.innerHTML = '<span class="dr-spinner"></span><span>生成中…</span>';
    } else {
      btn.innerHTML = '<i class="fas ' + icon + '"></i><span>' + label + '</span>';
    }
  }

  // ── Shimmer placeholder ──
  function _shimmer(n) {
    var html = '<div class="dr-loading">';
    for (var i = 0; i < (n || 3); i++) {
      html += '<div class="dr-shimmer" style="width:' + (60 + Math.random() * 35) + '%;height:' + (i === 0 ? 14 : 12) + 'px;"></div>';
    }
    return html + '</div>';
  }

  // ── Open / Close ──
  window.openDressingRoomApp = function() {
    if (typeof _showAppPage === 'function') _showAppPage('dressingRoomPage');
    drInitUI();
  };
  window.closeDressingRoomApp = function() {
    if (typeof openApp === 'function') {
      document.getElementById('dressingRoomPage').style.display = 'none';
      document.getElementById('dressingRoomPage').classList.remove('active');
      document.getElementById('homeScreen').style.display = '';
    }
  };

  // ── Tab switching ──
  window.drSwitchTab = function(tab) {
    _drState.currentTab = tab;
    document.querySelectorAll('.dr-tab').forEach(function(el) {
      el.classList.toggle('active', el.dataset.tab === tab);
    });
    document.querySelectorAll('.dr-tab-content').forEach(function(el) {
      el.classList.toggle('active', el.id === 'drTab-' + tab);
    });
    if (tab === 'wardrobe') drRenderWardrobe();
    if (tab === 'memories') drRenderMemories();
    _drRenderAllRecords();
  };

  function drApplyModeUI() {
    var isUser = _drState.mode === 'user';
    var p = _getCurrentPersona();
    var tabs = document.getElementById('drTabs');
    var todayTitle = document.getElementById('drTodayTitle');
    var todayImgTitle = document.getElementById('drTodayImageTitle');
    var genTodayBtn = document.getElementById('drGenTodayBtn');
    var charBtn = document.getElementById('drCoordModeCharBtn');
    var userBtn = document.getElementById('drCoordModeUserBtn');
    var hint = document.getElementById('drCoordRolePickHint');
    if (todayTitle) todayTitle.innerHTML = isUser ? '<i class="fas fa-sun"></i>我的今日造型' : '<i class="fas fa-sun"></i>角色今日造型';
    if (todayImgTitle) todayImgTitle.innerHTML = isUser ? '<i class="fas fa-camera"></i>我的今日形象' : '<i class="fas fa-camera"></i>角色今日形象';
    if (genTodayBtn) genTodayBtn.querySelector('span') && (genTodayBtn.querySelector('span').textContent = isUser ? '生成我的今日穿搭' : '生成角色今日穿搭');
    if (charBtn) charBtn.style.display = isUser ? 'none' : '';
    if (userBtn) userBtn.style.display = isUser ? '' : 'none';
    if (hint) hint.style.display = isUser ? 'block' : 'none';
    _drState.coordMode = isUser ? 'user' : 'char';
    var todayEl = document.getElementById('drTodayOutfitDisplay');
    if (todayEl && !_drState.todayOutfit) todayEl.innerHTML = '<div class="dr-empty"><i class="fas fa-tshirt"></i>' + (isUser ? '选择上方角色后，让TA帮你生成今天的穿搭' : '点击生成这个角色今天的穿搭') + '</div>';
    drSetCoordMode(_drState.coordMode);
    drRenderCoordManualBuilder();
    drRenderCoupleManualBuilders();
  }

  // ── Mode switch (char/user) ──
  window.drSwitchMode = function() {
    _drState.mode = _drState.mode === 'char' ? 'user' : 'char';
    var btn = document.getElementById('drModeBtn');
    if (btn) {
      if (_drState.mode === 'char') {
        btn.innerHTML = '<i class="fas fa-user"></i>角色';
      } else {
        btn.innerHTML = '<i class="fas fa-user-circle"></i>我的';
      }
    }
    _drState.todayOutfit = null;
    _drState.coordOutfit = null;
    _drState.coupleOutfit = null;
    _drWardrobeSelection = {};
    ['drTodayReactionCard','drTodayScoreCard','drTodayImageCard','drTodayStoryCard','drCoordResultCard','drCoordScoreCard','drCoordStoryCard','drCoupleResultCard','drCoupleScoreCard','drCoupleStoryCard','drCoupleImageCard'].forEach(function(cardId){ var el=document.getElementById(cardId); if(el) el.style.display='none'; });
    _drClearCollagePreview('drTodayCollageWrap', 'drTodayCollagePreview');
    _drClearCollagePreview('drCoordCollageWrap', 'drCoordCollagePreview');
    _drClearCollagePreview('drCoupleCollageWrap', 'drCoupleCollagePreview');
    drApplyModeUI();
    drRenderWardrobe();
    _drUpdateWardrobeActionBar();
    if (_drState.currentTab === 'memories') drRenderMemories();
    _drRenderAllRecords();
    _drToast(_drState.mode === 'char' ? '切换为：角色页面' : '切换为：我的页面，可选择角色帮我搭配');
  };

  // ── Coordination mode ──
  window.drSetCoordMode = function(mode) {
    // 用户页面只允许“帮我搭配”；角色页面只允许“帮角色搭配”。
    mode = (_drState.mode === 'user') ? 'user' : 'char';
    _drState.coordMode = mode;
    var charBtn = document.getElementById('drCoordModeCharBtn');
    var userBtn = document.getElementById('drCoordModeUserBtn');
    if (charBtn) charBtn.classList.toggle('active', mode === 'char');
    if (userBtn) userBtn.classList.toggle('active', mode === 'user');
    var info = document.getElementById('drCoordModeInfo');
    var p = _getCurrentPersona();
    if (info) {
      if (mode === 'char') info.textContent = p ? '角色页面：你在给 ' + p.name + ' 搭配造型。' : '请先选择角色';
      else info.textContent = p ? '我的页面：已选择 ' + p.name + ' 来帮你搭配造型。' : '请先选择一个角色来帮你搭配';
    }
    drRenderCoordManualBuilder();
  };

  // ── Couple mode ──
  window.drSetCoupleMode = function(mode) {
    _drState.coupleMode = mode;
    document.getElementById('drCoupleAutoBtn').classList.toggle('active', mode === 'auto');
    document.getElementById('drCoupleManualBtn').classList.toggle('active', mode === 'manual');
    var picker = document.getElementById('drCoupleStylePicker');
    if (picker) picker.style.display = mode === 'manual' ? 'flex' : 'none';
    var custom = document.getElementById('drCoupleCustomStyleInput');
    if (custom) custom.style.display = mode === 'manual' ? 'block' : 'none';
  };

  // ── Init UI ──
  async function drInitUI() {
    await _drRestoreBackupPackIfNeeded();
    drRenderPersonaStrip();
    _drRefreshGenderControls();
    drSwitchTab(_drState.currentTab);
    drApplyModeUI();
    _initOccasionChips();
    _initCoupleStyleChips();
    drRenderWardrobe();
    drRenderCoordManualBuilder();
    drRenderCoupleManualBuilders();
    _drRenderAllRecords();
  }

  // ── Persona strip ──
  function drRenderPersonaStrip() {
    var strip = document.getElementById('drPersonaStrip');
    if (!strip) return;
    var ps = [];
    try { ps = JSON.parse(localStorage.getItem('mono_personas') || '[]'); } catch(e) {}
    if (!ps.length) {
      strip.innerHTML = '<div style="font-size:12px;color:#bbb;padding:8px 0;">没有角色，请先创建角色</div>';
      return;
    }
    // Auto-select first if none selected
    if (!_drState.selectedPersonaId) _drState.selectedPersonaId = ps[0].id;
    strip.innerHTML = ps.map(function(p) {
      var av = p.avatar || '';
      var imgEl = av ? '<img class="dr-persona-avatar" src="' + av.replace(/"/g, '&quot;') + '">'
                     : '<div class="dr-persona-avatar" style="background:#e5e2db;display:flex;align-items:center;justify-content:center;font-size:18px;color:#999;">' + (p.name || '?').charAt(0) + '</div>';
      var sel = String(p.id) === String(_drState.selectedPersonaId) ? ' selected' : '';
      return '<div class="dr-persona-chip' + sel + '" onclick="drSelectPersona(\'' + p.id + '\')">' + imgEl + '<div class="dr-persona-name">' + (p.name || '角色') + '</div></div>';
    }).join('');
  }

  window.drSelectPersona = function(id) {
    if (String(_drState.selectedPersonaId || '') !== String(id || '')) {
      _drState.todayOutfit = null;
      _drState.coordOutfit = null;
      _drState.coupleOutfit = null;
      _drWardrobeSelection = {};
      ['drTodayReactionCard','drTodayScoreCard','drTodayImageCard','drTodayStoryCard','drCoordResultCard','drCoordScoreCard','drCoordStoryCard','drCoupleResultCard','drCoupleScoreCard','drCoupleStoryCard','drCoupleImageCard'].forEach(function(cardId){ var el=document.getElementById(cardId); if(el) el.style.display='none'; });
      _drClearCollagePreview('drTodayCollageWrap', 'drTodayCollagePreview');
      _drClearCollagePreview('drCoordCollageWrap', 'drCoordCollagePreview');
      _drClearCollagePreview('drCoupleCollageWrap', 'drCoupleCollagePreview');
      var todayEl=document.getElementById('drTodayOutfitDisplay');
      if(todayEl) todayEl.innerHTML='<div class="dr-empty"><i class="fas fa-tshirt"></i>点击生成这个角色今天的穿搭</div>';
    }
    _drState.selectedPersonaId = id;
    drRenderPersonaStrip();
    _drRefreshGenderControls();
    if (_drState.currentTab === 'wardrobe') { drRenderWardrobe(); _drUpdateWardrobeActionBar(); }
    if (_drState.currentTab === 'memories') drRenderMemories();
    drApplyModeUI();
    drRenderCoordManualBuilder();
    drRenderCoupleManualBuilders();
  };

  // ── Occasion chips ──
  function _initOccasionChips() {
    var chips = document.querySelectorAll('#drOccasionChips .dr-occasion-chip');
    chips.forEach(function(chip) {
      chip.onclick = function() {
        chips.forEach(function(c) { c.classList.remove('selected'); });
        chip.classList.add('selected');
        _drState.occasion = chip.dataset.occasion || '';
        document.getElementById('drOccasionCustomInput').value = '';
      };
    });
    var customInput = document.getElementById('drOccasionCustomInput');
    if (customInput) {
      customInput.oninput = function() {
        if (customInput.value.trim()) {
          chips.forEach(function(c) { c.classList.remove('selected'); });
          _drState.occasion = customInput.value.trim();
        }
      };
    }
    var wardrobeCheck = document.getElementById('drUseWardrobeOnly');
    if (wardrobeCheck) wardrobeCheck.onchange = function() { _drState.useWardrobeOnly = wardrobeCheck.checked; };
  }

  // ── Couple style chips ──
  function _initCoupleStyleChips() {
    var chips = document.querySelectorAll('#drCoupleStylePicker .dr-occasion-chip');
    chips.forEach(function(chip) {
      chip.onclick = function() {
        chips.forEach(function(c) { c.classList.remove('selected'); });
        chip.classList.add('selected');
        _drState.coupleStyle = chip.dataset.style || '甜妹风';
        var custom = document.getElementById('drCoupleCustomStyleInput');
        if (custom) custom.value = '';
      };
    });
    var custom = document.getElementById('drCoupleCustomStyleInput');
    if (custom) {
      custom.oninput = function() {
        if (custom.value.trim()) {
          chips.forEach(function(c) { c.classList.remove('selected'); });
          _drState.coupleStyle = custom.value.trim();
        }
      };
    }
  }

  // ── ── ── TODAY'S OUTFIT ── ── ──
  window.drGenerateTodayOutfit = async function() {
    var p = _getCurrentPersona();
    if (!p) { _drToast('请先选择角色'); return; }
    var btn = document.getElementById('drGenTodayBtn');
    if (btn) { btn.disabled = true; btn.innerHTML = '<span class="dr-spinner"></span><span>生成中…</span>'; }
    var displayEl = document.getElementById('drTodayOutfitDisplay');
    if (displayEl) displayEl.innerHTML = _shimmer(5);
    _drClearCollagePreview('drTodayCollageWrap', 'drTodayCollagePreview');

    try {
      var pCtx = _buildPersonaContext(p);
      var up = _getUserProfile();
      var targetIsUser = _drState.mode === 'user';
      var targetName = targetIsUser ? (up.name || '用户') : (p.name || '角色');
      var targetGender = targetIsUser ? _drGetUserGender(p.id) : _drGetPersonaGender(p);
      var today = new Date();
      var dateStr = today.getFullYear() + '年' + (today.getMonth()+1) + '月' + today.getDate() + '日，' + ['周日','周一','周二','周三','周四','周五','周六'][today.getDay()];
      var styleReq = (_drState.occasion && !/^(上学|约会|打工|下雨天)$/i.test(String(_drState.occasion))) ? ('\n用户手动填写/选择的风格或场景要求：' + _drState.occasion) : '';
      var todayUseWardrobeOnly = !!((document.getElementById('drTodayUseWardrobeOnly') || {}).checked);
      var wardrobeCtx = '';
      if (todayUseWardrobeOnly) {
        var wardrobeRows = [];
        _getWardrobeCats(p.id, targetIsUser).forEach(function(cat){ var items = _getWardrobe(p.id, cat, targetIsUser).map(_drWardrobeItemName).filter(Boolean); if (items.length) wardrobeRows.push(cat + '：' + items.join('、')); });
        wardrobeCtx = wardrobeRows.length ? ('\n【限定衣柜】只能从以下单品中选择：\n' + wardrobeRows.join('\n')) : '\n【限定衣柜】当前衣柜为空，本次不得生成新的即时单品。';
      }
      var broadRule = todayUseWardrobeOnly ? '必须严格只使用限定衣柜中的单品，不得编新单品。' : '如果不是衣柜已有单品，生成后会自动加入该页面衣柜。';
      var prompt = '你是一个时尚造型师AI。请生成【' + targetName + '】今天的穿搭造型。不要默认加入任何页面UI风格词；只有用户手动选择或填写了风格时，才参考该风格。人设和最近对话只作为参考，不要被限制，范围要更广、更特别、更有新鲜感，避免每次都生成相似基础款。\n\n【当前选择角色】\n' + pCtx + '\n【本次穿搭对象】' + (targetIsUser ? '用户：' + targetName + '；性别：' + targetGender + '；由角色 ' + p.name + ' 帮用户搭配。' : '角色：' + targetName + '；性别：' + targetGender + '。') + '\n今天日期：' + dateStr + styleReq + wardrobeCtx + _drBuildRecentAvoidHint(p.id, targetIsUser, false) + '\n\n任务要求：\n1. 造型要根据穿搭对象的身份、性别、场合、最近对话和角色关系推断。\n2. 每个品类只写一条精炼描述，建议 8-24 字，禁止嵌套对象。\n3. 选装理由控制在50字内，整体氛围控制在20字内。\n4. 不要输出多层 JSON，不要把上装/下装写成对象。\n5. 五个品类都必须写满，不能留空；没有也要写“无”。\n6. 单品范围要广一点，可以特别、有设计感、生活化或反差感，不要只按人设生成固定套路。\n7. ' + broadRule + _drStrictJsonRules('{"outfit":{"上装":"具体上装描述","下装":"具体下装描述","外套":"具体外套描述或无","鞋":"具体鞋子描述","配饰":"具体配饰描述或无"},"reason":"50字内选装理由","vibe":"整体氛围短句"}', 'outfit 必须是对象；上装、下装、外套、鞋、配饰五个字段必须全部存在；这五个字段的值必须是字符串，绝对不能是对象、数组或空的大括号；reason 和 vibe 必须是字符串。');
      if (todayUseWardrobeOnly) {
        prompt += '\n\n【重要：限定衣柜输出覆盖规则】这次 outfit 不要强行使用“上装/下装/外套/鞋/配饰”五个默认类型。请优先使用上方限定衣柜里的真实分类名作为 outfit 的 key，并且 value 必须是该分类里真实存在的单品名。至少选择 3 个不同分类；如果衣柜少于 3 个分类，就使用所有可用分类。禁止输出不在衣柜清单里的新衣物。';
      }
      var raw = await _drApiCall(prompt, 600);
      var result = _drCoerceOutfit(raw, _safeParseJSON(raw));
      if (todayUseWardrobeOnly) result.outfit = _drRestrictOutfitToWardrobeDynamic(p.id, result.outfit, _drState.mode === 'user');
      result.reactionContext = targetIsUser ? 'role_to_user' : 'user_to_role';
      result.targetName = targetName;
      result.targetGender = targetGender;
      result.occasion = _drState.occasion || '';
      result.refItems = _drCollectReferencedWardrobeItems(p.id, result.outfit || {}, _drState.mode === 'user');
      _drState.todayOutfit = result;

      // Save page record and add generated items into this page's wardrobe
      if (!todayUseWardrobeOnly) _drAddOutfitToWardrobe(p.id, result.outfit, _drState.mode === 'user');
      _drState.todayRecordId = _drAddRecord('today', {
        type: 'today', outfit: result.outfit, reason: result.reason, vibe: result.vibe,
        reactionContext: result.reactionContext, occasion: result.occasion,
        date: dateStr + ' · ' + new Date().toLocaleTimeString('zh-CN', {hour:'2-digit', minute:'2-digit'}), savedAt: Date.now()
      }, _drState.mode === 'user');
      drRenderWardrobe();

      // Render outfit
      var outfitHtml = Object.entries(result.outfit).map(function(kv) {
        if (!kv[1]) kv[1] = '无';
        return '<div class="dr-outfit-item"><div class="dr-outfit-category">' + kv[0] + '</div><div class="dr-outfit-value">' + kv[1] + '</div></div>';
      }).filter(Boolean).join('');
      if (result.vibe) outfitHtml += '<div class="dr-outfit-reason">整体氛围：' + result.vibe + '</div>';
      if (result.reason) outfitHtml += '<div class="dr-outfit-reason">选装理由：' + result.reason + '</div>';
      if (displayEl) displayEl.innerHTML = outfitHtml || '<div class="dr-empty">未能生成造型</div>';
      await _drBuildAndShowSingleCollage(p.id, result.outfit, _drState.mode === 'user', 'drTodayCollageWrap', 'drTodayCollagePreview', 'today', _drState.todayRecordId, targetName, 'outfit');

      // Show sub-cards
      ['drTodayReactionCard','drTodayScoreCard','drTodayStoryCard'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.style.display = 'block';
      });
      var todayStoryEl = document.getElementById('drStoryContent');
      if (todayStoryEl) todayStoryEl.innerHTML = '<div style="font-size:12px;color:#bbb;">点击下方按钮生成这套穿搭触发的剧情</div>';

      // Generate reaction and score, then attach to this outfit record
      var reactionTxt = await _generateReaction(p, result, 'drTodayReactionContent', _drState.mode !== 'user');
      var scoreTxt = await _generateScore(p, result, 'drScoreGrid');
      _drUpdateRecord('today', _drState.todayRecordId, { reactionText: reactionTxt || '', scoreText: scoreTxt || '' }, _drState.mode === 'user');

      // Image card (only if persona allows image gen)
      var imgCard = document.getElementById('drTodayImageCard');
      if (imgCard) imgCard.style.display = (p.allowImageGen === true) ? 'block' : 'none';

    } catch(err) {
      if (displayEl) { var fallback = _drCoerceOutfit((err && err.message) || 'API返回内容暂时不是标准JSON', null); displayEl.innerHTML = Object.entries(fallback.outfit || {}).map(function(kv){ return '<div class="dr-outfit-item"><div class="dr-outfit-category">' + kv[0] + '</div><div class="dr-outfit-value">' + kv[1] + '</div></div>'; }).join(''); }
    }
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-magic"></i><span>重新生成今日穿搭</span>'; }
  };

  function _drOutfitItemsText(outfit) {
    return Object.entries(outfit || {}).filter(function(kv) { return kv[1] && kv[1] !== '无'; }).map(function(kv) { return kv[0] + '：' + kv[1]; }).join('，') || '无';
  }

  function _drDescribeOutfitPerspective(persona, outfitData) {
    var up = _getUserProfile();
    var userName = up.name || '用户';
    var ctx = outfitData && outfitData.reactionContext || 'user_to_role';
    if (ctx === 'role_to_user') {
      return {
        ctx: ctx,
        targetName: userName,
        targetType: '用户',
        sceneText: persona.name + '给' + userName + '搭配了这套造型，最终真正穿这套衣服的人是' + userName + '，不是' + persona.name + '自己。',
        scoreFocus: '评分时要重点判断这套造型对用户 ' + userName + ' 本人的适配度，而不是对角色 ' + persona.name + ' 的适配度。',
        storyFocus: '剧情里必须明确这套造型是穿在用户 ' + userName + ' 身上的，并且是角色 ' + persona.name + ' 给用户搭的。'
      };
    }
    if (ctx === 'user_self') {
      return {
        ctx: ctx,
        targetName: userName,
        targetType: '用户',
        sceneText: userName + '自己给自己搭配了这套造型，最终真正穿这套衣服的人也是' + userName + '。角色' + persona.name + '只是看到并评价这套用户自搭造型。',
        scoreFocus: '评分时要重点判断这套造型对用户 ' + userName + ' 本人的适配度，并从角色 ' + persona.name + ' 的视角评价观感。',
        storyFocus: '剧情里必须明确这是用户 ' + userName + ' 自己穿的、自搭的造型，不要写成角色自己穿上了这套衣服。'
      };
    }
    return {
      ctx: ctx,
      targetName: persona.name,
      targetType: '角色',
      sceneText: userName + '给' + persona.name + '搭配了这套造型，最终真正穿这套衣服的人是角色 ' + persona.name + '，不是用户 ' + userName + '。',
      scoreFocus: '评分时要重点判断这套造型对角色 ' + persona.name + ' 本人的适配度，而不是对用户 ' + userName + ' 的适配度。',
      storyFocus: '剧情里必须明确这套造型是穿在角色 ' + persona.name + ' 身上的，并且是用户 ' + userName + ' 给角色搭的。'
    };
  }

  function _drRenderScoreRows(scores) {
    scores = Array.isArray(scores) ? scores : [];
    return scores.map(function(s) {
      var isNum = typeof s.value === 'number';
      var rowClass = 'dr-score-row' + (isNum ? ' dr-score-row-number' : ' dr-score-row-text');
      var valueClass = 'dr-score-value' + (isNum ? ' dr-score-value-number' : '');
      var barHtml = '<div class="dr-score-bar-wrap' + (isNum ? '' : ' dr-score-bar-wrap-empty') + '">' + (isNum ? '<div class="dr-score-bar" style="width:' + s.value + '%;"></div>' : '') + '</div>';
      return '<div class="' + rowClass + '"><div class="dr-score-head"><div class="dr-score-label">' + _escapeHtml(String(s.label || 'AI评分')) + '</div><div class="' + valueClass + '">' + _escapeHtml(String(s.value == null ? '' : s.value)) + '</div></div>' + barHtml + '</div>';
    }).join('');
  }

  async function _drGenerateSingleOutfitStory(persona, outfitData, targetId) {
    var el = document.getElementById(targetId);
    if (!el) return '';
    el.innerHTML = _shimmer(6);
    try {
      var outfitStr = _drOutfitItemsText(outfitData && outfitData.outfit || {});
      var pCtx = _buildPersonaContext(persona);
      var up = _getUserProfile();
      var userName = up.name || '用户';
      var meta = _drDescribeOutfitPerspective(persona, outfitData || {});
      var prompt = '你是一个擅长写日常感小剧情的作者。请根据以下信息，生成一段“角色/对象穿上这套造型之后，在生活里自然触发的小故事”。\n\n' + pCtx + '\n用户名：' + userName + '\n【穿搭归属】' + meta.sceneText + '\n【实际穿着对象】' + meta.targetName + '（' + meta.targetType + '）\n造型单品：' + outfitStr + '\n整体氛围：' + ((outfitData && outfitData.vibe) || '无') + '\n搭配理由：' + ((outfitData && outfitData.reason) || '无') + '\n场合：' + ((outfitData && outfitData.occasion) || '未特别限定') + '\n\n要求：\n1. 剧情要生活化、自然、有趣，像这套造型触发了某种场景气质、行动选择或日常际遇，但不是衣服说明书。\n2. 可以是校园、通勤、社团、街区、便利店、图书馆、咖啡店、展览、公交地铁、同事同学室友邻居等各种日常场景，不要局限于用户和角色彼此互动。\n3. 必须符合角色人设逻辑和实际穿着对象，不要写反，不要让角色突然脱离人设。\n4. 衣服只负责触发主题和气氛，例如清爽校园感、雨天通勤感、安静书卷感、街头松弛感，但正文不要反复盘衣服。\n5. 每次都要有新鲜的小切口，不要重复常见套路，也不要总是心动暧昧模板。\n6. 内容写成完整的一段或两段中文短篇，220到420字左右，结尾必须完整收住，不能像被截断。\n7. 只返回正文，不要标题，不要分点，不要解释。';
      var story = await _drApiCall(prompt, 1100);
      story = String(story || '').replace(/^```[\s\S]*?```$/g, '').trim();
      el.textContent = story || '（暂无剧情）';
      return story;
    } catch(err) {
      el.textContent = '（暂时无法生成穿搭剧情）';
      return '';
    }
  }

  // ── Generate reaction ──
  async function _generateReaction(persona, outfitData, targetId, userDressed) {
    var el = document.getElementById(targetId);
    if (!el) return;
    el.innerHTML = _shimmer(3);
    try {
      var pCtx = _buildPersonaContext(persona);
      var meta = _drDescribeOutfitPerspective(persona, outfitData || {});
      var outfitStr = _drOutfitItemsText(outfitData && outfitData.outfit || {});
      var prompt = '你是' + persona.name + '。' + pCtx + '\n\n【穿搭场景】' + meta.sceneText + '\n造型：' + outfitStr + '\n\n请用角色的真实性格，对这套造型发表简短反应（1-4句话，50-120字）。\n要求：\n1. 角色要有自己的意见，不是什么都接受\n2. 要有活人感，口语化，符合人设\n3. 必须准确区分：角色给用户搭配 / 用户给自己搭配 / 用户给角色搭配，不能说反\n4. 如果这套衣服穿在用户身上，就不能说成是角色自己穿上了这套\n5. 可以嘴硬、可以甜、可以吐槽，根据人设来\n6. 只返回角色说的话，不要加说明。';
      var reply = await _drApiCall(prompt, 200);
      var av = persona.avatar || '';
      var imgEl = av ? '<img class="dr-reaction-avatar" src="' + av.replace(/"/g,'&quot;') + '">' : '';
      el.innerHTML = '<div class="dr-reaction">' + imgEl + reply + '</div>';
      return reply;
    } catch(err) {
      el.innerHTML = '<div class="dr-reaction">（暂时无法获取角色反应）</div>';
      return '';
    }
  }

  // ── Generate score ──
  async function _generateScore(persona, outfitData, targetGridId) {
    var grid = document.getElementById(targetGridId);
    if (!grid) return;
    _drRenderScoreSummary(targetGridId, { overallScore:'', summary:'' });
    grid.innerHTML = _shimmer(5);
    try {
      var outfitStr = _drOutfitItemsText(outfitData && outfitData.outfit || {});
      var pCtx = _buildPersonaContext(persona);
      var meta = _drDescribeOutfitPerspective(persona, outfitData || {});
      var prompt = '你是时装比赛评委。请像客观评审一样，对这套造型做专业、克制、偏客观的评分与总评。\n\n' + pCtx + '\n【穿搭归属】' + meta.sceneText + '\n【实际穿着对象】' + meta.targetName + '（' + meta.targetType + '）\n造型：' + outfitStr + '\n整体氛围：' + ((outfitData && outfitData.vibe) || '无') + '\n搭配理由：' + ((outfitData && outfitData.reason) || '无') + '\n场合：' + ((outfitData && outfitData.occasion) || '未特别限定') + '\n' + meta.scoreFocus + '\n\n评分要求：\n1. 口吻要像时装比赛评审，偏客观分析，不要像恋爱脑夸夸文。\n2. 所有评分项目和分数都必须根据这次实际造型临时生成，不能复用固定标签名，不能默认固定分值。\n3. 禁止照抄任何示例标签、示例措辞或示例分数，尤其不要反复出现 92、88、90 这类示例数值。\n4. 至少 1 项专门评价这套造型对' + meta.targetName + '的适配度。\n5. 至少 2 项要直接围绕本次出现的具体衣物单品、颜色关系、层次或单品组合来评价，最好在 label 里体现具体单品或组合特点。\n6. 其余项可以评价廓形比例、色彩层次、完成度、场景契合度、细节处理，但都必须建立在这次单品内容上。\n7. 需要给出一段 40-100 字的客观总评 summary，像评委总结陈词。\n8. 需要给出一个 0-100 的 overallScore 作为总评得分。' + _drStrictJsonRules('{"overallScore":0,"summary":"请根据本次造型生成客观总评","scores":[{"label":"请按本次造型生成项目A","value":"请按这次结果生成"},{"label":"请按本次造型生成项目B","value":"请按这次结果生成"},{"label":"请按本次造型生成项目C","value":"请按这次结果生成"},{"label":"请按本次造型生成项目D","value":"请按这次结果生成"}]}', '必须返回 overallScore、summary、scores 三个字段；overallScore 必须是 0 到 100 的数字；summary 必须是 40 到 100 字左右、客观评委口吻的字符串；scores 必须是数组，长度 4 到 6；每一项必须包含 label 和 value；label 必须是根据本次造型临时生成的字符串，不能照抄示例字段名；value 优先用数字，也可以少量使用短文字；至少 1 项专门评价对穿着对象的适配度；至少 2 项直接基于本次具体单品或单品组合。');
      var raw = await _drApiCall(prompt, 300);
      var result = _drCoerceScores(raw, _safeParseJSON(raw));
      if (_drLooksLikeTemplateScores(result.scores)) {
        var reprompt = prompt + '\n\n补充要求：你上一轮很可能复用了示例。现在重新评分，禁止使用示例里的默认数字、默认标签和模板措辞；每一项都必须重新生成并直接对应本次真实单品与适配度。';
        raw = await _drApiCall(reprompt, 360);
        result = _drCoerceScores(raw, _safeParseJSON(raw));
      }
      _drRenderScoreSummary(targetGridId, result);
      grid.innerHTML = _drRenderScoreRows(result.scores);
      return [result.overallScore !== '' ? ('总评得分：' + result.overallScore) : '', result.summary ? ('总评：' + result.summary) : '', result.scores.map(function(s){ return s.label + '：' + s.value; }).join('；')].filter(Boolean).join('\n');
    } catch(err) {
      grid.innerHTML = '<div style="font-size:12px;color:#bbb;">评分暂时没有结构化，但主穿搭不会失败</div>';
      return '';
    }
  }


