  // ── ── ── WARDROBE ── ── ──
  function drRenderWardrobe() {
    var isUser = _drState.mode === 'user';
    var pId = _drState.selectedPersonaId;
    var catTabsEl = document.getElementById('drWardrobeCatTabs');
    var itemsEl = document.getElementById('drWardrobeItemsGrid');
    if (!catTabsEl || !itemsEl) return;

    var cats = _getWardrobeCats(pId, isUser);
    if (cats.indexOf(_drState.wardrobeCat) === -1) _drState.wardrobeCat = cats[0] || '上装';

    catTabsEl.innerHTML = cats.map(function(cat) {
      var code = encodeURIComponent(cat);
      return '<button class="dr-wardrobe-cat-btn' + (cat === _drState.wardrobeCat ? ' active' : '') + '" onclick="drSelectWardrobeCat(decodeURIComponent(\'' + code + '\'))">' + _escapeHtml(cat) + '<span onclick="event.stopPropagation();drDeleteWardrobeCat(decodeURIComponent(\'' + code + '\'))" style="margin-left:6px;color:#aaa;font-size:10px;">×</span></button>';
    }).join('');

    var items = _getWardrobe(pId, _drState.wardrobeCat, isUser).map(_drNormalizeWardrobeItem).filter(function(x){ return x.name; });
    _saveWardrobe(pId, _drState.wardrobeCat, items, isUser);
    if (!items.length) {
      itemsEl.className = 'dr-items-grid';
      itemsEl.innerHTML = '<div class="dr-empty" style="grid-column:1/-1;"><i class="fas fa-tshirt"></i>这个分类还没有单品<br>可以上传图片、手动添加或 AI 生成</div>';
      return;
    }
    itemsEl.className = 'dr-shop-grid';
    itemsEl.innerHTML = items.map(function(item, idx) {
      var selKey = _drState.wardrobeCat + '||' + idx;
      var selectedClass = _drWardrobeSelection[selKey] ? ' selected' : '';
      var img = item.imageSrc ? '<img src="' + String(item.imageSrc).replace(/"/g,'&quot;') + '">' : '<div class="dr-shop-placeholder"><i class="fas fa-shirt"></i></div>';
      var name = _escapeHtml(item.name || '单品');
      var meta = _escapeHtml(_drState.wardrobeCat + (item.source === 'upload' ? ' · 图片单品' : item.source === 'generated_today' ? ' · 今日穿搭收录' : ''));
      return '<div class="dr-shop-card' + selectedClass + '" data-idx="' + idx + '" onclick="drToggleItem(' + idx + ',\'' + _drState.wardrobeCat.replace(/'/g,"\\'") + '\')">' +
        '<button class="dr-shop-del" onclick="event.stopPropagation();drDeleteWardrobeItem(' + idx + ')">×</button>' +
        '<button class="dr-shop-edit" onclick="event.stopPropagation();drEditWardrobeItem(' + idx + ')" style="position:absolute;left:8px;top:8px;border:0;background:rgba(255,255,255,.92);border-radius:999px;padding:4px 7px;font-size:10px;color:#777;box-shadow:0 4px 12px rgba(0,0,0,.08);">编辑</button>' +
        '<div class="dr-shop-img">' + img + '</div>' +
        '<div class="dr-shop-name" title="' + name + '">' + name + '</div>' +
        '<div class="dr-shop-meta">' + meta + '</div>' +
        '</div>';
    }).join('');
  }


  window.drEditWardrobeItem = function(idx) {
    try {
      var isUser = _drState.mode === 'user';
      var pId = _drState.selectedPersonaId;
      var items = _getWardrobe(pId, _drState.wardrobeCat, isUser).map(_drNormalizeWardrobeItem);
      var item = items[idx];
      if (!item) { _drToast('找不到该单品'); return; }
      _drWardrobeEditState.idx = idx;
      var nameInput = document.getElementById('drWardrobeEditName');
      var descInput = document.getElementById('drWardrobeEditDesc');
      var preview = document.getElementById('drWardrobeEditPreview');
      if (nameInput) nameInput.value = item.name || '';
      if (descInput) descInput.value = item.detailDesc || item.desc || '';
      if (preview) {
        preview.innerHTML = item.imageSrc
          ? '<img src="' + String(item.imageSrc).replace(/"/g,'&quot;') + '" alt="wardrobe item preview">'
          : '<i class="fas fa-shirt" style="font-size:26px;color:#c8c1b8;"></i>';
      }
      _drOpenTopLayerModal('drWardrobeEditModal');
      setTimeout(function(){ try { if (nameInput) nameInput.focus(); } catch(e) {} }, 60);
    } catch(e) {
      console.error('[DressingRoom] edit wardrobe item failed', e);
      _drToast('编辑失败：' + (e.message || '未知错误'));
    }
  };

  window.drCloseWardrobeItemEditor = function() {
    _drWardrobeEditState.idx = null;
    _drCloseTopLayerModal('drWardrobeEditModal');
  };

  window.drSaveWardrobeItemEdit = function() {
    try {
      var idx = _drWardrobeEditState.idx;
      if (idx === null || idx === undefined) { _drToast('没有选中要编辑的单品'); return; }
      var isUser = _drState.mode === 'user';
      var pId = _drState.selectedPersonaId;
      var items = _getWardrobe(pId, _drState.wardrobeCat, isUser).map(_drNormalizeWardrobeItem);
      var item = items[idx];
      if (!item) { _drToast('找不到该单品'); return; }
      var nameInput = document.getElementById('drWardrobeEditName');
      var descInput = document.getElementById('drWardrobeEditDesc');
      var newName = String(nameInput && nameInput.value || '').trim();
      var newDesc = String(descInput && descInput.value || '').trim();
      if (!newName) { _drToast('名字不能为空'); return; }
      item.name = newName;
      item.detailDesc = newDesc;
      if (!item.desc) item.desc = '用户编辑的衣柜单品';
      items[idx] = item;
      _saveWardrobe(pId, _drState.wardrobeCat, items, isUser);
      drRenderWardrobe();
      drCloseWardrobeItemEditor();
      _drToast('已更新单品名字和隐藏描述');
    } catch(e) {
      console.error('[DressingRoom] save wardrobe item edit failed', e);
      _drToast('保存失败：' + (e.message || '未知错误'));
    }
  };

  window.drDeleteWardrobeItem = function(idx) {
    var isUser = _drState.mode === 'user';
    var pId = _drState.selectedPersonaId;
    var cat = _drState.wardrobeCat;
    var items = _getWardrobe(pId, _drState.wardrobeCat, isUser).map(_drNormalizeWardrobeItem);
    items.splice(idx, 1);
    _saveWardrobe(pId, _drState.wardrobeCat, items, isUser);
    var nextSelection = {};
    Object.keys(_drWardrobeSelection).forEach(function(key) {
      if (key.indexOf(cat + '||') !== 0) {
        nextSelection[key] = _drWardrobeSelection[key];
        return;
      }
      var parts = key.split('||');
      var itemIdx = parseInt(parts[1], 10);
      if (itemIdx < idx) nextSelection[key] = _drWardrobeSelection[key];
      else if (itemIdx > idx) nextSelection[cat + '||' + (itemIdx - 1)] = _drWardrobeSelection[key];
    });
    _drWardrobeSelection = nextSelection;
    drRenderWardrobe();
    _drUpdateWardrobeActionBar();
    _drToast('已删除该单品');
  };
  window.drOpenUploadWardrobeImage = function() {
    var input = document.getElementById('drWardrobeImageInput');
    if (input) { input.value = ''; input.click(); }
  };
  function _drCleanWardrobeTitle(text, cat) {
    var s = String(text || '').trim();
    s = s.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
    try {
      var obj = JSON.parse(s);
      if (obj && typeof obj === 'object') s = obj.name || obj.title || obj.item || obj.单品名 || obj.标题 || obj.content || s;
    } catch(e) {}
    s = String(s || '')
      .replace(/^(单品名|标题|名称|name|title)\s*[:：-]\s*/i, '')
      .replace(/["“”'`]/g, '')
      .replace(/\s+/g, ' ')
      .trim();
    // 如果模型回了一整句描述，只保留比较像商品名的前段
    s = s.split(/[。；;\n]/)[0].trim();
    if (s.length > 18) s = s.slice(0, 18).trim();
    if (!s || /无法|不能|看不清|不知道|图片|照片|这是一张|看起来/i.test(s)) {
      s = String(cat || '单品') + '图片单品';
    }
    return s;
  }

  function _drCleanWardrobeDetailDesc(text, cat, title) {
    var s = String(text || '').trim();
    s = s.replace(/^```(?:json)?/i, '').replace(/```$/i, '').trim();
    try {
      var obj = JSON.parse(s);
      if (obj && typeof obj === 'object') s = obj.detailDesc || obj.fullDetailDesc || obj.description || obj.desc || obj.content || s;
    } catch(e) {}
    s = String(s || '').replace(/[\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();
    s = s.replace(/^(描述|单品描述|详细描述|detail|description|full\s*detail)\s*[:：-]\s*/i, '');
    if (!s) s = String(cat || '单品') + '，名称“' + String(title || '单品') + '”，细节未识别完全。';
    if (s.length > 1200) s = s.slice(0, 1200).trim();
    return s;
  }

  async function _drAnalyzeWardrobeImage(dataUrl, cat, fileName) {
    var fallbackTitle = _drGuessItemNameFromFile(fileName, cat);
    var fallbackDetail = String(cat || '单品') + '，名称“' + fallbackTitle + '”。这是上传的真实单品图片，请尽量按图片本身的颜色、材质、剪裁、比例、结构和可见细节来理解与复刻。';
    try {
      if (typeof describeImageWithVisionApi !== 'function') {
        return { title: fallbackTitle, detailDesc: fallbackDetail, visionDesc: '' };
      }
      var visionDesc = await describeImageWithVisionApi(dataUrl);
      visionDesc = String(visionDesc || '').trim();
      if (!visionDesc) return { title: fallbackTitle, detailDesc: fallbackDetail, visionDesc: '' };
      var titlePrompt = '你是衣柜单品命名助手。根据图片识别描述，为这件衣物/配饰生成一个适合衣柜卡片显示的中文商品标题。\n分类：' + cat + '\n图片识别描述：' + visionDesc + '\n要求：\n1. 只返回标题，不要解释。\n2. 6到14个字左右。\n3. 要像衣柜/店铺里的单品名，例如“灰色连帽卫衣”“黑色玛丽珍鞋”“银色链条目链”。\n4. 不要写“图片中/看起来/可能是”。';
      var title = await _drApiCall(titlePrompt, 120);
      title = _drCleanWardrobeTitle(title, cat);
      if (!title || /图片单品$/.test(title)) title = _drCleanWardrobeTitle(visionDesc, cat);
      title = title || fallbackTitle;
      var detailPrompt = '你是高级服装视觉分析助手。根据图片识别描述，为这件单品生成一段会被隐藏保存、并会直接提供给生图 API 的中文超详细单品描述。\n分类：' + cat + '\n单品标题：' + title + '\n图片识别描述：' + visionDesc + '\n要求：\n1. 只返回一段中文描述，不要分点，不要标题，不要 markdown。\n2. 220到500字左右，尽量详细，但保持可读。\n3. 必须尽量写清：单品准确类别、主色/辅色/色调深浅、面料与材质、厚薄、硬挺度或垂坠感、表面纹理、光泽度、透明度、结构与剪裁、肩线、领口、袖型、衣长、腰线、下摆、裤腰、裤长、裤型、裙长、开衩、鞋头鞋跟鞋底、包型、五金、口袋、纽扣、拉链、缝线、压线、拼接、滚边、褶皱、印花、logo、文字、图案位置、洗水做旧、磨损处理、比例关系、宽松或修身程度、整体轮廓、穿上身后的视觉效果、适合的叠穿或穿戴方式、配饰佩戴位置与大小感、风格关键词。\n4. 如果图片里有关键但容易被忽略的小细节，一定要写出来，例如耳机挂脖方式、项链长度、戒指位置、帽檐形状、鞋带样式、袋口结构、袖口收口方式等。\n5. 禁止写“可能是”“大概”“似乎”“看起来像”，要尽量肯定、具体、可视化。\n6. 这段描述是隐藏内置描述词，后续会直接传给生图 API，所以重点是让模型能准确复刻该单品的细节、剪裁、比例与质感。';
      var detailDesc = await _drApiCall(detailPrompt, 520);
      detailDesc = _drCleanWardrobeDetailDesc(detailDesc, cat, title);
      if (!detailDesc) detailDesc = _drCleanWardrobeDetailDesc(visionDesc, cat, title);
      return { title: title || fallbackTitle, detailDesc: detailDesc || fallbackDetail, visionDesc: visionDesc };
    } catch(e) {
      console.warn('[DressingRoom] wardrobe image analysis failed:', e);
      return { title: fallbackTitle, detailDesc: fallbackDetail, visionDesc: '' };
    }
  }

  function _drWardrobeHiddenRefText(item) {
    var obj = _drNormalizeWardrobeItem(item || {});
    var parts = []; if (obj.detailDesc) parts.push('Full internal garment profile: ' + obj.detailDesc); if (obj.visionDesc) parts.push('Original vision observation: ' + obj.visionDesc); if (!parts.length && obj.desc) parts.push(obj.desc); return parts.join(' ').trim();
  }

  async function _drRecognizeWardrobeImageTitle(dataUrl, cat, fileName) {
    var analyzed = await _drAnalyzeWardrobeImage(dataUrl, cat, fileName);
    return analyzed && analyzed.title ? analyzed.title : _drGuessItemNameFromFile(fileName, cat);
  }

  function _drGuessItemNameFromFile(fileName, cat) {
    var raw = String(fileName || '').replace(/\.[^.]+$/, '').replace(/[_\-]+/g, ' ').trim();
    if (!raw || /^image|photo|img|截屏|截图|未命名/i.test(raw)) raw = String(cat || '单品') + '图片单品';
    return raw.slice(0, 36);
  }
  function _drSmartRemoveBg(dataUrl) {
    return new Promise(function(resolve){
      var img = new Image();
      img.onload = function(){
        var max = 900, scale = Math.min(1, max / Math.max(img.width, img.height));
        var w = Math.max(1, Math.round(img.width * scale)), h = Math.max(1, Math.round(img.height * scale));
        var c = document.createElement('canvas'); c.width = w; c.height = h;
        var ctx = c.getContext('2d'); ctx.drawImage(img, 0, 0, w, h);
        try {
          var im = ctx.getImageData(0,0,w,h), d = im.data;
          function px(x,y){ var i=(y*w+x)*4; return [d[i],d[i+1],d[i+2]]; }
          var samples = [px(0,0),px(w-1,0),px(0,h-1),px(w-1,h-1),px(Math.floor(w/2),0),px(Math.floor(w/2),h-1)];
          var bg = samples.reduce(function(a,b){ return [a[0]+b[0],a[1]+b[1],a[2]+b[2]]; }, [0,0,0]).map(function(v){return v/samples.length;});
          for (var y=0;y<h;y++) for (var x=0;x<w;x++) {
            var i=(y*w+x)*4, dr=d[i]-bg[0], dg=d[i+1]-bg[1], db=d[i+2]-bg[2];
            var dist=Math.sqrt(dr*dr+dg*dg+db*db);
            var nearEdge = x<8 || y<8 || x>w-9 || y>h-9;
            if (dist < (nearEdge ? 58 : 38)) d[i+3]=0;
            else if (dist < 72 && (d[i]>215&&d[i+1]>215&&d[i+2]>215)) d[i+3]=Math.max(0,d[i+3]-120);
          }
          ctx.putImageData(im,0,0);
          resolve(c.toDataURL('image/png'));
        } catch(e) { resolve(dataUrl); }
      };
      img.onerror = function(){ resolve(dataUrl); };
      img.src = dataUrl;
    });
  }
  window.drHandleWardrobeImageUpload = async function(ev) {
    var file = ev && ev.target && ev.target.files && ev.target.files[0];
    if (!file) return;
    if (!/^image\//i.test(file.type || '')) { _drToast('请上传图片文件'); return; }
    var reader = new FileReader();
    reader.onload = async function(){
      var originalDataUrl = String(reader.result || '');
      _drToast('正在识别单品内容…');
      var analyzed = await _drAnalyzeWardrobeImage(originalDataUrl, _drState.wardrobeCat, file.name);
      var itemName = analyzed && analyzed.title ? analyzed.title : _drGuessItemNameFromFile(file.name, _drState.wardrobeCat);
      var detailDesc = analyzed && analyzed.detailDesc ? analyzed.detailDesc : (_drState.wardrobeCat + '，名称“' + itemName + '”。因识别受限，建议以图片本身为准。');
      var visionDesc = analyzed && analyzed.visionDesc ? analyzed.visionDesc : '';
      _drToast('正在处理图片背景…');
      var processed = await _drSmartRemoveBg(originalDataUrl);
      var isUser = _drState.mode === 'user';
      var pId = _drState.selectedPersonaId;
      var item = { name:itemName, desc:'用户上传的单品图片，已自动识别标题并尝试去除背景', detailDesc:detailDesc, fullDetailDesc:detailDesc, visionDesc:visionDesc, imageSrc:processed, source:'upload', createdAt:Date.now() };
      _drAddItemToWardrobe(pId, _drState.wardrobeCat, item, isUser);
      drRenderWardrobe();
      _drToast('已识别为「' + itemName + '」，并已隐藏保存超详细单品描述');
    };
    reader.readAsDataURL(file);
  };

  window.drSelectWardrobeCat = function(cat) {
    _drState.wardrobeCat = cat;
    drRenderWardrobe();
    _drUpdateWardrobeActionBar();
  };

  window.drAddWardrobeCat = function() {
    var input = document.getElementById('drAddCatInput');
    var cat = input && input.value ? input.value.trim() : '';
    if (!cat) { _drToast('请输入分类名称'); return; }
    if (cat.length > 20) cat = cat.slice(0, 20);
    var isUser = _drState.mode === 'user';
    var pId = _drState.selectedPersonaId;
    var cats = _getWardrobeCats(pId, isUser);
    if (cats.indexOf(cat) !== -1) { _drToast('这个分类已存在'); return; }
    cats.push(cat);
    _saveWardrobeCats(pId, isUser, cats);
    _drState.wardrobeCat = cat;
    if (input) input.value = '';
    drRenderWardrobe();
    _drToast('已添加分类：' + cat);
  };

  window.drDeleteWardrobeCat = function(cat) {
    var isUser = _drState.mode === 'user';
    var pId = _drState.selectedPersonaId;
    var cats = _getWardrobeCats(pId, isUser);
    if (cats.length <= 1) { _drToast('至少保留一个衣柜分类'); return; }
    cats = cats.filter(function(c){ return c !== cat; });
    _saveWardrobeCats(pId, isUser, cats);
    try { localStorage.removeItem(_wKey(pId, cat, isUser)); } catch(e) {}
    try { _drPersistBackupPack(); } catch(e) {}
    if (_drState.wardrobeCat === cat) _drState.wardrobeCat = cats[0] || '上装';
    Object.keys(_drWardrobeSelection).forEach(function(key){
      if (key.indexOf(cat + '||') === 0) delete _drWardrobeSelection[key];
    });
    drRenderWardrobe();
    _drUpdateWardrobeActionBar();
    _drToast('已删除分类：' + cat);
  };

  // ── Wardrobe in-page item selection state ──
  var _drWardrobeSelection = {}; // key: cat+"||"+idx -> { cat, name, item }

  window.drToggleItem = function(idx, cat) {
    var card = document.querySelector('#drWardrobeItemsGrid .dr-shop-card[data-idx="' + idx + '"]');
    var key = (cat || _drState.wardrobeCat) + '||' + idx;
    var isUser = _drState.mode === 'user';
    var pId = _drState.selectedPersonaId;
    var items = _getWardrobe(pId, cat || _drState.wardrobeCat, isUser).map(_drNormalizeWardrobeItem);
    var item = items[idx];
    if (!item) return;
    if (_drWardrobeSelection[key]) {
      delete _drWardrobeSelection[key];
      if (card) card.classList.remove('selected');
    } else {
      _drWardrobeSelection[key] = { cat: cat || _drState.wardrobeCat, name: item.name, item: item };
      if (card) card.classList.add('selected');
    }
    _drUpdateWardrobeActionBar();
  };

  function _drUpdateWardrobeActionBar() {
    var bar = document.getElementById('drWardrobeActionBar');
    var count = Object.keys(_drWardrobeSelection).length;
    if (!bar) return;
    if (count === 0) {
      bar.style.display = 'none';
    } else {
      bar.style.display = 'flex';
      var label = bar.querySelector('.dr-wardrobe-sel-label');
      if (label) label.textContent = '已选 ' + count + ' 件单品';
    }
  }

  window.drClearWardrobeSelection = function() {
    _drWardrobeSelection = {};
    document.querySelectorAll('#drWardrobeItemsGrid .dr-shop-card.selected').forEach(function(el){ el.classList.remove('selected'); });
    _drUpdateWardrobeActionBar();
  };

  window.drSendWardrobeSelectionAsCard = function() {
    var items = Object.values(_drWardrobeSelection);
    if (!items.length) { _drToast('请先点击单品选择（再次点击取消）'); return; }
    // Inject outfit into _drState.coordOutfit so the existing card modal can use it
    var outfit = {};
    items.forEach(function(it) { if (!outfit[it.cat]) outfit[it.cat] = []; outfit[it.cat].push(it.name); });
    Object.keys(outfit).forEach(function(cat) { outfit[cat] = outfit[cat].join('、'); });
    var isUser = _drState.mode === 'user';
    var pId = _drState.selectedPersonaId;
    var refItems = _drCollectReferencedWardrobeItems(pId, outfit, isUser);
    _drState.coordOutfit = { outfit: outfit, reason: '用户从衣柜手动选择单品', vibe: '', reactionContext: isUser ? 'user_self' : 'user_to_role', refItems: refItems };
    _drState.coordMode = isUser ? 'user' : 'char';
    drOpenOutfitCardModal('coord');
  };

  window.drShowAddItemInput = function() {
    var area = document.getElementById('drAddItemInputArea');
    if (!area) return;
    area.style.display = area.style.display === 'none' ? 'flex' : 'none';
    area.style.flexDirection = 'column';
    area.style.gap = '8px';
  };

  window.drAddCustomItem = function() {
    var input = document.getElementById('drAddItemInput');
    if (!input || !input.value.trim()) { _drToast('请输入单品名称'); return; }
    var isUser = _drState.mode === 'user';
    var pId = _drState.selectedPersonaId;
    var items = _getWardrobe(pId, _drState.wardrobeCat, isUser).map(_drNormalizeWardrobeItem);
    var newItem = input.value.trim();
    if (items.some(function(x){ return x.name === newItem; })) { _drToast('该单品已存在'); return; }
    items.push({ name:newItem, desc:'', imageSrc:'', source:'manual', createdAt:Date.now() });
    _saveWardrobe(pId, _drState.wardrobeCat, items, isUser);
    input.value = '';
    drRenderWardrobe();
    _drToast('已添加到衣柜！');
  };

  window.drGenerateWardrobeItems = async function() {
    var p = _getCurrentPersona();
    var isUser = _drState.mode === 'user';
    var cat = _drState.wardrobeCat;
    var pId = _drState.selectedPersonaId;
    var btn = document.getElementById('drGenWardrobeBtn');
    if (btn) { btn.disabled = true; btn.innerHTML = '<span class="dr-spinner"></span><span>AI 生成中…</span>'; }
    try {
      var existing = _getWardrobe(pId, cat, isUser).map(_drWardrobeItemName).filter(Boolean);
      var who = isUser ? '用户（' + (_getUserProfile().name || '用户') + '，性别：' + _drGetUserGender(pId) + '）' : (p ? '角色（' + p.name + '，性别：' + _drGetPersonaGender(p) + '，人设：' + (p.persona || '').substring(0, 200) + '）' : '用户');
      var prompt = '你是时装造型师。请为以下人物生成5个独一无二的【' + cat + '】单品推荐（每个都要独特，和已有的不重复或相似）。\n\n人物：' + who + '\n\n已有【' + cat + '】：' + (existing.length ? existing.join('、') : '无') + '\n\n单品要求：\n1. 每个单品描述要具体，包含颜色/款式/材质。\n2. 要符合人物性格和风格。\n3. 不得与已有单品重复或过于相似。' + _drStrictJsonRules('["单品1","单品2","单品3","单品4","单品5"]', '根元素必须是数组；数组长度必须刚好为5；每个元素必须是字符串；不要返回对象。');
      var raw = await _drApiCall(prompt, 300);
      var items = _drCoerceStringArray(raw, _safeParseJSON(raw, 'array'));
      if (!items.length) items = [cat + '基础款1', cat + '基础款2', cat + '基础款3', cat + '基础款4', cat + '基础款5'];
      var added = 0;
      var curItems = _getWardrobe(pId, cat, isUser);
      items.forEach(function(item) {
        if (item && !curItems.map(_drWardrobeItemName).includes(item)) { curItems.push({ name:item, desc:'AI生成单品', imageSrc:'', source:'ai', createdAt:Date.now() }); added++; }
      });
      _saveWardrobe(pId, cat, curItems, isUser);
      drRenderWardrobe();
      _drToast('已生成 ' + added + ' 个新单品！');
    } catch(err) {
      _drToast('已收到返回内容，未再触发解析失败');
    }
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-magic"></i><span>AI 生成同类单品</span>'; }
  };

  // ── ── ── COORDINATION ── ── ──
  window.drGenerateCoordination = async function() {
    var p = _getCurrentPersona();
    if (!p) { _drToast('请先选择角色'); return; }
    var btn = document.getElementById('drGenCoordBtn');
    if (btn) { btn.disabled = true; btn.innerHTML = '<span class="dr-spinner"></span><span>搭配中…</span>'; }
    var resultCard = document.getElementById('drCoordResultCard');
    var scoreCard = document.getElementById('drCoordScoreCard');
    var displayEl = document.getElementById('drCoordOutfitDisplay');
    if (displayEl) displayEl.innerHTML = _shimmer(5);
    _drClearCollagePreview('drCoordCollageWrap', 'drCoordCollagePreview');
    if (resultCard) resultCard.style.display = 'block';

    try {
      var pCtx = _buildPersonaContext(p);
      var up = _getUserProfile();
      var customDesc = (document.getElementById('drCustomOutfitDesc') || {}).value || '';
      var useWardrobeOnly = (document.getElementById('drUseWardrobeOnly') || {}).checked;
      var occasionCustom = (document.getElementById('drOccasionCustomInput') || {}).value || '';
      var occasion = occasionCustom || _drState.occasion || '无限制';
      var coordMode = _drState.coordMode;
      var targetIsUser = coordMode === 'user'; // 角色帮用户搭配
      var isForChar = targetIsUser; // 兼容旧变量：true 表示本次结果存入用户侧衣柜/记忆
      var targetName = targetIsUser ? (up.name || '用户') : p.name;
      var targetGender = targetIsUser ? _drGetUserGender(p.id) : _drGetPersonaGender(p);

      // Build wardrobe context
      var wardrobeCtx = '';
      if (useWardrobeOnly) {
        var wardrobeItems = [];
        _getWardrobeCats(p.id, isForChar).forEach(function(cat) {
          var items = _getWardrobe(p.id, cat, isForChar).map(_drWardrobeItemName).filter(Boolean);
          if (items.length) wardrobeItems.push(cat + '：' + items.join('、'));
        });
        if (wardrobeItems.length) wardrobeCtx = '\n\n【限定衣柜】\n' + wardrobeItems.join('\n');
        else wardrobeCtx = '\n\n【限定衣柜】当前衣柜为空，本次不得混合或即时生成新单品';
      }

      var wardrobeJsonExample = '{}';
      var wardrobeJsonRule = '';
      if (useWardrobeOnly) {
        var catsForJson = _getWardrobeCats(p.id, targetIsUser).filter(function(cat){ return _getWardrobe(p.id, cat, targetIsUser).length; });
        var exampleObj = {};
        catsForJson.forEach(function(cat){ exampleObj[cat] = '只能填写该分类衣柜里实际存在的单品名，可多件用、连接'; });
        wardrobeJsonExample = JSON.stringify({ outfit: exampleObj, reason:'50字内搭配理由', vibe:'整体氛围短句' });
        wardrobeJsonRule = 'outfit 必须使用衣柜里的真实分类名作为 key；只显示被选择的分类，不要默认输出上装/下装/外套/鞋/配饰；每个 value 必须是该分类里实际存在的单品名，可以多件用、连接；至少选择3个不同分类或尽量组成完整造型；不得生成衣柜外的新单品。';
      } else {
        wardrobeJsonExample = '{"outfit":{"上装":"具体上装描述","下装":"具体下装描述","外套":"具体外套描述或无","鞋":"具体鞋子描述","配饰":"具体配饰描述或无"},"reason":"50字内搭配理由","vibe":"整体氛围短句"}';
        wardrobeJsonRule = 'outfit 必须是对象；上装、下装、外套、鞋、配饰五个字段建议存在；字段值必须是字符串，不能是对象或数组；reason 和 vibe 必须是字符串。';
      }
      var prompt = '你是' + p.name + '。\n\n' + pCtx + '\n\n【搭配任务】' + (targetIsUser ? '你（' + p.name + '）要给用户（' + targetName + '，性别：' + targetGender + '）搭配造型，你清楚知道这是你在给' + targetName + '搭配，不要误认为是用户给你搭配。' : '用户要给你（' + p.name + '，性别：' + targetGender + '）搭配造型，你清楚知道这是用户在给你搭配。') + '\n场合：' + occasion + (customDesc ? '\n自定义描述：' + customDesc : '') + wardrobeCtx + _drBuildRecentAvoidHint(p.id, targetIsUser, false) + '\n\n搭配要求：\n1. 造型必须符合' + targetName + '的性别（' + targetGender + '）。\n2. 不要默认加入页面UI风格词；只按角色人设、场合、自定义描述和用户手动选择/填写的风格搭配。\n3' + (useWardrobeOnly ? '. 仅使用衣柜内有的单品，并且要尽量搭配成完整造型，不要只选择一个衣物。输出时使用衣柜原本的分类名和单品名。' : '. 可以自由创意搭配，范围要广一点、特别一点，人设只作为参考，不要被限制。') + _drStrictJsonRules(wardrobeJsonExample, wardrobeJsonRule);
      var raw = await _drApiCall(prompt, 600);
      var result = _drCoerceOutfit(raw, _safeParseJSON(raw));
      if (useWardrobeOnly) result.outfit = _drRestrictOutfitToWardrobeDynamic(p.id, result.outfit, targetIsUser);
      result.reactionContext = targetIsUser ? 'role_to_user' : 'user_to_role';
      result.targetName = targetName;
      result.targetGender = targetGender;
      result.occasion = occasion;
      result.refItems = _drCollectReferencedWardrobeItems(p.id, result.outfit || {}, targetIsUser);
      _drState.coordOutfit = result;

      // Save page record
      _drState.coordRecordId = _drAddRecord('coord', {
        type:'coord', coordMode:coordMode, outfit:result.outfit, reason:result.reason, vibe:result.vibe, reactionContext:result.reactionContext,
        occasion:occasion, date:_drNowDateText(), savedAt:Date.now()
      }, targetIsUser);

      var outfitHtml = Object.entries(result.outfit).map(function(kv) {
        if (!kv[1]) kv[1] = '无';
        return '<div class="dr-outfit-item"><div class="dr-outfit-category">' + kv[0] + '</div><div class="dr-outfit-value">' + kv[1] + '</div></div>';
      }).filter(Boolean).join('');
      if (result.vibe) outfitHtml += '<div class="dr-outfit-reason">整体氛围：' + result.vibe + '</div>';
      if (result.reason) outfitHtml += '<div class="dr-outfit-reason">搭配理由：' + result.reason + '</div>';
      if (displayEl) displayEl.innerHTML = outfitHtml;
      await _drBuildAndShowSingleCollage(p.id, result.outfit, targetIsUser, 'drCoordCollageWrap', 'drCoordCollagePreview', 'coord', _drState.coordRecordId, targetName, 'outfit');

      // Reaction
      var reactionEl = document.getElementById('drCoordReactionContent');
      var coordReaction = reactionEl ? await _generateReaction(p, result, 'drCoordReactionContent', !targetIsUser) : '';

      // Score
      if (scoreCard) scoreCard.style.display = 'block';
      var storyCard = document.getElementById('drCoordStoryCard');
      if (storyCard) storyCard.style.display = 'block';
      var coordStoryHintEl = document.getElementById('drCoordStoryContent');
      if (coordStoryHintEl) coordStoryHintEl.innerHTML = '<div style="font-size:12px;color:#bbb;">点击下方按钮生成这套穿搭触发的剧情</div>';
      var coordScore = await _generateScore(p, result, 'drCoordScoreGrid');
      _drUpdateRecord('coord', _drState.coordRecordId, { reactionText: coordReaction || '', scoreText: coordScore || '' }, targetIsUser);

      // Show image btn if allowed
      var imgBtn = document.getElementById('drCoordGenImgBtn');
      if (imgBtn) imgBtn.style.display = p.allowImageGen === true ? 'flex' : 'none';

    } catch(err) {
      if (displayEl) { var fallback = _drCoerceOutfit((err && err.message) || 'API返回内容暂时不是标准JSON', null); displayEl.innerHTML = Object.entries(fallback.outfit || {}).map(function(kv){ return '<div class="dr-outfit-item"><div class="dr-outfit-category">' + kv[0] + '</div><div class="dr-outfit-value">' + kv[1] + '</div></div>'; }).join(''); }
    }
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-magic"></i><span>重新搭配</span>'; }
  };

  // ── ── ── OUTFIT CARD SYSTEM ── ── ──

  // State for the outfit card modal
  var _drCardState = { type: null, selectedPersonaId: null };
  var _drWardrobeEditState = { idx: null };

  function _drEnsureModalLayer(modalId) {
    var modal = document.getElementById(modalId);
    if (!modal) return null;
    if (modal.parentNode !== document.body) document.body.appendChild(modal);
    return modal;
  }

  function _drOpenTopLayerModal(modalId) {
    var modal = _drEnsureModalLayer(modalId);
    if (modal) modal.classList.add('open');
    return modal;
  }

  function _drCloseTopLayerModal(modalId) {
    var modal = document.getElementById(modalId);
    if (modal) modal.classList.remove('open');
  }

  // Helper: build rich item detail string from wardrobe item object
  function _drRichItemDetail(personaId, cat, itemName, isUser) {
    var items = _getWardrobe(personaId, cat, isUser).map(_drNormalizeWardrobeItem);
    var norm = _drSimpleTextNorm(itemName);
    var found = items.find(function(x){ return _drSimpleTextNorm(x.name) === norm; }) ||
                items.find(function(x){ return norm.indexOf(_drSimpleTextNorm(x.name)) >= 0 || _drSimpleTextNorm(x.name).indexOf(norm) >= 0; });
    if (!found) return '';
    return [found.detailDesc, found.visionDesc, found.desc].filter(Boolean).join(' ').trim();
  }

  // Build the hidden-context text for the chat (what the AI sees)
  function _drBuildOutfitCardChatContext(type, targetPersonaId) {
    var p = _getCurrentPersona();
    var up = _getUserProfile();
    var userName = up.name || '用户';
    var lines = [];

    if (type === 'coord') {
      var outfit = (_drState.coordOutfit && _drState.coordOutfit.outfit) || {};
      var coordMode = _drState.coordOutfit && _drState.coordOutfit.reactionContext;
      var targetIsUser = _drState.coordMode === 'user';
      var targetName = targetIsUser ? userName : (p ? p.name : '你');
      var wardrobeOwner = targetIsUser ? userName + '（用户本人）' : (p ? p.name + '（角色）' : '角色');
      var styledBy = '用户（' + userName + '）';

      lines.push('【换装室造型卡片】');
      lines.push('搭配者：' + styledBy);
      lines.push('搭配对象：' + targetName);
      lines.push('衣物来源：' + wardrobeOwner + '的衣柜');
      if (targetIsUser) {
        lines.push('（注意：这是用户给自己搭配的造型，不是给角色你搭配的，你是作为参与者被告知这套造型）');
      } else {
        lines.push('（注意：这是用户亲手给角色你搭配的造型，用的是角色你自己衣柜里的衣物）');
      }
      lines.push('');
      lines.push('搭配单品明细：');
      Object.entries(outfit).forEach(function(kv) {
        if (!kv[1] || kv[1] === '无') return;
        var itemNames = kv[1].split(/[、，,]/);
        itemNames.forEach(function(itemName) {
          itemName = itemName.trim();
          if (!itemName) return;
          var detail = '';
          if (p) detail = _drRichItemDetail(p.id, kv[0], itemName, targetIsUser);
          lines.push('  ' + kv[0] + '：' + itemName + (detail ? '\n    └ 详细描述：' + detail : ''));
        });
      });
      if (_drState.coordOutfit && _drState.coordOutfit.vibe) lines.push('整体氛围：' + _drState.coordOutfit.vibe);
      if (_drState.coordOutfit && _drState.coordOutfit.reason) lines.push('搭配理由：' + _drState.coordOutfit.reason);

    } else if (type === 'couple') {
      var co = _drState.coupleOutfit || {};
      lines.push('【换装室情侣造型卡片】');
      lines.push('这是用户（' + userName + '）发起的情侣搭配造型：');
      lines.push('');
      lines.push('用户（' + userName + '）的穿搭（来自用户自己的衣柜）：');
      lines.push('  ' + (co.userOutfit || '未提供'));
      // item details for user outfit
      if (co.userOutfitData && p) {
        Object.entries(co.userOutfitData).forEach(function(kv) {
          if (!kv[1] || kv[1] === '无') return;
          var detail = _drRichItemDetail(p.id, kv[0], kv[1], true);
          if (detail) lines.push('    └ ' + kv[0] + '详细描述：' + detail);
        });
      }
      lines.push('');
      lines.push('角色（' + (p ? p.name : '你') + '）的穿搭（来自角色自己的衣柜）：');
      lines.push('  ' + (co.charOutfit || '未提供'));
      if (co.charOutfitData && p) {
        Object.entries(co.charOutfitData).forEach(function(kv) {
          if (!kv[1] || kv[1] === '无') return;
          var detail = _drRichItemDetail(p.id, kv[0], kv[1], false);
          if (detail) lines.push('    └ ' + kv[0] + '详细描述：' + detail);
        });
      }
      if (co.eval) lines.push('');
      if (co.eval) lines.push('搭配评价：' + co.eval);
    }

    return lines.join('\n');
  }

  // Build the card visual HTML (rendered in chat bubble)
  function _drBuildOutfitCardHtml(type, collageDataUrl) {
    var p = _getCurrentPersona();
    var up = _getUserProfile();
    var userName = up.name || '用户';
    var now = new Date();
    var dateStr = now.getFullYear() + '.' + String(now.getMonth()+1).padStart(2,'0') + '.' + String(now.getDate()).padStart(2,'0');

    var collageHtml = '';
    if (collageDataUrl && collageDataUrl.length > 100) {
      collageHtml = '<div class="mono-outfit-card-collage"><img src="' + String(collageDataUrl).replace(/"/g,'&quot;') + '" alt="outfit collage"></div>';
    }

    var iconSvg = "<svg class='mono-outfit-card-icon' viewBox='0 0 52 52' xmlns='http://www.w3.org/2000/svg'><path d='M26 10 C23 10 20.5 11.8 19.2 14.2 L13 14.2 L10 21 L15.5 23.2 L15.5 42 L36.5 42 L36.5 23.2 L42 21 L39 14.2 L32.8 14.2 C31.5 11.8 29 10 26 10 Z' fill='none' stroke='rgba(255,255,255,0.9)' stroke-width='2.2' stroke-linejoin='round' stroke-linecap='round'/><path d='M19.2 14.2 C19.2 17.4 22.2 20 26 20 C29.8 20 32.8 17.4 32.8 14.2' fill='none' stroke='rgba(255,255,255,0.7)' stroke-width='2' stroke-linecap='round'/></svg>";

    var itemsHtml = '';
    var badges = '';

    if (type === 'coord') {
      var outfit = (_drState.coordOutfit && _drState.coordOutfit.outfit) || {};
      var targetIsUser = _drState.coordMode === 'user';
      var targetName = targetIsUser ? userName : (p ? p.name : '角色');

      badges = '<span class="mono-outfit-card-badge ' + (targetIsUser ? 'user-wardrobe' : 'char-wardrobe') + '">' +
        (targetIsUser ? '来自用户衣柜' : '来自角色衣柜') + '</span>' +
        '<span class="mono-outfit-card-badge styled-by-user">用户搭配</span>';

      Object.entries(outfit).forEach(function(kv) {
        if (!kv[1] || kv[1] === '无') return;
        itemsHtml += '<div class="mono-outfit-card-item">' +
          '<div class="mono-outfit-card-item-cat">' + _escapeHtml(kv[0]) + '</div>' +
          '<div class="mono-outfit-card-item-val">' + _escapeHtml(kv[1]) + '</div></div>';
      });

      var vibe = (_drState.coordOutfit && _drState.coordOutfit.vibe) ? '<div class="mono-outfit-card-vibe">' + _escapeHtml(_drState.coordOutfit.vibe) + '</div>' : '';

      return '<div class="mono-outfit-card">' +
        '<div class="mono-outfit-card-header">' + iconSvg +
        '<div class="mono-outfit-card-headtext">' +
        '<div class="mono-outfit-card-label">Outfit Card · 换装室</div>' +
        '<div class="mono-outfit-card-title">为 ' + _escapeHtml(targetName) + ' 的造型</div>' +
        '</div></div>' +
        collageHtml +
        '<div class="mono-outfit-card-body">' +
        '<div class="mono-outfit-card-meta">' + badges + '</div>' +
        '<div class="mono-outfit-card-items">' + itemsHtml + '</div>' +
        vibe +
        '</div>' +
        '<div class="mono-outfit-card-footer">✦ ' + _escapeHtml(userName) + ' 搭配 · ' + dateStr + '</div>' +
        '</div>';

    } else if (type === 'couple') {
      var co = _drState.coupleOutfit || {};
      badges = '<span class="mono-outfit-card-badge user-wardrobe">双方衣柜</span>' +
               '<span class="mono-outfit-card-badge styled-by-user">情侣搭配</span>';

      var userItems = '<div class="mono-outfit-card-item"><div class="mono-outfit-card-item-cat" style="min-width:40px;">我</div><div class="mono-outfit-card-item-val">' + _escapeHtml(co.userOutfit || '未填写') + '</div></div>';
      var charItems = '<div class="mono-outfit-card-item"><div class="mono-outfit-card-item-cat" style="min-width:40px;">' + _escapeHtml(p ? p.name.slice(0,4) : '角色') + '</div><div class="mono-outfit-card-item-val">' + _escapeHtml(co.charOutfit || '未填写') + '</div></div>';
      var evalHtml = co.eval ? '<div class="mono-outfit-card-vibe">' + _escapeHtml(co.eval) + '</div>' : '';

      return '<div class="mono-outfit-card">' +
        '<div class="mono-outfit-card-header">' + iconSvg +
        '<div class="mono-outfit-card-headtext">' +
        '<div class="mono-outfit-card-label">Couple Card · 换装室</div>' +
        '<div class="mono-outfit-card-title">情侣穿搭</div>' +
        '</div></div>' +
        collageHtml +
        '<div class="mono-outfit-card-body">' +
        '<div class="mono-outfit-card-meta">' + badges + '</div>' +
        '<div class="mono-outfit-card-items">' + userItems + charItems + '</div>' +
        evalHtml +
        '</div>' +
        '<div class="mono-outfit-card-footer">✦ ' + _escapeHtml(userName) + ' 发起 · ' + dateStr + '</div>' +
        '</div>';
    }
    return '';
  }

  function _drBuildOutfitCardPreviewText(type) {
    var p = _getCurrentPersona();
    var up = _getUserProfile();
    var userName = up.name || '用户';
    if (type === 'coord') {
      var outfit = (_drState.coordOutfit && _drState.coordOutfit.outfit) || {};
      var targetIsUser = _drState.coordMode === 'user';
      var targetName = targetIsUser ? userName : (p ? p.name : '角色');
      var parts = [];
      Object.entries(outfit).forEach(function(kv) {
        if (!kv[1] || kv[1] === '无') return;
        parts.push(kv[0] + ' ' + kv[1]);
      });
      var core = parts.slice(0, 2).join('；');
      if (parts.length > 2) core += ' 等' + parts.length + '项';
      return '[换装室造型卡片] 为 ' + targetName + ' 搭配' + (core ? '：' + core : '');
    }
    if (type === 'couple') {
      var co = _drState.coupleOutfit || {};
      var userOutfit = String(co.userOutfit || '').trim();
      var charOutfit = String(co.charOutfit || '').trim();
      var coupleCore = [userOutfit, charOutfit].filter(Boolean).slice(0, 2).join(' / ');
      return '[换装室情侣造型卡片]' + (coupleCore ? '：' + coupleCore : '');
    }
    return '[换装室造型卡片]';
  }

  window.renderOutfitCardBubble = function(m, idx, isUser, avatarSrc, authorName, isSelected) {
    var bubble = (m && m.outfitCardData && m.outfitCardData.cardHtml) || '';
    if (!bubble) {
      bubble = '<div class="mono-outfit-card"><div class="mono-outfit-card-body"><div class="mono-outfit-card-vibe">这张造型卡片暂时无法显示。</div></div></div>';
    }
    if (isUser) {
      return '<div class="msg-row user ' + (isSelected ? 'selected' : '') + '" data-idx="' + idx + '"><div class="msg-content" style="align-items:flex-end;">' + bubble + '</div><div class="msg-meta"><img src="' + (avatarSrc || '') + '" class="msg-avatar"><span class="msg-name">' + _escapeHtml(String(authorName || '你').substring(0,4)) + '</span></div></div>';
    }
    return '<div class="msg-row ai ' + (isSelected ? 'selected' : '') + '" data-idx="' + idx + '"><div class="msg-meta"><img src="' + (avatarSrc || '') + '" class="msg-avatar"><span class="msg-name">' + _escapeHtml(String(authorName || '角色').substring(0,4)) + '</span></div><div class="msg-content" style="align-items:flex-start;">' + bubble + '</div></div>';
  };

  async function _drResolveOutfitCardCollageSrc(type, targetPid) {
    try {
      var previewId = type === 'couple' ? 'drCoupleCollagePreview' : 'drCoordCollagePreview';
      var previewImg = document.querySelector('#' + previewId + ' img');
      if (previewImg && previewImg.src && previewImg.src.length > 100) return previewImg.src;
    } catch(e) {}

    if (type === 'coord') {
      if (_drState.coordOutfit && _drState.coordOutfit.collageSrc) return _drState.coordOutfit.collageSrc;
      var p = _getCurrentPersona();
      if (!p || !_drState.coordOutfit || !_drState.coordOutfit.outfit) return '';
      var targetIsUser = _drState.coordMode === 'user';
      var ownerLabel = targetIsUser ? (_getUserProfile().name || '用户') : (p.name || '角色');
      var refs = _drMergeRefLists(
        (_drState.coordOutfit && Array.isArray(_drState.coordOutfit.refItems)) ? _drState.coordOutfit.refItems : [],
        _drCollectReferencedWardrobeItems(p.id, _drState.coordOutfit.outfit || {}, targetIsUser)
      );
      if (!refs.length) return '';
      var singleSrc = await _drBuildWardrobeCollage([{ label: ownerLabel, refs: refs }]);
      if (singleSrc && _drState.coordOutfit) _drState.coordOutfit.collageSrc = singleSrc;
      return singleSrc || '';
    }

    if (type === 'couple') {
      if (_drState.coupleOutfit && _drState.coupleOutfit.collageSrc) return _drState.coupleOutfit.collageSrc;
      var cp = _getCurrentPersona();
      if (!cp || !_drState.coupleOutfit) return '';
      var userRefs = Array.isArray(_drState.coupleOutfit.userRefItems) ? _drState.coupleOutfit.userRefItems : [];
      var charRefs = Array.isArray(_drState.coupleOutfit.charRefItems) ? _drState.coupleOutfit.charRefItems : [];
      if (!userRefs.length && (_drState.coupleOutfit.userOutfitData || _drState.coupleOutfit.userOutfit)) {
        userRefs = _drState.coupleOutfit.userOutfitData
          ? _drCollectUploadedRefsFromOutfit(cp.id, _drState.coupleOutfit.userOutfitData, true, '用户')
          : _drCollectUploadedRefsFromText(cp.id, _drState.coupleOutfit.userOutfit || '', true, '用户');
      }
      if (!charRefs.length && (_drState.coupleOutfit.charOutfitData || _drState.coupleOutfit.charOutfit)) {
        charRefs = _drState.coupleOutfit.charOutfitData
          ? _drCollectUploadedRefsFromOutfit(cp.id, _drState.coupleOutfit.charOutfitData, false, '角色')
          : _drCollectUploadedRefsFromText(cp.id, _drState.coupleOutfit.charOutfit || '', false, '角色');
      }
      var groups = [];
      if (userRefs.length) groups.push({ label: (_getUserProfile().name || '用户'), refs: userRefs });
      if (charRefs.length) groups.push({ label: (cp.name || '角色'), refs: charRefs });
      if (!groups.length) return '';
      var coupleSrc = await _drBuildWardrobeCollage(groups);
      if (coupleSrc && _drState.coupleOutfit) _drState.coupleOutfit.collageSrc = coupleSrc;
      return coupleSrc || '';
    }

    return '';
  }

  function _drSendOutfitCardToChat(targetPid, hiddenContext, cardHtml, previewText, type) {
    if (!targetPid) { _drToast('请选择聊天室'); return false; }
    var p = null;
    try {
      if (Array.isArray(personas)) p = personas.find(function(x) { return String(x.id) === String(targetPid); });
    } catch(e) {}
    if (!p) {
      try {
        var saved = JSON.parse(localStorage.getItem('mono_personas') || '[]');
        p = saved.find(function(x) { return String(x.id) === String(targetPid); });
      } catch(e) {}
    }
    if (!p) { _drToast('找不到这个聊天室'); return false; }
    if (!Array.isArray(p.history)) p.history = [];

    var now = Date.now();
    var hiddenMsg = {
      role: 'user',
      content: String(hiddenContext || '').trim(),
      _hiddenContext: true,
      _drOutfitCardContext: true,
      timestamp: now
    };
    var visibleMsg = {
      role: 'user',
      msgType: 'outfit_card',
      outfitCardData: {
        type: type || 'coord',
        cardHtml: String(cardHtml || '')
      },
      content: String(previewText || '[换装室造型卡片]'),
      timestamp: now + 1,
      displayHint: '你发送给角色的换装室造型卡片'
    };
    p.history.push(hiddenMsg);
    p.history.push(visibleMsg);
    try {
      p._lastUserChatTs = visibleMsg.timestamp;
      p.lastUserMessageTime = visibleMsg.timestamp;
    } catch(e) {}

    try {
      if (typeof saveData === 'function') saveData();
      else localStorage.setItem('mono_personas', JSON.stringify((typeof getPersonas === 'function') ? getPersonas() : (window.personas || [])));
    } catch(e) {
      try { localStorage.setItem('mono_personas', JSON.stringify(window.personas || [])); } catch(_) {}
    }

    try { drCloseOutfitCardModal(); } catch(e) {}
    try { if (typeof drCloseWardrobeItemEditor === 'function') drCloseWardrobeItemEditor(); } catch(e) {}
    try { if (typeof openApp === 'function') openApp('chatPage'); else if (typeof _showAppPage === 'function') _showAppPage('chatPage'); } catch(e) {}
    try {
      if (typeof setCurrentPersona === 'function') setCurrentPersona(targetPid);
      else if (typeof selectPersona === 'function') selectPersona(targetPid);
      else {
        currentId = targetPid;
        window.currentId = targetPid;
      }
    } catch(e) {}

    setTimeout(function() {
      try { if (typeof renderContactList === 'function') renderContactList(); } catch(e) {}
      try {
        if (typeof renderMessages === 'function') renderMessages();
        var box = document.getElementById('chatBox');
        if (box) box.scrollTop = box.scrollHeight;
      } catch(e) {}
      try { if (typeof _handleAuto回复AfterSend === 'function') _handleAuto回复AfterSend(targetPid); } catch(e) {}
    }, 80);

    _drToast('造型卡片已发送到聊天室！');
    return true;
  }

  // Open the outfit card modal
  window.drOpenOutfitCardModal = function(type) {
    var hasData = type === 'coord' ? !!_drState.coordOutfit : !!_drState.coupleOutfit;
    if (!hasData) { _drToast('请先完成搭配'); return; }
    _drCardState.type = type;
    _drCardState.selectedPersonaId = null;

    // Build persona list
    var personas = [];
    try { personas = JSON.parse(localStorage.getItem('mono_personas') || '[]'); } catch(e) {}
    var list = document.getElementById('drPersonaPickList');
    var sub = document.getElementById('drOutfitCardModalSub');
    if (sub) sub.textContent = type === 'couple' ? '选择要发送情侣造型卡片的聊天室' : '选择要发送造型卡片的聊天室';
    if (list) {
      if (!personas.length) {
        list.innerHTML = '<div style="font-size:12px;color:#aaa;padding:12px 0;">还没有角色，先在主页创建角色吧</div>';
      } else {
        list.innerHTML = personas.map(function(p) {
          var avatarHtml = p.avatar ? '<img src="' + String(p.avatar).replace(/"/g,'&quot;') + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">' : '<span>' + _escapeHtml((p.name||'?').slice(0,1)) + '</span>';
          return '<div class="dr-persona-pick-item" data-pid="' + _escapeHtml(String(p.id||'')) + '" onclick="drSelectCardPersona(this)">' +
            '<div class="dr-persona-pick-avatar">' + avatarHtml + '</div>' +
            '<div><div class="dr-persona-pick-name">' + _escapeHtml(p.name||'角色') + '</div>' +
            '<div class="dr-persona-pick-sub">点击选择此聊天室</div></div>' +
            '</div>';
        }).join('');
      }
    }
    var sendBtn = document.getElementById('drOutfitCardSendBtn');
    if (sendBtn) sendBtn.disabled = true;

    _drOpenTopLayerModal('drOutfitCardModal');
  };

  window.drSelectCardPersona = function(el, pid) {
    pid = pid || (el && el.getAttribute && el.getAttribute('data-pid')) || '';
    if (!pid) { _drToast('这个聊天室暂时无法选择'); return; }
    _drCardState.selectedPersonaId = pid;
    var items = document.querySelectorAll('#drPersonaPickList .dr-persona-pick-item');
    items.forEach(function(x){ x.classList.remove('selected'); });
    if (el) el.classList.add('selected');
    var sendBtn = document.getElementById('drOutfitCardSendBtn');
    if (sendBtn) sendBtn.disabled = false;
  };

  window.drCloseOutfitCardModal = function() {
    _drCloseTopLayerModal('drOutfitCardModal');
  };

  window.drConfirmSendOutfitCard = async function() {
    var type = _drCardState.type;
    var targetPid = _drCardState.selectedPersonaId;
    if (!type || !targetPid) { _drToast('请选择聊天室'); return; }

    var collageDataUrl = '';
    try { collageDataUrl = await _drResolveOutfitCardCollageSrc(type, targetPid); } catch(e) {}

    var cardHtml = _drBuildOutfitCardHtml(type, collageDataUrl);
    var hiddenContext = _drBuildOutfitCardChatContext(type, targetPid);
    var previewText = _drBuildOutfitCardPreviewText(type);
    try { _drSendOutfitCardToChat(targetPid, hiddenContext, cardHtml, previewText, type); }
    catch(e) { _drToast('发送失败：' + (e.message||'')); }
  };

  // Keep old function name as alias for backward compat
  window.drSendCoordToChat = function() { drOpenOutfitCardModal('coord'); };

  window.drGenerateCoordImage = async function() {
    var p = _getCurrentPersona();
    if (!p || p.allowImageGen !== true) { _drToast('角色未开启生图功能'); return; }
    if (!_drState.coordOutfit) { _drToast('请先搭配造型'); return; }
    var preview = document.getElementById('drCoordImagePreview');
    if (preview) { preview.style.display = 'flex'; preview.innerHTML = '<div class="dr-img-placeholder"><span class="dr-spinner dr-spinner-dark"></span><br>生成描述词中…</div>'; }
    try {
      var coordMode = _drState.coordMode;
      var targetIsUser = coordMode === 'user';
      var outfitStr = Object.entries(_drState.coordOutfit.outfit || {}).filter(function(kv){ return kv[1] && kv[1] !== '无'; }).map(function(kv){ return kv[0] + '：' + kv[1]; }).join('，');
      var targetGender = targetIsUser ? _drGetUserGender(p.id) : _drGetPersonaGender(p);
      var imagePrompt = (p.imagePrompt || '') + ' ' + (p.imageStylePrompt || '');
      var refItems = _drGetCoordImageRefs(p.id, _drState.coordOutfit.outfit || {}, targetIsUser);
      var descPrompt = '你是生图提示词生成器。请只返回一段英文图片提示词，不要加解释，不要用 markdown。' + (targetGender ? '性别：' + targetGender + '，' : '') + '造型：' + outfitStr + '。要求：全身照，对镜自拍姿势，真实感，背景简洁干净，服装细节清楚，所有已选择的衣物和配饰都必须显示出来，小配饰也不能被省略，尤其是耳机、项链、戒指、眼镜、帽子、包、手链、耳环等。' + (refItems.length ? ' 如果某件单品来自上传衣柜图，必须在提示词里明确说明这些图会直接输入给生图模型，最终穿在人物身上的衣物必须与参考图为同一件衣物，不得只保留模糊相似感，不允许模型私自改版或替换。' : '') + (imagePrompt.trim() ? '风格参考：' + imagePrompt : '') + '。只返回英文描述词。';
      var descRaw = await _drApiCall(descPrompt, 220);
      var desc = (typeof monoCleanImageDescriptionText === 'function') ? monoCleanImageDescriptionText(descRaw) : String(descRaw || '').trim();
      var cfg = (typeof monoGetImageApiConfig === 'function') ? monoGetImageApiConfig() : null;
      if (cfg && cfg.url && cfg.key && cfg.model && typeof monoCallImageChatCompletions === 'function') {
        if (preview) preview.innerHTML = '<div class="dr-img-placeholder"><span class="dr-spinner dr-spinner-dark"></span><br>生图中…</div>';
        var finalPrompt = _drBuildImagePromptForGeneration(desc, p, refItems, _drState.coordOutfit.outfit || {}, targetIsUser ? (_getUserProfile().name || '用户') : (p.name || '角色'));
        var guideImages = _drState.useCompositeGuide ? await _drBuildGuideImagesForRefs(refItems, false) : [];
        var src = await _drCallImageApiWithRefs(finalPrompt, cfg, refItems, guideImages);
        if (preview) preview.innerHTML = '<div style="padding:12px;"><img id="drCoordGeneratedImage" src="' + String(src).replace(/"/g,'&quot;') + '" style="width:100%;display:block;border-radius:14px;object-fit:cover;background:#f6f6f6;"><div class="dr-img-download-row"><button class="dr-img-download-btn" onclick="drDownloadImageById(\'drCoordGeneratedImage\',\'dressing-room-coordinate.png\')"><i class="fas fa-download"></i>下载图片</button></div><div style="margin-top:10px;font-size:11px;color:#888;line-height:1.6;word-break:break-word;">已调用生图 API。' + (refItems.length ? '<br>已启用上传单品硬锁参考模式。' : '') + '<br>' + _escapeHtml(desc.slice(0, 220)) + '</div></div>';
        _drUpdateRecord('coord', _drState.coordRecordId, { imageDesc: desc, imageSrc: src }, _drState.coordMode === 'user');
      } else {
        if (preview) preview.innerHTML = '<div style="padding:14px;font-size:12px;color:#666;line-height:1.7;"><b style="color:#333;">未检测到可用生图 API，以下为造型描述词：</b><br><br>' + _escapeHtml(desc) + '</div>';
        _drUpdateRecord('coord', _drState.coordRecordId, { imageDesc: desc }, _drState.coordMode === 'user');
      }
    } catch(err) {
      if (preview) preview.innerHTML = '<div class="dr-img-placeholder"><i class="fas fa-exclamation-circle"></i>' + (err.message || '失败') + '</div>';
    }
  };

  // ── ── ── COUPLE PAIRING ── ── ──

  window.drGenerateCouplePairing = async function() {
    var p = _getCurrentPersona();
    if (!p) { _drToast('请先选择角色'); return; }
    var resultCard = document.getElementById('drCoupleResultCard');
    if (resultCard) resultCard.style.display = 'block';
    try {
      var pCtx = _buildPersonaContext(p);
      var up = _getUserProfile();
      var userName = up.name || '用户';
      var userGender = _drGetUserGender(p.id);
      var charGender = _drGetPersonaGender(p);
      var customStyleEl = document.getElementById('drCoupleCustomStyleInput');
      var customStyle = customStyleEl && customStyleEl.value.trim() ? customStyleEl.value.trim() : '';
      if (customStyle) _drState.coupleStyle = customStyle;
      var styleHint = _drState.coupleMode === 'manual' ? '用户风格偏好：' + (_drState.coupleStyle || customStyle || '自由自定义风格') + '，' : '';
      var prompt = pCtx + '\n\n用户信息：用户名=' + userName + '，性别=' + userGender + '\n\n请为这对组合生成一套情侣配对穿搭。\n' + styleHint + _drBuildRecentAvoidHint(p.id, _drState.mode === 'user', true) + '\n配对要求：\n1. 用户穿搭必须符合用户性别（' + userGender + '）。\n2. 角色穿搭必须符合角色性别（' + charGender + '）。\n3. 两套穿搭有呼应关系但不完全相同。\n4. 要有高级感。\n5. 生成一句评价，描述两人站在一起的感觉。' + _drStrictJsonRules('{"userOutfit":"用户穿搭简洁描述","charOutfit":"角色穿搭简洁描述","eval":"60字内的配对评价"}', '必须只有 userOutfit、charOutfit、eval 三个字段；三个值都必须是字符串；不要把穿搭拆成额外对象。');
      var userOutfitEl = document.getElementById('drCoupleUserOutfit');
      var charOutfitEl = document.getElementById('drCoupleCharOutfit');
      var evalEl = document.getElementById('drCoupleEval');
      var userLabelEl = document.getElementById('drCoupleUserLabel');
      var charLabelEl = document.getElementById('drCoupleCharLabel');
      if (userOutfitEl) userOutfitEl.innerHTML = _shimmer(3);
      if (charOutfitEl) charOutfitEl.innerHTML = _shimmer(3);
      if (evalEl) evalEl.innerHTML = _shimmer(2);
      if (userLabelEl) userLabelEl.textContent = userName + ' 的穿搭';
      if (charLabelEl) charLabelEl.textContent = p.name + ' 的穿搭';
      var raw = await _drApiCall(prompt, 500);
      var result = _drCoerceCouple(raw, _safeParseJSON(raw));
      await _drFinalizeCoupleResult(p, result, { manual:false, style:_drState.coupleStyle || customStyle || '' });
    } catch(err) {
      _drToast('已收到返回内容，未再触发解析失败');
      if (resultCard) resultCard.style.display = 'none';
    }
  };

  window.drGenerateCoupleImage = async function() {
    var p = _getCurrentPersona();
    if (!p || p.allowImageGen !== true) { _drToast('角色未开启生图功能'); return; }
    if (!_drState.coupleOutfit) { _drToast('请先生成情侣穿搭'); return; }
    var preview = document.getElementById('drCoupleImagePreview');
    var card = document.getElementById('drCoupleImageCard');
    if (card) card.style.display = 'block';
    if (preview) preview.innerHTML = '<div class="dr-img-placeholder"><span class="dr-spinner dr-spinner-dark"></span><br>正在准备情侣穿搭图…</div>';
    try {
      var up = _getUserProfile();
      var userName = up.name || '用户';
      var userGender = _drGetUserGender(p.id);
      var charGender = _drGetPersonaGender(p);
      var personaHint = [p.imagePrompt || '', p.imageStylePrompt || ''].filter(Boolean).join('，');
      var refItems = _drGetCoupleImageRefs(p.id, _drState.coupleOutfit);
      var descPrompt = '你是生图提示词生成器。请只返回一段英文图片提示词，不要加解释，不要加标题，不要用 markdown。画面内容：' + userName + '和' + p.name + '的情侣穿搭合拍。' + userName + '的性别是' + userGender + '，穿着：' + (_drState.coupleOutfit.userOutfit || '未提供') + '。' + p.name + '的性别是' + charGender + '，穿着：' + (_drState.coupleOutfit.charOutfit || '未提供') + '。要求：真实感、必须是两个人同框的全身双人对镜自拍、用户和角色都必须出现、禁止只生成角色一个人、禁止单人照、只有一人拿手机负责拍照、是合拍不是他拍、服装必须严格区分用户穿搭与角色穿搭、用户只穿用户穿搭、角色只穿角色穿搭、所有衣物和配饰都要显示出来，尤其不能漏掉耳机、项链、戒指、眼镜、包等小配饰；像情侣装但不完全一样、角色符合人设。人物不要正脸，不要直接面向镜头，可用侧脸、低头、被手机部分遮挡、微转身等方式，重点是不要正面拍脸。构图要能同时看清两个人的整身穿搭与情侣氛围，室内镜前自拍，干净背景。' + (refItems.length ? ' 如果有上传衣物参考图，必须明确这些图片将直接作为图像参考输入，人物身上对应衣物要与参考图保持同一件衣物级别的完全一致，包括版型、颜色、材质、配件、鞋型、洗水和图案，并且用户穿搭与角色穿搭都不得被模型擅自换成别的衣物。' : '') + (personaHint ? '角色补充设定：' + personaHint + '。' : '') + '控制在 150 英文词以内。';
      var descRaw = await _drApiCall(descPrompt, 360);
      var desc = (typeof monoCleanImageDescriptionText === 'function') ? monoCleanImageDescriptionText(descRaw) : String(descRaw || '').trim();
      if (!desc) desc = 'A realistic full-body two-person mirror selfie of a couple, only one person holding the phone, showing coordinated matching outfits. The user wears: ' + (_drState.coupleOutfit.userOutfit || '') + '. The character wears: ' + (_drState.coupleOutfit.charOutfit || '') + '. No direct frontal faces, clean indoor mirror background.';
      var cfg = (typeof monoGetImageApiConfig === 'function') ? monoGetImageApiConfig() : null;
      if (cfg && cfg.url && cfg.key && cfg.model && typeof monoCallImageChatCompletions === 'function') {
        if (preview) preview.innerHTML = '<div class="dr-img-placeholder"><span class="dr-spinner dr-spinner-dark"></span><br>生图中…</div>';
        var finalPrompt = _drBuildCoupleImagePromptForGeneration(desc, p, refItems, _drState.coupleOutfit);
        var guideImages = _drState.useCompositeGuide ? await _drBuildGuideImagesForRefs(refItems, true) : [];
        var src = await _drCallImageApiWithRefs(finalPrompt, cfg, refItems, guideImages);
        if (preview) preview.innerHTML = '<div style="padding:12px;"><img id="drCoupleGeneratedImage" src="' + String(src).replace(/"/g,'&quot;') + '" style="width:100%;display:block;border-radius:14px;object-fit:cover;background:#f6f6f6;"><div class="dr-img-download-row"><button class=\"dr-img-download-btn\" onclick=\"drDownloadImageById(\'drCoupleGeneratedImage\',\'dressing-room-couple.png\')\"><i class=\"fas fa-download\"></i>下载图片</button></div><div style="margin-top:10px;font-size:11px;color:#888;line-height:1.6;word-break:break-word;">已调用生图 API。' + (refItems.length ? '<br>已把上传衣物图片作为硬锁图像参考输入。' : '<br>已启用双人情侣合照锁定。') + (guideImages.length ? '<br>已启用情侣半合成 guide 模式。' : '') + '<br>' + _escapeHtml(desc.slice(0, 260)) + '</div></div>';
        _drUpdateRecord('couple', _drState.coupleRecordId, { imageSrc: src, imageDesc: desc }, _drState.mode === 'user');
      } else {
        if (preview) preview.innerHTML = '<div style="padding:14px;font-size:12px;color:#666;line-height:1.7;"><b style="color:#333;">未检测到可用生图 API，以下为情侣穿搭图描述词：</b><br><br>' + _escapeHtml(desc) + '</div>';
        _drUpdateRecord('couple', _drState.coupleRecordId, { imageDesc: desc }, _drState.mode === 'user');
      }
    } catch(err) {
      if (preview) preview.innerHTML = '<div class="dr-img-placeholder"><i class="fas fa-exclamation-circle"></i>' + (err.message || '失败') + '</div>';
    }
  };

  // ── ── ── MEMORIES ── ── ──
  function drRenderMemories() {
    var el = document.getElementById('drMemoriesList');
    if (!el) return;
    var pId = _drState.selectedPersonaId;
    var mems = _getMemories(pId, _drState.mode === 'user');
    if (!mems.length) {
      el.innerHTML = '<div class="dr-empty"><i class="fas fa-box-open"></i>还没有创作记录，<br>先去搭配一套吧！</div>';
      return;
    }
    el.innerHTML = mems.map(function(m, i) {
      var outfitStr = m.outfit ? Object.entries(m.outfit).filter(function(kv){ return kv[1] && kv[1] !== '无'; }).map(function(kv){ return kv[0] + '：' + kv[1]; }).join('，') : (m.outfitStr || '');
      var typeLabel = m.type === 'today' ? '今日穿搭' : m.type === 'coord' ? '搭配造型' : '记录';
      return '<div class="dr-memory-item"><div class="dr-memory-outfit">' + (outfitStr || '（无描述）') + '</div>' +
        (m.reason ? '<div class="dr-memory-context">' + m.reason + '</div>' : '') +
        '<div class="dr-memory-date">' + typeLabel + ' · ' + (m.date || '') + '</div></div>';
    }).join('');
  }

  // ── ── ── HOME ICON ── ── ──

  var DRESSING_ROOM_DEFAULT_SVG = "<svg viewBox='0 0 52 52' xmlns='http://www.w3.org/2000/svg' style='width:38px;height:38px;'><rect x='8' y='8' width='36' height='36' rx='11' fill='none' stroke='#444' stroke-width='2.2'/><path d='M26 13 C24 13 22 14.2 21 15.8 L16 15.8 L13.5 21 L17.5 22.5 L17.5 39 L34.5 39 L34.5 22.5 L38.5 21 L36 15.8 L31 15.8 C30 14.2 28 13 26 13 Z' fill='none' stroke='#444' stroke-width='2' stroke-linejoin='round' stroke-linecap='round'/><path d='M21 15.8 C21 18.2 23.2 20.2 26 20.2 C28.8 20.2 31 18.2 31 15.8' fill='none' stroke='#444' stroke-width='1.8' stroke-linecap='round'/></svg>";
  function refreshDressingRoomDefaultIcon() {
    var box = document.getElementById('dressingRoomHomeIconBox');
    if (!box) return;
    var customIcon = '';
    try { customIcon = localStorage.getItem('mono_icon_dressing-room') || ''; } catch(e) {}
    if (customIcon) box.innerHTML = '<img class="custom-icon" src="' + String(customIcon).replace(/"/g,'&quot;') + '" style="border-radius:16px;">';
    else box.innerHTML = DRESSING_ROOM_DEFAULT_SVG;
  }
  function injectDressingRoomHomeIcon() {
    var existed = document.getElementById('app-dressing-room');
    var el = existed;
    if (el) {
      el.classList.add('ig-music-icon-wrap', 'dressing-room-home-entry');
      el.setAttribute('data-drag-id', 'app-dressing-room');
      el.dataset.dragId = 'app-dressing-room';
      el.setAttribute('onclick', 'openDressingRoomApp()');
    }
    if (el) {
      var page3Existing = document.getElementById('homePage3');
      if (page3Existing && !page3Existing.contains(el)) page3Existing.appendChild(el);
      if (!document.getElementById('dressingRoomHomeIconBox')) {
        var iconBoxFix = document.createElement('div');
        iconBoxFix.className = 'ig-music-icon-box';
        iconBoxFix.id = 'dressingRoomHomeIconBox';
        el.insertBefore(iconBoxFix, el.firstChild);
      }
      if (!el.querySelector('.ig-music-icon-label')) {
        var labelFix = document.createElement('div');
        labelFix.className = 'ig-music-icon-label';
        labelFix.textContent = '换装室';
        el.appendChild(labelFix);
      }
      refreshDressingRoomDefaultIcon && refreshDressingRoomDefaultIcon();
      placeDressingRoomIcon();
      return;
    }
    // Create icon element
    el = document.createElement('div');
    el.id = 'app-dressing-room';
    el.className = 'ig-music-icon-wrap';
    el.dataset.dragId = 'app-dressing-room';
    el.setAttribute('onclick', 'openDressingRoomApp()');

    // Icon SVG — minimal T-shirt line style
    var DRESSING_ROOM_SVG = "<svg viewBox='0 0 52 52' xmlns='http://www.w3.org/2000/svg' style='width:38px;height:38px;'><rect x='8' y='8' width='36' height='36' rx='11' fill='none' stroke='#444' stroke-width='2.2'/><path d='M26 13 C24 13 22 14.2 21 15.8 L16 15.8 L13.5 21 L17.5 22.5 L17.5 39 L34.5 39 L34.5 22.5 L38.5 21 L36 15.8 L31 15.8 C30 14.2 28 13 26 13 Z' fill='none' stroke='#444' stroke-width='2' stroke-linejoin='round' stroke-linecap='round'/><path d='M21 15.8 C21 18.2 23.2 20.2 26 20.2 C28.8 20.2 31 18.2 31 15.8' fill='none' stroke='#444' stroke-width='1.8' stroke-linecap='round'/></svg>";

    var iconBox = document.createElement('div');
    iconBox.className = 'ig-music-icon-box';
    iconBox.id = 'dressingRoomHomeIconBox';
    // Check for custom icon
    var customIcon = '';
    try { customIcon = localStorage.getItem('mono_icon_dressing-room') || ''; } catch(e) {}
    if (customIcon) {
      iconBox.innerHTML = '<img class="custom-icon" src="' + customIcon.replace(/"/g,'&quot;') + '" style="border-radius:16px;">';
    } else {
      iconBox.innerHTML = DRESSING_ROOM_SVG;
    }

    var label = document.createElement('div');
    label.className = 'ig-music-icon-label';
    label.textContent = '换装室';

    el.appendChild(iconBox);
    el.appendChild(label);

    // Insert into page3
    var page3 = document.getElementById('homePage3');
    if (page3) page3.appendChild(el);

    // Place icon below decrypt (decrypt default: x=180, y=16; dressing room: x=180, y=100)
    placeDressingRoomIcon();
  }

  function placeDressingRoomIcon() {
    var el = document.getElementById('app-dressing-room');
    if (!el) return;
    el.dataset.dragId = 'app-dressing-room';
    var defaultPos = { x: 180, y: 128, parentId: 'homePage3' };
    try {
      var pos = JSON.parse(localStorage.getItem('mono_iph_positions_v3') || '{}');
      if (!pos['app-dressing-room']) {
        pos['app-dressing-room'] = defaultPos;
        localStorage.setItem('mono_iph_positions_v3', JSON.stringify(pos));
      }
      var saved = pos['app-dressing-room'];
      var parent = document.getElementById(saved.parentId || 'homePage3');
      if (parent && el.parentElement !== parent) parent.appendChild(el);
      el.classList.add('iph-placed');
      el.style.left = (Number.isFinite(Number(saved.x)) ? Number(saved.x) : defaultPos.x) + 'px';
      el.style.top  = (Number.isFinite(Number(saved.y)) ? Number(saved.y) : defaultPos.y) + 'px';
      el.style.margin = '0';
      el.style.flexShrink = '0';
    } catch(e) {}
  }

  function ensureDressingRoomInConfig() {
    try {
      var cfg = null;
      try { if (Array.isArray(APP_ICONS_CONFIG)) cfg = APP_ICONS_CONFIG; } catch(e) {}
      if (!cfg && Array.isArray(window.APP_ICONS_CONFIG)) cfg = window.APP_ICONS_CONFIG;
      if (cfg && !cfg.some(function(x){ return x && x.key === 'dressing-room'; })) {
        cfg.push({ key: 'dressing-room', label: '换装室', icon: 'fa-tshirt', type: 'page3', defaultSvg: DRESSING_ROOM_DEFAULT_SVG });
        if (typeof window.renderIconCustomizeGrid === 'function') window.renderIconCustomizeGrid();
        else if (typeof renderIconCustomizeGrid === 'function') renderIconCustomizeGrid();
      }
    } catch(e) {}
  }

  function patchApplyCustomIcon() {
    try {
      var orig = window.applyCustomIcon;
      if (typeof orig === 'function' && !orig.__drPatched) {
        window.applyCustomIcon = function(appKey, imgData) {
          if (appKey === 'dressing-room') {
            try { localStorage.setItem('mono_icon_dressing-room', String(imgData || '')); } catch(e) {}
            var box = document.getElementById('dressingRoomHomeIconBox');
            if (box) box.innerHTML = '<img class="custom-icon" src="' + String(imgData).replace(/"/g,'&quot;') + '" style="border-radius:16px;">';
            return;
          }
          return orig.apply(this, arguments);
        };
        window.applyCustomIcon.__drPatched = true;
      }
    } catch(e) {}
  }

