    if(parent && el.parentElement!==parent) parent.appendChild(el);
    el.style.left=(isFinite(Number(cur.x))?Number(cur.x):DEFAULT_POS.x)+'px';
    el.style.top=(isFinite(Number(cur.y))?Number(cur.y):DEFAULT_POS.y)+'px';
