// ===== mono-final-special-app-drag-stability-script =====

(function(){
  if(window.__monoFinalSpecialAppDragStability20260621_v2) return;
  window.__monoFinalSpecialAppDragStability20260621_v2 = true;
  var IDS = ['app-escape-theater','app-ticket-machine','app-ai-music-studio'];
  var FOLDER_KEY = 'mono_iph_folders_v1';
  function parse(raw, fb){ try { return JSON.parse(raw || ''); } catch(e) { return fb; } }
  function readFolders(){ return parse(localStorage.getItem(FOLDER_KEY), {}) || {}; }
  function isDragging(){ return !!(window._iphDragging || document.querySelector('.is-dragging-source')); }
  function appInFolder(id){
    var fd = readFolders();
    return Object.keys(fd).some(function(fid){ var list = fd[fid] && fd[fid].apps; return Array.isArray(list) && list.indexOf(id) >= 0; });
  }
  function normalizeOne(id){
    var el = document.getElementById(id);
    if(!el) return;
    el.dataset.dragId = id;
    el.setAttribute('data-drag-id', id);
    el.classList.add('iph-placed');
    if(appInFolder(id)){
      el.setAttribute('data-in-iph-folder','1');
      el.style.display = 'none';
      el.style.opacity = '0';
      el.style.visibility = 'hidden';
      el.style.pointerEvents = 'none';
      return;
    }
    el.removeAttribute('data-in-iph-folder');
    if(el.classList.contains('is-dragging-source')){
      el.style.display = 'flex';
      el.style.opacity = '0';
      el.style.visibility = 'hidden';
      el.style.pointerEvents = 'none';
      return;
    }
    if(!isDragging()){
      el.style.display = 'flex';
      el.style.opacity = '1';
      el.style.visibility = 'visible';
      el.style.pointerEvents = 'auto';
    }
  }
  function normalizeAll(){ IDS.forEach(normalizeOne); }
  function cleanupStuckDrag(){
    if(window._iphDragging) return;
    document.querySelectorAll('.is-dragging-source').forEach(function(el){
      el.classList.remove('is-dragging-source');
      el.style.opacity = '';
      el.style.visibility = '';
      el.style.pointerEvents = '';
    });
    var hs = document.getElementById('homeScreen');
    if(hs) hs.classList.remove('iph-dragging');
    normalizeAll();
  }
  function afterDrop(){ setTimeout(function(){ cleanupStuckDrag(); normalizeAll(); }, 80); }
  document.addEventListener('DOMContentLoaded', normalizeAll);
  window.addEventListener('load', normalizeAll, {passive:true});
  document.addEventListener('touchstart', function(){ if(!isDragging()) normalizeAll(); }, true);
  document.addEventListener('touchend', afterDrop, true);
  document.addEventListener('touchcancel', afterDrop, true);
  document.addEventListener('mouseup', afterDrop, true);
  window.addEventListener('blur', function(){ window._iphDragging = false; cleanupStuckDrag(); }, {passive:true});
  document.addEventListener('visibilitychange', function(){ if(document.visibilityState !== 'visible'){ window._iphDragging = false; cleanupStuckDrag(); } });
  setTimeout(normalizeAll, 0);
  setTimeout(normalizeAll, 600);
  setInterval(function(){ if(!isDragging()) normalizeAll(); }, 8000);
})();


