// ===== mono-stable-home-layout-reset-fix-20260629 =====

(function(){
  'use strict';
  if (window.__monoStableHomeLayoutResetFix20260629) return;
  window.__monoStableHomeLayoutResetFix20260629 = true;

  var POS_KEY = 'mono_iph_positions_v3';
  var FOLDER_KEY = 'mono_iph_folders_v1';
  var RESET_MARK_KEY = 'mono_home_layout_reset_requested_v20260629';

  /* 这里是“重置主屏幕布局”的唯一预设来源。
     不再依赖多个旧脚本各自补默认坐标，避免越点越乱。 */
  var DEFAULT_POSITIONS = {
    coupleSpaceWidget:      { x: 16,  y: 16,  w: 152, h: 152, parentId: 'homePage3' },
    'app-decrypt':          { x: 180, y: 16,  parentId: 'homePage3' },
    'app-entertainment':    { x: 264, y: 16,  parentId: 'homePage3' },

    'app-dressing-room':    { x: 180, y: 116, parentId: 'homePage3' },
    'app-ticket-machine':   { x: 264, y: 116, parentId: 'homePage3' },

    'app-youtube':          { x: 16,  y: 216, parentId: 'homePage3' },
    'app-instagram':        { x: 96,  y: 216, parentId: 'homePage3' },
    'app-ai-music-studio':  { x: 180, y: 216, parentId: 'homePage3' },
    'app-escape-theater':   { x: 264, y: 216, parentId: 'homePage3' }
  };

  function cloneDefaultPositions(){
    try { return JSON.parse(JSON.stringify(DEFAULT_POSITIONS)); }
    catch(e) { return Object.assign({}, DEFAULT_POSITIONS); }
  }

  function safeReadJSON(key, fallback){
    try {
      var raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch(e) {
      return fallback;
    }
  }

  function safeRemove(key){
    try { localStorage.removeItem(key); } catch(e) {}
  }

  function safeSet(key, value){
    try { localStorage.setItem(key, value); } catch(e) {}
  }

  function clearFolderDomAndRestoreApps(){
    try {
      var fd = safeReadJSON(FOLDER_KEY, {}) || {};
      Object.keys(fd).forEach(function(folderId){
        var data = fd[folderId] || {};
        (data.apps || []).forEach(function(appId){
          var appEl = document.getElementById(appId) || document.querySelector('[data-drag-id="' + appId + '"]');
          if (appEl) {
            appEl.style.display = '';
            appEl.style.visibility = '';
            appEl.style.opacity = '';
            appEl.removeAttribute('data-in-iph-folder');
          }
        });
      });
    } catch(e) {}
    try { document.querySelectorAll('.iph-folder-icon,.home-dock-placeholder').forEach(function(el){ el.remove(); }); } catch(e) {}
  }

  function clearLayoutStores(){
    [
      FOLDER_KEY,
      'mono_custom_widgets_v1',
      'mono_widget_photos_v1',
      'mono_widget_multi_photos_v1',
      'mono_custom_image_widget_v1',
      'mono_hidden_regular_widgets_v1',
      'mono_spotify_widget_text_v1',
      'mono_extra_pages_v1'
    ].forEach(safeRemove);
  }

  function markMigrationsDone(){
    /* 这些旧迁移脚本如果重新跑，会删除/覆盖我们刚写好的坐标。 */
    safeSet('mono_couple_widget_page3_migrated_v1', '1');
    safeSet('mono_decrypt_drag_exact_music_logic_migrated_v2', '1');
    safeRemove('mono_channel_icon_page3_migrated_v1');
  }

  function writeDefaultLayoutStore(){
    safeSet(POS_KEY, JSON.stringify(cloneDefaultPositions()));
    markMigrationsDone();
  }

  function ensureSpecialIconsExist(){
    try { if (typeof window.renderTicketMachineHomeIcon === 'function') window.renderTicketMachineHomeIcon(); } catch(e) {}
    try { if (typeof window.renderAiMusicStudioHomeIcon === 'function') window.renderAiMusicStudioHomeIcon(); } catch(e) {}
    try { if (typeof window.monoEnsureEscapeTheaterHomeIcon === 'function') window.monoEnsureEscapeTheaterHomeIcon(); } catch(e) {}
    try { if (typeof window.renderDecryptHomeIcon === 'function') window.renderDecryptHomeIcon(); } catch(e) {}
    try { if (typeof window.renderEntertainmentHomeIcon === 'function') window.renderEntertainmentHomeIcon(); } catch(e) {}
  }

  function showRegularWidgets(){
    ['homeCalendarWidget','igWidget','familyWidget','coupleSpaceWidget'].forEach(function(id){
      var el = document.getElementById(id);
      if (!el) return;
      el.hidden = false;
      el.style.display = '';
      el.style.visibility = '';
      el.style.opacity = '';
    });
  }

  function applyDefaultLayoutLive(){
    var pos = cloneDefaultPositions();
    Object.keys(pos).forEach(function(id){
      var el = document.getElementById(id);
      var p = pos[id];
      if (!el || !p) return;

      var parent = document.getElementById(p.parentId || 'homePage3');
      if (parent && el.parentElement !== parent) parent.appendChild(el);

      try {
        el.dataset.dragId = id;
        el.setAttribute('data-drag-id', id);
      } catch(e) {}

      el.classList.add('iph-placed');
      el.classList.remove('is-dragging-source');
      el.removeAttribute('data-in-iph-folder');

      el.style.position = 'absolute';
      el.style.left = Number(p.x || 0) + 'px';
      el.style.top = Number(p.y || 0) + 'px';
      el.style.margin = '0';
      el.style.flexShrink = '0';
      el.style.opacity = '';
      el.style.visibility = '';
      el.style.zIndex = '';

      if (p.w) el.style.width = Number(p.w) + 'px';
      else el.style.width = '';
      if (p.h) el.style.height = Number(p.h) + 'px';
      else el.style.height = '';
      if (el.style.display === 'none') el.style.display = '';
    });
  }

  function runStableResetLayout(){
    clearFolderDomAndRestoreApps();
    clearLayoutStores();
    writeDefaultLayoutStore();
    safeSet(RESET_MARK_KEY, String(Date.now()));

    try {
      var hs = document.getElementById('homeScreen');
      if (hs) hs.classList.remove('home-edit-active','iph-dragging','editing-home');
      document.body && document.body.classList.remove('home-edit-active','editing-home');
      var done = document.getElementById('iph-edit-done');
      if (done) done.style.display = 'none';
      var ghost = document.getElementById('iph-drag-ghost');
      if (ghost) ghost.style.display = 'none';
    } catch(e) {}

    showRegularWidgets();
    ensureSpecialIconsExist();
    applyDefaultLayoutLive();

    if (typeof window.toast === 'function') {
      try { window.toast('已重置主屏幕布局'); } catch(e) {}
    }

    setTimeout(function(){
      try {
        if (window.monoSafeReload) window.monoSafeReload('stable-home-layout-reset');
        else location.reload();
      } catch(e) {
        location.reload();
      }
    }, 80);
  }

  var oldReset = window.iphResetLayout;
  window.iphResetLayout = function(){
    var ok = true;
    try { ok = confirm('确定要重置主屏幕布局吗？所有图标和桌件将恢复原始预设位置，文件夹也将被清除。'); } catch(e) {}
    if (!ok) return false;
    runStableResetLayout();
    return false;
  };
  window.iphResetLayout.__monoStableResetWrapped = true;
  window.iphResetLayout.__monoOldResetLayout = oldReset;

  function finishPendingResetIfNeeded(){
    var mark = '';
    try { mark = localStorage.getItem(RESET_MARK_KEY) || ''; } catch(e) {}
    if (!mark) return;

    clearFolderDomAndRestoreApps();
    clearLayoutStores();
    writeDefaultLayoutStore();
    showRegularWidgets();
    ensureSpecialIconsExist();
    applyDefaultLayoutLive();

    /* 多个旧补丁会在 0~3000ms 内再次整理第三页，继续补几轮，保证最终坐标一致。 */
    [60, 180, 420, 900, 1600, 2800, 4200].forEach(function(ms){
      setTimeout(function(){
        writeDefaultLayoutStore();
        showRegularWidgets();
        ensureSpecialIconsExist();
        applyDefaultLayoutLive();
      }, ms);
    });

    setTimeout(function(){ safeRemove(RESET_MARK_KEY); }, 4600);
  }

  document.addEventListener('DOMContentLoaded', finishPendingResetIfNeeded);
  window.addEventListener('load', finishPendingResetIfNeeded, { passive: true });
  setTimeout(finishPendingResetIfNeeded, 0);
})();


