// ===== mono-escape-theater-final-grid-align-20260629 =====

(function(){
  'use strict';
  if (window.__monoEscapeTheaterFinalGridAlign20260629) return;
  window.__monoEscapeTheaterFinalGridAlign20260629 = true;

  var POS_KEY = 'mono_iph_positions_v3';
  var ICON_ID = 'app-escape-theater';
  var FINAL_POS = { x:264, y:216, parentId:'homePage3' };

  function read(){ try { return JSON.parse(localStorage.getItem(POS_KEY) || '{}') || {}; } catch(e) { return {}; } }
  function write(p){ try { localStorage.setItem(POS_KEY, JSON.stringify(p || {})); } catch(e) {} }
  function close(a,b,range){ a=Number(a); b=Number(b); return Number.isFinite(a) && Number.isFinite(b) && Math.abs(a-b) <= (range || 8); }

  function isDefaultLike(cur){
    if (!cur || typeof cur !== 'object') return true;
    if (String(cur.parentId || FINAL_POS.parentId) !== FINAL_POS.parentId) return false;
    var x = Number(cur.x), y = Number(cur.y);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return true;
    /* 只修复系统预设/旧预设附近的位置：196、216、276 都算旧预设；用户拖到别的位置不会被覆盖。 */
    return close(x, 264, 10) && (close(y, 196, 10) || close(y, 216, 10) || close(y, 276, 14));
  }

  function alignEscapeTheater(){
    if (window._iphDragging || document.querySelector('.is-dragging-source')) return;
    var el = document.getElementById(ICON_ID);
    if (!el) {
      try { if (typeof window.monoEnsureEscapeTheaterHomeIcon === 'function') window.monoEnsureEscapeTheaterHomeIcon(); } catch(e) {}
      el = document.getElementById(ICON_ID);
    }
    if (!el) return;

    var pos = read();
    var cur = pos[ICON_ID];
    if (!isDefaultLike(cur)) return;

    pos[ICON_ID] = { x:FINAL_POS.x, y:FINAL_POS.y, parentId:FINAL_POS.parentId };
    write(pos);

    var parent = document.getElementById(FINAL_POS.parentId);
    if (parent && el.parentElement !== parent) parent.appendChild(el);
    try { el.dataset.dragId = ICON_ID; el.setAttribute('data-drag-id', ICON_ID); } catch(e) {}
    el.classList.add('ig-music-icon-wrap','escape-theater-home-entry','iph-placed');
    el.removeAttribute('data-in-iph-folder');
    el.style.position = 'absolute';
    el.style.left = FINAL_POS.x + 'px';
    el.style.top = FINAL_POS.y + 'px';
    el.style.margin = '0';
    el.style.flexShrink = '0';
    el.style.transform = 'none';
    el.style.webkitTransform = 'none';
    if (el.style.display === 'none') el.style.display = 'flex';
  }

  document.addEventListener('DOMContentLoaded', alignEscapeTheater);
  window.addEventListener('load', alignEscapeTheater, { passive:true });
  [0,80,180,420,900,1600,2800,4200,6200,8200].forEach(function(ms){ setTimeout(alignEscapeTheater, ms); });
})();


