// ===== mono-nonfullscreen-app-frame-fix-script =====

(function(){
  if (window.__monoNonFullscreenAppFrameFixed) return;
  window.__monoNonFullscreenAppFrameFixed = true;

  var APP_IDS = [
    'blackboxPage','taskPage','babyAppPage','petAppPage','shopAppPage','healthAppPage','datingAppPage','musicPage',
    'dreamPage','decryptPage','coupleSpacePage','instagramPage','ticketMachinePage','dressingRoomPage','youtubePage',
    'aiMusicStudioPage','escapeTheaterPage','entertainmentPage','shopPage','datingChatPage'
  ];

  function phone(){ return document.querySelector('.phone-container'); }
  function isAppPage(el){ return !!(el && APP_IDS.indexOf(el.id) >= 0); }

  function moveIntoFrame(el){
    var pc = phone();
    if (!pc || !el) return;
    try { el.setAttribute('data-mono-framed-app','1'); } catch(e){}
    /* 动态创建的旋律工坊/密室逃脱等旧版会 append 到 body；框架模式必须移回 phone-container。 */
    try {
      if (el.parentNode !== pc) pc.appendChild(el);
    } catch(e) {}
  }

  function applyOne(el){
    if (!isAppPage(el)) return;
    moveIntoFrame(el);
    if (!document.body.classList.contains('ios-fullscreen')) {
      try {
        el.style.setProperty('position','absolute','important');
        el.style.setProperty('top','44px','important');
        el.style.setProperty('left','0','important');
        el.style.setProperty('right','0','important');
        el.style.setProperty('bottom','0','important');
        el.style.setProperty('width','100%','important');
        el.style.setProperty('height','auto','important');
        el.style.setProperty('max-width','100%','important');
        el.style.setProperty('max-height','calc(100% - 44px)','important');
        el.style.setProperty('margin','0','important');
        el.style.setProperty('transform','none','important');
        el.style.setProperty('overflow','hidden','important');
        el.style.setProperty('box-sizing','border-box','important');
      } catch(e) {}
    }
  }

  function enforce(){
    APP_IDS.forEach(function(id){ applyOne(document.getElementById(id)); });
    try {
      var pc = phone();
      if (pc) pc.querySelectorAll('[id$="Page"]').forEach(function(el){ if (isAppPage(el)) applyOne(el); });
    } catch(e) {}
  }

  document.addEventListener('DOMContentLoaded', function(){
    enforce();
    setTimeout(enforce, 80);
    setTimeout(enforce, 300);
    setTimeout(enforce, 900);
  });
  window.addEventListener('load', function(){ setTimeout(enforce, 100); setTimeout(enforce, 800); }, {passive:true});
  document.addEventListener('click', function(){ setTimeout(enforce, 0); setTimeout(enforce, 180); }, true);
  document.addEventListener('visibilitychange', function(){ if (!document.hidden) setTimeout(enforce, 80); }, {passive:true});

  try {
    var mo = new MutationObserver(function(records){
      var need = false;
      records.forEach(function(r){
        if (r.addedNodes) Array.prototype.forEach.call(r.addedNodes, function(n){
          if (n && n.nodeType === 1 && (isAppPage(n) || (n.querySelector && APP_IDS.some(function(id){ return n.querySelector('#'+id); })))) need = true;
        });
      });
      if (need) setTimeout(enforce, 0);
    });
    mo.observe(document.documentElement, { childList:true, subtree:true });
  } catch(e) {}
})();


