// ===== mono-offline-true-full-clean-no-compression-display-final =====

(function(){
  if (window.__monoOfflineTrueFullCleanNoCompressionDisplayFinal) return;
  window.__monoOfflineTrueFullCleanNoCompressionDisplayFinal = true;

  function cleanCompressionText(value){
    var s = (value == null) ? '' : String(value);
    if (!s) return '';
    s = s
      .replace(/…?\s*【中段已压缩(?:，保留开头与结尾)?】\s*…?/g, '\n')
      .replace(/^\s*【早期线下剧情已自动压缩】[^\n]*(?:\n|$)/gm, '')
      .replace(/^\s*【早期剧情回顾（(?:自动压缩节选，不是全文|已压缩节选)）】\s*$/gm, '')
      .replace(/^\s*【本段剧情总结记忆（已压缩，必须承接）】\s*$/gm, '')
      .replace(/^\s*【以上为早期压缩回顾，以下为近期完整剧情】\s*$/gm, '')
      .replace(/\n{3,}/g, '\n\n')
      .trim();
    return s;
  }

  // 生成前：完全不压缩、不插入早期压缩提示、不裁剪正文。
  window._monoOfflineCompactText = function(text){ return String(text || ''); };
  window._monoOfflineCompactMessages = function(list){
    return (Array.isArray(list) ? list : []).map(function(m){
      return { role: (m && m.role) || 'user', content: cleanCompressionText((m && m.content) || '') };
    }).filter(function(m){ return String(m.content || '').trim(); });
  };

  // 再覆盖一次完整上下文，避免旧函数在后面重新走“早期剧情回顾/节选”。
  window._buildFullSessionContext = _buildFullSessionContext = function(session, p, uName){
    var entries = (session && Array.isArray(session.entries)) ? session.entries : [];
    var textParts = [];
    var messages = [];
    if (!entries.length) return { recentEntries:'', messages:[] };
    textParts.push('【本次线下剧情完整原文（未压缩、未节选、未截断；必须完整承接，不得概述代替正文）】');
    entries.forEach(function(e, idx){
      e = e || {};
      var role = e.role === 'user' ? 'user' : 'assistant';
      var speaker = role === 'user' ? (uName || '你') : ((p && p.name) || '角色');
      var content = cleanCompressionText(e.content || '');
      if (!content) return;
      textParts.push('【第' + (idx + 1) + '条｜' + speaker + '】\n' + content);
      messages.push({ role:role, content:content });
    });
    return { recentEntries:textParts.join('\n\n'), messages:messages };
  };

  // 显示前：清理旧版本已经存进去的压缩提示文字。注意：旧版本已经丢掉的正文无法恢复；这只负责不再显示压缩标记，新生成不会再插入。
  function cleanSessionObj(session){
    var changed = false;
    if (!session || typeof session !== 'object') return false;
    ['entries','sessionMemory','memorySummaries'].forEach(function(key){
      var arr = Array.isArray(session[key]) ? session[key] : [];
      for (var i = arr.length - 1; i >= 0; i--) {
        var item = arr[i];
        if (!item || typeof item !== 'object') continue;
        ['content','text','summary','overview'].forEach(function(field){
          if (typeof item[field] === 'string') {
            var next = cleanCompressionText(item[field]);
            if (next !== item[field]) { item[field] = next; changed = true; }
          }
        });
        if ((key === 'entries') && item.role !== 'user' && !String(item.content || '').trim()) {
          arr.splice(i, 1); changed = true;
        }
      }
    });
    return changed;
  }
  function cleanAllOfflineSessions(){
    var changed = false;
    try {
      if (window._offlineState && window._offlineState.sessions) {
        Object.keys(window._offlineState.sessions).forEach(function(pid){
          var list = window._offlineState.sessions[pid];
          if (Array.isArray(list)) list.forEach(function(session){ if (cleanSessionObj(session)) changed = true; });
        });
      }
    } catch(e) {}
    try {
      var raw = localStorage.getItem('mono_offline_sessions');
      if (raw) {
        var data = JSON.parse(raw);
        var localChanged = false;
        Object.keys(data || {}).forEach(function(pid){
          var list = data[pid];
          if (Array.isArray(list)) list.forEach(function(session){ if (cleanSessionObj(session)) localChanged = true; });
        });
        if (localChanged) { localStorage.setItem('mono_offline_sessions', JSON.stringify(data)); changed = true; }
      }
    } catch(e) {}
    try { if (changed && typeof _saveOfflineSessions === 'function') _saveOfflineSessions(); } catch(e) {}
    return changed;
  }
  window.monoCleanOfflineCompressionMarkers = cleanAllOfflineSessions;

  var oldRender = window._renderOfflineContent;
  if (typeof oldRender === 'function' && !oldRender.__monoNoCompressionDisplayWrapped) {
    var wrapped = function(){ cleanAllOfflineSessions(); return oldRender.apply(this, arguments); };
    wrapped.__monoNoCompressionDisplayWrapped = true;
    window._renderOfflineContent = wrapped;
    try { _renderOfflineContent = window._renderOfflineContent; } catch(e) {}
  }

  document.addEventListener('DOMContentLoaded', function(){ setTimeout(cleanAllOfflineSessions, 80); setTimeout(function(){ try { cleanAllOfflineSessions(); if (typeof _renderOfflineContent === 'function') _renderOfflineContent(); } catch(e){} }, 600); }, {passive:true});
  if (document.readyState !== 'loading') setTimeout(cleanAllOfflineSessions, 80);
})();

